window.ATLAS = {"generado": "2026-10-26", "titulo": "Atlas de Inmunología", "marca": "Inmunología · clases 1 a 58", "descripcion": "las preguntas tipo examen de las 58 clases (de la inmunidad innata a las vacunas), sacadas de tu teoría (Rojas, 17.ª ed.)", "ejemplos": "«complemento», «HLA», «IgE», «Th17»", "credito": "Ilustraciones generadas con ChatGPT (sin texto); las etiquetas siguen tu teoría.", "grupos": [{"id": "g1", "nombre": "Generalidades, barreras y circulación", "icono": "🛡️"}, {"id": "g2", "nombre": "Fagocitos y células innatas", "icono": "🦠"}, {"id": "g3", "nombre": "Complemento e inflamación", "icono": "🔥"}, {"id": "g4", "nombre": "Antígenos, HLA y órganos linfoides", "icono": "🧬"}, {"id": "g5", "nombre": "Linfocitos T y B, inmunoglobulinas", "icono": "🧫"}, {"id": "g6", "nombre": "Mucosas y reproducción", "icono": "🫁"}, {"id": "g7", "nombre": "Citoquinas, tolerancia y muerte celular", "icono": "⚖️"}, {"id": "g8", "nombre": "Genética y evaluación inmunológica", "icono": "🔬"}, {"id": "g9", "nombre": "Bacterias y tuberculosis", "icono": "🦠"}, {"id": "g10", "nombre": "Virus, parásitos y malaria", "icono": "🦟"}, {"id": "g11", "nombre": "Hongos, candidiasis y sepsis", "icono": "🍄"}, {"id": "g12", "nombre": "Cáncer y proliferativas", "icono": "🎗️"}, {"id": "g13", "nombre": "Inmunodeficiencias primarias", "icono": "🧒"}, {"id": "g14", "nombre": "VIH e inmunodeficiencias secundarias", "icono": "🔴"}, {"id": "g15", "nombre": "Mecanismos de alergia y anafilaxia", "icono": "🐝"}, {"id": "g16", "nombre": "Asma, rinitis, urticaria y alergias", "icono": "🤧"}, {"id": "g17", "nombre": "Autoinmunidad y artritis", "icono": "🦴"}, {"id": "g18", "nombre": "Lupus, Sjögren, esclerodermia y SAF", "icono": "🦋"}, {"id": "g19", "nombre": "Autoinmunes: nervios, glándulas, piel y pulmón", "icono": "🧠"}, {"id": "g20", "nombre": "Autoinmunes: digestivo, hígado, corazón y riñón", "icono": "🫀"}, {"id": "g21", "nombre": "Autoinmunes: músculo, sangre, ojo y poliautoinmunidad", "icono": "🩸"}, {"id": "g22", "nombre": "Inmunomodulación, trasplantes y vacunas", "icono": "💉"}], "laminas": [{"n": 1, "slug": "Barreras_naturales", "titulo": "Barreras naturales y reconocimiento innato", "subtitulo": "piel, vía respiratoria e intestino · PAMP y receptores tipo Toll", "grupo": "g1", "lema": "La idea: casi ningún microbio entra por la piel intacta, porque cada puerta del cuerpo tiene <b>una barrera física</b> (queratina, moco y cilios) y <b>una química</b> (pH ácido, sebo, defensinas, ácido gástrico). Si el microbio pasa, los <mark>PRR</mark> reconocen sus <u>PAMP</u>, que no existen en nuestras células, y encienden la alarma innata en minutos. En la imagen verás tres puertas: piel, epitelio respiratorio y cripta intestinal; luego la cadena va de la puerta a la alarma.", "img": "img/01.webp", "mini": "img/mini/01.webp", "ratio": 1.5, "etiquetas": [{"n": "①", "t": "Microbios", "s": "no cruzan<br>la piel intacta", "c": "g", "x": 0.8, "y": 6, "ax": 9, "ay": 23, "al": "l"}, {"n": "⑤", "t": "Langerhans", "s": "captura y lleva<br>al ganglio", "c": "i", "x": 20.5, "y": 6, "ax": 11, "ay": 33}, {"n": "⑤", "t": "Sebo · pH", "s": "ácidos grasos<br>que matan", "c": "d", "x": 35.5, "y": 6, "ax": 27.5, "ay": 25, "d": "A"}, {"n": "⑥", "t": "Moco", "s": "la mucina<br>atrapa", "c": "i", "x": 48, "y": 6, "ax": 45, "ay": 22, "d": "B"}, {"n": "⑥", "t": "Cilios", "s": "barren hacia<br>la faringe", "c": "i", "x": 60.5, "y": 6, "ax": 60, "ay": 38}, {"n": "", "t": "Microbioma", "s": "comensales que<br>ocupan los nichos", "c": "g", "x": 84, "y": 6, "ax": 83, "ay": 22, "d": "D"}, {"n": "④", "t": "Queratinocitos", "s": "defensinas;<br>desmosomas", "c": "i", "x": 0.8, "y": 90, "ax": 6, "ay": 44, "al": "l"}, {"n": "", "t": "Melanocito", "s": "melanina<br>contra la luz UV", "c": "i", "x": 23, "y": 90, "ax": 13, "ay": 54}, {"n": "⑤", "t": "Glándula sebácea", "s": "sin ella:<br>micosis plantar", "c": "d", "x": 38, "y": 90, "ax": 26, "ay": 64}, {"n": "", "t": "Caliciforme", "s": "produce<br>el moco", "c": "i", "x": 54, "y": 90, "ax": 53, "ay": 50}, {"n": "", "t": "Neutrófilo", "s": "lo llama<br>la IL-8", "c": "g", "x": 69, "y": 90, "ax": 75, "ay": 57}, {"n": "⑤", "t": "Paneth", "s": "criptidinas<br>(defensinas)", "c": "d", "x": 87, "y": 90, "ax": 83, "ay": 67}], "diapos": [{"img": "img/01.webp", "ratio": 1.5, "titulo": "Tres puertas: piel, vía aérea e intestino", "texto": "Cada puerta tiene <mark>barrera física</mark> y <mark>barrera química</mark>; <span class=\"cx\">por eso</span> muy pocos gérmenes cruzan la piel intacta ①④⑤⑥.", "etiquetas": [{"n": "①", "t": "Microbios", "s": "no cruzan<br>la piel intacta", "c": "g", "x": 0.8, "y": 6, "ax": 9, "ay": 23, "al": "l"}, {"n": "⑤", "t": "Langerhans", "s": "captura y lleva<br>al ganglio", "c": "i", "x": 20.5, "y": 6, "ax": 11, "ay": 33}, {"n": "⑤", "t": "Sebo · pH", "s": "ácidos grasos<br>que matan", "c": "d", "x": 35.5, "y": 6, "ax": 27.5, "ay": 25, "d": "A"}, {"n": "⑥", "t": "Moco", "s": "la mucina<br>atrapa", "c": "i", "x": 48, "y": 6, "ax": 45, "ay": 22, "d": "B"}, {"n": "⑥", "t": "Cilios", "s": "barren hacia<br>la faringe", "c": "i", "x": 60.5, "y": 6, "ax": 60, "ay": 38}, {"n": "", "t": "Microbioma", "s": "comensales que<br>ocupan los nichos", "c": "g", "x": 84, "y": 6, "ax": 83, "ay": 22, "d": "D"}, {"n": "④", "t": "Queratinocitos", "s": "defensinas;<br>desmosomas", "c": "i", "x": 0.8, "y": 90, "ax": 6, "ay": 44, "al": "l"}, {"n": "", "t": "Melanocito", "s": "melanina<br>contra la luz UV", "c": "i", "x": 23, "y": 90, "ax": 13, "ay": 54}, {"n": "⑤", "t": "Glándula sebácea", "s": "sin ella:<br>micosis plantar", "c": "d", "x": 38, "y": 90, "ax": 26, "ay": 64}, {"n": "", "t": "Caliciforme", "s": "produce<br>el moco", "c": "i", "x": 54, "y": 90, "ax": 53, "ay": 50}, {"n": "", "t": "Neutrófilo", "s": "lo llama<br>la IL-8", "c": "g", "x": 69, "y": 90, "ax": 75, "ay": 57}, {"n": "⑤", "t": "Paneth", "s": "criptidinas<br>(defensinas)", "c": "d", "x": 87, "y": 90, "ax": 83, "ay": 67}]}, {"img": "img/01_2.webp", "ratio": 1.5, "titulo": "PRR reconoce PAMP: del LPS al núcleo", "texto": "El LPS, un <mark>PAMP</mark>, llega por <b>LBP</b> y <b>CD14</b> al TLR4 ③; <span class=\"cx\">luego</span> MyD88 lleva NF-kB al núcleo ⑨, <span class=\"cx\">así que</span> salen citoquinas y la PCR sube ⑩⑪.", "etiquetas": [{"n": "③", "t": "LPS = PAMP", "s": "molécula que solo<br>tiene el microbio", "c": "d", "x": 0.5, "y": 8, "ax": 16.3, "ay": 26.5, "al": "l"}, {"n": "③", "t": "LBP", "s": "transporta<br>el LPS", "c": "g", "x": 26, "y": 8, "ax": 35.8, "ay": 27}, {"n": "③", "t": "CD14", "s": "anclado por GPI,<br>lo entrega", "c": "g", "x": 43, "y": 8, "ax": 43, "ay": 35}, {"n": "⑩", "t": "TLR4 (PRR)", "s": "poco: infecciones<br>exceso: sepsis", "c": "i", "x": 62, "y": 8, "ax": 52, "ay": 32}, {"n": "⑪", "t": "Citoquinas", "s": "IL-6 al hígado:<br>sube la PCR", "c": "d", "x": 99.5, "y": 8, "ax": 91.5, "ay": 24, "al": "r"}, {"n": "", "t": "Bacteria Gram −", "s": "pared con LPS", "c": "g", "x": 0.5, "y": 91, "ax": 8, "ay": 62, "al": "l"}, {"n": "⑪", "t": "PCR (pentraxina)", "s": "anillo de 5: se liga al<br>polisacárido bacteriano", "c": "d", "x": 27, "y": 91, "ax": 19, "ay": 50}, {"n": "⑨", "t": "MyD88", "s": "adaptador de todos<br>los TLR menos el TLR3", "c": "i", "x": 50, "y": 91, "ax": 53.4, "ay": 59.6}, {"n": "⑨", "t": "NF-kB en el núcleo", "s": "enciende los genes<br>de citoquinas", "c": "i", "x": 76, "y": 91, "ax": 83, "ay": 69}]}, {"img": "img/01_3.webp", "ratio": 1.5, "titulo": "Ácido, lisozima, lactoferrina y Duffy", "texto": "Sin ácido gástrico bastan pocos vibriones ⑦ <span class=\"lt2\">C</span>; la lisozima <mark>rompe</mark> y la lactoferrina <mark>quita el hierro</mark> ⑫; sin antígeno Duffy no entra <b>P. vivax</b> ⑧.", "etiquetas": [{"n": "⑦", "t": "Mucosa gástrica", "s": "secreta el<br>ácido (HCl)", "c": "g", "x": 0.5, "y": 8, "ax": 19.5, "ay": 27, "al": "l"}, {"n": "⑫", "t": "Lágrima", "s": "película con<br>lisozima", "c": "i", "x": 33, "y": 8, "ax": 45.6, "ay": 27}, {"n": "⑧", "t": "Antígeno Duffy", "s": "receptor que usa<br>P. vivax", "c": "d", "x": 64, "y": 8, "ax": 74.2, "ay": 29.3}, {"n": "⑧", "t": "Merozoíto", "s": "se ancla al<br>hematíe Duffy+", "c": "d", "x": 99.5, "y": 8, "ax": 87.2, "ay": 31.3, "al": "r"}, {"n": "⑦", "t": "Vibriones disueltos", "s": "el ácido los mata:<br>hace falta >1 millón", "c": "i", "x": 0.5, "y": 91, "ax": 23.4, "ay": 58.6, "d": "C", "al": "l"}, {"n": "⑫", "t": "Lisozima", "s": "rompe la pared:<br>lisis directa", "c": "i", "x": 30, "y": 91, "ax": 38.4, "ay": 50.8}, {"n": "⑫", "t": "Lactoferrina", "s": "secuestra el hierro:<br>no se reproduce", "c": "i", "x": 50, "y": 91, "ax": 51.4, "ay": 53.7}, {"n": "⑧", "t": "Hematíe Duffy −", "s": "sin receptor:<br>no entra", "c": "g", "x": 75, "y": 91, "ax": 80.7, "ay": 62}, {"n": "⑧", "t": "Merozoíto libre", "s": "no puede<br>anclarse", "c": "g", "x": 99.5, "y": 91, "ax": 94.4, "ay": 52.7, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Tres puertas de izquierda a derecha: <b class=\"i\">piel</b>, <b class=\"i\">epitelio respiratorio</b> y <b class=\"i\">cripta del intestino delgado</b>. Colores: <b class=\"i\">azul</b> = barrera física o mecánica; <b class=\"d\">rojo</b> = barrera química (sustancias que matan); <b>gris</b> = microbios.", "La inmunidad innata es <mark>inmediata, inespecífica y sin memoria</mark> ①; <span class=\"cx\">en cambio</span>, la adquirida tarda 7-10 días y deja memoria. Las barreras son su primera línea, y <span class=\"cx\">por eso</span> <span class=\"res\">muy pocos gérmenes penetran la piel intacta</span>: hace falta herida, quemadura, cirugía o picadura de un vector.", "Si el microbio supera la barrera, los PRR de los fagocitos reconocen sus PAMP ③ (lipopolisacárido, peptidoglucano, manano, ADN y ARN microbianos). El TLR activa <b>MyD88</b> ⑨, NF-kB entra al núcleo y se producen citoquinas: <span class=\"cx\">así que</span> la PCR puede <span class=\"res\">subir hasta mil veces</span> ⑪."], "recordar": "Piel = <b>queratina + pH 5-6 + sebo + defensinas</b>; vía aérea = <b>moco + cilios</b>; intestino = <b>ácido gástrico + microbioma + criptidinas</b>. PRR reconoce PAMP: lo extraño sin aprender."}, "numeros": [{"l": "A", "html": "<b>pH de la piel</b>: <b class=\"n\">5–6</b>, por degradación de ácidos grasos (caprílico, oleico, undecilénico).", "rango": {"min": 3, "max": 8, "unidad": "pH", "zonas": [[5, 6, "n", "pH de la piel"]], "marcas": [5, 6]}}, {"l": "B", "html": "<b>Aparato ciliar</b>: <b class=\"n\">200 cilios</b> por célula; más del <b class=\"n\">80 %</b> de las partículas de un aerosol se expulsan. El árbol respiratorio mide <b class=\"n\">500 m²</b> y mueve <b class=\"n\">10.000 L</b> de aire al día.", "rango": null}, {"l": "C", "html": "<b>Ácido gástrico</b>: con acidez normal hacen falta <b class=\"a\">más de un millón</b> de <b>V. cholerae</b> o <b>E. coli</b> para infectar; en el aclorhídrico bastan unos pocos.", "rango": {"min": 0, "max": 2, "unidad": "millones de gérmenes ingeridos", "zonas": [[0, 1, "n", "con acidez normal no infecta"], [1, 2, "a", "infecta"]], "marcas": [1]}}, {"l": "D", "html": "<b>Microbioma</b>: más de <b class=\"n\">500 especies</b> en el intestino; unas <b class=\"n\">1.000 especies</b> de bacterias y hongos en piel y mucosas (hasta 300 billones, más de 1 kg).", "rango": null}], "escalas": [], "cadena": {"titulo": "De la puerta a la alarma innata", "subtitulo": "microbio en la superficie → barrera física → barrera química → PRR reconoce PAMP → alarma (o enfermedad si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Microbio en la puerta", "m": "<b>Qué pasa:</b> sobre piel y mucosas viven unas 1.000 especies de bacterias y hongos <span class=\"lt2\">D</span>, casi todas comensales. Un patógeno debe <b>adherirse y entrar</b>.", "pr": "la piel intacta casi no deja pasar; los comensales ocupan los nichos.", "pr_tit": "Produce:", "rf": "Preguntas ①⑤ · punto <span class=\"lt2\">D</span>", "color": "p1"}, {"t": "2. Barrera física", "m": "<b>Por qué funciona:</b> la queratina y los <mark>desmosomas</mark> sellan la piel; en la vía aérea el moco atrapa y los cilios barren hacia la faringe.", "pr": "más del 80 % de lo inhalado sale con la saliva <span class=\"lt2\">B</span>; si fallan los desmosomas, <span class=\"res\">bulas</span>.", "pr_tit": "Produce:", "rf": "Preguntas ④⑥ · punto <span class=\"lt2\">B</span>", "color": "p2"}, {"t": "3. Barrera química", "m": "<b>Qué mata:</b> pH 5-6 de la piel <span class=\"lt2\">A</span>, sebo, defensinas, criptidinas de Paneth, ácido gástrico <span class=\"lt2\">C</span>, lisozima (rompe) y lactoferrina (quita el hierro).", "pr": "el inóculo necesario es enorme; sin ácido gástrico, unos pocos vibriones bastan.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑦⑫ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">C</span>", "color": "p3"}, {"t": "4. Reconocimiento", "m": "<b>Cómo distingue lo extraño:</b> los PRR (TLR, NLR, lectinas tipo C) reconocen PAMP que <b>no existen en células humanas</b>; el TLR activa MyD88 (todos salvo TLR3) y NF-kB entra al núcleo.", "pr": "genes de defensinas, citoquinas e inflamación encendidos sin aprendizaje previo.", "pr_tit": "Produce:", "rf": "Preguntas ③⑨", "color": "p4"}, {"t": "5. Alarma o enfermedad", "m": "<b>Resultado:</b> TNF, IL-1 e IL-6; el hígado produce proteínas de fase aguda (PCR hasta ×1000); el epitelio intestinal libera IL-8 y llama neutrófilos.", "pr": "<b>si falla:</b> TLR4 bajo → infecciones frecuentes; TLR5 → <b>Legionella</b>; TLR11 → infecciones urinarias; TLR4 en exceso o falta de CD14 → <span class=\"res\">choque séptico</span>.", "pr_tit": "Produce:", "rf": "Preguntas ⑩⑪", "color": "p5"}], "extra": [{"html": "🧬 <b>Elementos constitutivos</b> (resistencia que se trae de nacimiento): especie, raza (sin antígeno <mark>Duffy</mark> no entra <b>P. vivax</b> ⑧), genes (<b>NRAMP</b> secuestra hierro en el fagosoma), edad (infancia y más de 60 años), hormonas (estrógeno → glucógeno → ácido láctico vaginal), temperatura (<b>M. leprae</b> en zonas frías).", "k": ""}, {"html": "👶 <b>Inmunidad pasiva</b> ②: anticuerpos ya hechos de la madre por placenta, calostro y leche; protege meses y no deja memoria. <b>Activa</b>: infección o vacuna, con memoria.", "k": "k"}], "escaleras": [{"c": "d", "t": "🚪 De la puerta abierta al choque séptico", "pasos": ["Barrera rota: herida, quemadura, aclorhidria", "el microbio entra con su LPS (PAMP)", "LBP lleva el LPS a <b>CD14</b>; el TLR4 lo reconoce", "TNF, IL-1, IL-6, IL-12; PCR ×1000", "TLR4 en exceso o CD14 defectuoso: <b>choque séptico</b>"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 1 (modalidades, activa y pasiva, PAMP, uniones celulares) y Clase 2 (elementos constitutivos, barreras físicas, PRR, TLR, NLR, lectinas tipo C, pentraxinas, moléculas destructoras)."}, "preguntas": [{"n": 1, "id": "IN1-001", "c": "g", "tema": "Las dos modalidades de la respuesta inmune", "pregunta": "Respecto a la inmunidad innata, es FALSO:", "opciones": ["a. Actúa de forma inmediata desde el primer contacto.", "b. No diferencia la clase ni la especie del agresor.", "c. No deja memoria del encuentro.", "d. Incluye barreras naturales, fagocitosis e inflamación.", "e. Necesita un período de aprendizaje de siete a diez días."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. El aprendizaje de 7-10 días es propio de la inmunidad adquirida, no de la innata.", "sin_banco": true, "ok": "", "x": "Las barreras de la imagen son innatas: actúan <mark>desde el primer contacto</mark>, sin aprendizaje ni memoria. Lo que tarda <span class=\"res\">7-10 días</span> es la adquirida.", "truco": "", "veces": 0}, {"n": 2, "id": "IN1-002", "c": "g", "tema": "Inmunidad activa e inmunidad pasiva", "pregunta": "Un recién nacido sano no se enferma de varias infecciones durante sus primeros meses, aunque nunca ha estado en contacto con esos microbios. ¿Qué tipo de inmunidad lo protege y por qué mecanismo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Inmunidad pasiva: anticuerpos maternos recibidos por la placenta, el calostro y la leche. No deja memoria propia, así que la protección es transitoria.", "sin_banco": true, "ok": "", "x": "El niño no ha fabricado esos anticuerpos: los <mark>recibe hechos</mark> de su madre. <span class=\"cx\">Por eso</span> es <span class=\"res\">inmunidad pasiva</span> y dura solo unos meses; <span class=\"cx\">en cambio</span>, la vacuna o la infección dan inmunidad activa con memoria.", "truco": "Pasiva = «me la pasaron» (placenta, calostro, leche).", "veces": 0}, {"n": 3, "id": "IN1-003", "c": "g", "tema": "Moléculas y sistemas de la defensa", "pregunta": "Los patrones moleculares asociados a patógenos (PAMP):", "opciones": ["a. Son proteínas propias alteradas por un tumor.", "b. Se presentan a los linfocitos T mediante moléculas MHC.", "c. Se expresan solo en microorganismos patógenos y los reconocen los PRR.", "d. Inducen la producción de un anticuerpo específico para cada uno.", "e. Son reconocidos únicamente por el receptor del linfocito B."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Son moléculas exclusivas de los microbios patógenos, reconocidas por los receptores de reconocimiento de patrones (PRR) de la inmunidad innata.", "sin_banco": true, "ok": "", "x": "El PAMP es un <mark>patrón</mark> que solo tienen los microbios (lipopolisacárido, peptidoglucano, manano), <span class=\"cx\">así que</span> el PRR lo reconoce sin «aprender». <span class=\"cx\">En cambio</span>, el antígeno induce un anticuerpo específico: eso ya es <span class=\"res\">inmunidad adquirida</span>.", "truco": "PAMP = Patrón del Patógeno; PRR = el Receptor que lo Reconoce.", "veces": 0}, {"n": 4, "id": "IN1-004", "c": "i", "tema": "Componentes celulares y tisulares", "pregunta": "Los defectos de qué tipo de unión celular son responsables de la formación de bulas en la piel:", "opciones": ["a. Uniones estrechas.", "b. Uniones de conexión por conectinas.", "c. Nanotúbulos.", "d. Desmosomas.", "e. Integrinas de la matriz extracelular."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los defectos de los desmosomas producen manifestaciones cutáneas como la formación de bulas.", "sin_banco": true, "ok": "", "x": "Los desmosomas sujetan los queratinocitos de la piel (panel izquierdo); <span class=\"cx\">por eso</span>, si fallan, las capas se separan y aparecen <span class=\"res\">bulas</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN1-005", "c": "d", "tema": "Barreras físicas: la piel", "pregunta": "Son defensas de la piel, EXCEPTO:", "opciones": ["a. Células de Paneth que almacenan criptidinas.", "b. pH ácido de 5 a 6 por degradación de ácidos grasos.", "c. Defensinas producidas por los queratinocitos.", "d. Moléculas antimicrobianas de las glándulas sebáceas.", "e. Células de Langerhans que capturan microorganismos."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Las células de Paneth están en la base de las criptas de Lieberkühn del intestino, no en la piel.", "sin_banco": true, "ok": "", "x": "Todo lo del panel izquierdo es de la piel (pH <span class=\"lt2\">A</span>, sebo, defensinas, Langerhans). Las células de <span class=\"res\">Paneth</span> están en el fondo de la cripta del panel derecho.", "truco": "", "veces": 0}, {"n": 6, "id": "IN1-006", "c": "d", "tema": "Barreras físicas: árbol respiratorio", "pregunta": "¿Cómo elimina el árbol respiratorio las partículas del aire inspirado?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Con la cubierta mucoserosa (mucina) y el aparato ciliar: cada célula ciliada tiene 200 cilios que barren el moco hacia la faringe, donde se deglute. Más del 80 % de las partículas de un aerosol se expulsan.", "sin_banco": true, "ok": "", "x": "Panel central: el moco <mark>atrapa</mark> y los cilios lo <mark>barren</mark> hacia la faringe; así sale <span class=\"res\">más del 80 %</span> de lo inhalado <span class=\"lt2\">B</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN1-007", "c": "i", "tema": "Barreras físicas: tracto gastrointestinal", "pregunta": "Un paciente gastrectomizado desarrolla cólera tras ingerir agua con muy pocos vibriones. ¿Qué barrera perdió y cuánto inóculo hace falta normalmente?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Perdió la acidez gástrica (barrera química). Con acidez normal se necesita ingerir más de un millón de gérmenes; en el aclorhídrico bastan unos pocos.", "sin_banco": true, "ok": "", "x": "El ácido gástrico es la barrera química del tubo digestivo <span class=\"lt2\">C</span>; sin él, <span class=\"res\">unos pocos vibriones</span> bastan.", "truco": "", "veces": 0}, {"n": 8, "id": "IN1-008", "c": "g", "tema": "Elementos constitutivos", "pregunta": "¿Por qué las personas de raza negra son más resistentes a *Plasmodium vivax*?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque sus eritrocitos carecen del antígeno del grupo sanguíneo Duffy, que es el receptor que usa *P. vivax* para invadir el hematíe.", "sin_banco": true, "ok": "", "x": "Es inmunidad <mark>racial</mark> o constitutiva: no se aprende. <b>P. vivax</b> necesita la molécula <span class=\"res\">Duffy</span> para entrar al eritrocito; sin ella, no tiene puerta. <span class=\"cx\">En cambio</span>, frente a <b>P. falciparum</b> protegen parcialmente la hemoglobina S y el déficit de G6PD.", "truco": "Sin Duffy no hay vivax: «sin cerradura, la llave no sirve».", "veces": 0}, {"n": 9, "id": "IN1-009", "c": "g", "tema": "Moléculas que detectan las señales de peligro", "pregunta": "La molécula adaptadora MyD88, que conduce a la entrada de NF-kB al núcleo, sirve a todos los receptores tipo Toll EXCEPTO al:", "opciones": ["a. TLR2.", "b. TLR4.", "c. TLR5.", "d. TLR11.", "e. TLR3."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. MyD88 sirve a todos los TLR con excepción del TLR3.", "sin_banco": true, "ok": "", "x": "<span class=\"cx\">Cuando</span> un PAMP se une a un TLR se activa <mark>MyD88</mark>, y esta lleva a que NF-kB entre al núcleo y encienda los genes de la respuesta innata. Es la vía de todos los TLR, salvo <span class=\"res\">el TLR3</span>.", "truco": "TLR3 = el «tercero excluido» de MyD88.", "veces": 0}, {"n": 10, "id": "IN1-010", "c": "d", "tema": "Moléculas que detectan las señales de peligro", "pregunta": "Relación correcta entre receptor tipo Toll y la consecuencia de su falla:", "opciones": ["a. TLR5 ausente: infecciones urinarias a repetición.", "b. TLR4 con baja expresión: infecciones frecuentes; en exceso, predisposición al síndrome séptico.", "c. TLR11 ausente: susceptibilidad a *Legionella*.", "d. TLR2 alterado: alergia al frío.", "e. TLR4 ausente: susceptibilidad a *Helicobacter pylori*."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La baja expresión del TLR4 da infecciones frecuentes y su exceso predispone al síndrome séptico.", "sin_banco": true, "ok": "", "x": "Cada TLR falla con su propia <mark>firma</mark>: TLR5 → <b>Legionella</b>; TLR11 → infecciones urinarias; TLR2 → regula el receptor de vitamina D frente al bacilo tuberculoso. La alergia al frío es de <span class=\"res\">NOD3</span>, y <b>H. pylori</b> corresponde a NOD1.", "truco": "TLR4 = Toxina (LPS) → poco: infecciones; mucho: sepsis.", "veces": 0}, {"n": 11, "id": "IN1-011", "c": "d", "tema": "Moléculas que detectan las señales de peligro", "pregunta": "Respecto a la proteína C reactiva, es correcto:", "opciones": ["a. Es una lectina tipo C que reconoce manosa.", "b. Es una galectina presente solo en el humano.", "c. Es una pentraxina que puede aumentar hasta mil veces ante una bacteria en sangre.", "d. La producen los queratinocitos de la piel.", "e. Destruye la quitina de la pared de los hongos."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es una pentraxina; ante bacteriemia se incrementa hasta mil veces su valor normal, se liga a polisacáridos bacterianos y activa el complemento.", "sin_banco": true, "ok": "", "x": "La PCR pertenece a las <mark>pentraxinas</mark>, junto con la proteína ligadora de lipopolisacáridos y el amiloide P. Normalmente está en microgramos, pero ante una bacteria en sangre sube <span class=\"res\">hasta mil veces</span>: <span class=\"cx\">por eso</span> es buen marcador de infección.", "truco": "PCR = Pentraxina que se Crece ×1000.", "veces": 0}, {"n": 12, "id": "IN1-012", "c": "d", "tema": "Sistemas y moléculas destructoras de microorganismos", "pregunta": "Compare cómo matan a las bacterias la lactoferrina y la lisozima.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La lactoferrina actúa por privación: secuestra el hierro libre e impide que la bacteria se reproduzca. La lisozima actúa por lisis directa: en lágrimas y moco nasal destruye grampositivas, gramnegativas y micobacterias.", "sin_banco": true, "ok": "", "x": "Son dos armas químicas de las secreciones: la lactoferrina <mark>quita el hierro</mark> y la lisozima <mark>rompe la pared</mark>; <span class=\"cx\">por eso</span> la lisozima de <span class=\"res\">lágrimas y moco nasal</span> protege la puerta.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "🧴 Piel", "🌬️ Vía respiratoria", "🍽️ Tubo digestivo"], "filas": [["Física", "Queratina y desmosomas, porque sellan la superficie", "Moco (mucina) y 200 cilios por célula, porque atrapan y barren", "Epitelio y microbioma, porque los comensales ocupan los nichos"], ["Química", "pH 5-6, sebo y defensinas, porque matan al microbio", "Lisozima y defensinas del moco, porque lisan bacterias", "Ácido gástrico y criptidinas de Paneth, porque destruyen lo ingerido"], ["Células", "Langerhans, porque capturan y llevan al ganglio", "Macrófagos alveolares (clase 4)", "Epitelio que libera IL-8, porque llama neutrófilos"], ["Si falla", "Planta del pie sin sebo: micosis; desmosomas: bulas", "Partículas que no se expulsan (literatura)", "Aclorhidria: cólera con pocos vibriones"], ["🔑 Para diferenciar", "Barrera <b>seca y ácida</b>", "Barrera que <b>se mueve</b> (moco + cilios)", "Barrera <b>ácida y poblada</b> (microbioma)"]]}, "fuente": "Fuente: tu teoría — Clase 1 (Generalidades y definiciones) y Clase 2 (Elementos constitutivos, barreras naturales y moléculas de reconocimiento), Rojas 17.ª ed., caps. 1-2."}, {"n": 2, "slug": "Circulacion_de_los_leucocitos", "titulo": "Circulación de los leucocitos", "subtitulo": "rodamiento, adherencia firme y diapédesis en la vénula poscapilar", "grupo": "g1", "lema": "La idea: un leucocito no sale de la sangre en cualquier sitio. La alarma del tejido <b>activa el endotelio cuboide</b> de la vénula poscapilar; entonces el leucocito <mark>rueda</mark> (selectinas), se <mark>pega</mark> (integrinas con ICAM) y <mark>sale</mark> (diapédesis o trancitosis), y en el tejido se arrastra hasta el foco siguiendo el gradiente de quimioquinas. En la imagen lo ves de izquierda a derecha; los números dicen cuánto tarda cada molécula.", "img": "img/02.webp", "mini": "img/mini/02.webp", "ratio": 1.5, "etiquetas": [{"n": "②", "t": "Libre", "s": "nada en<br>la sangre", "c": "d", "x": 0.8, "y": 8, "ax": 9, "ay": 37.5, "al": "l"}, {"n": "⑤⑨", "t": "Endotelio", "s": "cuboide: ICAM-1<br>y VCAM", "c": "i", "x": 20.5, "y": 8, "ax": 19.5, "ay": 29, "d": "B"}, {"n": "⑥⑦⑧", "t": "Rueda", "s": "selectina<br>y mucina", "c": "d", "x": 37.5, "y": 8, "ax": 26, "ay": 45.5, "d": "A"}, {"n": "⑥⑨", "t": "Se ancla", "s": "integrina<br>con ICAM", "c": "d", "x": 51.5, "y": 8, "ax": 45, "ay": 45.5, "d": "C"}, {"n": "⑩", "t": "Diapédesis", "s": "entre dos<br>células", "c": "d", "x": 66, "y": 8, "ax": 57.8, "ay": 49}, {"n": "⑪", "t": "Macrófago", "s": "libera<br>quimioquinas", "c": "g", "x": 85, "y": 8, "ax": 84, "ay": 56, "d": "D"}, {"n": "", "t": "Matriz extracelular", "s": "se arrastra:<br>VLA-1, 2 y 5", "c": "g", "x": 0.8, "y": 90, "ax": 19.5, "ay": 64, "al": "l"}, {"n": "⑪", "t": "Lamelipodio", "s": "hacia el gradiente<br>de quimioquinas", "c": "d", "x": 50, "y": 90, "ax": 69, "ay": 66.5}, {"n": "", "t": "Foco infeccioso", "s": "bacterias", "c": "g", "x": 70, "y": 90, "ax": 76, "ay": 70}, {"n": "③", "t": "Mastocito", "s": "histamina:<br>abre el capilar", "c": "g", "x": 88, "y": 90, "ax": 93.8, "ay": 65}], "diapos": [{"img": "img/02.webp", "ratio": 1.5, "titulo": "Rodar, pegarse y atravesar", "texto": "El leucocito <mark>rueda</mark> (selectinas), <mark>se ancla</mark> (integrinas con ICAM) y <mark>atraviesa</mark> la vénula poscapilar ⑤–⑪.", "etiquetas": [{"n": "②", "t": "Libre", "s": "nada en<br>la sangre", "c": "d", "x": 0.8, "y": 8, "ax": 9, "ay": 37.5, "al": "l"}, {"n": "⑤⑨", "t": "Endotelio", "s": "cuboide: ICAM-1<br>y VCAM", "c": "i", "x": 20.5, "y": 8, "ax": 19.5, "ay": 29, "d": "B"}, {"n": "⑥⑦⑧", "t": "Rueda", "s": "selectina<br>y mucina", "c": "d", "x": 37.5, "y": 8, "ax": 26, "ay": 45.5, "d": "A"}, {"n": "⑥⑨", "t": "Se ancla", "s": "integrina<br>con ICAM", "c": "d", "x": 51.5, "y": 8, "ax": 45, "ay": 45.5, "d": "C"}, {"n": "⑩", "t": "Diapédesis", "s": "entre dos<br>células", "c": "d", "x": 66, "y": 8, "ax": 57.8, "ay": 49}, {"n": "⑪", "t": "Macrófago", "s": "libera<br>quimioquinas", "c": "g", "x": 85, "y": 8, "ax": 84, "ay": 56, "d": "D"}, {"n": "", "t": "Matriz extracelular", "s": "se arrastra:<br>VLA-1, 2 y 5", "c": "g", "x": 0.8, "y": 90, "ax": 19.5, "ay": 64, "al": "l"}, {"n": "⑪", "t": "Lamelipodio", "s": "hacia el gradiente<br>de quimioquinas", "c": "d", "x": 50, "y": 90, "ax": 69, "ay": 66.5}, {"n": "", "t": "Foco infeccioso", "s": "bacterias", "c": "g", "x": 70, "y": 90, "ax": 76, "ay": 70}, {"n": "③", "t": "Mastocito", "s": "histamina:<br>abre el capilar", "c": "g", "x": 88, "y": 90, "ax": 93.8, "ay": 65}]}, {"img": "img/02_2.webp", "ratio": 1.5, "titulo": "Médula ósea y timo: órganos primarios", "texto": "La médula produce casi todas las células y el timo madura a los T ①; la <b>línea linfoide</b> da NK, T y B ②.", "etiquetas": [{"n": "①", "t": "Médula ósea roja", "s": "órgano primario:<br>fabrica casi todo", "c": "d", "x": 0.5, "y": 8, "ax": 8.5, "ay": 40, "al": "l"}, {"n": "②", "t": "Neutrófilo", "s": "línea mieloide,<br>no linfoide", "c": "g", "x": 24, "y": 8, "ax": 26, "ay": 29}, {"n": "①", "t": "Célula madre", "s": "pluripotencial:<br>origen de todas", "c": "g", "x": 41, "y": 8, "ax": 33.2, "ay": 44}, {"n": "②", "t": "Linfocitos", "s": "línea linfoide:<br>T y B", "c": "i", "x": 57, "y": 8, "ax": 39, "ay": 29.3}, {"n": "①", "t": "Timo", "s": "órgano primario:<br>madura los T", "c": "d", "x": 74, "y": 8, "ax": 57.3, "ay": 32}, {"n": "①", "t": "Corteza tímica", "s": "timocitos que<br>se seleccionan", "c": "i", "x": 99.5, "y": 8, "ax": 81.4, "ay": 30, "al": "r"}, {"n": "", "t": "Eritrocito", "s": "línea mieloide", "c": "g", "x": 0.5, "y": 91, "ax": 23.8, "ay": 56.6, "al": "l"}, {"n": "", "t": "Plaquetas", "s": "fragmentos del<br>megacariocito", "c": "g", "x": 20, "y": 91, "ax": 30.6, "ay": 62.5}, {"n": "②", "t": "NK", "s": "linfoide grande<br>con gránulos", "c": "i", "x": 40, "y": 91, "ax": 41.7, "ay": 55.7}, {"n": "", "t": "Corpúsculo de Hassall", "s": "en la médula<br>tímica", "c": "g", "x": 68, "y": 91, "ax": 80.4, "ay": 46.9}, {"n": "①", "t": "LsT maduro", "s": "sale del timo<br>a la sangre", "c": "i", "x": 99.5, "y": 91, "ax": 89.8, "ay": 58.6, "al": "r"}]}, {"img": "img/02_3.webp", "ratio": 1.5, "titulo": "Apoptosis, lisis y CCR5", "texto": "La apoptosis no vierte enzimas, <span class=\"cx\">por eso</span> <mark>no inflama</mark>; <span class=\"cx\">en cambio</span>, la lisis sí ④. El maraviroc tapa el <mark>CCR5</mark>, la puerta del VIH ⑫.", "etiquetas": [{"n": "④", "t": "Apoptosis", "s": "muerte programada<br>y ordenada", "c": "i", "x": 0.5, "y": 8, "ax": 7, "ay": 40, "al": "l"}, {"n": "④", "t": "Cuerpos apoptóticos", "s": "membrana intacta:<br>no vierten enzimas", "c": "i", "x": 25, "y": 8, "ax": 17.6, "ay": 45}, {"n": "④", "t": "Lisis celular", "s": "la membrana<br>se rompe", "c": "d", "x": 43, "y": 8, "ax": 42.3, "ay": 36}, {"n": "④", "t": "Enzimas vertidas", "s": "dañan el tejido:<br>inflamación", "c": "d", "x": 60, "y": 8, "ax": 52, "ay": 37}, {"n": "⑫", "t": "VIH", "s": "busca la puerta<br>CCR5", "c": "d", "x": 80, "y": 8, "ax": 79.4, "ay": 28}, {"n": "④", "t": "Macrófago", "s": "fagocita los cuerpos<br>sin inflamar", "c": "i", "x": 20, "y": 91, "ax": 30.6, "ay": 50}, {"n": "④", "t": "Neutrófilos", "s": "llegan atraídos<br>por la lisis", "c": "d", "x": 41, "y": 91, "ax": 50.8, "ay": 62}, {"n": "⑫", "t": "CCR5", "s": "receptor de<br>quimioquinas", "c": "i", "x": 61, "y": 91, "ax": 80, "ay": 55}, {"n": "⑫", "t": "Maraviroc", "s": "tapa el CCR5:<br>el virus no entra", "c": "i", "x": 80, "y": 91, "ax": 84.6, "ay": 57.6}, {"n": "⑫", "t": "CD4", "s": "receptor<br>principal", "c": "g", "x": 99.5, "y": 91, "ax": 95.7, "ay": 47, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Una vénula poscapilar cortada a lo largo. El mismo leucocito en cinco momentos: <b class=\"d\">libre → rueda → se pega → sale → se arrastra</b> hasta las bacterias. Colores: <b class=\"i\">azul</b> = vaso y endotelio; <b class=\"d\">rojo</b> = leucocito y sus moléculas; <b>gris</b> = tejido y foco.", "Todo empieza en el tejido: el macrófago detecta al microbio y libera quimioquinas; el mastocito libera histamina, y con el complemento y las kininas ③ el <mark>endotelio cuboide</mark> se activa ⑤: expresa ICAM-1 y VCAM.", "En reposo el endotelio es <span class=\"res\">no adherente</span> ⑨. El leucocito viene de la médula ósea, el órgano linfoide primario ①; los neutrófilos y monocitos son de línea mieloide y las NK, de línea linfoide ②."], "recordar": "<b>Rueda</b> (selectina-mucina) → <b>se ancla</b> (LFA-1/VLA-4 con ICAM-1/VCAM) → <b>sale</b> (diapédesis: neutrófilo y macrófago; trancitosis: linfocito). En la sangre nada; en el tejido se arrastra."}, "numeros": [{"l": "A", "html": "<b>Selectina P</b>: minutos (está prefabricada). <b>Selectina E</b>: a los <b class=\"n\">30 minutos</b>, inducida por IL-1, IFNγ y TNF.", "rango": {"min": 0, "max": 60, "unidad": "minutos tras el estímulo", "zonas": [[0, 30, "m", "solo selectina P (prefabricada)"], [30, 60, "n", "también selectina E"]], "marcas": [30]}}, {"l": "B", "html": "<b>ICAM-1</b> (CD54): se expresa <b class=\"n\">16–24 h</b> después del estímulo; <b>ICAM-2</b> está presente en reposo.", "rango": {"min": 0, "max": 30, "unidad": "horas tras el estímulo", "zonas": [[0, 16, "b", "ICAM-1 aún no"], [16, 24, "n", "ICAM-1 expresada"]], "marcas": [16, 24]}}, {"l": "C", "html": "<b>VLA-4</b>, «antígeno de expresión muy tardía»: aparece <b class=\"a\">7–10 días</b> después de activado el linfocito.", "rango": {"min": 0, "max": 14, "unidad": "días tras activar el linfocito", "zonas": [[0, 7, "b", "sin VLA-4"], [7, 10, "n", "aparece VLA-4"]], "marcas": [7, 10]}}, {"l": "D", "html": "<b>Quimioquinas</b>: CC <b class=\"n\">28</b> miembros (monocitos, NK, eosinófilos), CXC <b class=\"n\">13</b> (neutrófilos), XCL 2 y CX3CL 1; actúan sobre <b class=\"n\">18</b> receptores. El endotelio del adulto pesa <b class=\"n\">1 kg</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del foco infeccioso al leucocito en el tejido", "subtitulo": "alarma en el tejido → endotelio activado → rodamiento → adherencia firme → salida → migración (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Alarma en el tejido", "m": "<b>Qué pasa:</b> el macrófago detecta al agresor y libera <b>quimioquinas</b>; el mastocito libera histamina; se activan complemento (C5a) y kininas, que aumentan la permeabilidad.", "pr": "gradiente de quimioquinas con epicentro en el foco <span class=\"lt2\">D</span>.", "pr_tit": "Produce:", "rf": "Preguntas ③⑪ · punto <span class=\"lt2\">D</span>", "color": "p1"}, {"t": "2. Endotelio activado", "m": "<b>Por qué ahí:</b> en la vénula poscapilar el endotelio es <b>cuboide</b>. Activado, saca selectina P en minutos y E a los 30 min <span class=\"lt2\">A</span>; <span class=\"cx\">luego</span> ICAM-1 <span class=\"lt2\">B</span> y VCAM.", "pr": "el endotelio pasa de no adherente a «pegajoso».", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑧⑨ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">B</span>", "color": "p2"}, {"t": "3. Rodamiento", "m": "<b>Cómo:</b> las <mark>selectinas</mark> se unen a mucinas en forma <b>intermitente y débil</b>; la selectina L reconoce las adresinas GlyCAM-1 y MAdCAM-1.", "pr": "el leucocito frena y las quimioquinas cambian la forma de sus integrinas.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑦", "color": "p3"}, {"t": "4. Adherencia firme", "m": "<b>Cómo:</b> las integrinas LFA-1 y VLA-4 <span class=\"lt2\">C</span>, ya activadas, se unen <b>ávidamente</b> a ICAM-1 y VCAM.", "pr": "el leucocito se detiene y se aplana sobre el endotelio.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑨ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Salida", "m": "<b>Dos vías:</b> <mark>diapédesis</mark> entre dos células endoteliales que separan JAM y caderina E (neutrófilo, macrófago) o <mark>trancitosis</mark> a través de una (linfocito).", "pr": "el leucocito queda en el tejido conectivo.", "pr_tit": "Produce:", "rf": "Pregunta ⑩", "color": "p5"}, {"t": "6. En el tejido", "m": "<b>Qué hace:</b> «nada en la sangre, se arrastra en el tejido»: la IL-1 induce metaloproteinasas, y con VLA-1, 2 y 5 se ancla a laminina, fibronectina y vitronectina; emite un <b>lamelipodio</b> hacia el gradiente.", "pr": "llega al foco. <b>Si falla:</b> mutación de integrinas → deficiencia de adherencia leucocitaria; el VIH usa receptores de quimioquinas (CCR5) para entrar.", "pr_tit": "Produce:", "rf": "Preguntas ⑪⑫", "color": "p1"}], "extra": [{"html": "🏭 <b>De dónde vienen:</b> de la médula ósea (órgano linfoide primario, con el timo ①). Línea <b>mieloide</b>: neutrófilos, monocitos, dendríticas, eosinófilos, basófilos, mastocitos; línea <b>linfoide</b>: NK, T y B ②. <span class=\"cx\">Cuando</span> el neutrófilo muere por <b>apoptosis</b> no inflama; por <b>lisis</b>, sí ④.", "k": ""}, {"html": "💊 <b>Quimioquinas como diana:</b> el VIH y <b>P. vivax</b> entran por receptores de quimioquinas. <mark>Maraviroc</mark> bloquea el CCR5 ⑫ y <b>plerixafor</b> el CXCR4. La falta de caderina N facilita las metástasis.", "k": "k"}], "escaleras": [{"c": "i", "t": "⏱️ El reloj del endotelio activado", "pasos": ["Reposo: no adherente (selectinas E y P, ICAM-2)", "minutos: selectina P (prefabricada)", "30 min: selectina E (sintetizada)", "16-24 h: ICAM-1", "7-10 días: VLA-4 en linfocitos activados"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 3 (endotelio, quimioquinas, moléculas de adherencia, paso a los tejidos, migración del monocito, circulación en tejidos) y Clase 1 (órganos linfoides, líneas mieloide y linfoide, kininas, apoptosis)."}, "preguntas": [{"n": 1, "id": "IN1-013", "c": "g", "tema": "Órganos y células del sistema inmune", "pregunta": "Son órganos linfoides primarios:", "opciones": ["a. Ganglios linfáticos y bazo.", "b. Amígdalas y placas de Peyer.", "c. Bazo y timo.", "d. Médula ósea y timo.", "e. Acúmulos linfoides de las infecciones crónicas."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La médula ósea (produce casi todas las células) y el timo (madura y selecciona a los linfocitos T).", "sin_banco": true, "ok": "", "x": "Los primarios <mark>fabrican y educan</mark> las células: médula ósea y timo. <span class=\"cx\">En cambio</span>, los secundarios (ganglios, bazo, amígdalas, placas de Peyer) son donde los linfocitos reciben la información, y los terciarios son <span class=\"res\">neoformaciones en infecciones crónicas y autoinmunidad</span>.", "truco": "Primarios = fábrica y escuela (médula y timo).", "veces": 0}, {"n": 2, "id": "IN1-014", "c": "g", "tema": "Órganos y células del sistema inmune", "pregunta": "Deriva de la línea linfoide de la médula ósea:", "opciones": ["a. Célula asesina natural (NK).", "b. Neutrófilo.", "c. Monocito.", "d. Célula dendrítica.", "e. Mastocito."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La línea linfoide origina las NK, los linfocitos T y los linfocitos B.", "sin_banco": true, "ok": "", "x": "De la célula madre salen <mark>dos líneas</mark>: la mieloide (neutrófilos, monocitos, dendríticas, eosinófilos, basófilos, mastocitos) y la linfoide. La NK tiene morfología de linfocito, <span class=\"cx\">así que</span> viene de la <span class=\"res\">línea linfoide</span> aunque sea innata.", "truco": "Linfoide = T, B y NK; todo lo demás es mieloide.", "veces": 0}, {"n": 3, "id": "IN1-015", "c": "g", "tema": "Moléculas y sistemas de la defensa", "pregunta": "¿Qué sistema enzimático plasmático incrementa la respuesta inflamatoria al aumentar la permeabilidad capilar?", "opciones": ["a. Sistema del complemento.", "b. Sistema de la coagulación.", "c. Sistema fibrinolítico.", "d. Sistema de las kininas.", "e. Sistema de las caderinas."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El sistema de las kininas aumenta la permeabilidad capilar.", "sin_banco": true, "ok": "", "x": "Son tres sistemas que <mark>amplifican</mark> la respuesta: el complemento aumenta la fagocitosis y lisa gérmenes; la coagulación aísla lo extraño en un gel de fibrina; <span class=\"cx\">en cambio</span>, las kininas abren el capilar, <span class=\"cx\">así que</span> <span class=\"res\">aumentan la permeabilidad</span> y facilitan la salida de leucocitos.", "truco": "Kininas: abren la compuerta del capilar.", "veces": 0}, {"n": 4, "id": "IN1-016", "c": "i", "tema": "Mecanismos celulares básicos", "pregunta": "¿Por qué la apoptosis no produce inflamación y la lisis celular sí?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque la apoptosis es una muerte programada que no libera enzimas tóxicas al medio; la lisis vierte el contenido enzimático de la célula y genera daño tisular con reclutamiento inflamatorio.", "sin_banco": true, "ok": "", "x": "En la apoptosis la célula se <mark>desarma ordenadamente</mark> y nada tóxico sale afuera, <span class=\"cx\">por eso</span> no llama a los leucocitos. <span class=\"cx\">En cambio</span>, en la lisis la célula revienta, <span class=\"cx\">así que</span> sus enzimas dañan el tejido y <span class=\"res\">atraen la inflamación</span>.", "truco": "Apoptosis = mudanza ordenada; lisis = explosión.", "veces": 0}, {"n": 5, "id": "IN1-017", "c": "i", "tema": "La señal de alarma y el endotelio", "pregunta": "El paso de los leucocitos de la sangre a los tejidos ocurre principalmente en:", "opciones": ["a. Las arteriolas musculares.", "b. Los capilares de endotelio plano.", "c. Las vénulas poscapilares de endotelio cuboide.", "d. Los vasos linfáticos aferentes.", "e. Las arterias elásticas."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. En las vénulas poscapilares, cuyas células endoteliales son cuboides y unidas por JAM y caderinas que pueden abrirse de forma reversible.", "sin_banco": true, "ok": "", "x": "La imagen es una <mark>vénula poscapilar</mark>: sus células endoteliales son cuboides y sus uniones (JAM, caderinas) se abren de forma reversible; <span class=\"cx\">por eso</span> <span class=\"res\">ahí salen los leucocitos</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN1-018", "c": "d", "tema": "Paso de los leucocitos a los tejidos", "pregunta": "Secuencia correcta del paso de un leucocito al tejido inflamado:", "opciones": ["a. Diapédesis → rodamiento → adherencia firme.", "b. Adherencia firme → rodamiento → diapédesis.", "c. Rodamiento → diapédesis → adherencia firme.", "d. Diapédesis → adherencia firme → rodamiento.", "e. Rodamiento → adherencia firme → diapédesis."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Primero rodamiento (selectinas con mucinas), luego adherencia firme (integrinas con ICAM) y por último diapédesis o trancitosis.", "sin_banco": true, "ok": "", "x": "Léela de izquierda a derecha en la imagen: <span class=\"cx\">primero</span> <mark>rueda</mark>, <span class=\"cx\">luego</span> <mark>se pega</mark> y después <mark>sale</mark>. Ese orden no cambia.", "truco": "", "veces": 0}, {"n": 7, "id": "IN1-019", "c": "d", "tema": "Moléculas de adherencia", "pregunta": "El rodamiento del leucocito sobre el endotelio se debe a la unión intermitente de:", "opciones": ["a. Integrinas LFA-1 con ICAM-1.", "b. VLA-4 con VCAM-1.", "c. Selectinas con mucinas.", "d. JAM con caderina E.", "e. VLA-1 con laminina."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Selectinas con mucinas: una unión intermitente y de baja afinidad.", "sin_banco": true, "ok": "", "x": "Es la segunda célula de la imagen: toca la pared con contactos débiles e intermitentes <span class=\"res\">selectina-mucina</span>, <span class=\"cx\">así que</span> solo frena.", "truco": "", "veces": 0}, {"n": 8, "id": "IN1-020", "c": "d", "tema": "Moléculas de adherencia", "pregunta": "La selectina P aparece en la membrana endotelial en pocos minutos y la selectina E recién a los 30 minutos. ¿Qué explica la diferencia?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La selectina P está prefabricada y almacenada en la célula endotelial y solo debe trasladarse a la membrana; la selectina E debe sintetizarse tras el estímulo de IL-1, IFNγ y TNF.", "sin_banco": true, "ok": "", "x": "La selectina P ya estaba guardada en el endotelio <span class=\"lt2\">A</span>; la E hay que fabricarla, <span class=\"cx\">por eso</span> tarda <span class=\"res\">unos 30 minutos</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN1-021", "c": "i", "tema": "Moléculas de adherencia", "pregunta": "Respecto a las moléculas de adherencia, es FALSO:", "opciones": ["a. El ICAM-1 se expresa 16 a 24 horas después del estímulo.", "b. En reposo, el endotelio cuboide es muy adherente para los leucocitos.", "c. La VLA-4 aparece 7 a 10 días después de activado el linfocito.", "d. La falta de expresión de caderina N facilita las metástasis.", "e. Las JAM dejan de expresarse en los capilares de la región afectada."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. En reposo el endotelio cuboide es NO adherente, aunque exprese selectinas E y P e ICAM-2.", "sin_banco": true, "ok": "", "x": "En reposo el endotelio cuboide es <mark>no adherente</mark>; las letras <span class=\"lt2\">B</span> y <span class=\"lt2\">C</span> marcan cuándo aparecen ICAM-1 (16-24 h) y VLA-4 (<span class=\"res\">7-10 días</span>).", "truco": "", "veces": 0}, {"n": 10, "id": "IN1-022", "c": "d", "tema": "Paso de los leucocitos a los tejidos", "pregunta": "Los linfocitos atraviesan el endotelio penetrando una célula endotelial y saliendo por su cara opuesta. Este mecanismo se denomina:", "opciones": ["a. Diapédesis paracelular.", "b. Trancitosis.", "c. Rodamiento.", "d. Marginación.", "e. Macropinocitosis."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Trancitosis: la usan los linfocitos. La diapédesis (paracelular, entre dos células endoteliales) la usan macrófagos y neutrófilos.", "sin_banco": true, "ok": "", "x": "En la imagen el neutrófilo sale <mark>entre</mark> dos células endoteliales (diapédesis). El linfocito, <span class=\"cx\">en cambio</span>, las atraviesa: <span class=\"res\">trancitosis</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN1-023", "c": "d", "tema": "Quimioquinas", "pregunta": "La familia de quimioquinas que actúa principalmente sobre los neutrófilos es:", "opciones": ["a. CXC.", "b. CC.", "c. XCL.", "d. CX3CL.", "e. CCR."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Las quimioquinas CXC (13 miembros) actúan principalmente sobre los neutrófilos.", "sin_banco": true, "ok": "", "x": "Las quimioquinas se ordenan por sus <mark>cuatro cisteínas</mark>: CC (28 miembros, sobre monocitos, NK y eosinófilos), CXC (13, sobre neutrófilos), XCL (2) y CX3CL (una, anclada a membrana). CCR no es una familia: es <span class=\"res\">el nombre de un receptor</span>.", "truco": "CXC llama al neutrófilo; CC, al monocito.", "veces": 0}, {"n": 12, "id": "IN1-024", "c": "g", "tema": "Quimioquinas", "pregunta": "Un paciente con VIH inicia tratamiento con maraviroc. ¿Sobre qué molécula actúa y por qué frena al virus?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Bloquea el CCR5, un receptor de quimioquinas que el VIH usa como puerta de entrada a las células que invade.", "sin_banco": true, "ok": "", "x": "Algunos microbios usan los <mark>receptores de quimioquinas</mark> como puerta: el VIH y <b>P. vivax</b> entran por ellos. <span class=\"cx\">Por eso</span> bloquear el CCR5 con maraviroc impide la entrada del virus; el <span class=\"res\">plerixafor</span> bloquea, <span class=\"cx\">en cambio</span>, el CXCR4.", "truco": "MaRAViroc cierra la puerta CCR5.", "veces": 0}], "tabla": {"cab": ["", "🛞 Rodamiento", "⚓ Adherencia firme", "🚪 Salida"], "filas": [["Leucocito", "Selectina L y ligandos (PSGL-1), porque rozan el endotelio", "LFA-1, VLA-4, Mac-1, porque se activan con quimioquinas", "Separa JAM y caderina E, porque abre el paso"], ["Endotelio", "Selectinas P y E sobre mucinas, porque frenan", "ICAM-1, ICAM-2, VCAM-1, porque anclan", "Uniones que se abren de forma reversible"], ["Unión", "Débil e intermitente: solo frena", "Ávida y fija: lo detiene", "Diapédesis (neutrófilo, macrófago) o trancitosis (linfocito)"], ["🔑 Lo que no debes olvidar", "Selectina = <mark>rueda</mark>", "Integrina + ICAM = <mark>ancla</mark>", "Entre células = diapédesis; a través = trancitosis"]]}, "fuente": "Fuente: tu teoría — Clase 3 (Por qué, a dónde y cómo circulan los leucocitos) y Clase 1 (órganos, líneas celulares, sistemas enzimáticos y apoptosis), Rojas 17.ª ed., caps. 1 y 3."}, {"n": 3, "slug": "Neutrofilo_y_fagocitosis", "titulo": "Neutrófilo y fagocitosis", "subtitulo": "opsonina, fagosoma, estallido respiratorio y trampas de ADN", "grupo": "g2", "lema": "La idea: el neutrófilo es el <b>primero en llegar</b> y el más numeroso. Si el germen viene <mark>opsonizado</mark> (anticuerpos o complemento), lo agarra mil veces mejor, lo encierra <b>en cremallera</b> en un fagosoma, le vierte sus gránulos y lo mata con oxígeno (estallido respiratorio), nitrógeno o ácido. Después muere: por apoptosis, que apaga la inflamación, o lanzando una <u>red de ADN</u>. En la imagen ves los tres momentos de izquierda a derecha.", "img": "img/03.webp", "mini": "img/mini/03.webp", "ratio": 1.5, "etiquetas": [{"n": "①", "t": "Neutrófilo", "s": "célula<br>terminal", "c": "i", "x": 0.8, "y": 5, "ax": 9.8, "ay": 39, "d": "A", "al": "l"}, {"n": "③⑥", "t": "Opsoninas", "s": "anticuerpos y<br>complemento", "c": "i", "x": 21, "y": 5, "ax": 25, "ay": 17, "d": "B"}, {"n": "⑤", "t": "Cremallera", "s": "rodea al<br>germen", "c": "i", "x": 35, "y": 5, "ax": 26, "ay": 32}, {"n": "⑧⑨", "t": "Fagosoma", "s": "ROS y<br>pH ácido", "c": "d", "x": 49.5, "y": 5, "ax": 52, "ay": 41, "d": "C"}, {"n": "②⑦", "t": "Gránulos", "s": "mieloperoxidasa<br>al fagosoma", "c": "d", "x": 63, "y": 5, "ax": 56, "ay": 24.5}, {"n": "⑤", "t": "Macrófago", "s": "sí presenta<br>el antígeno", "c": "g", "x": 27, "y": 90, "ax": 44, "ay": 77}, {"n": "④", "t": "Muere", "s": "apoptosis o<br>red de ADN", "c": "i", "x": 67, "y": 90, "ax": 71, "ay": 40, "d": "D"}, {"n": "⑩", "t": "NET", "s": "red de ADN que<br>atrapa microbios", "c": "d", "x": 79.5, "y": 90, "ax": 86, "ay": 50}, {"n": "", "t": "Atrapados", "s": "cocos y<br>bacilos", "c": "g", "x": 99, "y": 90, "ax": 95.5, "ay": 31, "al": "r"}], "diapos": [{"img": "img/03.webp", "ratio": 1.5, "titulo": "Opsonina, fagosoma y trampas de ADN", "texto": "El neutrófilo agarra mil veces mejor al germen <mark>opsonizado</mark> <span class=\"lt2\">B</span>, lo encierra en el fagosoma y lo mata; <span class=\"cx\">luego</span> muere por apoptosis o lanza una NET ①–⑩.", "etiquetas": [{"n": "①", "t": "Neutrófilo", "s": "célula<br>terminal", "c": "i", "x": 0.8, "y": 5, "ax": 9.8, "ay": 39, "d": "A", "al": "l"}, {"n": "③⑥", "t": "Opsoninas", "s": "anticuerpos y<br>complemento", "c": "i", "x": 21, "y": 5, "ax": 25, "ay": 17, "d": "B"}, {"n": "⑤", "t": "Cremallera", "s": "rodea al<br>germen", "c": "i", "x": 35, "y": 5, "ax": 26, "ay": 32}, {"n": "⑧⑨", "t": "Fagosoma", "s": "ROS y<br>pH ácido", "c": "d", "x": 49.5, "y": 5, "ax": 52, "ay": 41, "d": "C"}, {"n": "②⑦", "t": "Gránulos", "s": "mieloperoxidasa<br>al fagosoma", "c": "d", "x": 63, "y": 5, "ax": 56, "ay": 24.5}, {"n": "⑤", "t": "Macrófago", "s": "sí presenta<br>el antígeno", "c": "g", "x": 27, "y": 90, "ax": 44, "ay": 77}, {"n": "④", "t": "Muere", "s": "apoptosis o<br>red de ADN", "c": "i", "x": 67, "y": 90, "ax": 71, "ay": 40, "d": "D"}, {"n": "⑩", "t": "NET", "s": "red de ADN que<br>atrapa microbios", "c": "d", "x": 79.5, "y": 90, "ax": 86, "ay": 50}, {"n": "", "t": "Atrapados", "s": "cocos y<br>bacilos", "c": "g", "x": 99, "y": 90, "ax": 95.5, "ay": 31, "al": "r"}]}, {"img": "img/03_2.webp", "ratio": 1.5, "titulo": "Estallido respiratorio y óxido nítrico", "texto": "La NADPH oxidasa genera radicales de oxígeno ⑨ y la <b>mieloperoxidasa</b> del neutrófilo los potencia ②⑦; el macrófago fabrica NO desde la <b>L-arginina</b> ⑧.", "etiquetas": [{"n": "⑨", "t": "Oxígeno (O₂)", "s": "su consumo<br>se dispara", "c": "i", "x": 0.5, "y": 6, "ax": 4, "ay": 32, "al": "l"}, {"n": "⑨", "t": "NADPH oxidasa", "s": "se arma en<br>la membrana", "c": "d", "x": 24, "y": 6, "ax": 31, "ay": 33}, {"n": "⑨", "t": "Chispas de ROS", "s": "superóxido, H₂O₂:<br>quimioluminiscencia", "c": "d", "x": 42, "y": 6, "ax": 38, "ay": 42}, {"n": "②⑦", "t": "Gránulo azurófilo", "s": "vierte la<br>mieloperoxidasa", "c": "d", "x": 60, "y": 6, "ax": 55, "ay": 24}, {"n": "⑧", "t": "L-arginina", "s": "sustrato de<br>la iNOS", "c": "g", "x": 76, "y": 6, "ax": 70, "ay": 28}, {"n": "⑧", "t": "iNOS", "s": "la inducen<br>IFNγ y TNFα", "c": "i", "x": 99.5, "y": 6, "ax": 82, "ay": 33, "al": "r"}, {"n": "②", "t": "Fagosoma del neutrófilo", "s": "con mieloperoxidasa:<br>hipohalógenos", "c": "d", "x": 0.5, "y": 91, "ax": 32, "ay": 65, "al": "l"}, {"n": "⑨", "t": "Bacteria destruida", "s": "por radicales<br>y enzimas", "c": "d", "x": 40, "y": 91, "ax": 48, "ay": 57}, {"n": "⑧", "t": "Óxido nítrico", "s": "se une al hierro<br>del germen", "c": "d", "x": 68, "y": 91, "ax": 77, "ay": 60}, {"n": "⑦", "t": "Fagosoma del macrófago", "s": "sin mieloperoxidasa:<br>mata con NO", "c": "g", "x": 99.5, "y": 91, "ax": 92, "ay": 58, "al": "r"}]}, {"img": "img/03_3.webp", "ratio": 1.5, "titulo": "Bazo, cápsula y evasión", "texto": "Sin bazo no hay <mark>tufsina</mark>, <span class=\"cx\">por eso</span> el neumococo encapsulado mata ⑪; cada germen evade a su modo: <b>Legionella</b> vive en el fagosoma, <b>E. coli</b> evita ser fagocitada ⑫.", "etiquetas": [{"n": "⑪", "t": "Bazo", "s": "fabrica la<br>tufsinasa", "c": "d", "x": 0.5, "y": 8, "ax": 9.8, "ay": 30, "al": "l"}, {"n": "⑪", "t": "IgG", "s": "de ella sale<br>la tufsina", "c": "i", "x": 18, "y": 8, "ax": 23.5, "ay": 33}, {"n": "⑪", "t": "Tufsinasa", "s": "enzima del bazo:<br>corta la IgG", "c": "g", "x": 34, "y": 8, "ax": 29.3, "ay": 43}, {"n": "⑪", "t": "Neumococo", "s": "diplococo<br>encapsulado", "c": "d", "x": 50, "y": 8, "ax": 43.6, "ay": 40}, {"n": "⑪", "t": "Cápsula", "s": "polisacárido<br>resbaladizo", "c": "d", "x": 66, "y": 8, "ax": 58.6, "ay": 34}, {"n": "⑫", "t": "E. coli", "s": "evita ser<br>fagocitada", "c": "d", "x": 99.5, "y": 8, "ax": 95, "ay": 29, "al": "r"}, {"n": "⑪", "t": "Neutrófilo", "s": "fagocita<br>más", "c": "i", "x": 0.5, "y": 91, "ax": 26, "ay": 62, "al": "l"}, {"n": "⑪", "t": "Tufsina", "s": "estimula la<br>fagocitosis", "c": "i", "x": 24, "y": 91, "ax": 30.6, "ay": 50}, {"n": "⑪", "t": "Seudópodo resbala", "s": "sin anticuerpo y<br>complemento no agarra", "c": "g", "x": 46, "y": 91, "ax": 53.4, "ay": 49}, {"n": "⑫", "t": "Macrófago", "s": "fagocito<br>infectado", "c": "g", "x": 68, "y": 91, "ax": 74.2, "ay": 55}, {"n": "⑫", "t": "Legionella", "s": "se multiplica<br>en el fagosoma", "c": "d", "x": 99.5, "y": 91, "ax": 86.6, "ay": 49, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Tres momentos del mismo neutrófilo: <b class=\"i\">ingestión</b> de una bacteria opsonizada, <b class=\"d\">fagosoma con degranulación y estallido</b>, y <b class=\"d\">NET</b> al morir. El círculo de abajo es un <b>macrófago</b>, el que sí presenta antígenos. Colores: <b class=\"i\">azul</b> = el neutrófilo y sus receptores; <b class=\"d\">rojo</b> = armas microbicidas; <b>gris</b> = microbios y macrófago.", "El neutrófilo es una <mark>célula terminal</mark> ①: fagocita y muere. No presenta antígenos ⑤, <span class=\"cx\">porque</span> en reposo no tiene HLA-II; esa última etapa la hacen el macrófago y la dendrítica.", "Su arma propia es la <mark>mieloperoxidasa</mark> ②⑦ de los gránulos azurófilos: activa cloro y yodo y forma hipohalógenos. <span class=\"cx\">Por eso</span> <b>Yersinia</b> muere en el neutrófilo pero vive dentro del macrófago."], "recordar": "Opsonina = ×1000. Cremallera → fagosoma → degranulación → muerte por <b>O₂</b> (NADPH, ROS), <b>N</b> (L-arginina → NO) o <b>pH</b> (6,5-4). Apoptosis = fin ordenado; NET = red de ADN."}, "numeros": [{"l": "A", "html": "<b>Neutrófilo</b>: <b class=\"n\">70 %</b> de los leucocitos de la sangre; la médula produce <b class=\"n\">7 millones por minuto</b> y guarda una reserva de 10 veces lo que se necesita al día (2,5 × 10⁹/kg).", "rango": null}, {"l": "B", "html": "<b>Opsonización</b>: C3b, iC3b o C4b sobre CR1 y CR3 aumentan la fagocitosis hasta <b class=\"a\">1.000 veces</b>.", "rango": null}, {"l": "C", "html": "<b>pH del fagosoma</b>: cae a <b class=\"n\">6,5–4</b> por metabolismo anaerobio, suficiente por sí solo para matar muchos gérmenes. La azurocidina actúa al máximo a pH 5,7.", "rango": {"min": 3, "max": 7, "unidad": "pH del fagosoma", "zonas": [[4, 6.5, "a", "ácido: mata gérmenes"]], "marcas": [4, 5.7, 6.5], "valor": 5.7}}, {"l": "D", "html": "<b>Vida del neutrófilo</b>: muere por apoptosis si a los <b class=\"n\">7 días</b> no encontró qué fagocitar.", "rango": {"min": 0, "max": 10, "unidad": "días de vida del neutrófilo", "zonas": [[0, 7, "n", "busca qué fagocitar"], [7, 10, "a", "apoptosis"]], "marcas": [7]}}], "escalas": [], "cadena": {"titulo": "Del llamado a la muerte del germen", "subtitulo": "quimiotaxis → reconocimiento y opsonización → fagosoma → degranulación → muerte → final del neutrófilo", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Llamado", "m": "<b>Qué lo atrae:</b> f-MLP bacteriano, C5a, IL-8 (CXCL8) y leucotrieno B4. La quimiotaxis sube el AMP cíclico y polimeriza actina y tubulina.", "pr": "llegan masivamente, primero que nadie <span class=\"lt2\">A</span>; al llegar, la <b>lipoxina</b> frena su propia migración.", "pr_tit": "Produce:", "rf": "Pregunta ① · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Reconocimiento", "m": "<b>Por qué la opsonina:</b> el germen recubierto de anticuerpos o complemento se une a receptores Fc y CR1-CR3; el neumococo exige <b>los dos a la vez</b>.", "pr": "fagocitosis hasta mil veces más eficiente <span class=\"lt2\">B</span>.", "pr_tit": "Produce:", "rf": "Preguntas ③⑥⑪ · punto <span class=\"lt2\">B</span>", "color": "p2"}, {"t": "3. Ingestión", "m": "<b>Cómo:</b> la membrana rodea al germen <b>en cremallera</b>, unión tras unión, hasta cerrarlo en una vacuola.", "pr": "el <span class=\"res\">fagosoma</span>.", "pr_tit": "Produce:", "rf": "Pregunta ⑤", "color": "p3"}, {"t": "4. Degranulación", "m": "<b>Qué pasa:</b> el citoesqueleto lleva los lisosomas y gránulos al fagosoma y se fusionan. Azurófilos: <mark>mieloperoxidasa</mark>, defensinas; secundarios: lisozima, lactoferrina.", "pr": "el fagolisosoma lleno de enzimas.", "pr_tit": "Produce:", "rf": "Preguntas ②⑦", "color": "p4"}, {"t": "5. Muerte del germen", "m": "<b>Tres vías:</b> oxígeno (NADPH → superóxido, H₂O₂, hidroxilo, halógenos), nitrógeno (L-arginina → NO por iNOS, sobre todo en el macrófago) y sin oxígeno (pH <span class=\"lt2\">C</span>, BPI, catepsina G).", "pr": "microbio destruido; los singletes emiten quimioluminiscencia medible.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨ · punto <span class=\"lt2\">C</span>", "color": "p5"}, {"t": "6. Final", "m": "<b>Dos salidas:</b> apoptosis <span class=\"lt2\">D</span> con señales «encuéntrame» y «cómeme», lipoxinas y resolvinas; o NET, red de ADN que atrapa cocos y bacilos.", "pr": "inflamación resuelta. <b>Si falla:</b> gérmenes que evaden (TBC, <b>Histoplasma</b>, <b>Legionella</b>) o déficit enzimático → <span class=\"res\">inmunodeficiencia</span>.", "pr_tit": "Produce:", "rf": "Preguntas ④⑩⑫ · punto <span class=\"lt2\">D</span>", "color": "p1"}], "extra": [{"html": "🫀 <b>Sin bazo</b>: no hay tufsinasa, <span class=\"cx\">así que</span> no se forma <b>tufsina</b> (de la región constante 2 de la IgG), uno de los mayores estimuladores de la fagocitosis ⑪. Riesgo de <mark>septicemia por neumococo y meningococo</mark>.", "k": ""}, {"html": "🕵️ <b>Evasión</b> ⑫: <b>M. tuberculosis</b> impide la acidificación; <b>N. gonorrhoeae</b> reduce los ROS; <b>Legionella</b> se replica en el fagosoma; <b>Histoplasma</b> mantiene pH 6,5; <b>Clostridium</b> bloquea la vacuola; <b>E. coli</b> evita ser fagocitada; <b>Cryptococcus</b> sale por <mark>vomocitosis</mark>.", "k": "k"}], "escaleras": [{"c": "i", "t": "🔢 Las ocho etapas de la fagocitosis", "pasos": ["Sale del vaso al tejido", "busca (patrulla)", "sigue el gradiente (quimiotaxis)", "reconoce (TLR, CR, Fc)", "se adhiere e ingiere en cremallera", "degranula en el fagosoma", "mata al germen", "presenta el antígeno (solo macrófago y dendrítica)"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 4a (neutrófilos: cinética, gránulos, opsonización, apoptosis) y Clase 4b (ocho etapas, mecanismos dependientes del oxígeno y del nitrógeno, otros mecanismos, NETOSIS, regulación y evasión)."}, "preguntas": [{"n": 1, "id": "IN2-001", "c": "i", "tema": "Polimorfonucleares neutrófilos", "pregunta": "Respecto al neutrófilo, es FALSO:", "opciones": ["a. Representa el 70 % de los leucocitos de la sangre.", "b. En condiciones fisiológicas expresa HLA-II y presenta antígenos a los linfocitos T.", "c. Es una célula terminal que muere por lisis tras fagocitar.", "d. Muere por apoptosis si a los siete días no encuentra qué fagocitar.", "e. Su producción la controla el G-CSF, inducido por la IL-17."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. En condiciones fisiológicas no expresa HLA-II; solo lo adquiere bajo estímulos inflamatorios.", "sin_banco": true, "ok": "", "x": "En la imagen el neutrófilo come y <span class=\"cx\">luego</span> <mark>muere</mark> (panel derecho): es una célula terminal. Quien presenta antígenos es el <span class=\"res\">macrófago</span> del círculo.", "truco": "", "veces": 0}, {"n": 2, "id": "IN2-002", "c": "d", "tema": "Membrana, gránulos y funciones del neutrófilo", "pregunta": "Los gránulos primarios o azurófilos del neutrófilo contienen:", "opciones": ["a. Lactoferrina.", "b. Gelatinasa.", "c. Colagenasa.", "d. Mieloperoxidasa.", "e. Fosfatasa alcalina."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Mieloperoxidasa (además de hidrolasa ácida, β-glucuronidasa, fosfatasa ácida, proteínas catiónicas y defensinas).", "sin_banco": true, "ok": "", "x": "Hay <mark>tres tipos de gránulos</mark>: primarios con mieloperoxidasa y defensinas; secundarios con lisozima, fosfatasa alcalina, colagenasa y lactoferrina; terciarios con gelatinasa. La mieloperoxidasa es la que activa los halógenos, <span class=\"cx\">así que</span> es <span class=\"res\">la gran arma del neutrófilo</span>.", "truco": "Primarios = Peroxidasa (azul = azurófilos).", "veces": 0}, {"n": 3, "id": "IN2-003", "c": "d", "tema": "Membrana, gránulos y funciones del neutrófilo", "pregunta": "¿Qué es la opsonización y qué receptores del neutrófilo la aprovechan?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es el recubrimiento del microorganismo por anticuerpos o factores del complemento, que hacen de puente con el fagocito. El neutrófilo usa receptores Fc para inmunoglobulinas y CR1, CR2 y CR3 para C3b, C3bi y C5a.", "sin_banco": true, "ok": "", "x": "Panel izquierdo: la bacteria lleva anticuerpos y fragmentos de complemento pegados; <span class=\"cx\">por eso</span> el neutrófilo la <mark>agarra</mark> con sus receptores <span class=\"res\">Fc y CR</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN2-004", "c": "i", "tema": "Membrana, gránulos y funciones del neutrófilo", "pregunta": "¿Por qué la apoptosis del neutrófilo es necesaria para que la inflamación se resuelva?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque al morir por apoptosis no vierte su arsenal al tejido, libera señales «encuéntrame» y «cómeme» para que los macrófagos lo retiren, y produce lipoxinas y resolvinas, que son antiinflamatorias.", "sin_banco": true, "ok": "", "x": "Si el neutrófilo se rompiera, sus enzimas dañarían el tejido. <span class=\"cx\">En cambio</span>, con la apoptosis <mark>se deja comer</mark> por el macrófago y, <span class=\"cx\">además</span>, fabrica <span class=\"res\">lipoxinas y resolvinas</span> que apagan el proceso. <span class=\"cx\">Así que</span> su muerte ordenada cierra la inflamación.", "truco": "Encuéntrame + cómeme + lipoxina = fin del incendio.", "veces": 0}, {"n": 5, "id": "IN2-005", "c": "i", "tema": "Las ocho etapas de la fagocitosis", "pregunta": "De las ocho etapas de la fagocitosis, ¿cuál NO la cumple el neutrófilo?", "opciones": ["a. Respuesta quimiotáctica.", "b. Reconocimiento del microorganismo.", "c. Adherencia e ingestión.", "d. Degranulación.", "e. Selección y presentación de moléculas antigénicas."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La presentación de antígenos la cumplen macrófagos y células dendríticas, no los neutrófilos.", "sin_banco": true, "ok": "", "x": "El círculo del macrófago muestra la etapa 8, <mark>presentar el antígeno</mark>; el neutrófilo de los paneles <span class=\"res\">no la hace</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN2-006", "c": "i", "tema": "Las ocho etapas de la fagocitosis", "pregunta": "La unión de C3b, iC3b o C4b a los receptores CR1 y CR3 del fagocito incrementa la fagocitosis hasta en:", "opciones": ["a. Mil veces.", "b. Dos veces.", "c. Diez veces.", "d. Cien veces.", "e. Un millón de veces."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Hasta en mil veces.", "sin_banco": true, "ok": "", "x": "La cubierta de opsoninas del panel izquierdo es lo que multiplica la fagocitosis <span class=\"res\">hasta ×1000</span> <span class=\"lt2\">B</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN2-007", "c": "d", "tema": "Las ocho etapas de la fagocitosis", "pregunta": "*Yersinia* es destruida por los granulocitos pero vive cómodamente dentro de los macrófagos, porque el macrófago carece de:", "opciones": ["a. Lisozima.", "b. Receptores tipo Toll.", "c. Mieloperoxidasa.", "d. Óxido nítrico sintetasa inducible.", "e. NADPH oxidasa."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Mieloperoxidasa: el neutrófilo la tiene y el macrófago no.", "sin_banco": true, "ok": "", "x": "Los dos fagocitos <mark>no tienen el mismo arsenal</mark>: la mieloperoxidasa activa cloro y yodo para formar hipohalógenos, y solo la posee el neutrófilo. <span class=\"cx\">Así que</span> algunos gérmenes, como <span class=\"res\"><b>Yersinia</span></b>, mueren en uno y sobreviven en el otro.", "truco": "Sin MPO, el macrófago es hotel de Yersinia.", "veces": 0}, {"n": 8, "id": "IN2-008", "c": "d", "tema": "Mecanismos bactericidas dependientes del nitrógeno", "pregunta": "El óxido nítrico bactericida del macrófago se genera a partir de:", "opciones": ["a. Glucosa, por la vía del NADPH.", "b. Ácido araquidónico, por la ciclooxigenasa.", "c. Oxígeno molecular, por la mieloperoxidasa.", "d. L-arginina, por la óxido nítrico sintetasa inducible.", "e. Hierro libre, por la lactoferrina."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. De la L-arginina, por acción de la iNOS, inducida por IFNγ, TNFα e IL-1; se producen NO y L-citrulina.", "sin_banco": true, "ok": "", "x": "El NO mata <span class=\"cx\">porque</span> se <mark>une al hierro</mark> de enzimas esenciales del microbio, y con el superóxido forma peroxinitrito, aún más tóxico. La iNOS no está siempre: la <span class=\"res\">inducen IFNγ, TNFα e IL-1</span>.", "truco": "ARGinina → NO: «ARGo el nitrógeno».", "veces": 0}, {"n": 9, "id": "IN2-009", "c": "d", "tema": "Mecanismos bactericidas dependientes del oxígeno", "pregunta": "¿Qué es el estallido respiratorio y cómo se aprovecha en el laboratorio?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es el aumento rápido del consumo de oxígeno tras formarse el fagosoma, iniciado por la activación del NADPH, que genera especies reactivas del oxígeno (ROS). Los singletes de oxígeno producen quimioluminiscencia, que se mide para cuantificar la actividad fagocítica.", "sin_banco": true, "ok": "", "x": "Las chispas del fagosoma (panel central) son el <mark>estallido respiratorio</mark>: el NADPH genera ROS y los singletes emiten luz, la <span class=\"res\">quimioluminiscencia</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN2-010", "c": "d", "tema": "Otros mecanismos bactericidas", "pregunta": "¿Qué es la NETOSIS y en qué cuadros clínicos destaca?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Mecanismo que se genera al morir el neutrófilo: forma redes de fibras de ADN (NET) que atrapan bacilos y cocos y los destruyen con péptidos antimicrobianos adheridos. Destaca en neumonía neumocócica, fascitis necrosante por estreptococo del grupo A y apendicitis.", "sin_banco": true, "ok": "", "x": "Panel derecho: el neutrófilo muerto lanza una <mark>red de ADN</mark> que atrapa cocos y bacilos; destaca en <span class=\"res\">neumococo, fascitis necrosante y apendicitis</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN2-011", "c": "g", "tema": "Regulación y evasión de la fagocitosis", "pregunta": "Un joven esplenectomizado tras un accidente presenta, meses después, una sepsis fulminante por neumococo. Según la regulación de la fagocitosis, ¿qué molécula dejó de producirse y por qué el neumococo es tan peligroso?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La tufsina, estimulador potente de la fagocitosis que se origina en la IgG por la tufsinasa del bazo. Además, el neumococo exige la acción simultánea de anticuerpos y complemento para ser fagocitado.", "sin_banco": true, "ok": "", "x": "Sin bazo <mark>no hay tufsinasa</mark>, <span class=\"cx\">así que</span> no se forma tufsina y la fagocitosis queda sin uno de sus mayores estímulos. Como el neumococo es exigente (necesita anticuerpos <span class=\"res\">y</span> complemento a la vez), el esplenectomizado queda expuesto a <span class=\"res\">septicemia por neumococo y meningococo</span>.", "truco": "Sin bazo, sin tufsina: neumococo libre.", "veces": 0}, {"n": 12, "id": "IN2-012", "c": "g", "tema": "Regulación y evasión de la fagocitosis", "pregunta": "Es INCORRECTA la relación entre el patógeno y su estrategia para evadir la fagocitosis:", "opciones": ["a. *Mycobacterium tuberculosis*: detiene la maduración del fagosoma e impide su acidificación.", "b. *Neisseria gonorrhoeae*: reduce la generación de especies reactivas del oxígeno.", "c. *Escherichia coli*: manipula el fagosoma y se replica en su interior.", "d. *Histoplasma capsulatum*: mantiene el pH de la vacuola en 6,5 y bloquea la fusión con lisosomas.", "e. *Cryptococcus neoformans*: escapa de la célula por vomocitosis sin lisarla."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Manipular el fagosoma y replicarse en su interior es la estrategia de *Legionella pneumophila*; *E. coli* evita ser fagocitada.", "sin_banco": true, "ok": "", "x": "Hay <mark>cuatro estrategias</mark> de evasión: impedir la acidificación, evitar la fusión con lisosomas, frenar las moléculas microbicidas o escapar al citoplasma. <span class=\"cx\">Por eso</span> la tuberculosis, la histoplasmosis y la legionelosis persisten aunque la fagocitosis sea normal; <span class=\"res\"><b>Cryptococcus</span></b> suma la vomocitosis.", "truco": "Crypto «vomita» y sale; Legionella se instala.", "veces": 0}], "tabla": {"cab": ["", "🔥 Dependiente del O₂", "🧪 Dependiente del N", "💧 Sin oxígeno"], "filas": [["Parte de", "O₂ y NADPH, porque el estallido aumenta el consumo de oxígeno", "L-arginina, porque la iNOS la convierte", "Gránulos y metabolismo anaerobio"], ["Clave", "Mieloperoxidasa (solo neutrófilo) activa halógenos", "iNOS, inducida por IFNγ, TNFα e IL-1", "pH 6,5-4, BPI, catepsina G, lactoferrina"], ["Mata por", "Superóxido, H₂O₂, hidroxilo, hipohalógenos", "NO que se une al hierro; peroxinitrito", "Ácido, permeabilidad de gramnegativas, falta de hierro"], ["El microbio se defiende", "Dismutasa de superóxido y catalasas", "TBC al inicio, hasta que llega el IFNγ", "<b>Histoplasma</b> mantiene pH 6,5"], ["🔑 Para diferenciar", "<mark>Estallido</mark> + luz (quimioluminiscencia)", "<mark>Arginina → NO</mark> (macrófago)", "<mark>Ácido</mark> y enzimas"]]}, "fuente": "Fuente: tu teoría — Clase 4a (Los fagocitos: neutrófilos) y Clase 4b (El proceso de la fagocitosis y los mecanismos bactericidas), Rojas 17.ª ed., cap. 4."}, {"n": 4, "slug": "Macrofago_y_celulas_linfoides_innatas", "titulo": "Macrófago y células linfoides innatas", "subtitulo": "NK, ILC2, Tγδ y linfocitos B-1: linfocitos que no necesitan aprender", "grupo": "g2", "lema": "La idea: hay células con cara de linfocito que <b>no esperan 7-10 días</b>: actúan de inmediato. La <mark>NK</mark> mata la célula que perdió su HLA (perforinas y granzimas → apoptosis) y, con el macrófago, forma un <b>circuito IL-12 ↔ IFNγ</b> que mata al bacilo tuberculoso. Los <u>B-1</u> traen anticuerpos de fábrica, las ILC2 explican el asma y los Tγδ son centinelas de las mucosas. En la imagen: NK frente a célula sana e infectada, macrófago con NK, y linfocito B con anticuerpos naturales.", "img": "img/04.webp", "mini": "img/mini/04.webp", "ratio": 1.5, "etiquetas": [{"n": "⑥", "t": "NK frenada", "s": "el KIR<br>ve el HLA", "c": "i", "x": 0.8, "y": 5, "ax": 7.8, "ay": 29, "d": "A", "al": "l"}, {"n": "⑥", "t": "HLA propio", "s": "célula<br>sana", "c": "i", "x": 21, "y": 5, "ax": 25.7, "ay": 18.6}, {"n": "①②", "t": "Macrófago", "s": "bacilos que aún<br>no puede matar", "c": "g", "x": 35.5, "y": 5, "ax": 36.5, "ay": 38, "d": "E"}, {"n": "⑩", "t": "IL-12 e IL-23", "s": "del macrófago<br>a la NK", "c": "g", "x": 49.5, "y": 5, "ax": 55.3, "ay": 33}, {"n": "⑨", "t": "NK", "s": "interferón tipo I<br>la potencia", "c": "i", "x": 64.5, "y": 5, "ax": 62, "ay": 46, "d": "B"}, {"n": "⑬", "t": "Linfocito B-1", "s": "IgM de<br>fábrica", "c": "g", "x": 79, "y": 5, "ax": 76.8, "ay": 40, "d": "D"}, {"n": "", "t": "Bazo", "s": "zona<br>marginal", "c": "g", "x": 99.2, "y": 5, "ax": 90, "ay": 22, "al": "r"}, {"n": "⑦", "t": "Sinapsis", "s": "perforinas<br>y granzimas", "c": "d", "x": 0.8, "y": 91, "ax": 15.6, "ay": 63.5, "al": "l"}, {"n": "⑦", "t": "Apoptosis", "s": "célula infectada<br>sin HLA", "c": "d", "x": 23, "y": 91, "ax": 27.3, "ay": 60.5}, {"n": "②⑩", "t": "IFNγ", "s": "vuelve al macrófago:<br>óxido nítrico", "c": "i", "x": 47, "y": 91, "ax": 52, "ay": 60}, {"n": "⑬", "t": "IgM natural", "s": "antes del<br>contacto", "c": "g", "x": 68, "y": 91, "ax": 82, "ay": 56}, {"n": "", "t": "Diplococos", "s": "neumococo,<br>meningococo", "c": "g", "x": 86, "y": 91, "ax": 84, "ay": 69}], "diapos": [{"img": "img/04.webp", "ratio": 1.5, "titulo": "NK, macrófago y linfocito B-1", "texto": "La NK mata a la célula que <mark>perdió su HLA</mark> ⑥⑦; el macrófago y la NK se activan mutuamente con IL-12 e IFNγ ⑩, y el B-1 trae IgM natural ⑬.", "etiquetas": [{"n": "⑥", "t": "NK frenada", "s": "el KIR<br>ve el HLA", "c": "i", "x": 0.8, "y": 5, "ax": 7.8, "ay": 29, "d": "A", "al": "l"}, {"n": "⑥", "t": "HLA propio", "s": "célula<br>sana", "c": "i", "x": 21, "y": 5, "ax": 25.7, "ay": 18.6}, {"n": "①②", "t": "Macrófago", "s": "bacilos que aún<br>no puede matar", "c": "g", "x": 35.5, "y": 5, "ax": 36.5, "ay": 38, "d": "E"}, {"n": "⑩", "t": "IL-12 e IL-23", "s": "del macrófago<br>a la NK", "c": "g", "x": 49.5, "y": 5, "ax": 55.3, "ay": 33}, {"n": "⑨", "t": "NK", "s": "interferón tipo I<br>la potencia", "c": "i", "x": 64.5, "y": 5, "ax": 62, "ay": 46, "d": "B"}, {"n": "⑬", "t": "Linfocito B-1", "s": "IgM de<br>fábrica", "c": "g", "x": 79, "y": 5, "ax": 76.8, "ay": 40, "d": "D"}, {"n": "", "t": "Bazo", "s": "zona<br>marginal", "c": "g", "x": 99.2, "y": 5, "ax": 90, "ay": 22, "al": "r"}, {"n": "⑦", "t": "Sinapsis", "s": "perforinas<br>y granzimas", "c": "d", "x": 0.8, "y": 91, "ax": 15.6, "ay": 63.5, "al": "l"}, {"n": "⑦", "t": "Apoptosis", "s": "célula infectada<br>sin HLA", "c": "d", "x": 23, "y": 91, "ax": 27.3, "ay": 60.5}, {"n": "②⑩", "t": "IFNγ", "s": "vuelve al macrófago:<br>óxido nítrico", "c": "i", "x": 47, "y": 91, "ax": 52, "ay": 60}, {"n": "⑬", "t": "IgM natural", "s": "antes del<br>contacto", "c": "g", "x": 68, "y": 91, "ax": 82, "ay": 56}, {"n": "", "t": "Diplococos", "s": "neumococo,<br>meningococo", "c": "g", "x": 86, "y": 91, "ax": 84, "ay": 69}]}, {"img": "img/04_2.webp", "ratio": 1.5, "titulo": "Macrófagos: M1, M2 y residentes", "texto": "Los Møs-2 son <mark>antiinflamatorios y cicatrizantes</mark> ③; el macrófago fijo cambia de nombre según el tejido: Kupffer, alveolar, microglía, osteoclasto ④.", "etiquetas": [{"n": "③", "t": "Mø-1 activado", "s": "proinflamatorio:<br>mata", "c": "d", "x": 0.5, "y": 8, "ax": 11, "ay": 24, "d": "E", "al": "l"}, {"n": "③", "t": "Citoquinas", "s": "inflamatorias", "c": "d", "x": 22, "y": 8, "ax": 26, "ay": 35}, {"n": "④", "t": "Kupffer", "s": "macrófago<br>del hígado", "c": "i", "x": 38, "y": 8, "ax": 39, "ay": 47}, {"n": "④", "t": "Alveolar", "s": "macrófago<br>del pulmón", "c": "i", "x": 55, "y": 8, "ax": 55.3, "ay": 46}, {"n": "④", "t": "Microglía", "s": "refractaria a señales<br>proinflamatorias", "c": "i", "x": 74, "y": 8, "ax": 71.6, "ay": 47}, {"n": "④", "t": "Osteoclasto", "s": "multinucleado:<br>reabsorbe hueso", "c": "i", "x": 99.5, "y": 8, "ax": 89.8, "ay": 38, "al": "r"}, {"n": "③", "t": "Mø-2", "s": "antiinflamatorio<br>y cicatrizante", "c": "i", "x": 0.5, "y": 91, "ax": 16, "ay": 52, "al": "l"}, {"n": "③", "t": "IL-10, TGFβ-1, PDGF", "s": "frenan y<br>reparan", "c": "i", "x": 22, "y": 91, "ax": 24.7, "ay": 54.7}, {"n": "③", "t": "Capilar nuevo", "s": "angiogénesis:<br>cicatriza", "c": "g", "x": 40, "y": 91, "ax": 30.6, "ay": 68}]}, {"img": "img/04_3.webp", "ratio": 1.5, "titulo": "ADCC de la NK e ILC2 en el asma", "texto": "Con <b>CD16</b> la NK mata células cubiertas de IgG ⑧; el epitelio dañado activa la <mark>ILC2</mark>, que con IL-5 e IL-13 da eosinofilia, moco y broncoespasmo ⑪.", "etiquetas": [{"n": "⑧", "t": "Célula NK", "s": "mata sin reconocer<br>el antígeno", "c": "i", "x": 0.5, "y": 8, "ax": 8.5, "ay": 30, "al": "l"}, {"n": "⑧", "t": "CD16", "s": "receptor Fcγ III<br>para IgG", "c": "i", "x": 20, "y": 8, "ax": 22.8, "ay": 29}, {"n": "⑧", "t": "IgG", "s": "cubre a la<br>célula blanco", "c": "g", "x": 37, "y": 8, "ax": 40.4, "ay": 25.4}, {"n": "⑪", "t": "Epitelio dañado", "s": "libera IL-25,<br>IL-33 y TSLP", "c": "d", "x": 58, "y": 8, "ax": 65, "ay": 37}, {"n": "⑪", "t": "Moco", "s": "hipersecreción", "c": "d", "x": 77, "y": 8, "ax": 81.4, "ay": 28}, {"n": "⑪", "t": "Caliciformes", "s": "hiperplasia<br>por IL-13", "c": "d", "x": 99.5, "y": 8, "ax": 87.2, "ay": 37, "al": "r"}, {"n": "⑧", "t": "Poros", "s": "perforinas: entran<br>las granzimas", "c": "d", "x": 12, "y": 91, "ax": 31.3, "ay": 45}, {"n": "⑧", "t": "Célula blanco", "s": "cubierta de IgG:<br>muere (ADCC)", "c": "d", "x": 32, "y": 91, "ax": 42.3, "ay": 55}, {"n": "⑪", "t": "Eosinófilos", "s": "atraídos<br>por la IL-5", "c": "d", "x": 52, "y": 91, "ax": 58.6, "ay": 60.5}, {"n": "⑪", "t": "ILC2", "s": "ayudadora innata:<br>IL-5 e IL-13", "c": "i", "x": 72, "y": 91, "ax": 69, "ay": 53.7}, {"n": "⑪", "t": "Músculo liso", "s": "broncoespasmo", "c": "d", "x": 99.5, "y": 91, "ax": 89.8, "ay": 63.5, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Tres escenas: <b class=\"i\">NK</b> ante una célula sana (arriba) y una infectada (abajo); <b class=\"i\">NK</b> con un <b>macrófago</b> lleno de bacilos; y un <b>linfocito B</b> que libera anticuerpos sobre diplococos. Colores: <b class=\"i\">azul</b> = NK y sus receptores; <b class=\"d\">rojo</b> = armas y muerte celular; <b>gris</b> = macrófago, linfocitos B y microbios.", "La NK <mark>pesa dos señales</mark> ⑥: los KAR la empujan a matar y los KIR la frenan al ver HLA-A, B y C. <span class=\"cx\">Por eso</span> respeta la célula sana y mata a la que <span class=\"res\">perdió su HLA</span> (virus, tumor) ⑦.", "El macrófago, a diferencia del neutrófilo, <mark>no muere</mark> al fagocitar ① y cambia según el tejido ③④. En la tuberculosis <span class=\"cx\">primero</span> es refugio del bacilo, hasta que el IFNγ le enseña a producir óxido nítrico ②⑩."], "recordar": "NK: <b>KIR frena, KAR acelera</b>; perforina abre, granzima corta el ADN; CD16 = ADCC. Macrófago IL-12 → NK IFNγ → macrófago NO. ILC2: IL-5 e IL-13 (asma). Tγδ: IL-17. B-1: IgM de fábrica."}, "numeros": [{"l": "A", "html": "<b>NK</b>: <b class=\"n\">5–15 %</b> de los linfocitos de la sangre, pero <b class=\"a\">70 %</b> de las células linfoides de la placenta.", "rango": {"min": 0, "max": 100, "unidad": "% de los linfocitos", "zonas": [[5, 15, "n", "NK en sangre"]], "marcas": [5, 15, 70], "valor": 70}}, {"l": "B", "html": "<b>Interferones tipo I</b>: aumentan la actividad microbicida de la NK hasta <b class=\"a\">100 veces</b>.", "rango": null}, {"l": "C", "html": "<b>Tγδ</b>: <b class=\"b\">1–5 %</b> de los linfocitos de sangre periférica; <b>iNKT</b>: 0,1-0,2 % de los T.", "rango": {"min": 0, "max": 10, "unidad": "% de los linfocitos de sangre", "zonas": [[1, 5, "b", "Tγδ"]], "marcas": [1, 5]}}, {"l": "D", "html": "<b>B-1</b>: <b class=\"a\">50 %</b> de los linfocitos B en la vida intrauterina, solo <b class=\"b\">3 %</b> después de nacer. Los B de zona marginal son el 5 % de los B del bazo.", "rango": null}, {"l": "E", "html": "<b>Monocito</b>: <b class=\"n\">10–15 μm</b> (el leucocito más grande); <b>macrófago</b>: <b class=\"n\">15–80 μm</b>; los Mon-1 viven unos 60 días.", "rango": {"min": 0, "max": 80, "unidad": "μm de diámetro", "zonas": [[10, 15, "n", "monocito"], [15, 80, "m", "macrófago"]], "marcas": [10, 15, 80]}}], "escalas": [], "cadena": {"titulo": "De la célula alterada a su muerte", "subtitulo": "señal de peligro → reconocimiento innato → mecanismo de muerte → cooperación → resultado (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Señal de peligro", "m": "<b>Qué pasa:</b> una célula infectada por virus o transformada <b>pierde su HLA</b> o se estresa; un macrófago fagocita un bacilo que no puede destruir.", "pr": "la célula ya no muestra el «carné» de lo propio.", "pr_tit": "Produce:", "rf": "Preguntas ②⑥", "color": "p1"}, {"t": "2. Reconocimiento", "m": "<b>Por qué la NK sabe:</b> el <mark>KIR</mark> ve HLA-A, B y C y frena; sin HLA solo queda la señal del <b>KAR</b>. Por CD16 reconoce también células cubiertas de IgG (ADCC).", "pr": "decide matar en minutos, sin aprendizaje.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑧ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Muerte de la célula blanco", "m": "<b>Cómo:</b> sinapsis → <mark>perforinas</mark> abren canales → <mark>granzimas</mark> (A, B, H, K, M) entran, llegan al núcleo y fragmentan el ADN.", "pr": "<span class=\"res\">apoptosis</span> de la célula blanco, sin inflamación.", "pr_tit": "Produce:", "rf": "Pregunta ⑦", "color": "p3"}, {"t": "4. Cooperación con el macrófago", "m": "<b>Circuito:</b> el macrófago produce IL-12 e IL-23 → la NK produce IFNγ → el macrófago induce la iNOS. Los interferones tipo I potencian a la NK <span class=\"lt2\">B</span>.", "pr": "el macrófago fabrica óxido nítrico y mata la micobacteria.", "pr_tit": "Produce:", "rf": "Preguntas ②⑩ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Otras células innatas", "m": "<b>ILC2:</b> IL-25, IL-33 y TSLP → IL-5 (eosinofilia) e IL-13 (moco, broncoconstricción). <b>Tγδ</b> <span class=\"lt2\">C</span>: centinelas, mayores productores de IL-17. <b>B-1</b> <span class=\"lt2\">D</span>: IgM natural antes del contacto.", "pr": "respuesta inmediata en mucosas, piel, pleura, peritoneo y bazo.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑪⑫⑬ · puntos <span class=\"lt2\">C</span><span class=\"lt2\">D</span>", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Consecuencias:</b> carencia congénita de NK → infecciones repetidas por bacterias y virus; ILC2 desreguladas con IL-33 y TGF → fibrosis pulmonar.", "pr": "sin bazo (sin B de zona marginal) → <span class=\"res\">sepsis fulminante</span> por <b>S. pneumoniae</b>, <b>H. influenzae</b> o <b>N. meningitidis</b>.", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑪", "color": "p1"}], "extra": [{"html": "🧩 <b>Clasificación de 2013</b> ⑤: ILC-1 = NK e iNKT; ILC-2 = ayudadoras innatas; ILC-3 = Tγδ y LTi; B-1 y B de zona marginal quedan fuera. El propio texto dice que <mark>no es completa ni clara</mark>. Las <b>LTi</b> forman ganglios, placas de Peyer y folículos en el embrión.", "k": ""}, {"html": "🏠 <b>Macrófago según el tejido</b> ③④: Møs-1 atacan (TNF, IL-12, IL-23); Møs-2 calman y reparan (IL-10, TGFβ-1, PDGF); Kupffer en el hígado; alveolares aeróbicos; <mark>microglia refractaria a la inflamación</mark>; osteoclastos; sinoviales tipo A. Su carencia en la zona marginal del bazo se asocia a lupus.", "k": "k"}], "escaleras": [{"c": "d", "t": "🦠 Del bacilo escondido al bacilo muerto", "pasos": ["El macrófago fagocita el bacilo tuberculoso", "no lo destruye: el bacilo se multiplica dentro", "el macrófago libera IL-12 e IL-23", "NK (y luego linfocitos T) producen IFNγ", "iNOS → óxido nítrico: micobacteria destruida"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 4a (monocitos, macrófagos, subpoblaciones y sistema reticuloendotelial) y Clase 5 (NK, iNKT, ILC2, Tγδ, LTi, B-1 y B de zona marginal)."}, "preguntas": [{"n": 1, "id": "IN2-013", "c": "g", "tema": "Monocitos y macrófagos", "pregunta": "Respecto a monocitos y macrófagos, es FALSO:", "opciones": ["a. El monocito es el leucocito de mayor tamaño, de 10 a 15 μm.", "b. Los monocitos Mon-1 (CXCR1) patrullan los tejidos de forma constitutiva.", "c. Los monocitos Mon-2 (CCR2) solo migran cuando los convocan quimioquinas del tejido.", "d. El macrófago puede fusionarse y formar células gigantes multinucleadas.", "e. El macrófago, igual que el neutrófilo, muere al cumplir su función fagocitaria."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. El macrófago no muere al fagocitar: reconstruye su arsenal enzimático y conserva la capacidad de reproducirse en los tejidos.", "sin_banco": true, "ok": "", "x": "El macrófago <mark>supera al neutrófilo</mark> en dos cosas: no muere al fagocitar y puede reproducirse en los tejidos. <span class=\"cx\">Por eso</span> puede atacar <span class=\"res\">una y otra vez</span>; <span class=\"cx\">en cambio</span>, el neutrófilo es una célula terminal.", "truco": "Macrófago = soldado de carrera; neutrófilo = kamikaze.", "veces": 0}, {"n": 2, "id": "IN2-014", "c": "g", "tema": "Monocitos y macrófagos", "pregunta": "En la primoinfección tuberculosa, el macrófago fagocita el bacilo pero no lo destruye y lo deja reproducirse en su interior. ¿Qué señal revierte esta situación y cómo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El IFN-γ que producen los linfocitos ya activados (y las NK): «enseña» al macrófago a producir óxido nítrico, con el que sí destruye la micobacteria.", "sin_banco": true, "ok": "", "x": "Escena central: el macrófago está lleno de bacilos que <mark>no puede matar</mark> hasta que le llega IFNγ; <span class=\"cx\">entonces</span> produce <span class=\"res\">óxido nítrico</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN2-015", "c": "g", "tema": "Subpoblaciones de macrófagos", "pregunta": "Los macrófagos Møs-2 se caracterizan por:", "opciones": ["a. Producir TNF, IL-12 e IL-23 y atacar bacterias y tumores.", "b. Suprimir la inmunidad antitumoral y favorecer el crecimiento del tumor.", "c. Ser refractarios a las señales proinflamatorias para proteger a las neuronas.", "d. Producir IL-10, TGFβ-1 y PDGF: son antiinflamatorios, cicatrizantes e inducen resistencia a la insulina.", "e. Participar en la artritis reumatoide, la enfermedad de Crohn y la esclerosis múltiple."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los Møs-2 son antiinflamatorios (IL-10), cicatrizantes (TGFβ-1, PDGF) e inducen resistencia a la insulina en el tejido adiposo.", "sin_banco": true, "ok": "", "x": "Hay <mark>dos caras</mark> del macrófago: los Møs-1 atacan (TNF, IL-12, IL-23) y participan en artritis reumatoide, Crohn y esclerosis múltiple; <span class=\"cx\">en cambio</span>, los Møs-2 <span class=\"res\">calman y reparan</span>. Los asociados a tumores (TAM) suprimen la inmunidad antitumoral, y la microglia es refractaria a la inflamación.", "truco": "Møs-1 = guerra; Møs-2 = reconstrucción.", "veces": 0}, {"n": 4, "id": "IN2-016", "c": "g", "tema": "Sistema reticuloendotelial", "pregunta": "Relación correcta entre la variedad fija del sistema reticuloendotelial y su característica:", "opciones": ["a. Células de Kupffer: viven en el alvéolo pulmonar.", "b. Microglia: refractaria a las señales proinflamatorias para no dañar las neuronas.", "c. Macrófagos peritoneales: metabolismo aeróbico.", "d. Osteoclastos: células sinoviales tipo A.", "e. Macrófagos alveolares: metabolismo anaerobio."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La microglia del sistema nervioso es refractaria a las señales proinflamatorias.", "sin_banco": true, "ok": "", "x": "El macrófago <mark>se adapta al tejido</mark> donde vive: Kupffer en los sinusoides hepáticos, alveolares con metabolismo aeróbico (10-15 millones por gramo de pulmón), peritoneales anaerobios. En el cerebro, la microglia evita inflamar, <span class=\"cx\">así que</span> <span class=\"res\">protege a las neuronas</span>.", "truco": "Microglia = macrófago con guantes de seda.", "veces": 0}, {"n": 5, "id": "IN2-017", "c": "g", "tema": "Panorama general y clasificación", "pregunta": "Según la clasificación propuesta en 2013 de las células linfoides innatas, es correcto:", "opciones": ["a. ILC-1 agrupa a las NK y las iNKT.", "b. ILC-2 agrupa a los linfocitos Tγδ y las LTi.", "c. ILC-3 agrupa a los linfocitos B-1.", "d. Los linfocitos B de zona marginal pertenecen a ILC-1.", "e. El texto la considera completa y clara."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. ILC-1: NK e iNKT; ILC-2: ayudadoras innatas; ILC-3: Tγδ y LTi. Los B-1 y los B de zona marginal quedan fuera.", "sin_banco": true, "ok": "", "x": "Son <mark>siete células</mark> con aspecto de linfocito que responden sin aprendizaje. La propuesta de 2013 las agrupa en ILC-1, ILC-2 e ILC-3, pero el propio texto advierte que <span class=\"res\">no es completa ni clara y se presta a confusión</span>.", "truco": "1 = matan (NK, iNKT); 2 = ayudan (ILC2); 3 = Tγδ y LTi.", "veces": 0}, {"n": 6, "id": "IN2-018", "c": "i", "tema": "Células asesinas naturales (NK)", "pregunta": "Una célula NK no destruye las células propias sanas porque:", "opciones": ["a. Sus receptores KAR reconocen el HLA propio y se apagan.", "b. Carece de perforinas hasta que es activada por anticuerpos.", "c. Solo reconoce bacterias extracelulares.", "d. Sus receptores KIR detectan HLA-A, HLA-B y HLA-C de la célula normal y emiten una señal inhibitoria.", "e. Necesita que un macrófago le presente el antígeno."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los KIR detectan el HLA de clase I propio y cancelan la muerte; una célula que pierde el HLA queda desprotegida.", "sin_banco": true, "ok": "", "x": "Escena izquierda: la NK de arriba ve el HLA de la célula sana y <mark>se frena</mark> (KIR); la de abajo no ve HLA y <span class=\"res\">ataca</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN2-019", "c": "i", "tema": "Células asesinas naturales (NK)", "pregunta": "Describe paso a paso la citotoxicidad directa de la célula NK.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La NK forma una sinapsis con la célula blanco; secreta perforinas que forman canales en su membrana; por ellos entran las granzimas (A, B, H, K, M), que llegan al núcleo, fragmentan el ADN e inducen apoptosis.", "sin_banco": true, "ok": "", "x": "La amplia zona de contacto de la escena izquierda es la <mark>sinapsis</mark>; por ella pasan perforinas y granzimas, y <span class=\"cx\">por eso</span> la célula blanco muestra <span class=\"res\">apoptosis</span> (vesículas y núcleo roto).", "truco": "", "veces": 0}, {"n": 8, "id": "IN2-020", "c": "i", "tema": "Células asesinas naturales (NK)", "pregunta": "La NK participa en la inmunidad adquirida atacando células recubiertas de anticuerpos (ADCC). ¿Qué molécula lo permite?", "opciones": ["a. CD56.", "b. CD16, receptor Fcγ III para IgG.", "c. CD4.", "d. KIR.", "e. CD1d."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. CD16 (receptor Fcγ III para IgG): permite la citotoxicidad mediada por anticuerpos.", "sin_banco": true, "ok": "", "x": "Por medio de <mark>CD16</mark> la NK reconoce la porción Fc de la IgG pegada a una célula, <span class=\"cx\">así que</span> mata células «marcadas» por anticuerpos. Es un <span class=\"res\">puente entre la inmunidad innata y la adquirida</span>; varios anticuerpos monoclonales contra el cáncer actúan activando las NK.", "truco": "CD16: la NK lee la IgG pegada a la célula.", "veces": 0}, {"n": 9, "id": "IN2-021", "c": "i", "tema": "Células asesinas naturales (NK)", "pregunta": "Respecto a las células NK, es FALSO:", "opciones": ["a. Se originan del progenitor linfoide común por IL-3, IL-7 e IL-15.", "b. Llegan a ser el 70 % de las células linfoides de la placenta.", "c. Los interferones tipo I aumentan su actividad hasta 100 veces.", "d. Destruyen algunas células dendríticas que reconocieron antígenos propios.", "e. Representan el 50 % de los linfocitos de la sangre."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. En sangre son del 5 % al 15 % del total de linfocitos.", "sin_banco": true, "ok": "", "x": "Las NK son <mark>pocas en sangre (5-15 %)</mark> pero muy abundantes en la decidua, donde forman el 70 % de las linfoides de la placenta y protegen al feto. Los interferones tipo I multiplican <span class=\"res\">hasta 100 veces</span> su poder.", "truco": "NK: 5-15 en sangre, 70 en placenta, ×100 con interferón.", "veces": 0}, {"n": 10, "id": "IN2-022", "c": "i", "tema": "Células asesinas naturales (NK)", "pregunta": "¿Cómo se activan mutuamente la NK y el macrófago frente al bacilo tuberculoso?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El macrófago produce IL-12 e IL-23, que estimulan a la NK a producir IFNγ; este IFNγ activa al macrófago para destruir las micobacterias fagocitadas.", "sin_banco": true, "ok": "", "x": "Las gotitas que van y vienen en la escena central son el circuito: <mark>IL-12/IL-23</mark> del macrófago a la NK e <mark>IFNγ</mark> de vuelta, que <span class=\"res\">activa al macrófago</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN2-023", "c": "g", "tema": "Células ayudadoras innatas (ILC2)", "pregunta": "Una paciente asmática presenta eosinofilia, hipersecreción de moco y broncoespasmo. El daño del epitelio respiratorio libera IL-25, IL-33 y TSLP. ¿Qué célula innata se activa y qué citoquinas explican el cuadro?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Las ILC2 (ayudadoras innatas), activadas sobre todo por IL-25: producen IL-5, que induce eosinofilia, e IL-13, que causa hiperplasia de células caliciformes, más moco y contracción del músculo liso bronquial.", "sin_banco": true, "ok": "", "x": "Las ILC2 producen citoquinas <mark>tipo 2</mark> que antes se creían exclusivas de los Th2. La IL-5 llama eosinófilos y la IL-13 produce moco y broncoconstricción; si la regulación falla, IL-33 con TGF lleva a <span class=\"res\">fibrosis pulmonar</span>.", "truco": "ILC2: IL-5 eosinófilos, IL-13 moco.", "veces": 0}, {"n": 12, "id": "IN2-024", "c": "g", "tema": "Linfocitos Tγδ", "pregunta": "Respecto a los linfocitos Tγδ, es correcto:", "opciones": ["a. Son los mayores productores de IL-17.", "b. Requieren moléculas coestimuladoras para activarse.", "c. Guardan memoria inmunológica.", "d. Representan el 50 % de los linfocitos de la sangre.", "e. Reconocen antígenos peptídicos presentados por HLA."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Son los mayores productores de IL-17; reconocen lípidos en moléculas CD1, no péptidos.", "sin_banco": true, "ok": "", "x": "Los Tγδ son <mark>centinelas</mark> de mucosas, piel e hígado: reconocen PAMPs y lípidos sin que nadie se los presente. <span class=\"cx\">Por eso</span> responden antes que los Tαβ, sin coestimulación ni memoria; en sangre son solo <span class=\"res\">1-5 %</span>.", "truco": "γδ = guardias de la puerta, gritan IL-17.", "veces": 0}, {"n": 13, "id": "IN2-025", "c": "g", "tema": "Linfocitos B de la inmunidad innata", "pregunta": "¿Por qué los linfocitos B-1 producen anticuerpos contra un patógeno con el que nunca tuvieron contacto?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque nacen programados para producir anticuerpos naturales, sobre todo IgM, contra pocos antígenos de los microbios más frecuentes de las vías altas (neumococo, meningococo). Son de baja afinidad, pero están listos antes del primer encuentro.", "sin_banco": true, "ok": "", "x": "Escena derecha: el linfocito B libera anticuerpos sobre diplococos sin haberlos visto antes; son <mark>IgM naturales</mark> de los B-1, listas <span class=\"res\">antes del primer contacto</span>.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "🗡️ NK", "🌬️ ILC2", "🛡️ Tγδ", "🧫 B-1"], "filas": [["Origen", "Médula: IL-3, IL-7, IL-15", "Médula: RORα, GATA3", "Timocitos doble positivos", "Hígado embrionario"], ["Reconoce", "Falta de HLA (KIR/KAR); IgG por CD16", "IL-25, IL-33, TSLP", "Lípidos en CD1; PAMP; MICA", "Pocos antígenos frecuentes"], ["Produce", "Perforinas, granzimas, IFNγ", "IL-5 e IL-13", "IL-17 (la que más)", "IgM natural"], ["Clínica", "Carencia: infecciones; 70 % de la placenta", "Asma; fibrosis pulmonar", "Mucosas, piel, hígado", "Neumococo, meningococo"], ["🔑 Para diferenciar", "<mark>Mata</mark> sin aprender", "<mark>Ayuda</mark> tipo 2", "<mark>Centinela</mark> IL-17", "<mark>Anticuerpo de fábrica</mark>"]]}, "fuente": "Fuente: tu teoría — Clase 4a (monocitos y macrófagos) y Clase 5 (Células linfoides de la inmunidad innata), Rojas 17.ª ed., caps. 4-5."}, {"n": 5, "slug": "Sistema_del_complemento", "titulo": "Sistema del complemento", "subtitulo": "tres vías que convergen en el C3: lisis, opsonización e inflamación", "grupo": "g3", "lema": "La idea: el complemento son unas <b>37 proteínas</b> del plasma que circulan inactivas y se encienden en cascada sobre la superficie del microbio. Tres vías lo prenden —<mark>clásica</mark> (anticuerpo), <mark>de las lectinas</mark> (manosa) y <mark>alterna</mark> (C3 espontáneo)— y todas llegan al mismo punto: <u>la convertasa del C3</u>. De ahí salen tres armas: el <b>poro</b> que revienta al microbio, el <b>C3b</b> que lo marca para el fagocito y las <b>anafilotoxinas</b> que encienden la inflamación. Importa porque, si falta un regulador, el complemento ataca lo propio (hemoglobinuria paroxística nocturna, edema angioneurótico) y, si falta el C1q, aparece el <b>lupus</b>. En la imagen verás de izquierda a derecha: la bacteria con las tres vías, el poro en su membrana y el macrófago comiéndose una bacteria opsonizada junto a un mastocito que se degranula.", "img": "img/05.webp", "mini": "img/mini/05.webp", "ratio": 1.5, "etiquetas": [{"n": "①②⑨⑩", "t": "C1q + anticuerpo", "s": "vía clásica:<br>C4bC2a", "c": "i", "x": 0.5, "y": 6, "ax": 10.2, "ay": 30, "al": "l"}, {"n": "", "t": "MBL + manosa", "s": "vía de las lectinas:<br>sin anticuerpos", "c": "i", "x": 31, "y": 6, "ax": 21.5, "ay": 31}, {"n": "③④", "t": "C3b solo", "s": "vía alterna:<br>C3bBb + properdina", "c": "i", "x": 48, "y": 6, "ax": 32.5, "ay": 46.5}, {"n": "", "t": "C3b = opsonina", "s": "marca a la bacteria<br>para el fagocito", "c": "d", "x": 72, "y": 6, "ax": 84, "ay": 52, "d": "B"}, {"n": "⑤", "t": "Mastocito", "s": "C3a y C5a lo degranulan:<br>vaso permeable, edema", "c": "d", "x": 99.5, "y": 6, "ax": 93.5, "ay": 32, "d": "C", "al": "r"}, {"n": "⑤⑪", "t": "Fragmentos libres", "s": "C3a, C4a, C5a:<br>anafilotoxinas", "c": "d", "x": 0.5, "y": 91, "ax": 4, "ay": 70, "d": "D", "al": "l"}, {"n": "④⑧", "t": "Bacteria", "s": "sin factor H<br>ni CD55/CD59", "c": "g", "x": 25, "y": 91, "ax": 24, "ay": 62}, {"n": "⑥", "t": "Poro C5b-C9", "s": "entra agua:<br>estallido osmótico", "c": "d", "x": 47, "y": 91, "ax": 49.5, "ay": 44, "d": "A"}, {"n": "", "t": "Macrófago", "s": "fagocita lo<br>opsonizado", "c": "g", "x": 66, "y": 91, "ax": 70, "ay": 46}, {"n": "⑦", "t": "Receptor CR1/CR3", "s": "une C3b e iC3b;<br>CR2 activa al LsB", "c": "d", "x": 99.5, "y": 91, "ax": 79.5, "ay": 59, "al": "r"}], "diapos": [{"img": "img/05.webp", "ratio": 1.5, "titulo": "Tres vías que convergen en el C3", "texto": "Clásica (C1q + anticuerpo), lectinas (MBL) y alterna (C3b solo) terminan en <mark>lisis, opsonización e inflamación</mark> ①–⑪.", "etiquetas": [{"n": "①②⑨⑩", "t": "C1q + anticuerpo", "s": "vía clásica:<br>C4bC2a", "c": "i", "x": 0.5, "y": 6, "ax": 10.2, "ay": 30, "al": "l"}, {"n": "", "t": "MBL + manosa", "s": "vía de las lectinas:<br>sin anticuerpos", "c": "i", "x": 31, "y": 6, "ax": 21.5, "ay": 31}, {"n": "③④", "t": "C3b solo", "s": "vía alterna:<br>C3bBb + properdina", "c": "i", "x": 48, "y": 6, "ax": 32.5, "ay": 46.5}, {"n": "", "t": "C3b = opsonina", "s": "marca a la bacteria<br>para el fagocito", "c": "d", "x": 72, "y": 6, "ax": 84, "ay": 52, "d": "B"}, {"n": "⑤", "t": "Mastocito", "s": "C3a y C5a lo degranulan:<br>vaso permeable, edema", "c": "d", "x": 99.5, "y": 6, "ax": 93.5, "ay": 32, "d": "C", "al": "r"}, {"n": "⑤⑪", "t": "Fragmentos libres", "s": "C3a, C4a, C5a:<br>anafilotoxinas", "c": "d", "x": 0.5, "y": 91, "ax": 4, "ay": 70, "d": "D", "al": "l"}, {"n": "④⑧", "t": "Bacteria", "s": "sin factor H<br>ni CD55/CD59", "c": "g", "x": 25, "y": 91, "ax": 24, "ay": 62}, {"n": "⑥", "t": "Poro C5b-C9", "s": "entra agua:<br>estallido osmótico", "c": "d", "x": 47, "y": 91, "ax": 49.5, "ay": 44, "d": "A"}, {"n": "", "t": "Macrófago", "s": "fagocita lo<br>opsonizado", "c": "g", "x": 66, "y": 91, "ax": 70, "ay": 46}, {"n": "⑦", "t": "Receptor CR1/CR3", "s": "une C3b e iC3b;<br>CR2 activa al LsB", "c": "d", "x": 99.5, "y": 91, "ax": 79.5, "ay": 59, "al": "r"}]}, {"img": "img/05_2.webp", "ratio": 1.5, "titulo": "Factor H, CD55 y CD59: quién se salva", "texto": "Sin CD55 ni CD59 el eritrocito se lisa: <mark>hemoglobinuria paroxística nocturna</mark> ⑧ <span class=\"lt2\">A</span>; <span class=\"cx\">en cambio</span>, el ácido siálico y el factor H protegen a la célula propia ④.", "etiquetas": [{"n": "⑧", "t": "Complemento", "s": "rebota en el<br>eritrocito sano", "c": "g", "x": 0.5, "y": 8, "ax": 6.2, "ay": 25, "al": "l"}, {"n": "⑧", "t": "CD55 y CD59", "s": "anclados por GPI:<br>protegen", "c": "i", "x": 23, "y": 8, "ax": 24.7, "ay": 23}, {"n": "④", "t": "Ácido siálico", "s": "sube la afinidad<br>por el factor H", "c": "i", "x": 52, "y": 8, "ax": 56.6, "ay": 32}, {"n": "④", "t": "Factor H", "s": "impide armar<br>la convertasa", "c": "i", "x": 74, "y": 8, "ax": 80.7, "ay": 21}, {"n": "④", "t": "C3b frenado", "s": "no se pega a<br>la célula propia", "c": "g", "x": 99.5, "y": 8, "ax": 91.8, "ay": 20.5, "al": "r"}, {"n": "⑧", "t": "Hemoglobina", "s": "orina oscura<br>al despertar", "c": "d", "x": 0.5, "y": 91, "ax": 6.5, "ay": 72, "al": "l"}, {"n": "⑧", "t": "Poro C5b-C9", "s": "ataque a la<br>membrana sin freno", "c": "d", "x": 22, "y": 91, "ax": 20.2, "ay": 64.5, "d": "A"}, {"n": "⑧", "t": "Eritrocito de la HPN", "s": "sin CD55 ni CD59<br>(PIG-A): se lisa", "c": "d", "x": 41, "y": 91, "ax": 27, "ay": 58}, {"n": "④", "t": "Bacteria", "s": "sin ácido siálico:<br>el C3b se acumula", "c": "d", "x": 66, "y": 91, "ax": 69, "ay": 70}, {"n": "④", "t": "C3b depositado", "s": "opsonina que<br>marca al microbio", "c": "d", "x": 99.5, "y": 91, "ax": 91.8, "ay": 70.3, "al": "r"}]}, {"img": "img/05_3.webp", "ratio": 1.5, "titulo": "Vía clásica y CR2 del linfocito B", "texto": "La IgM, con sus cinco brazos, es la mejor activadora del C1q ②; la convertasa <b>C4bC2a</b> parte el C3 ①; el C3d sobre el CR2 baja el umbral del B <span class=\"lt2\">B</span> ⑦.", "etiquetas": [{"n": "②", "t": "C1q", "s": "seis cabezas sobre<br>el anticuerpo", "c": "d", "x": 0.5, "y": 8, "ax": 19.5, "ay": 21, "al": "l"}, {"n": "①", "t": "C3", "s": "lo parte<br>la convertasa", "c": "g", "x": 27, "y": 8, "ax": 45.6, "ay": 30}, {"n": "", "t": "C3a", "s": "fragmento chico:<br>anafilotoxina", "c": "d", "x": 47, "y": 8, "ax": 59.2, "ay": 36}, {"n": "⑦", "t": "Antígeno", "s": "cubierto<br>de C3d", "c": "g", "x": 68, "y": 8, "ax": 79.4, "ay": 30}, {"n": "⑦", "t": "C3d", "s": "ligando<br>del CR2", "c": "d", "x": 99.5, "y": 8, "ax": 88.5, "ay": 38, "al": "r"}, {"n": "②", "t": "IgM pentamérica", "s": "cinco brazos: la<br>mejor activadora", "c": "i", "x": 0.5, "y": 91, "ax": 14.3, "ay": 40, "al": "l"}, {"n": "", "t": "Bacteria", "s": "superficie<br>activadora", "c": "g", "x": 22, "y": 91, "ax": 21.5, "ay": 62.5}, {"n": "①", "t": "C4bC2a", "s": "convertasa del C3<br>de la vía clásica", "c": "i", "x": 40, "y": 91, "ax": 48, "ay": 52.7}, {"n": "①", "t": "C3b", "s": "se pega:<br>opsonina", "c": "d", "x": 57, "y": 91, "ax": 56.6, "ay": 53.7}, {"n": "⑦", "t": "BCR", "s": "reconoce el<br>antígeno", "c": "i", "x": 73, "y": 91, "ax": 71.6, "ay": 42}, {"n": "⑦", "t": "CR2 (CD21)", "s": "baja el umbral<br>del linfocito B", "c": "i", "x": 99.5, "y": 91, "ax": 91, "ay": 46, "d": "B", "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = cómo se enciende</b> (las tres vías), <b class=\"d\">rojo = qué produce</b> (poro, opsonina, anafilotoxinas), gris = las células y estructuras de referencia.", "<b>Izquierda:</b> el C1q se sienta sobre el anticuerpo (en la imagen, una IgG; la <mark>IgM</mark> es mejor activadora <span class=\"cx\">porque</span> trae cinco sitios en una sola molécula). La MBL reconoce la <b>manosa</b> sin anticuerpo, y el C3b se pega solo a la superficie que <b>no tiene factor H</b>.", "<b>Regla de los fragmentos:</b> el fragmento <mark>mayor (b)</mark> se queda pegado a la membrana y activa al siguiente factor; el <mark>menor (a)</mark> queda libre e inflama. <span class=\"cx\">Por eso</span> C3b y C5b trabajan sobre la bacteria, <span class=\"cx\">en cambio</span> C3a y C5a viajan hasta el mastocito y el vaso.", "<b>Centro y derecha:</b> seis o más C9 forman un tubo por el que entra agua <span class=\"lt2\">A</span>; el macrófago reconoce el C3b con sus receptores CR1 y CR3 <span class=\"lt2\">B</span>."], "recordar": "Tres vías → <b>una</b> convertasa del C3 → tres armas: <b>poro</b> (C5b-C9), <b>opsonina</b> (C3b) e <b>inflamación</b> (C5a > C3a > C4a). El factor H, el CD55 y el CD59 protegen lo propio."}, "numeros": [{"l": "A", "html": "<b>Complejo de ataque</b>: <b class=\"n\">6 o más</b> moléculas de C9 se incrustan en la bicapa y forman el microtúbulo.", "rango": {"min": 0, "max": 12, "unidad": "moléculas de C9 por poro", "zonas": [[6, 12, "n", "6 o más forman el poro"]], "marcas": [6]}}, {"l": "B", "html": "<b>Opsonina</b>: una molécula de iC3b <b class=\"n\">reemplaza a 100</b> de anticuerpo. El CR2 baja el umbral de activación del linfocito B hasta <b class=\"a\">1000 veces</b>.", "rango": null}, {"l": "C", "html": "<b>Anafilotoxinas</b>: el C5a es <b class=\"a\">10 a 20 veces</b> más activo que el C3a; el C4a es el más débil.", "rango": null}, {"l": "D", "html": "<b>Permeabilidad por anafilotoxinas</b>: máxima a los <b class=\"a\">5–10 min</b>, desaparece a la <b class=\"n\">hora</b>. El complemento es el <b class=\"n\">10 %</b> de las proteínas del plasma (unos 3 g/L).", "rango": {"min": 0, "max": 60, "unidad": "minutos tras liberar anafilotoxinas", "zonas": [[5, 10, "a", "permeabilidad máxima"], [10, 60, "m", "va desapareciendo"]], "marcas": [5, 10, 60]}}], "escalas": [], "cadena": {"titulo": "Del microbio al poro", "subtitulo": "estímulo → vías de activación → convertasas → armas → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> un microbio entra; lo cubren anticuerpos (<mark>IgM</mark> o IgG) o la <b>PCR</b>, o expone manosa, o simplemente <b>no tiene factor H</b> ni ácido siálico.", "pr": "se encienden la vía clásica, la de las lectinas o la alterna.", "pr_tit": "Produce:", "rf": "Preguntas ②④⑩", "color": "p1"}, {"t": "2. Reconocimiento", "m": "<b>Por qué:</b> el C1q (con C1r y C1s) se une al anticuerpo; la MBL y las ficolinas activan las <b>MASP</b>; el C3 se hidroliza solo y el C3b se pega a la superficie.", "pr": "se fragmentan C4 y C2 (clásica y lectinas) o se une el factor B (alterna).", "pr_tit": "Produce:", "rf": "Preguntas ①③", "color": "p2"}, {"t": "3. Convertasa del C3", "m": "<b>Qué produce:</b> <mark>C4bC2a</mark> (clásica y lectinas) o <mark>C3bBb</mark> estabilizada por la properdina (alterna) parten el C3: el <b>C3b</b> queda pegado y el <b>C3a</b> sale libre.", "pr": "opsonización (C3b sobre CR1/CR3) y comienza la inflamación.", "pr_tit": "Produce:", "rf": "Preguntas ①③⑦ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Convertasa del C5 y poro", "m": "<b>Qué pasa:</b> el C3b se suma y forma la convertasa del C5. El C5a sale; el C5b se une a C6, C7 y C8, y <mark>6 o más C9</mark> forman un tubo en la bicapa.", "pr": "entra agua: <b>estallido osmótico</b> del microbio.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Inflamación", "m": "<b>Por qué:</b> las anafilotoxinas C5a > C3a > C4a degranulan mastocitos aun sin IgE, liberan aminas vasoactivas y atraen neutrófilos; las <b>kininas</b> dan dolor.", "pr": "edema, vasodilatación y llegada de neutrófilos en minutos.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑪ · punto <span class=\"lt2\">D</span>", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Regulador ausente:</b> sin GPI (CD55, CD59) → <mark>hemoglobinuria paroxística nocturna</mark>; sin inactivador del C1 → edema angioneurótico; sin factor H → SHU atípico. <b>Factor ausente:</b> C1q → lupus en el 95 %; properdina → Neisseria.", "pr": "hemólisis, edema, autoinmunidad o infecciones.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨", "color": "p4"}], "extra": [{"html": "🛡️ <b>Frenos del complemento:</b> inactivador del C1 (también frena las kininas), proteína ligadora de C4, <mark>factor I</mark> (degrada C3b y C4b), <mark>factor H</mark> (impide que el C3b se una al factor B), carboxipeptidasa N (apaga anafilotoxinas), <b>CD46, CD55 y CD59</b> en la membrana propia, y vitronectina y clusterina contra el poro.", "k": ""}, {"html": "💊 <b>Eculizumab</b> (anti-C5): impide formar el complejo de ataque; se usa en la hemoglobinuria paroxística nocturna y en el SHU atípico. En la <b>sepsis</b>, el exceso de C5a paraliza al neutrófilo y causa apoptosis de los linfocitos T.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Del fragmento libre al choque", "pasos": ["C3a y C5a libres en el foco", "mastocito degranulado: <b>histamina</b>", "vasodilatación y edema en 5–10 min", "neutrófilos atraídos por C5a", "<b>sepsis</b>: exceso de C5a paraliza al neutrófilo y daña la coagulación"]}], "html": "", "fuente": "Fuente: tu teoría — clase 6 (vías clásica, de las lectinas y alterna; fase de ataque; receptores, regulación y correlato clínico) y clase 7b (anafilotoxinas, kininas, metaloproteinasas y proteína C reactiva)."}, "preguntas": [{"n": 1, "id": "IN3-001", "c": "i", "tema": "Vía clásica", "pregunta": "En la vía clásica del complemento, la convertasa del C3 es el complejo:", "opciones": ["a. C3bBb", "b. C4bC2a", "c. C4bC2aC3b", "d. C5b-C9", "e. C1qC1rC1s"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. C4bC2a: el C1 activado parte el C4 y el C2, y el complejo C4bC2a parte el C3.", "sin_banco": true, "ok": "", "x": "Es el paso 3 de la cadena: <mark>C4bC2a</mark> parte el C3. Si se le suma un C3b ya es la convertasa del C5; la <b>C3bBb</b> es de la vía alterna. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN3-002", "c": "i", "tema": "Vía clásica", "pregunta": "¿Qué inmunoglobulina es la mejor activadora de la vía clásica del complemento?", "opciones": ["a. IgG4", "b. IgA", "c. IgM", "d. IgE", "e. IgG2"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. IgM, porque tiene cinco sitios de reconocimiento de antígeno en una sola molécula.", "sin_banco": true, "ok": "", "x": "En la imagen el C1q se apoya sobre un anticuerpo (arriba a la izquierda). Una sola <mark>IgM</mark> le ofrece cinco sitios, <span class=\"cx\">en cambio</span> la IgG necesita dos moléculas vecinas. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN3-003", "c": "i", "tema": "Vía alterna", "pregunta": "Respecto a la vía alterna (del properdín), es FALSO:", "opciones": ["a. Es evolutivamente la más antigua.", "b. El C3 se hidroliza espontáneamente por la inestabilidad de un enlace tioéster.", "c. La properdina estabiliza el complejo C3bBb.", "d. Necesita anticuerpos unidos al microbio para iniciarse.", "e. Su activación depende de la ausencia del factor H en la membrana blanco."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Es falso: la vía alterna no necesita anticuerpos; arranca por la hidrólisis espontánea del C3.", "sin_banco": true, "ok": "", "x": "La vía alterna está siempre «encendida» a bajo nivel, <span class=\"cx\">porque</span> el C3 se hidroliza solo y se pega a cualquier superficie. <span class=\"cx\">Luego</span> el factor B y el factor D arman <mark>C3bBb</mark>, que la properdina estabiliza. <span class=\"cx\">Así que</span> <span class=\"res\">no requiere anticuerpos</span>; quien la necesita es la vía clásica.", "truco": "Alterna = «A»utomática: no espera anticuerpos.", "veces": 0}, {"n": 4, "id": "IN3-004", "c": "i", "tema": "Vía alterna", "pregunta": "Si el C3 se hidroliza espontáneamente sobre cualquier superficie, ¿por qué la vía alterna no destruye las células propias?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque su activación depende de la ausencia del factor H. Las células propias portan factor H (y ácido siálico que aumenta su afinidad), que impide armar la convertasa; los microbios, sin él, dejan que la cascada avance.", "sin_banco": true, "ok": "", "x": "El C3b se pega en todos lados (etiqueta «C3b solo»), pero solo avanza donde falta el <mark>factor H</mark>. La bacteria no lo tiene; <span class=\"res\">la célula propia sí</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN3-005", "c": "d", "tema": "Moléculas generadas", "pregunta": "¿Cuál es la anafilotoxina más potente?", "opciones": ["a. C5a", "b. C3a", "c. C4a", "d. C3b", "e. C2b"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. C5a, de 10 a 20 veces más activo que el C3a; el C4a es el menos potente.", "sin_banco": true, "ok": "", "x": "Son los fragmentos libres que van al mastocito (punto Ⓒ): <mark>C5a > C3a > C4a</mark>. El C3b no es anafilotoxina, es opsonina. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN3-006", "c": "d", "tema": "Fase de ataque a la membrana", "pregunta": "El poro del complejo de ataque a la membrana está formado por:", "opciones": ["a. C3b y factor B", "b. C1q, C1r y C1s", "c. MBL y MASP", "d. C4b y C2a", "e. C5b, C6, C7 y C8 con seis o más moléculas de C9 polimerizadas"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. C5b-C8 más seis o más moléculas de C9 que se incrustan en la bicapa y forman un microtúbulo.", "sin_banco": true, "ok": "", "x": "Es el poro del centro de la imagen (punto Ⓐ): C5b-C8 más <mark>seis o más C9</mark>. Por el tubo entra agua y <span class=\"res\">la bacteria revienta</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN3-007", "c": "d", "tema": "Receptores del complemento", "pregunta": "¿Qué ligando reconoce el CR2 (CD21) y qué efecto tiene sobre el linfocito B?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Reconoce C3d, C3dg e iC3b. Disminuye hasta mil veces el umbral de activación del linfocito B, que produce más anticuerpos. Además es el receptor del virus de Epstein-Barr.", "sin_banco": true, "ok": "", "x": "Un antígeno cubierto de C3d estimula a la vez el BCR y el <mark>CR2</mark>; <span class=\"cx\">por eso</span> el linfocito B se activa con mucho menos antígeno. Es el puente entre la inmunidad innata y la adquirida. Como dato clínico, <span class=\"res\">el virus de Epstein-Barr usa el CR2 para entrar al linfocito B</span>.", "truco": "CR2 = «2 llaves»: BCR + C3d.", "veces": 0}, {"n": 8, "id": "IN3-008", "c": "d", "tema": "Correlato clínico", "pregunta": "Varón de 28 años con orina oscura al despertar y anemia hemolítica. La citometría muestra un clon de eritrocitos sin CD55 ni CD59. ¿Cuál es el diagnóstico, su mecanismo y el tratamiento?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Hemoglobinuria paroxística nocturna: una mutación del gen PIG-A impide anclar por GPI el CD55 y el CD59, así que el complemento lisa ese clon de eritrocitos. Se trata con eculizumab (anti-C5).", "sin_banco": true, "ok": "", "x": "La bacteria de la imagen no tiene CD55 ni CD59, <span class=\"cx\">por eso</span> el complemento la ataca. El eritrocito de la <mark>HPN</mark> tampoco los tiene (falta el ancla GPI), <span class=\"cx\">así que</span> <span class=\"res\">se lisa como si fuera un microbio</span>; el eculizumab corta en el C5.", "truco": "", "veces": 0}, {"n": 9, "id": "IN3-009", "c": "d", "tema": "Correlato clínico", "pregunta": "La deficiencia de C1q se asocia con mayor frecuencia a:", "opciones": ["a. Edema angioneurótico hereditario", "b. Lupus eritematoso sistémico", "c. Síndrome hemolítico urémico atípico", "d. Infecciones por Neisseria meningitidis", "e. Deficiencia de adhesividad leucocitaria tipo I"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Lupus eritematoso sistémico: lo desarrolla el 95 % de los pacientes con déficit de C1q.", "sin_banco": true, "ok": "", "x": "El C1q retira en silencio los cuerpos apoptóticos. Sin él se acumulan restos con autoantígenos nucleares, se pierde la tolerancia y aparecen autoanticuerpos. Los otros distractores son de otros déficits: inactivador del C1 (edema), factor H (SHU atípico), properdina (Neisseria) y CD18 (LAD I). <span class=\"cx\">Por eso</span> <span class=\"res\">déficit de C1q = lupus en el 95 %</span>.", "truco": "C1q = «Quita» cadáveres celulares; sin él, lupus.", "veces": 0}, {"n": 10, "id": "IN3-022", "c": "i", "tema": "Mediadores secundarios de origen celular", "pregunta": "Respecto a la proteína C reactiva, es correcto:", "opciones": ["a. La producen los macrófagos en el foco inflamatorio.", "b. Su síntesis la induce sobre todo la IL-10.", "c. Es pentamérica, se une a la fosfatidilcolina microbiana, actúa como opsonina y sube hasta diez mil veces en 24 horas.", "d. Es una proteína de fase aguda que desciende durante la infección.", "e. Es un mediador lipídico derivado del ácido araquidónico."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es pentamérica, se une a la fosfatidilcolina de la membrana microbiana, opsoniza y aumenta hasta diez mil veces en las primeras 24 horas.", "sin_banco": true, "ok": "", "x": "La PCR la fabrica el <mark>hígado</mark> por la IL-6; se pega a la fosfatidilcolina del microbio, lo opsoniza y puede iniciar la vía clásica (paso 1 de la cadena). Sube <span class=\"res\">hasta diez mil veces en 24 horas</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN3-023", "c": "d", "tema": "Mediadores primarios de origen humoral", "pregunta": "Respecto a los mediadores humorales de la inflamación, es FALSO:", "opciones": ["a. Las anafilotoxinas se describen como «hormonas con efecto local».", "b. El aumento de permeabilidad por anafilotoxinas es máximo a los 5-10 minutos y desaparece a la hora.", "c. La bradiquinina aumenta la permeabilidad vascular y produce dolor.", "d. La kalicreína se activa por el factor XII (Hageman) y por productos del daño tisular.", "e. Las metaloproteinasas están siempre presentes y activas en los tejidos en reposo."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es falso: las metaloproteinasas están ausentes en los tejidos en reposo y se secretan rápido ante una invasión o un trauma.", "sin_banco": true, "ok": "", "x": "Cuatro sistemas humorales amplifican la inflamación: complemento, kininas, coagulación-fibrinólisis y metaloproteinasas. Las anafilotoxinas actúan rápido y breve (<mark>5-10 minutos</mark>), la bradiquinina es la que <span class=\"res\">produce dolor</span>, y las metaloproteinasas, <span class=\"cx\">en cambio</span>, aparecen solo ante el daño y las frenan los TIMP.", "truco": "Kininas = «quema» (dolor); MMP = solo cuando hay daño.", "veces": 0}], "tabla": {"cab": ["", "Vía clásica", "Vía de las lectinas", "Vía alterna"], "filas": [["Qué la inicia", "Anticuerpo (IgM, IgG) o PCR unidos al microbio", "MBL y ficolinas sobre manano o N-acetil-glucosamina", "C3 que se hidroliza solo y se pega a la superficie"], ["¿Anticuerpo?", "Sí: IgM mejor que IgG, porque trae cinco sitios", "No: actúa de inmediato", "No: está siempre encendida a bajo nivel"], ["Enzimas clave", "C1q, C1r, C1s", "MASP-2 (como C1s) y MASP-1", "Factor B, factor D y properdina"], ["Convertasa del C3", "C4bC2a", "C4bC2a", "C3bBb"], ["🔑 Para diferenciar", "Anticuerpo + C1q", "Azúcar + MBL", "Superficie sin factor H"]]}, "fuente": "Fuente: tu teoría — clase 6 (Sistema del complemento) y clase 7b (mediadores humorales y proteína C reactiva), Rojas 17.ª ed."}, {"n": 6, "slug": "Inflamacion", "titulo": "Inflamación aguda", "subtitulo": "del mastocito al neutrófilo, los mediadores, la fiebre y la resolución", "grupo": "g3", "lema": "La idea: ante una agresión, el tejido <b>pide ayuda a la sangre</b>. El <mark>mastocito</mark> se degranula en segundos, la histamina dilata el vaso y lo vuelve permeable, y por las brechas salen plasma (edema) y leucocitos. Llegan en un orden fijo: <u>neutrófilos en minutos, macrófagos en horas y linfocitos en días</u>. Las citoquinas IL-1, IL-6 y TNF llevan el mensaje al hipotálamo (fiebre) y al hígado (proteínas de fase aguda). Importa porque es un proceso <b>benéfico</b> que, si se inicia sin causa o se prolonga, daña: gota, asma por aspirina o granulomas que fibrosan. En la imagen verás una vénula cortada a lo largo: arriba el neutrófilo que rueda, se pega y atraviesa la pared; abajo el mastocito, el macrófago y los neutrófilos que van hacia la herida.", "img": "img/06.webp", "mini": "img/mini/06.webp", "ratio": 1.5, "etiquetas": [{"n": "①", "t": "Neutrófilo libre", "s": "el primero en llegar:<br>minutos", "c": "i", "x": 0.5, "y": 6, "ax": 15.3, "ay": 28, "al": "l"}, {"n": "", "t": "Rodamiento", "s": "selectinas; la PTX-3<br>lo bloquea", "c": "i", "x": 30, "y": 6, "ax": 35.5, "ay": 30}, {"n": "", "t": "Adhesión firme", "s": "IL-1β induce moléculas<br>de adherencia", "c": "i", "x": 50, "y": 6, "ax": 55.3, "ay": 35.6}, {"n": "", "t": "Diapedesis", "s": "pasa entre dos<br>células endoteliales", "c": "i", "x": 69, "y": 6, "ax": 68.4, "ay": 39}, {"n": "⑦", "t": "Plaquetas", "s": "PAF, TGFβ;<br>inmunotrombosis", "c": "d", "x": 99.5, "y": 6, "ax": 84, "ay": 34.7, "d": "B", "al": "r"}, {"n": "④⑤", "t": "Mastocito", "s": "gránulos preformados:<br>responde en segundos", "c": "d", "x": 0.5, "y": 91, "ax": 13, "ay": 59.6, "d": "A", "al": "l"}, {"n": "⑨⑩⑫", "t": "Mediadores", "s": "histamina ya; leucotrienos<br>y PG horas después", "c": "d", "x": 26, "y": 91, "ax": 24.7, "ay": 50.8, "d": "D"}, {"n": "②③⑪", "t": "Macrófago", "s": "horas: IL-1, IL-6,<br>TNF (pirógenos)", "c": "i", "x": 44, "y": 91, "ax": 43, "ay": 64.5, "d": "C"}, {"n": "", "t": "Edema", "s": "plasma que sale<br>por las brechas", "c": "d", "x": 60, "y": 91, "ax": 61.8, "ay": 48.8}, {"n": "", "t": "Quimiotaxis", "s": "C5a, IL-8 y LTB4<br>guían al neutrófilo", "c": "i", "x": 77, "y": 91, "ax": 77, "ay": 57}, {"n": "", "t": "Herida y bacterias", "s": "el agresor que<br>lo inicia todo", "c": "g", "x": 99.5, "y": 91, "ax": 93, "ay": 68, "al": "r"}], "diapos": [{"img": "img/06.webp", "ratio": 1.5, "titulo": "Del mastocito al neutrófilo", "texto": "El <mark>mastocito</mark> se degranula en segundos ⑤, el vaso se abre y salen plasma y leucocitos: neutrófilos en minutos, macrófagos en horas ①.", "etiquetas": [{"n": "①", "t": "Neutrófilo libre", "s": "el primero en llegar:<br>minutos", "c": "i", "x": 0.5, "y": 6, "ax": 15.3, "ay": 28, "al": "l"}, {"n": "", "t": "Rodamiento", "s": "selectinas; la PTX-3<br>lo bloquea", "c": "i", "x": 30, "y": 6, "ax": 35.5, "ay": 30}, {"n": "", "t": "Adhesión firme", "s": "IL-1β induce moléculas<br>de adherencia", "c": "i", "x": 50, "y": 6, "ax": 55.3, "ay": 35.6}, {"n": "", "t": "Diapedesis", "s": "pasa entre dos<br>células endoteliales", "c": "i", "x": 69, "y": 6, "ax": 68.4, "ay": 39}, {"n": "⑦", "t": "Plaquetas", "s": "PAF, TGFβ;<br>inmunotrombosis", "c": "d", "x": 99.5, "y": 6, "ax": 84, "ay": 34.7, "d": "B", "al": "r"}, {"n": "④⑤", "t": "Mastocito", "s": "gránulos preformados:<br>responde en segundos", "c": "d", "x": 0.5, "y": 91, "ax": 13, "ay": 59.6, "d": "A", "al": "l"}, {"n": "⑨⑩⑫", "t": "Mediadores", "s": "histamina ya; leucotrienos<br>y PG horas después", "c": "d", "x": 26, "y": 91, "ax": 24.7, "ay": 50.8, "d": "D"}, {"n": "②③⑪", "t": "Macrófago", "s": "horas: IL-1, IL-6,<br>TNF (pirógenos)", "c": "i", "x": 44, "y": 91, "ax": 43, "ay": 64.5, "d": "C"}, {"n": "", "t": "Edema", "s": "plasma que sale<br>por las brechas", "c": "d", "x": 60, "y": 91, "ax": 61.8, "ay": 48.8}, {"n": "", "t": "Quimiotaxis", "s": "C5a, IL-8 y LTB4<br>guían al neutrófilo", "c": "i", "x": 77, "y": 91, "ax": 77, "ay": 57}, {"n": "", "t": "Herida y bacterias", "s": "el agresor que<br>lo inicia todo", "c": "g", "x": 99.5, "y": 91, "ax": 93, "ay": 68, "al": "r"}]}, {"img": "img/06_2.webp", "ratio": 1.5, "titulo": "Eosinófilo y granuloma", "texto": "El eosinófilo vierte <mark>MBP</mark> sobre la cutícula del esquistosoma ⑥⑧; si el agresor persiste, granuloma: Langhans en herradura frente a cuerpo extraño ⑬.", "etiquetas": [{"n": "⑧", "t": "Eosinófilo", "s": "bilobulado, gránulos<br>rojo-naranja", "c": "d", "x": 0.5, "y": 8, "ax": 13, "ay": 22, "al": "l"}, {"n": "⑧", "t": "Cutícula perforada", "s": "se abren<br>ventanas", "c": "d", "x": 26, "y": 8, "ax": 26.7, "ay": 45}, {"n": "⑬", "t": "Linfocitos", "s": "manguito<br>periférico", "c": "g", "x": 50, "y": 8, "ax": 55.3, "ay": 32}, {"n": "⑬", "t": "Langhans", "s": "núcleos en herradura:<br>tuberculosis", "c": "d", "x": 71, "y": 8, "ax": 74.2, "ay": 34}, {"n": "⑬", "t": "Cristal extraño", "s": "lo rodea<br>la gigante", "c": "g", "x": 99.5, "y": 8, "ax": 92.4, "ay": 51, "al": "r"}, {"n": "⑥", "t": "MBP", "s": "proteína básica mayor:<br>lesiona la cutícula", "c": "d", "x": 0.5, "y": 91, "ax": 21.5, "ay": 58.6, "al": "l"}, {"n": "⑧", "t": "Esquistosoma", "s": "larva mucho más<br>grande que el eosinófilo", "c": "g", "x": 32, "y": 91, "ax": 42.3, "ay": 66}, {"n": "⑬", "t": "Epitelioides", "s": "macrófagos<br>en empalizada", "c": "i", "x": 52, "y": 91, "ax": 60.5, "ay": 48.8}, {"n": "⑬", "t": "Necrosis caseosa", "s": "centro del<br>granuloma", "c": "g", "x": 67, "y": 91, "ax": 69, "ay": 46}, {"n": "⑬", "t": "Gigante a cuerpo extraño", "s": "núcleos<br>dispersos", "c": "i", "x": 99.5, "y": 91, "ax": 89.8, "ay": 62, "al": "r"}]}, {"img": "img/06_3.webp", "ratio": 1.5, "titulo": "Inflamasoma, eicosanoides y fiebre", "texto": "El <mark>NLRP3</mark> reconoce el urato y activa la IL-1β ②③; la aspirina desvía el araquidónico a leucotrienos ⑩⑫ <span class=\"lt2\">D</span>; IL-1, IL-6 y TNF → PGE2 → fiebre ⑪.", "etiquetas": [{"n": "②", "t": "Urato", "s": "los reconoce<br>el NLRP3", "c": "d", "x": 0.5, "y": 8, "ax": 13.7, "ay": 27, "al": "l"}, {"n": "③", "t": "NLRP3", "s": "inflamasoma con<br>procaspasa-1", "c": "d", "x": 26, "y": 8, "ax": 22, "ay": 40}, {"n": "⑨", "t": "Fosfolípido", "s": "la fosfolipasa libera<br>el araquidónico", "c": "g", "x": 44, "y": 8, "ax": 39.7, "ay": 32}, {"n": "⑩", "t": "Vía COX", "s": "prostaglandinas:<br>la PGE2 broncodilata", "c": "i", "x": 62, "y": 8, "ax": 61.8, "ay": 30}, {"n": "⑪", "t": "Hipotálamo", "s": "PGE2 sube el<br>termostato: fiebre", "c": "d", "x": 99.5, "y": 8, "ax": 82.7, "ay": 44, "al": "r"}, {"n": "③", "t": "Pro-IL-1β", "s": "inactiva hasta<br>que la cortan", "c": "g", "x": 0.5, "y": 91, "ax": 9, "ay": 55, "al": "l"}, {"n": "⑪", "t": "IL-1β activa", "s": "pirógeno<br>endógeno", "c": "d", "x": 21, "y": 91, "ax": 35.8, "ay": 67.4}, {"n": "⑫", "t": "Vía 5-LOX", "s": "leucotrienos<br>C4, D4, E4", "c": "d", "x": 40, "y": 91, "ax": 55.3, "ay": 55}, {"n": "⑩", "t": "Bronquio cerrado", "s": "asma por<br>aspirina", "c": "d", "x": 60, "y": 91, "ax": 60, "ay": 68, "d": "D"}, {"n": "⑪", "t": "Endotelio hipotalámico", "s": "recibe IL-1, IL-6 y<br>TNF: fabrica PGE2", "c": "d", "x": 99.5, "y": 91, "ax": 76.8, "ay": 60.5, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = los leucocitos que llegan</b> y cómo salen del vaso, <b class=\"d\">rojo = lo que dilata y filtra el vaso</b> (mastocito, mediadores, plaquetas, edema), gris = el agresor.", "<b>Arriba, de izquierda a derecha:</b> el neutrófilo <mark>rueda</mark> sobre las selectinas, se <mark>pega</mark> firme (la IL-1β induce moléculas de adherencia) y hace la <mark>diapedesis</mark> entre dos células endoteliales. <span class=\"cx\">Luego</span> sigue la quimiotaxis (C5a, IL-8, LTB4) hasta la herida.", "<b>Abajo:</b> el mastocito vierte histamina y heparina <b>ya fabricadas</b> <span class=\"lt2\">A</span>; horas después sintetiza leucotrienos y prostaglandinas. El macrófago, que llega en horas, libera IL-1, IL-6 y TNF <span class=\"lt2\">C</span>: son los <mark>pirógenos endógenos</mark>.", "<b>Ojo:</b> la imagen no muestra eosinófilos; su papel (parásitos, alergia) está en la cadena y en la tabla."], "recordar": "<b>Local:</b> calor, rubor, edema y dolor (kininas). <b>Sistémico:</b> fiebre, leucocitosis y fase aguda. Orden de llegada: <b>neutrófilo (minutos) → macrófago (horas) → linfocito (días)</b>."}, "numeros": [{"l": "A", "html": "<b>Mastocito</b>: <b class=\"n\">12 micras</b>, unos <b class=\"n\">1000 gránulos</b>; la heparina es el <b class=\"n\">30 %</b> del material granular. La histamina dura <b class=\"a\">menos de 1 min</b> (la degrada la histaminasa).", "rango": {"min": 0, "max": 5, "unidad": "minutos de acción de la histamina", "zonas": [[0, 1, "n", "menos de 1 min"]], "marcas": [1]}}, {"l": "B", "html": "<b>Plaquetas</b>: <b class=\"n\">100 millardos</b> al día, vida de <b class=\"n\">8–10 días</b>. El PAF es <b class=\"a\">1000 veces</b> más vasodilatador que la histamina.", "rango": {"min": 0, "max": 12, "unidad": "días de vida de la plaqueta", "zonas": [[8, 10, "n", "vida normal"]], "marcas": [8, 10]}}, {"l": "C", "html": "<b>TNF</b>: sube notoriamente a los <b class=\"a\">90 minutos</b>. La <b>PCR</b> aumenta hasta <b class=\"a\">10 000 veces</b> en <b class=\"a\">24 h</b>.", "rango": null}, {"l": "D", "html": "<b>Eicosanoides</b>: la PGD2 y la sustancia P son <b class=\"a\">100 veces</b> más potentes que la histamina (broncoconstricción y pápula). La aspirina desata asma en el <b class=\"a\">5–10 %</b> de los asmáticos.", "rango": {"min": 0, "max": 20, "unidad": "% de los asmáticos", "zonas": [[5, 10, "a", "asma por aspirina"]], "marcas": [5, 10]}}], "escalas": [], "cadena": {"titulo": "Del agresor al foco", "subtitulo": "estímulo → mastocito y vaso → leucocitos → mediadores → resolución (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Reconocimiento", "m": "<b>Qué pasa:</b> TLR, lectinas, pentraxinas y NLR detectan al agresor (microbio, cristal, trauma). El <mark>inflamasoma</mark> (NLR + procaspasa-1) corta la pro-IL-1β y la pro-IL-18.", "pr": "señales de alarma; IL-1β e IL-18 activas.", "pr_tit": "Produce:", "rf": "Preguntas ②③", "color": "p1"}, {"t": "2. Mastocito", "m": "<b>Por qué es tan rápido:</b> guarda unos mil gránulos con <mark>histamina y heparina</mark> listas; en una segunda etapa sintetiza prostaglandinas, leucotrienos y citoquinas.", "pr": "vasodilatación y permeabilidad en segundos o minutos.", "pr_tit": "Produce:", "rf": "Preguntas ④⑤ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Vaso", "m": "<b>Qué produce:</b> la histamina, las anafilotoxinas, el PAF y las kininas abren brechas en el endotelio; la bradiquinina da <b>dolor</b>. Sale plasma con proteínas.", "pr": "calor, rubor, edema y dolor.", "pr_tit": "Produce:", "rf": "Pregunta ⑦ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Leucocitos", "m": "<b>Cómo salen:</b> rodamiento (selectinas), adhesión firme (moléculas de adherencia inducidas por IL-1β y TNF), diapedesis y quimiotaxis por C5a, IL-8 y LTB4. El <mark>eosinófilo</mark> ataca parásitos con MBP, ECP, EPO y EDN.", "pr": "neutrófilos en minutos, macrófagos en horas, linfocitos en días.", "pr_tit": "Produce:", "rf": "Preguntas ①⑥⑧", "color": "p4"}, {"t": "5. Mediadores y fiebre", "m": "<b>Qué pasa:</b> de la fosfolipasa sale el ácido araquidónico → ciclooxigenasa (prostaglandinas) o 5-lipooxigenasa (leucotrienos). IL-1, IL-6 y TNF → <mark>PGE2</mark> en el hipotálamo → fiebre; el hígado fabrica PCR.", "pr": "fiebre, leucocitosis y fase aguda.", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑩⑪⑫ · puntos <span class=\"lt2\">C</span><span class=\"lt2\">D</span>", "color": "p5"}, {"t": "6. Resolución o cronicidad", "m": "<b>Si se controla:</b> IL-10, TGFβ y lipoxinas, resolvinas y protectinas (ω-3) apagan el foco; las células sobrantes mueren por apoptosis. <b>Si falla:</b> el agresor persiste → <mark>granuloma</mark> y fibrosis (IL-13).", "pr": "reparación; o tuberculosis, sarcoidosis y fibrosis.", "pr_tit": "Produce:", "rf": "Preguntas ⑬⑭", "color": "p4"}], "extra": [{"html": "💊 <b>Dónde corta cada fármaco:</b> fosfolipasa → <mark>corticoides</mark> (apagan las dos ramas); ciclooxigenasa → <b>AINE</b> (aspirina, ibuprofeno); 5-lipooxigenasa → <b>zileuton</b>; receptor de leucotrienos → <b>montelukast y zafirlukast</b>. La aspirina tapa la rama de la ciclooxigenasa y desvía todo a los leucotrienos: <b>asma por aspirina</b> <span class=\"lt2\">D</span>.", "k": ""}, {"html": "🔥 <b>Inflamasoma NLRP3:</b> cristales de ácido úrico (<mark>gota</mark>), sílice y asbesto (silicosis, asbestosis) y el aluminio de las vacunas. <b>Anakinra</b> bloquea el receptor de la IL-1; los <b>anti-TNF</b> obligan a descartar tuberculosis latente.", "k": "k"}], "escaleras": [{"c": "d", "t": "🌡️ De la endotoxina a la fiebre", "pasos": ["Pirógeno externo (endotoxina)", "macrófago y endotelio: <b>IL-1, IL-6 y TNF</b>", "endotelio del hipotálamo: <b>PGE2</b>", "receptor EP3: el termostato sube", "fiebre, hierro y zinc bajos, sueño y anorexia; la aspirina corta en la PGE2"]}, {"c": "i", "t": "⏳ De la inflamación aguda a la crónica", "pasos": ["Neutrófilos (minutos)", "macrófagos (horas)", "linfocitos (días)", "agresor que persiste: <b>granuloma</b>", "IL-13 y TGFβ: <b>fibrosis</b>"]}], "html": "", "fuente": "Fuente: tu teoría — clase 7a (etapas, inflamasomas, mastocitos, basófilos, eosinófilos, plaquetas) y clase 7b (mediadores primarios y secundarios, eicosanoides, fiebre, granuloma, resolución y farmacología)."}, "preguntas": [{"n": 1, "id": "IN3-010", "c": "i", "tema": "Etapas del proceso inflamatorio", "pregunta": "¿Cuál es el orden de llegada de los leucocitos al foco inflamatorio?", "opciones": ["a. Linfocitos en minutos, macrófagos en horas, neutrófilos en días.", "b. Macrófagos en minutos, neutrófilos en horas, linfocitos en días.", "c. Eosinófilos primero, luego basófilos y al final neutrófilos.", "d. Neutrófilos en minutos, macrófagos en algunas horas, linfocitos días más tarde.", "e. Todos llegan a la vez y el orden depende del agresor."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Neutrófilos en minutos, macrófagos pasadas algunas horas y linfocitos días más tarde.", "sin_banco": true, "ok": "", "x": "Mira la fila de arriba: el neutrófilo ya está en la sangre, <span class=\"cx\">así que</span> es <mark>el <span class=\"cx\">primero</span> en salir</mark> (minutos). El macrófago llega en horas y el linfocito en días. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN3-011", "c": "i", "tema": "Inflamasomas", "pregunta": "El inflamasoma que reconoce los cristales de ácido úrico, la sílice, el asbesto y el aluminio de las vacunas es:", "opciones": ["a. NLRP1", "b. NLRP3", "c. NLRC4", "d. AIM2", "e. TLR4"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. NLRP3, nexo entre la inflamación y la gota, la silicosis, la asbestosis y el adyuvante de aluminio.", "sin_banco": true, "ok": "", "x": "Cada inflamasoma reconoce cosas distintas: NLRP1 el muramil dipéptido y la toxina del ántrax, NLRC4 PAMPs o DAMPs, AIM2 el ADN de doble cadena o la flagelina. El <mark>NLRP3</mark> es el de las partículas, <span class=\"cx\">así que</span> <span class=\"res\">gota, silicosis, asbestosis y el aluminio vacunal pasan por la misma vía</span>.", "truco": "NLRP «3 piedras»: urato, sílice y asbesto (más el aluminio).", "veces": 0}, {"n": 3, "id": "IN3-012", "c": "i", "tema": "Inflamasomas", "pregunta": "¿Qué es un inflamasoma y por qué es imprescindible para que actúe la IL-1β?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es un complejo intracitoplasmático de NLR, proteínas adaptadoras y procaspasa-1. La IL-1β y la IL-18 están inactivas en el citoplasma de macrófagos y dendríticas; la caspasa-1 activada las procesa y permite secretarlas activas.", "sin_banco": true, "ok": "", "x": "La IL-1β se guarda como precursor inactivo. <span class=\"cx\">Cuando</span> un NLR detecta peligro, arma el inflamasoma y activa la <mark>caspasa-1</mark>, que corta la pro-IL-1β y la pro-IL-18. <span class=\"cx\">Por eso</span>, <span class=\"res\">sin inflamasoma no hay IL-1β activa ni fiebre por esa vía</span>.", "truco": "Inflamasoma = «tijera» (caspasa-1) que libera IL-1β e IL-18.", "veces": 0}, {"n": 4, "id": "IN3-013", "c": "d", "tema": "Basófilos", "pregunta": "Respecto a las diferencias entre mastocitos y basófilos, es FALSO:", "opciones": ["a. El mastocito vive meses o años.", "b. El basófilo circula en la sangre y vive horas.", "c. El mastocito posee elastasa, prostaglandina D2 y PAF.", "d. El mastocito expresa el receptor C-Kit.", "e. El basófilo prolifera en los tejidos después de madurar."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es falso: el basófilo no prolifera después de madurar; quien se multiplica en los tejidos es el mastocito.", "sin_banco": true, "ok": "", "x": "El mastocito de la imagen vive en el tejido junto al vaso: dura <mark>meses o años</mark> y se reproduce allí. El basófilo, <span class=\"cx\">en cambio</span>, circula y vive horas; <span class=\"res\">no prolifera tras madurar</span>, <span class=\"cx\">por eso</span> la e es la falsa.", "truco": "", "veces": 0}, {"n": 5, "id": "IN3-014", "c": "d", "tema": "Mastocitos", "pregunta": "¿Por qué el mastocito puede responder a una agresión en segundos?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque guarda mediadores preformados en unos mil gránulos (histamina y heparina, esta es el 30 % del material granular) que solo debe expulsar al degranularse. Las prostaglandinas, los leucotrienos y las citoquinas se sintetizan de novo y tardan más.", "sin_banco": true, "ok": "", "x": "Es el mastocito de abajo a la izquierda (punto Ⓐ): sus gránulos ya traen <mark>histamina y heparina</mark>, <span class=\"cx\">por eso</span> se vacían en segundos. Lo que fabrica después (leucotrienos, PG) <span class=\"res\">tarda horas</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN3-015", "c": "i", "tema": "Eosinófilos", "pregunta": "La proteína del gránulo del eosinófilo que es tóxica para la cutícula de los esquistosomas y también para el endotelio respiratorio es:", "opciones": ["a. Neurotoxina (EDN)", "b. Peroxidasa (EPO)", "c. Proteína catiónica (ECP)", "d. Proteína básica mayor (MBP)", "e. Triptasa"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Proteína básica mayor (MBP), de 11 kDa: lesiona la cutícula de parásitos y el endotelio respiratorio.", "sin_banco": true, "ok": "", "x": "Los gránulos secundarios guardan cuatro proteínas: la <mark>MBP</mark> (el cristal central del gránulo), la EDN, que daña las fibras mielinizadas, la EPO, que genera metabolitos del oxígeno, y la ECP, tóxica para larvas. La MBP también lesiona la mucosa respiratoria, <span class=\"cx\">por eso</span> <span class=\"res\">explica parte del daño del asma</span>.", "truco": "MBP = «Mata Bichos y Pulmón».", "veces": 0}, {"n": 7, "id": "IN3-016", "c": "d", "tema": "Plaquetas, linfocitos y fibroblastos", "pregunta": "Respecto al factor activador de las plaquetas (PAF), es correcto:", "opciones": ["a. Es la sustancia vasodilatadora más potente descrita, mil veces superior a la histamina.", "b. Solo lo producen las plaquetas.", "c. Es un inhibidor de la agregación plaquetaria.", "d. Es la principal fuente de TGFβ.", "e. Se degrada en menos de un minuto por la histaminasa."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Es el vasodilatador más potente descrito, mil veces más que la histamina; produce edema, broncoconstricción, paro cardíaco e hipotensión.", "sin_banco": true, "ok": "", "x": "Las plaquetas de la pared (punto Ⓑ) responden al PAF, <mark>mil veces más vasodilatador que la histamina</mark>. <span class=\"cx\">Por eso</span> puede causar edema, broncoconstricción y <span class=\"res\">paro cardíaco con hipotensión</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN3-017", "c": "i", "tema": "Eosinófilos", "pregunta": "Niño de 9 años con esquistosomiasis y eosinofilia. ¿Cómo destruye el eosinófilo a un parásito mucho más grande que él?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Se adhiere a la cutícula del parásito y vierte sobre ella las proteínas tóxicas de sus gránulos (MBP, ECP, EPO); la lisa y abre ventanas por las que entran los macrófagos para completar la destrucción.", "sin_banco": true, "ok": "", "x": "Un parásito no cabe en ningún fagocito, <span class=\"cx\">por eso</span> el eosinófilo ataca desde afuera. Se pega a la cutícula y la perfora con sus <mark>proteínas catiónicas</mark>. <span class=\"cx\">Luego</span> los macrófagos entran por esas ventanas, <span class=\"cx\">así que</span> <span class=\"res\">la defensa antiparasitaria es un trabajo en equipo eosinófilo-macrófago</span>.", "truco": "El eosinófilo abre la «ventana», el macrófago entra.", "veces": 0}, {"n": 9, "id": "IN3-018", "c": "d", "tema": "Correlato clínico: farmacología", "pregunta": "Los corticoides son antiinflamatorios más amplios que los AINE porque inhiben:", "opciones": ["a. La ciclooxigenasa", "b. La 5-lipooxigenasa", "c. El receptor de leucotrienos", "d. La 15-lipooxigenasa", "e. Parcialmente la fosfolipasa"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Inhiben parcialmente la fosfolipasa, que está antes de la bifurcación, y así reducen prostaglandinas y leucotrienos.", "sin_banco": true, "ok": "", "x": "Recuadro de fármacos de la página 2: el corticoide corta la <mark>fosfolipasa</mark>, antes de la bifurcación, <span class=\"cx\">así que</span> apaga prostaglandinas y leucotrienos. <span class=\"res\">El AINE solo corta la ciclooxigenasa</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN3-019", "c": "d", "tema": "Eicosanoides", "pregunta": "Mujer asmática de 35 años presenta una crisis grave de broncoespasmo tras tomar aspirina por cefalea. ¿Qué mecanismo lo explica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La aspirina bloquea la ciclooxigenasa: baja la PGE2, que es broncodilatadora, y el ácido araquidónico se desvía a la 5-lipooxigenasa, que produce más leucotrienos C4, D4 y E4, los broncoconstrictores más potentes. Ocurre en el 5-10 % de los asmáticos.", "sin_banco": true, "ok": "", "x": "El ácido araquidónico tiene dos salidas. Si se tapa la de la ciclooxigenasa, <mark>todo se va a la de la lipooxigenasa</mark>. <span class=\"cx\">Así que</span> hay menos PGE2 broncodilatadora y más leucotrienos broncoconstrictores. Le pasa al <span class=\"res\">5-10 % de los asmáticos</span>, también con otros AINE o con tartrazina.", "truco": "Tapas una salida, se desborda la otra.", "veces": 0}, {"n": 11, "id": "IN3-020", "c": "i", "tema": "Síndrome febril", "pregunta": "Describa la cadena que va de la endotoxina bacteriana a la fiebre y diga dónde actúa la aspirina.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Los pirógenos externos inducen en macrófagos y endotelio los pirógenos endógenos IL-1, IL-6 y TNF; estos hacen que el endotelio hipotalámico produzca PGE2, que actúa sobre receptores EP3 y sube el punto de control térmico. La aspirina inhibe la ciclooxigenasa y frena la PGE2.", "sin_banco": true, "ok": "", "x": "El macrófago de la imagen (punto Ⓒ) libera <mark>IL-1, IL-6 y TNF</mark>; en el hipotálamo inducen PGE2, que sube el termostato (escalera de la página 2). <span class=\"res\">La aspirina corta en la PGE2</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN3-021", "c": "d", "tema": "Eicosanoides", "pregunta": "La antigua «sustancia de reacción lenta de la anafilaxis» (SRS-A) corresponde a:", "opciones": ["a. Leucotrieno B4", "b. Leucotrienos C4, D4 y E4", "c. Prostaglandina D2", "d. Tromboxano A2", "e. Lipoxina A4"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Leucotrienos C4, D4 y E4, los broncoconstrictores más potentes, sinérgicos con la histamina.", "sin_banco": true, "ok": "", "x": "La 5-lipooxigenasa produce dos tipos de leucotrienos. El LTB4 es quimiotáctico para neutrófilos, <span class=\"cx\">en cambio</span> los <mark>LTC4, D4 y E4</mark> son los broncoconstrictores más potentes. <span class=\"cx\">Por eso</span> <span class=\"res\">SRS-A = LTC4, LTD4 y LTE4</span>, el blanco del montelukast y el zafirlukast.", "truco": "B4 «Busca» neutrófilos; C-D-E «Cierran» el bronquio.", "veces": 0}, {"n": 13, "id": "IN3-024", "c": "g", "tema": "Inflamación crónica, granuloma y fibrosis", "pregunta": "¿Qué diferencia a las células gigantes de Langhans de las de cuerpo extraño en el granuloma?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Las de Langhans son frecuentes en tuberculosis, sífilis, linfogranuloma venéreo y fiebre por arañazo de gato; las de cuerpo extraño son propias de la sarcoidosis y de procesos sin agente etiológico identificable.", "sin_banco": true, "ok": "", "x": "<span class=\"cx\">Cuando</span> el agresor no se puede eliminar, el organismo lo aísla en un <mark>granuloma</mark>: macrófagos, células gigantes de 40 a 60 micras con 15 o más núcleos y una corona de linfocitos (CD4 al centro, CD8 en la periferia). El tipo de célula gigante orienta la causa: <span class=\"res\">Langhans sugiere infección (tuberculosis); cuerpo extraño, sarcoidosis o causa no identificada</span>.", "truco": "Langhans = «Lleva bacilo» (TBC).", "veces": 0}, {"n": 14, "id": "IN3-025", "c": "g", "tema": "Correlato clínico: farmacología", "pregunta": "Antes de iniciar un anticuerpo monoclonal anti-TNF en un paciente con artritis reumatoide, debe descartarse:", "opciones": ["a. Tuberculosis latente", "b. Hemocromatosis", "c. Déficit de C1q", "d. Hipersensibilidad a abacavir", "e. Gota tofácea"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Tuberculosis latente, porque el bloqueo del TNF puede reactivarla.", "sin_banco": true, "ok": "", "x": "El TNF sostiene la inflamación crónica de la artritis reumatoide, pero también ayuda a mantener contenidos a los bacilos en el granuloma (literatura). <span class=\"cx\">Por eso</span>, al bloquearlo, <mark>una tuberculosis latente puede reactivarse</mark>. El bloqueo de la IL-6 parece dar resultados similares <span class=\"res\">con menos efectos colaterales</span>.", "truco": "Anti-TNF: primero «busca la TBC».", "veces": 0}], "tabla": {"cab": ["", "Mastocito", "Basófilo", "Eosinófilo"], "filas": [["Dónde y cuánto vive", "Tejidos, junto a vasos; meses o años", "Sangre; horas", "Sangre (1–3 %) y tejidos; 8–18 h en circulación"], ["Arsenal", "Histamina, heparina; elastasa, PGD2 y PAF", "Histamina; sin elastasa, PGD2 ni PAF", "MBP, ECP, EPO y EDN en gránulos"], ["¿Prolifera?", "Sí, en los tejidos, y rearma sus gránulos", "No, después de madurar", "Lo produce la médula por IL-3, IL-5 y GM-CSF"], ["Función clave", "Inicia la inflamación en segundos", "Alergia (IgE) y dermatitis atópica (TSLP)", "Mata parásitos; sostiene a las plasmáticas"], ["🔑 Para diferenciar", "Residente que vive años", "Viajero que vive horas", "Antiparasitario, frenado por anti-IL-5"]]}, "fuente": "Fuente: tu teoría — clases 7a (Inflamación: mecanismos y células) y 7b (Mediadores, fiebre y resolución), Rojas 17.ª ed."}, {"n": 7, "slug": "Antigenos_y_HLA", "titulo": "Antígenos y presentación por HLA", "subtitulo": "HLA-I muestra lo de dentro, HLA-II lo de fuera", "grupo": "g4", "lema": "La idea: el linfocito T <b>no ve microbios enteros</b>; solo ve <mark>péptidos</mark> que otra célula le muestra en una molécula HLA. Lo que se fabrica <b>dentro</b> de la célula (un virus) se tritura en el proteosoma y sale en la <mark>HLA-I</mark> hacia el linfocito T CD8, que mata. Lo que se captura <b>afuera</b> (una bacteria) se digiere en el fagolisosoma y sale en la <mark>HLA-II</mark> hacia el linfocito T CD4, que ayuda. Importa porque el HLA es tan variado (unos 8500 alelos) que explica el <b>rechazo de trasplantes</b>, la susceptibilidad a enfermedades (B27, DQ2) y alergias graves a fármacos (B*5701 y abacavir). En la imagen verás dos células: a la izquierda una célula infectada (vía de la HLA-I) y a la derecha una célula dendrítica (vía de la HLA-II).", "img": "img/07.webp", "mini": "img/mini/07.webp", "ratio": 1.5, "etiquetas": [{"n": "", "t": "Virus", "s": "se fabrica<br>dentro de la célula", "c": "g", "x": 0.5, "y": 6, "ax": 8.1, "ay": 23, "al": "l"}, {"n": "⑧⑨", "t": "Proteosoma", "s": "tritura lo marcado<br>con ubicuitina", "c": "i", "x": 23, "y": 6, "ax": 21.8, "ay": 41.5, "d": "A"}, {"n": "⑫⑭", "t": "HLA-I → T CD8", "s": "péptido corto al<br>linfocito citotóxico", "c": "i", "x": 40, "y": 6, "ax": 35.5, "ay": 28.3, "d": "C"}, {"n": "①", "t": "Bacteria fagocitada", "s": "inmunógeno<br>del exterior", "c": "g", "x": 60, "y": 6, "ax": 60.9, "ay": 28.8}, {"n": "③⑪", "t": "HLA-II → T CD4", "s": "péptido largo al<br>linfocito ayudador", "c": "d", "x": 99.5, "y": 6, "ax": 86.9, "ay": 31.3, "al": "r"}, {"n": "⑨", "t": "TAP", "s": "mete los péptidos<br>al retículo", "c": "i", "x": 0.5, "y": 91, "ax": 24.4, "ay": 56.6, "al": "l"}, {"n": "⑦", "t": "Retículo: HLA-I", "s": "cadena α + β2-<br>microglobulina", "c": "i", "x": 29, "y": 91, "ax": 32.2, "ay": 66.4}, {"n": "④", "t": "Célula dendrítica", "s": "la presentadora<br>más potente", "c": "g", "x": 47, "y": 91, "ax": 52, "ay": 42, "d": "D"}, {"n": "⑩", "t": "HLA-II naciente", "s": "cadena invariante;<br>HLA-DM quita el CLIP", "c": "d", "x": 65, "y": 91, "ax": 65.8, "ay": 64.5}, {"n": "⑧", "t": "Fagolisosoma", "s": "catepsinas: péptidos<br>de 12-20 aa", "c": "d", "x": 84, "y": 91, "ax": 74.2, "ay": 50.8, "d": "B"}], "diapos": [{"img": "img/07.webp", "ratio": 1.5, "titulo": "Las dos vías: HLA-I y HLA-II", "texto": "Lo de <b>adentro</b> sale en la <mark>HLA-I</mark> al CD8 ⑦⑧⑨; lo de <b>afuera</b>, en la <mark>HLA-II</mark> al CD4 ⑩⑪.", "etiquetas": [{"n": "", "t": "Virus", "s": "se fabrica<br>dentro de la célula", "c": "g", "x": 0.5, "y": 6, "ax": 8.1, "ay": 23, "al": "l"}, {"n": "⑧⑨", "t": "Proteosoma", "s": "tritura lo marcado<br>con ubicuitina", "c": "i", "x": 23, "y": 6, "ax": 21.8, "ay": 41.5, "d": "A"}, {"n": "⑫⑭", "t": "HLA-I → T CD8", "s": "péptido corto al<br>linfocito citotóxico", "c": "i", "x": 40, "y": 6, "ax": 35.5, "ay": 28.3, "d": "C"}, {"n": "①", "t": "Bacteria fagocitada", "s": "inmunógeno<br>del exterior", "c": "g", "x": 60, "y": 6, "ax": 60.9, "ay": 28.8}, {"n": "③⑪", "t": "HLA-II → T CD4", "s": "péptido largo al<br>linfocito ayudador", "c": "d", "x": 99.5, "y": 6, "ax": 86.9, "ay": 31.3, "al": "r"}, {"n": "⑨", "t": "TAP", "s": "mete los péptidos<br>al retículo", "c": "i", "x": 0.5, "y": 91, "ax": 24.4, "ay": 56.6, "al": "l"}, {"n": "⑦", "t": "Retículo: HLA-I", "s": "cadena α + β2-<br>microglobulina", "c": "i", "x": 29, "y": 91, "ax": 32.2, "ay": 66.4}, {"n": "④", "t": "Célula dendrítica", "s": "la presentadora<br>más potente", "c": "g", "x": 47, "y": 91, "ax": 52, "ay": 42, "d": "D"}, {"n": "⑩", "t": "HLA-II naciente", "s": "cadena invariante;<br>HLA-DM quita el CLIP", "c": "d", "x": 65, "y": 91, "ax": 65.8, "ay": 64.5}, {"n": "⑧", "t": "Fagolisosoma", "s": "catepsinas: péptidos<br>de 12-20 aa", "c": "d", "x": 84, "y": 91, "ax": 74.2, "ay": 50.8, "d": "B"}]}, {"img": "img/07_2.webp", "ratio": 1.5, "titulo": "Hapteno y linfocito B presentador", "texto": "El <mark>hapteno</mark> solo no basta: necesita una <b>proteína portadora</b> ②. El LB atrapa el antígeno con su BCR, lo junta en un polo (<b>capping</b>) y <span class=\"cx\">luego</span> lo presenta al CD4 ⑤.", "etiquetas": [{"n": "②", "t": "Hapteno libre", "s": "solo no<br>basta", "c": "g", "x": 0.5, "y": 8, "ax": 7.5, "ay": 43, "al": "l"}, {"n": "②", "t": "Hapteno + proteína", "s": "ya es<br>inmunogénico", "c": "g", "x": 26, "y": 8, "ax": 24, "ay": 52}, {"n": "①②", "t": "Anti-hapteno", "s": "ácido penicilínico<br>unido", "c": "d", "x": 45, "y": 8, "ax": 33.5, "ay": 26}, {"n": "⑤", "t": "BCR (IgM)", "s": "atrapa el<br>antígeno entero", "c": "i", "x": 63, "y": 8, "ax": 48.5, "ay": 37.0}, {"n": "⑤", "t": "Capping", "s": "los complejos se<br>juntan en un polo", "c": "i", "x": 82, "y": 8, "ax": 64.0, "ay": 36.0}, {"n": "", "t": "Anticuerpo indiferente", "s": "el hapteno solo<br>no lo engancha", "c": "g", "x": 0.5, "y": 91, "ax": 7, "ay": 58, "al": "l"}, {"n": "⑤", "t": "Endocitosis", "s": "se interioriza y se<br>extrae el mejor péptido", "c": "i", "x": 55, "y": 91, "ax": 78.5, "ay": 54}, {"n": "⑤", "t": "HLA-II del LB", "s": "presenta el<br>péptido", "c": "d", "x": 74, "y": 91, "ax": 84.5, "ay": 47}, {"n": "⑤", "t": "LsT CD4", "s": "da la ayuda<br>al LB", "c": "d", "x": 99.5, "y": 91, "ax": 95, "ay": 55, "al": "r"}]}, {"img": "img/07_3.webp", "ratio": 1.5, "titulo": "Antígeno, superantígeno y CD1", "texto": "El antígeno común entra en el surco ①; el <mark>superantígeno</mark> se pega <b>por fuera</b>, <span class=\"cx\">por eso</span> enciende hasta el 20 % de los LsT <span class=\"lt2\">D</span> ③. El <mark>CD1</mark> presenta lípidos al LsT γδ ⑬.", "etiquetas": [{"n": "③", "t": "TCR αβ", "s": "reconoce el péptido<br>dentro del surco", "c": "i", "x": 0.5, "y": 6, "ax": 15, "ay": 41, "al": "l"}, {"n": "③", "t": "LsT encendidos en masa", "s": "hasta el 20 %,<br>sin ver el epítope", "c": "d", "x": 38, "y": 6, "ax": 44, "ay": 15, "d": "D", "al": "r"}, {"n": "⑬", "t": "TCR del LsT γδ", "s": "reconoce<br>lípidos", "c": "g", "x": 99.5, "y": 6, "ax": 84, "ay": 41, "al": "r"}, {"n": "①", "t": "Péptido en la HLA-II", "s": "antígeno convencional:<br>activa el 0,0001 %", "c": "i", "x": 0.5, "y": 91, "ax": 14.3, "ay": 50.8, "al": "l"}, {"n": "③", "t": "Superantígeno", "s": "toxina de S. aureus:<br>une HLA-II y TCR por fuera", "c": "d", "x": 30, "y": 91, "ax": 40.4, "ay": 52}, {"n": "③", "t": "Péptido de lado", "s": "el surco no<br>importa aquí", "c": "d", "x": 50, "y": 91, "ax": 48.5, "ay": 51}, {"n": "⑬", "t": "CD1", "s": "no polimórfica,<br>fuera del MHC", "c": "g", "x": 76, "y": 91, "ax": 81.5, "ay": 62}, {"n": "⑬", "t": "Lípido", "s": "ácido micólico<br>(CD1b)", "c": "g", "x": 99.5, "y": 91, "ax": 86, "ay": 54, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = HLA-I</b> (vía endógena, como las moléculas azules del dibujo), <b class=\"d\">rojo = HLA-II</b> (vía exógena, moléculas rojas), gris = los antígenos y la célula presentadora.", "<b>Izquierda:</b> el virus se multiplica dentro; sus proteínas, marcadas con ubicuitina, pasan por el <mark>proteosoma</mark> <span class=\"lt2\">A</span>, la <mark>TAP</mark> las mete al retículo y allí la HLA-I (cadena α + β2-microglobulina) recibe un péptido corto. Arriba, el complejo se muestra al linfocito T CD8.", "<b>Derecha:</b> la dendrítica engulle bacterias; en el <mark>fagolisosoma</mark> las catepsinas sacan péptidos más largos <span class=\"lt2\">B</span>. La HLA-II llega con el surco tapado por la <b>cadena invariante</b>; la <b>HLA-DM</b> retira el CLIP y entra el péptido. Arriba, se muestra al linfocito T CD4.", "<b>Antígeno o inmunógeno:</b> toda molécula extraña que despierta respuesta es inmunógeno; solo la <b>proteína</b> que reconocen el BCR y el TCR es antígeno. Los lípidos van por el sistema <mark>CD1</mark> (a linfocitos T γδ)."], "recordar": "HLA-I = lo de <b>adentro</b> → linfocito T <b>CD8</b> (1 × 8 = 8); HLA-II = lo de <b>afuera</b> → <b>CD4</b> (2 × 4 = 8). Péptidos: clase I de 8-10 aa; clase II de 12-20 aa."}, "numeros": [{"l": "A", "html": "<b>Proteosoma</b>: solo el <b class=\"n\">10 %</b> de los péptidos tiene el tamaño justo para la HLA-I: <b class=\"n\">8–10 aminoácidos</b>.", "rango": {"min": 0, "max": 34, "unidad": "aminoácidos", "zonas": [[8, 10, "n", "HLA-I"], [12, 20, "m", "HLA-II"]], "marcas": [8, 10, 12, 20]}}, {"l": "B", "html": "<b>HLA-II</b>: péptidos más largos, de <b class=\"n\">12–20 aminoácidos</b> (hasta 34).", "rango": {"min": 0, "max": 34, "unidad": "aminoácidos", "zonas": [[8, 10, "n", "HLA-I"], [12, 20, "m", "HLA-II"], [20, 34, "a", "hasta 34"]], "marcas": [8, 12, 20, 34]}}, {"l": "C", "html": "<b>Polimorfismo</b>: unos <b class=\"n\">400 genes</b> del MHC en el cromosoma 6 y cerca de <b class=\"a\">8500 alelos</b>. HLA-B27 da riesgo <b class=\"a\">90 veces</b> mayor de espondilitis; DQ2, <b class=\"a\">25 veces</b> de celiaquía.", "rango": null}, {"l": "D", "html": "<b>Célula dendrítica</b>: llega al ganglio en <b class=\"n\">~24 h</b> y espera hasta <b class=\"n\">1 semana</b>; si no halla su linfocito T, muere por apoptosis. Un superantígeno activa el <b class=\"a\">20 %</b> de los linfocitos T, frente al <b class=\"n\">0,0001 %</b> de un antígeno común.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del inmunógeno al linfocito T", "subtitulo": "estímulo → captura → procesamiento → carga en la HLA → presentación (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Inmunógeno", "m": "<b>Qué pasa:</b> entra una molécula extraña. Será más inmunogénica si es <b>más extraña</b>, grande (más de 5000 Da), compleja y con carga. Si es pequeña, como el ácido penicilínico, es un <mark>hapteno</mark>: necesita una proteína portadora.", "pr": "solo las proteínas son antígenos para BCR y TCR.", "pr_tit": "Produce:", "rf": "Preguntas ①②⑥", "color": "p1"}, {"t": "2. Captura", "m": "<b>Quién lo atrapa:</b> las tres presentadoras profesionales: <mark>dendrítica</mark> (la más potente), macrófago y linfocito B (que junta el antígeno en un polo: <b>capping</b>). La dendrítica pierde la caderina E, expresa CCR7 y viaja al ganglio.", "pr": "el antígeno llega al ganglio en unas 24 horas.", "pr_tit": "Produce:", "rf": "Preguntas ④⑤ · punto <span class=\"lt2\">D</span>", "color": "p2"}, {"t": "3a. Vía endógena", "m": "<b>Lo de adentro:</b> ubicuitina → <mark>proteosoma</mark> → péptidos de 8-10 aa → TAP → retículo, donde espera la HLA-I (cadena α + β2-microglobulina).", "pr": "HLA-I con péptido en todas las células nucleadas.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑧⑨ · punto <span class=\"lt2\">A</span>", "color": "p3"}, {"t": "3b. Vía exógena", "m": "<b>Lo de afuera:</b> fagolisosoma y catepsinas → péptidos de 12-20 aa. La HLA-II viaja tapada por la <b>cadena invariante</b>; queda el CLIP y la <mark>HLA-DM</mark> lo retira.", "pr": "HLA-II con péptido solo en presentadoras (B, macrófago, dendrítica, Langerhans).", "pr_tit": "Produce:", "rf": "Preguntas ⑩⑪ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "4. Presentación", "m": "<b>Qué produce:</b> el TCR reconoce péptido + HLA propia; la HLA-I habla con el <mark>CD8</mark> (mata la célula infectada) y la HLA-II con el <mark>CD4</mark> (ayuda). Los lípidos van por CD1 a los T γδ.", "pr": "respuesta celular específica.", "pr_tit": "Produce:", "rf": "Preguntas ③⑬", "color": "p5"}, {"t": "5. Si falla o se desvía", "m": "<b>Superantígeno:</b> une HLA-II y TCR por fuera y enciende el 20 % de los T. <b>Mimetismo:</b> anticuerpos antiestreptococo atacan corazón y articulaciones. <b>Alelo de riesgo:</b> B27, DQ2, B*5701 con abacavir.", "pr": "choque tóxico (literatura), fiebre reumática, autoinmunidad o alergia a fármacos.", "pr_tit": "Produce:", "rf": "Preguntas ③⑥⑫⑭ · punto <span class=\"lt2\">C</span>", "color": "p4"}], "extra": [{"html": "🧬 <b>HLA no clásicas:</b> <mark>HLA-G</mark> (y HLA-F) en el trofoblasto protegen al feto inhibiendo a las NK; <b>MICA y MICB</b> señalan a la NK las células estresadas; <b>HFE</b> capta hierro (hemocromatosis); <b>FcRn</b> pasa la IgG materna al bebé. Los genes de <b>clase III</b> codifican C2, C4 y factor B del complemento.", "k": ""}, {"html": "🧪 <b>Tipos de antígeno que caen en examen:</b> xeno (otra especie), alo (otro individuo), auto (propio), <b>oculto</b> (cristalino, cerebro, testículo), <b>heterófilo</b> (mononucleosis: aglutina eritrocitos de carnero), <b>alérgeno</b> (IgE) y <b>toxoide</b> (toxina tetánica + formol).", "k": "k"}], "escaleras": [{"c": "i", "t": "🦠 Vía de la HLA-I (de adentro afuera)", "pasos": ["Proteína viral en el citoplasma", "marca con <b>ubicuitina</b>", "<b>proteosoma</b>: péptidos de 8-10 aa", "<b>TAP</b> al retículo: HLA-I + β2m", "membrana: linfocito T <b>CD8</b> mata"]}, {"c": "d", "t": "🍽️ Vía de la HLA-II (de afuera adentro)", "pasos": ["Bacteria fagocitada", "<b>fagolisosoma</b>: catepsinas", "HLA-II con <b>cadena invariante</b>", "<b>HLA-DM</b> retira el CLIP: péptido de 12-20 aa", "membrana: linfocito T <b>CD4</b> ayuda"]}], "html": "", "fuente": "Fuente: tu teoría — clase 8a (definiciones, inmunogenicidad, haptenos, tipos de antígenos, superantígenos, células presentadoras) y clase 8b (HLA-I, HLA-II, clase III, CD1, HLA no clásicas y asociaciones clínicas)."}, "preguntas": [{"n": 1, "id": "IN4-001", "c": "g", "tema": "Definiciones: inmunógeno y antígeno", "pregunta": "Respecto a inmunógeno y antígeno, es correcto:", "opciones": ["a. Todo inmunógeno es un antígeno.", "b. Antígeno es toda molécula proteica reconocida por el BCR o el TCR que induce anticuerpos o citoquinas.", "c. Los lípidos y los polisacáridos son antígenos porque el BCR los reconoce directamente.", "d. Un hapteno es un antígeno completo por sí solo.", "e. Inmunógeno y antígeno son sinónimos exactos."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Antígeno es la molécula proteica reconocida por BCR o TCR; inmunógeno es cualquier molécula extraña que induce respuesta.", "sin_banco": true, "ok": "", "x": "La bacteria de la derecha es un <mark>inmunógeno</mark> entero; lo que el linfocito T reconoce, <span class=\"cx\">en cambio</span>, es el <b>péptido proteico</b> en la HLA. <span class=\"cx\">Por eso</span> <span class=\"res\">antígeno = proteína reconocida por BCR o TCR</span>: la b.", "truco": "", "veces": 0}, {"n": 2, "id": "IN4-002", "c": "g", "tema": "Haptenos y adyuvantes", "pregunta": "Molécula que solo se vuelve inmunogénica al unirse a una proteína portadora y que explica la alergia a un antibiótico:", "opciones": ["a. Toxoide tetánico", "b. Hidróxido de aluminio", "c. Adyuvante de Freund", "d. Ácido penicilínico", "e. Lipopolisacárido"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Ácido penicilínico, metabolito de la penicilina que actúa como hapteno.", "sin_banco": true, "ok": "", "x": "Un <mark>hapteno</mark> es demasiado pequeño para despertar respuesta solo (menos de 5000 Da). Al pegarse a una proteína del paciente, el conjunto sí es inmunogénico, <span class=\"cx\">por eso</span> aparece la alergia. El aluminio y el Freund son adyuvantes, y el toxoide es una toxina inactivada; <span class=\"cx\">así que</span> <span class=\"res\">el hapteno del examen es el ácido penicilínico</span>.", "truco": "Hapteno = «medio antígeno»: necesita su proteína «pareja».", "veces": 0}, {"n": 3, "id": "IN4-003", "c": "d", "tema": "Superantígenos", "pregunta": "¿Cómo activan los superantígenos a los linfocitos T y en qué se diferencian de un antígeno convencional?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Son toxinas de S. aureus y S. pyogenes que se unen lateralmente y a la vez a la HLA-II y al TCR, sin reconocer el epítope. Activan hasta el 20 % de los linfocitos T, frente al 0,0001 % que activa un antígeno convencional.", "sin_banco": true, "ok": "", "x": "Fíjate en la unión HLA-II → TCR de arriba a la derecha: el péptido entra en el surco. El <mark>superantígeno</mark>, <span class=\"cx\">en cambio</span>, se pega <b>por fuera</b> a los dos, <span class=\"cx\">así que</span> enciende <span class=\"res\">hasta el 20 % de los linfocitos T</span> (punto Ⓓ).", "truco": "", "veces": 0}, {"n": 4, "id": "IN4-004", "c": "g", "tema": "Células presentadoras de antígenos", "pregunta": "Respecto a la célula dendrítica, es FALSO:", "opciones": ["a. Es la célula presentadora de antígenos más potente.", "b. Al capturar un antígeno madura, pierde la caderina E y expresa CCR7.", "c. Llega al ganglio en unas 24 horas.", "d. Si en una semana no encuentra un linfocito T que reconozca su antígeno, muere por apoptosis.", "e. Procesa con gran eficiencia las proteínas grandes porque tiene muchos lisosomas ricos en proteasas."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es falso: tiene pocos lisosomas y pobres en proteasas, así que procesa mal las proteínas grandes.", "sin_banco": true, "ok": "", "x": "La dendrítica de la derecha es la presentadora más potente, pero por <b>viajar</b> y presentar, no por triturar: tiene <mark>pocos lisosomas</mark>. <span class=\"cx\">Por eso</span> <span class=\"res\">la e es la falsa</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN4-005", "c": "d", "tema": "Células presentadoras de antígenos", "pregunta": "¿Cómo captura, procesa y presenta el antígeno un linfocito B?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Su BCR (IgM de membrana) se une al antígeno; el complejo se concentra en un polo de la célula (capping) y se internaliza. Dentro se extrae el fragmento más antigénico, que se acopla a la HLA-II y se presenta a los linfocitos T CD4.", "sin_banco": true, "ok": "", "x": "El linfocito B es una presentadora muy selectiva: su BCR reconoce un único antígeno. Lo agrupa en un polo (<mark>capping</mark>), lo internaliza y lo presenta por HLA-II. <span class=\"cx\">Así que</span> <span class=\"res\">el B muestra al CD4 justo el antígeno contra el que hará anticuerpos</span>.", "truco": "Capping = «gorra»: el B junta el antígeno en un polo.", "veces": 0}, {"n": 6, "id": "IN4-008", "c": "g", "tema": "Tipos de antígenos", "pregunta": "Los anticuerpos contra el estreptococo beta hemolítico que atacan la sinovial, el corazón y el riñón en la fiebre reumática son ejemplo de:", "opciones": ["a. Antígeno heterófilo", "b. Antígeno oculto", "c. Antígeno de reacción cruzada por mimetismo molecular", "d. Superantígeno", "e. Aloantígeno"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Antígeno de reacción cruzada por mimetismo molecular.", "sin_banco": true, "ok": "", "x": "El estreptococo tiene moléculas <mark>parecidas a las propias</mark>, <span class=\"cx\">así que</span> los anticuerpos contra él se equivocan y atacan tejidos sanos. El heterófilo es otra cosa: anticuerpos de la mononucleosis que aglutinan eritrocitos de carnero; el oculto es el que está detrás de una barrera. <span class=\"cx\">Por eso</span> <span class=\"res\">fiebre reumática = mimetismo molecular</span>.", "truco": "Mimetismo = el microbio «se disfraza» de corazón.", "veces": 0}, {"n": 7, "id": "IN4-009", "c": "i", "tema": "Moléculas HLA de clase I", "pregunta": "La molécula HLA de clase I está formada por:", "opciones": ["a. Una cadena α unida no covalentemente a la β2-microglobulina, codificada en el cromosoma 15.", "b. Dos cadenas, α y β, ambas codificadas en el MHC.", "c. Una cadena α unida a la cadena invariante de forma permanente.", "d. Cinco isotipos no polimórficos codificados fuera del MHC.", "e. Una cadena pesada y una ligera de inmunoglobulina."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Una cadena α (cromosoma 6) unida no covalentemente a la β2-microglobulina (cromosoma 15).", "sin_banco": true, "ok": "", "x": "En el retículo del dibujo, cada molécula azul lleva al lado una esfera blanca: la <mark>β2-microglobulina</mark> (cromosoma 15). <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN4-010", "c": "i", "tema": "Moléculas HLA de clase I", "pregunta": "¿Qué tamaño tienen los péptidos que presenta la HLA-I?", "opciones": ["a. 12 a 20 aminoácidos", "b. 30 a 40 aminoácidos", "c. 2 a 4 aminoácidos", "d. Proteínas completas", "e. 8 a 10 aminoácidos"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. 8 a 10 aminoácidos (hasta 11); la HLA-II presenta péptidos más largos, de 12 a 20.", "sin_banco": true, "ok": "", "x": "Compara los péptidos amarillos: cortos al salir del proteosoma (punto Ⓐ, 8-10 aa) y largos en el fagolisosoma (punto Ⓑ, 12-20 aa). <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN4-011", "c": "i", "tema": "Moléculas HLA de clase I", "pregunta": "Describa la vía de procesamiento de un antígeno endógeno (por ejemplo, viral) hasta su presentación por HLA-I.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La proteína se marca con ubicuitina, el proteosoma la fragmenta en péptidos de 8-10 aminoácidos, la TAP los transporta al retículo endoplásmico, se unen al nicho de la HLA-I y el complejo va a la membrana para presentarse a los linfocitos T CD8.", "sin_banco": true, "ok": "", "x": "Es la célula de la izquierda de arriba abajo: virus → <mark>proteosoma</mark> → TAP → retículo → membrana. <span class=\"res\">Cualquier célula nucleada infectada puede avisar al CD8</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN4-012", "c": "d", "tema": "Moléculas HLA de clase II", "pregunta": "En la vía de la HLA-II, la molécula que retira el fragmento CLIP para que se una el péptido antigénico es:", "opciones": ["a. TAP", "b. Calnexina", "c. HLA-DM", "d. Proteosoma", "e. β2-microglobulina"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. HLA-DM, que remueve el CLIP y permite la unión definitiva del péptido de 12-20 aminoácidos.", "sin_banco": true, "ok": "", "x": "La HLA-II naciente (etiqueta inferior) viaja con el surco tapado por la cadena invariante; queda el CLIP y la <mark>HLA-DM</mark> lo retira. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN4-013", "c": "d", "tema": "Moléculas HLA de clase II", "pregunta": "Expresan normalmente moléculas HLA-II, EXCEPTO:", "opciones": ["a. Linfocitos B", "b. Macrófagos", "c. Células dendríticas", "d. Hepatocitos en reposo", "e. Células de Langerhans"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Hepatocitos en reposo: la HLA-II solo se expresa en linfocitos B, macrófagos, dendríticas y Langerhans (inducible en endotelio y fibroblastos por IFN-γ).", "sin_banco": true, "ok": "", "x": "La HLA-I está en todas las células nucleadas, <span class=\"cx\">en cambio</span> la HLA-II <mark>queda reservada a las presentadoras profesionales</mark>: linfocitos B, macrófagos, dendríticas y Langerhans. El IFN-γ puede inducirla en endotelio y fibroblastos. <span class=\"cx\">Así que</span> <span class=\"res\">un hepatocito en reposo solo tiene HLA-I</span>.", "truco": "HLA-II = club exclusivo de presentadoras.", "veces": 0}, {"n": 12, "id": "IN4-014", "c": "i", "tema": "Implicaciones clínicas del sistema HLA", "pregunta": "Señale la asociación INCORRECTA entre alelo HLA y enfermedad:", "opciones": ["a. HLA-B27 – espondilitis anquilosante (riesgo 90 veces mayor)", "b. DQ2 – enfermedad celíaca (riesgo 25 veces mayor)", "c. DQB1*0602 – narcolepsia (presente en el 100 %)", "d. DRB1*0402 – mayor riesgo de artritis reumatoide", "e. B*5701 – hipersensibilidad al abacavir"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Es incorrecta: el DRB1*0402 confiere protección frente a la artritis reumatoide; el riesgo lo dan DRB1*0401, 0404, 0405 y 0408.", "sin_banco": true, "ok": "", "x": "El sistema HLA es un mapa de riesgo: <mark>B27 multiplica por 90</mark> el riesgo de espondilitis y DQ2 por 25 el de celiaquía. Pero no todos los alelos dañan. En la artritis reumatoide los DRB1*0401, 0404, 0405 y 0408 aumentan el riesgo, <span class=\"cx\">en cambio</span> <span class=\"res\">el DRB1*0402 protege</span>.", "truco": "B27 = «Bambú» (columna en caña de bambú: literatura).", "veces": 0}, {"n": 13, "id": "IN4-015", "c": "g", "tema": "El sistema CD1", "pregunta": "¿Qué presenta el sistema CD1 y en qué se diferencia del HLA?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Presenta inmunógenos lipídicos, no péptidos. Sus cinco isotipos (CD1a a CD1e) no son polimórficos y se codifican fuera del MHC; presentan sobre todo a linfocitos T γδ (y a NKT) lípidos de micobacterias, borrelias y leishmanias.", "sin_banco": true, "ok": "", "x": "El HLA lleva péptidos y es muy polimórfico (unos 8500 alelos). El <mark>CD1</mark>, <span class=\"cx\">en cambio</span>, tiene «bolsillos» para lípidos y casi no varía entre personas. <span class=\"cx\">Por eso</span> <span class=\"res\">el ácido micólico de la micobacteria (CD1b) se presenta igual en todos</span>.", "truco": "CD1 = «Con Domicilio para 1ípidos».", "veces": 0}, {"n": 14, "id": "IN4-016", "c": "i", "tema": "Implicaciones clínicas del sistema HLA", "pregunta": "Varón de 34 años con VIH que va a iniciar un esquema con abacavir. ¿Qué estudio genético debe pedirse antes y por qué?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Tipificación de HLA-B*5701: los portadores tienen hipersensibilidad grave al abacavir, así que el cribado previo permite evitar el fármaco en ellos.", "sin_banco": true, "ok": "", "x": "Es farmacogenética aplicada: un alelo HLA determina cómo se presenta el fármaco al sistema inmune. Los portadores de <mark>HLA-B*5701</mark> hacen una reacción de hipersensibilidad grave, <span class=\"cx\">por eso</span> se busca el alelo antes de empezar. Del mismo modo, <span class=\"res\">B*1502 con carbamazepina y B*5801 con alopurinol</span>.", "truco": "Abacavir «57-01»: primero el test, después la pastilla.", "veces": 0}], "tabla": {"cab": ["", "HLA-I", "HLA-II", "CD1"], "filas": [["Estructura", "Cadena α + β2-microglobulina", "Cadenas α y β del MHC", "Cinco isotipos (a-e), no polimórficos"], ["Dónde está", "Todas las células nucleadas (no neuronas ni eritrocitos)", "B, macrófagos, dendríticas, Langerhans", "Presentadoras; codificada fuera del MHC"], ["Qué presenta", "Péptidos internos de 8-10 aa", "Péptidos externos de 12-20 aa", "Lípidos (ácido micólico en CD1b)"], ["A quién", "Linfocito T CD8", "Linfocito T CD4", "T γδ y NKT"], ["🔑 Para diferenciar", "Interior → CD8: proteosoma y TAP", "Exterior → CD4: cadena invariante y HLA-DM", "Lípidos, casi igual en todos"]]}, "fuente": "Fuente: tu teoría — clases 8a (Inmunógenos y antígenos) y 8b (Presentación antigénica y sistema HLA), Rojas 17.ª ed."}, {"n": 8, "slug": "Organos_linfoides", "titulo": "Órganos linfoides", "subtitulo": "dónde nacen, se educan y se encuentran los linfocitos", "grupo": "g4", "lema": "La idea: los linfocitos <b>nacen en la médula ósea</b>; los B maduran allí y en el bazo, y los T van a la <mark>escuela del timo</mark>, donde solo «se gradúan» los que reconocen el HLA propio sin atacar lo propio. Ya maduros, viven de <b>encuentro en encuentro</b>: entran a los <mark>órganos secundarios</mark> (ganglios, bazo, placas de Peyer, amígdalas) por las vénulas de endotelio alto y allí buscan su antígeno. Cada órgano tiene <u>una zona T y una zona B</u>. Importa porque una lesión en cualquiera de ellos da una inmunodeficiencia predecible: sin timo, falla la inmunidad celular; sin bazo, sepsis por neumococo. En la imagen verás un lobulillo del timo, un ganglio cortado por la mitad con una ampliación de la vénula de endotelio alto, una placa de Peyer y un corte de bazo.", "img": "img/08.webp", "mini": "img/mini/08.webp", "ratio": 1.5, "etiquetas": [{"n": "③", "t": "Corteza del timo", "s": "selección positiva:<br>reconoce HLA propio", "c": "i", "x": 0.5, "y": 6, "ax": 21.5, "ay": 29.3, "al": "l"}, {"n": "⑧", "t": "Folículo", "s": "centro germinal:<br>LsB sobre las FDC", "c": "d", "x": 29, "y": 6, "ax": 37.8, "ay": 45}, {"n": "", "t": "Aferentes", "s": "linfa con<br>antígeno", "c": "g", "x": 46, "y": 6, "ax": 47.9, "ay": 23.4, "d": "B"}, {"n": "⑦", "t": "Vénula HEV", "s": "entra el<br>linfocito virgen", "c": "g", "x": 64, "y": 6, "ax": 65.4, "ay": 29.3, "d": "C"}, {"n": "⑨", "t": "Placa de Peyer", "s": "células M: IgA<br>de las mucosas", "c": "d", "x": 99.5, "y": 6, "ax": 84.6, "ay": 22, "d": "E", "al": "r"}, {"n": "④⑩", "t": "Médula y Hassall", "s": "AIRE: selección negativa;<br>Hassall induce Treg", "c": "i", "x": 0.5, "y": 91, "ax": 10.4, "ay": 54.7, "d": "A", "al": "l"}, {"n": "", "t": "Paracorteza", "s": "linfocitos T y FRC<br>(IL-7, CCL19)", "c": "i", "x": 35, "y": 91, "ax": 45.6, "ay": 46}, {"n": "", "t": "Hilio", "s": "arteria, vena y<br>linfático eferente", "c": "g", "x": 53, "y": 91, "ax": 52.7, "ay": 74}, {"n": "⑤", "t": "Pulpa blanca (PALS)", "s": "linfocitos T CD4<br>junto a la arteriola", "c": "i", "x": 72, "y": 91, "ax": 77.5, "ay": 58.1, "d": "D"}, {"n": "①②⑥", "t": "Zona marginal", "s": "linfocitos B: IgM<br>contra polisacáridos", "c": "d", "x": 99.5, "y": 91, "ax": 84.6, "ay": 64.5, "al": "r"}], "diapos": [{"img": "img/08.webp", "ratio": 1.5, "titulo": "Timo, ganglio, bazo y placa de Peyer", "texto": "Los <mark>primarios</mark> educan (timo ③④⑩); los <mark>secundarios</mark> reúnen linfocito y antígeno: folículo B ⑧, HEV ⑦, PALS y zona marginal ⑤⑥.", "etiquetas": [{"n": "③", "t": "Corteza del timo", "s": "selección positiva:<br>reconoce HLA propio", "c": "i", "x": 0.5, "y": 6, "ax": 21.5, "ay": 29.3, "al": "l"}, {"n": "⑧", "t": "Folículo", "s": "centro germinal:<br>LsB sobre las FDC", "c": "d", "x": 29, "y": 6, "ax": 37.8, "ay": 45}, {"n": "", "t": "Aferentes", "s": "linfa con<br>antígeno", "c": "g", "x": 46, "y": 6, "ax": 47.9, "ay": 23.4, "d": "B"}, {"n": "⑦", "t": "Vénula HEV", "s": "entra el<br>linfocito virgen", "c": "g", "x": 64, "y": 6, "ax": 65.4, "ay": 29.3, "d": "C"}, {"n": "⑨", "t": "Placa de Peyer", "s": "células M: IgA<br>de las mucosas", "c": "d", "x": 99.5, "y": 6, "ax": 84.6, "ay": 22, "d": "E", "al": "r"}, {"n": "④⑩", "t": "Médula y Hassall", "s": "AIRE: selección negativa;<br>Hassall induce Treg", "c": "i", "x": 0.5, "y": 91, "ax": 10.4, "ay": 54.7, "d": "A", "al": "l"}, {"n": "", "t": "Paracorteza", "s": "linfocitos T y FRC<br>(IL-7, CCL19)", "c": "i", "x": 35, "y": 91, "ax": 45.6, "ay": 46}, {"n": "", "t": "Hilio", "s": "arteria, vena y<br>linfático eferente", "c": "g", "x": 53, "y": 91, "ax": 52.7, "ay": 74}, {"n": "⑤", "t": "Pulpa blanca (PALS)", "s": "linfocitos T CD4<br>junto a la arteriola", "c": "i", "x": 72, "y": 91, "ax": 77.5, "ay": 58.1, "d": "D"}, {"n": "①②⑥", "t": "Zona marginal", "s": "linfocitos B: IgM<br>contra polisacáridos", "c": "d", "x": 99.5, "y": 91, "ax": 84.6, "ay": 64.5, "al": "r"}]}, {"img": "img/08_2.webp", "ratio": 1.5, "titulo": "Cómo entra el linfocito virgen al ganglio", "texto": "En la <mark>vénula de endotelio alto</mark>, la <b>selectina L</b> rueda sobre la adresina CD34; <span class=\"cx\">luego</span> <b>LFA-1</b> se pega a ICAM-1/2 y el eje CCR7-CCL21/CCL19 lo hace pasar ⑦.", "etiquetas": [{"n": "⑦", "t": "Adresina CD34", "s": "mucina del<br>endotelio alto", "c": "g", "x": 0.5, "y": 6, "ax": 8.5, "ay": 42, "al": "l"}, {"n": "⑦", "t": "1. Rodamiento", "s": "la selectina L<br>se engancha a CD34", "c": "i", "x": 25, "y": 6, "ax": 17, "ay": 30}, {"n": "⑦", "t": "2. LFA-1", "s": "integrina: adhesión<br>firme a ICAM-1/2", "c": "i", "x": 45, "y": 6, "ax": 47.5, "ay": 42}, {"n": "⑦", "t": "CCL21 / CCL19", "s": "quimioquinas<br>para el CCR7", "c": "g", "x": 64, "y": 6, "ax": 62, "ay": 43.5}, {"n": "⑦", "t": "3. Diapédesis", "s": "pasa entre dos<br>células endoteliales", "c": "i", "x": 99.5, "y": 6, "ax": 84, "ay": 50, "al": "r"}, {"n": "", "t": "Endotelio alto", "s": "células cúbicas<br>de la HEV", "c": "g", "x": 0.5, "y": 91, "ax": 19.5, "ay": 53, "al": "l"}, {"n": "", "t": "LsT virgen adentro", "s": "busca su antígeno<br>en la paracorteza", "c": "i", "x": 26, "y": 91, "ax": 30, "ay": 66, "d": "C"}, {"n": "⑦", "t": "ICAM-1/2", "s": "ligando de<br>la LFA-1", "c": "g", "x": 47, "y": 91, "ax": 54.5, "ay": 47}, {"n": "", "t": "Red de FRC", "s": "fibroblastos<br>reticulares", "c": "g", "x": 68, "y": 91, "ax": 65, "ay": 69}]}, {"img": "img/08_3.webp", "ratio": 1.5, "titulo": "Polisacárido solo frente a vacuna conjugada", "texto": "El polisacárido entrecruza BCR y da solo <mark>IgM</mark> sin memoria ①; unido a una <b>proteína</b> trae la ayuda T, <span class=\"cx\">por eso</span> la vacuna Hib protege ②. Sin bazo se pierde esa defensa contra los encapsulados ⑥.", "etiquetas": [{"n": "①", "t": "Polisacárido lineal", "s": "repetitivo:<br>T-independiente", "c": "d", "x": 0.5, "y": 6, "ax": 19.5, "ay": 27, "al": "l"}, {"n": "①⑥", "t": "LB de zona marginal", "s": "BCR entrecruzados,<br>sin ayuda T", "c": "d", "x": 28.0, "y": 6, "ax": 25, "ay": 40}, {"n": "①", "t": "IgM", "s": "baja afinidad,<br>poca memoria", "c": "d", "x": 47.0, "y": 6, "ax": 39, "ay": 36}, {"n": "②", "t": "HLA-II → LsT CD4", "s": "la proteína trae<br>la ayuda T", "c": "i", "x": 64, "y": 6, "ax": 79, "ay": 43}, {"n": "②", "t": "Proteína portadora", "s": "vacuna conjugada<br>contra Hib", "c": "i", "x": 99.5, "y": 6, "ax": 79, "ay": 18, "al": "r"}, {"n": "⑥", "t": "Sin bazo", "s": "pierde tuftsina y LB<br>de zona marginal", "c": "g", "x": 31, "y": 91, "ax": 36.5, "ay": 80, "al": "r"}, {"n": "⑥", "t": "Neumococo", "s": "encapsulado: sepsis<br>fulminante", "c": "g", "x": 64, "y": 91, "ax": 55, "ay": 86}, {"n": "②", "t": "IgG y LB de memoria", "s": "respuesta protectora<br>y duradera", "c": "i", "x": 99.5, "y": 91, "ax": 92.5, "ay": 60.5, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = territorio de linfocitos T</b> (timo, paracorteza, PALS), <b class=\"d\">rojo = territorio de linfocitos B</b> (folículos, zona marginal, placa de Peyer), gris = vasos por donde entran y salen.", "<b>Timo (izquierda):</b> la <mark>corteza</mark> oscura está llena de timocitos que aprenden a reconocer el HLA propio (selección positiva); la <mark>médula</mark> pálida, con los corpúsculos de Hassall, elimina a los autorreactivos gracias a <b>AIRE</b> (selección negativa) <span class=\"lt2\">A</span>.", "<b>Ganglio (centro):</b> la linfa entra por los aferentes <span class=\"lt2\">B</span>; los linfocitos vírgenes, por las vénulas de endotelio alto <span class=\"lt2\">C</span>. Los B se juntan en los <b>folículos</b> (FDC) y los T en la <b>paracorteza</b> (FRC). Todo sale por el hilio.", "<b>Derecha:</b> la placa de Peyer <span class=\"lt2\">E</span> toma antígenos de la luz intestinal por las células M. En el bazo <span class=\"lt2\">D</span>, la <mark>pulpa blanca</mark> (PALS + folículos) es lo linfoide; la <b>pulpa roja</b> (lo rojo del dibujo) son cordones con macrófagos y senos que depuran eritrocitos viejos."], "recordar": "<b>Primarios</b> (médula, timo) = nacer y educarse; <b>secundarios</b> (ganglio, bazo, MALT) = encontrar el antígeno; <b>terciarios</b> (granulomas) = solo en inflamación crónica, sin cápsula."}, "numeros": [{"l": "A", "html": "<b>Timo</b>: <b class=\"n\">40 g</b> a los 7 años y <b class=\"b\">12 g</b> hacia los 30, pero activo toda la vida. De <b class=\"n\">60 millones</b> de linfocitos T evaluados al día se gradúan solo <b class=\"a\">un par de millones</b>.", "rango": null}, {"l": "B", "html": "<b>Ganglios</b>: unos <b class=\"n\">450</b>; la linfa circula a razón de <b class=\"n\">2 litros</b> diarios.", "rango": null}, {"l": "C", "html": "<b>Dentro del ganglio</b>: el linfocito T virgen recorre hasta <b class=\"n\">15 000 km</b> al día y ve unas <b class=\"n\">5000</b> dendríticas por hora.", "rango": null}, {"l": "D", "html": "<b>Bazo</b>: <b class=\"n\">12 cm</b>; guarda el <b class=\"n\">25 %</b> de los linfocitos y recibe el <b class=\"n\">5 %</b> del gasto cardíaco: revisa toda la sangre cada <b class=\"n\">media hora</b>.", "rango": null}, {"l": "E", "html": "<b>Placas de Peyer</b>: unas <b class=\"n\">200</b> en el intestino del adulto.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la médula al encuentro", "subtitulo": "origen → educación → entrada → encuentro con el antígeno → salida (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Médula ósea", "m": "<b>Qué pasa:</b> en la médula (3–4 kg en el adulto) la <mark>CXCL12</mark> del estroma retiene a las células madre (receptor CXCR4). El pro-B pasa a pre-B y adquiere el BCR (IgM + IgD); el B que reconoce lo propio muere o lo elimina el bazo.", "pr": "linfocitos B maduros y precursores T que viajan al timo.", "pr_tit": "Produce:", "rf": "Pregunta ① (los B de la médula y el bazo)", "color": "p1"}, {"t": "2. Timo", "m": "<b>Por qué se educa:</b> el pre-T entra «desnudo» por la unión córtico-medular, se vuelve doble positivo en la corteza (<mark>selección positiva</mark>) y en la médula muere si ataca lo propio (<mark>selección negativa</mark>, AIRE).", "pr": "linfocitos T CD4, CD8, Treg, γδ e iNKT; los RTE maduran 3 semanas más.", "pr_tit": "Produce:", "rf": "Preguntas ③④⑩ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Entrada al ganglio", "m": "<b>Cómo entra:</b> por la vénula de endotelio alto: <mark>selectina L con adresina CD34</mark>, LFA-1 con ICAM-1/2 y CCR7 siguiendo a CCL21 y CCL19.", "pr": "el linfocito virgen llega a su zona: T a la paracorteza, B al folículo.", "pr_tit": "Produce:", "rf": "Pregunta ⑦ · punto <span class=\"lt2\">C</span>", "color": "p3"}, {"t": "4. Encuentro", "m": "<b>Qué produce:</b> las FRC sostienen a los T (IL-7) y las <mark>FDC</mark> muestran complejos inmunes a los B. En el bazo, la zona marginal hace IgM contra polisacáridos sin ayuda T; en Peyer, las <b>células M</b> inducen IgA.", "pr": "activación, centros germinales y expansión clonal.", "pr_tit": "Produce:", "rf": "Preguntas ①②⑤⑧⑨ · puntos <span class=\"lt2\">B</span><span class=\"lt2\">D</span>", "color": "p4"}, {"t": "5. Salida", "m": "<b>Por qué recircula:</b> la <mark>esfingosina-1-fosfato</mark> saca al linfocito del ganglio; si se bloquea, queda retenido. El virgen que no halla su antígeno muere en semanas; el de memoria recircula.", "pr": "linfocitos activados al tejido inflamado; memoria en circulación.", "pr_tit": "Produce:", "rf": "Pregunta ⑦", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Médula:</b> benzol, cloranfenicol o radiación → anemia aplásica. <b>Timo ausente:</b> falla la inmunidad celular. <b>Sin bazo:</b> sepsis por neumococo, meningococo y hemófilos (sin tuftsina). <b>Sin B:</b> agammaglobulinemia; <b>sin T ni B:</b> inmunodeficiencia combinada severa.", "pr": "inmunodeficiencias específicas y predecibles.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑩", "color": "p4"}], "extra": [{"html": "🧒 <b>Subpoblaciones de linfocitos B:</b> B-2 foliculares (circulan, viven 8 semanas), B de <mark>zona marginal</mark> (bazo: IgM contra polisacáridos sin ayuda T) y B-1 (CD5+, pleura, peritoneo y anillo de Waldeyer: anticuerpos «naturales»). <span class=\"cx\">Por eso</span> los antígenos <b>T-independientes tipo II</b> (cápsulas) dan IgM de baja afinidad, y la vacuna contra <b>Haemophilus</b> tuvo que <b>conjugarse</b> a una proteína.", "k": ""}, {"html": "💋 <b>¿Por qué las madres besan a sus bebés?</b> (Sompayrac, citado en la clase): toman muestras de los gérmenes de la piel del bebé, sus amígdalas fabrican IgA y esa IgA sale en la leche materna. El anillo de Waldeyer (amígdalas faríngea, palatinas y linguales) es el sistema inmune de la boca.", "k": "k"}], "escaleras": [{"c": "i", "t": "🎓 La escuela del timo", "pasos": ["Pre-T «desnudo» (sin CD4, CD8 ni TCR)", "corteza: adquiere TCR, <b>doble positivo</b>", "<b>selección positiva</b>: reconoce HLA propio", "pierde CD4 o CD8 y baja a la médula", "<b>selección negativa</b> (AIRE): de 60 millones, se gradúan un par de millones"]}], "html": "", "fuente": "Fuente: tu teoría — clase 9 (médula ósea, timo, ganglios, bazo, MALT, órganos terciarios, circulación y correlato clínico) y clase 8a (antígenos T-independientes y vacuna conjugada contra Haemophilus)."}, "preguntas": [{"n": 1, "id": "IN4-006", "c": "d", "tema": "Tipos de antígenos", "pregunta": "Respecto a los antígenos T-independientes tipo II, es correcto:", "opciones": ["a. Ingresan por la orofaringe y activan policlonalmente a los linfocitos B en el anillo de Waldeyer.", "b. Necesitan la ayuda de los linfocitos T CD4 para inducir anticuerpos.", "c. Son moléculas lineales no degradadas con determinantes repetitivos que generan IgM de baja afinidad y escasa memoria.", "d. Son proteínas globulares que inducen IgG de alta afinidad.", "e. Se presentan por moléculas CD1 a los linfocitos T γδ."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Son moléculas lineales no degradadas con determinantes repetitivos (polisacáridos capsulares) que generan IgM de baja afinidad y poca memoria.", "sin_banco": true, "ok": "", "x": "Los polisacáridos repetitivos los atienden los <mark>linfocitos B de la zona marginal</mark> del bazo (abajo a la derecha), sin ayuda T. <span class=\"cx\">Por eso</span> la respuesta es <span class=\"res\">IgM de baja afinidad y poca memoria</span>: la c.", "truco": "", "veces": 0}, {"n": 2, "id": "IN4-007", "c": "d", "tema": "Composición química de los inmunógenos", "pregunta": "Una madre pregunta por qué la vacuna de su bebé contra Haemophilus influenzae tipo b lleva el polisacárido de la cápsula «unido a una proteína». ¿Qué le explicaría?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El carbohidrato capsular solo genera una respuesta pobre (antígeno T-independiente). Al acoplarlo a una proteína portadora se vuelve antigénico y la respuesta es protectora; por eso la vacuna solo fue eficaz con ese diseño conjugado.", "sin_banco": true, "ok": "", "x": "Los carbohidratos son inmunógenos, pero el BCR reconoce mal lo que no es proteína. Al <mark>conjugarlo con una proteína portadora</mark>, el polisacárido entra en la vía de la ayuda T, <span class=\"cx\">así que</span> se gana afinidad y memoria (literatura), algo clave en el lactante. <span class=\"cx\">Por eso</span> <span class=\"res\">la vacuna contra Haemophilus solo funcionó al conjugarla</span>.", "truco": "Conjugar = darle al azúcar una «pareja» proteica.", "veces": 0}, {"n": 3, "id": "IN4-017", "c": "i", "tema": "Órganos linfoides primarios: timo", "pregunta": "Respecto a la selección de los timocitos, es correcto:", "opciones": ["a. La selección positiva ocurre en la médula y depende de AIRE.", "b. Los pre-T entran al timo ya como doble positivos CD4+CD8+.", "c. En la selección negativa sobreviven los que reaccionan ávidamente contra lo propio.", "d. De 60 millones de linfocitos T evaluados al día se gradúan unos 50 millones.", "e. En la corteza sobreviven solo los timocitos cuyo TCR reconoce alguna molécula HLA propia."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. En la corteza (selección positiva) sobreviven los timocitos cuyo TCR reconoce HLA propio; el resto muere por apoptosis.", "sin_banco": true, "ok": "", "x": "En la <mark>corteza</mark> oscura del timo (izquierda) sobrevive quien reconoce el HLA propio; en la médula pálida se elimina al autorreactivo. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN4-018", "c": "i", "tema": "Órganos linfoides primarios: timo", "pregunta": "¿Qué función cumple la molécula AIRE en la médula tímica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Ayuda a las células epiteliales medulares a presentar antígenos propios de órganos periféricos (páncreas, corazón, riñón) a los timocitos, para eliminar por selección negativa a los clones autorreactivos y evitar la autoinmunidad.", "sin_banco": true, "ok": "", "x": "El timo no tiene páncreas ni riñón, pero necesita «enseñar» esos antígenos. <mark>AIRE</mark> hace que las células epiteliales medulares los expresen, <span class=\"cx\">así que</span> los timocitos que reaccionan contra ellos mueren. Es la base de la <span class=\"res\">tolerancia central</span>; sin AIRE hay autoinmunidad de múltiples órganos (literatura).", "truco": "AIRE = el «aire» que trae al timo los antígenos de todo el cuerpo.", "veces": 0}, {"n": 5, "id": "IN4-019", "c": "i", "tema": "Órganos linfoides secundarios: bazo", "pregunta": "Respecto al bazo, es FALSO:", "opciones": ["a. Alberga el 25 % de todos los linfocitos del organismo.", "b. La pulpa roja contiene las vainas periarteriolares de linfocitos T CD4 (PALS).", "c. Recibe el 5 % del gasto cardíaco en cada sístole.", "d. Produce tuftsina, que estimula la fagocitosis.", "e. Su zona marginal alberga linfocitos B de zona marginal y LsB-1."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Es falso: las PALS y los folículos de linfocitos B forman la pulpa blanca; la pulpa roja son cordones ricos en macrófagos.", "sin_banco": true, "ok": "", "x": "Mira el bazo: los islotes morados con su arteriola son la <mark>pulpa blanca</mark> (PALS + folículos); lo rojo alrededor es la pulpa roja. <span class=\"cx\">Por eso</span> <span class=\"res\">la b es la falsa</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN4-020", "c": "d", "tema": "Correlato clínico", "pregunta": "Joven de 19 años esplenectomizado tras un accidente hace un año ingresa con sepsis fulminante por neumococo. ¿Por qué el paciente sin bazo es tan susceptible a este germen?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque pierde la tuftsina, tetrapéptido esplénico que estimula la fagocitosis de microbios opsonizados por complemento, como neumococos y hemófilos; además pierde los linfocitos B de zona marginal, que producen IgM contra polisacáridos sin ayuda T.", "sin_banco": true, "ok": "", "x": "El neumococo tiene cápsula de polisacárido. Contra él sirven la <mark>IgM de la zona marginal</mark> y la fagocitosis potenciada por la <mark>tuftsina</mark>, y las dos dependen del bazo. Sin bazo falla ese filtro, <span class=\"cx\">así que</span> <span class=\"res\">meningococo, neumococo y hemófilos causan septicemias graves</span>.", "truco": "Sin bazo, las bacterias «encapsuladas» pasan sin filtro.", "veces": 0}, {"n": 7, "id": "IN4-021", "c": "g", "tema": "Órganos linfoides secundarios: ganglios", "pregunta": "En la vénula de endotelio alto (HEV), la selectina L del linfocito virgen se une a:", "opciones": ["a. La adresina CD34", "b. ICAM-1", "c. La quimioquina CCL21", "d. La esfingosina-1-fosfato", "e. El CD1d"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La adresina CD34; luego LFA-1 se une a ICAM-1/2 y el eje CCR7-CCL21/CCL19 completa la entrada.", "sin_banco": true, "ok": "", "x": "Es la ampliación circular (punto Ⓒ): el linfocito cruza la vénula de endotelio alto <span class=\"cx\">porque</span> su <mark>selectina L</mark> se une a la adresina CD34. <span class=\"res\">La salida, <span class=\"cx\">en cambio</span>, la controla la S1P</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN4-022", "c": "d", "tema": "Órganos linfoides secundarios: ganglios", "pregunta": "Las células dendríticas foliculares (FDC) del ganglio linfático:", "opciones": ["a. Producen IL-7 y CCL19 para sostener a los linfocitos T de la paracorteza.", "b. Presentan péptidos por HLA-I a los linfocitos T CD8.", "c. Viajan desde la piel al ganglio en 24 horas.", "d. Capturan complejos inmunes, los presentan a los linfocitos B de los folículos y producen BAFF.", "e. Son linfocitos B de memoria."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Capturan complejos inmunes y los presentan a los linfocitos B de los folículos; producen BAFF.", "sin_banco": true, "ok": "", "x": "El ganglio tiene dos estromas organizadores. Las FRC sostienen a los T en la paracorteza con IL-7 y CCL19; las <mark>FDC</mark>, <span class=\"cx\">en cambio</span>, viven en los folículos y muestran complejos inmunes intactos a los linfocitos B. <span class=\"cx\">Por eso</span> <span class=\"res\">FDC = folículo = linfocito B</span>.", "truco": "FDC = «Folículo De Células B»; FRC = «Fibroblasto Retícula» de los T.", "veces": 0}, {"n": 9, "id": "IN4-023", "c": "d", "tema": "MALT y tejidos asociados", "pregunta": "¿Cuál es la función de las células M en las placas de Peyer?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Carecen de vellosidades y capturan microorganismos de la luz intestinal para entregarlos dentro de la placa a linfocitos de memoria programados para producir IgA.", "sin_banco": true, "ok": "", "x": "El epitelio intestinal es una barrera, pero el sistema inmune necesita «probar» lo que hay en la luz. Las <mark>células M</mark> son la ventana: sin vellosidades, capturan microbios y los pasan a la placa de Peyer. <span class=\"cx\">Así que</span> <span class=\"res\">inducen IgA, el anticuerpo de las mucosas</span>; hay unas 200 placas en el adulto.", "truco": "M = «Muestreo» (y «Mensajera» hacia la IgA).", "veces": 0}, {"n": 10, "id": "IN4-024", "c": "i", "tema": "Órganos linfoides primarios: timo", "pregunta": "Respecto al timo, es correcto:", "opciones": ["a. Alcanza su mayor tamaño hacia los 30 años.", "b. Deja de funcionar por completo después de la pubertad.", "c. Pesa unos 40 g a los siete años y unos 12 g hacia los treinta, pero sigue activo toda la vida.", "d. Está en el mediastino posterior.", "e. Es un órgano linfoide secundario."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Pesa unos 40 g a los siete años y 12 g hacia los treinta, aunque permanece activo toda la vida.", "sin_banco": true, "ok": "", "x": "El timo, en el mediastino anterosuperior, es <mark>máximo en el período perinatal</mark> y <span class=\"cx\">luego</span> involuciona. Aun así no se apaga: sigue produciendo linfocitos T toda la vida. <span class=\"cx\">Por eso</span> su ausencia congénita causa <span class=\"res\">inmunodeficiencia celular grave</span>, con infecciones por virus, hongos, parásitos y bacterias intracelulares.", "truco": "«7 años, 40 g; 30 años, 12 g»: se encoge pero no se apaga.", "veces": 0}], "tabla": {"cab": ["", "Timo", "Ganglio linfático", "Bazo", "Placa de Peyer"], "filas": [["Tipo", "Primario", "Secundario", "Secundario", "Secundario (MALT)"], ["Zona T", "Corteza y médula", "Paracorteza (FRC)", "PALS de la pulpa blanca", "Entre folículos (literatura)"], ["Zona B", "—", "Folículos (FDC)", "Folículos y zona marginal", "Folículo bajo la cúpula"], ["Qué filtra", "Educa a los T", "La linfa", "La sangre", "La luz intestinal (células M)"], ["🔑 Si falta", "Falla la inmunidad celular", "Sin sitio de encuentro regional (literatura)", "Sepsis por encapsulados", "Menos IgA intestinal (literatura)"]]}, "fuente": "Fuente: tu teoría — clase 9 (Órganos linfoides y ontogenia de los linfocitos) y clase 8a (antígenos T-independientes y vacuna conjugada), Rojas 17.ª ed."}, {"n": 9, "slug": "Linfocito_T", "titulo": "El linfocito T: dos señales y una especialidad", "subtitulo": "sinapsis, clon, subpoblaciones y citotoxicidad", "grupo": "g5", "lema": "La idea: un linfocito T virgen <b>no se activa con solo ver su antígeno</b>. Necesita la <b class=\"i\">primera señal</b> (TCR que reconoce el péptido en una molécula HLA) y la <b class=\"i\">segunda señal</b> (CD28 con CD80/86). Con las dos fabrica IL-2, se multiplica en un clon y se especializa: los CD4 en Th1, Th2, Th17, Tfh o Treg según las citoquinas del ambiente; los CD8 en <b class=\"d\">citotóxicos que matan</b>. Importa porque si falla el freno (Treg, CTLA-4) aparece la autoinmunidad, como el síndrome IPEX. En la imagen verás de izquierda a derecha: la sinapsis, el clon y la muerte de la célula blanco.", "img": "img/09.webp", "mini": "img/mini/09.webp", "ratio": 1.5, "etiquetas": [{"n": "①②③", "t": "Centro de la sinapsis", "s": "TCR-péptido-HLA (1.ª señal)<br>+ CD28-CD80/86 (2.ª)", "c": "i", "x": 0.8, "y": 6, "ax": 19.5, "ay": 48, "d": "A", "al": "l"}, {"n": "⑨", "t": "IL-2", "s": "receptor CD25<br>de alta afinidad", "c": "g", "x": 32, "y": 6, "ax": 42.6, "ay": 42.5, "d": "C"}, {"n": "④⑤⑥⑦", "t": "Clon", "s": "Th1, Th2, Th17,<br>Tfh o Treg", "c": "i", "x": 50, "y": 6, "ax": 52, "ay": 24, "d": "D"}, {"n": "⑧", "t": "LsT citotóxico", "s": "CD8 activado", "c": "d", "x": 67, "y": 6, "ax": 71, "ay": 40}, {"n": "⑧", "t": "Poros de perforina", "s": "por ahí entran<br>las granzimas", "c": "d", "x": 99.2, "y": 6, "ax": 83, "ay": 45.5, "al": "r"}, {"n": "", "t": "Célula dendrítica", "s": "presenta el péptido<br>en HLA y CD80/86", "c": "i", "x": 0.8, "y": 90, "ax": 8, "ay": 60, "al": "l"}, {"n": "", "t": "Anillo de adhesión", "s": "LFA-1-ICAM-1:<br>contacto de horas", "c": "g", "x": 25, "y": 90, "ax": 20.5, "ay": 57}, {"n": "", "t": "LsT virgen", "s": "núcleo denso;<br>busca su antígeno", "c": "i", "x": 40, "y": 90, "ax": 28, "ay": 57, "d": "B"}, {"n": "⑨", "t": "Linfoblasto", "s": "se divide; muere<br>el 90 %", "c": "g", "x": 54, "y": 90, "ax": 49, "ay": 55}, {"n": "⑧", "t": "Gránulos", "s": "perforinas, granzimas,<br>granulolisinas", "c": "d", "x": 69.5, "y": 90, "ax": 79, "ay": 52}, {"n": "⑧", "t": "Blanco en apoptosis", "s": "burbujas; núcleo<br>fragmentado", "c": "d", "x": 99.2, "y": 90, "ax": 91, "ay": 55, "al": "r"}], "diapos": [{"img": "img/09.webp", "ratio": 1.5, "titulo": "Sinapsis, clon y citotoxicidad", "texto": "Las dos señales encienden al LsT ①②, la IL-2 lo multiplica en un clon ⑨ y el citotóxico mata con <mark>perforinas y granzimas</mark> ⑧.", "etiquetas": [{"n": "①②③", "t": "Centro de la sinapsis", "s": "TCR-péptido-HLA (1.ª señal)<br>+ CD28-CD80/86 (2.ª)", "c": "i", "x": 0.8, "y": 6, "ax": 19.5, "ay": 48, "d": "A", "al": "l"}, {"n": "⑨", "t": "IL-2", "s": "receptor CD25<br>de alta afinidad", "c": "g", "x": 32, "y": 6, "ax": 42.6, "ay": 42.5, "d": "C"}, {"n": "④⑤⑥⑦", "t": "Clon", "s": "Th1, Th2, Th17,<br>Tfh o Treg", "c": "i", "x": 50, "y": 6, "ax": 52, "ay": 24, "d": "D"}, {"n": "⑧", "t": "LsT citotóxico", "s": "CD8 activado", "c": "d", "x": 67, "y": 6, "ax": 71, "ay": 40}, {"n": "⑧", "t": "Poros de perforina", "s": "por ahí entran<br>las granzimas", "c": "d", "x": 99.2, "y": 6, "ax": 83, "ay": 45.5, "al": "r"}, {"n": "", "t": "Célula dendrítica", "s": "presenta el péptido<br>en HLA y CD80/86", "c": "i", "x": 0.8, "y": 90, "ax": 8, "ay": 60, "al": "l"}, {"n": "", "t": "Anillo de adhesión", "s": "LFA-1-ICAM-1:<br>contacto de horas", "c": "g", "x": 25, "y": 90, "ax": 20.5, "ay": 57}, {"n": "", "t": "LsT virgen", "s": "núcleo denso;<br>busca su antígeno", "c": "i", "x": 40, "y": 90, "ax": 28, "ay": 57, "d": "B"}, {"n": "⑨", "t": "Linfoblasto", "s": "se divide; muere<br>el 90 %", "c": "g", "x": 54, "y": 90, "ax": 49, "ay": 55}, {"n": "⑧", "t": "Gránulos", "s": "perforinas, granzimas,<br>granulolisinas", "c": "d", "x": 69.5, "y": 90, "ax": 79, "ay": 52}, {"n": "⑧", "t": "Blanco en apoptosis", "s": "burbujas; núcleo<br>fragmentado", "c": "d", "x": 99.2, "y": 90, "ax": 91, "ay": 55, "al": "r"}]}, {"img": "img/09_2.webp", "ratio": 1.5, "titulo": "Las dos señales y el freno CTLA-4", "texto": "Solo con el TCR no basta: la <mark>CD28</mark> da la 2.ª señal, pero <b>sola no activa</b> ②③. <span class=\"cx\">Luego</span> la <mark>CTLA-4</mark> le quita el CD80/86 <span class=\"cx\">porque</span> es mil veces más afín <span class=\"lt2\">D</span>, y el LsT se apaga ⑨.", "etiquetas": [{"n": "②", "t": "Solo 1.ª señal", "s": "sin coestimulación,<br>el LsT no despierta", "c": "g", "x": 0.5, "y": 6, "ax": 15.6, "ay": 32, "al": "l"}, {"n": "②", "t": "LsT activado", "s": "las dos señales:<br>crece y se divide", "c": "i", "x": 30, "y": 6, "ax": 44, "ay": 26}, {"n": "⑨", "t": "IL-2", "s": "la CD28 sostiene<br>su producción", "c": "i", "x": 50, "y": 6, "ax": 59.6, "ay": 29, "d": "C"}, {"n": "⑨", "t": "LsT frenado", "s": "baja la IL-2 y<br>se detiene el ciclo", "c": "g", "x": 70, "y": 6, "ax": 80.7, "ay": 31}, {"n": "⑨", "t": "CTLA-4 (CD152)", "s": "mil veces más afín<br>por CD80/86", "c": "d", "x": 99.5, "y": 6, "ax": 87, "ay": 49, "d": "D", "al": "r"}, {"n": "①②", "t": "1.ª señal", "s": "TCR + péptido<br>en la HLA", "c": "i", "x": 0.5, "y": 91, "ax": 12.7, "ay": 53, "d": "A", "al": "l"}, {"n": "②③", "t": "CD28: 2.ª señal", "s": "sola no activa:<br>solo amplifica", "c": "i", "x": 34, "y": 91, "ax": 54, "ay": 46}, {"n": "②", "t": "CD80/86", "s": "en la célula<br>dendrítica", "c": "g", "x": 56, "y": 91, "ax": 54, "ay": 60}, {"n": "⑨", "t": "CD28 desplazada", "s": "queda sin<br>ligando", "c": "g", "x": 99.5, "y": 91, "ax": 95.4, "ay": 56, "al": "r"}]}, {"img": "img/09_3.webp", "ratio": 1.5, "titulo": "Las cinco especialidades del CD4", "texto": "El ambiente decide: <b>Th17</b> (RORγt) ④, <b>Tfh</b> (BCL-6) en el folículo ⑤ y <mark>Treg</mark> (FOXP3) que frena por IDO, IL-10 y contacto ⑥; sin FOXP3, IPEX ⑦.", "etiquetas": [{"n": "", "t": "Th2 + eosinófilo", "s": "IL-4 e IL-5:<br>contra parásitos", "c": "g", "x": 0.5, "y": 5, "ax": 23, "ay": 22, "al": "l"}, {"n": "④", "t": "Th17 (RORγt)", "s": "atrae neutrófilos<br>a las mucosas", "c": "i", "x": 33, "y": 5, "ax": 47, "ay": 31}, {"n": "⑤", "t": "Tfh (BCL-6)", "s": "IL-21; CXCR5:<br>queda en el folículo", "c": "i", "x": 70.0, "y": 5, "ax": 72, "ay": 36}, {"n": "⑤", "t": "LB del folículo", "s": "recibe la<br>ayuda del Tfh", "c": "i", "x": 99.5, "y": 5, "ax": 83, "ay": 33, "al": "r"}, {"n": "", "t": "Th1", "s": "IFN-γ: activa<br>al macrófago", "c": "g", "x": 38, "y": 93, "ax": 29, "ay": 67}, {"n": "④⑤⑥", "t": "LsT CD4 virgen", "s": "las citoquinas del<br>ambiente deciden", "c": "i", "x": 55, "y": 93, "ax": 50, "ay": 64}, {"n": "⑥⑦", "t": "Treg (FOXP3)", "s": "si falta FOXP3:<br>síndrome IPEX", "c": "d", "x": 72.5, "y": 93, "ax": 69, "ay": 70, "d": "D"}, {"n": "⑥", "t": "Dendrítica frenada", "s": "CTLA-4 induce IDO;<br>IL-10, TGF-β", "c": "d", "x": 99.5, "y": 93, "ax": 85, "ay": 70, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Tres escenas en orden: <b class=\"i\">1 sinapsis</b> entre la dendrítica y el LsT, <b class=\"i\">2 expansión clonal</b> por IL-2, <b class=\"d\">3 linfocito T citotóxico</b> matando a una célula infectada. <b>Azul</b> = activación y ayuda; <b>rojo</b> = efecto que mata; <b>gris</b> = datos y frenos.", "En la sinapsis, el TCR solo ve <mark>péptidos procesados</mark> en HLA, <span class=\"cx\">por eso</span> el centro del contacto es TCR-péptido-HLA con CD4/CD8 y CD28; alrededor, el anillo de adhesión (LFA-1-ICAM-1) sostiene el contacto durante horas.", "El clon nace <span class=\"cx\">porque</span> el LsT activado expresa CD25 y su receptor de IL-2 se vuelve de alta afinidad; <span class=\"cx\">luego</span> <span class=\"res\">el 90 % muere</span> en la contracción y quedan los de memoria."], "recordar": "señal 1 = <b>TCR + péptido-HLA</b>; señal 2 = <b>CD28-CD80/86</b>; CTLA-4 y PD-1 <b>frenan</b>. Th17 = RORγt, Treg = FOXP3, Tfh = BCL-6."}, "numeros": [{"l": "A", "html": "<b>Péptidos que ve el TCR αβ</b>: por HLA-I <b class=\"n\">8-10 aa</b> (intracelulares); por HLA-II <b class=\"n\">13-25 aa</b> (extracelulares).", "rango": {"min": 0, "max": 25, "unidad": "aminoácidos", "zonas": [[8, 10, "n", "HLA-I"], [13, 25, "m", "HLA-II"]], "marcas": [8, 10, 13, 25]}}, {"l": "B", "html": "<b>Búsqueda del antígeno</b>: contactos transitorios de <b class=\"n\">3-11 minutos</b> con cada dendrítica; todo el proceso de activación a expansión toma <b class=\"n\">7-14 días</b>.", "rango": {"min": 0, "max": 21, "unidad": "días", "zonas": [[7, 14, "n", "activación a expansión"]], "marcas": [7, 14]}}, {"l": "C", "html": "<b>Receptor de IL-2</b>: al añadir CD25, la afinidad sube <b class=\"a\">10 a 100 veces</b>. Tras la expansión muere por apoptosis el <b class=\"a\">90 %</b> de los efectores.", "rango": null}, {"l": "D", "html": "<b>Treg</b>: <b class=\"n\">5-10 %</b> de los LsT CD4 circulantes. <b>CTLA-4</b>: afinidad <b class=\"a\">mil veces</b> mayor por CD80/86 que la CD28.", "rango": {"min": 0, "max": 20, "unidad": "% de LsT CD4", "zonas": [[5, 10, "n", "Treg"]], "marcas": [5, 10]}}], "escalas": [], "cadena": {"titulo": "Del antígeno al linfocito efector", "subtitulo": "estímulo → señales → expansión → especialización → resultado (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> la dendrítica llega al ganglio con un péptido en su HLA. El LsT virgen entra por la <b>selectina L</b> y prueba dendríticas por pocos minutos <span class=\"lt2\">B</span>.", "pr": "contacto estable de horas (ICAM-1) cuando encuentra su antígeno.", "pr_tit": "Produce:", "rf": "Pregunta ① · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Dos señales", "m": "<b>Por qué:</b> el TCR (con CD3 y ζ, que tienen ITAM) da la <b>especificidad</b>; CD28-CD80/86 confirma el peligro. ZAP-70 enciende NFAT, NF-κB y AP-1.", "pr": "más de 70 genes activos, entre ellos el de la <u>IL-2</u>.", "pr_tit": "Produce:", "rf": "Preguntas ②③", "color": "p2"}, {"t": "3. Expansión clonal", "m": "<b>Qué pasa:</b> el LsT expresa CD25 y responde a su propia IL-2 (con IL-15 e IL-21) <span class=\"lt2\">C</span>.", "pr": "un clon numeroso de LsT idénticos; después, contracción y memoria (IL-7, IL-15).", "pr_tit": "Produce:", "rf": "Pregunta ⑨ · punto <span class=\"lt2\">C</span>", "color": "p3"}, {"t": "4. Especialización", "m": "<b>Por qué:</b> el <mark>microambiente de citoquinas</mark> decide. IL-12 → Th1 (T-bet); IL-4 → Th2 (GATA-3); IL-6 + TGF-β → Th17 (RORγt); IL-21 → Tfh (BCL-6); TGF-β + IL-2 → Treg (FOXP3). Los CD8 se vuelven citotóxicos.", "pr": "cada subpoblación con sus citoquinas y su blanco; IL-4 e IFNγ se excluyen.", "pr_tit": "Produce:", "rf": "Preguntas ④⑤⑥", "color": "p4"}, {"t": "5. Resultado", "m": "<b>Qué produce:</b> Th1 activa macrófagos, Th2 lleva a IgE, Th17 atrae neutrófilos, Tfh ayuda al LB; el LTctx mata con <b>perforinas, granzimas</b> o <b>FasL</b>.", "pr": "se controla el patógeno intracelular; CTLA-4 y Treg apagan la respuesta <span class=\"lt2\">D</span>.", "pr_tit": "Produce:", "rf": "Pregunta ⑧", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Qué pasa si falla el freno:</b> sin FOXP3 no hay Treg (síndrome <mark>IPEX</mark>); exceso de Th17 o Th22 da autoinmunidad; desviación Th2, alergia.", "pr": "<span class=\"res\">autoinmunidad, enteropatía, poliendocrinopatía o alergia</span>.", "pr_tit": "Produce:", "rf": "Pregunta ⑦", "color": "p1"}], "extra": [{"html": "🧩 <b>Sinapsis inmunológica en tres anillos:</b> <b>central</b> TCR-péptido-HLA, CD4/CD8 y CD28-CD80/86; <b>periférico</b> LFA-1-ICAM-1 y CD2-LFA-3; <b>distal</b> F-actina y la fosfatasa CD45, que activa Fyn y Lck.", "k": ""}, {"html": "🛑 <b>Tres frenos del LsT:</b> CTLA-4 (desplaza a CD28), PD-1 (coestimulador inhibitorio) y los <b>Treg</b> (IDO por CTLA-4, IL-10/TGF-β/IL-35, granzimas y «sumidero» de IL-2).", "k": "k"}], "escaleras": [{"c": "i", "t": "🔁 Vida de un clon T", "pasos": ["LsT virgen busca su antígeno", "<b>dos señales</b>: activación", "IL-2: expansión clonal", "efectores actúan", "<b>contracción</b>: muere el 90 %", "quedan LsT de <b>memoria</b> (IL-7, IL-15)"]}, {"c": "d", "t": "⚠️ Cuando falta el freno", "pasos": ["Mutación de <b>FOXP3</b>", "no se generan Treg", "clones autorreactivos sin control", "enteropatía, diabetes, eccema", "<b>IPEX</b> en varones (ligado al X)"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 10: TCR, búsqueda del antígeno, activación, expansión clonal, subpoblaciones CD4 (tabla), Treg, LTctx, CTLA-4 y memoria."}, "preguntas": [{"n": 1, "id": "IN5-001", "c": "i", "tema": "Receptor TCR", "pregunta": "Respecto a lo que reconoce el TCR αβ, es correcto:", "opciones": ["a. Reconoce el antígeno en su forma nativa, igual que el BCR.", "b. Reconoce péptidos procesados presentados por HLA: de 8-10 aa por HLA-I y de 13-25 aa por HLA-II.", "c. Reconoce glicolípidos y fosfolípidos presentados por CD1.", "d. Reconoce carbohidratos libres sin necesidad de presentación.", "e. Reconoce péptidos de 13-25 aa de origen intracelular presentados por HLA-I."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Péptidos procesados presentados por HLA: HLA-I los pequeños (8-10 aa, intracelulares) y HLA-II los mayores (13-25 aa, extracelulares).", "sin_banco": true, "ok": "", "x": "Es lo que pasa en la sinapsis (escena 1): el TCR ve un <mark>péptido procesado en HLA</mark>, nunca el antígeno entero. HLA-I lleva <span class=\"res\">8-10 aa</span> de adentro; HLA-II, <span class=\"res\">13-25 aa</span> de afuera (punto Ⓐ).", "truco": "", "veces": 0}, {"n": 2, "id": "IN5-002", "c": "i", "tema": "Activación: dos señales", "pregunta": "¿Cuáles son las dos señales necesarias para activar por completo a un linfocito T virgen?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "1.ª señal: el TCR reconoce el complejo péptido-HLA (sinapsis inmunológica). 2.ª señal: coestimulación, sobre todo CD28 con CD80/CD86, que sola no activa pero amplifica la señal, sostiene la IL-2 y da señales antiapoptóticas.", "sin_banco": true, "ok": "", "x": "La primera señal da la <mark>especificidad</mark> (qué antígeno es), y la segunda confirma que hay peligro. <span class=\"cx\">Por eso</span> la CD28 sola no activa al linfocito; <span class=\"cx\">en cambio</span>, sin ella la señal del TCR se apaga. Con las dos, NFAT, NF-κB y AP-1 encienden más de 70 genes, <span class=\"cx\">así que</span> <span class=\"res\">la IL-2 dispara la expansión clonal</span>.", "truco": "Señal 1 = «¿quién eres?» (TCR); señal 2 = «¿es en serio?» (CD28).", "veces": 0}, {"n": 3, "id": "IN5-003", "c": "i", "tema": "Activación: coestimulación", "pregunta": "Respecto a la coestimulación del linfocito T, es FALSO:", "opciones": ["a. El par CD28-CD80/86 es el principal coestimulador.", "b. ICOS-ICOSL y OX40-OX40L también son coestimuladores.", "c. CTLA-4 y PD-1 son moléculas coestimuladoras inhibitorias.", "d. La CD28, por sí sola y sin TCR, activa por completo al LsT virgen.", "e. La coestimulación sostiene la producción de IL-2 e inicia señales antiapoptóticas."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Falso: la CD28 no activa por sí sola al linfocito T; solo amplifica la señal iniciada por el TCR.", "sin_banco": true, "ok": "", "x": "La coestimulación es un <mark>amplificador</mark>, no un interruptor: necesita que el TCR haya reconocido antes su péptido-HLA. <span class=\"cx\">Por eso</span> la opción d es falsa. Ojo que no toda coestimulación suma: <span class=\"res\">CTLA-4 y PD-1 son coestimuladoras inhibitorias</span> (frenos).", "truco": "CD28 acelera, CTLA-4 y PD-1 frenan.", "veces": 0}, {"n": 4, "id": "IN5-004", "c": "i", "tema": "Subpoblaciones CD4", "pregunta": "El factor de transcripción que sostiene la diferenciación del linfocito Th17 es:", "opciones": ["a. T-bet", "b. GATA-3", "c. FOXP3", "d. BCL-6", "e. RORγt"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. RORγt; el Th17 se induce por IL-6, IL-21, IL-23 y TGF-β.", "sin_banco": true, "ok": "", "x": "Cada subpoblación tiene su factor maestro: T-bet en <mark>Th1</mark>, GATA-3 en <mark>Th2</mark>, FOXP3 en <mark>Treg</mark>, BCL-6 en <mark>Tfh</mark> y RORγt en <mark>Th17</mark>. El Th17 atrae neutrófilos con IL-17, <span class=\"cx\">por eso</span> su exceso se vincula a <span class=\"res\">artritis reumatoide, lupus, asma y rechazo de trasplantes</span>.", "truco": "Th17 = «RORγ-diecisiete»: la R de Reumatoide.", "veces": 0}, {"n": 5, "id": "IN5-005", "c": "i", "tema": "Subpoblaciones CD4", "pregunta": "¿Qué subpoblación de linfocitos T CD4 forma los centros germinales y estimula a los linfocitos B?", "opciones": ["a. Th22", "b. Th9", "c. Tfh", "d. Th1", "e. Treg"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Tfh (T folicular helper): BCL-6, IL-21; expresa CXCR5 y pierde CCR7, así que se queda en el folículo.", "sin_banco": true, "ok": "", "x": "El Tfh mantiene el receptor <mark>CXCR5</mark> y pierde CCR7, <span class=\"cx\">por eso</span> se queda junto a los LB foliculares que producen CXCL13 en vez de salir a los tejidos. Ahí, con IL-21, <span class=\"res\">ayuda al LB en el centro germinal</span> (afinidad y cambio de clase).", "truco": "Tfh = «T del Folículo».", "veces": 0}, {"n": 6, "id": "IN5-006", "c": "g", "tema": "Treg", "pregunta": "¿Cuáles son los tres mecanismos de acción de los linfocitos T reguladores?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "1) CTLA-4 induce IDO en la dendrítica, que degrada triptófano en kinureninas proapoptóticas; 2) secretan IL-10, TGF-β, IL-35 y adenosina; 3) matan por contacto (granzimas) y consumen IL-2 como «sumidero».", "sin_banco": true, "ok": "", "x": "Los Treg son CD4+CD25+ y anérgicos, <span class=\"cx\">así que</span> no fabrican su propia IL-2 y la <mark>roban</mark> a los vecinos. <span class=\"cx\">Además</span> frenan con citoquinas reguladoras y con la <mark>IDO</mark>, que deja sin triptófano al LsT. Son el <span class=\"res\">5-10 % de los LsT CD4</span> circulantes y sostienen la tolerancia periférica.", "truco": "Treg: «IDO, citoquinas y contacto» (ICC).", "veces": 0}, {"n": 7, "id": "IN5-007", "c": "d", "tema": "Correlato clínico", "pregunta": "Lactante varón con diarrea crónica grave (enteropatía), diabetes de inicio neonatal y eccema; su tío materno murió con un cuadro igual. ¿Qué gen está mutado y qué célula falla?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome IPEX: mutación del gen FOXP3 (ligado al X) que impide generar linfocitos T reguladores, así que se pierde la tolerancia periférica.", "sin_banco": true, "ok": "", "x": "IPEX significa <mark>inmunodesregulación, poliendocrinopatía y enteropatía ligada al X</mark>. El FOXP3 es el factor maestro del Treg; <span class=\"cx\">por eso</span>, si falla, no hay freno y los clones autorreactivos atacan intestino, páncreas y piel. Al ser ligado al X, <span class=\"res\">lo sufren los varones</span> y lo transmite la madre.", "truco": "FOXP3 roto = Treg ausente = IPEX.", "veces": 0}, {"n": 8, "id": "IN5-008", "c": "d", "tema": "Linfocitos T CD8 citotóxicos", "pregunta": "¿Por qué mecanismos mata un linfocito T citotóxico a su célula blanco?", "opciones": ["a. Por gránulos con perforinas, granzimas y granulolisinas, o por FasL que se une a Fas (CD95).", "b. Fagocitando a la célula blanco y digiriéndola en fagolisosomas.", "c. Secretando IgG que activa el complemento por vía clásica.", "d. Liberando IL-4 que induce la apoptosis del blanco.", "e. Produciendo histamina y leucotrienos sobre la célula blanco."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Gránulos citolíticos (perforinas, granzimas, granulolisinas) o FasL que activa el receptor de muerte Fas.", "sin_banco": true, "ok": "", "x": "Escena 3: el citotóxico vacía sus gránulos; las <mark>perforinas</mark> abren los poros que ves en la membrana y por ahí entran las granzimas. La célula se encoge, burbujea y su núcleo se fragmenta: <span class=\"res\">apoptosis</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN5-009", "c": "g", "tema": "Finalización y memoria", "pregunta": "¿Por qué mecanismo termina la CTLA-4 la activación del linfocito T y qué sostiene luego a los LsT de memoria?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "CTLA-4 (CD152) tiene afinidad mil veces mayor por CD80/CD86 que la CD28: desplaza la coestimulación, baja la IL-2 y frena el ciclo celular. Los LsT de memoria se sostienen con IL-7 (receptor CD127) e IL-15.", "sin_banco": true, "ok": "", "x": "La CTLA-4 <mark>le gana el sitio</mark> a la CD28 en CD80/86, <span class=\"cx\">así que</span> la señal 2 pasa de acelerar a frenar. Después de la contracción (muere el <span class=\"res\">90 %</span> de los efectores) quedan los de memoria, que responden más rápido <span class=\"cx\">porque</span> requieren menos señales y tienen el locus del IFNγ desmetilado.", "truco": "CTLA-4 «mil veces más pegajosa» que CD28.", "veces": 0}], "tabla": {"cab": ["", "Th1", "Th2", "Th17", "Tfh", "Treg"], "filas": [["Inductor", "IL-12, IL-18, IFN-α/β", "IL-4, IL-25, IL-33", "IL-6, IL-21, IL-23, TGF-β", "IL-6, IL-12, IL-21", "TGF-β + IL-2"], ["Factor", "T-bet, STAT4", "GATA-3, STAT-6", "RORγt", "BCL-6", "FOXP3"], ["Produce", "IFNγ, IL-2", "IL-4, IL-5, IL-13", "IL-17A/F, IL-22", "IL-21, IL-4", "IL-10, TGF-β, IL-35"], ["Función", "activa macrófagos: intracelulares", "IgE: extracelulares y alérgenos", "atrae neutrófilos", "centro germinal: ayuda al LB", "tolerancia periférica"], ["🔑 Para diferenciar", "intracelular", "alergia", "autoinmunidad (AR, lupus)", "se queda en el folículo (CXCR5)", "si falta: IPEX"]]}, "fuente": "Fuente: tu teoría — Clase 10 Linfocitos T e inmunidad celular (Rojas, 17.ª ed., cap. 10)."}, {"n": 10, "slug": "Linfocito_B_y_anticuerpo", "titulo": "Del linfocito B al anticuerpo", "subtitulo": "BCR, centro germinal, célula plasmática e inmunoglobulinas", "grupo": "g5", "lema": "La idea: el linfocito B <b class=\"i\">reconoce el antígeno con su BCR</b> (IgM de membrana + Igα/Igβ), se activa y entra al <mark>centro germinal</mark>, donde muta y se prueba frente a los Tfh hasta fabricar anticuerpos de <b>alta afinidad y otra clase</b>. Termina como <b class=\"d\">célula plasmática</b> (hasta 2.000 anticuerpos por segundo) o como LB de memoria. El anticuerpo tiene dos mitades: la <b>variable</b> reconoce y la <b>constante</b> (Fc) ejecuta. Importa porque la cinética IgM → IgG es la base de la serología, y la falta de una clase (IgA, IgG2) da enfermedad. En la imagen, de izquierda a derecha: LB virgen, centro germinal, célula plasmática y la molécula de Ig.", "img": "img/10.webp", "mini": "img/mini/10.webp", "ratio": 1.5, "etiquetas": [{"n": "①②④", "t": "BCR", "s": "IgM de membrana<br>+ Igα/Igβ (ITAM)", "c": "i", "x": 0.8, "y": 6, "ax": 10.6, "ay": 34.7, "d": "A", "al": "l"}, {"n": "⑤", "t": "Zona oscura", "s": "centroblastos:<br>dividen y mutan", "c": "i", "x": 25, "y": 6, "ax": 29, "ay": 40}, {"n": "⑤⑯", "t": "Zona clara", "s": "afinidad y<br>cambio de clase", "c": "i", "x": 41, "y": 6, "ax": 40, "ay": 40, "d": "B"}, {"n": "⑥", "t": "Retículo rugoso", "s": "fábrica de<br>anticuerpos", "c": "d", "x": 59, "y": 6, "ax": 65, "ay": 43}, {"n": "⑫", "t": "Fab", "s": "cadena liviana (clara)<br>y pesada (oscura)", "c": "d", "x": 78, "y": 6, "ax": 82, "ay": 37}, {"n": "⑩", "t": "Gozne", "s": "flexible", "c": "d", "x": 99.2, "y": 6, "ax": 90, "ay": 45, "al": "r"}, {"n": "③", "t": "LB virgen", "s": "llega por CXCL13", "c": "i", "x": 0.8, "y": 90, "ax": 10, "ay": 56, "al": "l"}, {"n": "", "t": "Manto", "s": "linfocitos que<br>rodean el folículo", "c": "g", "x": 20, "y": 90, "ax": 30, "ay": 67.5}, {"n": "⑤", "t": "Tfh y dendríticas", "s": "eligen al<br>centrocito", "c": "i", "x": 37.5, "y": 90, "ax": 43, "ay": 53}, {"n": "⑥", "t": "Plasmática", "s": "núcleo en<br>rueda de carreta", "c": "d", "x": 55, "y": 90, "ax": 57, "ay": 55, "d": "C"}, {"n": "⑦⑧", "t": "Anticuerpos", "s": "IgM primero,<br>luego IgG", "c": "d", "x": 72, "y": 90, "ax": 78, "ay": 58.5, "d": "E"}, {"n": "⑪", "t": "Fc", "s": "CH2: complemento<br>CH3: opsonina", "c": "d", "x": 99.2, "y": 90, "ax": 89.5, "ay": 58, "d": "D", "al": "r"}], "diapos": [{"img": "img/10.webp", "ratio": 1.5, "titulo": "Del LB virgen a la inmunoglobulina", "texto": "El BCR atrapa ①, el <mark>centro germinal</mark> afina y cambia de clase ⑤, la plasmática fabrica ⑥ y el Fc ejecuta ⑪.", "etiquetas": [{"n": "①②④", "t": "BCR", "s": "IgM de membrana<br>+ Igα/Igβ (ITAM)", "c": "i", "x": 0.8, "y": 6, "ax": 10.6, "ay": 34.7, "d": "A", "al": "l"}, {"n": "⑤", "t": "Zona oscura", "s": "centroblastos:<br>dividen y mutan", "c": "i", "x": 25, "y": 6, "ax": 29, "ay": 40}, {"n": "⑤⑯", "t": "Zona clara", "s": "afinidad y<br>cambio de clase", "c": "i", "x": 41, "y": 6, "ax": 40, "ay": 40, "d": "B"}, {"n": "⑥", "t": "Retículo rugoso", "s": "fábrica de<br>anticuerpos", "c": "d", "x": 59, "y": 6, "ax": 65, "ay": 43}, {"n": "⑫", "t": "Fab", "s": "cadena liviana (clara)<br>y pesada (oscura)", "c": "d", "x": 78, "y": 6, "ax": 82, "ay": 37}, {"n": "⑩", "t": "Gozne", "s": "flexible", "c": "d", "x": 99.2, "y": 6, "ax": 90, "ay": 45, "al": "r"}, {"n": "③", "t": "LB virgen", "s": "llega por CXCL13", "c": "i", "x": 0.8, "y": 90, "ax": 10, "ay": 56, "al": "l"}, {"n": "", "t": "Manto", "s": "linfocitos que<br>rodean el folículo", "c": "g", "x": 20, "y": 90, "ax": 30, "ay": 67.5}, {"n": "⑤", "t": "Tfh y dendríticas", "s": "eligen al<br>centrocito", "c": "i", "x": 37.5, "y": 90, "ax": 43, "ay": 53}, {"n": "⑥", "t": "Plasmática", "s": "núcleo en<br>rueda de carreta", "c": "d", "x": 55, "y": 90, "ax": 57, "ay": 55, "d": "C"}, {"n": "⑦⑧", "t": "Anticuerpos", "s": "IgM primero,<br>luego IgG", "c": "d", "x": 72, "y": 90, "ax": 78, "ay": 58.5, "d": "E"}, {"n": "⑪", "t": "Fc", "s": "CH2: complemento<br>CH3: opsonina", "c": "d", "x": 99.2, "y": 90, "ax": 89.5, "ay": 58, "d": "D", "al": "r"}]}, {"img": "img/10_2.webp", "ratio": 1.5, "titulo": "Las clases de inmunoglobulina", "texto": "La <mark>IgM</mark> pentamérica activa el complemento <b>con una sola molécula</b>, la IgG necesita dos ⑨⑬. La <mark>IgA</mark> dimérica cuida las mucosas <span class=\"lt2\">E</span> ⑮; la IgE se fija al mastocito ⑯.", "etiquetas": [{"n": "⑬", "t": "C1q sobre la IgM", "s": "una sola molécula<br>inicia la vía clásica", "c": "d", "x": 0.5, "y": 6, "ax": 13, "ay": 27, "al": "l"}, {"n": "⑬", "t": "C1q entre dos IgG", "s": "la IgG necesita<br>dos vecinas", "c": "d", "x": 26, "y": 6, "ax": 36.8, "ay": 35}, {"n": "⑮", "t": "Pieza secretora", "s": "protege la IgA<br>en la luz", "c": "i", "x": 47, "y": 6, "ax": 59.6, "ay": 44}, {"n": "⑯", "t": "IgE", "s": "la IL-4 favorece<br>IgG1 e IgE", "c": "d", "x": 99.5, "y": 6, "ax": 91.5, "ay": 29, "al": "r"}, {"n": "⑨", "t": "IgM pentamérica", "s": "900 kDa, cadena J;<br>intravascular", "c": "d", "x": 0.5, "y": 91, "ax": 13.3, "ay": 48.5, "d": "D", "al": "l"}, {"n": "⑬", "t": "IgG monomérica", "s": "85 % de las Ig<br>del plasma", "c": "d", "x": 27, "y": 91, "ax": 31, "ay": 53}, {"n": "⑮", "t": "IgA dimérica", "s": "deficiencia: 1 de<br>cada 500 personas", "c": "i", "x": 48, "y": 91, "ax": 61, "ay": 47, "d": "E"}, {"n": "", "t": "Epitelio intestinal", "s": "la IgA lo cruza<br>hacia la luz", "c": "g", "x": 69, "y": 91, "ax": 66, "ay": 70}, {"n": "⑯", "t": "Mastocito", "s": "fija la IgE<br>por su Fc", "c": "g", "x": 99.5, "y": 91, "ax": 88, "ay": 56, "al": "r"}]}, {"img": "img/10_3.webp", "ratio": 1.5, "titulo": "Placenta y fragmentos del anticuerpo", "texto": "Solo la <mark>IgG</mark> cruza la placenta por transcitosis; <span class=\"cx\">por eso</span> la IgM del cordón la fabricó el feto ⑭. La <b>papaína</b> corta encima del gozne (2 Fab + Fc); la <mark>pepsina</mark>, debajo: F(ab')₂ ⑩.", "etiquetas": [{"n": "⑭", "t": "IgM materna", "s": "pentámero: no<br>cruza la placenta", "c": "d", "x": 0.5, "y": 5, "ax": 13.7, "ay": 24, "al": "l"}, {"n": "⑭", "t": "Receptor Fc", "s": "del trofoblasto:<br>toma la IgG", "c": "d", "x": 28, "y": 5, "ax": 15.3, "ay": 36}, {"n": "⑩", "t": "Gozne", "s": "puentes<br>disulfuro", "c": "g", "x": 62, "y": 5, "ax": 73.6, "ay": 31}, {"n": "⑫", "t": "Ig intacta", "s": "dos Fab<br>y un Fc", "c": "g", "x": 99.5, "y": 5, "ax": 85, "ay": 22, "al": "r"}, {"n": "⑭", "t": "Transcitosis", "s": "la IgG cruza<br>en vesículas", "c": "d", "x": 0.5, "y": 92, "ax": 20.5, "ay": 49, "al": "l"}, {"n": "⑭", "t": "IgG en la sangre fetal", "s": "solo la IgG<br>llega al feto", "c": "d", "x": 28, "y": 92, "ax": 30.3, "ay": 67}, {"n": "⑩", "t": "Papaína", "s": "corta encima del<br>gozne: 2 Fab + Fc", "c": "i", "x": 51, "y": 92, "ax": 58, "ay": 60}, {"n": "⑩", "t": "Fc libre", "s": "separado<br>de los brazos", "c": "g", "x": 70, "y": 92, "ax": 64, "ay": 76}, {"n": "⑩", "t": "Pepsina", "s": "corta debajo:<br>queda F(ab')₂", "c": "i", "x": 99.5, "y": 92, "ax": 88, "ay": 61, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Cuatro elementos en orden: <b class=\"i\">1 LB virgen</b> con su BCR, <b class=\"i\">2 centro germinal</b> (zona oscura y zona clara), <b class=\"d\">3 célula plasmática</b> secretando anticuerpos y <b class=\"d\">4 la inmunoglobulina</b> con sus cadenas. <b>Azul</b> = el linfocito B y su maduración; <b>rojo</b> = el producto (plasmática y anticuerpo); <b>gris</b> = datos.", "En el centro germinal, la <b>zona oscura</b> son centroblastos que se dividen y <mark>mutan</mark> (hipermutación somática); en la <b>zona clara</b> los centrocitos se prueban contra los Tfh y ganan afinidad y cambio de clase. El antígeno timo independiente se salta este paso, <span class=\"cx\">por eso</span> solo da IgM.", "En la molécula: cadenas pesadas (oscuras) y livianas (claras); arriba las regiones variables (CDR) que atrapan el antígeno; al centro el <b>gozne</b>; abajo el Fc: <span class=\"res\">CH2 fija complemento, CH3 opsoniza y cruza la placenta</span>."], "recordar": "IgM agarra, <b>Igα/Igβ</b> avisan, <b>CD22</b> apaga. Primaria = <b>IgM</b> en 7-10 días; secundaria = <b>IgG</b> en 24-72 h."}, "numeros": [{"l": "A", "html": "<b>BCR</b>: <b class=\"n\">0,5-1,5 × 10⁵</b> moléculas de IgM de membrana por LB. Si no halla su antígeno, el LB muere en <b class=\"n\">2-3 días</b>.", "rango": null}, {"l": "B", "html": "<b>Respuesta primaria</b>: IgM en <b class=\"n\">7-10 días</b>; <b>secundaria</b>: IgG en <b class=\"a\">24-72 horas</b>, más específica y duradera.", "rango": {"min": 0, "max": 14, "unidad": "días", "zonas": [[1, 3, "n", "IgG secundaria"], [7, 10, "m", "IgM primaria"]], "marcas": [1, 3, 7, 10]}}, {"l": "C", "html": "<b>Célula plasmática</b>: hasta <b class=\"a\">2.000 anticuerpos por segundo</b>. Un adulto sintetiza <b class=\"n\">2-4 g</b> de anticuerpos al día.", "rango": null}, {"l": "D", "html": "<b>Ig</b>: cadena pesada <b class=\"n\">440 aa</b>, liviana <b class=\"n\">220 aa</b>; gozne de <b class=\"n\">8-15 aa</b>. IgG <b class=\"n\">180 kDa</b> (85 % de las Ig plasmáticas, vida media 15-20 días); IgM <b class=\"a\">900 kDa</b> (5-6 días).", "rango": null}, {"l": "E", "html": "<b>Deficiencia de IgA</b>: <b class=\"a\">1 de cada 500</b> personas, la inmunodeficiencia congénita más frecuente. Producción de IgA: <b class=\"n\">66 mg/kg/día</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del antígeno al anticuerpo", "subtitulo": "estímulo → BCR → centro germinal → plasmática y memoria → anticuerpo (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> la CXCL13 lleva al LB al folículo; el antígeno le llega presentado por dendríticas, macrófagos o células dendríticas foliculares <span class=\"lt2\">A</span>.", "pr": "el BCR captura el antígeno y lo agrupa en un polo (<b>capping</b>).", "pr_tit": "Produce:", "rf": "Pregunta ③ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Señal del BCR", "m": "<b>Por qué:</b> la IgM de membrana no señaliza; CD45 activa Lyn, Fyn y Blk, que fosforilan los ITAM de <mark>Igα/Igβ</mark> → BLNK → AP-1 y NF-κB. CD19 y CD21 (C3d) refuerzan; CD22 (ITIM) apaga.", "pr": "LB activado que expresa CCR7 y S1P1 (ya no vuelve a la sangre).", "pr_tit": "Produce:", "rf": "Preguntas ①②④", "color": "p2"}, {"t": "3. Centro germinal", "m": "<b>Qué pasa:</b> con CXCR5, LB y Tfh migran al folículo. <b>Zona oscura</b>: centroblastos (CXCR4) proliferan y mutan. <b>Zona clara</b>: centrocitos + Tfh (ICOS, IL-21).", "pr": "más afinidad y <u>cambio de clase</u> (IL-4 → IgG1 e IgE; IFNγ → IgG2).", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑯", "color": "p3"}, {"t": "4. Plasmática y memoria", "m": "<b>Qué produce:</b> por IL-2 e IL-10, el LB pierde el BCR y se vuelve célula plasmática <span class=\"lt2\">C</span>; otros quedan como LB de memoria.", "pr": "vida corta (ganglio) o vida larga (médula ósea, IgG por años).", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑦⑧", "color": "p4"}, {"t": "5. Anticuerpo", "m": "<b>Qué hace:</b> la región variable reconoce; el Fc ejecuta: inmoviliza, neutraliza, opsoniza, activa complemento, protege al feto, ADCC <span class=\"lt2\">D</span>.", "pr": "IgM primero (pentámero, complemento); luego IgG (tejidos, placenta).", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑩⑪⑫⑬⑭", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Qué pasa si falla:</b> sin CD22/CD72 el LB autorreactivo produce autoanticuerpos; sin IgA, autoinmunidad y alergia; sin IgG2, neumococo; la IgG4 da enfermedad fibroinflamatoria <span class=\"lt2\">E</span>.", "pr": "<span class=\"res\">autoinmunidad, infecciones por encapsulados, alergia</span>.", "pr_tit": "Produce:", "rf": "Pregunta ⑮", "color": "p1"}], "extra": [{"html": "✂️ <b>Enzimas:</b> la <b>papaína</b> da dos Fab + un Fc; la <b>pepsina</b> corta bajo el gozne y deja un <b>F(ab')₂</b>. <b>Isotipo</b> = clase (toda la especie); <b>alotipo</b> = varía entre personas; <b>idiotipo</b> = especificidad de cada anticuerpo.", "k": ""}, {"html": "🧬 <b>Diversidad:</b> <b class=\"n\">10⁵-10⁸</b> especificidades por recombinación somática de más de <b class=\"n\">765 genes</b>: cadena pesada en el cromosoma 14 (65 V + 27 D + 6 J), kappa en el 2, lambda en el 22. El antígeno <b>no moldea</b> al anticuerpo.", "k": "k"}], "escaleras": [{"c": "i", "t": "📈 Primaria frente a secundaria", "pasos": ["LB virgen ve el antígeno", "7-10 días: <b>IgM</b> de baja especificidad", "centro germinal: mutación y cambio de clase", "LB de <b>memoria</b>", "2.º contacto: <b>IgG</b> en 24-72 h, alta afinidad"]}, {"c": "d", "t": "👶 Anticuerpos en el feto y el lactante", "pasos": ["IgG materna cruza por <b>transcitosis</b> (CH3)", "IgM materna <b>no</b> cruza", "IgM en cordón = <b>infección intrauterina</b>", "4.º-5.º mes: baja IgG (se gasta la materna)", "calostro y leche: IgA e IgG"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 11a (BCR, CXCL13, señalización, centro germinal, plasmática, primaria/secundaria) y Clase 11b (estructura, dominios, enzimas, diversidad, isotipos, cambio de clase, cinco clases, deficiencias)."}, "preguntas": [{"n": 1, "id": "IN5-010", "c": "i", "tema": "Receptor BCR", "pregunta": "Respecto al receptor de antígeno del linfocito B (BCR), es correcto:", "opciones": ["a. La IgM de membrana transmite la señal por su larga porción intracitoplasmática.", "b. Las moléculas accesorias Igα e Igβ, con dominios ITAM, transmiten la señal al interior.", "c. La IgD de membrana es la única que reconoce el antígeno.", "d. Los linfocitos B fetales tienen abundante IgD de membrana.", "e. CD22 inicia la cascada gracias a sus motivos ITAM."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Igα e Igβ, con sus ITAM, transmiten la señal; la IgM de membrana solo captura el antígeno.", "sin_banco": true, "ok": "", "x": "Mira los receptores en «Y» del LB virgen (elemento 1): esa <mark>IgM de membrana</mark> solo atrapa el antígeno; quien avisa al interior son <span class=\"res\">Igα e Igβ con sus ITAM</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN5-011", "c": "i", "tema": "IgD de membrana", "pregunta": "¿Qué función cumple la IgD de membrana del linfocito B y qué relación tiene con la tolerancia fetal?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Evita que el LB se haga tolerante al antígeno que capturó su IgM. Los LB fetales carecen de IgD, lo que explicaría la tolerancia fetal frente a los antígenos propios.", "sin_banco": true, "ok": "", "x": "La IgD funciona como un <mark>seguro contra la tolerancia</mark>: con ella, el LB maduro responde al antígeno en vez de quedar anérgico. <span class=\"cx\">En cambio</span>, el LB del feto no la tiene, <span class=\"cx\">así que</span> tiende a tolerar lo que encuentra, y <span class=\"cx\">por eso</span> <span class=\"res\">el feto se hace tolerante a lo propio</span>.", "truco": "Sin D no hay «Defensa»: el feto tolera.", "veces": 0}, {"n": 3, "id": "IN5-012", "c": "i", "tema": "Ingreso a órganos linfoides", "pregunta": "La quimioquina que atrae a los linfocitos B maduros hacia los folículos linfoides es:", "opciones": ["a. CCL19", "b. CXCL12 (SDF-1)", "c. CCL20", "d. CXCL13", "e. CXCL8 (IL-8)"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. CXCL13; si en 2-3 días el LB no encuentra su antígeno, muere por apoptosis.", "sin_banco": true, "ok": "", "x": "Los folículos producen <mark>CXCL13</mark> y el LB la sigue gracias a CXCR5; LFA-1 e ICAM-1 lo pegan al endotelio de las vénulas. Si no halla su antígeno no se queda indefinidamente: <span class=\"res\">muere por apoptosis en 2-3 días</span>.", "truco": "B de «Bolsa 13»: CXCL13 lleva al B al folículo.", "veces": 0}, {"n": 4, "id": "IN5-013", "c": "i", "tema": "Señalización del BCR", "pregunta": "¿Qué molécula, con motivos ITIM, apaga la cascada de señalización del BCR cuando la producción de anticuerpos llega al nivel óptimo?", "opciones": ["a. CD22", "b. CD45", "c. CD19", "d. CD21", "e. BLNK"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. CD22 (con CD72 frena además a los LB que tocan un autoantígeno).", "sin_banco": true, "ok": "", "x": "La cascada empieza con <mark>CD45</mark> (fosfatasa que activa Lyn, Fyn y Blk), sigue con BLNK hacia AP-1 y NF-κB, y CD19/CD21 la refuerzan. Para frenar está <mark>CD22</mark>, cuyos ITIM desactivan los ITAM. <span class=\"cx\">Por eso</span> CD22 y CD72 son también el <span class=\"res\">control de tolerancia periférica B</span>: frenan e inducen apoptosis del LB autorreactivo.", "truco": "ITAM activa, ITIM inhibe.", "veces": 0}, {"n": 5, "id": "IN5-014", "c": "i", "tema": "Centros germinales", "pregunta": "Respecto al centro germinal, es FALSO:", "opciones": ["a. En la zona oscura los centroblastos proliferan expresando CXCR4.", "b. La hipermutación somática ocurre en la zona oscura.", "c. En la zona clara los centrocitos contactan a los linfocitos Tfh.", "d. En la zona clara aumenta la afinidad y ocurre el cambio de clase.", "e. Los antígenos timo independientes generan LB de memoria e IgG de alta afinidad."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Falso: los antígenos timo independientes producen solo células plasmáticas de IgM, sin LB de memoria.", "sin_banco": true, "ok": "", "x": "En el corte del folículo (elemento 2): la mitad oscura y apretada es la <mark>zona oscura</mark> (dividen y mutan); la mitad pálida con Tfh y dendríticas foliculares es la <mark>zona clara</mark> (selección y cambio de clase). El timo independiente <span class=\"res\">no pasa por aquí</span>: solo IgM, sin memoria.", "truco": "", "veces": 0}, {"n": 6, "id": "IN5-015", "c": "d", "tema": "Células plasmáticas", "pregunta": "¿Qué cambios sufre el linfocito B al volverse célula plasmática y en qué se diferencian las de vida corta y vida larga?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Pierde BCR, CXCR5, CXCR7 y CD19; gana CXCR4, CD20, CD22 y MHC-II; deja de dividirse y produce hasta 2.000 anticuerpos/s. Vida corta: médula del ganglio, sale rápido. Vida larga: nicho de médula ósea (SDF-1, IL-16), IgG prolongada.", "sin_banco": true, "ok": "", "x": "Elemento 3: el retículo endoplásmico rugoso apilado llena el citoplasma <span class=\"cx\">porque</span> la célula es una <mark>fábrica de anticuerpos</mark> (punto Ⓒ). Ya no tiene BCR ni se divide.", "truco": "", "veces": 0}, {"n": 7, "id": "IN5-016", "c": "g", "tema": "Respuesta primaria y secundaria", "pregunta": "Respecto a la respuesta humoral primaria y secundaria, es correcto:", "opciones": ["a. La primaria produce IgG en 24-72 horas.", "b. La secundaria produce IgM de baja especificidad en 7-10 días.", "c. La primaria da IgM en 7-10 días; la secundaria, IgG más específica en 24-72 horas.", "d. Ambas tardan 7-10 días y producen la misma clase de anticuerpo.", "e. La respuesta secundaria la generan linfocitos B vírgenes."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Primaria (LB virgen): IgM en 7-10 días, poco específica y breve; secundaria (LB de memoria): IgG en 24-72 h, más específica y duradera.", "sin_banco": true, "ok": "", "x": "El LB virgen tiene que activarse desde cero, <span class=\"cx\">por eso</span> tarda <mark>7-10 días</mark> y saca IgM. El LB de memoria ya pasó por el centro germinal, <span class=\"cx\">así que</span> responde en <mark>24-72 horas</mark> con IgG de mayor afinidad. <span class=\"res\">Es la base de la serología: IgM = reciente, IgG = contacto previo</span>.", "truco": "1.ª vez: M de «Muy lenta»; 2.ª vez: G de «Ganas».", "veces": 0}, {"n": 8, "id": "IN5-017", "c": "g", "tema": "Correlato clínico", "pregunta": "Un estudiante con fiebre, faringitis y adenopatías tiene anticuerpos IgM positivos e IgG negativos contra un virus. ¿Qué indica y por qué?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Infección reciente (respuesta primaria): el LB virgen produce primero IgM a los 7-10 días; la IgG aparece después o indica contacto previo/memoria.", "sin_banco": true, "ok": "", "x": "La <mark>cinética IgM-IgG</mark> es la base de la interpretación serológica. La IgM es la primera clase que fabrica un LB virgen, <span class=\"cx\">en cambio</span> la IgG requiere cambio de clase en el centro germinal. <span class=\"cx\">Por eso</span> IgM sola sugiere <span class=\"res\">infección aguda o reciente</span>.", "truco": "IgM = «Momento actual»; IgG = «Ya Gané antes».", "veces": 0}, {"n": 9, "id": "IN5-018", "c": "d", "tema": "Clases de inmunoglobulinas", "pregunta": "¿Qué inmunoglobulina pesa 900 kDa, circula como pentámero unido por la cadena J y queda casi exclusivamente en el intravascular?", "opciones": ["a. IgG", "b. IgM", "c. IgA secretora", "d. IgE", "e. IgD"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. IgM: pentámero de 900 kDa, intravascular, vida media de 5-6 días.", "sin_banco": true, "ok": "", "x": "El <mark>tamaño</mark> decide dónde está: la IgG (180 kDa) sale a los tejidos y cruza la placenta; <span class=\"cx\">en cambio</span>, la IgM (900 kDa) es demasiado grande y se queda en la sangre. <span class=\"cx\">Por eso</span> la IgM es <span class=\"res\">la primera en aparecer y la que mejor activa el complemento</span>.", "truco": "IgM = «Mega» (900 kDa), se queda en el vaso.", "veces": 0}, {"n": 10, "id": "IN5-019", "c": "d", "tema": "Fragmentos funcionales", "pregunta": "La digestión de un anticuerpo con pepsina produce:", "opciones": ["a. Dos fragmentos Fab independientes y un Fc.", "b. Cadenas livianas libres.", "c. Solo las regiones CDR.", "d. Un fragmento F(ab&#x27;)₂ que mantiene unidos los dos brazos.", "e. Dos fragmentos Fc unidos por el gozne."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. F(ab&#x27;)₂: la pepsina corta por debajo del gozne y deja unidos los dos brazos de unión al antígeno.", "sin_banco": true, "ok": "", "x": "En la molécula (elemento 4): la papaína corta <b>encima</b> del gozne y separa dos Fab; la pepsina corta <b>debajo</b> y deja los dos brazos unidos: <span class=\"res\">F(ab')₂</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN5-020", "c": "d", "tema": "Dominios de la cadena pesada", "pregunta": "¿Qué dominio de la cadena pesada fija los primeros factores del complemento tras la reacción antígeno-anticuerpo?", "opciones": ["a. CH2", "b. CH1", "c. CL", "d. CH3", "e. El gozne"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. CH2, primer dominio del Fc; la remoción de su ácido siálico facilita la fagocitosis y el catabolismo hepático.", "sin_banco": true, "ok": "", "x": "El tallo de la Y es el Fc: su primer dominio, <mark>CH2</mark>, fija el complemento; el siguiente, CH3, es la opsonina y la llave de la placenta (punto Ⓓ).", "truco": "", "veces": 0}, {"n": 12, "id": "IN5-021", "c": "g", "tema": "Isotipo, alotipo, idiotipo", "pregunta": "Diferencie isotipo, alotipo e idiotipo de una inmunoglobulina.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Isotipo: determinantes de la cadena pesada comunes a toda la especie, indican la clase (γ, α, μ, δ, ε). Alotipo: variantes de una subclase presentes solo en algunos individuos (herencia mendeliana). Idiotipo: diferencias del segmento variable, propias de la especificidad de cada anticuerpo.", "sin_banco": true, "ok": "", "x": "Piensa en tres niveles: el <mark>isotipo</mark> dice <b>qué clase</b> es (todos lo tenemos), el <mark>alotipo</mark> dice <b>de quién</b> es (varía entre personas) y el <mark>idiotipo</mark> dice <b>qué reconoce</b>. <span class=\"cx\">Por eso</span> <span class=\"res\">un individuo tiene tantos idiotipos como anticuerpos distintos fabrica</span>.", "truco": "ISO = igual en la especie; ALO = otro individuo; IDIO = idea propia (especificidad).", "veces": 0}, {"n": 13, "id": "IN5-022", "c": "d", "tema": "Las cinco clases", "pregunta": "¿Por qué la IgM es más eficiente que la IgG para activar el complemento por la vía clásica?", "opciones": ["a. Porque tiene mayor afinidad individual por el antígeno.", "b. Porque cruza la placenta y llega antes al tejido.", "c. Porque carece de dominio CH2.", "d. Porque es citofílica y se fija a mastocitos.", "e. Porque al ser pentámero basta una sola molécula unida al antígeno; la IgG necesita dos moléculas próximas."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Su forma pentamérica le permite iniciar la vía clásica con una sola molécula; la IgG requiere dos moléculas vecinas.", "sin_banco": true, "ok": "", "x": "El C1 necesita <mark>dos regiones Fc juntas</mark> para activarse. La IgM pentamérica ya trae cinco Fc en una sola molécula, <span class=\"cx\">en cambio</span> la IgG monomérica depende de que otra IgG se pegue al lado. <span class=\"cx\">Por eso</span> <span class=\"res\">una sola IgM basta</span>.", "truco": "IgM = cinco manos juntas; IgG = necesita una amiga.", "veces": 0}, {"n": 14, "id": "IN5-023", "c": "g", "tema": "Correlato clínico", "pregunta": "Recién nacido con microcefalia y hepatoesplenomegalia; en sangre de cordón se detecta IgM específica contra citomegalovirus. ¿Qué indica ese hallazgo y por qué?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Infección intrauterina: la IgM materna no cruza la placenta (solo la IgG por transcitosis), así que la IgM del cordón la fabricó el propio feto en respuesta a la infección.", "sin_banco": true, "ok": "", "x": "Solo la <mark>IgG</mark> atraviesa el trofoblasto por transcitosis; la IgM, grande, no pasa. <span class=\"cx\">Por eso</span> encontrar IgM en el cordón significa que el feto hizo <span class=\"res\">su propia respuesta primaria</span> contra un microbio que cruzó la placenta (el cuadro de CMV congénito: literatura).", "truco": "IgM en el cordón = el feto se defendió solo.", "veces": 0}, {"n": 15, "id": "IN5-024", "c": "g", "tema": "Las cinco clases", "pregunta": "Respecto a las inmunoglobulinas, es FALSO:", "opciones": ["a. La IgG es el 85 % de las inmunoglobulinas plasmáticas.", "b. La producción diaria de IgA (66 mg/kg) supera a todas las demás juntas.", "c. La deficiencia de IgA es rara: 1 de cada 50.000 personas.", "d. La IgE es citofílica: se fija con rapidez a los mastocitos.", "e. La deficiencia de IgG2 predispone a gérmenes encapsulados como el neumococo."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Falso: la deficiencia de IgA es la inmunodeficiencia congénita más frecuente, 1 de cada 500 personas.", "sin_banco": true, "ok": "", "x": "La deficiencia de IgA es la <mark>inmunodeficiencia congénita más frecuente</mark> (<span class=\"res\">1 de cada 500</span>) y predispone a autoinmunidad y alergia. La IgG2 responde a los polisacáridos de las cápsulas, <span class=\"cx\">por eso</span> su falta favorece al neumococo.", "truco": "IgA: la más producida y la que más falta (1/500).", "veces": 0}, {"n": 16, "id": "IN5-025", "c": "i", "tema": "Cambio de clase", "pregunta": "En el cambio de clase de las inmunoglobulinas, la IL-4 favorece la producción de:", "opciones": ["a. IgG2", "b. IgG1 e IgE", "c. IgM e IgA", "d. Solo IgD", "e. IgM pentamérica sin ayuda T"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. IgG1 e IgE (la IL-5 favorece IgM e IgA; el IFNγ, IgG2).", "sin_banco": true, "ok": "", "x": "El cambio de clase necesita un <mark>antígeno timo dependiente</mark> y la ayuda del LT; los timo independientes solo dan IgM. Las citoquinas eligen el destino: IL-4 (perfil Th2) lleva a <span class=\"res\">IgG1 e IgE</span>, <span class=\"cx\">por eso</span> la desviación Th2 explica la alergia.", "truco": "IL-4 y Th2 = alergia = IgE.", "veces": 0}], "tabla": {"cab": ["", "IgM", "IgG", "IgA", "IgE", "IgD"], "filas": [["Forma", "pentámero, 900 kDa", "monómero, 180 kDa", "monómero o dímero secretor", "monómero", "monómero"], ["Dónde", "intravascular", "tejidos, LCR, placenta", "secreciones y leche", "pegada a mastocitos", "membrana del LB"], ["Vida media", "5-6 días", "15-20 días", "4-5 días", "muy breve", "muy baja en plasma"], ["Clave", "1.ª en aparecer; activa complemento sola", "85 %; cruza placenta (IgG1)", "la más producida; exclusión inmune", "alergia y parásitos", "evita tolerancia del LB"], ["🔑 Lo que no debes olvidar", "en cordón = infección fetal", "falta IgG2 = neumococo", "falta IgA = 1/500", "citofílica", "falta en el LB fetal"]]}, "fuente": "Fuente: tu teoría — Clase 11a Linfocitos B y centros germinales, Clase 11b Inmunoglobulinas y respuesta humoral (Rojas, 17.ª ed., cap. 11)."}, {"n": 11, "slug": "Mucosas_y_reproduccion", "titulo": "Mucosas, privilegio inmunológico y embarazo", "subtitulo": "mucosas, testículo, SNC, ojo y placenta", "grupo": "g6", "lema": "La idea: cada órgano arma <b>su propia mezcla</b> de barrera, células y tolerancia. Las <b class=\"i\">mucosas</b> deben matar al patógeno <b>sin inflamarse</b> contra la microbiota (IgA, Treg, células M). Los órganos con <b class=\"g\">privilegio inmunológico</b> (testículo, SNC, ojo) prefieren tolerar, porque una inflamación los destruiría. Y en el <b class=\"d\">embarazo</b> el trofoblasto <b>apaga activamente</b> la respuesta materna contra los antígenos paternos. Importa porque cuando el equilibrio falla aparecen pénfigo, EPOC, salpingitis, infertilidad, aborto recurrente o preeclampsia. En la imagen: mucosa intestinal, interfaz materno-fetal y túbulo seminífero.", "img": "img/11.webp", "mini": "img/mini/11.webp", "ratio": 1.5, "etiquetas": [{"n": "⑥", "t": "Célula M", "s": "entrega bacterias<br>a la dendrítica", "c": "i", "x": 0.8, "y": 6, "ax": 13.7, "ay": 37, "al": "l"}, {"n": "⑤", "t": "IgA dimérica", "s": "cruza el epitelio<br>(transcitosis)", "c": "i", "x": 24, "y": 6, "ax": 26.7, "ay": 38, "d": "A"}, {"n": "㉑", "t": "Trofoblasto", "s": "pasa IgG1<br>al feto", "c": "d", "x": 40, "y": 6, "ax": 40.4, "ay": 22}, {"n": "⑱⑲", "t": "Extravelloso", "s": "HLA-G, E, C;<br>IDO, FasL", "c": "d", "x": 55.5, "y": 6, "ax": 52.7, "ay": 42}, {"n": "⑨⑩", "t": "Espermatozoides", "s": "antígenos de<br>la pubertad", "c": "g", "x": 72.5, "y": 6, "ax": 81, "ay": 27.3}, {"n": "⑨", "t": "Barrera de Sertoli", "s": "uniones estrechas<br>(BTB)", "c": "g", "x": 99.2, "y": 6, "ax": 84.3, "ay": 45, "al": "r"}, {"n": "", "t": "Placa de Peyer", "s": "linfocitos<br>del GALT", "c": "i", "x": 0.8, "y": 90, "ax": 12.4, "ay": 65, "al": "l"}, {"n": "㉒", "t": "Plasmática", "s": "fabrica IgA", "c": "i", "x": 22, "y": 90, "ax": 29.3, "ay": 56, "d": "D"}, {"n": "⑰", "t": "NK deciduales", "s": "80 %: no matan,<br>remodelan", "c": "d", "x": 38, "y": 90, "ax": 37, "ay": 52, "d": "B"}, {"n": "㉔", "t": "Arteria espiral", "s": "baja resistencia,<br>alto flujo", "c": "d", "x": 54, "y": 90, "ax": 52, "ay": 66.4, "d": "C"}, {"n": "⑩", "t": "Leydig", "s": "testosterona", "c": "g", "x": 73, "y": 90, "ax": 76.8, "ay": 70.3}, {"n": "⑩", "t": "Macrófago", "s": "ayuda a la<br>testosterona", "c": "g", "x": 99.2, "y": 90, "ax": 88.2, "ay": 67.4, "al": "r"}], "diapos": [{"img": "img/11.webp", "ratio": 1.5, "titulo": "Mucosa, decidua y túbulo seminífero", "texto": "La <mark>IgA</mark> cruza el epitelio ⑤ y la célula M entrega antígeno ⑥; en la decidua mandan las <b>NK deciduales</b> ⑰ y el trofoblasto se esconde con HLA-G ⑱; Sertoli aísla al espermatozoide ⑨.", "etiquetas": [{"n": "⑥", "t": "Célula M", "s": "entrega bacterias<br>a la dendrítica", "c": "i", "x": 0.8, "y": 6, "ax": 13.7, "ay": 37, "al": "l"}, {"n": "⑤", "t": "IgA dimérica", "s": "cruza el epitelio<br>(transcitosis)", "c": "i", "x": 24, "y": 6, "ax": 26.7, "ay": 38, "d": "A"}, {"n": "㉑", "t": "Trofoblasto", "s": "pasa IgG1<br>al feto", "c": "d", "x": 40, "y": 6, "ax": 40.4, "ay": 22}, {"n": "⑱⑲", "t": "Extravelloso", "s": "HLA-G, E, C;<br>IDO, FasL", "c": "d", "x": 55.5, "y": 6, "ax": 52.7, "ay": 42}, {"n": "⑨⑩", "t": "Espermatozoides", "s": "antígenos de<br>la pubertad", "c": "g", "x": 72.5, "y": 6, "ax": 81, "ay": 27.3}, {"n": "⑨", "t": "Barrera de Sertoli", "s": "uniones estrechas<br>(BTB)", "c": "g", "x": 99.2, "y": 6, "ax": 84.3, "ay": 45, "al": "r"}, {"n": "", "t": "Placa de Peyer", "s": "linfocitos<br>del GALT", "c": "i", "x": 0.8, "y": 90, "ax": 12.4, "ay": 65, "al": "l"}, {"n": "㉒", "t": "Plasmática", "s": "fabrica IgA", "c": "i", "x": 22, "y": 90, "ax": 29.3, "ay": 56, "d": "D"}, {"n": "⑰", "t": "NK deciduales", "s": "80 %: no matan,<br>remodelan", "c": "d", "x": 38, "y": 90, "ax": 37, "ay": 52, "d": "B"}, {"n": "㉔", "t": "Arteria espiral", "s": "baja resistencia,<br>alto flujo", "c": "d", "x": 54, "y": 90, "ax": 52, "ay": 66.4, "d": "C"}, {"n": "⑩", "t": "Leydig", "s": "testosterona", "c": "g", "x": 73, "y": 90, "ax": 76.8, "ay": 70.3}, {"n": "⑩", "t": "Macrófago", "s": "ayuda a la<br>testosterona", "c": "g", "x": 99.2, "y": 90, "ax": 88.2, "ay": 67.4, "al": "r"}]}, {"img": "img/11_2.webp", "ratio": 1.5, "titulo": "Piel: Langerhans y pénfigo", "texto": "La <mark>célula de Langerhans</mark> cambia CCR6 por CCR7 y migra al ganglio ②; en la dermis esperan LsT de <b>memoria</b> residentes ③ <span class=\"lt2\">A</span>; en el pénfigo, los anticuerpos contra el desmosoma separan los queratinocitos ①.", "etiquetas": [{"n": "①", "t": "Queratinocitos", "s": "unidos por<br>desmosomas", "c": "g", "x": 0.5, "y": 8, "ax": 6.5, "ay": 38, "al": "l"}, {"n": "②", "t": "Langerhans inmadura", "s": "CCR6: va al<br>sitio del antígeno", "c": "i", "x": 28, "y": 8, "ax": 22, "ay": 36}, {"n": "②", "t": "Langerhans madura", "s": "CCR7 (por TNF):<br>migra al ganglio", "c": "i", "x": 50, "y": 8, "ax": 48.8, "ay": 44}, {"n": "①", "t": "Ampolla", "s": "intraepidérmica:<br>pénfigo", "c": "d", "x": 72, "y": 8, "ax": 78, "ay": 40}, {"n": "①", "t": "Autoanticuerpos", "s": "contra el<br>desmosoma", "c": "d", "x": 99.5, "y": 8, "ax": 86, "ay": 27, "al": "r"}, {"n": "", "t": "Capilar", "s": "dermis", "c": "g", "x": 0.5, "y": 91, "ax": 11.7, "ay": 63.5, "al": "l"}, {"n": "③", "t": "LsT de memoria", "s": "residentes,<br>no vírgenes", "c": "i", "x": 21, "y": 91, "ax": 24.7, "ay": 67, "d": "A"}, {"n": "②", "t": "Linfático", "s": "lleva la célula<br>al ganglio (CCL19)", "c": "i", "x": 50, "y": 91, "ax": 56, "ay": 70}, {"n": "①", "t": "Queratinocito suelto", "s": "acantólisis:<br>se separa", "c": "d", "x": 76, "y": 91, "ax": 74.9, "ay": 46}]}, {"img": "img/11_3.webp", "ratio": 1.5, "titulo": "SNC y ojo: privilegio inmunológico", "texto": "La <mark>microglía</mark> responde <span class=\"cx\">primero</span> ⑭; en el <b>OVLT</b> la barrera no es hermética y pasan los pirógenos ⑫; el humor acuoso drena por el canal de Schlemm a las venas, sin linfáticos ⑮.", "etiquetas": [{"n": "", "t": "Astrocito", "s": "su pie sella<br>la barrera", "c": "g", "x": 0.5, "y": 8, "ax": 6.5, "ay": 22, "al": "l"}, {"n": "⑭", "t": "Microglía", "s": "macrófago residente:<br>responde primero", "c": "i", "x": 21, "y": 8, "ax": 26, "ay": 27}, {"n": "⑫", "t": "Capilar fenestrado", "s": "OVLT: barrera<br>no hermética", "c": "d", "x": 50, "y": 8, "ax": 58.6, "ay": 40}, {"n": "⑮", "t": "Humor acuoso", "s": "cámara<br>anterior", "c": "i", "x": 73, "y": 8, "ax": 74.9, "ay": 29}, {"n": "⑮", "t": "Córnea", "s": "avascular", "c": "g", "x": 99.5, "y": 8, "ax": 84.6, "ay": 22, "al": "r"}, {"n": "⑫", "t": "Barrera hematoencefálica", "s": "uniones estrechas:<br>hermética", "c": "i", "x": 0.5, "y": 91, "ax": 17, "ay": 52, "al": "l"}, {"n": "⑫", "t": "Glía con TLR", "s": "detecta<br>los PAMP", "c": "g", "x": 31, "y": 91, "ax": 46.9, "ay": 60.5}, {"n": "⑫", "t": "Pirógenos", "s": "TNF, IL-1, IFN-α<br>pasan: fiebre", "c": "d", "x": 50, "y": 91, "ax": 52, "ay": 54.7}, {"n": "", "t": "Cristalino", "s": "", "c": "g", "x": 70, "y": 91, "ax": 74.9, "ay": 62}, {"n": "⑮", "t": "Canal de Schlemm", "s": "drena a las venas:<br>sin linfáticos", "c": "i", "x": 99.5, "y": 91, "ax": 89.5, "ay": 51.5, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Tres paneles: <b class=\"i\">1 mucosa intestinal</b> con placa de Peyer, <b class=\"d\">2 placenta y decidua</b> con NK deciduales alrededor de una arteria espiral, <b class=\"g\">3 túbulo seminífero</b> con la barrera de Sertoli. <b>Azul</b> = mucosas; <b>rojo</b> = embarazo; <b>gris</b> = privilegio inmunológico.", "En el intestino, la <mark>célula M</mark> entrega bacterias a la dendrítica y la <mark>IgA dimérica</mark> cruza el epitelio <b>a través</b> de las células (transcitosis) hacia la luz; los linfocitos intraepiteliales son en un 60 % γδ.", "En la decidua, las <mark>NK deciduales</mark> (80 %) no matan: remodelan la arteria espiral con IFN-γ. El trofoblasto se esconde con HLA-G, E y C, e IDO. En el testículo, las uniones estrechas entre células de Sertoli forman la <span class=\"res\">barrera hemato-testicular</span>."], "recordar": "mucosa = <b>IgA + Treg + tolerancia a la flora</b>; privilegio = <b>más tolerancia que rechazo</b>; embarazo = <b>el trofoblasto apaga a la madre</b> (HLA-G, IDO, FasL)."}, "numeros": [{"l": "A", "html": "<b>Linfocitos intraepiteliales</b>: <b class=\"n\">60 %</b> con TCR γδ, maduran en el intestino. Microbiota: <b class=\"n\">100 billones</b> de bacterias que aportan el <b class=\"n\">10 %</b> de las calorías. <b>Piel</b>: SALT con <b class=\"n\">20.000 millones</b> de LsT de memoria. <b>Hígado</b>: filtra la sangre <b class=\"n\">40 veces al día</b>.", "rango": null}, {"l": "B", "html": "<b>Decidua</b>: NK deciduales <b class=\"a\">80 %</b>, macrófagos <b class=\"n\">20 %</b>; LsT CD4 y CD8 = <b class=\"n\">10-20 %</b> de los leucocitos deciduales del 1.er trimestre.", "rango": null}, {"l": "C", "html": "<b>Hormonas del embarazo</b>: estrógenos hasta <b class=\"a\">×10</b>. <b>Preeclampsia</b>: <b class=\"a\">5-7 %</b> de los embarazos, tras la semana 20; <b class=\"a\">15-20 %</b> de las muertes maternas en países en desarrollo.", "rango": {"min": 0, "max": 40, "unidad": "semanas de gestación", "zonas": [[0, 20, "n", "antes: no es preeclampsia"], [20, 40, "a", "puede aparecer"]], "marcas": [20]}}, {"l": "D", "html": "<b>Lactancia</b>: calostro <b class=\"a\">10-100 millones</b> de leucocitos/mL y <b class=\"a\">5-6 g</b> de IgA en 24 h; leche madura <b class=\"n\">100.000</b>/mL. Al pecho: eccema <b class=\"b\">11 %</b> vs 57 %, asma <b class=\"b\">3 %</b> vs 22 %.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la barrera a la tolerancia", "subtitulo": "estímulo → células del órgano → mecanismo → resultado (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> llegan antígenos sin pausa: microbiota y alimentos al intestino, humo al bronquio, antígenos paternos del feto a la decidua, espermatozoides que maduran en la pubertad.", "pr": "el órgano debe <b>distinguir</b> lo peligroso de lo inofensivo.", "pr_tit": "Produce:", "rf": "Preguntas ④⑨ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Células del órgano", "m": "<b>Quién responde:</b> piel = queratinocitos, Langerhans y SALT; intestino = células M, IgA, γδ; hígado = LSEC y Kupffer; SNC = microglía; decidua = dNKs y macrófagos <span class=\"lt2\">B</span>.", "pr": "una respuesta local con su propio estilo.", "pr_tit": "Produce:", "rf": "Preguntas ②③⑥⑭⑰", "color": "p2"}, {"t": "3. Mecanismo de tolerancia", "m": "<b>Por qué no se inflama:</b> polisacárido A de <b>Bacteroides</b> → Treg e IL-10; LSEC tolerogénicas; humor acuoso → Treg y CD95L; trofoblasto con <mark>HLA-G, IDO, FasL</mark>; hormonas (estrógenos ×10, progesterona, hCG) <span class=\"lt2\">C</span>.", "pr": "más tolerancia que rechazo; en el embarazo predomina Th2.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑦⑩⑮⑱⑲⑳", "color": "p3"}, {"t": "4. Resultado", "m": "<b>Qué produce:</b> flora comensal tolerada; trasplante hepático y corneal aceptados; arterias espirales remodeladas; IgG1 materna al feto; calostro con IgA <span class=\"lt2\">D</span>.", "pr": "homeostasis y protección pasiva del recién nacido.", "pr_tit": "Produce:", "rf": "Preguntas ㉑㉒", "color": "p4"}, {"t": "5. Si falla", "m": "<b>Qué pasa si se rompe el equilibrio:</b> anticuerpos anti-desmosoma (pénfigo), humo sostenido (EPOC), <b>Chlamydia</b> en espermatozoides (salpingitis), BTB rota (antiespermatozoide), dNKs que atacan, antifosfolípidos, placentación deficiente.", "pr": "<span class=\"res\">pénfigo, EPOC, infertilidad, aborto recurrente, preeclampsia</span>.", "pr_tit": "Produce:", "rf": "Preguntas ①⑧⑪⑯㉓㉔", "color": "p5"}], "extra": [{"html": "🧠 <b>Eje neuroinmunoendocrino:</b> IL-1, IL-6 y TNF llegan al hipotálamo por el <b>OVLT</b> → fiebre y anorexia; el eje hipotálamo-hipófisis responde con corticosteroides. El <b>simpático</b> estimula la inflamación; el <b>vago</b> (acetilcolina) la frena ⑫⑬. El VIH entra al cerebro dentro de monocitos (caballo de Troya).", "k": ""}, {"html": "🧫 <b>Tracto genital femenino:</b> introito como piel; <b>vagina</b> (CD8 de memoria) → <i>Candida</i>, <i>Trichomonas</i>; <b>cérvix</b> (más inmunidad adquirida, IgA e IgG) → VIH, <i>Chlamydia</i>, gonococo; <b>trompas</b> → salpingitis. SLPI y elafina limitan el daño; si faltan, vaginitis y cervicitis.", "k": "k"}], "escaleras": [{"c": "d", "t": "🤰 Del embarazo tolerado a la preeclampsia", "pasos": ["Trofoblasto invade la decidua", "dNKs <b>remodelan</b> arterias espirales", "si la placentación es <b>deficiente</b>: hipoxia", "estrés oxidativo y complemento sin control", "disfunción endotelial", "<b>preeclampsia</b>: HTA + proteinuria tras la semana 20"]}, {"c": "g", "t": "🔒 Del privilegio a la infertilidad", "pasos": ["Espermatozoides con antígenos <b>nuevos</b> en la pubertad", "BTB de Sertoli los aísla", "trauma, orquitis o vasectomía <b>rompen</b> la BTB", "anticuerpos <b>antiespermatozoide</b>", "<b>infertilidad</b>"]}], "html": "", "fuente": "Fuente: tu teoría — Clase 12a (piel, respiratorio, intestino, hígado, genital femenino), Clase 12b (testículo, riñón, SNC, ojo, hueso) y Clase 13 (interfaz materno-fetal, trofoblasto, hormonas, IgG, lactancia, aborto, preeclampsia)."}, "preguntas": [{"n": 1, "id": "IN6-001", "c": "i", "tema": "Piel: pénfigo", "pregunta": "En el pénfigo, los autoanticuerpos que producen las ampollas se dirigen contra:", "opciones": ["a. El colágeno IV de la membrana basal.", "b. Las moléculas del desmosoma (desmogleínas, desmocolinas, desmoplacina).", "c. La queratina del estrato córneo.", "d. Las células de Langerhans.", "e. Los melanocitos de la capa basal."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Las moléculas del desmosoma; al unirse activan el complemento y separan a los queratinocitos.", "sin_banco": true, "ok": "", "x": "Los queratinocitos se mantienen unidos por <mark>desmosomas</mark>. <span class=\"cx\">Cuando</span> los autoanticuerpos se pegan a sus proteínas activan el complemento, <span class=\"cx\">así que</span> la unión se rompe y las capas de la epidermis se separan: <span class=\"res\">ampollas del pénfigo</span>.", "truco": "Pénfigo = «Pega-fuera»: despega el desmosoma.", "veces": 0}, {"n": 2, "id": "IN6-002", "c": "i", "tema": "Piel: células de Langerhans", "pregunta": "¿Qué cambio de receptores marca la maduración de la célula de Langerhans y para qué le sirve?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Inmadura expresa CCR6 (va donde hay CCL20, al sitio del antígeno); al madurar adquiere CCR7, inducido por TNF, y migra al ganglio siguiendo a CCL19 para presentar el antígeno.", "sin_banco": true, "ok": "", "x": "La célula de Langerhans es la <mark>dendrítica de la epidermis</mark>. <span class=\"cx\">Primero</span> se queda en la piel atraída por CCL20 (CCR6) para capturar; después cambia a <mark>CCR7</mark>, <span class=\"cx\">por eso</span> abandona la piel y viaja al ganglio, donde <span class=\"res\">presenta el antígeno a los linfocitos T</span>.", "truco": "CCR6 = Sentarse (captura en piel); CCR7 = Siete leguas al ganglio.", "veces": 0}, {"n": 3, "id": "IN6-003", "c": "i", "tema": "Piel: SALT", "pregunta": "Respecto al tejido linfoide asociado a la piel (SALT), es FALSO:", "opciones": ["a. Alberga unos 20.000 millones de linfocitos T residentes de memoria.", "b. Los CD8 de memoria se ubican en la epidermis y los CD4 en la dermis.", "c. La vitamina D controla su reclutamiento vía CCL17/CCL27 y el receptor CCR4.", "d. Los Th22 están aumentados en la dermatitis atópica.", "e. Sus linfocitos T son vírgenes y llegan solo por la selectina L a las vénulas de la piel."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Falso: los linfocitos T del SALT son residentes de memoria, no vírgenes.", "sin_banco": true, "ok": "", "x": "La piel guarda un <mark>ejército de memoria</mark> de unos <span class=\"res\">20.000 millones de LsT</span>: CD8 arriba (epidermis) y CD4 abajo (dermis). La vitamina D estimula CCL17 y CCL27, que los atraen por CCR4. <span class=\"cx\">Por eso</span> la opción e, que habla de linfocitos vírgenes, es falsa.", "truco": "SALT: «8 arriba, 4 abajo» (CD8 epidermis, CD4 dermis).", "veces": 0}, {"n": 4, "id": "IN6-004", "c": "i", "tema": "Tracto respiratorio", "pregunta": "Varón de 62 años, fumador de 40 paquetes-año, con tos productiva y disnea progresiva desde hace años. ¿Qué mecanismo inmunológico explica que su inflamación bronquial no se apague y termine en EPOC?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El humo mantiene activos los factores quimiotácticos del epitelio bronquial mientras dura la inhalación, así que los neutrófilos se reclutan y activan sin pausa y la inflamación se perpetúa hasta dañar la arquitectura pulmonar.", "sin_banco": true, "ok": "", "x": "Normalmente la inflamación se resuelve (los macrófagos alveolares incluso producen lipoxinas y resolvinas). En el fumador, <span class=\"cx\">en cambio</span>, el estímulo <mark>no cesa</mark>, <span class=\"cx\">por eso</span> los neutrófilos siguen llegando y la inflamación se vuelve crónica: <span class=\"res\">EPOC</span>. <span class=\"cx\">Además</span>, el aumento de TLR2/TLR4 en el enfisema agrava la respuesta al neumococo.", "truco": "Humo que no para = neutrófilo que no se va.", "veces": 0}, {"n": 5, "id": "IN6-005", "c": "i", "tema": "Tracto gastrointestinal: microbiota", "pregunta": "El polisacárido A de *Bacteroides fragilis* induce tolerancia intestinal porque:", "opciones": ["a. Induce linfocitos T reguladores productores de IL-10 que frenan la IL-17.", "b. Destruye a las células M de las placas de Peyer.", "c. Estimula la IL-17 y el reclutamiento de neutrófilos.", "d. Bloquea la producción de IgA secretora.", "e. Deprime a los linfocitos T reguladores, como *Clostridium*."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Induce en el colon Treg productores de IL-10 que frenan la IL-17 y evitan la enfermedad inflamatoria intestinal.", "sin_banco": true, "ok": "", "x": "Panel 1: sobre el epitelio viven las bacterias de la luz. <b>Bacteroides</b> las «amansa»: su <mark>polisacárido A</mark> induce Treg con IL-10 que frenan la IL-17, <span class=\"cx\">así que</span> <span class=\"res\">la mucosa tolera a la flora</span> sin dejar de vigilar.", "truco": "", "veces": 0}, {"n": 6, "id": "IN6-006", "c": "i", "tema": "Tracto gastrointestinal: GALT", "pregunta": "Respecto a los linfocitos intraepiteliales del intestino, es correcto:", "opciones": ["a. El 60 % tiene TCR αβ y madura en el timo.", "b. Son linfocitos B productores de IgE.", "c. Solo aparecen cuando hay una infección intestinal.", "d. El 60 % expresa TCR γδ y madura en el propio intestino, no en el timo.", "e. Son células M que capturan bacterias del lumen."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El 60 % lleva receptor γδ y completa su maduración en el intestino, no en el timo.", "sin_banco": true, "ok": "", "x": "En el panel 1 los linfocitos entre las células epiteliales son los <mark>intraepiteliales</mark>: el <span class=\"res\">60 % γδ</span> y maduran en el propio intestino (punto Ⓐ). La célula M de la placa de Peyer es otra cosa: captura y entrega a la dendrítica.", "truco": "", "veces": 0}, {"n": 7, "id": "IN6-007", "c": "i", "tema": "Hígado", "pregunta": "¿Qué célula explica la buena aceptación del trasplante hepático aun sin compatibilidad de histocompatibilidad?", "opciones": ["a. El hepatocito", "b. La célula estrellada", "c. La célula endotelial sinusoidal (LSEC)", "d. El neutrófilo", "e. El linfocito B"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. La LSEC: presenta antígeno de forma tolerogénica (a CD4 solo induce IL-4 e IL-10; a CD8 le frena el IFN-γ).", "sin_banco": true, "ok": "", "x": "El hígado filtra la sangre <span class=\"res\">40 veces al día</span> y no puede inflamarse ante cada antígeno. Las <mark>LSEC</mark> presentan antígeno pero no generan células efectoras, <span class=\"cx\">así que</span> inducen tolerancia; las células de Kupffer ayudan con IL-10 constante. <span class=\"cx\">Por eso</span> el <span class=\"res\">injerto hepático se tolera</span>.", "truco": "LSEC = «Le Sale En Calma».", "veces": 0}, {"n": 8, "id": "IN6-008", "c": "i", "tema": "Tracto genital femenino", "pregunta": "Mujer de 22 años con dolor pélvico y fiebre; se diagnostica salpingitis por *Chlamydia trachomatis*. ¿Cómo superó la bacteria las barreras del cérvix y el útero, y qué complicaciones futuras puede tener?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Se adhiere a los espermatozoides, que la transportan más allá del cérvix como «pasajero no invitado»; en la trompa produce salpingitis que destruye la mucosa y puede causar infertilidad o embarazo ectópico.", "sin_banco": true, "ok": "", "x": "El <mark>cérvix</mark> es el segmento con más inmunidad adquirida y es vulnerable a VIH, <b>Chlamydia</b> y gonococo; la vagina, <span class=\"cx\">en cambio</span>, a <b>Candida</b> y <b>Trichomonas</b>. <b>Chlamydia</b> y gonococo usan a los espermatozoides como <mark>vehículo</mark>, <span class=\"cx\">así que</span> llegan a la trompa: <span class=\"res\">salpingitis, infertilidad o embarazo ectópico</span>.", "truco": "El espermatozoide hace de taxi para la clamidia.", "veces": 0}, {"n": 9, "id": "IN6-009", "c": "g", "tema": "Testículo", "pregunta": "Los espermatozoides necesitan la protección de la barrera hemato-testicular porque:", "opciones": ["a. Carecen por completo de antígenos de superficie.", "b. Expresan HLA-G, que activa a las NK.", "c. Expresan sus antígenos recién en la pubertad, cuando el sistema inmune ya madurado los reconoce como extraños.", "d. El testículo carece de macrófagos.", "e. Las células de Sertoli producen IgE contra ellos."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Sus antígenos aparecen en la pubertad, cuando la tolerancia central ya se formó; la BTB (Sertoli y peritubulares) los aísla.", "sin_banco": true, "ok": "", "x": "Panel 3: las uniones estrechas entre las <mark>células de Sertoli</mark> separan las células germinales de la sangre. Así los antígenos que aparecen en la pubertad <span class=\"res\">no se exponen</span> al sistema inmune.", "truco": "", "veces": 0}, {"n": 10, "id": "IN6-010", "c": "g", "tema": "Testículo", "pregunta": "¿Por qué IL-1α, IL-6 y activina A, abundantes en el testículo, no producen inflamación allí?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque en el microambiente testicular, modulado por las células de Sertoli, cumplen la función paradójica de promover la formación de espermatozoides en lugar de inflamar.", "sin_banco": true, "ok": "", "x": "El testículo es un <mark>órgano inmunoprivilegiado</mark>: genera más tolerancia que rechazo, <span class=\"cx\">porque</span> una inflamación sin control llevaría a esterilidad. <span class=\"cx\">Por eso</span> las células de Sertoli reorientan estas citoquinas hacia la <span class=\"res\">espermatogénesis</span>. Los macrófagos testiculares, <span class=\"cx\">además</span>, ayudan a fabricar testosterona (25-hidroxicolesterol).", "truco": "En el testículo la IL-6 «fabrica», no «quema».", "veces": 0}, {"n": 11, "id": "IN6-011", "c": "g", "tema": "Riñón", "pregunta": "NO es un mecanismo de producción de glomerulonefritis:", "opciones": ["a. Precipitación de complejos inmunes circulantes que activan el complemento por vía clásica.", "b. Autoanticuerpos contra la osteoprotegerina.", "c. Unión en el glomérulo de anticuerpos y antígenos que circulaban por separado.", "d. Anticuerpos contra antígenos «sembrados» en el riñón.", "e. Infiltración por linfocitos T y macrófagos citotóxicos."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Los anticuerpos contra la osteoprotegerina causan osteoporosis, no glomerulonefritis.", "sin_banco": true, "ok": "", "x": "El riñón es un <mark>filtro</mark> que concentra y precipita complejos inmunes; al activar el complemento, se daña. Los cuatro mecanismos son: complejos circulantes, unión in situ, antígenos sembrados e infiltración celular. <span class=\"res\">La anti-osteoprotegerina pertenece a la osteoinmunología</span>.", "truco": "GN: «Circula, Se une, Siembra, Infiltra».", "veces": 0}, {"n": 12, "id": "IN6-012", "c": "g", "tema": "Sistema nervioso central", "pregunta": "¿En qué estructura la barrera hematoencefálica no es hermética, permite la entrada de pirógenos endógenos que producen fiebre y la aprovecha el neurocisticerco?", "opciones": ["a. Plexo coroideo (BCSFB)", "b. Barrera leptomeníngea (BLMB)", "c. Barrera hematorretiniana", "d. OVLT (órgano circunventricular de la lámina terminal)", "e. Canal de Schlemm"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El OVLT: sus células gliales detectan PAMPs con TLR y dejan entrar TNF, IL-1 e IFN-α.", "sin_banco": true, "ok": "", "x": "En el <mark>OVLT</mark> la BBB es permeable a propósito: así el cerebro «se entera» de la infección y el hipotálamo produce <span class=\"res\">fiebre</span>. <span class=\"cx\">En cambio</span>, la barrera leptomeníngea es la más estricta. Esa misma puerta abierta es la que usa el <span class=\"res\">neurocisticerco</span>.", "truco": "OVLT = «Oye, Ve, La Temperatura».", "veces": 0}, {"n": 13, "id": "IN6-013", "c": "g", "tema": "Sistema nervioso autónomo", "pregunta": "¿Cómo se oponen el sistema simpático y el nervio vago en su efecto sobre la respuesta inmune?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El simpático (norepinefrina, adrenalina) estimula la inflamación; el vago, por acetilcolina en su vía eferente, frena las citoquinas de los macrófagos y estimula la liberación de corticosteroides inmunodepresores.", "sin_banco": true, "ok": "", "x": "El sistema nervioso es <mark>rector</mark> del inmune. El simpático enciende la inflamación (aunque vía receptores β también induce IL-10), <span class=\"cx\">en cambio</span> el <mark>vago</mark> la apaga con acetilcolina. <span class=\"cx\">Por eso</span> se habla del <span class=\"res\">reflejo antiinflamatorio colinérgico</span> (nombre: literatura).", "truco": "Simpático = acelera; Vago = «vagancia» de los macrófagos.", "veces": 0}, {"n": 14, "id": "IN6-014", "c": "g", "tema": "Respuesta inmune en el SNC", "pregunta": "¿Qué célula es la primera en responder ante una violación del entorno inmunoprivilegiado del SNC?", "opciones": ["a. La microglía", "b. El oligodendrocito", "c. El neutrófilo", "d. El linfocito B", "e. El astrocito"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La microglía, el macrófago residente, incluso antes de que se altere la BBB.", "sin_banco": true, "ok": "", "x": "La respuesta innata del SNC recae en tres células: <mark>microglía</mark> (primera en responder, TLR2/TLR4), astrocitos (sensores que expresan HLA y producen CXCL10, IFN-β, IL-10) y oligodendrocitos (remielinizan). <span class=\"res\"><span class=\"cx\">Primero</span> responde la microglía</span>.", "truco": "Microglía = «Mini-macrófago» del cerebro, el primero en llegar.", "veces": 0}, {"n": 15, "id": "IN6-015", "c": "g", "tema": "Ojo", "pregunta": "Respecto al privilegio inmunológico del ojo, es FALSO:", "opciones": ["a. La córnea carece de HLA-II y expresa poco HLA-I.", "b. El humor acuoso transforma linfocitos T en T reguladores.", "c. No hay canales linfáticos en la cámara anterior, el vítreo ni el espacio subretinal.", "d. Las células corneales expresan CD95L, que induce apoptosis de linfocitos.", "e. El humor acuoso drena por linfáticos a los ganglios cervicales, donde se activan linfocitos efectores."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Falso: el humor acuoso drena directamente a la circulación venosa por el canal de Schlemm, sin linfáticos.", "sin_banco": true, "ok": "", "x": "El ojo esconde sus antígenos: <mark>sin linfáticos</mark>, sin HLA-II en la córnea y con un humor acuoso que induce Treg y apoptosis (CD95L), VIP, somatostatina y α-MSH. <span class=\"cx\">Por eso</span> los antígenos no llegan a los ganglios, y <span class=\"res\">los injertos de córnea se toleran casi siempre</span>.", "truco": "Córnea: sin HLA-II, sin linfa, sin rechazo.", "veces": 0}, {"n": 16, "id": "IN6-016", "c": "g", "tema": "Osteoinmunología", "pregunta": "El mecanismo de acción del romosozumab en la osteoporosis es:", "opciones": ["a. Neutralizar la osteoprotegerina.", "b. Estimular la actividad de los osteoclastos.", "c. Inhibir la esclerostina, freno de los osteoblastos, e inducir neoformación ósea.", "d. Bloquear la PGE1.", "e. Activar la molécula OSCAR de los macrófagos."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Anticuerpo monoclonal que inhibe la esclerostina (inhibidor osteoblástico), así induce neoformación ósea.", "sin_banco": true, "ok": "", "x": "La esclerostina <mark>frena al osteoblasto</mark>; si el romosozumab la bloquea, el osteoblasto queda libre y forma hueso. <span class=\"cx\">En cambio</span>, neutralizar la <mark>osteoprotegerina</mark> (como hacen ciertos autoanticuerpos) suelta a los osteoclastos y <span class=\"res\">causa osteoporosis</span>.", "truco": "Romosozumab: «quita el freno al constructor».", "veces": 0}, {"n": 17, "id": "IN6-017", "c": "d", "tema": "Interfaz materno-fetal", "pregunta": "Respecto a las NK deciduales (dNKs), es correcto:", "opciones": ["a. Son el 20 % de los leucocitos deciduales y son CD16+ desde el inicio.", "b. Son el 80 % de la decidua y, mediante IFN-γ, remodelan las arterias espirales en vasos de baja resistencia y alto flujo.", "c. Su función principal es destruir al trofoblasto extravelloso.", "d. Desaparecen al iniciarse la gestación, igual que las dendríticas.", "e. Producen IDO para agotar el triptófano."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Son el 80 % (CD56+CD16-) y remodelan los capilares espirales con IFN-γ; si atacan al trofoblasto, hay pérdida recurrente del embarazo.", "sin_banco": true, "ok": "", "x": "Panel 2: alrededor de la arteria espiral están las <mark>NK deciduales</mark> (punto Ⓑ, 80 % de la decidua). En vez de matar, la <span class=\"res\">remodelan con IFN-γ</span> en un vaso ancho, de baja resistencia y alto flujo.", "truco": "", "veces": 0}, {"n": 18, "id": "IN6-018", "c": "d", "tema": "El feto desactiva la respuesta materna", "pregunta": "¿Qué moléculas expresa el citotrofoblasto extravelloso para bloquear la citotoxicidad de las NK deciduales?", "opciones": ["a. HLA-A y HLA-B clásicos", "b. HLA-II clásico", "c. CD80 y CD86", "d. HLA-G, HLA-E y HLA-C", "e. CD1"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Las moléculas no clásicas HLA-G, HLA-E y HLA-C; no expresa HLA-II clásico ni HLA-A/B.", "sin_banco": true, "ok": "", "x": "Panel 2: el trofoblasto que baja a la decidua (extravelloso) expresa <mark>HLA-G, E y C</mark> y no HLA clásico: así <span class=\"res\">la NK no lo ataca</span> y el LsT no ve los antígenos paternos.", "truco": "", "veces": 0}, {"n": 19, "id": "IN6-019", "c": "d", "tema": "El feto desactiva la respuesta materna", "pregunta": "¿Qué función cumple la IDO (indolamina 2,3-dioxigenasa) producida por el trofoblasto?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Degrada el triptófano; al agotar este aminoácido indispensable, los linfocitos T maternos que podrían reaccionar contra antígenos fetales no pueden funcionar.", "sin_banco": true, "ok": "", "x": "El LsT necesita <mark>triptófano</mark> para proliferar. El trofoblasto lo consume con la IDO, <span class=\"cx\">así que</span> crea un entorno «sin combustible» para el linfocito materno. Es el mismo truco que usan los <span class=\"res\">Treg vía CTLA-4 en la dendrítica</span> (clase 10).", "truco": "IDO = «Infinito Desayuno Obligado» que deja al LsT sin triptófano.", "veces": 0}, {"n": 20, "id": "IN6-020", "c": "d", "tema": "Inmunosupresión materna", "pregunta": "Respecto a la inmunosupresión materna y el parto, es FALSO:", "opciones": ["a. Las citoquinas Th1 sostienen la tolerancia y las Th2 disparan el trabajo de parto.", "b. Los estrógenos, elevados hasta 10 veces, suprimen la respuesta inflamatoria.", "c. La progesterona reduce la linfotransformación.", "d. La hCG suprime poblaciones de linfocitos T.", "e. Aumentan notoriamente los linfocitos T CD4+CD25+ (Treg)."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Falso: es al revés; las citoquinas Th1 promueven el rechazo y el parto, las Th2 inhiben a Th1 y sostienen la tolerancia.", "sin_banco": true, "ok": "", "x": "Durante el embarazo manda un <mark>perfil Th2</mark> y hormonal (corticoides, estrógenos ×10, progesterona, hCG) más Treg aumentados. <span class=\"cx\">Al final</span>, las citoquinas <mark>Th1</mark> de los LsT CD4 deciduales promueven el rechazo del embrión, <span class=\"cx\">así que</span> <span class=\"res\">disparan el parto</span>.", "truco": "Th2 = 2 (embarazo de dos); Th1 = 1 (sale el bebé, queda uno).", "veces": 0}, {"n": 21, "id": "IN6-021", "c": "d", "tema": "Inmunidad pasiva", "pregunta": "La IgG materna pasa al feto por transcitosis mediante receptores Fc del trofoblasto; ¿qué subclase predomina en ese paso?", "opciones": ["a. IgG4", "b. IgG2", "c. IgG3", "d. IgA dimérica", "e. IgG1"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. IgG1 (predomina sobre IgG4, IgG3 e IgG2).", "sin_banco": true, "ok": "", "x": "El paso es <mark>activo y selectivo</mark>: el trofoblasto toma la IgG por sus receptores Fc y la entrega a la sangre fetal. No existe para la IgM, <span class=\"cx\">por eso</span> la IgM del cordón es fetal. <span class=\"res\">Predomina la IgG1</span>.", "truco": "Placenta: IgG «uno» pasa primero.", "veces": 0}, {"n": 22, "id": "IN6-022", "c": "d", "tema": "Lactancia", "pregunta": "¿Qué diferencia inmunológica hay entre el calostro y la leche materna madura?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Calostro: 10-100 millones de leucocitos/mL (PMN 40-60 %, macrófagos 35 %) y 5-6 g de IgA en las primeras 24 h. Leche madura: solo 100.000 leucocitos/mL y 1-2 g/día de IgA, pero rica en lactoferrina, lisozima y glucopéptidos.", "sin_banco": true, "ok": "", "x": "El <mark>calostro</mark> es una «transfusión» de células e IgA justo <span class=\"cx\">cuando</span> el intestino del recién nacido está abierto. La leche madura tiene menos células, <span class=\"cx\">en cambio</span> aporta <mark>lactoferrina</mark> (quita hierro a las bacterias) y lisozima. <span class=\"cx\">Por eso</span> los niños al pecho tienen menos eccema (<span class=\"res\">11 % vs 57 %</span>) y menos asma (<span class=\"res\">3 % vs 22 %</span>).", "truco": "Calostro = Células; Leche madura = Lactoferrina.", "veces": 0}, {"n": 23, "id": "IN6-023", "c": "d", "tema": "Correlato clínico", "pregunta": "Mujer de 30 años con tres abortos del primer trimestre; el laboratorio muestra tiempo de coagulación prolongado in vitro y anticuerpos anticardiolipina positivos. ¿Qué anticuerpo es y por qué su nombre es engañoso?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Anticoagulante lúpico (antifosfolipídico contra la cardiolipina): prolonga la coagulación in vitro, pero in vivo causa trombosis vasculares, infartos placentarios y aborto.", "sin_banco": true, "ok": "", "x": "El <mark>anticoagulante lúpico</mark> engaña: en el tubo alarga la coagulación, <span class=\"cx\">en cambio</span> en el cuerpo <span class=\"res\">trombosa</span>. En la placenta eso da infartos y pérdida del embarazo. La activación de NK deciduales y la falta de reguladores del complemento (CD55, CD46, CD59) son las otras causas inmunes del aborto recurrente.", "truco": "Anticoagulante de nombre, trombótico de oficio.", "veces": 0}, {"n": 24, "id": "IN6-024", "c": "d", "tema": "Correlato clínico", "pregunta": "Respecto a la preeclampsia, es correcto:", "opciones": ["a. Aparece antes de la semana 20 y no tiene proteinuria.", "b. Afecta al 5-7 % de los embarazos y combina placentación deficiente, estrés oxidativo, disfunción endotelial y respuesta inflamatoria sistémica.", "c. Se debe solo a anticuerpos contra receptores de LH o FSH.", "d. Es una tolerancia materna excesiva, igual que el coriocarcinoma.", "e. Es rara: menos del 0,1 % de los embarazos."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Afecta al 5-7 % de los embarazos, tras la semana 20, con hipertensión y proteinuria; es multifactorial.", "sin_banco": true, "ok": "", "x": "La preeclampsia nace de una <mark>placentación deficiente</mark>: si las arterias espirales no se remodelan bien, hay hipoxia y estrés oxidativo, <span class=\"cx\">así que</span> el endotelio materno se daña. Comparte con el aborto recurrente la <mark>activación descontrolada del complemento</mark> sobre la placenta. Causa el <span class=\"res\">15-20 % de las muertes maternas</span> en países en desarrollo.", "truco": "Pre-eclampsia: «Placenta Pobre → Presión y Proteinuria».", "veces": 0}], "tabla": {"cab": ["", "Intestino", "Hígado", "Testículo", "Ojo", "Placenta"], "filas": [["Barrera", "epitelio, moco, uniones estrechas", "LSEC fenestradas", "BTB de Sertoli", "BRB y BAqB; sin linfáticos", "trofoblasto"], ["Célula clave", "célula M, IgA, γδ", "LSEC, Kupffer", "Sertoli", "córnea (CD95L)", "dNKs (80 %)"], ["Cómo tolera", "Treg por polisacárido A", "IL-10; CD8 sin IFN-γ", "citoquinas que fabrican esperma", "humor acuoso: Treg, apoptosis", "HLA-G, IDO, FasL"], ["Si falla", "disbiosis, <i>C. difficile</i>", "hepatitis B/C → cáncer", "antiespermatozoide", "uveítis", "aborto, preeclampsia"], ["🔑 Para diferenciar", "tolera la flora", "acepta el injerto", "antígenos tardíos", "injerto de córnea", "tolera lo paterno"]]}, "fuente": "Fuente: tu teoría — Clase 12a Inmunidad de mucosas, Clase 12b Aparato reproductor y eje neuroinmunoendocrino, Clase 13 Inmunología de la reproducción (Rojas, 17.ª ed., caps. 12 y 13)."}, {"n": 12, "slug": "Citoquinas_y_tolerancia", "titulo": "Citoquinas, tolerancia y regulación", "subtitulo": "los mensajeros del sistema inmune y los frenos que evitan atacar lo propio", "grupo": "g7", "lema": "La idea: las células inmunes <b>hablan con citoquinas</b>, moléculas de unos 30 kDa que actúan sobre la misma célula, la vecina o todo el cuerpo. Pero hablar no basta: hay que <u>saber cuándo callar</u>. Por eso el timo elimina los clones que reconocen lo propio (gen <mark>AIRE</mark>), los Treg (<mark>FOXP3</mark>) frenan a los efectores y la IL-10 apaga la inflamación. Importa porque, si falla un mensajero, aparece una inmunodeficiencia (SCID por la cadena γ); en cambio, si falla un freno, aparece la <b>autoinmunidad</b> (APECED). En la imagen verás tres escenas: un macrófago que secreta citoquinas, la selección negativa en el timo y un Treg que calma a un efector.", "img": "img/12.webp", "mini": "img/mini/12.webp", "ratio": 1.5, "etiquetas": [{"n": "①④", "t": "Citoquinas", "s": "~30 kDa:<br>el mensaje", "c": "i", "x": 0.8, "y": 6, "ax": 13, "ay": 43, "d": "A", "al": "l"}, {"n": "②", "t": "Autocrina", "s": "a su propio<br>receptor", "c": "i", "x": 22, "y": 6, "ax": 13.2, "ay": 24}, {"n": "③⑦", "t": "Paracrina", "s": "al linfocito<br>vecino", "c": "i", "x": 38.5, "y": 6, "ax": 28.5, "ay": 33}, {"n": "⑨⑪", "t": "Epitelio tímico", "s": "AIRE muestra<br>lo propio", "c": "d", "x": 56, "y": 6, "ax": 45, "ay": 30}, {"n": "⑩⑭", "t": "Treg (FOXP3)", "s": "frena al<br>efector", "c": "g", "x": 73, "y": 6, "ax": 76, "ay": 38}, {"n": "⑤⑰", "t": "Señal inhibidora", "s": "IL-10: apaga<br>la inflamación", "c": "g", "x": 99.2, "y": 6, "ax": 85.5, "ay": 40, "d": "B", "al": "r"}, {"n": "⑥⑧", "t": "Endocrina", "s": "a la sangre: fiebre,<br>fase aguda, caquexia", "c": "i", "x": 0.8, "y": 90, "ax": 15, "ay": 68, "d": "D", "al": "l"}, {"n": "⑨⑪", "t": "Antígeno propio", "s": "de otros órganos<br>en la membrana", "c": "d", "x": 36, "y": 90, "ax": 45, "ay": 58}, {"n": "⑨⑫⑬", "t": "Clon autorreactivo", "s": "se une fuerte y muere:<br>cuerpos apoptóticos", "c": "d", "x": 60, "y": 90, "ax": 63, "ay": 63, "d": "C"}, {"n": "⑮⑯", "t": "Efector apagado", "s": "la respuesta termina;<br>queda la memoria", "c": "g", "x": 99.2, "y": 90, "ax": 90, "ay": 56, "al": "r"}], "diapos": [{"img": "img/12.webp", "ratio": 1.5, "titulo": "Citoquinas, selección negativa y Treg", "texto": "Las citoquinas actúan autocrina, paracrina o endocrinamente ②③⑥; <mark>AIRE</mark> enseña lo propio en el timo ⑨⑪ y el <b>Treg</b> frena al efector ⑩⑭.", "etiquetas": [{"n": "①④", "t": "Citoquinas", "s": "~30 kDa:<br>el mensaje", "c": "i", "x": 0.8, "y": 6, "ax": 13, "ay": 43, "d": "A", "al": "l"}, {"n": "②", "t": "Autocrina", "s": "a su propio<br>receptor", "c": "i", "x": 22, "y": 6, "ax": 13.2, "ay": 24}, {"n": "③⑦", "t": "Paracrina", "s": "al linfocito<br>vecino", "c": "i", "x": 38.5, "y": 6, "ax": 28.5, "ay": 33}, {"n": "⑨⑪", "t": "Epitelio tímico", "s": "AIRE muestra<br>lo propio", "c": "d", "x": 56, "y": 6, "ax": 45, "ay": 30}, {"n": "⑩⑭", "t": "Treg (FOXP3)", "s": "frena al<br>efector", "c": "g", "x": 73, "y": 6, "ax": 76, "ay": 38}, {"n": "⑤⑰", "t": "Señal inhibidora", "s": "IL-10: apaga<br>la inflamación", "c": "g", "x": 99.2, "y": 6, "ax": 85.5, "ay": 40, "d": "B", "al": "r"}, {"n": "⑥⑧", "t": "Endocrina", "s": "a la sangre: fiebre,<br>fase aguda, caquexia", "c": "i", "x": 0.8, "y": 90, "ax": 15, "ay": 68, "d": "D", "al": "l"}, {"n": "⑨⑪", "t": "Antígeno propio", "s": "de otros órganos<br>en la membrana", "c": "d", "x": 36, "y": 90, "ax": 45, "ay": 58}, {"n": "⑨⑫⑬", "t": "Clon autorreactivo", "s": "se une fuerte y muere:<br>cuerpos apoptóticos", "c": "d", "x": 60, "y": 90, "ax": 63, "ay": 63, "d": "C"}, {"n": "⑮⑯", "t": "Efector apagado", "s": "la respuesta termina;<br>queda la memoria", "c": "g", "x": 99.2, "y": 90, "ax": 90, "ay": 56, "al": "r"}]}, {"img": "img/12_2.webp", "ratio": 1.5, "titulo": "Receptores: cadena γ común y JAK/STAT", "texto": "IL-2, IL-4, IL-7, IL-9 e IL-15 comparten la <mark>cadena γ común</mark>: si falla, SCID ③. La señal viaja por <b>JAK/STAT</b> y las SOCS la frenan ②.", "etiquetas": [{"n": "③", "t": "Cadena específica", "s": "distinta para<br>cada citoquina", "c": "i", "x": 0.5, "y": 8, "ax": 6.5, "ay": 28, "al": "l"}, {"n": "③", "t": "IL-2, 4, 7, 9 y 15", "s": "cada una en<br>su receptor", "c": "g", "x": 26, "y": 8, "ax": 23, "ay": 19}, {"n": "③", "t": "Cadena γ común", "s": "compartida:<br>si falla, SCID", "c": "d", "x": 46, "y": 8, "ax": 55, "ay": 30}, {"n": "", "t": "Citoquina", "s": "se une a<br>dos cadenas", "c": "g", "x": 68, "y": 8, "ax": 79, "ay": 18}, {"n": "②", "t": "SOCS", "s": "frena a JAK<br>si es excesiva", "c": "d", "x": 99.5, "y": 8, "ax": 87.9, "ay": 48, "al": "r"}, {"n": "", "t": "Membrana", "s": "del linfocito", "c": "g", "x": 0.5, "y": 92, "ax": 20, "ay": 40, "al": "l"}, {"n": "②", "t": "JAK", "s": "cinasa:<br>fosforila a STAT", "c": "i", "x": 44, "y": 92, "ax": 74.9, "ay": 50}, {"n": "②", "t": "STAT", "s": "se une en<br>dímero", "c": "i", "x": 62, "y": 92, "ax": 76.8, "ay": 60.5}, {"n": "②", "t": "STAT en el núcleo", "s": "enciende<br>genes", "c": "i", "x": 99.5, "y": 92, "ax": 80, "ay": 78, "al": "r"}]}, {"img": "img/12_3.webp", "ratio": 1.5, "titulo": "Interferones tipo I y tipo II", "texto": "El <mark>IFN tipo I</mark> de la célula infectada protege a las vecinas; el <b>IFN-γ</b> de LsT CD4 y NK activa al macrófago ⑦.", "etiquetas": [{"n": "⑦", "t": "Célula infectada", "s": "fabrica IFN<br>tipo I", "c": "d", "x": 0.5, "y": 8, "ax": 7.2, "ay": 38, "al": "l"}, {"n": "⑦", "t": "IFN tipo I", "s": "α y β: avisa<br>a las vecinas", "c": "i", "x": 24, "y": 8, "ax": 22.8, "ay": 44}, {"n": "⑦", "t": "Virus", "s": "rebota: no<br>puede entrar", "c": "g", "x": 43, "y": 8, "ax": 42.3, "ay": 23.4}, {"n": "⑦", "t": "LsT CD4", "s": "fabrica<br>IFN-γ", "c": "i", "x": 61, "y": 8, "ax": 58, "ay": 30}, {"n": "⑦", "t": "Macrófago activado", "s": "IFN-γ: su principal<br>activador", "c": "d", "x": 99.5, "y": 8, "ax": 87.2, "ay": 30, "al": "r"}, {"n": "⑦", "t": "Células vecinas", "s": "estado<br>antiviral", "c": "i", "x": 20, "y": 91, "ax": 33.2, "ay": 62}, {"n": "⑦", "t": "NK", "s": "también<br>fabrica IFN-γ", "c": "i", "x": 46, "y": 91, "ax": 57.3, "ay": 62}, {"n": "⑦", "t": "IFN-γ", "s": "tipo II", "c": "d", "x": 66, "y": 91, "ax": 69, "ay": 50}, {"n": "", "t": "Bacterias", "s": "destruidas en<br>el fagosoma", "c": "g", "x": 99.5, "y": 91, "ax": 90.5, "ay": 58, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = citoquinas</b> (los mensajeros), <b class=\"d\">rojo = tolerancia central</b> (el timo), gris = <b>regulación periférica</b> (Treg, Bregs y memoria).", "<b>Escena 1:</b> el macrófago secreta citoquinas que vuelven a él (<mark>autocrina</mark>), llegan al linfocito vecino (<mark>paracrina</mark>) o pasan a la sangre (<mark>endocrina</mark>). Una misma citoquina hace cosas distintas en células distintas (<b>pleiotropía</b>), y varias pueden hacer lo mismo (<b>redundancia</b>).", "<b>Escena 2:</b> la célula epitelial medular del timo, gracias a <mark>AIRE</mark>, muestra antígenos de otros órganos; el linfocito que se une demasiado fuerte <span class=\"res\">muere por apoptosis</span> (selección negativa).", "<b>Escena 3:</b> el linfocito T regulador (<mark>FOXP3</mark>) apaga al efector; la IL-10 y la IL-4 frenan a los Th1, y la red idiotipo-anti-idiotipo frena a los anticuerpos."], "recordar": "Citoquina = <b>mensaje</b>; AIRE = el timo <b>enseña</b> lo propio; FOXP3 = <b>fabrica</b> Treg; IL-10 = <b>apaga</b>; CTLA-4 y BAFF = <b>blancos</b> de fármacos (ipilimumab y belimumab)."}, "numeros": [{"l": "A", "html": "<b>Tamaño de una citoquina</b>: del orden de <b class=\"n\">30 kDa</b>; su potencia es extrema: <b class=\"n\">10⁻¹² g</b> de interferón protegen in vitro a un millón de células.", "rango": null}, {"l": "B", "html": "<b>IL-10</b>: controla la expresión de <b class=\"n\">300 genes</b>; por eso es el freno antiinflamatorio central.", "rango": null}, {"l": "C", "html": "<b>Autorreactividad</b>: del <b class=\"a\">20 % al 50 %</b> de los TCR y BCR reconocen algo propio, pero solo el <b class=\"n\">3–8 %</b> de las personas hace enfermedad autoinmune gracias a la tolerancia.", "rango": {"min": 0, "max": 60, "unidad": "%", "zonas": [[3, 8, "m", "personas con enfermedad autoinmune"], [20, 50, "a", "TCR/BCR autorreactivos"]], "marcas": [3, 8, 20, 50]}}, {"l": "D", "html": "<b>TNF</b>: más de <b class=\"n\">19</b> miembros en su familia y <b class=\"n\">29</b> receptores; TNF-R1 mata, TNF-R2 hace proliferar linfocitos T.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del mensaje al freno", "subtitulo": "estímulo → citoquinas → señal → efecto → freno (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> un microbio o un daño activa al macrófago; los lipopolisacáridos son el inductor más potente del TNF. La célula dañada libera alarminas como la <mark>IL-33</mark>.", "pr": "secreción de IL-1, IL-6, TNF e IL-12.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑧ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Citoquina y receptor", "m": "<b>Por qué:</b> la citoquina se une a un receptor específico (autocrino, paracrino o endocrino) y dispara una cascada de fosforilaciones <mark>JAK/STAT</mark>; varias IL comparten la <b>cadena γ común</b>.", "pr": "cambios del citoesqueleto, nuevas citoquinas o apoptosis; las SOCS frenan el exceso.", "pr_tit": "Produce:", "rf": "Preguntas ①②③", "color": "p2"}, {"t": "3. Efecto", "m": "<b>Qué produce:</b> IL-1, IL-6 y TNF dan fiebre y proteínas de fase aguda; la IL-5 hace eosinófilos; la IL-4 con la IL-13, IgE; el IFN-γ activa macrófagos; los IFN tipo I protegen a las células vecinas de los virus.", "pr": "defensa: inflamación, anticuerpos o estado antiviral.", "pr_tit": "Produce:", "rf": "Preguntas ④⑦⑧", "color": "p3"}, {"t": "4. Tolerancia", "m": "<b>Por qué no atacamos lo propio:</b> en el timo, <mark>AIRE</mark> muestra antígenos de otros órganos y se eliminan los clones autorreactivos; el linfocito B autorreactivo no sale de la médula (sin CD62L ni receptor de BAFF).", "pr": "solo el 3–8 % hace autoinmunidad <span class=\"lt2\">C</span>.", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑩⑪⑫⑬", "color": "p4"}, {"t": "5. Freno y memoria", "m": "<b>Qué apaga la respuesta:</b> Treg (FOXP3), Bregs e <mark>IL-10</mark> <span class=\"lt2\">B</span>, CTLA-4, la red idiotipo-anti-idiotipo y las MDSC. Quedan linfocitos de memoria en alerta.", "pr": "la respuesta se apaga y el segundo contacto es más rápido.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑭⑮⑯⑰", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Mensajero roto:</b> cadena γ → SCID. <b>Freno roto:</b> AIRE → APECED; FOXP3 → autoinmunidad grave; exceso de BAFF → autoinmunidad B. <b>Exceso de mensaje:</b> TNF → tormenta de citoquinas y caquexia.", "pr": "inmunodeficiencia, autoinmunidad o choque.", "pr_tit": "Produce:", "rf": "Preguntas ③⑪", "color": "d"}], "extra": [{"html": "💊 <b>Fármacos que salen de esta lámina:</b> <mark>anakinra</mark> (antagonista del receptor de IL-1: sepsis, artritis reumatoide, psoriasis), <b>anti-TNF</b> (artritis reumatoide), <b>bloqueo de IL-6</b> (autoinmunes), <mark>belimumab</mark> (anti-BAFF: lupus) e <mark>ipilimumab</mark> (anti-CTLA-4: melanoma; puede soltar la autoinmunidad).", "k": ""}, {"html": "⏰ <b>Ritmo circadiano:</b> el <b class=\"n\">10 %</b> del genoma sigue el reloj del núcleo supraquiasmático; <span class=\"cx\">por eso</span> en la artritis reumatoide el dolor y la rigidez son peores <b>al amanecer</b>, <span class=\"cx\">cuando</span> suben IL-6 y TNF.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De la citoquina útil a la tormenta", "pasos": ["Infección local: IL-1, IL-6 y TNF en el sitio", "fiebre y proteínas de fase aguda (redundancia)", "TNF sistémico: lipólisis y <b>caquexia</b>", "<b>sepsis grave</b> o malaria cerebral: tormenta de citoquinas", "choque y <b>disfunción multiorgánica</b>"]}], "html": "", "fuente": "Fuente: tu teoría — clase 14 (propiedades, familias, interleuquinas, TNF, interferones, TGF-β) y clase 15 (AIRE, FOXP3, tolerancia del linfocito B, otros tipos de tolerancia, regulación innata y adquirida, memoria, ritmo circadiano)."}, "preguntas": [{"n": 1, "id": "IN7-001", "c": "i", "tema": "Propiedades de las citoquinas", "pregunta": "La propiedad por la cual IL-1, IL-6 y TNF inducen por igual la síntesis de proteínas de fase aguda en el hígado se denomina:", "opciones": ["a. Pleiotropía.", "b. Sinergismo.", "c. Antagonismo.", "d. Redundancia.", "e. Acción autocrina."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Redundancia: citoquinas distintas producen el mismo efecto.", "sin_banco": true, "ok": "", "x": "Son <mark>tres citoquinas distintas</mark> que llegan a un mismo efecto, <span class=\"cx\">así que</span> es redundancia. <span class=\"cx\">En cambio</span>, la pleiotropía es al revés: una sola citoquina con efectos distintos en células distintas. <span class=\"cx\">Por eso</span> <span class=\"res\">bloquear una sola citoquina redundante no siempre apaga el efecto</span>.", "truco": "Redundancia = Repetido por varias; Pleiotropía = Polifacética una sola.", "veces": 0}, {"n": 2, "id": "IN7-002", "c": "i", "tema": "Propiedades de las citoquinas", "pregunta": "Respecto a la forma de actuar de las citoquinas, es FALSO:", "opciones": ["a. La pleiotropía es que una citoquina produzca efectos distintos en células distintas.", "b. IL-4 e IL-13 potencian juntas el cambio de isotipo hacia IgE (sinergismo).", "c. La IL-4 inhibe la síntesis de IFN-γ y viceversa (antagonismo).", "d. Las SOCS amplifican la señalización JAK/STAT cuando esta es excesiva.", "e. Pueden actuar de forma autocrina, paracrina o endocrina mediante receptores específicos."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Las SOCS no amplifican: frenan la señalización JAK/STAT cuando es excesiva.", "sin_banco": true, "ok": "", "x": "La señal viaja por <mark>JAK/STAT</mark> (paso 2 de la cadena). Las SOCS son <b>supresoras</b>: la apagan <span class=\"cx\">cuando</span> sobra; <span class=\"cx\">por eso</span> <span class=\"res\">la d es la falsa</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN7-003", "c": "i", "tema": "Familias y receptores", "pregunta": "¿Qué cadena comparten los receptores de IL-2, IL-4, IL-7, IL-9 e IL-15, y qué produce su falla congénita?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La cadena γ común del receptor; su defecto congénito (o el de la producción de IL-2) causa una variedad de inmunodeficiencia combinada severa (SCID).", "sin_banco": true, "ok": "", "x": "Varias interleuquinas usan la <mark>misma cadena γ</mark> para señalizar, <span class=\"cx\">así que</span> si esa pieza falla se pierden todas a la vez. <span class=\"cx\">Por eso</span> el linfocito no recibe señales de crecimiento y aparece una <span class=\"res\">inmunodeficiencia combinada severa (SCID)</span>.", "truco": "Una sola llave (γ) para cinco puertas: si se rompe, se cierran todas.", "veces": 0}, {"n": 4, "id": "IN7-004", "c": "i", "tema": "Interleuquinas Th2", "pregunta": "El principal factor de crecimiento y diferenciación de los eosinófilos es:", "opciones": ["a. IL-4.", "b. IL-5.", "c. IL-13.", "d. IL-9.", "e. IL-10."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. IL-5.", "sin_banco": true, "ok": "", "x": "Las cuatro primeras son del grupo Th2, pero cada una tiene su papel: la IL-4 impulsa la <mark>IgE</mark>, la IL-13 coestimula el cambio de isotipo y la fibrosis, y la IL-9 sinergiza con IL-4. <span class=\"cx\">En cambio</span>, el eosinófilo depende de la <span class=\"res\">IL-5</span>.", "truco": "IL-5 = «cinco» dedos que señalan al Eosinófilo.", "veces": 0}, {"n": 5, "id": "IN7-005", "c": "i", "tema": "Interleuquinas reguladoras", "pregunta": "Sobre la IL-10, es correcto:", "opciones": ["a. Inhibe las citoquinas proinflamatorias y el virus de Epstein-Barr produce una proteína homóloga (BCRF1).", "b. Es el principal activador de los macrófagos.", "c. Expande y sostiene a los linfocitos Th17.", "d. Es la principal linfopoyetina del estroma medular y tímico.", "e. Es una alarmina liberada tras daño celular."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Es el principal inhibidor de citoquinas proinflamatorias (controla 300 genes); Leishmania y el VEB (BCRF1) la explotan.", "sin_banco": true, "ok": "", "x": "Es el freno del paso 5 (punto Ⓑ): controla <span class=\"res\">300 genes</span>. <span class=\"cx\">Por eso</span> <b>Leishmania</b> y el VEB (BCRF1) la imitan para apagar la inmunidad celular.", "truco": "", "veces": 0}, {"n": 6, "id": "IN7-006", "c": "i", "tema": "TNF y superfamilia", "pregunta": "La unión del TNF a su receptor TNF-R2 produce:", "opciones": ["a. Apoptosis de algunas células.", "b. Lisis de células tumorales.", "c. Necrosis hemorrágica en tumores.", "d. Lipólisis y caquexia.", "e. Proliferación de linfocitos T."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Proliferación de linfocitos T.", "sin_banco": true, "ok": "", "x": "El TNF tiene dos receptores con efectos opuestos: el <mark>TNF-R1</mark> da apoptosis, lisis tumoral y necrosis hemorrágica, <span class=\"cx\">en cambio</span> el <mark>TNF-R2</mark> hace <span class=\"res\">proliferar a los linfocitos T</span>. <span class=\"cx\">Por eso</span> la terapia anti-TNF exige precisión: bloquear uno sin el otro.", "truco": "R1 = «uno» que mata; R2 = «dos» que multiplica.", "veces": 0}, {"n": 7, "id": "IN7-007", "c": "i", "tema": "Interferones", "pregunta": "¿Cómo se diferencian los interferones tipo I del interferón tipo II (IFN-γ)?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Los tipo I (α, β…) los produce casi cualquier célula infectada por virus e inducen estado antiviral en las vecinas; el IFN-γ (LsT CD4 y NK) es el principal activador de macrófagos y dirige la diferenciación Th1.", "sin_banco": true, "ok": "", "x": "El tipo I es una <mark>alarma antiviral</mark>: la célula infectada avisa a sus vecinas para que fabriquen proteínas antivirales. <span class=\"cx\">En cambio</span>, el IFN-γ no es antiviral directo sino el <span class=\"res\">activador de macrófagos</span> que induce Th1 e inhibe Th2 y Th17. El tipo III (IL-28, IL-29) actúa en epitelios.", "truco": "Tipo I = Infección viral; tipo II (γ) = Gran activador del macrófago.", "veces": 0}, {"n": 8, "id": "IN7-008", "c": "i", "tema": "Interleuquinas: IL-6", "pregunta": "Mujer de 56 años, posmenopáusica, con osteoporosis. ¿Qué citoquina, normalmente antagonizada por el 17-β-estradiol, explica la osteoclastogénesis?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La IL-6: al caer los estrógenos pierde su antagonista y estimula la osteoclastogénesis, que lleva a osteoporosis.", "sin_banco": true, "ok": "", "x": "El <mark>17-β-estradiol</mark> frena normalmente a la IL-6. Tras la menopausia ese freno desaparece, <span class=\"cx\">así que</span> la IL-6 activa a los osteoclastos y el hueso se reabsorbe. <span class=\"cx\">Por eso</span> <span class=\"res\">IL-6 libre = osteoporosis posmenopáusica</span>.", "truco": "Sin estrógeno, la IL-6 «se come» el hueso.", "veces": 0}, {"n": 9, "id": "IN7-009", "c": "d", "tema": "Tolerancia central", "pregunta": "El gen que controla la expresión de antígenos órgano-específicos en las células epiteliales de la médula tímica es:", "opciones": ["a. FOXP3.", "b. CHRNA.", "c. AIRE.", "d. IRF5.", "e. IL2RA."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. AIRE (autoimmune regulator gene).", "sin_banco": true, "ok": "", "x": "Es la escena central: la célula epitelial medular <b>enseña</b> antígenos de otros órganos gracias a <mark>AIRE</mark>, y el linfocito que se une fuerte <span class=\"res\">muere</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN7-010", "c": "g", "tema": "Tolerancia central", "pregunta": "¿Qué factor de transcripción es necesario y suficiente para que el timo genere linfocitos T reguladores, y qué produce su mutación?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "FOXP3; sus mutaciones causan síndromes autoinmunes graves por falta de Treg.", "sin_banco": true, "ok": "", "x": "El <mark>FOXP3</mark> es el interruptor que convierte un linfocito T en regulador. Si muta, no hay Treg que frenen la respuesta, <span class=\"cx\">así que</span> aparecen <span class=\"res\">síndromes autoinmunes graves</span>.", "truco": "FOXP3 = el «zorro» (fox) guardián de los Treg.", "veces": 0}, {"n": 11, "id": "IN7-011", "c": "d", "tema": "Tolerancia central", "pregunta": "Niño con candidiasis mucocutánea crónica, tiroiditis, diabetes y vitíligo. ¿Qué síndrome sospecha y qué gen falla?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome APECED (poliendocrinopatía autoinmune con candidiasis y distrofia ectodérmica) por deficiencia del gen AIRE.", "sin_banco": true, "ok": "", "x": "Sin <mark>AIRE</mark> el timo no elimina los clones contra glándulas, <span class=\"cx\">por eso</span> aparecen tiroiditis, diabetes, vitíligo e insuficiencia gonadal. La candidiasis se explica <span class=\"cx\">porque</span> se forman <span class=\"res\">autoanticuerpos contra IL-17</span>, la citoquina que defiende las mucosas.", "truco": "APECED = Poliendocrino + Candida + Ectodermo.", "veces": 0}, {"n": 12, "id": "IN7-012", "c": "d", "tema": "Tolerancia central del linfocito B", "pregunta": "Un linfocito B inmaduro autorreactivo no abandona la médula ósea porque:", "opciones": ["a. No expresa CD62L ni el receptor para BAFF.", "b. Expresa FOXP3.", "c. Pierde la expresión de CD19.", "d. Produce IL-10 en exceso.", "e. Recibe señales de AIRE en la médula."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Al interiorizar su BCR no expresa CD62L (homing) ni el receptor de BAFF (supervivencia).", "sin_banco": true, "ok": "", "x": "Si su BCR se une con fuerza a lo propio, el linfocito B lo <mark>interioriza</mark> y detiene su maduración. Sin CD62L no puede salir y sin receptor de BAFF no sobrevive, <span class=\"cx\">así que</span>, si no logra editar su BCR, <span class=\"res\">muere por apoptosis</span>.", "truco": "Sin pasaporte (CD62L) y sin comida (BAFF): no sale.", "veces": 0}, {"n": 13, "id": "IN7-013", "c": "d", "tema": "Otros tipos de tolerancia", "pregunta": "La profilaxis anti-Rh(D) se basa en un tipo de tolerancia:", "opciones": ["a. Intrauterina.", "b. Por dosis bajas.", "c. Oral.", "d. Por dosis altas.", "e. Posnatal inducida."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Posnatal inducida: antígeno junto con un anticuerpo específico; es transitoria.", "sin_banco": true, "ok": "", "x": "Al dar el <mark>anticuerpo específico</mark> junto con el antígeno, la madre no monta respuesta contra el Rh fetal. Es inducida después del nacimiento y transitoria. <span class=\"cx\">En cambio</span>, la intrauterina es <span class=\"res\">contra lo propio y casi siempre permanente</span>.", "truco": "Anti-D = tolerancia «a pedido» y pasajera.", "veces": 0}, {"n": 14, "id": "IN7-014", "c": "g", "tema": "Aplicaciones farmacológicas", "pregunta": "El ipilimumab, útil en el melanoma, bloquea:", "opciones": ["a. BAFF.", "b. CTLA-4.", "c. TNF.", "d. IL-6.", "e. CD40L."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. CTLA-4, molécula coestimuladora inhibitoria.", "sin_banco": true, "ok": "", "x": "CTLA-4 es un <mark>freno</mark> del linfocito T; al bloquearlo, el linfocito ataca al tumor. <span class=\"cx\">Por eso</span> también puede soltar la autoinmunidad como efecto adverso. <span class=\"cx\">En cambio</span>, el belimumab bloquea <span class=\"res\">BAFF</span> y se usa en lupus.", "truco": "IpiliMUMAB suelta el freno (CTLA-4); BeliMUMAB quita la comida del B (BAFF).", "veces": 0}, {"n": 15, "id": "IN7-015", "c": "g", "tema": "Regulación de la inmunidad adquirida", "pregunta": "Explique la red idiotipo-anti-idiotipo de Jerne.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El anticuerpo Ac-1 tiene en su región variable (idiotipo) una secuencia que el sistema reconoce como antígeno; se produce un anti-idiotipo (Ac-2) contra Ac-1, que frena progresivamente la producción del primero.", "sin_banco": true, "ok": "", "x": "El <mark>idiotipo</mark> es la «cara» única del anticuerpo y el sistema la trata como algo nuevo. <span class=\"cx\">Así que</span> fabrica un anticuerpo contra el anticuerpo (Ac-2), y ese segundo <span class=\"res\">frena al <span class=\"cx\">primero</span></span>: es una regulación en cadena.", "truco": "Ac-2 es el «anticuerpo del anticuerpo»: espejo que apaga.", "veces": 0}, {"n": 16, "id": "IN7-016", "c": "g", "tema": "Memoria inmunológica", "pregunta": "Sobre la memoria inmunológica, es FALSO:", "opciones": ["a. La memoria innata es estática e igual en todos los individuos.", "b. La memoria adquirida es dinámica, expandible y personalizada.", "c. Los linfocitos de memoria producen anticuerpos de manera continua.", "d. Algunos linfocitos de memoria migran al sitio de ingreso del antígeno original.", "e. Ante un segundo contacto, la respuesta es más rápida."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. No producen anticuerpos de forma continua: conservan el «programa» para activarse rápido.", "sin_banco": true, "ok": "", "x": "Los linfocitos de memoria están <mark>en alerta permanente</mark>, pero no gastan energía produciendo anticuerpos todo el tiempo. Su valor es guardar el programa; <span class=\"cx\">por eso</span>, si el antígeno reingresa, <span class=\"res\">la respuesta es rápida y eficaz</span>.", "truco": "Memoria = programa guardado, no fábrica encendida.", "veces": 0}, {"n": 17, "id": "IN7-017", "c": "g", "tema": "Regulación de la inmunidad adquirida", "pregunta": "¿Qué son los linfocitos B reguladores (Bregs), qué fenotipo tienen y cómo actúan?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Subpoblación CD19+ CD24+ CD38low que produce IL-10 y frena el desarrollo de linfocitos Th1; su activación depende de la unión CD40-CD154.", "sin_banco": true, "ok": "", "x": "No todos los linfocitos B fabrican anticuerpos: los Bregs regulan. Producen <mark>IL-10</mark>, el freno antiinflamatorio, <span class=\"cx\">así que</span> frenan a los Th1 y mantienen la tolerancia. Necesitan la señal <span class=\"res\">CD40-CD154</span> para activarse.", "truco": "Breg = B que «riega» IL-10 para calmar.", "veces": 0}], "tabla": {"cab": ["", "Productor", "Efecto clave", "Si falla o sobra"], "filas": [["IL-1", "Fagocitos", "Fiebre y fase aguda, porque es pirógeno endógeno", "Exceso: sepsis; se frena con anakinra"], ["IL-6", "Varias células", "Principal inductora hepática de fase aguda", "Sin estrógeno: osteoporosis"], ["TNF", "Macrófagos (LPS)", "R1 mata, R2 hace proliferar LsT", "Exceso: caquexia, choque séptico"], ["IL-10", "Bregs y otras", "Apaga citoquinas proinflamatorias (300 genes)", "Imitada por VEB y Leishmania"], ["IFN-γ", "LsT CD4 y NK", "Activa macrófagos; induce Th1", "Inhibido por vitamina D3 y ciclosporina"], ["🔑 Para diferenciar", "Pleiotropía = una → muchos efectos", "Redundancia = muchas → un efecto", "Cadena γ rota = SCID"]]}, "fuente": "Fuente: tu teoría — clases 14 (Citoquinas) y 15 (Tolerancia, regulación y memoria inmunológica), Rojas 17.ª ed."}, {"n": 13, "slug": "Muerte_celular", "titulo": "Por qué, cuándo y cómo mueren las células", "subtitulo": "necrosis, apoptosis y netosis (con necroptosis, autofagia y piroptosis)", "grupo": "g7", "lema": "La idea: no importa solo <b>que</b> la célula muera, sino <b>cómo</b>. Si la membrana estalla (<mark>necrosis</mark>), las enzimas salen y <u>siempre hay inflamación</u>; si la célula se desarma por dentro (<mark>apoptosis</mark>), los restos se empaquetan y un macrófago los come en silencio. Importa porque una apoptosis que falla deja vivir clones autorreactivos o tumorales, y una que sobra explica la inmunosenescencia. En la imagen verás tres muertes: una célula que revienta, una que se fragmenta en cuerpos apoptóticos y un neutrófilo que muere tejiendo una red que atrapa bacterias.", "img": "img/13.webp", "mini": "img/mini/13.webp", "ratio": 1.5, "etiquetas": [{"n": "①⑨", "t": "Necrosis", "s": "la membrana<br>estalla", "c": "d", "x": 0.8, "y": 6, "ax": 13, "ay": 30, "al": "l"}, {"n": "①", "t": "Enzimas liberadas", "s": "dañan a las<br>vecinas", "c": "d", "x": 25.5, "y": 6, "ax": 26, "ay": 37}, {"n": "②④", "t": "Célula apoptótica", "s": "cromatina densa,<br>ADN cortado", "c": "i", "x": 45.5, "y": 6, "ax": 37, "ay": 44, "d": "A"}, {"n": "⑤", "t": "Macrófago", "s": "fagocitosis<br>silenciosa", "c": "i", "x": 64, "y": 6, "ax": 61, "ay": 37}, {"n": "⑦", "t": "Red NET", "s": "filamentos de ADN con<br>~20 microbicidas", "c": "g", "x": 99.2, "y": 6, "ax": 86, "ay": 30, "d": "C", "al": "r"}, {"n": "①", "t": "Neutrófilos atraídos", "s": "siempre hay<br>inflamación", "c": "d", "x": 0.8, "y": 90, "ax": 10, "ay": 63, "al": "l"}, {"n": "③⑥", "t": "Cuerpos apoptóticos", "s": "la célula se empaqueta;<br>no derrama nada", "c": "i", "x": 31, "y": 90, "ax": 42, "ay": 58, "d": "B"}, {"n": "⑤", "t": "Fosfatidilserina", "s": "afuera: señal<br>«cómeme»", "c": "i", "x": 52, "y": 90, "ax": 51, "ay": 41}, {"n": "⑦", "t": "Neutrófilo muerto", "s": "netosis: núcleo<br>fragmentado", "c": "g", "x": 70, "y": 90, "ax": 71, "ay": 52}, {"n": "⑦", "t": "Bacterias atrapadas", "s": "destruidas por<br>la red", "c": "g", "x": 99.2, "y": 90, "ax": 85, "ay": 46, "al": "r"}], "diapos": [{"img": "img/13.webp", "ratio": 1.5, "titulo": "Tres maneras de morir", "texto": "La <mark>necrosis</mark> estalla y <span class=\"res\">siempre inflama</span> ①; la <mark>apoptosis</mark> se empaqueta y el macrófago la come en silencio ⑤; la <b>netosis</b> lanza una red que atrapa bacterias ⑦.", "etiquetas": [{"n": "①⑨", "t": "Necrosis", "s": "la membrana<br>estalla", "c": "d", "x": 0.8, "y": 6, "ax": 13, "ay": 30, "al": "l"}, {"n": "①", "t": "Enzimas liberadas", "s": "dañan a las<br>vecinas", "c": "d", "x": 25.5, "y": 6, "ax": 26, "ay": 37}, {"n": "②④", "t": "Célula apoptótica", "s": "cromatina densa,<br>ADN cortado", "c": "i", "x": 45.5, "y": 6, "ax": 37, "ay": 44, "d": "A"}, {"n": "⑤", "t": "Macrófago", "s": "fagocitosis<br>silenciosa", "c": "i", "x": 64, "y": 6, "ax": 61, "ay": 37}, {"n": "⑦", "t": "Red NET", "s": "filamentos de ADN con<br>~20 microbicidas", "c": "g", "x": 99.2, "y": 6, "ax": 86, "ay": 30, "d": "C", "al": "r"}, {"n": "①", "t": "Neutrófilos atraídos", "s": "siempre hay<br>inflamación", "c": "d", "x": 0.8, "y": 90, "ax": 10, "ay": 63, "al": "l"}, {"n": "③⑥", "t": "Cuerpos apoptóticos", "s": "la célula se empaqueta;<br>no derrama nada", "c": "i", "x": 31, "y": 90, "ax": 42, "ay": 58, "d": "B"}, {"n": "⑤", "t": "Fosfatidilserina", "s": "afuera: señal<br>«cómeme»", "c": "i", "x": 52, "y": 90, "ax": 51, "ay": 41}, {"n": "⑦", "t": "Neutrófilo muerto", "s": "netosis: núcleo<br>fragmentado", "c": "g", "x": 70, "y": 90, "ax": 71, "ay": 52}, {"n": "⑦", "t": "Bacterias atrapadas", "s": "destruidas por<br>la red", "c": "g", "x": 99.2, "y": 90, "ax": 85, "ay": 46, "al": "r"}]}, {"img": "img/13_2.webp", "ratio": 1.5, "titulo": "Las tres puertas de la apoptosis", "texto": "Membrana (Fas → <b>caspasa 8</b>) ③, mitocondria (citocromo C → apoptosoma → <b>caspasa 9</b>) ④ y núcleo (p53); todas terminan en las ejecutoras <span class=\"res\">3, 6 y 7</span> ②, que cortan el ADN <span class=\"lt2\">A</span>.", "etiquetas": [{"n": "③", "t": "LsT citotóxico", "s": "trae el FasL<br>(CD95L)", "c": "i", "x": 0.8, "y": 6, "ax": 12, "ay": 18, "al": "l"}, {"n": "③", "t": "Fas (CD95)", "s": "receptor de muerte<br>en la membrana", "c": "i", "x": 25, "y": 6, "ax": 15, "ay": 42}, {"n": "④", "t": "Mitocondria perforada", "s": "PUMA y BAX<br>abren poros", "c": "i", "x": 45, "y": 6, "ax": 51, "ay": 30}, {"n": "④", "t": "Citocromo C", "s": "sale al<br>citoplasma", "c": "i", "x": 63, "y": 6, "ax": 57, "ay": 43}, {"n": "④", "t": "p53", "s": "revisa el ADN<br>dañado", "c": "g", "x": 79, "y": 6, "ax": 77, "ay": 38}, {"n": "④", "t": "ADN roto", "s": "daño que p53<br>no repara", "c": "d", "x": 99.2, "y": 6, "ax": 84, "ay": 36, "al": "r"}, {"n": "③", "t": "Caspasa 8", "s": "iniciadora de la<br>vía de membrana", "c": "i", "x": 0.8, "y": 92, "ax": 14, "ay": 72, "al": "l"}, {"n": "④", "t": "Apoptosoma", "s": "citocromo C<br>+ Apaf-1", "c": "i", "x": 31, "y": 92, "ax": 46, "ay": 56}, {"n": "②④", "t": "Caspasa 9", "s": "enciende a las<br>ejecutoras 3, 6 y 7", "c": "i", "x": 50, "y": 92, "ax": 50, "ay": 73}, {"n": "②", "t": "Cromatina condensada", "s": "medialunas<br>oscuras", "c": "i", "x": 70, "y": 92, "ax": 73, "ay": 58}, {"n": "②", "t": "ADN en trozos", "s": "lo corta el CAD", "c": "i", "x": 99.2, "y": 92, "ax": 88, "ay": 52, "d": "A", "al": "r"}]}, {"img": "img/13_3.webp", "ratio": 1.5, "titulo": "Telómeros, telomerasa y autofagia", "texto": "Cada mitosis gasta telómero hasta que la célula envejece; la tumoral <span class=\"res\">repone</span> con telomerasa ⑧. La <mark>autofagia</mark> no es muerte: la célula se come a sí misma para sobrevivir ⑦.", "etiquetas": [{"n": "⑧", "t": "Telómero largo", "s": "célula joven", "c": "i", "x": 0.8, "y": 6, "ax": 6, "ay": 23, "al": "l"}, {"n": "⑧", "t": "Telomerasa", "s": "la tumoral repone<br>sus telómeros", "c": "d", "x": 42, "y": 6, "ax": 57, "ay": 22}, {"n": "⑦", "t": "Doble membrana", "s": "rodea una<br>mitocondria dañada", "c": "g", "x": 61, "y": 6, "ax": 69, "ay": 33}, {"n": "⑦", "t": "Lisosoma", "s": "se fusiona<br>y digiere", "c": "g", "x": 78, "y": 6, "ax": 85, "ay": 29}, {"n": "⑦", "t": "Autofagosoma", "s": "saca nutrientes<br>para sobrevivir", "c": "g", "x": 99.2, "y": 6, "ax": 93, "ay": 42, "al": "r"}, {"n": "⑧", "t": "Telómero agotado", "s": "uno menos en<br>cada mitosis", "c": "i", "x": 0.8, "y": 92, "ax": 7, "ay": 61, "al": "l"}, {"n": "⑧", "t": "Célula senescente", "s": "envejece y muere", "c": "i", "x": 29, "y": 92, "ax": 19, "ay": 70}, {"n": "⑧", "t": "Célula tumoral", "s": "se divide<br>sin límite", "c": "d", "x": 47, "y": 92, "ax": 40, "ay": 70}, {"n": "⑦", "t": "Bacilos atrapados", "s": "la autofagia elimina<br>M. tuberculosis", "c": "g", "x": 99.2, "y": 92, "ax": 80, "ay": 62, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"d\">rojo = necrosis</b> (muerte con inflamación), <b class=\"i\">azul = apoptosis</b> (muerte silenciosa), gris = <b>netosis</b> y otras formas.", "<b>Necrosis:</b> agentes físicos, químicos o <mark>porinas</mark> (NK, LsT citotóxicos, complemento) abren canales; entra agua y la célula <span class=\"res\">estalla</span>. La <b>necroptosis</b> se ve igual, pero es programada: TNF → necrosoma → RIPK3.", "<b>Apoptosis:</b> condensa la cromatina, corta el ADN en trozos de unos 200 pb y saca la <mark>fosfatidilserina</mark> afuera: es la señal «cómeme» para el macrófago.", "<b>Netosis:</b> el neutrófilo fragmenta su núcleo y lanza redes (NET) con unas veinte moléculas microbicidas que atrapan bacterias."], "recordar": "Necrosis = <b>estalla e inflama</b>; apoptosis = <b>se empaqueta y calla</b>; piroptosis = <b>caspasa 1, fuego</b>; autofagia = <b>se come a sí misma para sobrevivir</b>."}, "numeros": [{"l": "A", "html": "<b>Fragmentación del ADN</b> en la apoptosis: segmentos de unos <b class=\"n\">200 pares de bases</b>.", "rango": null}, {"l": "B", "html": "<b>Genes que regulan la apoptosis</b>: más de <b class=\"n\">200</b>; casi siempre participan la mitocondria y las caspasas.", "rango": null}, {"l": "C", "html": "<b>Redes NET</b>: se les adhieren unas <b class=\"n\">20 moléculas microbicidas</b> de origen granular.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la señal de muerte a la fagocitosis silenciosa", "subtitulo": "señal → iniciadoras → mitocondria → ejecutoras → cuerpos apoptóticos (y qué pasa si falla)", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Señal", "m": "<b>Tres puertas:</b> <mark>membrana</mark> (FasL se une a Fas, CD95); <mark>mitocondria</mark> (se pierden señales de supervivencia como insulina, IL-2, IL-3); <mark>núcleo</mark> (daño del ADN que p53 no repara).", "pr": "se activa el programa de muerte.", "pr_tit": "Produce:", "rf": "Preguntas ③④", "color": "p1"}, {"t": "2. Caspasas iniciadoras", "m": "<b>Por qué:</b> Fas activa la <b>caspasa 8</b>; p53 activa PUMA y BAX, que perforan la mitocondria y sale el <mark>citocromo C</mark>; con Apaf-1 se forma el apoptosoma y se activa la <b>caspasa 9</b>.", "pr": "las iniciadoras (8, 9 y 10) encienden la cascada.", "pr_tit": "Produce:", "rf": "Preguntas ②④⑥ · punto <span class=\"lt2\">B</span>", "color": "p2"}, {"t": "3. Caspasas ejecutoras", "m": "<b>Qué pasa:</b> las caspasas 3, 6 y 7 activan el CAD, que corta el ADN, y degradan la laminina nuclear. Los IAP las frenan; SMAC/DIABLO quita ese freno.", "pr": "cromatina condensada y ADN en trozos de unos 200 pb <span class=\"lt2\">A</span>.", "pr_tit": "Produce:", "rf": "Preguntas ②⑥", "color": "p3"}, {"t": "4. Cuerpos apoptóticos", "m": "<b>Qué produce:</b> la célula se encoge, forma protrusiones y se divide en cuerpos apoptóticos con <mark>fosfatidilserina</mark> afuera.", "pr": "el macrófago los fagocita <span class=\"res\">sin inflamación</span>.", "pr_tit": "Produce:", "rf": "Preguntas ①⑤", "color": "p4"}, {"t": "5. Si falla", "m": "<b>Poca apoptosis:</b> defectos de Fas/FasL o caspasas → autoinmunidad; telomerasa → cáncer. <b>Mucha apoptosis:</b> inmunosenescencia después de los <b>70 años</b>. <b>Otra vía:</b> caspasa 1 por el inflamasoma NLRP3 → piroptosis inflamatoria.", "pr": "autoinmunidad, tumores o infecciones del anciano.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑧", "color": "d"}], "extra": [{"html": "🧬 <b>Telómeros:</b> se pierde uno en cada mitosis; agotados, la célula envejece y muere. La célula maligna produce <mark>telomerasa</mark>, <span class=\"cx\">así que</span> se multiplica sin límite.", "k": ""}, {"html": "🍂 <b>Autofagia:</b> no es muerte sino <span class=\"res\">supervivencia</span>: ante estrés, inanición o hipoxia, la célula encierra parte de su citoplasma en un <b>autofagosoma</b> para sacar nutrientes; también elimina <b>M. tuberculosis</b> y <b>Toxoplasma</b> que escapan del fagosoma.", "k": "k"}], "escaleras": [{"c": "d", "t": "💥 De la porina al tejido inflamado (necrosis)", "pasos": ["Porinas, tóxicos o agentes físicos dañan la membrana", "entra agua: la célula se hincha", "<b>estallido osmótico</b>", "las enzimas salen y dañan a las vecinas", "<b>inflamación</b> siempre"]}], "html": "", "fuente": "Fuente: tu teoría — clase 16 (necrosis, necroptosis, apoptosis, caspasas, vías de inicio, telómeros, autofagia, netosis, piroptosis, inmunosenescencia)."}, "preguntas": [{"n": 1, "id": "IN7-018", "c": "d", "tema": "Necrosis y apoptosis", "pregunta": "Es característica de la necrosis y NO de la apoptosis:", "opciones": ["a. Condensación de la cromatina.", "b. Fragmentación del ADN en segmentos de unos 200 pares de bases.", "c. Externalización de la fosfatidilserina.", "d. Siempre es seguida de proceso inflamatorio.", "e. Formación de cuerpos apoptóticos."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La necrosis siempre es seguida de inflamación.", "sin_banco": true, "ok": "", "x": "Compara la célula que <b>revienta</b> (izquierda) con la que se <b>empaqueta</b> (centro): solo la primera derrama enzimas y atrae neutrófilos, <span class=\"cx\">por eso</span> <span class=\"res\">siempre inflama</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN7-019", "c": "i", "tema": "Caspasas", "pregunta": "Las caspasas ejecutoras de la apoptosis son:", "opciones": ["a. 1, 8 y 9.", "b. 8, 9 y 10.", "c. 3, 6 y 7.", "d. 2, 4 y 5.", "e. 1, 11 y 12."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. 3, 6 y 7.", "sin_banco": true, "ok": "", "x": "Las <mark>iniciadoras</mark> (8, 9 y 10) disparan la cascada; las <mark>ejecutoras</mark> (3, 6 y 7) hacen el trabajo final, <span class=\"cx\">porque</span> activan el CAD que corta el ADN y degradan la laminina nuclear. <span class=\"cx\">Así que</span> <span class=\"res\">la caspasa 3 es la ejecutora común</span> de las tres vías.", "truco": "Iniciadoras = números altos (8-9-10) que dan la orden; ejecutoras = 3-6-7 que cortan.", "veces": 0}, {"n": 3, "id": "IN7-020", "c": "i", "tema": "Vías de inicio de la apoptosis", "pregunta": "Describa la vía de apoptosis iniciada en la membrana.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "FasL (CD95L) se une al receptor Fas (CD95); su dominio de muerte activa la procaspasa 8 y libera caspasa 8, que lleva a la caspasa 3 ejecutora.", "sin_banco": true, "ok": "", "x": "Es la vía <mark>extrínseca</mark>: la orden de morir llega desde afuera, por el ligando Fas. El receptor tiene un dominio de muerte que activa la <span class=\"res\">caspasa 8</span>, y esta, <span class=\"cx\">luego</span>, la caspasa 3. <span class=\"cx\">Por eso</span> un defecto de Fas/FasL rompe la tolerancia y favorece la autoinmunidad.", "truco": "Fas = «faz» de afuera: la orden entra por la membrana.", "veces": 0}, {"n": 4, "id": "IN7-021", "c": "i", "tema": "Vías de inicio de la apoptosis", "pregunta": "Ante un daño irreparable del ADN, la secuencia correcta de la apoptosis iniciada en el núcleo es:", "opciones": ["a. p53 → PUMA → BAX → citocromo C → caspasa 9 → caspasa 3.", "b. FasL → Fas → caspasa 8 → caspasa 3.", "c. p53 → BAX → caspasa 1 → IL-1β.", "d. Citocromo C → p53 → PUMA → caspasa 8.", "e. TNF → necrosoma → RIPK3."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. p53 → PUMA → BAX → citocromo C (apoptosoma) → caspasa 9 → caspasa 3.", "sin_banco": true, "ok": "", "x": "Es la puerta del núcleo de la cadena (pasos 1-2): <mark>p53</mark> → PUMA → BAX → citocromo C → apoptosoma → <span class=\"res\">caspasa 9 y <span class=\"cx\">luego</span> 3</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN7-022", "c": "i", "tema": "Apoptosis: rasgos bioquímicos", "pregunta": "La señal de membrana que permite a los macrófagos reconocer y fagocitar sin inflamación a una célula apoptótica es:", "opciones": ["a. La liberación de enzimas lisosomales.", "b. La expresión de CD62L.", "c. La formación de poros por porinas.", "d. La liberación de IL-1β.", "e. La externalización de la fosfatidilserina."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La externalización de la fosfatidilserina (señal «cómeme»).", "sin_banco": true, "ok": "", "x": "En la escena central el macrófago come un cuerpo apoptótico <span class=\"res\">sin inflamación</span> alrededor: lo guía la <mark>fosfatidilserina</mark> expuesta.", "truco": "", "veces": 0}, {"n": 6, "id": "IN7-023", "c": "i", "tema": "Caspasas y control mitocondrial", "pregunta": "¿Cómo se libera una caspasa que está inhibida por los IAP?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Por la liberación de la proteína SMAC/DIABLO, que neutraliza a los IAP y devuelve la actividad a la caspasa.", "sin_banco": true, "ok": "", "x": "Los <mark>IAP</mark> son los frenos de las caspasas. La mitocondria libera SMAC/DIABLO, que «inhibe al inhibidor», <span class=\"cx\">por eso</span> <span class=\"res\">la caspasa recupera su actividad</span> y la apoptosis sigue.", "truco": "DIABLO le quita el freno al verdugo.", "veces": 0}, {"n": 7, "id": "IN7-024", "c": "g", "tema": "Autofagia, netosis y piroptosis", "pregunta": "Sobre las otras formas de muerte celular, es FALSO:", "opciones": ["a. La autofagia es sobre todo un mecanismo de supervivencia ante estrés, inanición o hipoxia.", "b. La piroptosis ocurre sin inflamación porque es una variante de la apoptosis.", "c. En la netosis el neutrófilo libera redes con unas veinte moléculas microbicidas.", "d. La piroptosis depende de la caspasa 1 activada por el inflamasoma NLRP3.", "e. La autofagia ayuda a eliminar M. tuberculosis que escapa del fagosoma."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La piroptosis es una muerte rápida y proinflamatoria (caspasa 1, IL-1β e IL-18).", "sin_banco": true, "ok": "", "x": "La piroptosis comparte con la apoptosis la fragmentación del ADN, pero con la necrosis la <mark>ruptura de membrana</mark>; <span class=\"cx\">por eso</span> es inflamatoria. <span class=\"cx\">Además</span> la caspasa 1 madura IL-1β e IL-18, <span class=\"cx\">así que</span> <span class=\"res\">piro = fuego</span>.", "truco": "PIROptosis = PIRO (fuego) = inflamación.", "veces": 0}, {"n": 8, "id": "IN7-025", "c": "g", "tema": "Telómeros", "pregunta": "¿Qué estructura limita el número de divisiones de una célula y cómo la evaden las células malignas?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Los telómeros, que se pierden uno a uno en cada mitosis; las células malignas producen telomerasa, que los repone y les permite multiplicarse indefinidamente.", "sin_banco": true, "ok": "", "x": "Cada mitosis gasta un trozo de <mark>telómero</mark>; <span class=\"cx\">cuando</span> se agotan, la célula entra en senescencia y muere. <span class=\"cx\">En cambio</span>, la célula tumoral fabrica <span class=\"res\">telomerasa</span>, <span class=\"cx\">así que</span> repone los telómeros y no conoce límite.", "truco": "Telómero = la mecha de la vela; telomerasa = la vela que se rellena sola.", "veces": 0}, {"n": 9, "id": "IN7-026", "c": "d", "tema": "Necrosis y necroptosis", "pregunta": "Paciente con infarto de miocardio: parte de los cardiomiocitos mueren con aspecto de necrosis pero por una vía molecular definida, activada por el TNF. ¿Cómo se llama esta muerte y qué quinasa la ejecuta?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Necroptosis, dependiente de la quinasa RIPK3; el TNF forma el necrosoma, que desactiva la caspasa 8.", "sin_banco": true, "ok": "", "x": "La necroptosis <mark>parece necrosis</mark> pero está programada: el TNF arma el necrosoma, que desactiva la caspasa 8, <span class=\"cx\">así que</span> la célula no hace apoptosis y estalla vía <span class=\"res\">RIPK3</span>. Participa en infarto, ACV, aterosclerosis, pancreatitis y enfermedad inflamatoria intestinal.", "truco": "Necro-PTOSIS = necrosis con programa (RIPK3).", "veces": 0}], "tabla": {"cab": ["", "Necrosis", "Apoptosis", "Piroptosis", "Netosis"], "filas": [["Disparo", "Daño de membrana (porinas)", "Fas, mitocondria o p53", "Caspasa 1 (NLRP3)", "Muerte del neutrófilo"], ["Membrana", "Se rompe", "Íntegra, con fosfatidilserina afuera", "Se rompe", "Libera redes"], ["Inflamación", "Siempre", "No", "Sí, rápida", "Variable"], ["Para qué", "Ninguno: es daño", "Limpia sin ruido", "Alarma (IL-1β, IL-18)", "Atrapa bacterias"], ["🔑 Para diferenciar", "Estalla", "Se empaqueta", "ADN cortado + estallido", "Red de ADN"]]}, "fuente": "Fuente: tu teoría — clase 16 «Por qué, cuándo y cómo mueren las células» (Rojas 17.ª ed., cap. 16)."}, {"n": 14, "slug": "Genetica_y_evaluacion_inmunologica", "titulo": "Genética, epigenética y evaluación inmunológica", "subtitulo": "de la cromatina abierta o cerrada al tubo de Ficoll y la citometría de flujo", "grupo": "g8", "lema": "La idea: los genes no lo deciden todo. Sobre el ADN hay <mark>marcas epigenéticas</mark> que <u>abren o cierran la cromatina</u> sin cambiar la secuencia; por eso un fármaco que desmetila puede causar lupus y otro que metila puede tratar una mielodisplasia. Y para saber cómo está el sistema inmune hay que <b>medirlo</b>: separar los linfocitos, marcarlos y contarlos, y dosar complemento y anticuerpos. En la imagen verás a la izquierda la cromatina abierta (acetilada) y cerrada (metilada), al centro el tubo de Ficoll-Hipaque y a la derecha la citometría de flujo.", "img": "img/14.webp", "mini": "img/mini/14.webp", "ratio": 1.5, "etiquetas": [{"n": "⑧", "t": "Acetilación", "s": "histonas H3 y H4:<br>abre la cromatina", "c": "i", "x": 0.8, "y": 6, "ax": 10, "ay": 17, "al": "l"}, {"n": "①⑥", "t": "Nucleosoma", "s": "ADN enrollado<br>en histonas", "c": "i", "x": 23, "y": 6, "ax": 25, "ay": 27, "d": "A"}, {"n": "⑫", "t": "Plasma", "s": "arriba, tras<br>centrifugar", "c": "g", "x": 40, "y": 6, "ax": 52, "ay": 30}, {"n": "⑬⑭", "t": "Anillo de linfocitos", "s": "capa intermedia:<br>se recogen aquí", "c": "d", "x": 59, "y": 6, "ax": 56, "ay": 42, "d": "B"}, {"n": "⑭", "t": "Láser", "s": "excita al<br>fluorocromo", "c": "d", "x": 76, "y": 6, "ax": 69, "ay": 34}, {"n": "⑭⑮", "t": "Célula marcada", "s": "monoclonal<br>fluorescente anti-CD", "c": "d", "x": 99.2, "y": 6, "ax": 80.5, "ay": 34.5, "d": "C", "al": "r"}, {"n": "⑨⑩", "t": "Metilación", "s": "CpG: el<br>gen calla", "c": "i", "x": 0.8, "y": 90, "ax": 13, "ay": 60, "al": "l"}, {"n": "①⑪", "t": "Cerrada", "s": "heterocromatina:<br>reversible", "c": "i", "x": 25, "y": 90, "ax": 27, "ay": 74}, {"n": "⑭", "t": "Ficoll-Hipaque", "s": "separa por<br>densidad", "c": "d", "x": 43.5, "y": 90, "ax": 53, "ay": 50}, {"n": "", "t": "Eritrocitos", "s": "y granulocitos<br>al fondo", "c": "g", "x": 61, "y": 90, "ax": 54, "ay": 78}, {"n": "⑮", "t": "Tubos colectores", "s": "cada población<br>a su tubo (CD4, CD8)", "c": "d", "x": 99.2, "y": 90, "ax": 87, "ay": 72, "al": "r"}], "diapos": [{"img": "img/14.webp", "ratio": 1.5, "titulo": "Epigenética y estudio de linfocitos", "texto": "La <mark>acetilación</mark> abre la cromatina y la <mark>metilación</mark> la cierra ⑧⑨; en el laboratorio, Ficoll separa los linfocitos y el citómetro los cuenta por CD ⑭ <span class=\"lt2\">C</span>.", "etiquetas": [{"n": "⑧", "t": "Acetilación", "s": "histonas H3 y H4:<br>abre la cromatina", "c": "i", "x": 0.8, "y": 6, "ax": 10, "ay": 17, "al": "l"}, {"n": "①⑥", "t": "Nucleosoma", "s": "ADN enrollado<br>en histonas", "c": "i", "x": 23, "y": 6, "ax": 25, "ay": 27, "d": "A"}, {"n": "⑫", "t": "Plasma", "s": "arriba, tras<br>centrifugar", "c": "g", "x": 40, "y": 6, "ax": 52, "ay": 30}, {"n": "⑬⑭", "t": "Anillo de linfocitos", "s": "capa intermedia:<br>se recogen aquí", "c": "d", "x": 59, "y": 6, "ax": 56, "ay": 42, "d": "B"}, {"n": "⑭", "t": "Láser", "s": "excita al<br>fluorocromo", "c": "d", "x": 76, "y": 6, "ax": 69, "ay": 34}, {"n": "⑭⑮", "t": "Célula marcada", "s": "monoclonal<br>fluorescente anti-CD", "c": "d", "x": 99.2, "y": 6, "ax": 80.5, "ay": 34.5, "d": "C", "al": "r"}, {"n": "⑨⑩", "t": "Metilación", "s": "CpG: el<br>gen calla", "c": "i", "x": 0.8, "y": 90, "ax": 13, "ay": 60, "al": "l"}, {"n": "①⑪", "t": "Cerrada", "s": "heterocromatina:<br>reversible", "c": "i", "x": 25, "y": 90, "ax": 27, "ay": 74}, {"n": "⑭", "t": "Ficoll-Hipaque", "s": "separa por<br>densidad", "c": "d", "x": 43.5, "y": 90, "ax": 53, "ay": 50}, {"n": "", "t": "Eritrocitos", "s": "y granulocitos<br>al fondo", "c": "g", "x": 61, "y": 90, "ax": 54, "ay": 78}, {"n": "⑮", "t": "Tubos colectores", "s": "cada población<br>a su tubo (CD4, CD8)", "c": "d", "x": 99.2, "y": 90, "ax": 87, "ay": 72, "al": "r"}]}, {"img": "img/14_2.webp", "ratio": 1.5, "titulo": "Las pruebas clásicas del laboratorio", "texto": "<mark>ELISA</mark> cambia el isótopo por una enzima ⑯; el <b>Western blot</b> confirma un ELISA dudoso ⑲; <b>Ouchterlony</b> muestra identidad, no identidad e identidad parcial ⑳.", "etiquetas": [{"n": "⑯", "t": "Anticuerpo marcado", "s": "lleva una enzima,<br>no un isótopo", "c": "d", "x": 0.8, "y": 6, "ax": 11, "ay": 42, "al": "l"}, {"n": "⑯", "t": "Producto de color", "s": "la enzima tiñe<br>el sustrato", "c": "d", "x": 31, "y": 6, "ax": 24, "ay": 27}, {"n": "⑲", "t": "Gel", "s": "electroforesis:<br>separa proteínas", "c": "d", "x": 50, "y": 6, "ax": 43, "ay": 32}, {"n": "⑳", "t": "Arcos fusionados", "s": "identidad", "c": "d", "x": 72, "y": 6, "ax": 79, "ay": 37}, {"n": "⑳", "t": "Arcos cruzados", "s": "no identidad", "c": "d", "x": 99.2, "y": 6, "ax": 88, "ay": 42, "al": "r"}, {"n": "⑯", "t": "Pozos del ELISA", "s": "más color,<br>más antígeno", "c": "d", "x": 0.8, "y": 92, "ax": 10, "ay": 72, "al": "l"}, {"n": "⑯", "t": "Antígeno capturado", "s": "entre dos<br>anticuerpos", "c": "d", "x": 26, "y": 92, "ax": 22, "ay": 48}, {"n": "⑲", "t": "Western blot", "s": "bandas que confirman<br>un ELISA dudoso", "c": "d", "x": 49, "y": 92, "ax": 56, "ay": 62}, {"n": "⑳", "t": "Pozo central", "s": "frente a seis<br>pozos periféricos", "c": "d", "x": 71, "y": 92, "ax": 80, "ay": 47}, {"n": "⑳", "t": "Espolón", "s": "identidad parcial", "c": "d", "x": 99.2, "y": 92, "ax": 83, "ay": 57, "al": "r"}]}, {"img": "img/14_3.webp", "ratio": 1.5, "titulo": "Genes, SNP y terapia génica", "texto": "El MHC está en el <mark>cromosoma 6</mark> ②; el X lleva TLR7, CD40L y FOXP3 ③④. Un <b>SNP</b> cambia una sola base ⑥, y la terapia génica de la ADA corrigió la inmunidad pero causó <span class=\"res\">linfoproliferación</span> ⑦.", "etiquetas": [{"n": "②", "t": "Cromosoma 6", "s": "MHC y factores<br>del complemento", "c": "i", "x": 0.8, "y": 6, "ax": 8, "ay": 42, "al": "l"}, {"n": "③", "t": "Cromosoma X", "s": "TLR7, CD40L,<br>FOXP3, miARN", "c": "i", "x": 28, "y": 6, "ax": 24, "ay": 36}, {"n": "⑦", "t": "Vector viral", "s": "lleva el gen<br>corregido", "c": "i", "x": 58, "y": 6, "ax": 61, "ay": 33}, {"n": "⑦", "t": "Gen corregido", "s": "entra a la<br>célula madre", "c": "i", "x": 80, "y": 6, "ax": 72, "ay": 48}, {"n": "④", "t": "Dos cromosomas X", "s": "mejor defensa, pero<br>más autoinmunidad", "c": "i", "x": 0.8, "y": 92, "ax": 22, "ay": 62, "al": "l"}, {"n": "⑤⑥", "t": "SNP", "s": "cambia una sola base;<br>el GWAS lo asocia", "c": "i", "x": 40, "y": 92, "ax": 46, "ay": 48}, {"n": "⑦", "t": "Célula madre", "s": "médula ósea<br>(déficit de ADA)", "c": "i", "x": 63, "y": 92, "ax": 70, "ay": 63}, {"n": "⑦", "t": "Linfocitos nuevos", "s": "inmunidad corregida;<br>riesgo: linfoproliferación", "c": "i", "x": 99.2, "y": 92, "ax": 91, "ay": 62, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = genética y epigenética</b> (clase 17), <b class=\"d\">rojo = laboratorio</b> (clase 18), gris = estructuras de referencia.", "<b>Cromatina:</b> el ADN se enrolla en histonas (<mark>nucleosoma</mark>). La <b>acetilación</b> de las histonas la abre y el gen se expresa; la <b>metilación</b> de las citosinas (islas CpG) la cierra y el gen calla. Esas marcas <span class=\"res\">prevalecen</span> sobre la secuencia y son reversibles.", "<b>Tubo de Ficoll-Hipaque:</b> tras centrifugar, los linfocitos forman un <mark>anillo intermedio</mark>, entre el plasma (arriba) y los eritrocitos y granulocitos (abajo).", "<b>Citometría:</b> los linfocitos marcados con monoclonales fluorescentes pasan de a uno frente a un láser y se separan por su fluorescencia (CD4, CD8…)."], "recordar": "Acetilación = <b>abre</b>; metilación = <b>calla</b>. Separar (Ficoll) → pintar (monoclonales) → contar (citómetro). CH50 bajo = complemento <b>activado</b>."}, "numeros": [{"l": "A", "html": "<b>Nucleosoma</b>: <b class=\"n\">146 pares de bases</b> de ADN asociadas a histonas. El genoma tiene unos <b class=\"n\">3,2 mil millones</b> de pb y <b class=\"n\">20.000 genes</b>; solo el <b class=\"n\">1–2 %</b> codifica proteínas.", "rango": null}, {"l": "B", "html": "<b>Linfocitos</b>: menos de <b class=\"b\">1.000 /mm³</b> indica deficiencia; un aumento sugiere infección o proliferación maligna.", "rango": {"min": 0, "max": 3000, "unidad": "linfocitos/mm³", "zonas": [[0, 1000, "b", "Deficiencia"], [1000, 3000, "n"]], "marcas": [1000]}}, {"l": "C", "html": "<b>Subpoblaciones</b>: CD3+ <b class=\"n\">60–75 %</b>, CD4+ <b class=\"n\">60–70 %</b>, CD8+ <b class=\"n\">20–30 %</b>, γδ <b class=\"n\">5–10 %</b>, CD22+ (B) <b class=\"n\">8–15 %</b>, CD16+ (NK) <b class=\"n\">7–15 %</b>.", "rango": {"min": 0, "max": 30, "unidad": "% CD22+ (LB)", "zonas": [[0, 8, "b"], [8, 15, "n"], [15, 30, "a"]], "marcas": [8, 15]}}], "escalas": [], "cadena": {"titulo": "Del gen al resultado de laboratorio", "subtitulo": "ambiente → marca epigenética → expresión del gen → enfermedad → cómo se mide", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> factores del ambiente (fármacos, envejecimiento, estrés) actúan sobre el genoma; las <mark>sirtuinas</mark> son el sensor que traduce el estrés metabólico en marcas.", "pr": "se modifica la cromatina sin cambiar la secuencia.", "pr_tit": "Produce:", "rf": "Preguntas ①⑥", "color": "p1"}, {"t": "2. Marcas", "m": "<b>Por qué:</b> la <b>metilación</b> de citosinas en islas CpG (ADN-metiltransferasa) reprime; la <b>acetilación</b> de H3 y H4 abre la cromatina; las HDAC la cierran. Las marcas <mark>prevalecen</mark> sobre los factores de transcripción.", "pr": "eucromatina activa o heterocromatina silenciosa <span class=\"lt2\">A</span>.", "pr_tit": "Produce:", "rf": "Preguntas ①⑧⑪", "color": "p2"}, {"t": "3. Genes inmunes", "m": "<b>Dónde:</b> cromosoma 6 (MHC, complemento), X (TLR7, CD40L, FOXP3), 2, 14 y 22 (cadenas de inmunoglobulinas). Los SNP y los loci de GWAS modulan el riesgo.", "pr": "IRF5 → lupus, IL2RA → diabetes tipo 1, CD6 → esclerosis múltiple (GWAS: 425 loci de riesgo).", "pr_tit": "Produce:", "rf": "Preguntas ②③④⑤⑥", "color": "p3"}, {"t": "4. Enfermedad", "m": "<b>Si falla:</b> hipometilación por <mark>hidralazina o procainamida</mark> → lupus; hipometilación global + hipermetilación de supresores → cáncer; déficit de ADA → SCID (terapia génica con riesgo linfoproliferativo).", "pr": "autoinmunidad, cáncer o inmunodeficiencia.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑨⑩", "color": "d"}, {"t": "5. Cómo se mide", "m": "<b>Innata:</b> leucograma, quimiotaxis, quimioluminiscencia, <mark>CH50</mark>, C3 y C4, PCR. <b>Celular:</b> recuento <span class=\"lt2\">B</span>, Ficoll + monoclonales + citometría <span class=\"lt2\">C</span>. <b>Humoral:</b> electroforesis, ELISA, nefelometría (IgE), Western blot.", "pr": "se sabe qué línea falla y cuánto.", "pr_tit": "Produce:", "rf": "Preguntas ⑫–㉒", "color": "p5"}], "extra": [{"html": "🧪 <b>ELISA o RIA:</b> los dos detectan antígeno o anticuerpo; el RIA usa un <mark>isótopo</mark> (muy sensible, contamina), el ELISA una <b>enzima</b> (estable, algo menos sensible). Si el ELISA para VIH sale dudoso, se confirma con <b>Western blot</b>.", "k": ""}, {"html": "🧫 <b>Fijación del complemento (Wassermann):</b> si hay anticuerpos, la reacción <b>consume</b> el complemento y los eritrocitos de carnero <span class=\"res\">no se lisan</span>; sin anticuerpos, el complemento queda libre y sí hay lisis.", "k": "k"}], "escaleras": [{"c": "i", "t": "🔬 Ruta para estudiar una sospecha de inmunodeficiencia", "pasos": ["Leucograma con extendido periférico", "recuento de linfocitos: ¿menos de 1.000/mm³?", "Ficoll-Hipaque: separar linfocitos", "monoclonales fluorescentes anti-CD", "<b>citometría de flujo</b>: qué línea (T, B o NK) falla y cuánto"]}], "html": "", "fuente": "Fuente: tu teoría — clase 17 (cromosomas, GWAS, SNP, terapia génica, mecanismos epigenéticos, lupus inducido, cáncer, bisulfito, terapia epigenética) y clase 18 (innata, celular, humoral, alergia, autoinmunidad, Western blot)."}, "preguntas": [{"n": 1, "id": "IN8-001", "c": "i", "tema": "Mecanismos epigenéticos", "pregunta": "Son mecanismos que generan marcas epigenéticas, EXCEPTO:", "opciones": ["a. Metilación de la citosina del ADN.", "b. Acetilación de las histonas.", "c. Remodelación de la estructura de la cromatina.", "d. Mutación puntual (SNP) de una base por otra.", "e. Desacetilación de histonas por las HDAC."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El SNP cambia la secuencia: es un cambio genético, no epigenético.", "sin_banco": true, "ok": "", "x": "La epigenética modifica la <mark>expresión</mark> del genoma sin tocar la secuencia; sus tres mecanismos son metilación, acetilación (y su reverso, la desacetilación) y remodelación de la cromatina. <span class=\"cx\">En cambio</span>, un SNP cambia una base, <span class=\"cx\">así que</span> es <span class=\"res\">genético</span>.", "truco": "Epi = «encima» del ADN: marca la tapa, no cambia las letras.", "veces": 0}, {"n": 2, "id": "IN8-002", "c": "i", "tema": "Genes y respuesta inmune", "pregunta": "El complejo mayor de histocompatibilidad (MHC) y varios factores del complemento se codifican en el cromosoma:", "opciones": ["a. X.", "b. 2.", "c. 6.", "d. 14.", "e. 22."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Cromosoma 6.", "sin_banco": true, "ok": "", "x": "El <mark>cromosoma 6</mark> guarda el MHC, factores del complemento y proteínas de choque térmico, <span class=\"cx\">por eso</span> es la base de la presentación del antígeno. <span class=\"cx\">En cambio</span>, los cromosomas 2, 14 y 22 llevan las <span class=\"res\">cadenas de las inmunoglobulinas</span> (y el 14, también el TCR).", "truco": "SELFIE tiene 6 letras: el MHC del cromosoma 6 muestra lo propio.", "veces": 0}, {"n": 3, "id": "IN8-003", "c": "i", "tema": "Cromosoma X", "pregunta": "Son genes inmunológicos localizados en el cromosoma X, EXCEPTO:", "opciones": ["a. TLR7.", "b. CD40L.", "c. FOXP3.", "d. Numerosos miARN.", "e. El complejo mayor de histocompatibilidad."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. El MHC está en el cromosoma 6.", "sin_banco": true, "ok": "", "x": "El X lleva <mark>TLR7, CD40L, FOXP3</mark> y muchos miARN, <span class=\"cx\">por eso</span> se asocia a <span class=\"res\">13 inmunodeficiencias ligadas a X</span>. El MHC, <span class=\"cx\">en cambio</span>, está en el cromosoma 6.", "truco": "En la X viajan el TOLL-7, el CD40L y el FOX (zorro).", "veces": 0}, {"n": 4, "id": "IN8-004", "c": "i", "tema": "Cromosoma X", "pregunta": "¿Por qué el cromosoma X da a las mujeres mejor defensa antiinfecciosa pero mayor riesgo autoinmune?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque alberga genes inmunológicos clave (TLR7, CD40L, FOXP3, miARN): dos copias mejoran la respuesta antiinfecciosa, pero aumentan la expresión anormal de esos genes y la autoinmunidad.", "sin_banco": true, "ok": "", "x": "Tener <mark>dos X</mark> es tener doble dosis de genes inmunes, <span class=\"cx\">así que</span> la mujer se defiende mejor de las infecciones. <span class=\"cx\">En cambio</span>, esa misma dosis extra facilita que se expresen de forma anormal, <span class=\"cx\">por eso</span> <span class=\"res\">predomina la autoinmunidad en mujeres</span>.", "truco": "Doble X = doble escudo, doble riesgo.", "veces": 0}, {"n": 5, "id": "IN8-005", "c": "i", "tema": "Genes y respuesta inmune (GWAS)", "pregunta": "Según los estudios GWAS, la asociación correcta es:", "opciones": ["a. IRF5 – diabetes tipo 1.", "b. IL2RA – lupus eritematoso sistémico.", "c. Isoformas de CD6 – esclerosis múltiple.", "d. IRF5 – esclerosis múltiple.", "e. IL2RA – artritis reumatoide."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Isoformas de CD6 – esclerosis múltiple.", "sin_banco": true, "ok": "", "x": "Los GWAS hallaron <mark>425 loci de riesgo</mark>, más de 35 ligados a enfermedad inmunológica. Las tres parejas de la clase son IRF5 → lupus, IL2RA → diabetes tipo 1 y <span class=\"res\">CD6 → esclerosis múltiple</span>; <span class=\"cx\">por eso</span> a y b están invertidas.", "truco": "IRF5 = Lupus (5 letras: L-U-P-U-S); IL2RA = Azúcar; CD6 = Esclerosis.", "veces": 0}, {"n": 6, "id": "IN8-006", "c": "i", "tema": "Mecanismos de alteración del genoma", "pregunta": "¿Qué es un SNP y por qué importa en las enfermedades poligénicas?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Polimorfismo de un solo nucleótido: el cambio de una base por otra, que puede alterar la transcripción; su estudio por GWAS asocia variantes con el riesgo de enfermedades poligénicas.", "sin_banco": true, "ok": "", "x": "Es la alteración más pequeña: <mark>una sola letra</mark> del ADN cambia. La mayoría de enfermedades inmunes son poligénicas, <span class=\"cx\">así que</span> muchos SNP pequeños suman riesgo; <span class=\"cx\">por eso</span> se rastrean con <span class=\"res\">GWAS</span>. Los otros mecanismos son inserción/deleción y rearreglo estructural.", "truco": "SNP = «Solo uN Punto» cambiado.", "veces": 0}, {"n": 7, "id": "IN8-007", "c": "i", "tema": "Terapia génica", "pregunta": "Niño con inmunodeficiencia combinada severa por déficit de adenosindeaminasa (ADA) recibe terapia génica con vector viral y se corrige su inmunidad. ¿Qué complicación presentaron algunos niños tratados entre 2000 y 2002?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Un síndrome linfoproliferativo, lo que impulsó la búsqueda de vectores virales más seguros.", "sin_banco": true, "ok": "", "x": "El primer intento fue en <mark>1990</mark> y la corrección funcionó entre 2000 y 2002. Pero el vector viral se integró en el genoma, <span class=\"cx\">así que</span> algunos niños hicieron un <span class=\"res\">síndrome linfoproliferativo</span> (la causa exacta por integración del vector es literatura). Otra opción de reemplazo es el trasplante de médula ósea.", "truco": "ADA corregida, pero el virus «despertó» linfocitos de más.", "veces": 0}, {"n": 8, "id": "IN8-008", "c": "i", "tema": "Mecanismos epigenéticos", "pregunta": "La acetilación de las lisinas de las histonas H3 y H4:", "opciones": ["a. Abre la cromatina y aumenta la transcripción.", "b. Compacta la cromatina y reprime el gen.", "c. Cambia la secuencia de bases del ADN.", "d. Metila las islas CpG del promotor.", "e. Es revertida por la ADN-metiltransferasa."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Abre la cromatina (eucromatina) y favorece la transcripción.", "sin_banco": true, "ok": "", "x": "Mira la cromatina de arriba a la izquierda: con <mark>acetilación</mark> está <b>suelta</b> y el ADN queda accesible; abajo, metilada y compacta, <span class=\"res\">el gen calla</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN8-009", "c": "i", "tema": "Epigenética y enfermedad", "pregunta": "Varón de 60 años, hipertenso tratado con hidralazina, presenta artralgias y anticuerpos antinucleares positivos. El mecanismo de este lupus inducido es:", "opciones": ["a. Hipermetilación de las islas CpG de genes supresores.", "b. Inhibición de la ADN-metiltransferasa 1 con hipometilación del ADN.", "c. Mutación del gen AIRE.", "d. Acetilación excesiva de histonas por inhibición de las sirtuinas.", "e. Deleción del cromosoma X."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La hidralazina (como la procainamida) inhibe la ADN-metiltransferasa 1: hipometilación y expresión anormal de genes de autoinmunidad.", "sin_banco": true, "ok": "", "x": "Sin metilación, los genes de autoinmunidad que estaban <mark>silenciados</mark> se encienden en los linfocitos T y caen los CD4. <span class=\"cx\">Por eso</span> aparece un cuadro de <span class=\"res\">lupus de tipo epigenético</span>; unos cien fármacos pueden inducir ANA.", "truco": "HIDRAlazina y PROCAinamida «desmetilan»: HIPOmetilación = lupus.", "veces": 0}, {"n": 10, "id": "IN8-010", "c": "i", "tema": "Epigenética y cáncer", "pregunta": "El patrón epigenético característico del desarrollo temprano del cáncer es:", "opciones": ["a. Hipermetilación global y desmetilación de los genes supresores.", "b. Acetilación global de histonas sin cambios de metilación.", "c. Mutación de p53 sin cambios epigenéticos.", "d. Hipometilación focal de los oncogenes solamente.", "e. Hipometilación global con hipermetilación focal de las islas CpG de genes supresores."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Hipometilación global (evento temprano) con hipermetilación focal de promotores de genes supresores.", "sin_banco": true, "ok": "", "x": "Son dos errores a la vez: el genoma se <mark>desmetila</mark> en general (y se acumula con el avance tumoral), <span class=\"cx\">en cambio</span> los genes supresores se <span class=\"res\">silencian</span> por hipermetilación de sus promotores. <span class=\"cx\">Por eso</span> los inhibidores de la metilación (vidaza, decitabine) tienen sentido.", "truco": "Cáncer: «todo suelto, los frenos amarrados».", "veces": 0}, {"n": 11, "id": "IN8-011", "c": "i", "tema": "Bisulfito y terapia epigenética", "pregunta": "¿Por qué el bisulfito de sodio revolucionó el estudio de la metilación, y qué fármacos epigenéticos están aprobados?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Convierte la citosina no metilada en uracilo y la 5-metilcitosina en timina, así distingue el estado de metilación que la PCR y la clonación no ven. Aprobados: vidaza (azacitidina) y decitabine, en mielodisplasias.", "sin_banco": true, "ok": "", "x": "La PCR solo lee la <mark>secuencia</mark>; el bisulfito «marca» de forma distinta las citosinas metiladas y las no metiladas, <span class=\"cx\">por eso</span> recupera la información epigenética. Como las marcas son reversibles, se tratan con fármacos: <span class=\"res\">vidaza y decitabine</span> en mielodisplasias.", "truco": "Bisulfito = revelador de la foto epigenética.", "veces": 0}, {"n": 12, "id": "IN8-012", "c": "d", "tema": "Evaluación de la inmunidad innata", "pregunta": "Una actividad hemolítica total del complemento (CH50) disminuida indica:", "opciones": ["a. Deficiencia de IgE.", "b. Que el sistema del complemento ha sido activado.", "c. Defecto de la quimiotaxis.", "d. Exceso de C3 y C4.", "e. Linfopenia."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Que el complemento ha sido activado (consumido); es la prueba de tamizaje.", "sin_banco": true, "ok": "", "x": "Si el complemento se activa, sus factores se <mark>consumen</mark>, <span class=\"cx\">así que</span> queda menos para lisar los eritrocitos de la prueba y el CH50 baja. <span class=\"cx\">Por eso</span> es el tamizaje; <span class=\"cx\">luego</span> se dosan <span class=\"res\">C3 y C4</span> por inmunodifusión radial.", "truco": "CH50 bajo = complemento «gastado».", "veces": 0}, {"n": 13, "id": "IN8-013", "c": "d", "tema": "Evaluación de la inmunidad celular", "pregunta": "¿Qué recuento absoluto de linfocitos indica deficiencia y qué sugiere un aumento?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Menos de 1.000 linfocitos por mm³ indica deficiencia; un incremento sugiere infección o proliferación maligna.", "sin_banco": true, "ok": "", "x": "El <mark>extendido de sangre periférica</mark> da el primer indicio. Si los linfocitos caen por debajo de <span class=\"res\">1.000/mm³</span> hay que descartar una inmunodeficiencia; <span class=\"cx\">en cambio</span>, si suben, se piensa en infección o en un proceso maligno.", "truco": "Menos de «mil» = «mil» problemas.", "veces": 0}, {"n": 14, "id": "IN8-014", "c": "d", "tema": "Evaluación de la inmunidad celular", "pregunta": "¿Qué tres pasos se siguen para estudiar las subpoblaciones de linfocitos en sangre periférica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "1) Separar los linfocitos por centrifugación en gradiente de Ficoll-Hipaque; 2) marcarlos con anticuerpos monoclonales fluorescentes contra moléculas CD; 3) analizarlos por citometría de flujo.", "sin_banco": true, "ok": "", "x": "Es la lámina de izquierda a derecha en su mitad derecha: <mark>Ficoll</mark> (anillo de linfocitos en el tubo) → monoclonales fluorescentes → <span class=\"res\">citometría</span> con láser y tubos colectores.", "truco": "", "veces": 0}, {"n": 15, "id": "IN8-015", "c": "d", "tema": "Subpoblaciones linfocitarias", "pregunta": "En el estudio de subpoblaciones linfocitarias, el par marcador – rango de referencia correcto es:", "opciones": ["a. CD3+ (T totales): 20-30 %.", "b. CD8+ (T citotóxicos): 60-70 %.", "c. CD22+ (linfocitos B): 8-15 %.", "d. CD16+ (NK): 60-75 %.", "e. T gamma-delta: 20-30 %."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. CD22+ (linfocitos B): 8-15 %.", "sin_banco": true, "ok": "", "x": "Según la tabla de la clase: T totales <mark>CD3+ 60-75 %</mark>, CD4+ 60-70 %, CD8+ 20-30 %, γδ 5-10 %, NK CD16+ 7-15 % y <span class=\"res\">linfocitos B CD22+ 8-15 %</span>. Las demás opciones intercambian los rangos.", "truco": "B = «22» como dos patitos: pocos (8-15 %).", "veces": 0}, {"n": 16, "id": "IN8-016", "c": "d", "tema": "Técnicas de inmunidad humoral", "pregunta": "Respecto al ELISA, es correcto:", "opciones": ["a. Usa una enzima (peroxidasa o fosfatasa) como marcador en lugar de un isótopo.", "b. Es más contaminante que el radioinmunoanálisis.", "c. Es siempre más sensible que el RIA.", "d. Se basa en el consumo de complemento.", "e. Separa las proteínas por carga eléctrica."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Sustituye el isótopo del RIA por una enzima; es más estable y no contaminante, aunque algo menos sensible.", "sin_banco": true, "ok": "", "x": "El RIA usa <mark>isótopos radiactivos</mark>: es muy sensible pero contamina. El ELISA cambia el isótopo por una enzima, <span class=\"cx\">así que</span> es más estable y seguro, aunque <span class=\"res\">algo menos sensible</span>. La d es la fijación del complemento y la e, la electroforesis.", "truco": "ELISA = Enzima en Lugar del Isótopo.", "veces": 0}, {"n": 17, "id": "IN8-017", "c": "d", "tema": "Inmunoglobulina E", "pregunta": "La IgE sérica total se cuantifica por:", "opciones": ["a. Inmunodifusión radial simple.", "b. Inmunodifusión doble de Ouchterlony.", "c. Electroforesis convencional.", "d. Nefelometría.", "e. Fijación del complemento."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Nefelometría.", "sin_banco": true, "ok": "", "x": "La IgE está en <mark>concentración muy baja</mark>, <span class=\"cx\">por eso</span> la inmunodifusión radial no la detecta. La nefelometría mide la dispersión de una radiación al atravesar partículas, <span class=\"cx\">así que</span> sí la cuantifica. La <span class=\"res\">IgE específica</span> se dosa por radioinmunoensayo.", "truco": "IgE «nebulosa»: se mide con NEFElometría.", "veces": 0}, {"n": 18, "id": "IN8-018", "c": "d", "tema": "Técnicas de inmunidad humoral", "pregunta": "La prueba de Wassermann para sífilis se basa en:", "opciones": ["a. Aglutinación.", "b. ELISA.", "c. Inmunofluorescencia indirecta.", "d. Fijación del complemento.", "e. Western blot."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Fijación del complemento.", "sin_banco": true, "ok": "", "x": "Si el suero tiene anticuerpos, la reacción antígeno-anticuerpo <mark>consume el complemento</mark>, <span class=\"cx\">así que</span> no queda para lisar el sistema indicador (eritrocitos de carnero con su anticuerpo). <span class=\"cx\">En cambio</span>, sin reacción el complemento queda libre y hay lisis. Esa es la base de la <span class=\"res\">prueba de Wassermann</span>.", "truco": "Wassermann: sin lisis = sífilis (complemento «fijado»).", "veces": 0}, {"n": 19, "id": "IN8-019", "c": "d", "tema": "Western blot", "pregunta": "Paciente con ELISA sospechoso (dudoso) para VIH. ¿Qué prueba confirma el diagnóstico y en qué consiste?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El Western blot (inmunoblot): transfiere proteínas separadas por electroforesis a una fase sólida y las identifica con anticuerpos marcados.", "sin_banco": true, "ok": "", "x": "El ELISA es un <mark>tamizaje</mark>; si sale sospechoso, se confirma con el Western blot, <span class=\"cx\">porque</span> identifica las <span class=\"res\">proteínas virales específicas</span> una por una en la membrana.", "truco": "ELISA tamiza, Western confirma.", "veces": 0}, {"n": 20, "id": "IN8-020", "c": "d", "tema": "Técnicas de inmunidad humoral", "pregunta": "La inmunodifusión doble de Ouchterlony permite:", "opciones": ["a. Cuantificar la IgE total.", "b. Distinguir identidad, no identidad e identidad parcial entre los anticuerpos de dos sueros.", "c. Separar linfocitos por densidad.", "d. Tipificar el MHC de clase II.", "e. Medir complejos inmunes por el C1q."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Distinguir identidad, no identidad e identidad parcial.", "sin_banco": true, "ok": "", "x": "En el gel, las líneas de <mark>precipitación</mark> de dos sueros se unen, se cruzan o forman un espolón. <span class=\"cx\">Por eso</span> dice si reconocen el mismo epítope (identidad), epítopes distintos (no identidad) o <span class=\"res\">relacionados (identidad parcial)</span>.", "truco": "Ouchterlony = dos pozos que «se miran»: ¿iguales, distintos o parecidos?", "veces": 0}, {"n": 21, "id": "IN8-021", "c": "d", "tema": "Evaluación de la inmunidad innata", "pregunta": "¿Por qué un recuento normal de neutrófilos no descarta un defecto de la fagocitosis?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque el número no garantiza la función; se necesitan pruebas funcionales, como la quimioluminiscencia de los PMN tras ingerir microorganismos (y la quimiotaxis en cámara de Boyden).", "sin_banco": true, "ok": "", "x": "Contar neutrófilos dice <mark>cuántos hay</mark>, no si matan. <span class=\"cx\">Por eso</span> la fagocitosis se evalúa midiendo la <span class=\"res\">quimioluminiscencia</span> que emiten al ingerir microbios; la migración se mide con la cámara de Boyden, la agarosa o la ventana de Rebuck.", "truco": "Cantidad no es calidad.", "veces": 0}, {"n": 22, "id": "IN8-022", "c": "d", "tema": "Evaluación autoinmune", "pregunta": "Ante la falta de un método directo, los complejos inmunes circulantes se miden:", "opciones": ["a. Midiendo el C1q del complemento, con el que tienen gran afinidad.", "b. Por nefelometría de la IgE.", "c. Por citometría de flujo con CD22.", "d. Por la prueba de Coombs.", "e. Por cariotipo."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Midiendo el C1q (o precipitándolos químicamente y cuantificando la IgG).", "sin_banco": true, "ok": "", "x": "Los complejos inmunes tienen <mark>gran afinidad por el C1q</mark>, <span class=\"cx\">así que</span> se los «pesca» con él. La otra vía es precipitarlos químicamente y <span class=\"cx\">luego</span> medir la <span class=\"res\">IgG</span> que contienen.", "truco": "C1q = el anzuelo de los complejos inmunes.", "veces": 0}], "tabla": {"cab": ["Técnica", "Principio", "Para qué"], "filas": [["CH50, C3 y C4", "Lisis total; inmunodifusión radial", "Tamizaje del complemento; autoinmunidad y rechazo"], ["Citometría", "Láser y anticuerpos fluorescentes", "Subpoblaciones y clasificar leucemias"], ["ELISA", "Enzima como marcador", "Detectar antígeno o anticuerpo (tamizaje)"], ["Western blot", "Proteínas transferidas a fase sólida", "Confirmar VIH tras ELISA dudoso"], ["Nefelometría", "Dispersión de radiación", "IgE total (muy baja)"], ["Bisulfito", "Citosina no metilada → uracilo", "Ver el estado de metilación"], ["🔑 Lo que no debes olvidar", "CH50 bajo = complemento activado", "Menos de 1.000 linfocitos/mm³ = deficiencia"]]}, "fuente": "Fuente: tu teoría — clases 17 (Genética y epigenética de la respuesta inmune) y 18 (Evaluación del estado inmunológico), Rojas 17.ª ed."}, {"n": 15, "slug": "Bacterias_hospedero_y_defensa", "titulo": "Bacterias: hospedero, virulencia y defensa", "subtitulo": "cómo se pega, se esconde y cae una bacteria", "grupo": "g9", "lema": "La idea: toda infección es un triángulo —<mark>hospedero susceptible</mark>, <mark>patógeno</mark> y <mark>microambiente</mark>—. La bacteria gana terreno por etapas: se <b>adhiere</b> (pili, adhesinas, biopelícula), <b>invade</b> y <b>se esconde</b> (cápsula contra el fagocito, ácido siálico contra el complemento). El hospedero responde con barreras, <b>complemento</b> (poro y C3b) y <b>anticuerpos</b> que la marcan para el fagocito. Importa porque cada falla tiene su germen: sin C6-C8 vuelve la <b>Neisseria</b>, sin anticuerpos el <b>S. aureus</b>, y si la bacteria activa en masa a los linfocitos T llega el <b>choque tóxico</b>. En la imagen verás de izquierda a derecha: bacterias pegadas al epitelio y una biopelícula sobre un catéter, una bacteria encapsulada junto a otra perforada por el complemento, y un fagocito comiéndose cocos cubiertos de anticuerpos y C3b.", "img": "img/15.webp", "mini": "img/mini/15.webp", "ratio": 1.5, "etiquetas": [{"n": "⑰", "t": "Pili y adhesinas", "s": "se pegan al receptor<br>propio de cada tejido", "c": "d", "x": 0.5, "y": 6, "ax": 12.7, "ay": 33, "al": "l"}, {"n": "", "t": "Biopelícula", "s": "matriz sobre plástico:<br>resiste antibióticos", "c": "d", "x": 26, "y": 6, "ax": 26.5, "ay": 33}, {"n": "③", "t": "Cápsula", "s": "polisacáridos:<br>frena la fagocitosis", "c": "d", "x": 44, "y": 6, "ax": 44, "ay": 25}, {"n": "⑪⑯", "t": "Anticuerpo", "s": "opsonina por su Fc;<br>la proteína A lo anula", "c": "i", "x": 66, "y": 6, "ax": 70.5, "ay": 36}, {"n": "⑯", "t": "C3b = opsonina", "s": "marca al coco<br>para el fagocito", "c": "i", "x": 99.5, "y": 6, "ax": 81.5, "ay": 37, "d": "A", "al": "r"}, {"n": "①⑤⑨", "t": "Epitelio", "s": "barrera: ácido<br>y microbiota", "c": "g", "x": 0.5, "y": 91, "ax": 8, "ay": 50, "d": "C", "al": "l"}, {"n": "", "t": "Catéter", "s": "cuerpo extraño:<br>menos inóculo", "c": "g", "x": 28, "y": 91, "ax": 36, "ay": 64, "d": "B"}, {"n": "⑩", "t": "Poro C5b-C9", "s": "lisa a la Neisseria;<br>sin C6-C8 se disemina", "c": "i", "x": 47, "y": 91, "ax": 51.5, "ay": 59}, {"n": "⑪", "t": "Receptores", "s": "unen Fc y C3b:<br>fagocitosis", "c": "i", "x": 67, "y": 91, "ax": 72, "ay": 56}, {"n": "⑮", "t": "Fagosoma", "s": "germen digerido; Mycobacterium<br>impide que se acidifique", "c": "i", "x": 99.5, "y": 91, "ax": 86.6, "ay": 67, "al": "r"}], "diapos": [{"img": "img/15.webp", "ratio": 1.5, "titulo": "Cómo entra la bacteria y cómo cae", "texto": "Se pega con pili ⑰, se esconde en su cápsula ③ y la vence la opsonización: anticuerpo + C3b <span class=\"lt2\">A</span> ⑪⑯, o el poro C5b-C9 ⑩.", "etiquetas": [{"n": "⑰", "t": "Pili y adhesinas", "s": "se pegan al receptor<br>propio de cada tejido", "c": "d", "x": 0.5, "y": 6, "ax": 12.7, "ay": 33, "al": "l"}, {"n": "", "t": "Biopelícula", "s": "matriz sobre plástico:<br>resiste antibióticos", "c": "d", "x": 26, "y": 6, "ax": 26.5, "ay": 33}, {"n": "③", "t": "Cápsula", "s": "polisacáridos:<br>frena la fagocitosis", "c": "d", "x": 44, "y": 6, "ax": 44, "ay": 25}, {"n": "⑪⑯", "t": "Anticuerpo", "s": "opsonina por su Fc;<br>la proteína A lo anula", "c": "i", "x": 66, "y": 6, "ax": 70.5, "ay": 36}, {"n": "⑯", "t": "C3b = opsonina", "s": "marca al coco<br>para el fagocito", "c": "i", "x": 99.5, "y": 6, "ax": 81.5, "ay": 37, "d": "A", "al": "r"}, {"n": "①⑤⑨", "t": "Epitelio", "s": "barrera: ácido<br>y microbiota", "c": "g", "x": 0.5, "y": 91, "ax": 8, "ay": 50, "d": "C", "al": "l"}, {"n": "", "t": "Catéter", "s": "cuerpo extraño:<br>menos inóculo", "c": "g", "x": 28, "y": 91, "ax": 36, "ay": 64, "d": "B"}, {"n": "⑩", "t": "Poro C5b-C9", "s": "lisa a la Neisseria;<br>sin C6-C8 se disemina", "c": "i", "x": 47, "y": 91, "ax": 51.5, "ay": 59}, {"n": "⑪", "t": "Receptores", "s": "unen Fc y C3b:<br>fagocitosis", "c": "i", "x": 67, "y": 91, "ax": 72, "ay": 56}, {"n": "⑮", "t": "Fagosoma", "s": "germen digerido; Mycobacterium<br>impide que se acidifique", "c": "i", "x": 99.5, "y": 91, "ax": 86.6, "ay": 67, "al": "r"}]}, {"img": "img/15_2.webp", "ratio": 1.5, "titulo": "Daño indirecto: el que causa la inmunidad", "texto": "El <mark>superantígeno</mark> activa en bloque al 5-20 % de los LT ⑫ <span class=\"lt2\">C</span>; por <b>mimetismo</b> la anti-proteína M ataca el miocardio ⑭; los complejos inmunes dañan el glomérulo ②.", "etiquetas": [{"n": "⑫", "t": "Presentadora", "s": "HLA-II sin<br>procesar nada", "c": "g", "x": 0.8, "y": 6, "ax": 6, "ay": 30, "al": "l"}, {"n": "⑫", "t": "Superantígeno", "s": "une TCR y HLA<br>por el costado", "c": "d", "x": 28, "y": 6, "ax": 18, "ay": 40}, {"n": "⑭", "t": "S. pyogenes", "s": "proteína M<br>en su superficie", "c": "d", "x": 45, "y": 6, "ax": 41, "ay": 27}, {"n": "⑭", "t": "Anti-proteína M", "s": "anticuerpo contra<br>el estreptococo", "c": "i", "x": 63, "y": 6, "ax": 55, "ay": 38}, {"n": "②", "t": "Complejos inmunes", "s": "se depositan en<br>los capilares", "c": "i", "x": 99.2, "y": 6, "ax": 83, "ay": 42, "al": "r"}, {"n": "⑫", "t": "LT activados en bloque", "s": "5-20 %: tormenta de<br>citoquinas, choque tóxico", "c": "i", "x": 0.8, "y": 92, "ax": 16, "ay": 70, "d": "C", "al": "l"}, {"n": "⑭", "t": "Reacción cruzada", "s": "el anticuerpo se pega<br>a la miosina", "c": "i", "x": 35, "y": 92, "ax": 52, "ay": 63}, {"n": "⑭", "t": "Miocardio inflamado", "s": "fiebre reumática", "c": "g", "x": 57, "y": 92, "ax": 58, "ay": 72}, {"n": "②", "t": "Glomérulo dañado", "s": "glomerulonefritis<br>postestreptocócica", "c": "g", "x": 99.2, "y": 92, "ax": 87, "ay": 70, "al": "r"}]}, {"img": "img/15_3.webp", "ratio": 1.5, "titulo": "La barrera intestinal y la invasión", "texto": "Microbiota e <mark>IgA</mark> secretora impiden la adherencia ⑦; si el antibiótico barre la microbiota, prolifera <b>C. difficile</b> ⑨; <b>Salmonella typhi</b> cruza el epitelio y llega al hígado ⑰.", "etiquetas": [{"n": "⑨", "t": "Microbiota normal", "s": "compite por espacio<br>y nutrientes", "c": "i", "x": 0.8, "y": 6, "ax": 8, "ay": 31, "al": "l"}, {"n": "⑦", "t": "IgA secretora", "s": "impide que se<br>adhieran", "c": "i", "x": 26, "y": 6, "ax": 27, "ay": 36}, {"n": "⑨", "t": "C. difficile", "s": "prolifera sin<br>competencia", "c": "d", "x": 45, "y": 6, "ax": 42, "ay": 33}, {"n": "⑰", "t": "S. typhi", "s": "atraviesa<br>el epitelio", "c": "d", "x": 66, "y": 6, "ax": 76, "ay": 40}, {"n": "⑰", "t": "Hígado", "s": "lo coloniza", "c": "g", "x": 99.2, "y": 6, "ax": 94, "ay": 40, "al": "r"}, {"n": "⑦", "t": "Moco", "s": "con IgA y<br>péptidos", "c": "i", "x": 0.8, "y": 92, "ax": 6, "ay": 44, "al": "l"}, {"n": "⑨", "t": "Toxinas", "s": "dañan y desprenden<br>el epitelio", "c": "d", "x": 26, "y": 92, "ax": 52, "ay": 48}, {"n": "⑰", "t": "Vaso sanguíneo", "s": "llega a la<br>circulación", "c": "d", "x": 56, "y": 92, "ax": 72, "ay": 63}, {"n": "⑰", "t": "Linfático", "s": "y a los<br>ganglios", "c": "d", "x": 82, "y": 92, "ax": 86, "ay": 60}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa del hospedero</b> (complemento, anticuerpos, fagocito), <b class=\"d\">rojo = armas del germen</b> (adherencia, cápsula, biopelícula, evasión), gris = estructuras de referencia.", "<b>Izquierda:</b> los <mark>pili y adhesinas</mark> explican el tropismo: cada germen se pega solo donde está su receptor. Sobre un catéter, la <b>biopelícula</b> hace a la bacteria más resistente a los antibióticos, y con un cuerpo extraño bastan muchas menos bacterias para un absceso <span class=\"lt2\">B</span>.", "<b>Centro:</b> la <mark>cápsula</mark> resiste la fagocitosis (<b>S. pneumoniae</b>, <b>H. influenzae</b>); <span class=\"cx\">en cambio</span> la <b>Neisseria</b> cae por el poro del complemento, <span class=\"cx\">por eso</span> sin C6-C8 se disemina.", "<b>Derecha:</b> el C3b multiplica la fagocitosis y el anticuerpo también <span class=\"lt2\">A</span>; <b>S. aureus</b> necesita las dos opsoninas, <b>S. epidermidis</b> solo el complemento."], "recordar": "Triángulo hospedero-patógeno-ambiente. Germen: <b>pegarse → invadir → esconderse</b>. Hospedero: <b>barrera → complemento → anticuerpo → fagocito</b>. Falla del complemento terminal = Neisseria; superantígeno = choque tóxico."}, "numeros": [{"l": "A", "html": "<b>Opsonización</b>: el C3b aumenta la fagocitosis hasta <b class=\"a\">1000 veces</b>; los anticuerpos solos, hasta <b class=\"a\">100 veces</b>.", "rango": null}, {"l": "B", "html": "<b>Inóculo de S. aureus</b> para un absceso cutáneo: <b class=\"n\">1 millón</b> en tejido sano, apenas <b class=\"a\">1000</b> con un cuerpo extraño implantado.", "rango": null}, {"l": "C", "html": "<b>Ácido gástrico</b>: con acidez normal se necesitan <b class=\"n\">más de 1 millón</b> de <b>V. cholerae</b>; con aclorhidria bastan <b class=\"a\">unos cientos</b>. Piel: pH <b class=\"n\">5 a 6</b>. <b>Superantígenos</b>: activan del <b class=\"a\">5 % al 20 %</b> de los LT; <b>sepsis</b>: mortalidad del <b class=\"a\">20 % al 50 %</b>.", "rango": {"min": 4, "max": 8, "unidad": "pH de la piel", "zonas": [[5, 6, "n"]], "marcas": [5, 6]}}], "escalas": [], "cadena": {"titulo": "De la adherencia a la sepsis", "subtitulo": "estímulo → armas del germen → defensa del hospedero → resultado → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Encuentro", "m": "<b>Qué pasa:</b> el germen llega a un hospedero (inmunocompetente o no) en un microambiente dado; la <mark>microbiota</mark> compite con él y el ácido gástrico o el pH de la piel lo frenan.", "pr": "solo enferma si gana el triángulo: primario en cualquiera, oportunista en el debilitado.", "pr_tit": "Produce:", "rf": "Preguntas ①④⑤⑨ · punto <span class=\"lt2\">C</span>", "color": "p1"}, {"t": "2. Adherencia e invasión", "m": "<b>Por qué:</b> las <mark>adhesinas y pili</mark> se unen a receptores propios de cada tejido; algunas bacterias no cruzan el epitelio (<b>V. cholerae</b>), otras lo atraviesan y llegan a la sangre (<b>S. typhi</b>). Sobre plástico forman <b>biopelícula</b>.", "pr": "colonización del tejido blanco o infección crónica asociada a polímeros.", "pr_tit": "Produce:", "rf": "Preguntas ⑰ · punto <span class=\"lt2\">B</span>", "color": "p2"}, {"t": "3. Barreras y complemento", "m": "<b>Qué produce:</b> péptidos antimicrobianos (lisozima, lactoferrina, defensinas, LL-37), IgA en mucosas y el <mark>complemento</mark>: el C3b opsoniza y el poro C5b-C9 lisa a la <b>Neisseria</b>.", "pr": "germen marcado para el fagocito o perforado.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑦⑩ · punto <span class=\"lt2\">A</span>", "color": "p3"}, {"t": "4. Anticuerpos y fagocito", "m": "<b>Por qué:</b> la IgM primaria y <span class=\"cx\">luego</span> la IgG opsonizan; el fagocito une Fc y C3b. Contra intracelulares (TB, lepra, <b>Brucella</b>, <b>Listeria</b>) los <mark>LT activan al macrófago</mark>.", "pr": "fagocitosis y destrucción; memoria contra la reinfección.", "pr_tit": "Produce:", "rf": "Preguntas ⑯ · punto <span class=\"lt2\">A</span>", "color": "p4"}, {"t": "5. Evasión", "m": "<b>Qué pasa:</b> la <mark>cápsula</mark> resiste al fagocito, el ácido siálico frena la vía alterna, la <b>proteína A</b> atrapa el Fc, <b>Legionella</b> impide la fusión lisosomal, <b>Mycobacterium</b> no deja acidificar y los <b>superantígenos</b> encienden en masa a los LT.", "pr": "el germen persiste o desencadena una tormenta de citoquinas.", "pr_tit": "Produce:", "rf": "Preguntas ③⑪⑫⑮", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Daño directo</b> (toxinas) o <b>indirecto</b> (fiebre reumática por mimetismo de la proteína M; lepra según Th1/Th2). Diseminación → <mark>sepsis</mark>: inflamación sistémica, procoagulación y falla de órganos.", "pr": "choque tóxico, sepsis (20-50 % de mortalidad), cardiopatía reumática.", "pr_tit": "Produce:", "rf": "Preguntas ②⑬⑭", "color": "p4"}], "extra": [{"html": "🧬 <b>Lepra, el espejo del Th1/Th2:</b> la forma <mark>tuberculoide</mark> (Th1) tiene lepromina positiva, granulomas y pocos bacilos; la <mark>lepromatosa</mark> (Th2, anergia, LT CD8) tiene lepromina negativa y macrófagos repletos. El daño neural es por desmielinización de las células de Schwann; el eritema nodoso, por complejos inmunes.", "k": ""}, {"html": "💊 <b>Antibióticos de amplio espectro:</b> barren la microbiota y <span class=\"cx\">además</span> deprimen la defensa (vancomicina y metronidazol bajan el REG3-γ, la ampicilina la IgG, la tetraciclina la secreción de Ig): de ahí la diarrea por <b>C. difficile</b>. Las <b>rickettsias</b>, intracelulares obligadas, escapan casi por completo a anticuerpos y linfocitos.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Del foco a la sepsis", "pasos": ["bacteria adherida y multiplicándose", "invasión del tejido y de la sangre", "liberación masiva de TNF (<b>P. aeruginosa</b>) o superantígenos", "inflamación sistémica y procoagulación", "<b>sepsis</b>: disfunción de varios órganos, 20-50 % de mortalidad"]}], "html": "", "fuente": "Fuente: tu teoría — clase 19 (patogenicidad, virulencia, zoonosis, microbiota, ambiente, péptidos antimicrobianos, emergentes) y clase 20 (virulencia, complemento y opsonización, evasión, lepra, fiebre reumática, rickettsiosis, sepsis)."}, "preguntas": [{"n": 1, "id": "IN9-001", "c": "g", "tema": "Hospedero, patógeno y patogenicidad", "pregunta": "¿Cuál de los siguientes es un patógeno OPORTUNISTA, es decir, que solo daña a un hospedero inmunocomprometido?", "opciones": ["a. Virus de la rabia", "b. Virus de la viruela", "c. Pneumocystis jiroveci", "d. Streptococcus pyogenes", "e. Salmonella typhi"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Pneumocystis jiroveci: solo enferma al inmunocomprometido (igual que Cryptococcus neoformans).", "sin_banco": true, "ok": "", "x": "El patógeno <mark>primario</mark> enferma aun a un hospedero sano, como la rabia o la viruela. <span class=\"cx\">En cambio</span> el <mark>oportunista</mark> necesita un terreno debilitado (VIH, quimioterapia, esteroides). <span class=\"cx\">Por eso</span>, si aparece <b>Pneumocystis</b> sin causa conocida, <span class=\"res\">hay que buscar el VIH</span>.", "truco": "Oportunista = «aprovecha la oportunidad» de unas defensas caídas.", "veces": 0}, {"n": 2, "id": "IN9-002", "c": "d", "tema": "Hospedero, patógeno y patogenicidad", "pregunta": "¿Qué diferencia la patogenicidad «directa» de la «indirecta»? Dé un ejemplo de cada una.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Directa: daño del propio germen por exotoxinas, endotoxinas o efecto citotóxico (difteria, cólera). Indirecta: daño por la respuesta inmune del hospedero —complejos inmunes, autoanticuerpos, reacción celular— (glomerulonefritis postestreptocócica, fiebre reumática, tuberculosis).", "sin_banco": true, "ok": "", "x": "En la directa el culpable es el <mark>microbio</mark> y sus toxinas. En la indirecta el culpable es la <mark>propia defensa</mark>, <span class=\"cx\">porque</span> forma complejos inmunes o ataca lo propio por error. <span class=\"cx\">Así que</span> <span class=\"res\">la tuberculosis y la fiebre reumática dañan sobre todo por la respuesta inmune</span>.", "truco": "Directa = toxina; indirecta = «fuego amigo».", "veces": 0}, {"n": 3, "id": "IN9-003", "c": "d", "tema": "Virulencia", "pregunta": "Una cápsula bacteriana rica en polisacáridos es un factor de virulencia que sirve principalmente para:", "opciones": ["a. Evitar la activación del complemento por la vía alterna", "b. Resistir la fagocitosis", "c. Adherirse al epitelio", "d. Cambiar la antigenicidad para escapar de los anticuerpos", "e. Secuestrar el hierro del hospedero"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Resistir la fagocitosis.", "sin_banco": true, "ok": "", "x": "Es el halo claro de la bacteria del centro de la imagen: la <mark>cápsula</mark> de polisacáridos hace resbaladizo al germen y el fagocito no lo agarra. El ácido siálico frena el complemento y los pili sirven para pegarse. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN9-004", "c": "g", "tema": "Zoonosis y antroponosis", "pregunta": "¿Por qué las zoonosis (rabia, brucelosis, tularemia) suelen ser más letales que las antroponosis (sarampión, polio)?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque el contacto humano con los agentes zoonóticos solo tiene unos 12.000 años (desde la domesticación), tiempo insuficiente para seleccionar defensas eficaces; las antroponosis conviven con el hombre desde hace milenios y seleccionaron genes de respuesta inmune.", "sin_banco": true, "ok": "", "x": "La evolución necesita tiempo: con las antroponosis, sin reservorio animal, la especie humana tuvo <mark>milenios</mark> para seleccionar genes de defensa. <span class=\"cx\">En cambio</span> con las zoonosis solo hubo <span class=\"res\">unos 12.000 años</span>, <span class=\"cx\">así que</span> la respuesta es todavía torpe.", "truco": "Zoonosis = «visitante nuevo»: el cuerpo aún no lo conoce.", "veces": 0}, {"n": 5, "id": "IN9-005", "c": "i", "tema": "Ambiente y microambiente", "pregunta": "Correlación: un paciente gastrectomizado (aclorhidria) bebe agua contaminada con apenas unos cientos de Vibrio cholerae y desarrolla cólera, mientras su familia no enferma. ¿Qué lo explica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La acidez gástrica normal es bactericida y eleva el inóculo necesario a más de un millón de vibriones; sin ácido bastan unos pocos cientos.", "sin_banco": true, "ok": "", "x": "Es el punto Ⓒ: el ácido gástrico es parte del <mark>microambiente</mark>. Con acidez normal se necesitan <span class=\"res\">más de un millón</span> de vibriones; sin ácido, unos cientos llegan vivos al intestino y lo enferman.", "truco": "", "veces": 0}, {"n": 6, "id": "IN9-006", "c": "i", "tema": "Barreras naturales", "pregunta": "Sobre los péptidos antimicrobianos de las barreras naturales, todo es correcto EXCEPTO:", "opciones": ["a. La lactoferrina impide el uso microbiano del hierro", "b. La lisozima fragmenta los peptidoglucanos bacterianos", "c. Las catelicidinas generan en el humano el péptido LL-37", "d. Las catepsinas estimulan la producción de IL-6, IL-17 e IL-23", "e. Las defensinas se almacenan en gránulos de neutrófilos y células de Paneth"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Es falso: las catepsinas son proteasas lisosomales que INHIBEN la IL-6, la IL-17 y la IL-23.", "sin_banco": true, "ok": "", "x": "Cada péptido tiene su oficio: la lactoferrina <mark>secuestra hierro</mark>, la lisozima rompe la pared, la catelicidina da el LL-37 (sudor, moco, leche) y las defensinas matan y atraen células innatas. <span class=\"cx\">En cambio</span> las <b>catepsinas</b> <span class=\"res\">frenan</span> citoquinas proinflamatorias, no las estimulan.", "truco": "Catepsina = «calma»: inhibe IL-6, IL-17 e IL-23.", "veces": 0}, {"n": 7, "id": "IN9-007", "c": "i", "tema": "Inmunidad adquirida", "pregunta": "¿Qué inmunoglobulina protege la superficie de las mucosas y las secreciones impidiendo la adherencia de microorganismos y toxinas?", "opciones": ["a. IgM", "b. IgG", "c. IgE", "d. IgD", "e. IgA"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. IgA, que actúa en las mucosas y secreciones («fuera del organismo»).", "sin_banco": true, "ok": "", "x": "Cada clase cuida un compartimento: la <mark>IgM</mark> el intravascular (complemento, aglutinación), la <mark>IgG</mark> los tejidos (opsoniza y neutraliza) y la <mark>IgA</mark> las mucosas. <span class=\"cx\">Por eso</span> <span class=\"res\">la IgA impide que el germen se pegue</span>, antes de que entre.", "truco": "M = «Mangueras» (vasos), G = «Granja» (tejidos), A = «Afuera» (mucosas).", "veces": 0}, {"n": 8, "id": "IN9-008", "c": "g", "tema": "Emergentes y reemergentes", "pregunta": "La tuberculosis multirresistente es un ejemplo de enfermedad:", "opciones": ["a. Emergente", "b. Reemergente", "c. Zoonótica", "d. Oportunista", "e. Adquirida en el hospital"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Reemergente: estaba controlada y reaparece por resistencia a los antibióticos.", "sin_banco": true, "ok": "", "x": "La <mark>emergente</mark> es un germen recién identificado frente al que la población responde mal (el VIH). La <mark>reemergente</mark> ya estaba controlada y vuelve, <span class=\"cx\">porque</span> el microbio se hizo resistente al antibiótico o el vector al insecticida. <span class=\"cx\">Así que</span> <span class=\"res\">la TB multirresistente es reemergente</span>.", "truco": "Re-emergente = «regresa»; emergente = «recién llegado».", "veces": 0}, {"n": 9, "id": "IN9-009", "c": "d", "tema": "Microbiota y antibióticos", "pregunta": "Correlación: un paciente hospitalizado que recibió antibióticos de amplio espectro durante dos semanas presenta diarrea intensa por Clostridium difficile. ¿Qué mecanismo explica esta infección?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El antibiótico eliminó la microbiota normal que compite por espacio y nutrientes, y además deprimió la defensa (menos REG3-γ, IgG o secreción de Ig según el fármaco); así proliferó el oportunista C. difficile.", "sin_banco": true, "ok": "", "x": "La <mark>microbiota</mark> no es pasiva: compite con los patógenos y produce sustancias contra ellos. Al barrerla con un antibiótico de amplio espectro, el nicho queda libre; <span class=\"cx\">además</span> vancomicina y metronidazol bajan el péptido REG3-γ. <span class=\"cx\">Por eso</span> <span class=\"res\">aparece el oportunista <b>C. difficile</span></b>.", "truco": "Antibiótico amplio = «desalojo»: entra el okupa C. difficile.", "veces": 0}, {"n": 10, "id": "IN9-010", "c": "i", "tema": "Defensa: complemento", "pregunta": "Un paciente con deficiencia de los factores terminales C6, C7 o C8 del complemento es especialmente susceptible a infecciones diseminadas por:", "opciones": ["a. Neisseria meningitidis y N. gonorrhoeae", "b. Staphylococcus aureus", "c. Mycobacterium tuberculosis", "d. Candida albicans", "e. Pneumocystis jiroveci"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Neisseria meningitidis y N. gonorrhoeae, porque sin C6-C8 no se forma el complejo de ataque que las lisa.", "sin_banco": true, "ok": "", "x": "Mira la bacteria perforada del centro: el <mark>poro C5b-C9</mark> lisa a la <b>Neisseria</b> aun sin anticuerpos. Si falta C6, C7 o C8, el poro no se arma y el meningococo se disemina. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN9-011", "c": "d", "tema": "Evasión bacteriana", "pregunta": "La proteína A de Staphylococcus aureus evade la respuesta inmune porque:", "opciones": ["a. Destruye el H₂O₂ generado por el fagocito", "b. Activa de forma inespecífica al 5-20 % de los linfocitos T", "c. Se une al segmento constante (Fc) de las inmunoglobulinas e impide su unión a los receptores Fc del fagocito", "d. Bloquea el citoesqueleto del macrófago", "e. Impide la fusión del lisosoma con el fagosoma"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Se pega al segmento constante de las Ig y anula la opsonización por anticuerpos.", "sin_banco": true, "ok": "", "x": "En el fagocito de la derecha los anticuerpos unen el coco al receptor por su <mark>Fc</mark>. La proteína A de <b>S. aureus</b> atrapa justo ese Fc, <span class=\"cx\">así que</span> el anticuerpo ya no sirve de puente. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN9-012", "c": "d", "tema": "Evasión bacteriana", "pregunta": "¿Qué es un superantígeno bacteriano, qué proporción de linfocitos T activa y qué cuadro puede producir?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Toxina que une lateralmente el TCR y la molécula HLA sin procesamiento antigénico y activa de forma inespecífica al 5-20 % de los linfocitos T; la liberación masiva de citoquinas causa choque tóxico (S. aureus, S. pyogenes, Mycoplasma arthritidis).", "sin_banco": true, "ok": "", "x": "Un antígeno normal enciende muy pocos clones, <span class=\"cx\">porque</span> necesita ser procesado y encajar en el TCR. El <mark>superantígeno</mark> se pega por fuera del surco y enciende de golpe <span class=\"res\">del 5 % al 20 %</span> de los LT. <span class=\"cx\">Así que</span> la tormenta de citoquinas lleva al <span class=\"res\">choque tóxico</span>.", "truco": "Súper-antígeno = «llave maestra» que abre miles de puertas.", "veces": 0}, {"n": 13, "id": "IN9-013", "c": "d", "tema": "Lepra", "pregunta": "Respecto a la forma LEPROMATOSA de la lepra, es CIERTO:", "opciones": ["a. La prueba de lepromina es positiva", "b. Forma granulomas bien organizados", "c. Predomina una respuesta Th1 eficaz", "d. Hay anergia celular con predominio Th2, LT CD8 y bacilos abundantes", "e. Las lesiones son localizadas y con escasos bacilos"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Hay anergia celular específica, predominio Th2 y de LT CD8, y macrófagos repletos de bacilos.", "sin_banco": true, "ok": "", "x": "La lepra es el mejor ejemplo de que <mark>el tipo de respuesta</mark> decide la clínica. En la <b>tuberculoide</b> manda Th1: lepromina positiva, granulomas y pocos bacilos. <span class=\"cx\">En cambio</span> en la <b>lepromatosa</b> manda Th2, la lepromina es negativa y <span class=\"res\">los bacilos llegan hasta 10⁶/mL de sangre</span>.", "truco": "Lepromatosa = «llena de bacilos» y «lepromina limpia» (negativa).", "veces": 0}, {"n": 14, "id": "IN9-014", "c": "d", "tema": "Fiebre reumática", "pregunta": "¿Cómo se produce la fiebre reumática tras una faringitis por Streptococcus pyogenes?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Por mimetismo molecular: los anticuerpos contra la proteína M del estreptococo reaccionan en forma cruzada con la miosina del miocardio y dañan el corazón.", "sin_banco": true, "ok": "", "x": "La <mark>proteína M</mark> del germen se parece a la <b>miosina</b> cardíaca. <span class=\"cx\">Por eso</span> los anticuerpos que el cuerpo fabrica contra el estreptococo también se pegan al miocardio. <span class=\"cx\">Así que</span> <span class=\"res\">tratar a tiempo la faringitis estreptocócica previene la cardiopatía reumática</span>.", "truco": "Proteína M ≈ Miosina: «M de mismo disfraz».", "veces": 0}, {"n": 15, "id": "IN9-015", "c": "d", "tema": "Evasión bacteriana", "pregunta": "¿Qué bacteria evita la acidificación del fagosoma excluyendo las ATPasas de protones de su membrana?", "opciones": ["a. Legionella pneumophila", "b. Yersinia spp.", "c. Shigella", "d. Pseudomonas aeruginosa", "e. Mycobacterium spp."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Mycobacterium spp.", "sin_banco": true, "ok": "", "x": "Cada germen sabotea un paso distinto: <b>Legionella</b> impide la <mark>fusión del lisosoma</mark>, <b>Yersinia</b> (YopH) bloquea el citoesqueleto, <b>Shigella</b> induce apoptosis del macrófago y <b>P. aeruginosa</b> cambia su LPS para el TLR4. <span class=\"cx\">En cambio</span> <span class=\"res\">las micobacterias impiden que el fagosoma se acidifique</span>.", "truco": "Mycobacterium = «sin ácido»: saca las bombas de protones.", "veces": 0}, {"n": 16, "id": "IN9-016", "c": "i", "tema": "Defensa: opsonización", "pregunta": "¿Por qué la fagocitosis de S. aureus requiere dos opsoninas y la de S. epidermidis solo una?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "S. aureus necesita la acción conjunta de anticuerpos y complemento para ser fagocitado; S. epidermidis se fagocita con el complemento solo, aun sin anticuerpos.", "sin_banco": true, "ok": "", "x": "Los cocos de la derecha llevan las dos opsoninas: <mark>anticuerpo y C3b</mark> (punto Ⓐ). <b>S. aureus</b> las necesita juntas; <b>S. epidermidis</b> se fagocita con el complemento solo. <span class=\"cx\">Por eso</span> <span class=\"res\">un <b>S. aureus</b> recurrente sugiere falla humoral</span>.", "truco": "", "veces": 0}, {"n": 17, "id": "IN9-017", "c": "d", "tema": "Virulencia bacteriana", "pregunta": "¿Qué bacteria traspasa el epitelio intestinal, invade los tejidos, alcanza la circulación y los linfáticos y puede colonizar el hígado?", "opciones": ["a. Vibrio cholerae", "b. Streptococcus mutans", "c. Salmonella typhi", "d. Shigella disenteriae", "e. Staphylococcus epidermidis"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Salmonella typhi: es el ejemplo de invasión profunda.", "sin_banco": true, "ok": "", "x": "En el epitelio de la izquierda las bacterias solo se pegan (<mark>adherencia</mark>), como <b>V. cholerae</b>, que no cruza. <b>S. typhi</b> <span class=\"cx\">en cambio</span> atraviesa el epitelio y llega a la sangre y al hígado. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "Arma del germen", "Ejemplo", "Efecto"], "filas": [["Cápsula", "Polisacáridos", "S. pneumoniae, H. influenzae", "Frena la fagocitosis"], ["Ácido siálico", "Superficie sin activar", "Neisseria", "Frena la vía alterna"], ["Proteína A", "Atrapa el Fc", "S. aureus", "Anula la opsonización"], ["Biopelícula", "Matriz sobre plástico", "S. epidermidis, P. aeruginosa", "Resiste al antibiótico"], ["Superantígeno", "Une TCR y HLA por fuera", "S. aureus, S. pyogenes", "Choque tóxico (5-20 % de LT)"], ["🔑 Para diferenciar", "Cápsula = fagocito", "Siálico = complemento", "Proteína A = anticuerpo"]]}, "fuente": "Fuente: tu teoría — clase 19 (hospedero, patógeno y medio ambiente) y clase 20 (defensa inmune contra infecciones por bacterias), Rojas 17.ª ed."}, {"n": 16, "slug": "Respuesta_inmune_en_tuberculosis", "titulo": "Respuesta inmune en tuberculosis", "subtitulo": "del macrófago alveolar al granuloma: un equilibrio que contiene sin erradicar", "grupo": "g9", "lema": "La idea: <b>Mycobacterium tuberculosis</b> entra al alvéolo y lo come un <mark>macrófago</mark>, pero el bacilo convierte el fagosoma en su casa (no deja que se acidifique ni que se fusione el lisosoma). Semanas después la célula dendrítica presenta sus antígenos a los <mark>LT CD4 Th1</mark>, que vuelven con <b>IFNγ</b>; en el humano hace falta además el <b>TNF</b> para que el macrófago lo destruya. Lo que no se destruye queda encerrado en un <mark>granuloma</mark> y en latencia. Importa porque solo enferma el <b>5 %</b> de los infectados: cuando caen los CD4 (VIH) o el TNF (anti-TNF, esteroides), la latencia se rompe. En la imagen verás de izquierda a derecha: el macrófago alveolar con bacilos en un fagosoma sin lisosomas, la célula dendrítica y el linfocito T que activan a un macrófago, y el corte de un granuloma caseoso.", "img": "img/16.webp", "mini": "img/mini/16.webp", "ratio": 1.5, "etiquetas": [{"n": "③", "t": "Fagosoma", "s": "bacilos sin ácido<br>ni lisosomas", "c": "d", "x": 0.5, "y": 6, "ax": 13.7, "ay": 50, "d": "C", "al": "l"}, {"n": "⑤", "t": "Célula dendrítica", "s": "llega al ganglio<br>semanas tarde", "c": "i", "x": 24, "y": 6, "ax": 30, "ay": 40}, {"n": "①②", "t": "LT CD4 Th1", "s": "contiene la latencia;<br>el VIH lo destruye", "c": "i", "x": 41, "y": 6, "ax": 39.4, "ay": 43, "d": "A"}, {"n": "④", "t": "Células epitelioides", "s": "núcleo del granuloma;<br>ESAT-6 las estimula", "c": "i", "x": 60, "y": 6, "ax": 78, "ay": 37}, {"n": "④", "t": "Caseum", "s": "hipoxia: bacilos<br>vivos en anaerobiosis", "c": "d", "x": 77.5, "y": 6, "ax": 83, "ay": 46, "d": "B"}, {"n": "④", "t": "Fibrosis", "s": "halo<br>calcificable", "c": "g", "x": 99.5, "y": 6, "ax": 86, "ay": 25, "al": "r"}, {"n": "③⑤", "t": "Macrófago alveolar", "s": "lo fagocita, pero<br>se vuelve su refugio", "c": "d", "x": 0.5, "y": 91, "ax": 19, "ay": 58, "al": "l"}, {"n": "①②", "t": "IFNγ + TNF", "s": "juntos activan<br>al macrófago humano", "c": "i", "x": 30, "y": 91, "ax": 45, "ay": 48}, {"n": "①", "t": "Macrófago activado", "s": "lisosomas fusionados:<br>destruye bacilos", "c": "i", "x": 50, "y": 91, "ax": 56, "ay": 62}, {"n": "④⑧", "t": "Linfocitos", "s": "LT CD4 y luego CD8<br>rodean el centro", "c": "i", "x": 72, "y": 91, "ax": 73.6, "ay": 59}, {"n": "", "t": "Célula gigante", "s": "macrófagos fusionados<br>en el granuloma", "c": "g", "x": 99.5, "y": 91, "ax": 92.4, "ay": 50, "al": "r"}], "diapos": [{"img": "img/16.webp", "ratio": 1.5, "titulo": "Del macrófago alveolar al granuloma", "texto": "El bacilo vive en un fagosoma que no se acidifica ③; el Th1 lo frena con <mark>IFNγ + TNF</mark> juntos ① y el granuloma lo encierra, con bacilos vivos en el caseum <span class=\"lt2\">B</span> ④.", "etiquetas": [{"n": "③", "t": "Fagosoma", "s": "bacilos sin ácido<br>ni lisosomas", "c": "d", "x": 0.5, "y": 6, "ax": 13.7, "ay": 50, "d": "C", "al": "l"}, {"n": "⑤", "t": "Célula dendrítica", "s": "llega al ganglio<br>semanas tarde", "c": "i", "x": 24, "y": 6, "ax": 30, "ay": 40}, {"n": "①②", "t": "LT CD4 Th1", "s": "contiene la latencia;<br>el VIH lo destruye", "c": "i", "x": 41, "y": 6, "ax": 39.4, "ay": 43, "d": "A"}, {"n": "④", "t": "Células epitelioides", "s": "núcleo del granuloma;<br>ESAT-6 las estimula", "c": "i", "x": 60, "y": 6, "ax": 78, "ay": 37}, {"n": "④", "t": "Caseum", "s": "hipoxia: bacilos<br>vivos en anaerobiosis", "c": "d", "x": 77.5, "y": 6, "ax": 83, "ay": 46, "d": "B"}, {"n": "④", "t": "Fibrosis", "s": "halo<br>calcificable", "c": "g", "x": 99.5, "y": 6, "ax": 86, "ay": 25, "al": "r"}, {"n": "③⑤", "t": "Macrófago alveolar", "s": "lo fagocita, pero<br>se vuelve su refugio", "c": "d", "x": 0.5, "y": 91, "ax": 19, "ay": 58, "al": "l"}, {"n": "①②", "t": "IFNγ + TNF", "s": "juntos activan<br>al macrófago humano", "c": "i", "x": 30, "y": 91, "ax": 45, "ay": 48}, {"n": "①", "t": "Macrófago activado", "s": "lisosomas fusionados:<br>destruye bacilos", "c": "i", "x": 50, "y": 91, "ax": 56, "ay": 62}, {"n": "④⑧", "t": "Linfocitos", "s": "LT CD4 y luego CD8<br>rodean el centro", "c": "i", "x": 72, "y": 91, "ax": 73.6, "ay": 59}, {"n": "", "t": "Célula gigante", "s": "macrófagos fusionados<br>en el granuloma", "c": "g", "x": 99.5, "y": 91, "ax": 92.4, "ay": 50, "al": "r"}]}, {"img": "img/16_2.webp", "ratio": 1.5, "titulo": "Infección, latencia y reactivación", "texto": "Solo el ~5 % enferma <span class=\"lt2\">A</span> ⑧: el resto queda latente en un granuloma. Si cae el TNF (anti-TNF) o los LT CD4 (sida), el granuloma <span class=\"res\">se rompe</span> y el bacilo se disemina ②.", "etiquetas": [{"n": "⑧", "t": "Bacilos inhalados", "s": "llegan al alvéolo", "c": "d", "x": 0.8, "y": 6, "ax": 10, "ay": 28, "al": "l"}, {"n": "④", "t": "Cápsula fibrosa", "s": "calcificada:<br>encierra al bacilo", "c": "i", "x": 38, "y": 6, "ax": 49, "ay": 31}, {"n": "②", "t": "Bronquio", "s": "la caverna se<br>abre a la vía aérea", "c": "g", "x": 99.2, "y": 6, "ax": 89, "ay": 36, "al": "r"}, {"n": "②⑧", "t": "Pared rota", "s": "reactivación", "c": "d", "x": 71, "y": 6, "ax": 79, "ay": 33}, {"n": "⑧", "t": "Macrófago alveolar", "s": "fagocita<br>al bacilo", "c": "i", "x": 0.8, "y": 92, "ax": 20, "ay": 47, "al": "l"}, {"n": "④", "t": "Caseum latente", "s": "bacilos dormidos<br>por décadas", "c": "d", "x": 50, "y": 92, "ax": 49, "ay": 48, "d": "B"}, {"n": "④", "t": "Anillo de linfocitos", "s": "contiene la<br>infección", "c": "i", "x": 31, "y": 92, "ax": 41, "ay": 58}, {"n": "②", "t": "Pocos linfocitos", "s": "sin TNF ni LT CD4,<br>el control se pierde", "c": "i", "x": 70, "y": 92, "ax": 74, "ay": 56}, {"n": "⑧", "t": "Bacilos diseminados", "s": "enfermedad activa", "c": "d", "x": 99.2, "y": 92, "ax": 85, "ay": 53, "d": "A", "al": "r"}]}, {"img": "img/16_3.webp", "ratio": 1.5, "titulo": "Tuberculina y la decisión del macrófago", "texto": "La tuberculina mide <mark>hipersensibilidad retardada</mark>, no protección ⑥. SP110 decide: necrosis <span class=\"res\">libera bacilos vivos</span>, apoptosis libera antígenos ⑤.", "etiquetas": [{"n": "⑥", "t": "Induración", "s": "tuberculina +:<br>no es protección", "c": "i", "x": 0.8, "y": 6, "ax": 21, "ay": 24, "al": "l"}, {"n": "⑤", "t": "Necrosis", "s": "el macrófago<br>revienta", "c": "d", "x": 40, "y": 6, "ax": 45, "ay": 34}, {"n": "⑤", "t": "Bacilos vivos", "s": "salen e infectan<br>a otras células", "c": "d", "x": 62, "y": 6, "ax": 62, "ay": 32}, {"n": "⑤", "t": "Célula dendrítica", "s": "toma los antígenos<br>y los presenta", "c": "i", "x": 99.2, "y": 6, "ax": 92, "ay": 30, "al": "r"}, {"n": "⑥", "t": "Linfocitos T", "s": "hipersensibilidad<br>retardada", "c": "i", "x": 0.8, "y": 92, "ax": 10, "ay": 50, "al": "l"}, {"n": "⑥", "t": "Macrófagos", "s": "reclutados alrededor<br>de los vasos", "c": "i", "x": 23, "y": 92, "ax": 15, "ay": 45}, {"n": "⑤", "t": "Cuerpos apoptóticos", "s": "SP110 elige apoptosis:<br>bacilos fragmentados", "c": "i", "x": 70, "y": 92, "ax": 73, "ay": 55}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa del hospedero</b> (dendrítica, Th1, macrófago activado, granuloma), <b class=\"d\">rojo = el bacilo y sus trucos</b> (fagosoma sin ácido, caseum), gris = estructuras de referencia.", "<b>Izquierda:</b> el bacilo forma la cubierta <mark>TACO</mark>, produce lipoarabinomanán y P13P e impide la acidificación; <span class=\"cx\">por eso</span> los lisosomas quedan aparte y el macrófago se vuelve su refugio.", "<b>Centro:</b> la célula dendrítica tarda <mark>semanas</mark> en llegar al ganglio (en otras infecciones, una). El Th1 activa al macrófago con IFNγ + TNF <span class=\"lt2\">A</span>.", "<b>Derecha:</b> el granuloma humano tiene, de adentro afuera, células epitelioides y gigantes, LT CD4, LT CD8 y fibroblastos; el centro se caseifica y el bacilo sobrevive en anaerobiosis <span class=\"lt2\">B</span>."], "recordar": "Macrófago-refugio → dendrítica lenta → Th1 con <b>IFNγ + TNF</b> → granuloma → <b>latencia</b>. Se reactiva con VIH, anti-TNF, esteroides, alcohol o vejez. Tuberculina + = hipersensibilidad, no protección."}, "numeros": [{"l": "A", "html": "<b>Enfermedad activa</b>: solo el <b class=\"a\">5 %</b> de unos <b class=\"n\">2 millardos</b> de infectados; el <b class=\"a\">11 %</b> de las muertes por sida es TB reactivada.", "rango": null}, {"l": "B", "html": "<b>Granuloma</b>: los bacilos del caseum sobreviven <b class=\"a\">décadas</b> en metabolismo anaerobio.", "rango": null}, {"l": "C", "html": "<b>Diagnóstico</b>: el directo necesita <b class=\"a\">más de 10 000 bacilos/mL</b>; el MTB/RIF es positivo en el <b class=\"n\">98 %</b> de esputos positivos y el <b class=\"n\">72 %</b> de los negativos al directo. <b>Resistencia</b>: hasta el <b class=\"a\">25 %</b> de los pacientes en algunos países; tratamiento <b class=\"a\">hasta 1000 veces</b> más costoso.", "rango": {"min": 0, "max": 20000, "unidad": "bacilos/mL", "zonas": [[0, 10000, "m", "Directo negativo"], [10000, 20000, "a", "Directo +"]], "marcas": [10000]}}], "escalas": [], "cadena": {"titulo": "Del bacilo inhalado a la latencia", "subtitulo": "estímulo → macrófago → células dendríticas y Th1 → granuloma → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Inhalación", "m": "<b>Qué pasa:</b> Mtb llega al alvéolo; su capa cerosa (lipoarabinomanán, ácido micólico) es reconocida por <mark>TLR2 y TLR4</mark>. Neutrófilos, NK (primer IFNγ) y LT γδ (glucolípidos en CD1) responden <span class=\"cx\">primero</span>.", "pr": "el macrófago alveolar fagocita al bacilo.", "pr_tit": "Produce:", "rf": "Preguntas ⑧", "color": "p1"}, {"t": "2. Macrófago-refugio", "m": "<b>Por qué:</b> cubierta <b>TACO</b>, LAM y <b>P13P</b>, fagosoma sin ácido (menos TNF, IL-1 e iNOS; más IL-10 y TGF-β) y PGE2. <mark>SP110</mark> decide: necrosis (bacilos vivos) o apoptosis (antígenos). La vitamina D activa la catelicidina (LL-37).", "pr": "el bacilo se multiplica dentro de la célula que debía matarlo.", "pr_tit": "Produce:", "rf": "Preguntas ③⑤", "color": "p2"}, {"t": "3. Dendrítica lenta y Th1", "m": "<b>Qué produce:</b> la DC llega al ganglio mediastinal con <mark>semanas de retraso</mark>; allí activa a los LT CD4, que vuelven al pulmón con <b>IFNγ</b>. Th17 atraen neutrófilos, Th2 ayudan a los LB, LT CD8 sueltan granulisinas.", "pr": "IFNγ + TNF activan al macrófago y destruyen bacilos.", "pr_tit": "Produce:", "rf": "Preguntas ① · punto <span class=\"lt2\">A</span>", "color": "p3"}, {"t": "4. Granuloma", "m": "<b>Qué pasa:</b> los CD4 lo inducen con IFNγ, IL-1 e IL-2: centro de <mark>epitelioides</mark>, <span class=\"cx\">luego</span> CD4, CD8 y fibroblastos. El núcleo se caseifica; ESAT-6 y MMP-9 atraen macrófagos nuevos que le sirven al bacilo.", "pr": "el bacilo queda encerrado, vivo, en hipoxia.", "pr_tit": "Produce:", "rf": "Preguntas ④ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Latencia", "m": "<b>Por qué:</b> la defensa controla pero no elimina; el bacilo activa el gen <mark>SIGF</mark> y se duerme. La tuberculina (hipersensibilidad) o el IGRA lo detectan, pero una tuberculina positiva no prueba protección.", "pr": "el 95 % queda infectado sin enfermedad.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑧ · punto <span class=\"lt2\">A</span>", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Caen los CD4</b> (VIH) o <b>el TNF</b> (anti-TNF), esteroides, alcohol, drogas o vejez → <mark>reactivación</mark>. Tratar sin cultivo ni sensibilidad deja contagiando a quien tiene cepa resistente.", "pr": "TB pulmonar o sistémica, cepas resistentes.", "pr_tit": "Produce:", "rf": "Preguntas ②⑦ · punto <span class=\"lt2\">C</span>", "color": "p4"}], "extra": [{"html": "🧪 <b>Diagnóstico:</b> directo de esputo (inmediato, pero con más de 10 000 bacilos/mL), cultivo (referencia, semanas), <mark>MTB/RIF</mark> (horas, detecta resistencia a rifampicina), tuberculina (falsos positivos por BCG, falsos negativos en inmunocomprometidos) e <b>IGRA</b> (más sensible, detecta latentes).", "k": ""}, {"html": "💉 <b>BCG:</b> mutante de <b>M. bovis</b>, la única vacuna; protección limitada y variable, pero sí protege a los niños de la <mark>TB meníngea y miliar</mark>. <b>No</b> se aplica a hijos de madres con VIH.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De la latencia a la enfermedad", "pasos": ["bacilo dormido en el granuloma (gen SIGF)", "caen los LT CD4 o se bloquea el TNF", "el macrófago deja de estar activado", "el caseum se licúa y libera bacilos", "<b>TB activa</b> y diseminación; riesgo de cepa resistente"]}], "html": "", "fuente": "Fuente: tu teoría — clase 21 (el bacilo y el hospedero, inmunidad innata y adquirida, granulomas, evasión, latencia, resistencia, hipersensibilidad, diagnóstico y prevención)."}, "preguntas": [{"n": 1, "id": "IN9-018", "c": "i", "tema": "Inmunidad adquirida", "pregunta": "¿Qué citoquinas deben actuar en forma sinérgica para que el macrófago HUMANO destruya a Mycobacterium tuberculosis?", "opciones": ["a. IFNγ y TNF", "b. IL-4 e IL-5", "c. IL-10 y TGF-β", "d. IFNγ sola es suficiente", "e. IL-17 e IL-22"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. IFNγ y TNF: en el humano ninguna basta sola.", "sin_banco": true, "ok": "", "x": "Es el linfocito T del centro de la imagen activando al macrófago: el <mark>IFNγ</mark> del Th1 solo no basta en el humano, se necesita el <mark>TNF</mark>. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>, y <span class=\"cx\">por eso</span> el anti-TNF reactiva la TB.", "truco": "", "veces": 0}, {"n": 2, "id": "IN9-019", "c": "d", "tema": "Latencia y reactivación", "pregunta": "Correlación: una mujer con artritis reumatoide inicia un anticuerpo monoclonal anti-TNF y a los tres meses presenta fiebre, tos y un infiltrado pulmonar apical con bacilos ácido-alcohol resistentes. ¿Qué ocurrió y cómo se previene?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Reactivación de una tuberculosis latente: el TNF, junto con el IFNγ, mantiene activados a los macrófagos que contienen al bacilo. Antes de un anti-TNF es obligatorio despistar la infección latente con tuberculina o IGRA.", "sin_banco": true, "ok": "", "x": "En la <mark>latencia</mark> el bacilo está vivo pero contenido por macrófagos activados por IFNγ y TNF. Al quitar el TNF, el freno cae y el bacilo vuelve a multiplicarse. <span class=\"cx\">Por eso</span> <span class=\"res\">se pide tuberculina o IGRA antes de toda terapia anti-TNF</span>.", "truco": "Anti-TNF = «abre la jaula» del bacilo dormido.", "veces": 0}, {"n": 3, "id": "IN9-020", "c": "d", "tema": "Evasión", "pregunta": "Son estrategias de M. tuberculosis para modificar al macrófago y evadir su destrucción, EXCEPTO:", "opciones": ["a. Formar la cubierta TACO, rica en triptófano y aspartato", "b. Producir lipoarabinomanán y la fosfatasa P13P", "c. Impedir la acidificación del fagosoma e inducir IL-10 y TGF-β", "d. Generar prostaglandina E2", "e. Producir proteína A que bloquea el segmento Fc de los anticuerpos"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La proteína A es de Staphylococcus aureus, no de M. tuberculosis.", "sin_banco": true, "ok": "", "x": "Mira el macrófago de la izquierda: el fagosoma con bacilos y los lisosomas aparte. Eso lo logran <mark>TACO, LAM-P13P, la falta de ácido y la PGE2</mark>. La proteína A es de <b>S. aureus</b>. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN9-021", "c": "i", "tema": "Granuloma", "pregunta": "Describa la organización del granuloma tuberculoso humano desde el centro hacia la periferia y qué ocurre con su núcleo.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Centro de células epitelioides y macrófagos; alrededor LT CD4, luego LT CD8 y por fuera fibroblastos con un halo de fibrosis calcificable. El núcleo se caseifica: la hipoxia mata células y libera bacilos que sobreviven décadas en metabolismo anaerobio.", "sin_banco": true, "ok": "", "x": "Es el corte de la derecha (punto Ⓑ): centro <mark>caseoso</mark> con epitelioides y una célula gigante, anillo de linfocitos y borde fibroso. La hipoxia del centro deja al bacilo <span class=\"res\">vivo en anaerobiosis por décadas</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN9-022", "c": "i", "tema": "Inmunidad innata", "pregunta": "¿Qué determina la proteína SP110 en el macrófago infectado por M. tuberculosis?", "opciones": ["a. Acidifica los lisosomas y facilita su fusión al fagosoma", "b. Controla la replicación bacilar y define si el macrófago muere por necrosis o por apoptosis", "c. Activa el gen de latencia del bacilo", "d. Estimula la formación de células epitelioides y MMP-9", "e. Retrasa la migración de las células dendríticas"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Controla la replicación del bacilo y decide si el macrófago muere por necrosis (libera bacilos vivos) o por apoptosis (libera antígenos).", "sin_banco": true, "ok": "", "x": "Hay dos proteínas del hospedero clave: <mark>LRG-47</mark> acidifica y fusiona el lisosoma, y <mark>SP110</mark> decide la forma de morir. La <b>necrosis</b> suelta bacilos vivos; <span class=\"cx\">en cambio</span> la <b>apoptosis</b> entrega antígenos a las células dendríticas. <span class=\"cx\">Por eso</span> <span class=\"res\">la apoptosis favorece al hospedero</span>. ESAT-6 es del bacilo; SIGF es su gen de latencia.", "truco": "SP110 = «Señala cómo Perecer».", "veces": 0}, {"n": 6, "id": "IN9-023", "c": "g", "tema": "Hipersensibilidad y diagnóstico", "pregunta": "¿Por qué una prueba de tuberculina positiva no garantiza que el paciente tenga inmunidad celular protectora contra la tuberculosis?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque la tuberculina mide hipersensibilidad retardada, que depende de antígenos y mecanismos genéticos distintos de los de la inmunidad celular protectora; ambas pueden coexistir, darse por separado o faltar.", "sin_banco": true, "ok": "", "x": "La infección tuberculosa produce dos fenómenos distintos: la <mark>hipersensibilidad retardada</mark> (la que lee la tuberculina) y la <mark>inmunidad celular efectiva</mark>. Como se desencadenan por caminos diferentes, <span class=\"res\">una tuberculina positiva no prueba protección</span>; <span class=\"cx\">además</span> da falsos positivos por BCG.", "truco": "Tuberculina «+» = «me conoce», no «me protege».", "veces": 0}, {"n": 7, "id": "IN9-024", "c": "g", "tema": "Diagnóstico", "pregunta": "Respecto al MTB/RIF Test en tuberculosis, es CORRECTO:", "opciones": ["a. Solo es positivo con más de 10.000 bacilos/mL", "b. Tarda varias semanas, como el cultivo", "c. Es positivo en el 98 % de los esputos positivos y en el 72 % de los negativos al directo, y detecta resistencia a rifampicina", "d. Da falsos positivos en vacunados con BCG", "e. Detecta la resistencia a isoniazida"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Positivo en el 98 % de esputos positivos y 72 % de negativos al directo; detecta resistencia a rifampicina.", "sin_banco": true, "ok": "", "x": "El <mark>examen directo</mark> necesita más de 10.000 bacilos/mL y el <mark>cultivo</mark> tarda semanas. <span class=\"cx\">En cambio</span> el MTB/RIF da resultado en horas y <span class=\"cx\">además</span> detecta la resistencia a <b>rifampicina</b>. <span class=\"cx\">Por eso</span> <span class=\"res\">permite empezar el esquema correcto desde el primer día</span>; la BCG confunde a la tuberculina, no al MTB/RIF.", "truco": "MTB/RIF: «98-72 y RIFampicina».", "veces": 0}, {"n": 8, "id": "IN9-025", "c": "g", "tema": "Epidemiología", "pregunta": "Según la OMS, ¿qué proporción aproximada de los infectados por M. tuberculosis desarrolla enfermedad activa?", "opciones": ["a. 25 %", "b. 11 %", "c. 50 %", "d. 5 %", "e. 1 %"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Cerca del 5 %; la mayoría queda en infección latente.", "sin_banco": true, "ok": "", "x": "Punto Ⓐ: de unos dos millardos de infectados solo el <mark>5 %</mark> enferma, <span class=\"cx\">porque</span> los LT CD4 y el granuloma contienen al bacilo en latencia. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "Infección latente", "Tuberculosis activa"], "filas": [["Bacilo", "Vivo, dormido en el granuloma (gen SIGF)", "Multiplicándose, se disemina"], ["LT CD4 y TNF", "Suficientes: macrófago activado", "Caídos (VIH) o bloqueados (anti-TNF)"], ["Tuberculina / IGRA", "Positivos", "Positivos (pueden negativizarse si hay inmunosupresión)"], ["Esputo y MTB/RIF", "Negativos", "Positivos; MTB/RIF ve resistencia a rifampicina"], ["Contagio", "No", "Sí"], ["🔑 Para diferenciar", "Infectado sin enfermedad (95 %)", "Enfermo y contagioso (5 %)"]]}, "fuente": "Fuente: tu teoría — clase 21 (Respuesta inmune en tuberculosis), Rojas 17.ª ed."}, {"n": 17, "slug": "Respuesta_inmune_contra_virus", "titulo": "Respuesta inmune contra los virus", "subtitulo": "interferón para el vecino, citotoxicidad para la célula infectada y anticuerpos para el virus libre", "grupo": "g10", "lema": "La idea: el virus no tiene maquinaria propia, así que vive <b>dentro</b> de nuestras células. Por eso la defensa tiene tres tiempos: la célula infectada avisa a sus vecinas con <mark>interferones tipo I</mark> para que frenen su fábrica de proteínas; las <mark>NK</mark> y luego los <mark>LT CD8</mark> matan a la célula ya infectada (perforinas o Fas); y los <b>anticuerpos</b> neutralizan al virus libre antes de que entre. Importa porque los virus evolucionan más rápido que nosotros: cambian sus antígenos (influenza), esconden el HLA-I (citomegalovirus) o imitan citoquinas (EBV), y algunos destruyen (VIH) o hacen proliferar (HTLV-1) a los propios linfocitos. En la imagen verás de izquierda a derecha: una célula infectada enviando interferón a su vecina, una célula infectada atacada por una NK y un LT citotóxico, y viriones cubiertos de anticuerpos que ya no pueden entrar.", "img": "img/17.webp", "mini": "img/mini/17.webp", "ratio": 1.5, "etiquetas": [{"n": "②", "t": "Viriones nuevos", "s": "brotan y buscan<br>su receptor", "c": "g", "x": 0.5, "y": 6, "ax": 4.6, "ay": 27, "al": "l"}, {"n": "①", "t": "Interferón α/β", "s": "avisa a la vecina:<br>frena sus proteínas", "c": "i", "x": 25, "y": 6, "ax": 18, "ay": 38}, {"n": "③④", "t": "Célula NK", "s": "puente: mata a la<br>que no tiene HLA-I", "c": "i", "x": 43, "y": 6, "ax": 40, "ay": 30}, {"n": "④⑤", "t": "LT CD8 citotóxico", "s": "péptido en HLA-I:<br>perforinas o Fas", "c": "d", "x": 63, "y": 6, "ax": 62.5, "ay": 36, "d": "A"}, {"n": "⑤", "t": "Anticuerpo neutralizante", "s": "tapa las espículas:<br>el virus no se une", "c": "d", "x": 99.5, "y": 6, "ax": 87.9, "ay": 44, "al": "r"}, {"n": "⑥⑦", "t": "Célula infectada", "s": "fabrica virus; algunos<br>imitan citoquinas", "c": "g", "x": 0.5, "y": 91, "ax": 10, "ay": 51, "d": "B", "al": "l"}, {"n": "①", "t": "Célula vecina", "s": "protegida por<br>el interferón", "c": "i", "x": 26, "y": 91, "ax": 27, "ay": 62}, {"n": "④", "t": "Apoptosis", "s": "la célula infectada<br>se fragmenta", "c": "d", "x": 50, "y": 91, "ax": 59, "ay": 66}, {"n": "②", "t": "Receptores vacíos", "s": "cada virus usa el suyo:<br>CD4, CR2, ICAM-1", "c": "g", "x": 80, "y": 91, "ax": 82.7, "ay": 64}], "diapos": [{"img": "img/17.webp", "ratio": 1.5, "titulo": "Las armas contra el virus", "texto": "El <mark>interferón</mark> protege a la vecina ①; la NK actúa de inmediato ③ y el LT CD8 llega después <span class=\"lt2\">A</span> ④; el anticuerpo neutraliza al virus libre ⑤.", "etiquetas": [{"n": "②", "t": "Viriones nuevos", "s": "brotan y buscan<br>su receptor", "c": "g", "x": 0.5, "y": 6, "ax": 4.6, "ay": 27, "al": "l"}, {"n": "①", "t": "Interferón α/β", "s": "avisa a la vecina:<br>frena sus proteínas", "c": "i", "x": 25, "y": 6, "ax": 18, "ay": 38}, {"n": "③④", "t": "Célula NK", "s": "puente: mata a la<br>que no tiene HLA-I", "c": "i", "x": 43, "y": 6, "ax": 40, "ay": 30}, {"n": "④⑤", "t": "LT CD8 citotóxico", "s": "péptido en HLA-I:<br>perforinas o Fas", "c": "d", "x": 63, "y": 6, "ax": 62.5, "ay": 36, "d": "A"}, {"n": "⑤", "t": "Anticuerpo neutralizante", "s": "tapa las espículas:<br>el virus no se une", "c": "d", "x": 99.5, "y": 6, "ax": 87.9, "ay": 44, "al": "r"}, {"n": "⑥⑦", "t": "Célula infectada", "s": "fabrica virus; algunos<br>imitan citoquinas", "c": "g", "x": 0.5, "y": 91, "ax": 10, "ay": 51, "d": "B", "al": "l"}, {"n": "①", "t": "Célula vecina", "s": "protegida por<br>el interferón", "c": "i", "x": 26, "y": 91, "ax": 27, "ay": 62}, {"n": "④", "t": "Apoptosis", "s": "la célula infectada<br>se fragmenta", "c": "d", "x": 50, "y": 91, "ax": 59, "ay": 66}, {"n": "②", "t": "Receptores vacíos", "s": "cada virus usa el suyo:<br>CD4, CR2, ICAM-1", "c": "g", "x": 80, "y": 91, "ax": 82.7, "ay": 64}]}, {"img": "img/17_2.webp", "ratio": 1.5, "titulo": "Cómo se escapan los virus", "texto": "El EBV entra al LB por el <mark>CR2</mark> ②; el CMV baja el HLA-I y muestra HLA-E, así engaña al LT CD8 y a la NK ④; el BCRF1 imita la IL-10 <span class=\"lt2\">B</span> ⑦.", "etiquetas": [{"n": "②", "t": "EBV", "s": "virus de<br>Epstein-Barr", "c": "g", "x": 0.8, "y": 6, "ax": 13, "ay": 26, "al": "l"}, {"n": "②", "t": "Entra al LB", "s": "por fusión", "c": "g", "x": 22, "y": 6, "ax": 18, "ay": 41}, {"n": "④", "t": "LT CD8 sin blanco", "s": "no ve el<br>HLA-I", "c": "d", "x": 39, "y": 6, "ax": 33, "ay": 35}, {"n": "④", "t": "Pocas HLA-I", "s": "el CMV las baja", "c": "g", "x": 56, "y": 6, "ax": 52, "ay": 31}, {"n": "⑦", "t": "Macrófago apagado", "s": "no responde<br>al IFNγ", "c": "g", "x": 99.2, "y": 6, "ax": 90, "ay": 32, "al": "r"}, {"n": "②", "t": "CR2", "s": "receptor del<br>complemento del LB", "c": "g", "x": 0.8, "y": 92, "ax": 12, "ay": 61, "al": "l"}, {"n": "④", "t": "HLA-E", "s": "señal de «célula<br>sana» para la NK", "c": "g", "x": 30, "y": 92, "ax": 54, "ay": 47}, {"n": "③④", "t": "NK frenada", "s": "no lisa a la<br>célula infectada", "c": "i", "x": 53, "y": 92, "ax": 61, "ay": 55}, {"n": "⑦", "t": "BCRF1", "s": "imita a la IL-10", "c": "g", "x": 74, "y": 92, "ax": 84, "ay": 46, "d": "B"}, {"n": "⑦", "t": "LT inhibido", "s": "respuesta frenada", "c": "g", "x": 99.2, "y": 92, "ax": 93, "ay": 66, "al": "r"}]}, {"img": "img/17_3.webp", "ratio": 1.5, "titulo": "Retrovirus opuestos y priones", "texto": "El <mark>HTLV-1</mark> hace proliferar a los LT CD4 (leucemia) y el <mark>VIH</mark> los destruye (sida) ⑥; el prión <span class=\"res\">no despierta</span> respuesta inmune: no hay anticuerpos ⑧.", "etiquetas": [{"n": "⑥", "t": "HTLV-1", "s": "retrovirus que<br>estimula al LT CD4", "c": "g", "x": 0.8, "y": 6, "ax": 7, "ay": 27, "al": "l"}, {"n": "⑥", "t": "Clon de LT CD4", "s": "se multiplica<br>sin freno", "c": "g", "x": 24, "y": 6, "ax": 25, "ay": 36}, {"n": "⑥", "t": "VIH", "s": "brota del LT CD4", "c": "g", "x": 45, "y": 6, "ax": 45, "ay": 30}, {"n": "⑧", "t": "Placa de prión", "s": "proteína mal<br>plegada", "c": "g", "x": 70, "y": 6, "ax": 85, "ay": 32}, {"n": "⑧", "t": "Vacuolas", "s": "cerebro<br>espongiforme", "c": "g", "x": 99.2, "y": 6, "ax": 93, "ay": 40, "al": "r"}, {"n": "⑥", "t": "LT CD4 en mitosis", "s": "proliferación sin<br>control: leucemia T", "c": "g", "x": 0.8, "y": 92, "ax": 14, "ay": 50, "al": "l"}, {"n": "⑥", "t": "LT CD4 destruido", "s": "caen los CD4: sida", "c": "g", "x": 45, "y": 92, "ax": 57, "ay": 66}, {"n": "⑧", "t": "Sin células inmunes", "s": "no hay anticuerpos<br>contra el prión", "c": "g", "x": 99.2, "y": 92, "ax": 78, "ay": 62, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa innata</b> (interferón, NK), <b class=\"d\">rojo = defensa adquirida</b> (LT CD8, anticuerpos), gris = el virus y las células de referencia.", "<b>Izquierda:</b> la célula infectada detecta el virus con <mark>TLR3/7/8/9</mark> (o RIG-1 y Mda5 en el citoplasma) y secreta IFNα e IFNβ; la vecina enciende la 2'-5' oligoadenilato sintetasa y la quinasa del ARNdc.", "<b>Centro:</b> la NK llega <span class=\"cx\">primero</span> (puente innata-adquirida); el <mark>LT CD8</mark> reconoce péptidos de 10-20 aminoácidos sobre HLA-I y se multiplica <span class=\"lt2\">A</span>.", "<b>Derecha:</b> el anticuerpo tapa las espículas y el receptor de la célula queda vacío: cada virus usa su receptor (VIH-CD4, EBV-CR2, rinovirus-ICAM-1)."], "recordar": "Vecino → <b>interferón</b>; infectada → <b>NK y LT CD8</b>; virus libre → <b>anticuerpo</b>. Memoria T = semanas; memoria B = años. Evasión: variar antígeno, bajar HLA-I, imitar IL-10."}, "numeros": [{"l": "A", "html": "<b>LT CD8 citotóxicos</b>: aumentan hasta <b class=\"a\">10 000 veces</b> durante la infección; reconocen péptidos de <b class=\"n\">10 a 20 aminoácidos</b>.", "rango": null}, {"l": "B", "html": "<b>BCRF1 del EBV</b>: <b class=\"a\">84 %</b> de homología con la IL-10 humana.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del virus a la memoria", "subtitulo": "estímulo → interferón y NK → LT CD8 → anticuerpos → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Entrada", "m": "<b>Qué pasa:</b> el virus entra por piel lesionada, vector o mucosa usando un <mark>receptor específico</mark> (VIH: CD4, CCR5, CXCR4; EBV: CR2; influenza A: glicoforina A; rinovirus: ICAM-1).", "pr": "el receptor define qué células infecta (tropismo).", "pr_tit": "Produce:", "rf": "Preguntas ②", "color": "p1"}, {"t": "2. Alarma: interferones", "m": "<b>Por qué:</b> TLR3, 7, 8 y 9 (y RIG-1, Mda5) detectan el ácido nucleico viral; la célula secreta <mark>IFNα e IFNβ</mark>. Las vecinas activan la 2'-5' oligoadenilato sintetasa y la quinasa del ARNdc.", "pr": "las vecinas frenan su síntesis proteica: el virus no se replica en ellas.", "pr_tit": "Produce:", "rf": "Preguntas ①", "color": "p2"}, {"t": "3. NK: el puente", "m": "<b>Qué produce:</b> las <mark>NK</mark>, activadas por IL-12 e interferones, lisan células infectadas y producen IFNγ, TNF y GM-CSF mientras se preparan los linfocitos.", "pr": "contención temprana de la infección.", "pr_tit": "Produce:", "rf": "Preguntas ③④", "color": "p3"}, {"t": "4. LT CD8 y anticuerpos", "m": "<b>Qué pasa:</b> el <mark>LT CD8</mark> ve el péptido viral sobre HLA-I y mata por <b>perforinas</b> o por <b>Fas-CD95</b>; los LT CD4 ayudan a los LB, cuyos anticuerpos bloquean la unión del virus a la célula.", "pr": "eliminación de células infectadas y neutralización del virus libre.", "pr_tit": "Produce:", "rf": "Preguntas ④ · punto <span class=\"lt2\">A</span>", "color": "p4"}, {"t": "5. Memoria", "m": "<b>Por qué:</b> la respuesta T dura <mark>semanas</mark> pero deja memoria de respuesta rápida; la memoria B dura <mark>años</mark>, <span class=\"cx\">por eso</span> polio, viruela y sarampión dan inmunidad permanente.", "pr": "reinfección rápida y abortada.", "pr_tit": "Produce:", "rf": "Preguntas ⑤", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Evasión:</b> variación antigénica (influenza), HLA-I bajo y HLA-E alto (CMV), viroquinas (BCRF1 ≈ IL-10), sincitios (sarampión). <b>Daño:</b> complejos inmunes, latencia, cáncer; VIH destruye y HTLV-1 hace proliferar a los CD4.", "pr": "infección persistente, sida, leucemia T, linfoma.", "pr_tit": "Produce:", "rf": "Preguntas ④⑥⑦⑧ · punto <span class=\"lt2\">B</span>", "color": "p4"}], "extra": [{"html": "🧫 <b>Tipos de infección viral:</b> agudas rápidas (rinovirus), sistémicas con inmunidad de por vida (varicela, sarampión, paperas, rubéola), <mark>latentes</mark> en neuronas (herpes simple, varicela-zóster), crónicas con portador sano (hepatitis B) y crónicas con neoplasia (hepatoma por hepatitis B/C, linfoma por EBV, leucemia por HTLV-I).", "k": ""}, {"html": "🧠 <b>Priones:</b> proteínas mal plegadas, sin ácido nucleico, que no inducen respuesta inmune; las células dendríticas foliculares los multiplican en el ganglio. Causan Kuru, Creutzfeldt-Jakob, Gerstmann-Sträussler-Scheinker e insomnio familiar fatal. Controladores de élite del VIH: <mark>HLA-B*57 o B*27</mark>.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De la infección persistente al cáncer", "pasos": ["virus que escapa a la defensa", "persiste años en la célula (latente o crónico)", "inmortaliza o hace proliferar a la célula (EBV, HTLV-1)", "translocación C-MYC 8→14 (EBV)", "<b>linfoma, leucemia T, hepatoma o cáncer cervical</b> (el 20 % de los tumores se asocia a virus)"]}], "html": "", "fuente": "Fuente: tu teoría — clase 22 (biología viral, defensa innata y adquirida, memoria, inmunopatología, evasión, virus y cáncer, priones)."}, "preguntas": [{"n": 1, "id": "IN10-001", "c": "i", "tema": "Defensa innata: interferones", "pregunta": "El mecanismo antiviral central de los interferones tipo I (IFNα e IFNβ) consiste en:", "opciones": ["a. Lisar directamente la célula infectada mediante perforinas", "b. Inducir en las células vecinas la 2&#x27;-5&#x27; oligoadenilato sintetasa y una quinasa dependiente de ARN de doble cadena que frenan la síntesis proteica", "c. Neutralizar los viriones libres en la sangre", "d. Formar sincitios entre células sanas", "e. Opsonizar los virus para los macrófagos"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Inducen en las células vecinas enzimas (2&#x27;-5&#x27; oligoadenilato sintetasa y quinasa del ARNdc) que frenan la síntesis proteica e impiden la replicación viral.", "sin_banco": true, "ok": "", "x": "Es la escena de la izquierda: la célula infectada lanza <mark>interferón</mark> y la vecina queda protegida, <span class=\"cx\">porque</span> frena su propia síntesis de proteínas y el virus no puede replicarse en ella. No mata ni neutraliza: <span class=\"cx\">por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN10-002", "c": "g", "tema": "Puertas de entrada", "pregunta": "¿Qué receptor celular usa el virus de Epstein-Barr para infectar a los linfocitos B?", "opciones": ["a. CD4", "b. ICAM-1", "c. CR2 (receptor del complemento)", "d. Glicoforina A", "e. CCR5"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. CR2, el receptor del complemento de los linfocitos B.", "sin_banco": true, "ok": "", "x": "A la derecha, el receptor de la célula queda vacío <span class=\"cx\">porque</span> el anticuerpo tapa al virus: sin receptor no hay entrada. El EBV usa el <mark>CR2</mark> de los linfocitos B. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN10-003", "c": "i", "tema": "Defensa innata: NK", "pregunta": "¿Por qué se considera a las células NK el «puente» entre la inmunidad innata y la adquirida frente a los virus?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque actúan de inmediato, lisando células infectadas y produciendo IFNγ, TNF y GM-CSF, y así contienen la infección mientras los linfocitos B y T se activan y montan la respuesta específica, que tarda más.", "sin_banco": true, "ok": "", "x": "La respuesta específica necesita días para expandir clones. Mientras tanto, las <mark>NK</mark> activadas por IL-12 matan células infectadas y producen citoquinas que modulan a los linfocitos. <span class=\"cx\">Por eso</span> <span class=\"res\">ganan tiempo</span> hasta que llegan los LT CD8 y los anticuerpos.", "truco": "NK = «guardia de turno» hasta que llegue el especialista.", "veces": 0}, {"n": 4, "id": "IN10-004", "c": "i", "tema": "Evasión viral", "pregunta": "¿Qué estrategia usa el citomegalovirus para escapar a la vez de los LT CD8 y de las células NK?", "opciones": ["a. Disminuye la expresión de HLA-I e induce la expresión de HLA-E", "b. Variación antigénica de sus proteínas de superficie", "c. Formación de sincitios", "d. Producción de una viroquina homóloga a la IL-10", "e. Restricción de la expresión de sus genes"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Baja el HLA-I (escapa del LT CD8) e induce HLA-E (apaga a la NK).", "sin_banco": true, "ok": "", "x": "En el centro, la NK y el LT CD8 atacan a la misma célula: el LT ve el péptido sobre <mark>HLA-I</mark> y la NK mata a la que <b>no</b> tiene HLA-I. El CMV quita el HLA-I y pone <span class=\"res\">HLA-E</span> para burlar a los dos. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN10-005", "c": "d", "tema": "Memoria inmunológica", "pregunta": "¿Qué diferencia hay entre la duración de la respuesta de los linfocitos T y la de los linfocitos B frente a un virus?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La respuesta de LT dura solo semanas, aunque deja células de memoria de respuesta rápida; la de LB persiste años, y explica la inmunidad permanente contra polio, viruela y sarampión.", "sin_banco": true, "ok": "", "x": "Durante la infección los <mark>LT CD8</mark> pueden multiplicarse hasta <span class=\"res\">10.000 veces</span> y <span class=\"cx\">luego</span> se retraen en semanas. <span class=\"cx\">En cambio</span> la memoria de los <mark>LB</mark> y sus anticuerpos neutralizantes dura años, <span class=\"cx\">así que</span> <span class=\"res\">los virus antigénicamente estables dan inmunidad de por vida</span>.", "truco": "T = «Temporal»; B = «Bastantes años».", "veces": 0}, {"n": 6, "id": "IN10-006", "c": "d", "tema": "Virus que alteran la respuesta", "pregunta": "Correlación: un adulto de zona endémica presenta leucemia de linfocitos T CD4. Su hermano, con un retrovirus distinto que también infecta los LT CD4, desarrolla infecciones oportunistas graves. ¿Qué virus tiene cada uno y por qué el efecto es opuesto?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El primero tiene HTLV-1, que estimula la proliferación anormal de los LT CD4 (leucemia de linfocitos T); el segundo tiene VIH, que los destruye progresivamente (sida).", "sin_banco": true, "ok": "", "x": "Los dos son <mark>retrovirus con tropismo por el LT CD4</mark>, pero hacen lo contrario: el <b>HTLV-1</b> lo empuja a dividirse sin control, <span class=\"cx\">en cambio</span> el <b>VIH</b> lo mata. <span class=\"cx\">Por eso</span> uno da <span class=\"res\">leucemia T</span> y el otro <span class=\"res\">inmunodeficiencia</span>.", "truco": "HTLV-1 = «hace más T»; VIH = «vacía de T».", "veces": 0}, {"n": 7, "id": "IN10-007", "c": "d", "tema": "Evasión viral", "pregunta": "La proteína BCRF1 del virus de Epstein-Barr tiene un 84 % de homología con la citoquina humana:", "opciones": ["a. IL-2", "b. IFNγ", "c. IL-18", "d. TNF", "e. IL-10"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. IL-10: imita a esta citoquina antiinflamatoria y protege al virus del IFNγ.", "sin_banco": true, "ok": "", "x": "Las <mark>viroquinas</mark> imitan citoquinas humanas para apagar la defensa. La BCRF1 del EBV se parece en un <span class=\"res\">84 % a la IL-10</span>, que frena la respuesta Th1. <span class=\"cx\">En cambio</span> el ortopoxvirus fabrica una proteína que <b>atrapa la IL-18</b> y el HHV8 bloquea la caspasa 8.", "truco": "EBV «habla en IL-10» para calmar al IFNγ.", "veces": 0}, {"n": 8, "id": "IN10-008", "c": "g", "tema": "Priones", "pregunta": "Respecto a los priones, es FALSO:", "opciones": ["a. Son proteínas anormalmente plegadas, sin ácido nucleico", "b. No inducen respuesta inmune", "c. Causan Kuru, Creutzfeldt-Jakob e insomnio familiar fatal", "d. Inducen anticuerpos neutralizantes que permiten el diagnóstico serológico", "e. Las células dendríticas foliculares los capturan y facilitan su replicación en los ganglios"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Es falso: los priones no inducen respuesta inmune, así que no hay anticuerpos neutralizantes.", "sin_banco": true, "ok": "", "x": "El prión es la <mark>proteína mal plegada</mark> que contagia su forma a las proteínas normales; como es una proteína propia, el sistema inmune <span class=\"res\">no responde</span>. Peor aún, las <b>células dendríticas foliculares</b> lo atrapan y lo multiplican en el ganglio, y de ahí llega al SNC por fibras simpáticas.", "truco": "Prión = «proteína disfrazada de propia»: nadie la ataca.", "veces": 0}], "tabla": {"cab": ["", "Interferón tipo I", "NK", "LT CD8", "Anticuerpo"], "filas": [["Blanco", "Célula vecina", "Infectada sin HLA-I", "Infectada con péptido en HLA-I", "Virus libre"], ["Cómo actúa", "Frena la síntesis proteica", "Lisis, IFNγ", "Perforinas o Fas", "Bloquea la unión"], ["Cuándo (literatura)", "Horas", "Primeros días", "Días; ×10 000", "Días; memoria años"], ["Evasión", "Viroquinas", "HLA-E (CMV)", "HLA-I bajo (CMV)", "Variación (influenza)"], ["🔑 Para diferenciar", "Protege", "Puente", "Mata", "Neutraliza"]]}, "fuente": "Fuente: tu teoría — clase 22 (Respuesta inmune contra las infecciones virales), Rojas 17.ª ed."}, {"n": 18, "slug": "Parasitos_y_malaria", "titulo": "Parásitos y malaria", "subtitulo": "helmintos con Th2, protozoos con Th1 y el eritrocito pegajoso de P. falciparum", "grupo": "g10", "lema": "La idea: frente a los parásitos el sistema inmune elige el arma según el tamaño y el sitio. Al <mark>helminto</mark>, grande y extracelular, lo ataca la respuesta <b>Th2</b>: IgE, mastocitos y eosinófilos que se descargan sobre su cutícula. Al <mark>protozoo intracelular</mark> (leishmania, toxoplasma) lo destruye el macrófago activado por el <b>IFNγ</b> de los Th1. Casi nunca se logra una victoria total: es la <b>preinmunización</b>, que controla sin erradicar. En la <mark>malaria</mark>, <b>P. falciparum</b> exporta la PfEMP1 y pega el eritrocito al endotelio, por eso tapa los capilares del cerebro. Importa porque si cae la inmunidad celular el parásito latente despierta (toxoplasmosis en el sida) y porque parte del daño es la propia respuesta (Chagas, esquistosomiasis). En la imagen verás de izquierda a derecha: eosinófilos atacando a un esquistosómulo, un macrófago lleno de leishmanias frente a uno activado que las destruye, y un capilar cerebral con eritrocitos parasitados pegados y una roseta.", "img": "img/18.webp", "mini": "img/mini/18.webp", "ratio": 1.5, "etiquetas": [{"n": "①③", "t": "Eosinófilo", "s": "Th2: sobre<br>la cutícula", "c": "i", "x": 0.5, "y": 6, "ax": 6.2, "ay": 36, "al": "l"}, {"n": "③", "t": "Cutícula", "s": "erosionada<br>por gránulos", "c": "d", "x": 21, "y": 6, "ax": 19.5, "ay": 41}, {"n": "②⑨", "t": "Macrófago-refugio", "s": "no activado:<br>leishmanias vivas", "c": "d", "x": 40, "y": 6, "ax": 41.7, "ay": 42, "d": "A"}, {"n": "①⑭", "t": "Macrófago activado", "s": "IFNγ y TNF:<br>las destruye", "c": "i", "x": 60, "y": 6, "ax": 61, "ay": 40}, {"n": "", "t": "Endotelio cerebral", "s": "receptores de adherencia<br>(ICAM-1, VCAM-1)", "c": "g", "x": 99.5, "y": 6, "ax": 84.6, "ay": 28.5, "al": "r"}, {"n": "⑦", "t": "Esquistosómulo", "s": "camuflado con<br>HLA del hospedero", "c": "d", "x": 0.5, "y": 91, "ax": 3, "ay": 67, "d": "D", "al": "l"}, {"n": "⑧", "t": "Mastocito", "s": "IgE: inflama y<br>barre al gusano", "c": "i", "x": 23.5, "y": 91, "ax": 26, "ay": 60}, {"n": "⑨", "t": "Amastigotes", "s": "entraron por el<br>complemento", "c": "d", "x": 42, "y": 91, "ax": 43, "ay": 55}, {"n": "⑩⑪⑮", "t": "Knobs de PfEMP1", "s": "pegan el eritrocito al vaso:<br>no pasa por el bazo", "c": "d", "x": 64, "y": 91, "ax": 75.5, "ay": 42, "d": "C"}, {"n": "⑯", "t": "Roseta", "s": "eritrocitos sanos<br>tapan el capilar", "c": "d", "x": 99.5, "y": 91, "ax": 87, "ay": 50, "d": "B", "al": "r"}], "diapos": [{"img": "img/18.webp", "ratio": 1.5, "titulo": "Helmintos, protozoos y malaria", "texto": "Contra el helminto, <mark>Th2</mark>: eosinófilos sobre la cutícula ①③ y mastocitos con IgE ⑧; la leishmania se refugia en el macrófago ⑨ <span class=\"lt2\">A</span>; <b>P. falciparum</b> pega knobs al endotelio cerebral ⑪⑯ <span class=\"lt2\">B</span>.", "etiquetas": [{"n": "①③", "t": "Eosinófilo", "s": "Th2: sobre<br>la cutícula", "c": "i", "x": 0.5, "y": 6, "ax": 6.2, "ay": 36, "al": "l"}, {"n": "③", "t": "Cutícula", "s": "erosionada<br>por gránulos", "c": "d", "x": 21, "y": 6, "ax": 19.5, "ay": 41}, {"n": "②⑨", "t": "Macrófago-refugio", "s": "no activado:<br>leishmanias vivas", "c": "d", "x": 40, "y": 6, "ax": 41.7, "ay": 42, "d": "A"}, {"n": "①⑭", "t": "Macrófago activado", "s": "IFNγ y TNF:<br>las destruye", "c": "i", "x": 60, "y": 6, "ax": 61, "ay": 40}, {"n": "", "t": "Endotelio cerebral", "s": "receptores de adherencia<br>(ICAM-1, VCAM-1)", "c": "g", "x": 99.5, "y": 6, "ax": 84.6, "ay": 28.5, "al": "r"}, {"n": "⑦", "t": "Esquistosómulo", "s": "camuflado con<br>HLA del hospedero", "c": "d", "x": 0.5, "y": 91, "ax": 3, "ay": 67, "d": "D", "al": "l"}, {"n": "⑧", "t": "Mastocito", "s": "IgE: inflama y<br>barre al gusano", "c": "i", "x": 23.5, "y": 91, "ax": 26, "ay": 60}, {"n": "⑨", "t": "Amastigotes", "s": "entraron por el<br>complemento", "c": "d", "x": 42, "y": 91, "ax": 43, "ay": 55}, {"n": "⑩⑪⑮", "t": "Knobs de PfEMP1", "s": "pegan el eritrocito al vaso:<br>no pasa por el bazo", "c": "d", "x": 64, "y": 91, "ax": 75.5, "ay": 42, "d": "C"}, {"n": "⑯", "t": "Roseta", "s": "eritrocitos sanos<br>tapan el capilar", "c": "d", "x": 99.5, "y": 91, "ax": 87, "ay": 50, "d": "B", "al": "r"}]}, {"img": "img/18_2.webp", "ratio": 1.5, "titulo": "El ciclo de la malaria en el hombre", "texto": "El esporozoíto pasa minutos en sangre: <span class=\"cx\">por eso</span> el anticuerpo lo alcanza ⑫ <span class=\"lt2\">C</span>; el hepatocito libera miles de merozoítos ⑮; <b>P. vivax</b> deja hipnozoítos ⑬ y necesita el antígeno <mark>Duffy</mark> ⑩.", "etiquetas": [{"n": "⑫", "t": "Picadura", "s": "inocula<br>esporozoítos", "c": "g", "x": 0.8, "y": 6, "ax": 12, "ay": 27, "al": "l"}, {"n": "⑮", "t": "Esquizonte hepático", "s": "miles de merozoítos<br>en el merosoma", "c": "d", "x": 38, "y": 6, "ax": 48, "ay": 41, "d": "C"}, {"n": "⑫", "t": "Merozoítos", "s": "invaden en<br>segundos", "c": "d", "x": 58, "y": 6, "ax": 61, "ay": 46}, {"n": "⑩", "t": "Antígeno Duffy", "s": "puerta de<br>P. vivax", "c": "i", "x": 77, "y": 6, "ax": 75, "ay": 37}, {"n": "⑩", "t": "Anillo", "s": "parásito en<br>el eritrocito", "c": "d", "x": 99.2, "y": 6, "ax": 90, "ay": 37, "al": "r"}, {"n": "⑫", "t": "Esporozoítos", "s": "minutos en sangre", "c": "d", "x": 0.8, "y": 92, "ax": 21, "ay": 58, "al": "l"}, {"n": "⑫", "t": "Anticuerpo", "s": "alcanza al<br>esporozoíto", "c": "i", "x": 25, "y": 92, "ax": 24, "ay": 61}, {"n": "⑬", "t": "Hipnozoíto", "s": "latente: recaídas<br>(P. vivax y ovale)", "c": "d", "x": 46, "y": 92, "ax": 45, "ay": 59}, {"n": "⑩", "t": "Merozoíto entrando", "s": "se une al<br>receptor", "c": "d", "x": 70, "y": 92, "ax": 80, "ay": 50}, {"n": "⑩", "t": "Sin Duffy", "s": "no puede<br>entrar", "c": "i", "x": 99.2, "y": 92, "ax": 93, "ay": 57, "al": "r"}]}, {"img": "img/18_3.webp", "ratio": 1.5, "titulo": "Escapar y dañar a largo plazo", "texto": "<b>T. brucei</b> cambia su capa con más de 1000 genes ⑤ <span class=\"lt2\">D</span>; en el Chagas crónico el miocardio se daña <span class=\"res\">sin parásitos</span> (autoinmunidad) ④; el toxoplasma se reactiva si caen los LT CD4 ⑥②.", "etiquetas": [{"n": "⑤", "t": "Anticuerpos", "s": "solo reconocen<br>la capa vieja", "c": "i", "x": 0.8, "y": 6, "ax": 7, "ay": 26, "al": "l"}, {"n": "⑤", "t": "Capa nueva", "s": "el anticuerpo<br>ya no la ve", "c": "d", "x": 22, "y": 6, "ax": 22, "ay": 37}, {"n": "④", "t": "Infiltrado linfocitario", "s": "reacción<br>autoinmune", "c": "i", "x": 46, "y": 6, "ax": 53, "ay": 45}, {"n": "②⑥", "t": "Quiste tisular", "s": "toxoplasma latente,<br>controlado por Th1", "c": "d", "x": 99.2, "y": 6, "ax": 90, "ay": 34, "al": "r"}, {"n": "⑤", "t": "T. brucei", "s": "cambia de capa:<br>más de 1000 genes", "c": "d", "x": 0.8, "y": 92, "ax": 10, "ay": 52, "d": "D", "al": "l"}, {"n": "④", "t": "Miocardio sin parásitos", "s": "Chagas crónico", "c": "g", "x": 32, "y": 92, "ax": 40, "ay": 62}, {"n": "④", "t": "Fibrosis", "s": "corazón<br>dañado", "c": "g", "x": 52, "y": 92, "ax": 59, "ay": 62}, {"n": "⑥", "t": "Quiste roto", "s": "reactivación si<br>caen los LT CD4", "c": "d", "x": 72, "y": 92, "ax": 77, "ay": 58}, {"n": "⑥", "t": "Parásitos libres", "s": "lesiones<br>cerebrales", "c": "d", "x": 99.2, "y": 92, "ax": 86, "ay": 58, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa del hospedero</b> (eosinófilo, mastocito, macrófago activado), <b class=\"d\">rojo = el parásito y su daño</b> (leishmanias, knobs, roseta), gris = estructuras de referencia.", "<b>Izquierda:</b> el eosinófilo no puede comerse al gusano, <span class=\"cx\">así que</span> se <mark>degranula sobre su cutícula</mark> y abre heridas por donde entran los macrófagos; el mastocito con IgE inflama y, en el intestino, barre al parásito.", "<b>Centro:</b> el macrófago no activado es <b>refugio</b> de leishmanias (destruye solo una parte de los promastigotes <span class=\"lt2\">A</span>); activado por IFNγ y TNF las destruye.", "<b>Derecha:</b> la <mark>PfEMP1</mark> forma knobs que pegan el eritrocito al endotelio y forman rosetas; así evita el bazo y tapa el capilar <span class=\"lt2\">B</span>."], "recordar": "Helminto → <b>Th2</b> (IL-4, IL-5, IL-13, IgE, eosinófilo). Protozoo → <b>Th1</b> (IFNγ, macrófago, óxido nítrico). Malaria: esporozoíto (minutos) → hígado (7-10 días) → eritrocito (segundos) → PfEMP1 → malaria cerebral."}, "numeros": [{"l": "A", "html": "<b>Leishmania</b>: el macrófago destruye solo del <b class=\"a\">80 % al 90 %</b> de los promastigotes fagocitados.", "rango": null}, {"l": "B", "html": "<b>Malaria cerebral</b>: afecta al <b class=\"a\">1 %</b> de los infectados y mata al <b class=\"a\">10-20 %</b> de ellos.", "rango": null}, {"l": "C", "html": "<b>Ciclo</b>: cada picadura inocula <b class=\"n\">50 a 100</b> esporozoítos; cada hepatocito libera <b class=\"a\">20 000 a 30 000</b> merozoítos en <b class=\"n\">7 a 10 días</b>.", "rango": null}, {"l": "D", "html": "<b>Esquistosomiasis</b>: <b class=\"a\">200 millones</b> de afectados. <b>T. brucei</b>: más de <b class=\"a\">1000 genes</b> de variación, ciclos de <b class=\"n\">4 semanas</b>. <b>Chagas</b>: antígeno de <b class=\"n\">160 kDa</b>; <b class=\"a\">20 millones</b> de infectados.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del parásito a la preinmunización", "subtitulo": "estímulo → Th1 o Th2 → células efectoras → resultado → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> entra un <mark>protozoo intracelular</mark> (<b>Plasmodium</b>, <b>Toxoplasma</b>, leishmania) o un <mark>helminto</mark> extracelular (<b>Schistosoma</b>, <b>Ancylostoma</b>). Algunas larvas cruzan la piel (<b>Necator</b>); otros llegan por vector.", "pr": "el tipo de parásito orienta la respuesta.", "pr_tit": "Produce:", "rf": "Preguntas ①", "color": "p1"}, {"t": "2. Th1 contra protozoos", "m": "<b>Por qué:</b> el <mark>IFNγ</mark> activa al macrófago, que produce H₂O₂ y <b>óxido nítrico</b>. En la malaria, el TLR9 reconoce la <b>hemozoína</b> y la dendrítica produce IL-12 para generar Th1.", "pr": "macrófago activado que destruye leishmanias y eritrocitos parasitados.", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑭ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Th2 contra helmintos", "m": "<b>Qué produce:</b> IL-4, IL-5 e IL-13 → <mark>IgE</mark>, mastocitos y eosinófilos. El eosinófilo se degranula sobre la cutícula; la IgE en el intestino aumenta peristaltismo y secreción.", "pr": "lesión de la cutícula y barrido intestinal del parásito.", "pr_tit": "Produce:", "rf": "Preguntas ①③⑧", "color": "p3"}, {"t": "4. Preinmunización", "m": "<b>Qué pasa:</b> la respuesta controla la enfermedad <mark>sin erradicar</mark> (malaria, toxoplasmosis, leishmaniasis); en la malaria hacen falta <b>varias infecciones</b> y anticuerpos IgG1/IgG3 para un control parcial.", "pr": "parásito vivo y contenido.", "pr_tit": "Produce:", "rf": "Preguntas ②⑫", "color": "p4"}, {"t": "5. Evasión", "m": "<b>Por qué:</b> variación antigénica (<b>T. brucei</b>), camuflaje con HLA y grupo sanguíneo (<b>Schistosoma</b>), DAF-like (<b>T. cruzi</b>), entrada por el complemento (leishmania), <mark>PfEMP1</mark> en el eritrocito, hipnozoítos (<b>P. vivax</b>, <b>P. ovale</b>).", "pr": "persistencia, recaídas y complicaciones.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑨⑩⑪⑬ · puntos <span class=\"lt2\">C</span><span class=\"lt2\">D</span>", "color": "p5"}, {"t": "6. Si falla", "m": "<b>Cae la inmunidad celular</b> → reactivación (toxoplasmosis en el sida). <b>Daño por la respuesta:</b> Chagas autoinmune, granulomas y fibrosis en la esquistosomiasis, rosetas y TNF en la <mark>malaria cerebral</mark>.", "pr": "encefalitis, miocardiopatía, hipertensión portal, coma.", "pr_tit": "Produce:", "rf": "Preguntas ④⑥⑦⑯ · punto <span class=\"lt2\">B</span>", "color": "p4"}], "extra": [{"html": "🦟 <b>Malaria por fases</b> ⑫⑮: esporozoíto (minutos; anticuerpos anti-CSP) → hígado (7-10 días; LT CD8, Tγδ y NK) → eritrocito (segundos; IgG1/IgG3 y fagocitosis) → gametocito (anticuerpos que cortan la transmisión). Resistencia natural: <mark>Duffy negativo</mark> ⑩ (contra <b>P. vivax</b>), hemoglobinas S, C y E, deficiencia de G6PD (contra <b>P. falciparum</b>); loci ATP2B4 y MARVELD3.", "k": ""}, {"html": "💉 <b>Vacunas:</b> contra esporozoítos (péptido repetido o esporozoítos irradiados), contra formas intraeritrocíticas (<mark>Patarroyo</mark> ⑰, primera sintética, 35 % en campo) y contra gametocitos. La <b>amibiasis</b> inactiva el CD59 y degrada anafilotoxinas; la falta de helmintos se asocia al aumento del asma.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Hacia la malaria grave", "pasos": ["eritrocitos parasitados por <b>P. falciparum</b>", "PfEMP1 forma knobs y rosetas", "GPI → TNF y linfotoxina (ICAM-1, VCAM-1)", "obstrucción de capilares cerebrales y placentarios", "<b>malaria cerebral</b>, anemia, hipoglucemia y acidosis láctica"]}], "html": "", "fuente": "Fuente: tu teoría — clase 23 (eje Th1/Th2, preinmunización, eosinófilos, IgE, evasión, leishmaniasis, Chagas, enfermedad del sueño, esquistosomiasis, toxoplasmosis, amibiasis) y clase 24 (ciclo, genética, respuesta innata y adquirida por fases, inmunopatología, complicaciones y vacunas)."}, "preguntas": [{"n": 1, "id": "IN10-009", "c": "i", "tema": "Eje Th1/Th2", "pregunta": "Frente a los helmintos extracelulares, la respuesta inmune predominante es:", "opciones": ["a. Th1, con IFNγ y activación de macrófagos", "b. Th17, con neutrófilos", "c. LT CD8 citotóxicos con perforinas", "d. Th2, con IL-4, IL-5 e IL-13, IgE, eosinófilos y mastocitos", "e. Treg, con IL-10"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Th2: IL-4, IL-5 e IL-13 llevan a IgE y a la activación de eosinófilos y mastocitos.", "sin_banco": true, "ok": "", "x": "Mira la escena de la izquierda: el gusano es demasiado grande para un fagocito, <span class=\"cx\">así que</span> lo atacan <mark>eosinófilos y mastocitos</mark>, el brazo <b>Th2</b> (IL-4, IL-5, IL-13 e IgE). <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN10-010", "c": "g", "tema": "Conceptos", "pregunta": "¿Qué es la «preinmunización» (inmunidad no esterilizante) y en qué parasitosis es característica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es la respuesta inmune que controla la enfermedad clínica sin eliminar todos los parásitos; es típica de malaria, toxoplasmosis y leishmaniasis. Si esa respuesta cae, la infección latente se reactiva.", "sin_banco": true, "ok": "", "x": "La defensa antiparasitaria <mark>rara vez es esterilizante</mark>: mantiene al parásito a raya pero no lo erradica. <span class=\"cx\">Por eso</span>, <span class=\"cx\">cuando</span> la inmunidad celular cae (sida, <span class=\"cx\">por ejemplo</span>), <span class=\"res\">la infección latente se reactiva</span>. No confundir con la <b>inmunidad concomitante</b>: respuesta contra una fase del ciclo y no contra otra.", "truco": "Pre-inmunización = «tregua», no victoria.", "veces": 0}, {"n": 3, "id": "IN10-011", "c": "i", "tema": "Inmunidad innata: eosinófilos", "pregunta": "Describa los dos mecanismos con los que los eosinófilos destruyen parásitos de gran tamaño.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "1) Facilitan la degranulación de los mastocitos, que genera inflamación alrededor del parásito; 2) se degranulan directamente sobre la cutícula del parásito y liberan enzimas que la lesionan, y luego los macrófagos completan la destrucción.", "sin_banco": true, "ok": "", "x": "Son los eosinófilos de la izquierda: se pegan a la <mark>cutícula</mark> y descargan sus gránulos (las zonas erosionadas), y el mastocito vecino inflama alrededor. <span class=\"cx\">Luego</span> <span class=\"res\">los macrófagos terminan el trabajo</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN10-012", "c": "d", "tema": "Enfermedad de Chagas", "pregunta": "El daño cardíaco de la fase crónica de la enfermedad de Chagas se atribuye principalmente a:", "opciones": ["a. La invasión directa del miocardio por tripomastigotes", "b. Una reacción autoinmune por reactividad cruzada con antígenos del parásito", "c. Granulomas inducidos por LT CD4 alrededor de huevos", "d. Una toxina GPI que induce TNF", "e. Depósito de complejos inmunes en los glomérulos"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Una reacción autoinmune: en las autopsias no se hallan parásitos en el miocardio.", "sin_banco": true, "ok": "", "x": "En la fase crónica el miocardio está dañado pero <mark>sin parásitos</mark> en la autopsia. Se hallaron anticuerpos contra un antígeno de <span class=\"res\">160 kDa</span> del <b>T. cruzi</b> que reaccionan en forma cruzada con el tejido nervioso, <span class=\"cx\">así que</span> el megaesófago y el megacolon también son en parte autoinmunes. <span class=\"cx\">Por eso</span> <span class=\"res\">no ver parásitos no descarta el Chagas</span>.", "truco": "Chagas crónico = «el parásito se fue, el anticuerpo se quedó».", "veces": 0}, {"n": 5, "id": "IN10-013", "c": "d", "tema": "Evasión parasitaria", "pregunta": "Trypanosoma brucei (enfermedad del sueño) evade la respuesta de anticuerpos principalmente por:", "opciones": ["a. Localizarse en sitios inmunoprivilegiados", "b. Producir una proteína DAF-like que degrada el C3b", "c. Variación antigénica, con más de 1.000 genes para cambiar sus moléculas de membrana", "d. Producir SCIP, que bloquea el complejo de ataque", "e. Exportar PfEMP1 a la membrana del eritrocito"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Variación antigénica: más de 1.000 genes para cambiar su antígeno de membrana.", "sin_banco": true, "ok": "", "x": "Cada vez que el hospedero fabrica un anticuerpo, el parásito ya <mark>cambió de abrigo</mark>; los ciclos duran unas <span class=\"res\">cuatro semanas</span>. <span class=\"cx\">Además</span>, los complejos inmunes aumentan la permeabilidad de la barrera hematoencefálica y así llega al SNC. La DAF-like es de <b>T. cruzi</b> y la SCIP, de <b>S. mansoni</b>.", "truco": "T. brucei = «mil disfraces».", "veces": 0}, {"n": 6, "id": "IN10-014", "c": "d", "tema": "Toxoplasmosis", "pregunta": "Correlación: un paciente con VIH y recuento muy bajo de LT CD4 que no recibe profilaxis presenta fiebre, cefalea, convulsiones y lesiones cerebrales múltiples. ¿Qué parasitosis se sospecha y por qué se reactivó?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Toxoplasmosis cerebral por reactivación de quistes latentes: la infección se mantenía controlada por preinmunización Th1 y se reactiva al caer la inmunidad celular. Por eso se indica profilaxis en todo VIH con LT CD4 bajos.", "sin_banco": true, "ok": "", "x": "La toxoplasmosis se controla por <mark>preinmunización Th1</mark>, sin erradicar los quistes. <span class=\"cx\">Cuando</span> el VIH destruye a los LT CD4, falta el IFNγ que activa al macrófago y <span class=\"res\">los quistes latentes se reactivan</span> con neumonitis, carditis o encefalitis mortal.", "truco": "Toxo dormido + CD4 caídos = «despierta en el cerebro».", "veces": 0}, {"n": 7, "id": "IN10-015", "c": "d", "tema": "Esquistosomiasis", "pregunta": "En la esquistosomiasis, la hipertensión portal se debe principalmente a:", "opciones": ["a. Granulomas inducidos por LT CD4 alrededor de los huevos depositados en el hígado, seguidos de fibrosis", "b. La obstrucción mecánica de la vena porta por gusanos adultos", "c. Una reacción autoinmune contra el hepatocito", "d. La lisis de hepatocitos por LT CD8", "e. Complejos inmunes depositados en los sinusoides"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Granulomas por LT CD4 alrededor de los huevos en el hígado y la fibrosis que sigue.", "sin_banco": true, "ok": "", "x": "El gusano adulto vive años en la sangre camuflado con <mark>antígenos de grupo sanguíneo y HLA</mark> del hospedero. El daño lo causan sus <b>huevos</b>: los LT CD4 forman granulomas a su alrededor y la <mark>fibrosis</mark> resultante <span class=\"res\">obstruye la circulación portal</span>.", "truco": "Esquisto: «el huevo, no el gusano», hace la cirrosis.", "veces": 0}, {"n": 8, "id": "IN10-016", "c": "i", "tema": "Inmunidad adquirida antiparasitaria", "pregunta": "¿Cómo contribuye la IgE a la expulsión de los parásitos intestinales?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Sensibiliza a los mastocitos intestinales y promueve su degranulación, lo que aumenta el peristaltismo y la secreción intestinal y produce un barrido mecánico del parásito.", "sin_banco": true, "ok": "", "x": "La IgE se fija a los <mark>mastocitos</mark> del intestino; <span class=\"cx\">cuando</span> el antígeno del helminto la entrecruza, el mastocito se degranula. <span class=\"cx\">Así que</span> el intestino se mueve más y secreta más, y <span class=\"res\">el parásito es barrido</span>. La IL-33 ayuda <span class=\"cx\">porque</span> estimula IL-4.", "truco": "IgE = «escoba intestinal».", "veces": 0}, {"n": 9, "id": "IN10-017", "c": "d", "tema": "Leishmaniasis", "pregunta": "Las leishmanias evitan la activación de las enzimas generadoras de radicales del oxígeno del macrófago porque:", "opciones": ["a. Producen una catalasa propia que destruye el H₂O₂", "b. Forman una vacuola que impide la formación del fagosoma", "c. Escapan del fagosoma con una enzima que lisa su membrana", "d. Varían periódicamente sus antígenos de superficie", "e. Usan el complemento para ingresar por una vía distinta de la fagocitosis normal"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Usan el complemento para entrar por una vía distinta a la fagocitosis normal (e inactivan C8 y C9).", "sin_banco": true, "ok": "", "x": "En el centro, el macrófago no activado está lleno de leishmanias (punto Ⓐ): entraron <mark>por el complemento</mark>, una vía que no enciende el estallido respiratorio. Activado por IFNγ, el de al lado sí las destruye. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN10-018", "c": "g", "tema": "Genética y susceptibilidad", "pregunta": "La ausencia del antígeno Duffy en los eritrocitos confiere resistencia natural a:", "opciones": ["a. Plasmodium falciparum", "b. Plasmodium malariae", "c. Plasmodium vivax", "d. Plasmodium ovale", "e. Toxoplasma gondii"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Plasmodium vivax, que necesita la molécula Duffy para entrar al eritrocito.", "sin_banco": true, "ok": "", "x": "La molécula <mark>Duffy</mark> es la puerta del eritrocito para <b>P. vivax</b>; sin ella no puede invadir. <span class=\"cx\">Por eso</span> <span class=\"res\">la población de origen africano, mayoritariamente Duffy negativa, resiste al vivax</span>. <span class=\"cx\">En cambio</span> la hemoglobina S, C o E y la deficiencia de G6PD dificultan a <b>P. falciparum</b>.", "truco": "Duffy ausente = «vivax sin llave».", "veces": 0}, {"n": 11, "id": "IN10-019", "c": "d", "tema": "Fase eritrocítica", "pregunta": "Respecto a la proteína PfEMP1 de Plasmodium falciparum, es CORRECTO:", "opciones": ["a. Forma knobs en la membrana del eritrocito que se adhieren al endotelio y evitan la captura del eritrocito en el bazo", "b. Es una proteína del esporozoíto contra la que se dirige la vacuna sintética de esporozoítos", "c. Es el receptor eritrocitario que usa P. vivax", "d. Es una toxina reconocida por TLR9", "e. Se expresa solo en el hepatocito infectado"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Forma micronódulos (knobs) que se pegan al endotelio y le ahorran al eritrocito el paso por el bazo.", "sin_banco": true, "ok": "", "x": "Es el capilar de la derecha: los <mark>knobs</mark> de PfEMP1 pegan el eritrocito parasitado al endotelio, <span class=\"cx\">así que</span> no pasa por el bazo. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN10-020", "c": "i", "tema": "Fases del ciclo", "pregunta": "¿Por qué los anticuerpos contra esporozoítos son más eficaces que los anticuerpos contra merozoítos?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque los esporozoítos permanecen varios minutos en la sangre tras la picadura, dando tiempo a los anticuerpos, mientras que los merozoítos invaden nuevos eritrocitos en solo segundos.", "sin_banco": true, "ok": "", "x": "El anticuerpo necesita <mark>tiempo de contacto</mark> con el parásito libre. Cada picadura inocula <b>50 a 100 esporozoítos</b> que tardan minutos en llegar al hígado; <span class=\"cx\">en cambio</span> el merozoíto pasa <span class=\"res\">segundos</span> fuera de la célula. Aun así, los anticuerpos que bloquean los knobs aminoran las complicaciones.", "truco": "Esporozoíto = «minutos»; merozoíto = «segundos».", "veces": 0}, {"n": 13, "id": "IN10-021", "c": "d", "tema": "Fase hepática", "pregunta": "¿Qué son los hipnozoítos, qué especies los producen y qué importancia clínica tienen?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Son formas hepáticas latentes de P. vivax y P. ovale, responsables de recaídas clínicas semanas o años después de la curación aparente.", "sin_banco": true, "ok": "", "x": "En la <mark>fase hepática</mark> el parásito se reproduce de 7 a 10 días dentro del hepatocito. <b>P. vivax</b> y <b>P. ovale</b> dejan <span class=\"cx\">además</span> formas dormidas, los <mark>hipnozoítos</mark> (de <b>hypnos</b>, sueño), que despiertan después. <span class=\"cx\">Por eso</span> <span class=\"res\">un paciente «curado» puede recaer meses o años más tarde</span>.", "truco": "Hipnozoíto = «hipnotizado» en el hígado.", "veces": 0}, {"n": 14, "id": "IN10-022", "c": "i", "tema": "Inmunidad adquirida", "pregunta": "¿Qué receptor reconoce la hemozoína, subproducto de la degradación de la hemoglobina, y activa a las células dendríticas en la malaria?", "opciones": ["a. TLR2", "b. TLR4", "c. TLR3", "d. TLR9", "e. TLR5"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. TLR9: activa a la célula dendrítica, induce IL-12 y sobreexpresa CD40 y CD86 para generar Th1.", "sin_banco": true, "ok": "", "x": "La <mark>hemozoína</mark> es el pigmento que deja el parásito al digerir la hemoglobina. El <b>TLR9</b> la reconoce, la célula dendrítica produce IL-12 y madura, y así se generan <span class=\"res\">linfocitos Th1</span>. <span class=\"cx\">En cambio</span> la toxina <b>GPI</b> del plasmodio se reconoce por TLR2 y TLR4 e induce TNF.", "truco": "Hemozoína → «TLR nueve, Th1 se mueve».", "veces": 0}, {"n": 15, "id": "IN10-023", "c": "d", "tema": "Fase hepática", "pregunta": "¿Cuántos merozoítos genera aproximadamente cada hepatocito infectado en la fase hepática de la malaria?", "opciones": ["a. 50 a 100", "b. 1.000", "c. 2.000 a 3.000", "d. 200.000 a 300.000", "e. 20.000 a 30.000"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. De 20.000 a 30.000 merozoítos por célula, protegidos por el merosoma.", "sin_banco": true, "ok": "", "x": "Los <mark>50 a 100</mark> son los esporozoítos que inocula cada picadura. Al llegar al hígado se reproducen asexualmente durante <span class=\"res\">7 a 10 días</span> y cada hepatocito libera <span class=\"res\">20.000 a 30.000 merozoítos</span>, envueltos en el <b>merosoma</b>; los LT CD8 y las NK atacan esa fase.", "truco": "Hígado = «fábrica de 20-30 mil».", "veces": 0}, {"n": 16, "id": "IN10-024", "c": "d", "tema": "Complicaciones", "pregunta": "Correlación: un niño de zona endémica con malaria por P. falciparum presenta fiebre, convulsiones y coma. ¿Qué complicación tiene, cuál es su mecanismo y qué tan grave es?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Malaria cerebral: los eritrocitos parasitados se adhieren al endotelio cerebral por PfEMP1 (receptores activados por IFNα) y forman rosetas que obstruyen el flujo. Afecta al 1 % de los infectados y mata al 10-20 % de ellos.", "sin_banco": true, "ok": "", "x": "Es la escena de la derecha (punto Ⓑ): eritrocitos pegados al endotelio cerebral y una <mark>roseta</mark> que tapa la luz del capilar. Afecta al 1 % de los infectados y <span class=\"res\">mata al 10-20 % de ellos</span>.", "truco": "", "veces": 0}, {"n": 17, "id": "IN10-025", "c": "i", "tema": "Vacunas", "pregunta": "La vacuna desarrollada por el Dr. Manuel E. Patarroyo contra la malaria:", "opciones": ["a. Es sintética, dirigida a las formas intraeritrocíticas, y mostró 35 % de protección en campo", "b. Usa esporozoítos irradiados, al menos mil por dosis", "c. Se dirige a los gametocitos para bloquear la transmisión", "d. Induce solo LT CD8 contra el hepatocito", "e. Es una vacuna de parásitos vivos atenuados"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Primera vacuna sintética para humanos, contra formas intraeritrocíticas, con 35 % de protección en América y África.", "sin_banco": true, "ok": "", "x": "Hay tres líneas: contra <mark>esporozoítos</mark> (péptido repetido o esporozoítos irradiados), contra <mark>formas intraeritrocíticas</mark> y contra <mark>gametocitos</mark> (bloquean la transmisión al mosquito). La de Patarroyo es química, <span class=\"cx\">así que</span> evita conseguir miles de esporozoítos vivos; logró <span class=\"res\">35 % en campo</span> y su nueva fórmula, 90 % en monos <b>Aotus</b>.", "truco": "Patarroyo = «Péptido sintético» contra el eritrocito.", "veces": 0}], "tabla": {"cab": ["", "Protozoos", "Helmintos", "Plasmodium falciparum"], "filas": [["Ejemplos", "Leishmania, Toxoplasma, T. cruzi", "Schistosoma, Ancylostoma, filarias", "Malaria grave"], ["Respuesta", "Th1: IFNγ, óxido nítrico", "Th2: IL-4, IL-5, IL-13, IgE", "Th1 (TLR9-hemozoína) + IgG1/IgG3"], ["Célula efectora", "Macrófago activado", "Eosinófilo y mastocito", "Macrófago, NK, LT CD8"], ["Evasión típica", "Vivir en el macrófago", "Camuflaje con HLA del hospedero", "PfEMP1, variación"], ["🔑 Para diferenciar", "Adentro: IFNγ", "Afuera: IgE y eosinófilo", "Eritrocito pegajoso"]]}, "fuente": "Fuente: tu teoría — clase 23 (Respuesta inmune contra infecciones por parásitos) y clase 24 (Respuesta inmune en malaria), Rojas 17.ª ed."}, {"n": 19, "slug": "Hongos_y_candidiasis", "titulo": "Hongos y candidiasis", "subtitulo": "del macrófago alveolar a la red del neutrófilo y el Th17 de la mucosa", "grupo": "g11", "lema": "La idea: respiramos y tragamos hongos todos los días y casi nunca enfermamos, porque la <mark>inmunidad innata</mark> los frena. El macrófago alveolar se come la <b>conidia</b> antes de que germine; si se convierte en <b>hifa</b>, ya no cabe y el neutrófilo la enreda con sus <b>NETs</b>. La defensa de fondo es celular: el <mark>Th1</mark> (IFNγ y TNF) activa al macrófago y el <mark>Th17</mark> (IL-17) protege las mucosas; en cambio el <b>Th2</b> empeora la micosis. Por eso los hongos son marcadores de inmunodeficiencia: Pneumocystis, Cryptococcus o Candida esofágica obligan a descartar sida. En la imagen verás, de izquierda a derecha: un alveolo con su macrófago, una hifa atrapada por neutrófilos y una mucosa donde Candida pasa de levadura a hifa invasora.", "img": "img/19.webp", "mini": "img/mini/19.webp", "ratio": 1.5, "etiquetas": [{"n": "③⑧", "t": "Macrófago alveolar", "s": "come la conidia<br>antes de germinar", "c": "i", "x": 0.5, "y": 6, "ax": 12, "ay": 48, "al": "l"}, {"n": "②⑫", "t": "Neutrófilo", "s": "las hifas lo atraen;<br>radicales del O₂", "c": "i", "x": 30, "y": 6, "ax": 36, "ay": 31}, {"n": "③", "t": "Trampas NETs", "s": "calprotectina<br>quita el zinc", "c": "i", "x": 49, "y": 6, "ax": 46, "ay": 37}, {"n": "⑨⑩", "t": "Levaduras", "s": "Candida comensal<br>(blastoconidias)", "c": "d", "x": 68, "y": 6, "ax": 76, "ay": 30, "d": "A"}, {"n": "⑪⑯", "t": "Hifa que invade", "s": "adhesinas; mananos<br>tapan el glucano", "c": "d", "x": 99.5, "y": 6, "ax": 86.5, "ay": 40, "al": "r"}, {"n": "⑦", "t": "Alveolo", "s": "Pneumocystis:<br>CD4 bajo 200", "c": "g", "x": 0.5, "y": 91, "ax": 6, "ay": 72, "d": "B", "al": "l"}, {"n": "③⑤⑧", "t": "Hongo en el fagosoma", "s": "Histoplasma, Cripto<br>sobreviven dentro", "c": "d", "x": 25, "y": 91, "ax": 15.3, "ay": 57, "d": "C"}, {"n": "⑮", "t": "Epitelio mucoso", "s": "vagina: neutrófilos<br>agresivos", "c": "g", "x": 47, "y": 91, "ax": 70, "ay": 46, "d": "D"}, {"n": "④⑬⑭", "t": "Th17 / Th1", "s": "IL-17 e IFNγ protegen;<br>Th2 empeora", "c": "i", "x": 69, "y": 91, "ax": 72.5, "ay": 67}, {"n": "⑧", "t": "Macrófago activado", "s": "IFNγ y TNF:<br>fungistasis", "c": "i", "x": 99.5, "y": 91, "ax": 91, "ay": 64, "al": "r"}], "diapos": [{"img": "img/19.webp", "ratio": 1.5, "titulo": "Hongos: alveolo, hifa y mucosa", "texto": "El <mark>macrófago</mark> se come la conidia; la hifa no cabe, <span class=\"cx\">así que</span> el <mark>neutrófilo</mark> la enreda con NETs ②③; en la mucosa manda el <b>Th17</b> ⑬.", "etiquetas": [{"n": "③⑧", "t": "Macrófago alveolar", "s": "come la conidia<br>antes de germinar", "c": "i", "x": 0.5, "y": 6, "ax": 12, "ay": 48, "al": "l"}, {"n": "②⑫", "t": "Neutrófilo", "s": "las hifas lo atraen;<br>radicales del O₂", "c": "i", "x": 30, "y": 6, "ax": 36, "ay": 31}, {"n": "③", "t": "Trampas NETs", "s": "calprotectina<br>quita el zinc", "c": "i", "x": 49, "y": 6, "ax": 46, "ay": 37}, {"n": "⑨⑩", "t": "Levaduras", "s": "Candida comensal<br>(blastoconidias)", "c": "d", "x": 68, "y": 6, "ax": 76, "ay": 30, "d": "A"}, {"n": "⑪⑯", "t": "Hifa que invade", "s": "adhesinas; mananos<br>tapan el glucano", "c": "d", "x": 99.5, "y": 6, "ax": 86.5, "ay": 40, "al": "r"}, {"n": "⑦", "t": "Alveolo", "s": "Pneumocystis:<br>CD4 bajo 200", "c": "g", "x": 0.5, "y": 91, "ax": 6, "ay": 72, "d": "B", "al": "l"}, {"n": "③⑤⑧", "t": "Hongo en el fagosoma", "s": "Histoplasma, Cripto<br>sobreviven dentro", "c": "d", "x": 25, "y": 91, "ax": 15.3, "ay": 57, "d": "C"}, {"n": "⑮", "t": "Epitelio mucoso", "s": "vagina: neutrófilos<br>agresivos", "c": "g", "x": 47, "y": 91, "ax": 70, "ay": 46, "d": "D"}, {"n": "④⑬⑭", "t": "Th17 / Th1", "s": "IL-17 e IFNγ protegen;<br>Th2 empeora", "c": "i", "x": 69, "y": 91, "ax": 72.5, "ay": 67}, {"n": "⑧", "t": "Macrófago activado", "s": "IFNγ y TNF:<br>fungistasis", "c": "i", "x": 99.5, "y": 91, "ax": 91, "ay": 64, "al": "r"}]}, {"img": "img/19_2.webp", "ratio": 1.5, "titulo": "Cómo se esconden los hongos", "texto": "Candida tapa el glucano con <mark>mananos</mark> y la dectina-1 no la ve ⑯; Cryptococcus suelta su <mark>cápsula de GXM</mark> ⑤; el estradiol frena al Paracoccidioides ⑥.", "etiquetas": [{"n": "⑯", "t": "Mananos", "s": "cubren la pared<br>de la hifa", "c": "d", "x": 10, "y": 6, "ax": 16.3, "ay": 22.5}, {"n": "⑤", "t": "Cápsula de GXM", "s": "halo de<br>polisacárido", "c": "g", "x": 34, "y": 6, "ax": 37.0, "ay": 30.0}, {"n": "⑤", "t": "GXM liberado", "s": "induce IL-10,<br>frena el IFN-γ", "c": "g", "x": 56, "y": 6, "ax": 58.6, "ay": 34.5}, {"n": "⑥", "t": "Estradiol", "s": "bloquea su<br>receptor", "c": "d", "x": 72, "y": 6, "ax": 70.6, "ay": 42.5}, {"n": "⑥", "t": "Multigemante", "s": "levadura en<br>timón de barco", "c": "g", "x": 99.5, "y": 6, "ax": 91.0, "ay": 40.0, "al": "r"}, {"n": "⑯", "t": "Glucano oculto", "s": "β-glucano<br>bajo los mananos", "c": "d", "x": 0.5, "y": 92, "ax": 9.0, "ay": 38.0, "al": "l"}, {"n": "⑯", "t": "Dectina-1", "s": "no alcanza<br>el glucano", "c": "i", "x": 23, "y": 92, "ax": 19.9, "ay": 62.0}, {"n": "⑯", "t": "Levadura", "s": "glucano expuesto:<br>sí se reconoce", "c": "i", "x": 40, "y": 92, "ax": 30.0, "ay": 47.0}, {"n": "⑤", "t": "Macrófago quieto", "s": "no se activa", "c": "i", "x": 62, "y": 92, "ax": 66.0, "ay": 70.0}, {"n": "⑥", "t": "Conidia que crece", "s": "pasa a levadura<br>(sin estradiol)", "c": "g", "x": 82, "y": 92, "ax": 78.8, "ay": 47.0}]}, {"img": "img/19_3.webp", "ratio": 1.5, "titulo": "Del comensal a la micosis oportunista", "texto": "El <b>oportunista</b> solo enferma al inmunocomprometido ①: muguet, candidiasis mucocutánea por falla del <mark>eje IL-17</mark> ⑭ y neumocistosis con CD4 <span class=\"lt2\">B</span> ⑦.", "etiquetas": [{"n": "①⑨", "t": "Muguet oral", "s": "placas blancas<br>que se desprenden", "c": "g", "x": 10, "y": 6, "ax": 8.5, "ay": 34.0}, {"n": "⑭", "t": "Uñas engrosadas", "s": "onicomicosis por<br>Candida", "c": "d", "x": 38, "y": 6, "ax": 39.7, "ay": 29.0}, {"n": "⑦", "t": "Infiltrado bilateral", "s": "neumonía por<br>P. jirovecii", "c": "i", "x": 62, "y": 6, "ax": 60.5, "ay": 41.0, "d": "B"}, {"n": "⑦", "t": "Quistes en el alveolo", "s": "exudado<br>espumoso", "c": "i", "x": 88, "y": 6, "ax": 90.0, "ay": 44.0}, {"n": "⑨", "t": "Mucosa roja", "s": "debajo de<br>la placa", "c": "d", "x": 14, "y": 92, "ax": 18.9, "ay": 50.8}, {"n": "⑭", "t": "Placas en la piel", "s": "candidiasis<br>mucocutánea crónica", "c": "d", "x": 36, "y": 92, "ax": 35.0, "ay": 62.5}, {"n": "⑭", "t": "Pliegue ungueal", "s": "paroniquia<br>(falla IL-17)", "c": "d", "x": 56, "y": 92, "ax": 49.2, "ay": 38.0}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa del hospedero</b> (fagocitos, NETs, linfocitos), <b class=\"d\">rojo = el hongo y su virulencia</b>, gris = tejidos de referencia.", "<b>Izquierda:</b> el macrófago alveolar fagocita las conidias de Aspergillus antes de que germinen. Los <mark>dimórficos</mark> (Histoplasma, Blastomyces, Paracoccidioides) y Cryptococcus, <span class=\"cx\">en cambio</span>, sobreviven dentro del fagosoma <span class=\"lt2\">C</span> hasta que el linfocito T activa al macrófago.", "<b>Centro:</b> la hifa es demasiado grande para fagocitarla, <span class=\"cx\">así que</span> el neutrófilo lanza <mark>NETs</mark> con calprotectina. Es eficaz contra <b>Aspergillus, Candida y Rhizopus</b>, no contra los dimórficos.", "<b>Derecha:</b> Candida coloniza como levadura <span class=\"lt2\">A</span>; <span class=\"cx\">cuando</span> <mark>germina a hifa</mark>, se pega con adhesinas, invade el epitelio y atrae neutrófilos. Debajo, el Th17 (sostenido por la IL-23) y el macrófago activado por IFNγ la contienen."], "recordar": "Conidia → macrófago; hifa → neutrófilo con NETs; dimórfico → macrófago activado por Th1. En mucosas manda el <b>Th17</b>; el <b>Th2</b> disemina."}, "numeros": [{"l": "A", "html": "<b>Candida</b> es el <b class=\"a\">4.º</b> agente de septicemia nosocomial (cerca del <b class=\"a\">9 %</b>); <b>C. albicans</b> da el <b class=\"n\">37-40 %</b> de los aislamientos.", "rango": null}, {"l": "B", "html": "<b>Pneumocystis</b> infecta a más del <b class=\"n\">95 %</b> de la población; profilaxis con trimetoprim-sulfametoxazol si los CD4 bajan de <b class=\"b\">200/mm³</b>.", "rango": {"min": 0, "max": 1000, "unidad": "LT CD4+/µL", "zonas": [[0, 200, "a"], [200, 500, "m"], [500, 1000, "n"]], "marcas": [200, 500], "valor": 150}}, {"l": "C", "html": "<b>Histoplasmosis</b>: se resuelve sola en el <b class=\"n\">90-95 %</b>. <b>Paracoccidioidomicosis</b>: hombre:mujer hasta <b class=\"a\">70:1</b> (el estradiol protege).", "rango": null}, {"l": "D", "html": "<b>Vulvovaginitis por Candida</b>: afecta al <b class=\"a\">50-70 %</b> de las mujeres al menos una vez en la vida.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la conidia a la micosis", "subtitulo": "estímulo → células → mecanismo → resultado → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> se inhalan conidias (Aspergillus, Histoplasma, Cryptococcus) o <b>Candida</b> comensal pierde el control y <mark>germina a hifa</mark>.", "pr": "el hongo expone β-glucanos y mananos (PAMP).", "pr_tit": "Produce:", "rf": "Preguntas ①⑨⑪ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Reconocimiento", "m": "<b>Por qué:</b> la <mark>dectina-1</mark>, el receptor de manosa y los TLR-2/4 detectan los PAMP; el inflamasoma NLRP3 libera IL-1β. Candida tapa el glucano con mananos para esconderse.", "pr": "se encienden los fagocitos y la inflamación temprana.", "pr_tit": "Produce:", "rf": "Preguntas ⑯⑰", "color": "p2"}, {"t": "3. Innata", "m": "<b>Qué produce:</b> el macrófago alveolar come la conidia; las hifas atraen al <mark>neutrófilo</mark>, que las ataca con radicales y NETs con calprotectina.", "pr": "Aspergillus, Candida y Rhizopus se controlan; los dimórficos resisten.", "pr_tit": "Produce:", "rf": "Preguntas ②③⑫", "color": "p3"}, {"t": "4. Adquirida", "m": "<b>Por qué:</b> la DC produce IL-12 → <mark>Th1</mark> (IFNγ, TNF) que activa al macrófago; la IL-23 sostiene al <mark>Th17</mark> (IL-17) en las mucosas.", "pr": "fungistasis y granuloma; mucosa protegida.", "pr_tit": "Produce:", "rf": "Preguntas ④⑬ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Si falla", "m": "<b>Qué pasa:</b> sida (CD4 bajos), esteroides, neutropenia, diabetes, anti-TNF o defectos del eje IL-17 dejan pasar al hongo; un perfil <mark>Th2/Th3</mark> (IL-4, IL-10, TGF-β) bloquea la fagocitosis.", "pr": "neumocistosis, criptococosis meníngea, candidiasis invasora o mucocutánea crónica.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑧⑭⑮ · punto <span class=\"lt2\">B</span>", "color": "p4"}], "extra": [{"html": "🍄 <b>Trucos de evasión:</b> catalasa y melanina contra los radicales; cápsula de <b>GXM</b> que sube IL-10 (Cryptococcus); CBP1 y bloqueo de la acidificación del fagosoma (Histoplasma); <b>CRASP</b> contra el complemento y <b>flavohemoglobina Ynb1p</b> contra el óxido nítrico (Candida).", "k": ""}, {"html": "💊 Los antimicóticos también hablan con los TLR: anfotericina B (TLR-1, 2, 4), equinocandinas (TLR-2/dectina-1, 4, 9) y azoles (TLR-2, 4, 9). En candidiasis se ensayaron GM-CSF, G-CSF e IFNγ como terapia inmunomoduladora.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De comensal a invasora (Candida)", "pasos": ["levadura comensal en la mucosa", "factor de riesgo: antibióticos, diabetes, catéter, sida", "<b>germina a hifa</b> con adhesinas", "invade el epitelio y entra al vaso", "<b>candidemia</b>: 4.º agente de sepsis nosocomial"]}], "html": "", "fuente": "Fuente: tu teoría — clase 25 (respuesta innata y adquirida, micosis con particularidades inmunológicas, evasión y antimicóticos) y clase 26 (ecología, respuesta según forma clínica, evasión y terapia inmunomoduladora)."}, "preguntas": [{"n": 1, "id": "IN11-001", "c": "g", "tema": "Generalidades", "pregunta": "¿Qué diferencia a un hongo «oportunista» de un hongo «patógeno»?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El oportunista solo enferma al inmunocomprometido; el patógeno puede enfermar incluso al inmunocompetente.", "sin_banco": true, "ok": "", "x": "Convivimos con los hongos del ambiente y rara vez enfermamos, <span class=\"cx\">porque</span> la inmunidad innata suele bastar. <span class=\"cx\">Por eso</span> los <mark>oportunistas</mark> (Aspergillus, Candida, Cryptococcus) solo invaden <span class=\"cx\">cuando</span> el hospedero cae; <span class=\"cx\">en cambio</span> los <span class=\"res\">patógenos</span> (Histoplasma, Coccidioides, Paracoccidioides) infectan también al sano.", "truco": "Oportunista = «aprovecha la ocasión» (la defensa baja).", "veces": 0}, {"n": 2, "id": "IN11-002", "c": "i", "tema": "Respuesta innata", "pregunta": "Los neutrófilos son eficaces, mediante radicales del oxígeno, contra todos los siguientes hongos, EXCEPTO:", "opciones": ["a. Aspergillus fumigatus", "b. Candida albicans", "c. Histoplasma capsulatum", "d. Rhizopus", "e. Ninguno: los mata a todos por igual"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Histoplasma capsulatum: es dimórfico y el neutrófilo no lo controla; necesita macrófagos activados por linfocitos T.", "sin_banco": true, "ok": "", "x": "El neutrófilo del centro de la imagen ataca a la hifa de <mark>Aspergillus</mark>, Candida o Rhizopus con radicales. <span class=\"cx\">En cambio</span> Histoplasma vive dentro del macrófago (punto Ⓒ) y solo cae <span class=\"cx\">cuando</span> el Th1 lo activa. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN11-003", "c": "i", "tema": "Aspergilosis", "pregunta": "Si las conidias inhaladas de Aspergillus escapan al macrófago alveolar y forman hifas, ¿cómo las ataca el neutrófilo?", "opciones": ["a. Formando trampas extracelulares (NETs) con calprotectina", "b. Fagocitando la hifa completa", "c. Produciendo IgE contra la pared fúngica", "d. Activando la vía clásica del complemento con IgM", "e. Liberando perforina como la célula NK"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Formando trampas extracelulares (NETs) reforzadas por calprotectina, que quela el zinc que el hongo necesita.", "sin_banco": true, "ok": "", "x": "Es la red lila que envuelve la hifa en el centro: las <mark>NETs con calprotectina</mark> quitan el zinc. La hifa no cabe en el fagocito, <span class=\"cx\">así que</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN11-004", "c": "i", "tema": "Inmunidad celular", "pregunta": "En las micosis, ¿qué perfil de linfocitos T es perjudicial y con qué cuadro se asocia?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El perfil Th2: se asocia a formas graves y diseminadas y a la aspergilosis broncopulmonar alérgica.", "sin_banco": true, "ok": "", "x": "El perfil protector es <mark>Th1</mark>, <span class=\"cx\">porque</span> el IFNγ y el TNF activan al macrófago (fungistasis); el Th17 y el Th22 protegen las mucosas. <span class=\"cx\">En cambio</span> el <span class=\"res\">Th2 empeora la micosis</span>, al revés que en los helmintos, donde el Th2 sí protege.", "truco": "En hongos «1 sí, 2 no»: Th1 protege, Th2 disemina.", "veces": 0}, {"n": 5, "id": "IN11-005", "c": "d", "tema": "Criptococosis", "pregunta": "Respecto a Cryptococcus neoformans, es FALSO:", "opciones": ["a. Su principal manifestación es una meningitis con frecuencia fatal.", "b. Puede escapar del macrófago por vomocitosis.", "c. Su melanina neutraliza péptidos antimicrobianos.", "d. El GXM circulante estimula la producción de IFN y la inmunidad celular.", "e. Puede entrar al SNC dentro de fagocitos («caballo de Troya»)."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Es falso: el GXM no estimula la inmunidad celular; induce IL-10 y frena el IFN, deteniéndola.", "sin_banco": true, "ok": "", "x": "La <mark>cápsula de glucoronoxilomanano (GXM)</mark> es antifagocítica e inmunosupresora: el GXM circulante sube la IL-10 y baja el IFN. Dentro del macrófago puede proliferar o salir por <b>vomocitosis</b>, y llega al SNC por el endotelio o como <span class=\"res\">caballo de Troya</span>.", "truco": "Cripto «se esconde en su abrigo» (cápsula) y viaja en caballo de Troya.", "veces": 0}, {"n": 6, "id": "IN11-006", "c": "d", "tema": "Paracoccidioidomicosis", "pregunta": "¿Por qué la paracoccidioidomicosis es hasta 70 veces más frecuente en hombres que en mujeres?", "opciones": ["a. Porque la testosterona estimula la fagocitosis", "b. Por un receptor fúngico para el 17-β-estradiol que impide la transformación a levadura", "c. Porque las mujeres producen más IgA en el pulmón", "d. Por mayor expresión de HLA-DR en mujeres", "e. Porque el hongo solo se transmite por vía sexual"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Porque el hongo tiene un receptor para el 17-β-estradiol que impide la transformación de conidia a levadura.", "sin_banco": true, "ok": "", "x": "Mira el punto Ⓒ: el estradiol se une a un receptor del propio hongo y le impide pasar de conidia a levadura. <span class=\"cx\">Por eso</span> la relación llega a <mark>70:1</mark> y <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN11-007", "c": "g", "tema": "Pneumocistosis", "pregunta": "Paciente con VIH y recuento de LT CD4 de 150/mm³ sin profilaxis. ¿Qué infección fúngica se busca prevenir y con qué fármaco?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Neumonía por Pneumocystis jirovecii; se indica trimetoprim-sulfametoxazol cuando los CD4 caen por debajo de 200/mm³.", "sin_banco": true, "ok": "", "x": "Pneumocystis infecta a <mark>más del 95 %</mark> de la población sin enfermarla, <span class=\"cx\">porque</span> la inmunidad celular (CD4 y CD8) lo controla. <span class=\"cx\">Cuando</span> los CD4 bajan de <span class=\"res\">200/mm³</span>, produce neumonía grave; <span class=\"cx\">por eso</span> se da <b>trimetoprim-sulfametoxazol</b> como profilaxis.", "truco": "«Bajo 200, TMP-SMX».", "veces": 0}, {"n": 8, "id": "IN11-008", "c": "i", "tema": "Correlato clínico", "pregunta": "Paciente con artritis reumatoide que recibe un bloqueador del TNF desarrolla fiebre y lesiones pulmonares; vive en zona endémica de histoplasmosis. ¿Qué mecanismo explica el cuadro?", "opciones": ["a. Hipersensibilidad tipo I contra esporas", "b. Déficit de complemento por consumo", "c. Aspergilosis por neutropenia", "d. Candidiasis por exceso de IL-17", "e. Reactivación de histoplasmosis por falta de activación del macrófago"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Reactivación de histoplasmosis: sin TNF el macrófago no se activa para destruir la levadura intracelular.", "sin_banco": true, "ok": "", "x": "El hongo que sobrevive en el fagosoma (punto Ⓒ) solo muere <span class=\"cx\">cuando</span> el macrófago se activa (abajo a la derecha) con <mark>IFNγ y TNF</mark>. Si bloqueas el TNF, <span class=\"res\">se reactiva la histoplasmosis</span>: la e.", "truco": "", "veces": 0}, {"n": 9, "id": "IN11-009", "c": "d", "tema": "Generalidades", "pregunta": "¿Por qué se llama a la candidiasis «la enfermedad del enfermo»?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque Candida es un comensal de mucosas que solo invade cuando el hospedero pierde el control inmunológico.", "sin_banco": true, "ok": "", "x": "Candida vive en la boca, la vagina y el intestino sin dañar al sano. <span class=\"cx\">Por eso</span>, <span class=\"cx\">cuando</span> aparece una candidiasis frecuente o grave, es <mark>señal de deterioro inmune</mark>: es el <span class=\"res\">oportunista por excelencia</span> y ocupa el cuarto lugar en la septicemia nosocomial.", "truco": "", "veces": 0}, {"n": 10, "id": "IN11-010", "c": "d", "tema": "Epidemiología", "pregunta": "Entre los agentes de septicemia nosocomial, Candida ocupa el lugar:", "opciones": ["a. Primero", "b. Segundo", "c. Tercero", "d. Cuarto", "e. Décimo"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Cuarto, después del estafilococo coagulasa positivo, S. aureus y Enterococcus; causa cerca del 9 % de esos casos.", "sin_banco": true, "ok": "", "x": "Es un dato de examen: <mark>cuarto lugar y 9 %</mark>. Entre las especies, <b>C. albicans</b> es la más frecuente (<span class=\"res\">37-40 %</span>), seguida de <b>C. parapsilosis</b> y <b>C. glabrata</b>, que importan <span class=\"cx\">porque</span> responden distinto a los antifúngicos.", "truco": "Candida «4 × 9»: cuarta y 9 %.", "veces": 0}, {"n": 11, "id": "IN11-011", "c": "d", "tema": "Virulencia", "pregunta": "¿Qué cambio morfológico debe sufrir Candida albicans para pasar de comensal a invasora?", "opciones": ["a. Formar una cápsula de polisacárido", "b. Germinar de blastoconidia a hifa", "c. Convertirse en esférula con endosporas", "d. Producir melanina en la pared", "e. Formar conidias aéreas"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Germinar de blastoconidia (levadura) a forma filamentosa (hifas), con adhesinas para laminina y fibronectina.", "sin_banco": true, "ok": "", "x": "Arriba a la derecha una levadura brota y se alarga en <mark>hifa</mark> que se mete entre las células del epitelio. Esa transformación es el paso a invasora: <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN11-012", "c": "i", "tema": "Respuesta innata", "pregunta": "¿Qué forma de Candida induce la quimiotaxis de los neutrófilos y por qué importa?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Solo las hifas, no las levaduras; así la respuesta neutrofílica se concentra en la forma invasiva que daña los tejidos.", "sin_banco": true, "ok": "", "x": "El neutrófilo «discrimina»: las <mark>hifas lo atraen</mark> y las levaduras no. Destruye las blastoconidias por mecanismos oxidativos, daña los seudomicelios y forma NETs con <b>calprotectina</b>, que le quita manganeso y zinc al hongo. <span class=\"cx\">Por eso</span> <span class=\"res\">ataca justo la forma peligrosa</span>.", "truco": "", "veces": 0}, {"n": 13, "id": "IN11-013", "c": "i", "tema": "Respuesta adquirida", "pregunta": "En el control de la candidiasis de mucosas, la IL-23 cumple la función de:", "opciones": ["a. Mantener a los linfocitos Th17", "b. Inducir el cambio de clase a IgE", "c. Activar a los eosinófilos", "d. Suprimir a los neutrófilos", "e. Inducir perfil Th2 protector"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Mantener a los linfocitos Th17, que tienen el papel predominante en la defensa mucosa contra Candida.", "sin_banco": true, "ok": "", "x": "El linfocito de abajo libera citoquinas hacia el epitelio: es el <mark>Th17</mark> que la IL-23 mantiene. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 14, "id": "IN11-014", "c": "i", "tema": "Formas clínicas", "pregunta": "Niño con candidiasis de piel, uñas y boca recurrente desde la infancia, sin otras infecciones graves. El estudio genético muestra deficiencia autosómica recesiva completa del receptor de IL-17A. ¿Qué diagnóstico y qué eje inmune falla?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Candidiasis mucocutánea crónica: falla la inmunidad celular del eje Th17 (IL-17A/IL-17F).", "sin_banco": true, "ok": "", "x": "Hay dos causas genéticas: deficiencia <mark>AR completa del IL-17RA</mark> y deficiencia AD parcial de IL-17F. Ambas muestran que la IL-17 es esencial en la piel y las mucosas, <span class=\"cx\">porque</span> el niño solo sufre Candida. <span class=\"cx\">Así que</span> <span class=\"res\">un defecto de un solo eje da una susceptibilidad selectiva</span>.", "truco": "", "veces": 0}, {"n": 15, "id": "IN11-015", "c": "g", "tema": "Formas clínicas", "pregunta": "Respecto a la respuesta inmune según la forma clínica de candidiasis, es FALSO:", "opciones": ["a. La candidiasis invasora se asocia a perfil Th2 y Th3 (IL-4, IL-10, TGF-β).", "b. La orofaríngea se asocia a déficit salival de β-defensina-2 e histatinas.", "c. La mucocutánea crónica se debe a un defecto de la inmunidad celular, sobre todo Th17.", "d. La anemia ferropénica desvía el balance hacia Th2 en la vulvovaginitis.", "e. La vulvovaginitis se debe principalmente a una falla de la respuesta Th1."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es falso: la vulvovaginitis no se debe a falla Th1; se asocia a una respuesta agresiva de neutrófilos en el lumen vaginal.", "sin_banco": true, "ok": "", "x": "El paradigma cambió: la vulvovaginitis (<mark>50-70 %</mark> de las mujeres alguna vez) se asocia a neutrófilos agresivos, y la protección vaginal es <b>no inflamatoria</b>. <span class=\"cx\">En cambio</span> la orofaríngea se asocia a falta de β-defensina-2 e histatinas, y la invasora a un <span class=\"res\">perfil Th2/Th3 (IL-4, IL-10, TGF-β)</span> que bloquea la fagocitosis.", "truco": "Vagina: «demasiados neutrófilos», no «poco Th1».", "veces": 0}, {"n": 16, "id": "IN11-016", "c": "d", "tema": "Evasión", "pregunta": "¿Cómo evita Candida, en su fase de hifa, ser reconocida por la dectina-1?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Reemplaza los glucanos de su pared por mananos, ocultando el β-glucano que la dectina-1 reconoce.", "sin_banco": true, "ok": "", "x": "La dectina-1 es el sensor de <mark>β-glucanos</mark>. Al cubrirlos con mananos, la hifa enmascara su PAMP. <span class=\"cx\">Además</span> usa <b>CRASP</b> contra el complemento, la <b>flavohemoglobina Ynb1p</b> que convierte el óxido nítrico en nitratos, y señales por CR3 que <span class=\"res\">apagan la vía proinflamatoria del TLR-4</span>.", "truco": "Se pone un «disfraz de manano» sobre el glucano.", "veces": 0}, {"n": 17, "id": "IN11-017", "c": "d", "tema": "Evasión", "pregunta": "La proteína de Candida que convierte el óxido nítrico en nitratos inofensivos es:", "opciones": ["a. Las CRASP", "b. La adhesina HWP1", "c. La flavohemoglobina Ynb1p", "d. La N-caderina", "e. La catalasa de pared"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. La flavohemoglobina Ynb1p.", "sin_banco": true, "ok": "", "x": "El óxido nítrico es un arma del fagocito. Candida fabrica la <mark>flavohemoglobina Ynb1p</mark> que lo desactiva. <span class=\"cx\">En cambio</span> las <b>CRASP</b> captan reguladores del complemento y las <b>N-caderinas</b> le sirven para <span class=\"res\">entrar en el endotelio por endocitosis</span>.", "truco": "Ynb1p: «Y No Basta el NO».", "veces": 0}], "tabla": {"cab": ["", "Aspergillus", "Histoplasma", "Cryptococcus", "Candida"], "filas": [["Puerta", "Inhalada (conidia)", "Inhalada (microconidia)", "Inhalada", "Comensal de mucosas"], ["Quién la frena", "Macrófago y luego neutrófilo (NETs)", "Macrófago activado por IFNγ y TNF", "Macrófago y NK; Th1", "Neutrófilo y Th17 (IL-17)"], ["Truco del hongo", "Hifa demasiado grande", "Impide acidificar el fagosoma (CBP1)", "Cápsula de GXM, melanina, vomocitosis", "Mananos tapan el glucano; CRASP"], ["Riesgo", "Neutropenia, esteroides", "Anti-TNF, sida", "Sida: meningitis", "Antibióticos, diabetes, catéter"], ["🔑 Para diferenciar", "Hifa → neutrófilo", "Dimórfico → Th1", "Cápsula → meninge", "Mucosa → Th17"]]}, "fuente": "Fuente: tu teoría — clase 25 (Respuesta inmune contra las infecciones por hongos) y clase 26 (Candidiasis), Rojas 17.ª ed."}, {"n": 20, "slug": "Sepsis_y_trauma", "titulo": "Sepsis y trauma", "subtitulo": "cuando la respuesta del hospedero, y no el germen, causa el daño", "grupo": "g11", "lema": "La idea: en la sepsis el problema ya no es solo el microbio sino <mark>la hiperrespuesta del hospedero</mark>. El complemento se desboca y el exceso de <b>C5a</b> paraliza al neutrófilo; los macrófagos vuelcan <b>TNF e IL-1</b> que dañan el endotelio, y aparecen la fuga de plasma (choque) y los microtrombos (CID). Después llega la paradoja: las caspasas matan linfocitos por <b>apoptosis</b> y el paciente queda inmunodeficiente. El trauma grave sigue el mismo guion, iniciado por las <b>alarminas</b> del tejido roto. Por eso el tratamiento busca frenar la inflamación, la coagulación y la inmunodepresión, no solo matar al germen. En la imagen verás, de izquierda a derecha: bacterias, complemento, un neutrófilo paralizado y un macrófago; un vaso con endotelio roto y microtrombos; y un linfocito que termina en cuerpos apoptóticos.", "img": "img/20.webp", "mini": "img/mini/20.webp", "ratio": 1.5, "etiquetas": [{"n": "①", "t": "Bacterias", "s": "infección grave<br>o resistente", "c": "g", "x": 0.5, "y": 6, "ax": 3.5, "ay": 35, "d": "A", "al": "l"}, {"n": "②⑥", "t": "C5a en exceso", "s": "complemento<br>desbocado", "c": "d", "x": 49, "y": 6, "ax": 28, "ay": 53}, {"n": "③⑦", "t": "Macrófago activado", "s": "TNF e IL-1;<br>en trauma, alarminas", "c": "i", "x": 27, "y": 6, "ax": 20, "ay": 40}, {"n": "③⑤", "t": "Microtrombo", "s": "fibrina y<br>plaquetas: CID", "c": "d", "x": 69, "y": 6, "ax": 44, "ay": 42}, {"n": "④⑨", "t": "Cuerpos apoptóticos", "s": "inmunodeficiencia<br>secundaria", "c": "d", "x": 99.5, "y": 6, "ax": 97, "ay": 51, "al": "r"}, {"n": "②⑧", "t": "Neutrófilo paralizado", "s": "C5aR ocupado; NADPH<br>oxidasa apagada", "c": "i", "x": 0.5, "y": 91, "ax": 10, "ay": 60, "al": "l"}, {"n": "③", "t": "Endotelio dañado", "s": "brechas entre<br>células", "c": "d", "x": 33, "y": 91, "ax": 52, "ay": 55}, {"n": "⑧", "t": "Fuga de plasma", "s": "choque;<br>SDRA en el pulmón", "c": "d", "x": 52, "y": 91, "ax": 58, "ay": 68}, {"n": "④", "t": "Linfocito T", "s": "las caspasas lo<br>llevan a apoptosis", "c": "i", "x": 73, "y": 91, "ax": 73, "ay": 50}], "diapos": [{"img": "img/20.webp", "ratio": 1.5, "titulo": "Sepsis: complemento, vaso y apoptosis", "texto": "El <b>C5a</b> paraliza al neutrófilo ②, el endotelio dañado hace <mark>CID</mark> ③ y la apoptosis de linfocitos deja <mark>inmunodeficiencia</mark> ④.", "etiquetas": [{"n": "①", "t": "Bacterias", "s": "infección grave<br>o resistente", "c": "g", "x": 0.5, "y": 6, "ax": 3.5, "ay": 35, "d": "A", "al": "l"}, {"n": "②⑥", "t": "C5a en exceso", "s": "complemento<br>desbocado", "c": "d", "x": 49, "y": 6, "ax": 28, "ay": 53}, {"n": "③⑦", "t": "Macrófago activado", "s": "TNF e IL-1;<br>en trauma, alarminas", "c": "i", "x": 27, "y": 6, "ax": 20, "ay": 40}, {"n": "③⑤", "t": "Microtrombo", "s": "fibrina y<br>plaquetas: CID", "c": "d", "x": 69, "y": 6, "ax": 44, "ay": 42}, {"n": "④⑨", "t": "Cuerpos apoptóticos", "s": "inmunodeficiencia<br>secundaria", "c": "d", "x": 99.5, "y": 6, "ax": 97, "ay": 51, "al": "r"}, {"n": "②⑧", "t": "Neutrófilo paralizado", "s": "C5aR ocupado; NADPH<br>oxidasa apagada", "c": "i", "x": 0.5, "y": 91, "ax": 10, "ay": 60, "al": "l"}, {"n": "③", "t": "Endotelio dañado", "s": "brechas entre<br>células", "c": "d", "x": 33, "y": 91, "ax": 52, "ay": 55}, {"n": "⑧", "t": "Fuga de plasma", "s": "choque;<br>SDRA en el pulmón", "c": "d", "x": 52, "y": 91, "ax": 58, "ay": 68}, {"n": "④", "t": "Linfocito T", "s": "las caspasas lo<br>llevan a apoptosis", "c": "i", "x": 73, "y": 91, "ax": 73, "ay": 50}]}, {"img": "img/20_2.webp", "ratio": 1.5, "titulo": "Inflamación que coagula y la proteína C", "texto": "TNF e IL-1 dañan el endotelio y exponen factor tisular ③; la <mark>proteína C activada</mark> corta Va y VIIIa, <span class=\"cx\">por eso</span> frena coagulación <b>e</b> inflamación ⑤.", "etiquetas": [{"n": "⑤", "t": "Trombomodulina", "s": "activa la<br>proteína C", "c": "i", "x": 0.5, "y": 6, "ax": 13.5, "ay": 38.0, "al": "l"}, {"n": "③", "t": "Macrófago activado", "s": "suelta TNF<br>e IL-1", "c": "d", "x": 32, "y": 6, "ax": 39.7, "ay": 27.0}, {"n": "③", "t": "TNF e IL-1", "s": "en exceso", "c": "d", "x": 52, "y": 6, "ax": 49.5, "ay": 29.0}, {"n": "⑤", "t": "Proteína C activada", "s": "doble función", "c": "i", "x": 72, "y": 6, "ax": 78.0, "ay": 43.0}, {"n": "⑤", "t": "Neutrófilo calmado", "s": "menos<br>inflamación", "c": "i", "x": 99.5, "y": 6, "ax": 93.0, "ay": 31.0, "al": "r"}, {"n": "③", "t": "Endotelio sano", "s": "liso, sin<br>coágulos", "c": "g", "x": 12, "y": 92, "ax": 15.6, "ay": 68.0}, {"n": "③", "t": "Factor tisular", "s": "expuesto por<br>el endotelio dañado", "c": "d", "x": 32, "y": 92, "ax": 42.3, "ay": 43.5}, {"n": "③", "t": "Microtrombos", "s": "fibrina y plaquetas:<br>CID", "c": "d", "x": 52, "y": 92, "ax": 56.0, "ay": 59.6}, {"n": "⑤", "t": "Va y VIIIa cortados", "s": "no se forma<br>trombina", "c": "i", "x": 74, "y": 92, "ax": 86.6, "ay": 53.0}, {"n": "⑤", "t": "Fibrina deshecha", "s": "el coágulo<br>se disuelve", "c": "i", "x": 99.5, "y": 92, "ax": 93.8, "ay": 63.5, "al": "r"}]}, {"img": "img/20_3.webp", "ratio": 1.5, "titulo": "Trauma: alarminas, pulmón y anergia", "texto": "El tejido roto suelta <mark>alarminas</mark> ⑦; el <b>neutrófilo</b> daña el alveolo (SDRA) ⑧; <span class=\"cx\">luego</span> baja el <mark>HLA-DR</mark> del monocito ⑨.", "etiquetas": [{"n": "⑦", "t": "Músculo destrozado", "s": "células<br>necróticas", "c": "d", "x": 0.5, "y": 6, "ax": 5.2, "ay": 40.0, "al": "l"}, {"n": "⑦", "t": "Alarminas", "s": "proteínas de<br>choque térmico", "c": "d", "x": 27, "y": 6, "ax": 15.6, "ay": 45.0}, {"n": "⑧", "t": "Radicales y enzimas", "s": "dañan la pared<br>alveolar", "c": "d", "x": 48, "y": 6, "ax": 54.0, "ay": 52.7}, {"n": "⑨", "t": "Monocito sano", "s": "mucho HLA-DR", "c": "i", "x": 72, "y": 6, "ax": 72.3, "ay": 40.0}, {"n": "⑨", "t": "LT inactivo", "s": "nadie le<br>presenta", "c": "i", "x": 99.5, "y": 6, "ax": 95.0, "ay": 51.0, "al": "r"}, {"n": "⑦", "t": "Macrófago", "s": "capta alarminas<br>con sus receptores", "c": "i", "x": 26, "y": 92, "ax": 30.0, "ay": 52.0}, {"n": "⑧", "t": "Neutrófilo alveolar", "s": "atraído por C5a,<br>PAF y GM-CSF", "c": "d", "x": 46, "y": 92, "ax": 45.0, "ay": 62.5}, {"n": "⑧", "t": "Membrana hialina", "s": "SDRA", "c": "d", "x": 66, "y": 92, "ax": 58.6, "ay": 64.0}, {"n": "⑨", "t": "Monocito agotado", "s": "HLA-DR bajo:<br>anergia", "c": "g", "x": 84, "y": 92, "ax": 86.6, "ay": 49.0}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = células de defensa</b>, <b class=\"d\">rojo = lo que daña</b> (C5a, trombos, fuga, apoptosis), gris = el germen y estructuras.", "<b>Izquierda:</b> las bolitas naranjas son complemento. El <mark>C5a</mark> en exceso ocupa los receptores del neutrófilo, sube su propio receptor (C5aR), apaga la <b>NADPH oxidasa</b> y estimula el factor tisular. Hay muchos neutrófilos, pero matan poco.", "<b>Centro:</b> el TNF y la IL-1 abren brechas en el endotelio: sale plasma (hipotensión, choque; en el pulmón, SDRA) y se forman microtrombos de fibrina y plaquetas (<mark>CID</mark>).", "<b>Derecha:</b> las caspasas llevan al linfocito T a la apoptosis: núcleo condensado y cuerpos apoptóticos. Así se instala la <mark>inmunosupresión</mark> de la sepsis."], "recordar": "Sepsis = C5a que paraliza + TNF/IL-1 que rompe el endotelio + apoptosis que vacía de linfocitos. Tratamiento: proteína C activada, glucemia controlada, IFNγ en la fase tardía."}, "numeros": [{"l": "A", "html": "La sepsis causa el <b class=\"a\">10 %</b> de los ingresos a cuidado intensivo y tiene una mortalidad del <b class=\"a\">40 %</b>; las mutaciones del TLR4 predisponen.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la infección a la falla multisistémica", "subtitulo": "estímulo → células y moléculas → mecanismo → resultado → qué pasa si sigue", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> infección bacteriana masiva o resistente (o, en el trauma, <mark>alarminas</mark> del tejido roto reconocidas por los TLR).", "pr": "inflamación grave y sistémica.", "pr_tit": "Produce:", "rf": "Preguntas ①⑦ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Complemento", "m": "<b>Por qué:</b> se activa en exceso y produce <mark>C5a</mark> masivo, que sube el C5aR, apaga la NADPH oxidasa y estimula el factor tisular.", "pr": "neutrófilo paralizado y coagulación encendida.", "pr_tit": "Produce:", "rf": "Preguntas ②⑥", "color": "p2"}, {"t": "3. Citoquinas", "m": "<b>Qué produce:</b> los macrófagos y las endotoxinas (como superantígenos) disparan <mark>TNF e IL-1</mark> en exceso.", "pr": "daño endotelial: fuga de plasma y microtrombos.", "pr_tit": "Produce:", "rf": "Preguntas ③⑤", "color": "p3"}, {"t": "4. Vaso y pulmón", "m": "<b>Qué pasa:</b> aumenta la permeabilidad (hipotensión, choque) y la <mark>CID</mark>; el C5a acumula neutrófilos en el pulmón, que descargan radicales, mieloperoxidasa y elastasa.", "pr": "SDRA y daño de corazón, riñón y suprarrenales.", "pr_tit": "Produce:", "rf": "Pregunta ⑧", "color": "p4"}, {"t": "5. Inmunosupresión", "m": "<b>Si sigue:</b> las caspasas causan <mark>apoptosis de linfocitos T y B</mark>, las DCs presentan mal y el intestino pierde su barrera (apoptosis epitelial).", "pr": "infecciones secundarias (Pseudomonas, Klebsiella, Candida) y falla multisistémica.", "pr_tit": "Produce:", "rf": "Preguntas ④⑨", "color": "p4"}], "extra": [{"html": "💊 <b>Tratamiento:</b> <mark>proteína C activada</mark> (inactiva Va y VIIIa: anticoagulante y antiinflamatoria), control estricto de la glucemia (la hiperglucemia frena la fagocitosis), IFNγ en la fase de inmunosupresión; en evaluación: bloqueadores del C5aR e IL-7. El <b>eritoran</b> (anti-TLR4) se suspendió.", "k": "k"}, {"html": "🩹 <b>Trauma:</b> respuesta local en el monotraumatizado y sistémica en el politraumatizado; <span class=\"cx\">luego</span> baja la respuesta T, baja el HLA-DR del monocito y se suprimen las NK. Medir TNF, IL-1 e IL-10 antes de operar; inmunonutrición con <b>glutamina</b> y omega-3.", "k": ""}], "escaleras": [{"c": "d", "t": "🔥 Cómo empeora el paciente séptico", "pasos": ["foco infeccioso", "inflamación sistémica: fiebre, taquicardia, leucocitosis", "fuga de plasma: <b>choque</b>", "<b>CID</b> y SDRA", "apoptosis linfocitaria: <b>inmunoparálisis</b>", "falla multisistémica (40 % de mortalidad)"]}], "html": "", "fuente": "Fuente: tu teoría — clase 27 (los diez pasos de la sepsis, inmunosupresión, tratamiento; trauma: respuesta sistémica, inmunidad innata y adquirida, tratamiento)."}, "preguntas": [{"n": 1, "id": "IN11-018", "c": "g", "tema": "Definición", "pregunta": "Defina sepsis y dé su impacto en cuidados intensivos y su mortalidad.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Respuesta sistémica a una infección grave con inflamación exagerada; causa el 10 % de los ingresos a UCI y tiene mortalidad del 40 %.", "sin_banco": true, "ok": "", "x": "Cursa con hipertermia, taquicardia, taquipnea, leucocitosis y alteraciones de la coagulación; en fases avanzadas, <mark>apoptosis de linfocitos e inmunodeficiencia</mark>. Las mutaciones del TLR4 predisponen. Cifras: <span class=\"res\">10 % de ingresos a UCI y 40 % de mortalidad</span>.", "truco": "Sepsis «10 entra, 40 muere».", "veces": 0}, {"n": 2, "id": "IN11-019", "c": "d", "tema": "Inmunopatología", "pregunta": "En la sepsis, el exceso de C5a produce todos los efectos siguientes, EXCEPTO:", "opciones": ["a. Parálisis funcional del neutrófilo", "b. Aumento de la actividad de la NADPH oxidasa", "c. Mayor expresión del receptor C5aR", "d. Producción de factor tisular procoagulante", "e. Acúmulo pulmonar de neutrófilos"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Es la excepción: el C5a en exceso no potencia la NADPH oxidasa, la desactiva y baja los radicales del oxígeno.", "sin_banco": true, "ok": "", "x": "El neutrófilo de la izquierda está cubierto de C5a (bolitas naranjas) y pálido: <mark>paralizado</mark>. El C5a apaga su NADPH oxidasa, no la potencia. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN11-020", "c": "d", "tema": "Inmunopatología", "pregunta": "¿Qué mecanismo une las citoquinas proinflamatorias con la coagulación intravascular diseminada en la sepsis?", "opciones": ["a. Daño endotelial por TNF e IL-1", "b. Exceso de IgE sobre los mastocitos", "c. Déficit congénito de factor VIII", "d. Activación de linfocitos Th2", "e. Consumo de IgA en el intestino"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. El TNF y la IL-1 en exceso dañan el endotelio, que propicia la coagulopatía intravascular.", "sin_banco": true, "ok": "", "x": "Del macrófago salen las gotitas rojas (TNF e IL-1) y en el centro ves el resultado: <mark>endotelio con brechas</mark> y microtrombos. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN11-021", "c": "i", "tema": "Inmunosupresión", "pregunta": "¿Por qué la sepsis avanzada produce inmunodeficiencia y no una respuesta reforzada?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque las caspasas aceleran la apoptosis de linfocitos T y B, y macrófagos y DCs presentan mal los antígenos; además se expresan receptores antiinmunes.", "sin_banco": true, "ok": "", "x": "Mira la secuencia de la derecha: el linfocito sano termina en <mark>cuerpos apoptóticos</mark>. Menos linfocitos y peor presentación de antígenos: <span class=\"res\">la sepsis vacía la defensa</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN11-022", "c": "i", "tema": "Tratamiento", "pregunta": "La proteína C activada se considera de «doble función» en el choque séptico porque:", "opciones": ["a. Es un antibiótico y un antiinflamatorio", "b. Bloquea el TLR4 y el receptor de C5a", "c. Inactiva los factores Va y VIIIa: anticoagulante y antiinflamatoria", "d. Es marcador diagnóstico y pronóstico", "e. Activa los linfocitos T y los neutrófilos"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Inactiva los factores Va y VIIIa, evita la trombina y así frena a la vez la coagulación y la inflamación.", "sin_banco": true, "ok": "", "x": "La trombina, <span class=\"cx\">además</span> de coagular, activa plaquetas y mastocitos. Al impedir su formación, la <mark>proteína C activada</mark> es anticoagulante y antiinflamatoria; fue el <span class=\"res\">primer fármaco con resultados satisfactorios</span> en choque séptico. No confundir con la proteína C reactiva, que es un marcador hepático.", "truco": "Proteína C «activada» trata; C «reactiva» mide.", "veces": 0}, {"n": 6, "id": "IN11-023", "c": "i", "tema": "Tratamiento", "pregunta": "Respecto al tratamiento inmunológico de la sepsis, es FALSO:", "opciones": ["a. Controlar la hiperglucemia mejora la fagocitosis.", "b. El IFNγ se usa en la fase de inmunosupresión para reactivar al macrófago.", "c. Los bloqueadores del receptor de C5a están en evaluación.", "d. El eritoran (antagonista del TLR4) demostró reducir la mortalidad y es de uso rutinario.", "e. La IL-7 se evalúa para restaurar la respuesta inmune."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Es falso: el eritoran (antagonista del TLR4) fue suspendido por falta de resultados satisfactorios.", "sin_banco": true, "ok": "", "x": "La idea central es que <mark>la hiperrespuesta del hospedero causa la enfermedad</mark>. El control de la glucemia es una medida inmune (la hiperglucemia frena la fagocitosis); el IFNγ reactiva al macrófago en la fase tardía; los bloqueadores del C5aR y la IL-7 están en evaluación. <span class=\"cx\">En cambio</span> <span class=\"res\">el eritoran fracasó</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN11-024", "c": "i", "tema": "Trauma", "pregunta": "¿Qué son las alarminas y qué papel cumplen en la respuesta postraumática?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Moléculas endógenas del daño tisular (proteínas de choque térmico, anexinas, defensinas) que, reconocidas por los TLR, inician la inflamación local y sistémica.", "sin_banco": true, "ok": "", "x": "En el trauma no hay microbio al inicio: las <mark>señales de peligro</mark> las da el propio tejido roto. Los TLR reconocen esas alarminas y se liberan IL-1β, TNF, IL-6 e IL-8; minutos después se activa el complemento (C5a). <span class=\"cx\">Por eso</span> <span class=\"res\">el trauma inflama aunque sea estéril</span>.", "truco": "Alarmina = «alarma» del tejido roto.", "veces": 0}, {"n": 8, "id": "IN11-025", "c": "d", "tema": "Trauma", "pregunta": "Politraumatizado de 30 años; al tercer día presenta hipoxemia grave con infiltrados pulmonares bilaterales. ¿Qué célula y qué productos explican el daño pulmonar?", "opciones": ["a. El eosinófilo por IL-5", "b. El linfocito B por IgE", "c. La célula NK por perforina", "d. El mastocito por histamina", "e. El neutrófilo por radicales, mieloperoxidasa y elastasa"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. El neutrófilo atraído por C5a, PAF y GM-CSF, que libera radicales del oxígeno, mieloperoxidasa y elastasa y causa síndrome de dificultad respiratoria aguda.", "sin_banco": true, "ok": "", "x": "El neutrófilo rueda, se adhiere al endotelio y pasa al tejido, donde descarga <mark>radicales, mieloperoxidasa y elastasa</mark>. Ese arsenal daña también tejido sano: <span class=\"res\">SDRA</span>, falla multisistémica y, en el trauma craneal, edema cerebral. <span class=\"cx\">Por eso</span> se evalúa el estado inflamatorio (TNF, IL-1, IL-10) antes de operar.", "truco": "En el trauma, el neutrófilo «dispara a todos, aliados incluidos».", "veces": 0}, {"n": 9, "id": "IN11-026", "c": "i", "tema": "Trauma", "pregunta": "Mencione los cambios de la inmunidad adquirida tras un trauma grave y un nutriente recomendado en la inmunonutrición.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Baja la respuesta de los linfocitos T, baja el HLA-DR de los monocitos y se suprime la actividad NK; se recomienda glutamina (y omega-3).", "sin_banco": true, "ok": "", "x": "A la hiperinflamación inicial le sigue una <mark>inmunodepresión</mark> que predispone a infecciones secundarias y sepsis. El hipercatabolismo, la hiperglucemia y la acidosis láctica frenan la fagocitosis. La <span class=\"res\">glutamina</span> activa la fagocitosis y es precursora del glutatión antioxidante; los omega-3 son antiinflamatorios.", "truco": "Trauma: «T baja, DR baja, NK baja».", "veces": 0}], "tabla": {"cab": ["", "Sepsis", "Trauma grave"], "filas": [["Qué lo inicia", "PAMP de la infección (TLR4)", "Alarminas del tejido roto (TLR)"], ["Fase temprana", "C5a, TNF e IL-1: choque y CID", "IL-1β, TNF, IL-6; C5a, PAF y GM-CSF: neutrófilo agresor"], ["Fase tardía", "Apoptosis de linfocitos, DCs que presentan mal", "Baja la respuesta T, el HLA-DR y las NK"], ["Qué se hace", "Proteína C activada, glucemia, IFNγ tardío", "Esperar a que se estabilice la inflamación; glutamina y omega-3"], ["🔑 Para diferenciar", "Empieza por un germen", "Empieza estéril, por el daño"]]}, "fuente": "Fuente: tu teoría — clase 27 (Sepsis y trauma), Rojas 17.ª ed."}, {"n": 21, "slug": "Cancer_y_proliferativas", "titulo": "Cáncer y proliferativas", "subtitulo": "vigilancia, evasión tumoral y el clon inmune maligno", "grupo": "g12", "lema": "La idea: cada día aparecen más de un millón de mutaciones y casi ninguna llega a tumor, porque el sistema inmune ejerce <mark>vigilancia inmunológica</mark> (Burnet, 1957): las <b>NK</b> y los <b>LT CD8</b> matan a la célula anormal. Un tumor que crece es uno que aprendió a escapar: esconde sus antígenos o su HLA-I, secreta IL-10 y TGF-β y recluta <b>macrófagos M2</b> que le dan vasos. Cuando el clon maligno es una célula del propio sistema inmune, aparecen las <mark>leucemias, linfomas y el mieloma</mark>. Por eso la terapia moderna no solo ataca al tumor: libera al linfocito (anti-CTLA-4) o golpea la diana molecular del clon (imatinib). En la imagen verás: una célula tumoral entre un LT CD8 y una NK; una masa con neovasos, macrófagos M2 y una célula que migra; y una médula llena de plasmocitos con osteoclastos que excavan el hueso.", "img": "img/21.webp", "mini": "img/mini/21.webp", "ratio": 1.5, "etiquetas": [{"n": "⑦⑧", "t": "LT CD8", "s": "lisa si ve el<br>antígeno en HLA-I", "c": "i", "x": 0.5, "y": 6, "ax": 4, "ay": 46, "al": "l"}, {"n": "①③⑧", "t": "Célula tumoral", "s": "telomerasa activa;<br>puede perder HLA-I", "c": "d", "x": 26, "y": 6, "ax": 17, "ay": 40, "d": "A"}, {"n": "⑦⑧", "t": "Célula NK", "s": "ataca sin estímulo<br>previo ni anticuerpos", "c": "i", "x": 45, "y": 6, "ax": 29.5, "ay": 42}, {"n": "⑦⑨", "t": "Macrófago M2 (TAM)", "s": "IL-10, arginasa,<br>TGF-β y VEGF", "c": "d", "x": 65, "y": 6, "ax": 61, "ay": 33}, {"n": "㉑", "t": "Osteoclasto", "s": "RANKL lo activa:<br>lesión lítica", "c": "d", "x": 99.5, "y": 6, "ax": 84, "ay": 30, "al": "r"}, {"n": "②⑩", "t": "Masa tumoral", "s": "1 cm = 10⁹ células;<br>suelta CEA", "c": "d", "x": 20, "y": 91, "ax": 42, "ay": 50, "d": "B"}, {"n": "⑪", "t": "Neovasos", "s": "VEGF: bevacizumab<br>los bloquea", "c": "g", "x": 38, "y": 91, "ax": 46, "ay": 64}, {"n": "⑥", "t": "Célula que migra", "s": "TWIST-1, CXCR4:<br>metástasis", "c": "d", "x": 55, "y": 91, "ax": 58, "ay": 54}, {"n": "⑭㉑㉒", "t": "Plasmocitos", "s": "clon: Ig homogénea,<br>pico monoclonal", "c": "d", "x": 73, "y": 91, "ax": 88, "ay": 55, "d": "C"}, {"n": "㉑", "t": "Osteoblasto", "s": "DKK1<br>lo apaga", "c": "g", "x": 99.5, "y": 91, "ax": 95, "ay": 69, "al": "r"}], "diapos": [{"img": "img/21.webp", "ratio": 1.5, "titulo": "Vigilancia inmune y escape tumoral", "texto": "LT CD8 y NK atacan la célula mutada ①⑧; el tumor crece con <b>angiogénesis</b> y TAM ⑦, y el mieloma cava <mark>lesiones líticas</mark> ㉑.", "etiquetas": [{"n": "⑦⑧", "t": "LT CD8", "s": "lisa si ve el<br>antígeno en HLA-I", "c": "i", "x": 0.5, "y": 6, "ax": 4, "ay": 46, "al": "l"}, {"n": "①③⑧", "t": "Célula tumoral", "s": "telomerasa activa;<br>puede perder HLA-I", "c": "d", "x": 26, "y": 6, "ax": 17, "ay": 40, "d": "A"}, {"n": "⑦⑧", "t": "Célula NK", "s": "ataca sin estímulo<br>previo ni anticuerpos", "c": "i", "x": 45, "y": 6, "ax": 29.5, "ay": 42}, {"n": "⑦⑨", "t": "Macrófago M2 (TAM)", "s": "IL-10, arginasa,<br>TGF-β y VEGF", "c": "d", "x": 65, "y": 6, "ax": 61, "ay": 33}, {"n": "㉑", "t": "Osteoclasto", "s": "RANKL lo activa:<br>lesión lítica", "c": "d", "x": 99.5, "y": 6, "ax": 84, "ay": 30, "al": "r"}, {"n": "②⑩", "t": "Masa tumoral", "s": "1 cm = 10⁹ células;<br>suelta CEA", "c": "d", "x": 20, "y": 91, "ax": 42, "ay": 50, "d": "B"}, {"n": "⑪", "t": "Neovasos", "s": "VEGF: bevacizumab<br>los bloquea", "c": "g", "x": 38, "y": 91, "ax": 46, "ay": 64}, {"n": "⑥", "t": "Célula que migra", "s": "TWIST-1, CXCR4:<br>metástasis", "c": "d", "x": 55, "y": 91, "ax": 58, "ay": 54}, {"n": "⑭㉑㉒", "t": "Plasmocitos", "s": "clon: Ig homogénea,<br>pico monoclonal", "c": "d", "x": 73, "y": 91, "ax": 88, "ay": 55, "d": "C"}, {"n": "㉑", "t": "Osteoblasto", "s": "DKK1<br>lo apaga", "c": "g", "x": 99.5, "y": 91, "ax": 95, "ay": 69, "al": "r"}]}, {"img": "img/21_2.webp", "ratio": 1.5, "titulo": "Genes del cáncer e inmunoterapia", "texto": "La <mark>telomerasa</mark> evita el acortamiento de los telómeros ③ <span class=\"lt2\">A</span>; la t(9;22) forma <mark>BCR-ABL</mark> ④; el <b>ipilimumab</b> quita el freno CTLA-4 ⑪.", "etiquetas": [{"n": "④", "t": "Cromosoma 9", "s": "aporta ABL", "c": "g", "x": 0.5, "y": 6, "ax": 3.9, "ay": 30.0, "al": "l"}, {"n": "④", "t": "Cromosoma 22", "s": "aporta BCR", "c": "g", "x": 25, "y": 6, "ax": 11.4, "ay": 40.0}, {"n": "③", "t": "Telómero que se acorta", "s": "célula normal:<br>envejece", "c": "g", "x": 46, "y": 6, "ax": 58.0, "ay": 43.0}, {"n": "⑪", "t": "CTLA-4 bloqueado", "s": "el freno<br>del LT", "c": "d", "x": 66, "y": 6, "ax": 80.0, "ay": 39.0}, {"n": "⑪", "t": "Ipilimumab", "s": "anticuerpo<br>anti-CTLA-4", "c": "i", "x": 85, "y": 6, "ax": 82.4, "ay": 30.0}, {"n": "⑪", "t": "Célula tumoral", "s": "recibe los<br>gránulos", "c": "d", "x": 90, "y": 92, "ax": 93.0, "ay": 58.0}, {"n": "④", "t": "Translocación t(9;22)", "s": "intercambio<br>de brazos", "c": "g", "x": 0.5, "y": 92, "ax": 7.2, "ay": 63.0, "al": "l"}, {"n": "④", "t": "Filadelfia", "s": "gen BCR-ABL:<br>LMC", "c": "d", "x": 26, "y": 92, "ax": 29.3, "ay": 64.5}, {"n": "③", "t": "Telomerasa", "s": "rehace el<br>telómero", "c": "d", "x": 46, "y": 92, "ax": 48.2, "ay": 58.0, "d": "A"}, {"n": "⑪", "t": "LT CD8 activo", "s": "sin freno,<br>ataca", "c": "i", "x": 68, "y": 92, "ax": 69.0, "ay": 60.0}]}, {"img": "img/21_3.webp", "ratio": 1.5, "titulo": "Proliferativas al microscopio", "texto": "Reed-Sternberg en el Hodgkin ⑲ <span class=\"lt2\">E</span>, cielo estrellado del <mark>Burkitt</mark> ⑳, linfocitos pequeños de la LLC ⑱ e <b>IgM</b> que espesa la sangre en el Waldenström ⑮.", "etiquetas": [{"n": "⑲", "t": "Reed-Sternberg", "s": "ojos de búho:<br>Hodgkin", "c": "d", "x": 13, "y": 6, "ax": 15.0, "ay": 45.4, "d": "E"}, {"n": "⑳", "t": "Cielo estrellado", "s": "macrófagos entre<br>las células del Burkitt", "c": "g", "x": 38, "y": 6, "ax": 44.3, "ay": 38.0}, {"n": "⑱", "t": "Linfocitos pequeños", "s": "LLC: CD19, CD5<br>y CD23", "c": "d", "x": 62, "y": 6, "ax": 58.6, "ay": 40.0}, {"n": "⑮", "t": "IgM pentamérica", "s": "en exceso:<br>Waldenström", "c": "d", "x": 88, "y": 6, "ax": 92.4, "ay": 44.0}, {"n": "⑲", "t": "Fondo reactivo", "s": "muchos linfocitos<br>alrededor", "c": "i", "x": 8, "y": 92, "ax": 5.0, "ay": 55.0}, {"n": "⑳", "t": "Mar de LB", "s": "muy agresivo<br>(C-MYC)", "c": "d", "x": 32, "y": 92, "ax": 34.0, "ay": 56.0}, {"n": "⑮", "t": "Pilas de monedas", "s": "sangre espesa:<br>plasmaféresis", "c": "d", "x": 84, "y": 92, "ax": 84.6, "ay": 49.0}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa antitumoral</b> (CD8, NK), <b class=\"d\">rojo = el tumor y lo que lo ayuda</b> (TAM, migración, osteoclasto), gris = estructuras de referencia.", "<b>Izquierda:</b> el CD8 solo ve el antígeno presentado en <mark>HLA-I</mark>; si el tumor pierde el HLA-I, se esconde del CD8 pero queda expuesto a la NK, que ataca justo a la célula sin HLA propio. Es un <b>arma de doble filo</b>.", "<b>Centro:</b> los <mark>macrófagos asociados a tumores (M2)</mark> frenan al linfocito con IL-10 y arginasa y dan VEGF para los neovasos. Una célula se suelta (TWIST-1 apaga la caderina E) y entra al vaso: metástasis guiada por quimioquinas (CXCR4 → pulmón, hígado, médula).", "<b>Derecha:</b> un clon de plasmocitos llena la médula (<span class=\"lt2\">C</span>). Sus RANKL y TGF encienden al <mark>osteoclasto</mark> y su DKK1 apaga al osteoblasto: lesiones líticas, dolor e hipercalcemia."], "recordar": "Vigilancia (NK + CD8) → evasión (sin HLA-I, IgG4 de bloqueo, IL-10, TGF-β, TAM) → crecimiento y metástasis. Clon inmune maligno: LMC = BCR-ABL; Burkitt = C-MYC; mieloma = RANKL + DKK1."}, "numeros": [{"l": "A", "html": "<b>Genes:</b> P53 mutado en <b class=\"a\">más del 50 %</b> de los tumores; telomerasa activa en el <b class=\"a\">90 %</b>. El trasplantado renal inmunosuprimido tiene <b class=\"a\">200 veces</b> más riesgo de tumor maligno.", "rango": null}, {"l": "B", "html": "<b>Detección:</b> un cáncer clínicamente detectable mide <b class=\"n\">1 cm</b> y tiene unas <b class=\"a\">10⁹ células</b>. Cerca del <b class=\"a\">20 %</b> de los tumores se asocia a infecciones.", "rango": null}, {"l": "C", "html": "<b>Mieloma:</b> <b class=\"n\">10 %</b> de los cánceres hematológicos y <b class=\"n\">1 %</b> de todos los tumores; después de los <b class=\"n\">60 años</b>. <b>Gammopatía monoclonal</b>: <b class=\"n\">3 %</b> de los adultos mayores, <b class=\"a\">1 % al año</b> pasa a mieloma.", "rango": null}, {"l": "D", "html": "<b>Monocitosis</b>: más de <b class=\"a\">750/mL</b> en niños y más de <b class=\"a\">500/mL</b> en adultos (tuberculosis, endocarditis, Hodgkin).", "rango": {"min": 0, "max": 1500, "unidad": "monocitos/mL", "zonas": [[0, 500, "n"], [500, 750, "m"], [750, 1500, "a"]], "marcas": [500, 750]}}, {"l": "E", "html": "<b>Hodgkin</b>: la célula de Reed-Sternberg viene de LB en el <b class=\"n\">85 %</b>. <b>Burkitt</b>: <b class=\"a\">40 %</b> de los linfomas de niños.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la mutación al tumor", "subtitulo": "estímulo → células → mecanismo → resultado → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> mutaciones en oncogenes (reactivados) o genes supresores (P53), traslocaciones (<mark>BCR-ABL</mark>, C-MYC), virus (VEB, HTLV-1, hepatitis B, herpes 8) o inflamación crónica.", "pr": "una célula prolifera sin control e inmortal (telomerasa).", "pr_tit": "Produce:", "rf": "Preguntas ③④⑤ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Vigilancia", "m": "<b>Por qué:</b> la célula expresa antígenos extraños o embrionarios (CEA); las <mark>NK</mark>, los LT γδ, los <b>LT CD8</b> y los macrófagos M1 (TNF) la atacan; los anticuerpos activan complemento y ADCC.", "pr": "la mayoría de las células mutadas se elimina.", "pr_tit": "Produce:", "rf": "Preguntas ①②⑦", "color": "p2"}, {"t": "3. Evasión", "m": "<b>Qué produce:</b> el tumor baja sus antígenos, pierde el HLA-I o expresa HLA-G, genera <mark>IgG4 de bloqueo</mark>, secreta IL-10, TGF-β y VEGF y recluta TAM M2 y linfocitos T reguladores (CCL21).", "pr": "el sistema inmune deja de verlo o queda frenado.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨", "color": "p3"}, {"t": "4. Crecimiento y metástasis", "m": "<b>Qué pasa:</b> neovasos (VEGF, HIF), desprendimiento (TWIST-1), metaloproteinasas y quimioquinas (<mark>CXCR4</mark>, CCR7) llevan células a pulmón, hígado, médula o ganglio.", "pr": "tumor detectable (1 cm, 10⁹ células) y metástasis.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑩ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Si el clon es inmune", "m": "<b>Qué pasa:</b> el clon maligno es un leucocito: <mark>LMC</mark> (Filadelfia), LLC (CD19⁺ CD5⁺ CD23⁺), Burkitt (C-MYC), Hodgkin (Reed-Sternberg) o <b>mieloma</b> (plasmocito con lesiones líticas).", "pr": "leucemia, linfoma o mieloma; tratamiento dirigido (imatinib, rituximab, bortezomib).", "pr_tit": "Produce:", "rf": "Preguntas ⑯⑱⑲⑳㉑ · punto <span class=\"lt2\">C</span>", "color": "p4"}], "extra": [{"html": "💊 <b>Inmunoterapia:</b> ipilimumab (anti-CTLA-4, melanoma), trastuzumab (anti-HER2, seno), bevacizumab (anti-VEGF), rituximab (anti-CD20), imatinib (BCR-ABL), IL-2 e IFNα (90 % de respuesta en la leucemia de células vellosas), LT con TCR anti-CD19 en la LLC.", "k": "k"}, {"html": "🩸 <b>Proliferaciones benignas que confunden:</b> la tos ferina bloquea las integrinas y sube los linfocitos hasta 60 000/mL (con linfopenia en los tejidos); monocitosis = más de 750/mL en niños y 500/mL en adultos; Waldenström = IgM con hiperviscosidad (plasmaféresis).", "k": ""}], "escaleras": [{"c": "d", "t": "🔥 Del pico monoclonal al mieloma", "pasos": ["gammopatía monoclonal benigna: pico sin síntomas (3 % de mayores)", "1 % al año progresa", "<b>mieloma múltiple</b>: clon plasmocitario", "RANKL + DKK1: lesiones líticas e hipercalcemia", "anemia, falla renal, hiperviscosidad e infecciones"]}], "html": "", "fuente": "Fuente: tu teoría — clase 28 (vigilancia, genes, microorganismos, metástasis, ataque y evasión, inmunodiagnóstico e inmunoterapia) y clase 29 (proliferaciones benignas, leucemias de granulocitos, linfocitos T y B, mieloma múltiple)."}, "preguntas": [{"n": 1, "id": "IN12-001", "c": "i", "tema": "Vigilancia inmunológica", "pregunta": "¿Qué postula la teoría de la vigilancia inmunológica y quién la propuso?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Burnet (1957): el sistema inmune reconoce y destruye las células mutadas antes de que formen un tumor; si falla, algunas mutaciones progresan a cáncer.", "sin_banco": true, "ok": "", "x": "Cada día hay más de <mark>un millón de mutaciones</mark> por las mitosis de la médula. La prueba clínica: el trasplantado renal inmunosuprimido tiene <span class=\"res\">200 veces más riesgo</span> de tumor maligno, y los tumores infiltrados por linfocitos crecen más lento.", "truco": "Burnet «quema» (burn) las células mutadas.", "veces": 0}, {"n": 2, "id": "IN12-002", "c": "i", "tema": "Vigilancia inmunológica", "pregunta": "Un paciente con trasplante renal e inmunosupresión tiene, frente a la población general, un riesgo de tumor maligno de aproximadamente:", "opciones": ["a. 2 veces más", "b. 20 veces más", "c. 200 veces más", "d. 2000 veces más", "e. Igual riesgo"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. 200 veces más.", "sin_banco": true, "ok": "", "x": "Es la <mark>evidencia directa</mark> de la vigilancia: al frenar al sistema inmune para proteger el injerto, se pierde el control de las células mutadas. <span class=\"cx\">Por eso</span> todo inmunosuprimido crónico (trasplantado, quimioterapia prolongada) <span class=\"res\">requiere vigilancia oncológica</span>.", "truco": "Trasplante renal: «doscientas veces».", "veces": 0}, {"n": 3, "id": "IN12-003", "c": "d", "tema": "Bases genéticas", "pregunta": "¿Qué papel cumple la activación de la telomerasa en el 90 % de las células malignas?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Genera nuevos telómeros en cada mitosis, evitando el acortamiento que normalmente lleva a la apoptosis; así la célula se divide sin fin.", "sin_banco": true, "ok": "", "x": "La célula tumoral de la izquierda (punto Ⓐ) tiene la <mark>telomerasa encendida</mark>: repone sus telómeros en cada mitosis y no llega a la apoptosis. <span class=\"cx\">Por eso</span> <span class=\"res\">se divide sin fin</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN12-004", "c": "d", "tema": "Bases genéticas", "pregunta": "La traslocación entre los cromosomas 9 y 22 (cromosoma Filadelfia) genera el gen de fusión:", "opciones": ["a. BCR-ABL", "b. C-MYC", "c. BRAF", "d. MYD88", "e. HER2"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. BCR-ABL, una quinasa de tirosina siempre activa, típica de la leucemia mieloide crónica; la inhibe el imatinib.", "sin_banco": true, "ok": "", "x": "La fusión <mark>BCR-ABL</mark> deja una quinasa de tirosina encendida que impulsa la proliferación del granulocito. El <span class=\"res\">imatinib</span> la bloquea: es el paradigma de la terapia molecular dirigida. <span class=\"cx\">En cambio</span> <b>c-myc</b> es la traslocación del linfoma de Burkitt.", "truco": "Filadelfia «9-22»: BCR-ABL ← imatinib.", "veces": 0}, {"n": 5, "id": "IN12-005", "c": "g", "tema": "Microorganismos y cáncer", "pregunta": "Relación agente infeccioso–neoplasia INCORRECTA:", "opciones": ["a. Virus de Epstein-Barr – linfoma de Burkitt", "b. HTLV-1 – leucemia de linfocitos T", "c. Virus de hepatitis B – hepatoma", "d. Herpes virus 8 – cáncer gástrico", "e. Virus de hepatitis C – linfoma de linfocitos B"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Incorrecta: el herpes virus 8 se asocia al sarcoma de Kaposi, no al cáncer gástrico (que se asocia a Helicobacter pylori).", "sin_banco": true, "ok": "", "x": "Cerca del <mark>20 %</mark> de los tumores malignos se asocian a infecciones. VEB: Burkitt y nasofaríngeo; HTLV-1: leucemia T; hepatitis B: hepatoma; hepatitis C: linfoma B; <span class=\"res\">herpes 8: Kaposi</span>; H. pylori: estómago.", "truco": "Herpes «OCHO» → Kaposi; Helicobacter → estómago.", "veces": 0}, {"n": 6, "id": "IN12-006", "c": "d", "tema": "Metástasis", "pregunta": "¿Por qué las células tumorales que expresan CXCR4 metastatizan preferentemente a pulmón, hígado y médula ósea?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque responden a la quimioquina CXCL12 que producen esos órganos; en cambio el par CCL21-CCR7 las dirige a los ganglios linfáticos.", "sin_banco": true, "ok": "", "x": "Mira la célula que se suelta de la masa y entra al vaso: la guían <mark>quimioquinas</mark>. Con CXCR4 sigue a la CXCL12 hacia <span class=\"res\">pulmón, hígado y médula ósea</span>; con CCR7, al ganglio.", "truco": "", "veces": 0}, {"n": 7, "id": "IN12-007", "c": "i", "tema": "Mecanismos de ataque", "pregunta": "Respecto a los mecanismos inmunes contra las células tumorales, es FALSO:", "opciones": ["a. Las NK atacan sin estimulación antigénica previa.", "b. Los tumores muy infiltrados por LT CD8 tienen mejor pronóstico.", "c. Los anticuerpos antitumorales median ADCC y activan el complemento.", "d. El TNF del macrófago lisa al tumor, pero puede dar caquexia.", "e. Los macrófagos asociados a tumores (M2) destruyen el tumor con IL-10 y VEGF."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es falso: los TAM (M2) favorecen al tumor con IL-10, arginasa, TGF-β y VEGF; no lo destruyen.", "sin_banco": true, "ok": "", "x": "En la imagen el CD8 y la NK atacan a la célula tumoral, <span class=\"cx\">en cambio</span> los <mark>macrófagos naranjas de la masa (M2)</mark> la protegen con IL-10 y VEGF. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span> es la falsa.", "truco": "", "veces": 0}, {"n": 8, "id": "IN12-008", "c": "i", "tema": "Evasión tumoral", "pregunta": "¿Por qué la pérdida completa de HLA-I en un tumor es un arma de doble filo?", "opciones": ["a. Lo esconde de las NK y lo expone a los anticuerpos", "b. Lo esconde de los LT CD8 y lo expone a las NK", "c. Aumenta su inmunogenicidad para los LT CD4", "d. Le impide hacer metástasis", "e. Activa la vía clásica del complemento sobre él"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Lo esconde de los LT citotóxicos CD8, pero lo deja expuesto a las NK, que atacan a las células sin HLA propio.", "sin_banco": true, "ok": "", "x": "La célula tumoral de la izquierda está entre un CD8 y una NK. Si pierde el <mark>HLA-I</mark>, el CD8 deja de verla, pero la NK la reconoce justamente por esa falta. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN12-009", "c": "d", "tema": "Evasión tumoral", "pregunta": "¿Por qué un anticuerpo antitumoral de la subclase IgG4 puede favorecer el crecimiento del tumor?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque no activa el complemento: actúa como anticuerpo de bloqueo, ocupa el antígeno sin destruirlo e impide el complemento y la ADCC.", "sin_banco": true, "ok": "", "x": "Se une al antígeno tumoral como cualquier IgG, pero <mark>no enciende el complemento</mark>. <span class=\"cx\">Así que</span>, en vez de marcar al tumor, lo <span class=\"res\">tapa</span> frente a los mecanismos que sí lo matarían. Otros escapes: desprender antígenos, IL-10, VEGF, TGF-β y CCL21 que atrae linfocitos T reguladores.", "truco": "IgG4 = «escudo», no «espada».", "veces": 0}, {"n": 10, "id": "IN12-010", "c": "d", "tema": "Inmunodiagnóstico", "pregunta": "Paciente operado de cáncer de colon; su antígeno carcinoembrionario (CEA) bajó tras la cirugía y seis meses después vuelve a subir. ¿Qué indica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Recaída o metástasis: la caída tras la resección confirma la extirpación y la reelevación anuncia recurrencia.", "sin_banco": true, "ok": "", "x": "El CEA es un <mark>antígeno embrionario</mark> que reaparece con la transformación maligna y circula al desprenderse. Su mayor utilidad es el <span class=\"res\">seguimiento</span>. <span class=\"cx\">Cuando</span> un cáncer se detecta clínicamente ya mide 1 cm y tiene unas <b>10⁹ células</b>.", "truco": "CEA que vuelve a subir = tumor que vuelve.", "veces": 0}, {"n": 11, "id": "IN12-011", "c": "i", "tema": "Inmunoterapia", "pregunta": "El ipilimumab potencia la respuesta antitumoral porque bloquea:", "opciones": ["a. HER2", "b. VEGF", "c. CD20", "d. CTLA-4", "e. BCR-ABL"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. CTLA-4, molécula coestimuladora inhibitoria que el tumor usa para apagar al linfocito T; útil en melanoma.", "sin_banco": true, "ok": "", "x": "El tumor «silencia» al linfocito T activado a través de <mark>CTLA-4</mark>. Al bloquearlo, el LT citotóxico sigue atacando. Otros biofármacos: <span class=\"res\">trastuzumab</span> (anti-HER2, seno), bevacizumab (anti-VEGF), rituximab (anti-CD20), imatinib (BCR-ABL).", "truco": "IPI-limumab «quita el freno» CTLA-4.", "veces": 0}, {"n": 12, "id": "IN12-012", "c": "g", "tema": "Proliferaciones benignas", "pregunta": "¿Por qué la tos ferina (Bordetella pertussis) produce la linfocitosis reactiva más alta?", "opciones": ["a. Bloquea las integrinas endoteliales y los linfocitos no salen", "b. Estimula la médula con IL-7", "c. Transforma los linfocitos en un clon maligno", "d. Destruye el bazo", "e. Inhibe la apoptosis de los linfocitos por BCL-2"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Libera un factor que bloquea las integrinas del endotelio; los linfocitos no salen a los tejidos y se acumulan en sangre (hasta 60 000/mL).", "sin_banco": true, "ok": "", "x": "No es que se fabriquen más linfocitos: <mark>no pueden salir</mark> del vaso. <span class=\"cx\">Por eso</span> la sangre llega a <span class=\"res\">60 000 linfocitos/mL</span> mientras los tejidos tienen linfopenia paradójica. Puede confundirse con una leucemia; se aclara con el inmunofenotipo y la clonalidad.", "truco": "Pertussis «cierra la puerta» del vaso.", "veces": 0}, {"n": 13, "id": "IN12-013", "c": "g", "tema": "Proliferaciones benignas", "pregunta": "Mencione los umbrales de monocitosis en niños y adultos y dos enfermedades en que aparece.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Más de 750 monocitos/mL en niños y más de 500/mL en adultos; p. ej., tuberculosis y endocarditis bacteriana subaguda (también Hodgkin, mieloma, lupus, artritis reumatoide, colitis ulcerativa).", "sin_banco": true, "ok": "", "x": "Son cifras de examen: <mark>750 en niños, 500 en adultos</mark>. En la endocarditis bacteriana subaguda los monocitos llegan al <span class=\"res\">15-20 %</span> de los leucocitos. Linfocitosis en adulto: más de 4000/mL.", "truco": "Monocitosis «750 niño, 500 adulto».", "veces": 0}, {"n": 14, "id": "IN12-014", "c": "d", "tema": "Gammopatías", "pregunta": "Respecto a la gammopatía monoclonal benigna, es correcto:", "opciones": ["a. Cursa siempre con lesiones líticas óseas", "b. Es más frecuente en niños", "c. Afecta al 3 % de adultos mayores y 1 % al año evoluciona a mieloma", "d. Produce un pico policlonal en la electroforesis", "e. Se trata de inmediato con trasplante de médula"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Afecta a cerca del 3 % de los adultos mayores y el 1 % de los casos evoluciona cada año a mieloma.", "sin_banco": true, "ok": "", "x": "El clon plasmocitario de la derecha (punto Ⓒ) produce una sola Ig: el <mark>pico monoclonal</mark>. Sin lesiones líticas es gammopatía benigna, pero <span class=\"res\">1 % al año pasa a mieloma</span>: la c.", "truco": "", "veces": 0}, {"n": 15, "id": "IN12-015", "c": "d", "tema": "Macroglobulinemia", "pregunta": "¿Qué inmunoglobulina produce en exceso la macroglobulinemia de Waldenström, qué complicación causa y cuál es su tratamiento inicial?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "IgM en exceso; causa hiperviscosidad sanguínea y se trata con plasmaféresis. Tiene casi siempre la mutación MYD88 L265P.", "sin_banco": true, "ok": "", "x": "Son plasmocitos <mark>bien diferenciados</mark> que secretan IgM, una molécula grande (pentámero) que espesa la sangre. <span class=\"cx\">Por eso</span> la <span class=\"res\">plasmaféresis</span> mejora los síntomas; su evolución es más benigna que la del mieloma.", "truco": "Waldenström = «IgM espesa».", "veces": 0}, {"n": 16, "id": "IN12-016", "c": "d", "tema": "Leucemias de granulocitos", "pregunta": "Respecto a la leucemia mielocítica crónica, es FALSO:", "opciones": ["a. Se asocia a la traslocación t(9;22).", "b. Sus granulocitos son no funcionales desde el inicio.", "c. El imatinib inhibe la quinasa de tirosina BCR-ABL.", "d. Puede evolucionar a una fase blástica.", "e. Es paradigma de la terapia molecular dirigida."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Es falso: los granulocitos conservan su función en la fase crónica; la defensa se compromete en la fase blástica.", "sin_banco": true, "ok": "", "x": "En la LMC hay muchos granulocitos <mark>funcionales</mark>; con el avance llega la <b>fase blástica</b>, que reduce la eficacia fagocitaria. Lleva el <span class=\"res\">cromosoma Filadelfia (BCR-ABL)</span> y responde muy bien al mesilato de imatinib.", "truco": "", "veces": 0}, {"n": 17, "id": "IN12-017", "c": "d", "tema": "Linfocitos T", "pregunta": "Paciente de 60 años con placas eccematosas que evolucionan a eritrodermia exfoliativa; la biopsia muestra infiltración de la piel por linfocitos T anormales. ¿Diagnóstico y entidad afín?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Linfoma cutáneo de linfocitos T (micosis fungoide); la entidad afín es el síndrome de Sézary (eritrodermia con prurito intenso).", "sin_banco": true, "ok": "", "x": "Pese al nombre, la <mark>micosis fungoide no es un hongo</mark>: es un linfoma T de la piel. El <b>síndrome de Sézary</b> es su pariente con eritrodermia y <span class=\"res\">prurito intenso</span>. Otra proliferación T, la leucemia por HTLV-1, muestra núcleos polisegmentados.", "truco": "«Micosis» fungoide: nombre de hongo, alma de linfoma T.", "veces": 0}, {"n": 18, "id": "IN12-018", "c": "d", "tema": "Linfocitos B", "pregunta": "Inmunofenotipo de la leucemia linfocítica crónica de linfocitos B:", "opciones": ["a. CD3⁺, CD4⁺, CD8⁻", "b. CD34⁺, CD33⁺", "c. CD1a⁺ (células de Langerhans)", "d. CD19⁻, CD5⁻, IgM alta", "e. CD19⁺, CD5⁺, CD23⁺ con IgM e IgD disminuidas"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. CD19⁺, CD5⁺ y CD23⁺, con disminución de IgM e IgD de membrana; cursa con hipogammaglobulinemia.", "sin_banco": true, "ok": "", "x": "Son linfocitos B inmaduros que <mark>producen poco anticuerpo</mark>: <span class=\"cx\">por eso</span> hay hipogammaglobulinemia y el paciente se infecta, aunque la inmunidad celular esté conservada. Tratamiento innovador: <span class=\"res\">linfocitos T con TCR anti-CD19</span>.", "truco": "LLC «19-5-23».", "veces": 0}, {"n": 19, "id": "IN12-019", "c": "d", "tema": "Linfocitos B", "pregunta": "¿Qué célula es patognomónica de la enfermedad de Hodgkin y de qué línea proviene en la mayoría de los casos?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La célula de Reed-Sternberg (gigante, bi o multinucleada); en el 85 % proviene de linfocitos B, aunque perdió sus marcadores.", "sin_banco": true, "ok": "", "x": "Su presencia en el ganglio es <mark>patognomónica</mark>. Como perdió los marcadores B y en el 15 % el origen no se define, el Hodgkin <span class=\"res\">podría ser un grupo de enfermedades</span>. Es más común en adultos y se trata con rituximab (anti-CD20), entre otros.", "truco": "Reed-Sternberg = «ojos de búho» (literatura).", "veces": 0}, {"n": 20, "id": "IN12-020", "c": "d", "tema": "Linfocitos B", "pregunta": "Respecto al linfoma de Burkitt, es correcto:", "opciones": ["a. C-MYC, muy agresivo, 40 % de linfomas infantiles, 90 % de curación en niños", "b. BCR-ABL, curso lento, responde a imatinib", "c. BRAF, esplenomegalia y curso lento", "d. MYD88, IgM e hiperviscosidad", "e. Deleción del cromosoma 13 en el 50 %"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Se debe a la traslocación de C-MYC, es muy agresivo, representa el 40 % de los linfomas en niños y se cura en el 90 % con tratamiento precoz.", "sin_banco": true, "ok": "", "x": "Es el linfoma <mark>más agresivo</mark> de la lista, pero muy quimiosensible: <span class=\"res\">90 % de curación</span> en niños si se trata a tiempo. Se asocia al virus de Epstein-Barr, sobre todo en niños africanos. La mutación BRAF es, <span class=\"cx\">en cambio</span>, de la leucemia de células vellosas.", "truco": "Burkitt: «MYC-40-90».", "veces": 0}, {"n": 21, "id": "IN12-021", "c": "d", "tema": "Mieloma múltiple", "pregunta": "¿Por qué el mieloma múltiple produce lesiones óseas líticas?", "opciones": ["a. Por invasión bacteriana del hueso", "b. Por depósito de IgE en el periostio", "c. Por exceso de osteoblastos activados", "d. Por RANKL y TGF que activan osteoclastos y DKK1 que apaga osteoblastos", "e. Por déficit de vitamina D exclusivamente"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Sus plasmocitos secretan RANKL (activa osteoclastos) y TGF (sube IL-6 y VEGF), y a la vez DKK1, que inactiva a los osteoblastos.", "sin_banco": true, "ok": "", "x": "Es la derecha de la imagen: el <mark>osteoclasto</mark> (arriba) excava el hueso <span class=\"cx\">porque</span> el plasmocito le da RANKL, y el osteoblasto aplanado no repara <span class=\"cx\">porque</span> el DKK1 lo apaga. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 22, "id": "IN12-022", "c": "d", "tema": "Mieloma múltiple", "pregunta": "Varón de 68 años con dolor óseo lumbar, anemia, hipercalcemia, falla renal e infecciones a repetición; la electroforesis muestra un pico monoclonal. ¿Diagnóstico, célula responsable y fármaco que induce apoptosis en formas refractarias?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Mieloma múltiple, por un clon de células plasmáticas; en las formas refractarias se usa bortezomib, que induce su apoptosis.", "sin_banco": true, "ok": "", "x": "El clon plasmocitario produce una <mark>inmunoglobulina homogénea</mark> y desplaza la médula (anemia, infecciones). Tratamiento: melfalán, prednisona, radioterapia, talidomida (inhibe IL-6 y angiogénesis) y trasplante autólogo; la <b>lenalidomida</b> aumenta un segundo cáncer y el <span class=\"res\">bortezomib</span> sirve en las refractarias.", "truco": "Mieloma «CRAB» (literatura): calcio, riñón, anemia, hueso.", "veces": 0}], "tabla": {"cab": ["", "LMC", "LLC (B)", "Burkitt", "Mieloma"], "filas": [["Célula", "Granulocito funcional", "LB inmaduro CD19⁺ CD5⁺ CD23⁺", "Linfocito B", "Plasmocito"], ["Marca", "t(9;22) BCR-ABL", "IgM e IgD bajas", "C-MYC; VEB", "14q32 o deleción del 13"], ["Clave", "Fase blástica tardía", "Hipogammaglobulinemia", "Muy agresivo; 90 % se cura", "Lesiones líticas, calcio alto"], ["Tratamiento", "Imatinib", "Rituximab; LT anti-CD19", "Quimioterapia precoz", "Melfalán, talidomida, bortezomib"], ["🔑 Para diferenciar", "Filadelfia", "CD5 en un B", "MYC", "RANKL + DKK1"]]}, "fuente": "Fuente: tu teoría — clase 28 (Cáncer y respuesta inmune) y clase 29 (Enfermedades proliferativas de las células del sistema inmune), Rojas 17.ª ed."}, {"n": 22, "slug": "Inmunodeficiencias_combinadas", "titulo": "Inmunodeficiencias combinadas y sindrómicas", "subtitulo": "sin linfocito T no hay defensa: IDCS, hiper-IgM, DiGeorge, Wiskott-Aldrich y ataxia-telangiectasia", "grupo": "g13", "lema": "La idea: las <mark>inmunodeficiencias primarias</mark> son defectos <b>genéticos</b> del sistema inmune (1 en 2.000 nacidos vivos), más frecuentes en <b>varones</b> porque muchas son ligadas al X. En las <mark>combinadas</mark> falla el <b>linfocito T</b> y, como el T ayuda al B, también fallan los anticuerpos: la <u>IDCS es una emergencia pediátrica</u> que solo se cura con trasplante de células madre. Algunas traen «pistas» fuera del sistema inmune (corazón, plaquetas, cerebelo). En la imagen: timo normal y ausente, linfocito T con el receptor roto, la pareja T–B sin CD40L y un frotis con plaquetas diminutas.", "img": "img/22.webp", "mini": "img/mini/22.webp", "ratio": 1.5, "etiquetas": [{"n": "①②", "t": "Timo normal", "s": "escuela del<br>linfocito T", "c": "g", "x": 0.5, "y": 6, "ax": 12.5, "ay": 29, "al": "l"}, {"n": "", "t": "Interleucinas", "s": "IL-2, 4, 7, 9,<br>15 y 21 sin señal", "c": "d", "x": 27, "y": 6, "ax": 35.5, "ay": 24}, {"n": "③", "t": "Cadena γc rota", "s": "IDCS-XL:<br>T−B+NK−", "c": "i", "x": 43, "y": 6, "ax": 39, "ay": 36, "d": "D"}, {"n": "⑨", "t": "Linfocito T", "s": "sin HLA-II<br>no hay CD4", "c": "i", "x": 57.5, "y": 6, "ax": 52, "ay": 36}, {"n": "⑧", "t": "Sin CD40L", "s": "no hay cambio<br>de isotipo", "c": "i", "x": 72, "y": 6, "ax": 61, "ay": 41.5}, {"n": "", "t": "Plaquetas normales", "s": "referencia<br>de tamaño", "c": "g", "x": 99.5, "y": 6, "ax": 82, "ay": 47, "al": "r"}, {"n": "⑥⑪", "t": "Timo ausente", "s": "IDCS o DiGeorge:<br>linfopenia severa", "c": "d", "x": 0.5, "y": 91, "ax": 12, "ay": 60, "d": "A", "al": "l"}, {"n": "⑪", "t": "Corazón", "s": "cardiopatía<br>conotruncal", "c": "d", "x": 22, "y": 91, "ax": 14, "ay": 72, "d": "B"}, {"n": "④", "t": "JAK3 suelta", "s": "misma falla,<br>herencia AR", "c": "i", "x": 37, "y": 91, "ax": 41, "ay": 49}, {"n": "⑧", "t": "Solo IgM", "s": "hiper-IgM:<br>IgG, IgA, IgE bajas", "c": "d", "x": 55, "y": 91, "ax": 66, "ay": 63}, {"n": "", "t": "Linfocito B", "s": "espera la<br>ayuda del T", "c": "g", "x": 72, "y": 91, "ax": 71, "ay": 50}, {"n": "⑩", "t": "Plaquetas diminutas", "s": "Wiskott-Aldrich:<br>sangrado + eczema", "c": "d", "x": 99.5, "y": 91, "ax": 92.5, "ay": 55, "d": "C", "al": "r"}], "diapos": [{"img": "img/22.webp", "ratio": 1.5, "titulo": "Timo, cadena γc, CD40L y plaquetas", "texto": "Sin timo no hay LT (DiGeorge) ⑪; sin <mark>γc</mark> o JAK3 nada madura ③④; sin CD40L solo hay <b>IgM</b> ⑧; Wiskott-Aldrich da plaquetas pequeñas <span class=\"lt2\">C</span> ⑩.", "etiquetas": [{"n": "①②", "t": "Timo normal", "s": "escuela del<br>linfocito T", "c": "g", "x": 0.5, "y": 6, "ax": 12.5, "ay": 29, "al": "l"}, {"n": "", "t": "Interleucinas", "s": "IL-2, 4, 7, 9,<br>15 y 21 sin señal", "c": "d", "x": 27, "y": 6, "ax": 35.5, "ay": 24}, {"n": "③", "t": "Cadena γc rota", "s": "IDCS-XL:<br>T−B+NK−", "c": "i", "x": 43, "y": 6, "ax": 39, "ay": 36, "d": "D"}, {"n": "⑨", "t": "Linfocito T", "s": "sin HLA-II<br>no hay CD4", "c": "i", "x": 57.5, "y": 6, "ax": 52, "ay": 36}, {"n": "⑧", "t": "Sin CD40L", "s": "no hay cambio<br>de isotipo", "c": "i", "x": 72, "y": 6, "ax": 61, "ay": 41.5}, {"n": "", "t": "Plaquetas normales", "s": "referencia<br>de tamaño", "c": "g", "x": 99.5, "y": 6, "ax": 82, "ay": 47, "al": "r"}, {"n": "⑥⑪", "t": "Timo ausente", "s": "IDCS o DiGeorge:<br>linfopenia severa", "c": "d", "x": 0.5, "y": 91, "ax": 12, "ay": 60, "d": "A", "al": "l"}, {"n": "⑪", "t": "Corazón", "s": "cardiopatía<br>conotruncal", "c": "d", "x": 22, "y": 91, "ax": 14, "ay": 72, "d": "B"}, {"n": "④", "t": "JAK3 suelta", "s": "misma falla,<br>herencia AR", "c": "i", "x": 37, "y": 91, "ax": 41, "ay": 49}, {"n": "⑧", "t": "Solo IgM", "s": "hiper-IgM:<br>IgG, IgA, IgE bajas", "c": "d", "x": 55, "y": 91, "ax": 66, "ay": 63}, {"n": "", "t": "Linfocito B", "s": "espera la<br>ayuda del T", "c": "g", "x": 72, "y": 91, "ax": 71, "ay": 50}, {"n": "⑩", "t": "Plaquetas diminutas", "s": "Wiskott-Aldrich:<br>sangrado + eczema", "c": "d", "x": 99.5, "y": 91, "ax": 92.5, "ay": 55, "d": "C", "al": "r"}]}, {"img": "img/22_2.webp", "ratio": 1.5, "titulo": "ADA, HLA-II y Omenn", "texto": "En la deficiencia de <mark>ADA</mark> los metabolitos de purinas matan al linfocito ⑤; sin HLA-II no se seleccionan los CD4 ⑨; el <b>Omenn</b> imita una alergia severa ⑦.", "etiquetas": [{"n": "⑤", "t": "ADA rota", "s": "enzima de<br>las purinas", "c": "d", "x": 8, "y": 6, "ax": 9.8, "ay": 26.0}, {"n": "⑨", "t": "LT que no maduran", "s": "sin selección<br>de los CD4", "c": "g", "x": 26, "y": 6, "ax": 38.4, "ay": 27.0}, {"n": "⑨", "t": "Sin HLA-II", "s": "huecos vacíos<br>en el epitelio", "c": "d", "x": 46, "y": 6, "ax": 50.0, "ay": 37.0}, {"n": "⑦", "t": "Eritrodermia", "s": "piel roja que<br>descama", "c": "d", "x": 74, "y": 6, "ax": 75.0, "ay": 26.0}, {"n": "⑦", "t": "Ganglio grande", "s": "adenopatías", "c": "g", "x": 99.5, "y": 6, "ax": 92.4, "ay": 40.0, "al": "r"}, {"n": "⑤", "t": "Metabolitos", "s": "tóxicos, de<br>purinas", "c": "d", "x": 0.5, "y": 92, "ax": 8.5, "ay": 51.0, "al": "l"}, {"n": "⑤", "t": "Linfocito muere", "s": "núcleo<br>fragmentado", "c": "d", "x": 28, "y": 92, "ax": 16.3, "ay": 52.7}, {"n": "⑨", "t": "Epitelio tímico", "s": "no presenta<br>a los CD4", "c": "g", "x": 47, "y": 92, "ax": 45.6, "ay": 47.0}, {"n": "⑦", "t": "LT infiltrando", "s": "oligoclonales,<br>activados", "c": "d", "x": 66, "y": 92, "ax": 71.6, "ay": 54.7}, {"n": "⑦", "t": "Eosinófilos", "s": "parece una<br>alergia severa", "c": "d", "x": 85, "y": 92, "ax": 79.4, "ay": 50.0}]}, {"img": "img/22_3.webp", "ratio": 1.5, "titulo": "Signos de las sindrómicas", "texto": "Telangiectasias y ataxia ⑫; eccema con <mark>petequias</mark> (Wiskott-Aldrich) ⑩; abscesos fríos, neumatoceles e <mark>IgE muy alta</mark> <span class=\"lt2\">E</span> (STAT3) ⑬.", "etiquetas": [{"n": "⑫", "t": "Telangiectasias", "s": "vasos dilatados<br>en la conjuntiva", "c": "d", "x": 8, "y": 6, "ax": 7.2, "ay": 26.0}, {"n": "⑩", "t": "Eccema", "s": "placas rojas<br>y ásperas", "c": "d", "x": 38, "y": 6, "ax": 44.3, "ay": 35.0}, {"n": "⑬", "t": "Neumatoceles", "s": "quistes de<br>pared fina", "c": "g", "x": 66, "y": 6, "ax": 69.0, "ay": 27.0}, {"n": "⑬", "t": "Eosinofilia", "s": "con IgE alta", "c": "d", "x": 88, "y": 6, "ax": 82.7, "ay": 40.0, "d": "E"}, {"n": "⑫", "t": "Cerebelo atrófico", "s": "ataxia<br>progresiva", "c": "g", "x": 12, "y": 92, "ax": 21.5, "ay": 70.0}, {"n": "⑩", "t": "Hematoma", "s": "plaquetas<br>pequeñas y pocas", "c": "d", "x": 32, "y": 92, "ax": 35.8, "ay": 58.6}, {"n": "⑩", "t": "Petequias", "s": "puntos de<br>sangrado", "c": "d", "x": 52, "y": 92, "ax": 51.4, "ay": 58.6}, {"n": "⑬", "t": "Absceso frío", "s": "estafilococo<br>sin rubor", "c": "d", "x": 84, "y": 92, "ax": 85.3, "ay": 52.0}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = lo que falla</b> (la célula, el gen o la molécula), <b class=\"d\">rojo = lo que produce</b> (la infección, el síntoma o el dato de laboratorio), gris = estructuras de referencia.", "<b>Izquierda:</b> el timo es la «escuela» del linfocito T. Si no se forma (<mark>DiGeorge</mark>, 3.ª y 4.ª bolsas faríngeas) o si el T no puede madurar (IDCS), la radiografía no muestra sombra tímica <span class=\"lt2\">A</span>.", "<b>Centro izquierda:</b> la <mark>cadena γc</mark> es común a seis receptores (IL-2, 4, 7, 9, 15 y 21) y la JAK3 lleva su señal adentro; <span class=\"cx\">por eso</span> su falta (XL) y la de JAK3 (AR) son idénticas <span class=\"lt2\">D</span>.", "<b>Centro derecha:</b> sin <mark>CD40L</mark> el linfocito B no cambia de isotipo y solo fabrica IgM. <b>Derecha:</b> en el Wiskott-Aldrich las plaquetas son pequeñas <span class=\"lt2\">C</span> y sangran."], "recordar": "<b>T−B+</b> = γc o JAK3; <b>T−B−NK−</b> = ADA. Hiper-IgM = CD40L. Timo + corazón + calcio = <b>DiGeorge</b>. Plaquetas chicas + eczema = <b>Wiskott-Aldrich</b>. Ataxia + telangiectasias + alfa-fetoproteína = <b>AT</b>."}, "numeros": [{"l": "A", "html": "<b>IDCS</b>: <b class=\"a\">1 en 25.000</b> nacidos vivos; todas las IDP juntas <b class=\"a\">1 en 2.000</b>, más del <b class=\"n\">80 %</b> diagnosticadas antes de los 5 años, varones <b class=\"a\">5:1</b>.", "rango": null}, {"l": "B", "html": "<b>DiGeorge</b>: deleción <b class=\"a\">22q11.2</b> en más del 90 %, <b class=\"a\">1 en 3.000</b> nacidos vivos; cardiopatía conotruncal <b class=\"a\">>90 %</b>, hipoplasia tímica <b class=\"a\">80–90 %</b>, hipocalcemia <b class=\"a\">60 %</b>.", "rango": null}, {"l": "C", "html": "<b>Wiskott-Aldrich</b>: plaquetas de volumen <b class=\"b\">menor de 5 fl</b>; tríada completa solo en <b class=\"n\">un tercio</b>.", "rango": {"min": 0, "max": 10, "unidad": "fl (volumen plaquetario)", "zonas": [[0, 5, "b"]], "marcas": [5]}}, {"l": "D", "html": "<b>IDCS-XL</b> (cadena γc): <b class=\"a\">más del 40 %</b> de todas las IDCS; la IDC es el <b class=\"n\">20 %</b> de las IDP y la sindrómica el <b class=\"n\">15 %</b>.", "rango": null}, {"l": "E", "html": "<b>Hiper-IgE (STAT3)</b>: IgE sérica <b class=\"a\">mayor de 2.000 UI/mL</b> con eosinofilia; STAT3 en <b class=\"a\">más del 90 %</b>.", "rango": {"min": 0, "max": 4000, "unidad": "UI/mL de IgE", "zonas": [[2000, 4000, "a"]], "marcas": [2000]}}], "escalas": [], "cadena": {"titulo": "Del gen roto al lactante grave", "subtitulo": "defecto genético → linfocito T que no madura → B sin ayuda → infecciones → qué hacer", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Defecto genético", "m": "<b>Qué pasa:</b> una mutación <mark>ligada al X</mark> (γc, CD40L, WAS) o autosómica (JAK3, ADA, RAG, ATM) toca un gen del desarrollo inmune.", "pr": "por eso predominan los varones (5:1) y se diagnostica antes de los 5 años.", "pr_tit": "Produce:", "rf": "Preguntas ①② · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. El T no madura", "m": "<b>Por qué:</b> sin la cadena γc o la JAK3 el precursor no recibe la IL-7 (y el NK la IL-15); en la <mark>deficiencia de ADA</mark> los metabolitos de purinas matan T, B y NK.", "pr": "linfopenia severa: fenotipo T−B+ (γc) o T−B−NK− (ADA).", "pr_tit": "Produce:", "rf": "Preguntas ③④⑤ · punto <span class=\"lt2\">D</span>", "color": "p2"}, {"t": "3. El B sin ayuda", "m": "<b>Qué produce:</b> sin <mark>CD40L</mark> el B no cambia de isotipo (solo IgM); sin HLA-II no hay CD4 que ayuden. Las mutaciones hipomórficas dejan T autorreactivos (<b>Omenn</b>).", "pr": "hipogammaglobulinemia o hiper-IgM; en Omenn, IgE alta y eritrodermia.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑧⑨", "color": "p3"}, {"t": "4. Clínica", "m": "<b>Qué pasa:</b> lactante con infecciones graves por Candida, P. jirovecii, CMV, falla en el medro y <mark>timo ausente</mark>.", "pr": "IDCS: emergencia pediátrica.", "pr_tit": "Produce:", "rf": "Pregunta ⑥ · punto <span class=\"lt2\">A</span>", "color": "p4"}, {"t": "5. Pistas sindrómicas", "m": "<b>Por qué ayudan:</b> el defecto toca otros tejidos: corazón y calcio (<mark>DiGeorge</mark>), plaquetas y piel (Wiskott-Aldrich), cerebelo y vasos (ataxia-telangiectasia), dientes y Th17 (hiper-IgE).", "pr": "el fenotipo no inmune orienta el diagnóstico.", "pr_tit": "Produce:", "rf": "Preguntas ⑩⑪⑫⑬ · puntos <span class=\"lt2\">B</span><span class=\"lt2\">C</span>", "color": "p5"}, {"t": "6. Si no se trata", "m": "<b>Desenlace:</b> el lactante con IDCS muere de infección; la AT termina en neumopatía o <mark>linfoma</mark>. <b>Tratamiento:</b> trasplante de células madre hematopoyéticas o terapia génica.", "pr": "el retraso diagnóstico define el pronóstico.", "pr_tit": "Produce:", "rf": "Pregunta ⑥", "color": "p4"}], "extra": [{"html": "🧪 <b>Pistas de laboratorio:</b> IDCS = linfopenia severa y sin fracción gamma · CD40L = IgM normal o alta · AT = <mark>alfa-fetoproteína alta</mark> · WAS = plaquetas menores de 5 fl · SHIE-AD = IgE mayor de 2.000 UI/mL · Omenn = IgE alta con eosinofilia.", "k": ""}, {"html": "⚠️ <b>Ojo:</b> el niño con IDCS no debe recibir vacunas de virus o bacterias vivas (BCG) (literatura): sin linfocitos T pueden diseminarse.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De la IDC leve a la emergencia", "pasos": ["IDC no severa: T en número normal, falla una subpoblación (ZAP-70, CD8, HLA-I)", "deficiencia de HLA-II: sin CD4, cuadro tipo IDCS", "DiGeorge parcial: linfopenia leve", "DiGeorge completo (&lt;1 %): equivale a IDCS", "<b>IDCS</b>: sin T, infecciones mortales → TCMH"]}], "html": "", "fuente": "Fuente: tu teoría — clase 30a (IDCS T−B+ y T−B−, Omenn, CD40L, IDC no severas, ataxia-telangiectasia, Wiskott-Aldrich, DiGeorge e hiper-IgE AD)."}, "preguntas": [{"n": 1, "id": "IN13-001", "c": "i", "tema": "Epidemiología", "pregunta": "¿Cuál es la frecuencia estimada de las inmunodeficiencias primarias (IDP) en nacidos vivos?", "opciones": ["a. 1 en 200", "b. 1 en 2.000", "c. 1 en 25.000", "d. 1 en 100.000", "e. 1 en 500.000"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. 1 en cada 2.000 nacidos vivos; en la población general, 1 en 5.000.", "sin_banco": true, "ok": "", "x": "Las IDP se llaman «raras», pero su frecuencia real es mayor de lo esperado: <mark>1 en 2.000 nacidos vivos</mark>. El 1 en 25.000 es solo de la IDCS, <span class=\"cx\">en cambio</span> el 1 en 2.000 abarca todas. <span class=\"cx\">Además</span>, <span class=\"res\">más del 80 % se diagnostica antes de los 5 años</span>.", "truco": "«Dos mil nacen, uno falla»: 1/2.000 todas, 1/25.000 la severa.", "veces": 0}, {"n": 2, "id": "IN13-002", "c": "i", "tema": "Epidemiología", "pregunta": "¿Por qué las IDP predominan en niños varones sobre niñas (5:1) y esa diferencia desaparece en adolescentes y adultos?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque muchas formas graves son ligadas al X (XL) y afectan a varones; en adolescentes y adultos predominan las formas autosómicas (AR y AD), por eso la proporción se iguala.", "sin_banco": true, "ok": "", "x": "El varón tiene un solo cromosoma X, <span class=\"cx\">así que</span> una mutación <mark>ligada al X</mark> se expresa completa. Las formas graves (IDCS-XL, Bruton, Wiskott-Aldrich) debutan en el lactante. <span class=\"cx\">En cambio</span>, las formas tardías son AR o AD, <span class=\"cx\">por eso</span> <span class=\"res\">la relación 5:1 se iguala con la edad</span>.", "truco": "X = varón pequeño; autosómica = cualquiera, más tarde.", "veces": 0}, {"n": 3, "id": "IN13-003", "c": "i", "tema": "IDCS", "pregunta": "La inmunodeficiencia combinada severa más frecuente (más del 40 % de los casos) se debe a mutación en:", "opciones": ["a. ADA", "b. RAG1/RAG2", "c. JAK3", "d. IL-2RG (cadena γc)", "e. AK2"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. IL-2RG, que codifica la cadena γc común de los receptores de IL-2, IL-4, IL-7, IL-9, IL-15 e IL-21 (IDCS-XL, fenotipo T−B+).", "sin_banco": true, "ok": "", "x": "Es el receptor roto del linfocito de la imagen: la <mark>cadena γc</mark> es la pieza común de seis receptores de interleucinas (punto Ⓓ). <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>, la IDCS más frecuente.", "truco": "", "veces": 0}, {"n": 4, "id": "IN13-004", "c": "i", "tema": "IDCS", "pregunta": "¿Por qué la deficiencia de JAK3 es clínica e inmunológicamente indistinguible de la IDCS ligada al X?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque JAK3 se asocia físicamente a la cadena γc y transmite su señal; sin JAK3 los mismos receptores de interleucinas quedan mudos, aunque la herencia sea autosómica recesiva.", "sin_banco": true, "ok": "", "x": "El receptor recibe la citoquina, pero quien <mark>transmite la señal</mark> hacia adentro es la quinasa JAK3 pegada a la γc. <span class=\"cx\">Así que</span> da igual que falle el receptor o su quinasa: el bloqueo es el mismo. La diferencia está en la herencia: <span class=\"res\">XL la γc, AR la JAK3</span>.", "truco": "Receptor sin JAK3 = teléfono sin cable.", "veces": 0}, {"n": 5, "id": "IN13-005", "c": "i", "tema": "IDCS", "pregunta": "La deficiencia de adenosina desaminasa (ADA) produce IDCS porque:", "opciones": ["a. Bloquea la recombinación V(D)J", "b. Impide la señal de la cadena γc", "c. Acumula metabolitos de purinas proapoptóticos que matan linfocitos T, B y NK", "d. Destruye el epitelio tímico", "e. Impide la expresión de HLA-II"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es un error innato del metabolismo de purinas: los metabolitos acumulados son proapoptóticos y dan fenotipo T−B−NK−.", "sin_banco": true, "ok": "", "x": "La ADA trabaja en la vía de salvamento de purinas; si falta, se acumulan <mark>metabolitos tóxicos</mark> que los linfocitos, por su alta proliferación, no toleran. <span class=\"cx\">Por eso</span> caen T, B y NK. <span class=\"cx\">Además</span> es un error metabólico, <span class=\"cx\">así que</span> da <span class=\"res\">displasia osteocondral, sordera y daño renal, hepático y neurológico</span>.", "truco": "ADA = «A Desaparecen All»: T, B y NK.", "veces": 0}, {"n": 6, "id": "IN13-006", "c": "d", "tema": "IDCS", "pregunta": "Lactante de 4 meses con candidiasis persistente, neumonía por P. jirovecii, diarrea y falla en el medro. La radiografía no muestra sombra tímica y el hemograma revela linfopenia severa. ¿Diagnóstico probable y tratamiento definitivo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Inmunodeficiencia combinada severa (IDCS), una emergencia pediátrica; el tratamiento definitivo es el trasplante de células madre hematopoyéticas (o terapia génica).", "sin_banco": true, "ok": "", "x": "Lo ves a la izquierda: el pecho de abajo <mark>no tiene timo</mark> (punto Ⓐ). Lactante con oportunistas, sin timo y con linfopenia = IDCS, y <span class=\"res\">se trata con trasplante de células madre</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN13-007", "c": "i", "tema": "IDCS", "pregunta": "¿Qué es el síndrome de Omenn y por qué se confunde con una alergia severa?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es una IDCS por mutaciones hipomórficas (IL-2RG, IL7Rα, RMRP, ADA): hay LT normales o altos pero autorreactivos, con eritrodermia descamativa, diarrea, hepatoesplenomegalia, eosinofilia e IgE elevada.", "sin_banco": true, "ok": "", "x": "Una mutación <mark>hipomórfica</mark> reduce la función del gen sin anularla, <span class=\"cx\">así que</span> salen pocos clones T y <span class=\"cx\">además</span> autorreactivos. Esos clones inflaman la piel y el intestino, y suben la eosinofilia y la IgE. <span class=\"cx\">Por eso</span> parece una dermatitis atópica grave, <span class=\"cx\">en cambio</span> es <span class=\"res\">una IDCS con hipogammaglobulinemia</span>.", "truco": "Omenn = IDCS «disfrazada» de alergia roja.", "veces": 0}, {"n": 8, "id": "IN13-008", "c": "d", "tema": "Deficiencia de CD40L", "pregunta": "En la deficiencia de CD40L (ligada al X), el perfil de inmunoglobulinas típico es:", "opciones": ["a. Ausencia de todas las inmunoglobulinas", "b. IgA aislada baja con el resto normal", "c. IgE mayor de 2.000 UI/mL", "d. IgM baja con IgA normal o alta", "e. IgM normal o elevada con descenso severo de IgG, IgA e IgE"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Sin la señal CD40L–CD40 el linfocito B no hace cambio de isotipo ni hipermutación: solo produce IgM.", "sin_banco": true, "ok": "", "x": "En la imagen falta el puente entre el T y el B, y el B suelta solo estrellas de cinco brazos (IgM). Sin <mark>CD40L</mark> no hay cambio de isotipo, <span class=\"cx\">así que</span> <span class=\"res\">la e</span>: IgM normal o alta y lo demás bajo.", "truco": "", "veces": 0}, {"n": 9, "id": "IN13-009", "c": "i", "tema": "IDC no severas", "pregunta": "La deficiencia de HLA clase II produce un cuadro tipo IDCS porque:", "opciones": ["a. No se seleccionan ni maduran en el timo los linfocitos T CD4+", "b. Falta la cadena γc", "c. Se pierden los linfocitos T CD8+", "d. Todos los linfocitos T son TCRγδ+", "e. Se acumulan metabolitos de purinas"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Sin HLA-II no hay selección tímica de los CD4+; hay linfopenia CD4 selectiva e hipo o agamaglobulinemia por falta de ayuda T al linfocito B.", "sin_banco": true, "ok": "", "x": "Los linfocitos CD4 se seleccionan en el timo reconociendo péptidos en <mark>HLA-II</mark>. Si esa molécula falta, no maduran CD4 y, sin ayudantes, el linfocito B tampoco produce anticuerpos. <span class=\"cx\">En cambio</span>, la falta de HLA-I deja sin <span class=\"res\">CD8</span>.", "truco": "Regla del 8: HLA-I × CD8 = 8; HLA-II × CD4 = 8.", "veces": 0}, {"n": 10, "id": "IN13-010", "c": "d", "tema": "Síndrome de Wiskott-Aldrich", "pregunta": "Sobre el síndrome de Wiskott-Aldrich, todo es correcto EXCEPTO:", "opciones": ["a. Se debe a mutaciones ligadas al X en el gen WAS", "b. Su tríada es trombocitopenia, inmunodeficiencia y eczema", "c. Las plaquetas son gigantes, de más de 15 fl", "d. La tríada completa aparece solo en un tercio de los pacientes", "e. Suele tener IgA normal o alta e IgE elevada"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es falso: las plaquetas del Wiskott-Aldrich son pequeñas, con volumen menor de 5 fl.", "sin_banco": true, "ok": "", "x": "Mira el frotis de la derecha (punto Ⓒ): las plaquetas del Wiskott-Aldrich son <mark>diminutas</mark>, no gigantes. <span class=\"cx\">Por eso</span> <span class=\"res\">la c es la falsa</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN13-011", "c": "d", "tema": "Síndrome de DiGeorge", "pregunta": "El síndrome de DiGeorge se debe en más del 90 % de los casos a:", "opciones": ["a. Mutación en ATM", "b. Microdeleción en el cromosoma 22q11.2 que altera la 3.ª y 4.ª bolsas faríngeas", "c. Mutación en STAT3", "d. Trisomía 21", "e. Mutación en FOXP3"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Microdeleción 22q11.2 (1 en 3.000 nacidos vivos): hipoplasia tímica, cardiopatía conotruncal e hipoparatiroidismo con hipocalcemia.", "sin_banco": true, "ok": "", "x": "El timo ausente y el tracto de salida del corazón alterado (punto Ⓑ) vienen de la misma zona embrionaria: la <mark>3.ª y 4.ª bolsas faríngeas</mark>. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN13-012", "c": "d", "tema": "Defectos de reparación del ADN", "pregunta": "Niño de 6 años con marcha inestable progresiva, vasitos dilatados en las conjuntivas y neumonías a repetición. ¿Qué hallazgo sérico apoya el diagnóstico?", "opciones": ["a. IgE mayor de 2.000 UI/mL", "b. Ausencia de linfocitos B", "c. Alfa-fetoproteína elevada", "d. Plaquetas menores de 5 fl", "e. Hipocalcemia"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es una ataxia-telangiectasia (mutación AR en ATM): la alfa-fetoproteína sérica elevada es su marcador diagnóstico.", "sin_banco": true, "ok": "", "x": "Ataxia + telangiectasias + infecciones respiratorias = <mark>ataxia-telangiectasia</mark>. El gen ATM repara el ADN, <span class=\"cx\">así que</span> <span class=\"cx\">además</span> hay linfopenia T progresiva, deficiencia de IgA e IgE y riesgo de linfomas. <span class=\"cx\">En cambio</span> el síndrome de Nijmegen da microcefalia y <span class=\"res\">no eleva la alfa-fetoproteína</span>.", "truco": "AT = «Alfa-feTo» alta.", "veces": 0}, {"n": 13, "id": "IN13-013", "c": "d", "tema": "Síndrome de hiper-IgE", "pregunta": "¿Cuál es el gen y el perfil inmune cardinal del síndrome de hiper-IgE autosómico dominante?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "STAT3 (más del 90 %): IgE sérica mayor de 2.000 UI/mL, eosinofilia y deficiencia marcada de linfocitos Th17; da dermatitis, candidiasis mucocutánea y neumonías con neumatoceles.", "sin_banco": true, "ok": "", "x": "El STAT3 transmite la señal que forma los <mark>Th17</mark>; sin ellos fallan las defensas de piel y mucosa contra Candida y estafilococo. <span class=\"cx\">Por eso</span> hay abscesos, candidiasis y neumatoceles. <span class=\"cx\">Además</span> no muda la dentición decidual y hay escoliosis, y <span class=\"res\">la IgE pasa de 2.000 UI/mL</span>.", "truco": "STAT3: «3 S»: Staphylococcus, Sin Th17, Sin muda de dientes.", "veces": 0}], "tabla": {"cab": ["", "Gen", "Pista clínica", "Laboratorio"], "filas": [["IDCS-XL", "IL-2RG (γc)", "Lactante con oportunistas, sin timo", "T−B+NK−"], ["Déficit ADA", "ADA", "IDCS + displasia ósea, sordera", "T−B−NK−"], ["Hiper-IgM", "CD40L (XL)", "P. jirovecii, Cryptosporidium", "IgM normal o alta"], ["DiGeorge", "22q11.2", "Cardiopatía, hipocalcemia", "LT bajos"], ["Wiskott-Aldrich", "WAS (XL)", "Sangrado + eczema", "Plaquetas &lt; 5 fl"], ["Ataxia-telang.", "ATM", "Ataxia + telangiectasias", "Alfa-fetoproteína alta"], ["Hiper-IgE AD", "STAT3", "Abscesos, neumatoceles", "IgE > 2.000, sin Th17"], ["🔑 Para diferenciar", "XL = varón", "La pista no inmune delata el síndrome", "Un dato de laboratorio por síndrome"]]}, "fuente": "Fuente: tu teoría — clase 30a (Inmunodeficiencias primarias: concepto, epidemiología, combinadas y sindrómicas), Rojas 17.ª ed., cap. 30."}, {"n": 23, "slug": "Anticuerpos_fagocitos_complemento", "titulo": "Deficiencias de anticuerpos, fagocitos y complemento", "subtitulo": "qué brazo falla dice qué germen ataca: encapsuladas, catalasa positivos, micobacterias o Neisseria", "grupo": "g13", "lema": "La idea: la clasificación IUIS ordena las IDP por el <b>brazo que falla</b>, y cada brazo deja pasar un tipo de germen. Las <mark>deficiencias de anticuerpos</mark> son las más frecuentes (más del 50 %) y dan neumonías y diarreas por <b>encapsuladas</b>; si falla el <mark>fagocito</mark> ganan los catalasa positivos, hongos y micobacterias; si falla el <mark>complemento</mark>, la <b>Neisseria</b> o el lupus. Importa porque <u>el germen orienta el diagnóstico</u>. En la imagen: el B que no madura, neutrófilos atrapados en el vaso, un neutrófilo con microbios vivos junto a un granuloma y meningococos que el complemento no perfora.", "img": "img/23.webp", "mini": "img/mini/23.webp", "ratio": 1.5, "etiquetas": [{"n": "", "t": "Pro-B / pre-B", "s": "la médula lo forma<br>pero ahí se detiene", "c": "g", "x": 0.5, "y": 6, "ax": 13, "ay": 41, "al": "l"}, {"n": "⑦", "t": "Neutrófilos atrapados", "s": "LAD: sin CD18 no salen;<br>afuera, bacterias sin pus", "c": "i", "x": 29, "y": 6, "ax": 42, "ay": 44}, {"n": "⑧", "t": "Neutrófilo de la EGC", "s": "come, pero<br>no mata", "c": "i", "x": 49, "y": 6, "ax": 54, "ay": 31}, {"n": "⑧⑨", "t": "Granuloma", "s": "macrófagos que<br>encierran al microbio", "c": "d", "x": 69, "y": 6, "ax": 75.5, "ay": 40}, {"n": "⑪", "t": "Meningococos", "s": "Neisseria<br>que sobrevive", "c": "d", "x": 99.5, "y": 6, "ax": 94, "ay": 32, "al": "r"}, {"n": "②", "t": "Bloqueo BTK", "s": "Bruton: el pre-B<br>no recibe señal", "c": "i", "x": 0.5, "y": 91, "ax": 19, "ay": 48, "d": "A", "al": "l"}, {"n": "①③④", "t": "B maduro ausente", "s": "sin anticuerpos:<br>encapsuladas", "c": "d", "x": 28, "y": 91, "ax": 24, "ay": 52, "d": "D"}, {"n": "⑧", "t": "Vacuola sin estallido", "s": "sin NADPH-oxidasa:<br>catalasa + vivos", "c": "i", "x": 58, "y": 91, "ax": 64, "ay": 52, "d": "B"}, {"n": "⑪", "t": "Complemento sin poro", "s": "sin C5–C8 no se<br>arma el ataque", "c": "i", "x": 99.5, "y": 91, "ax": 90.5, "ay": 55.5, "d": "C", "al": "r"}], "diapos": [{"img": "img/23.webp", "ratio": 1.5, "titulo": "Anticuerpos, fagocitos y complemento", "texto": "Bruton frena al LB <span class=\"lt2\">A</span> ②; en la LAD-1 el neutrófilo no sale ⑦; en la EGC no hay explosión respiratoria <span class=\"lt2\">B</span> ⑧; sin C5-C8 vuelve la <b>Neisseria</b> ⑪.", "etiquetas": [{"n": "", "t": "Pro-B / pre-B", "s": "la médula lo forma<br>pero ahí se detiene", "c": "g", "x": 0.5, "y": 6, "ax": 13, "ay": 41, "al": "l"}, {"n": "⑦", "t": "Neutrófilos atrapados", "s": "LAD: sin CD18 no salen;<br>afuera, bacterias sin pus", "c": "i", "x": 29, "y": 6, "ax": 42, "ay": 44}, {"n": "⑧", "t": "Neutrófilo de la EGC", "s": "come, pero<br>no mata", "c": "i", "x": 49, "y": 6, "ax": 54, "ay": 31}, {"n": "⑧⑨", "t": "Granuloma", "s": "macrófagos que<br>encierran al microbio", "c": "d", "x": 69, "y": 6, "ax": 75.5, "ay": 40}, {"n": "⑪", "t": "Meningococos", "s": "Neisseria<br>que sobrevive", "c": "d", "x": 99.5, "y": 6, "ax": 94, "ay": 32, "al": "r"}, {"n": "②", "t": "Bloqueo BTK", "s": "Bruton: el pre-B<br>no recibe señal", "c": "i", "x": 0.5, "y": 91, "ax": 19, "ay": 48, "d": "A", "al": "l"}, {"n": "①③④", "t": "B maduro ausente", "s": "sin anticuerpos:<br>encapsuladas", "c": "d", "x": 28, "y": 91, "ax": 24, "ay": 52, "d": "D"}, {"n": "⑧", "t": "Vacuola sin estallido", "s": "sin NADPH-oxidasa:<br>catalasa + vivos", "c": "i", "x": 58, "y": 91, "ax": 64, "ay": 52, "d": "B"}, {"n": "⑪", "t": "Complemento sin poro", "s": "sin C5–C8 no se<br>arma el ataque", "c": "i", "x": 99.5, "y": 91, "ax": 90.5, "ay": 55.5, "d": "C", "al": "r"}]}, {"img": "img/23_2.webp", "ratio": 1.5, "titulo": "Desregulación y autoinflamación", "texto": "Sin <mark>FOXP3</mark> no hay Treg (IPEX) ⑤; sin <mark>FAS</mark> los linfocitos no mueren (ALPS) ⑥; la fiebre mediterránea deja <b>amiloidosis renal</b> ⑩.", "etiquetas": [{"n": "⑤", "t": "Islote atacado", "s": "diabetes: sin<br>Treg (FOXP3)", "c": "d", "x": 0.5, "y": 6, "ax": 11.0, "ay": 32.0, "al": "l"}, {"n": "⑤", "t": "LT efectores", "s": "nadie los<br>frena", "c": "d", "x": 26, "y": 6, "ax": 24.7, "ay": 23.4}, {"n": "⑥", "t": "FAS roto", "s": "receptor de<br>muerte (CD95)", "c": "d", "x": 45, "y": 6, "ax": 47.2, "ay": 29.0}, {"n": "⑥", "t": "FasL suelto", "s": "no puede<br>unirse", "c": "g", "x": 64, "y": 6, "ax": 64.1, "ay": 28.0}, {"n": "⑩", "t": "Amiloide", "s": "en el glomérulo:<br>amiloidosis renal", "c": "d", "x": 86, "y": 6, "ax": 84.6, "ay": 32.0}, {"n": "⑤", "t": "Intestino", "s": "enteropatía<br>autoinmune", "c": "d", "x": 0.5, "y": 92, "ax": 6.5, "ay": 68.0, "al": "l"}, {"n": "⑥", "t": "Ganglio grande", "s": "linfocitos<br>que no mueren", "c": "d", "x": 24, "y": 92, "ax": 35.2, "ay": 54.7}, {"n": "⑥", "t": "Doble negativos", "s": "TCRαβ CD4− CD8−:<br>ALPS", "c": "d", "x": 46, "y": 92, "ax": 57.0, "ay": 69.3}, {"n": "⑩", "t": "Inflamasoma", "s": "pirina (MEFV)<br>sin freno", "c": "d", "x": 72, "y": 92, "ax": 84.0, "ay": 64.5}, {"n": "⑩", "t": "Citocinas", "s": "fiebre y serositis<br>de 24-48 h", "c": "d", "x": 99.5, "y": 92, "ax": 93.8, "ay": 67.4, "al": "r"}]}, {"img": "img/23_3.webp", "ratio": 1.5, "titulo": "C1INH, poro del complemento e IgA", "texto": "Sin <mark>C1INH</mark> el edema cierra la laringe ⑫; sin C5-C8 no hay poro ⑪; sin <b>IgA secretora</b> la mucosa queda desnuda <span class=\"lt2\">D</span> ④.", "etiquetas": [{"n": "⑫", "t": "Laringe normal", "s": "vía aérea<br>abierta", "c": "g", "x": 8, "y": 6, "ax": 9.8, "ay": 39.0}, {"n": "⑫", "t": "Edema laríngeo", "s": "sin C1INH:<br>se cierra", "c": "d", "x": 27, "y": 6, "ax": 24.7, "ay": 42.0}, {"n": "⑪", "t": "Poro completo", "s": "C5 a C9: la<br>bacteria estalla", "c": "i", "x": 46, "y": 6, "ax": 48.2, "ay": 39.0}, {"n": "④", "t": "IgA secretora", "s": "cubre<br>la mucosa", "c": "i", "x": 68, "y": 6, "ax": 71.6, "ay": 32.0}, {"n": "④", "t": "Mucosa desnuda", "s": "las bacterias<br>se pegan", "c": "d", "x": 90, "y": 6, "ax": 89.8, "ay": 30.0, "d": "D"}, {"n": "⑫", "t": "Fuga del vaso", "s": "sistema de<br>contacto sin freno", "c": "d", "x": 20, "y": 92, "ax": 30.6, "ay": 60.5}, {"n": "⑪", "t": "Neisseria intacta", "s": "sobrevive", "c": "d", "x": 39, "y": 92, "ax": 48.8, "ay": 67.4}, {"n": "⑪", "t": "Sin C5-C8", "s": "no se arma<br>el poro", "c": "d", "x": 56, "y": 92, "ax": 55.3, "ay": 55.7}, {"n": "④", "t": "Plasmocito", "s": "fabrica IgA", "c": "i", "x": 72, "y": 92, "ax": 71.6, "ay": 62.5}, {"n": "④", "t": "Plasmocito sin IgA", "s": "IgA < 5 mg/dL", "c": "d", "x": 99.5, "y": 92, "ax": 87.2, "ay": 61.5, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = lo que falla</b> (la célula, el gen o la molécula), <b class=\"d\">rojo = lo que produce</b> (la infección, el síntoma o el dato de laboratorio), gris = estructuras de referencia.", "<b>Izquierda:</b> en la <mark>agamaglobulinemia de Bruton</mark> el pre-B no recibe la señal de BTK y no llega a B maduro <span class=\"lt2\">A</span>: no hay anticuerpos de ninguna clase.", "<b>Centro:</b> en la <mark>LAD</mark> el neutrófilo no tiene integrina CD18 y no sale del vaso, <span class=\"cx\">así que</span> hay leucocitosis en sangre y heridas sin pus. En la <mark>EGC</mark> sí come, pero sin NADPH-oxidasa no mata <span class=\"lt2\">B</span>: el microbio queda vivo y se forma un granuloma.", "<b>Derecha:</b> sin C5-C8 no se arma el poro y la <mark>Neisseria</mark> sobrevive; sin C1, C2 o C4 aparece el lupus <span class=\"lt2\">C</span>."], "recordar": "<b>Anticuerpo</b> → encapsuladas (pulmón y tripa). <b>Neutrófilo que no sale</b> → LAD. <b>Neutrófilo que no mata</b> → EGC (catalasa +). <b>Eje IL-12/IFN-γ</b> → micobacterias. <b>C5-C8</b> → Neisseria; <b>C1-C4</b> → lupus; <b>C1INH</b> → angioedema."}, "numeros": [{"l": "A", "html": "<b>Bruton</b>: linfocitos B <b class=\"b\">menos del 2 %</b>; debuta a los <b class=\"n\">4–6 meses</b>. Las agamaglobulinemias AR son el <b class=\"n\">15 %</b>.", "rango": {"min": 0, "max": 20, "unidad": "% de LB en sangre", "zonas": [[0, 2, "b"]], "marcas": [2]}}, {"l": "B", "html": "<b>EGC</b>: CYBB (gp91phox) ligada al X en el <b class=\"a\">80 %</b>. Los defectos de fagocitos son el <b class=\"n\">11 %</b> de las IDP; neutropenia congénita severa con <b class=\"b\">menos de 500/μL</b>.", "rango": {"min": 0, "max": 2000, "unidad": "neutrófilos/µL", "zonas": [[0, 500, "b"]], "marcas": [500]}}, {"l": "C", "html": "<b>Complemento</b>: <b class=\"n\">2,5 %</b> de las IDP; déficit de C1q + C4 lleva el lupus al <b class=\"a\">80–90 %</b>; déficit de C3 da autoinmunidad tipo LES en <b class=\"a\">15–20 %</b>.", "rango": null}, {"l": "D", "html": "<b>Anticuerpos</b>: <b class=\"a\">más del 50 %</b> de las IDP. Déficit selectivo de IgA: IgA <b class=\"b\">menor de 5 mg/dL</b>, <b class=\"a\">1 en 700</b>. IDCV: <b class=\"n\">1 en 10.000</b>, neoplasias <b class=\"a\">×25</b>.", "rango": {"min": 0, "max": 50, "unidad": "mg/dL de IgA", "zonas": [[0, 5, "b"]], "marcas": [5]}}], "escalas": [], "cadena": {"titulo": "Del brazo que falla al germen que entra", "subtitulo": "germen → brazo inmune que debería frenarlo → defecto → infección típica → qué pasa si falla la regulación", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Anticuerpos", "m": "<b>Qué pasa:</b> el B no madura (<mark>BTK</mark>), no cambia de isotipo o no responde (IDCV); la IgA aislada es la más común.", "pr": "neumonías, sinusitis y diarreas por <b>encapsuladas</b>: bronquiectasias y malabsorción.", "pr_tit": "Produce:", "rf": "Preguntas ①②③④ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">D</span>", "color": "p1"}, {"t": "2. Fagocito que no sale", "m": "<b>Por qué:</b> sin integrina <mark>CD18</mark> (LAD-1) el neutrófilo no se pega al endotelio; en la neutropenia congénita (ELANE) ni siquiera se forma.", "pr": "leucocitosis sin pus, cordón que cae tarde.", "pr_tit": "Produce:", "rf": "Pregunta ⑦", "color": "p2"}, {"t": "3. Fagocito que no mata", "m": "<b>Qué produce:</b> sin <mark>NADPH-oxidasa</mark> no hay explosión respiratoria; sin el eje IL-12/IFN-γ el macrófago no se activa.", "pr": "EGC: abscesos por catalasa +, hongos, BCG; MSMD: micobacterias y Salmonella.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Complemento", "m": "<b>Qué pasa:</b> sin C1, C2, C4 no se limpian inmunocomplejos; sin <mark>C5-C8</mark> no hay poro; sin C1INH se libera bradiquinina.", "pr": "lupus temprano, Neisseria recurrente o angioedema sin prurito.", "pr_tit": "Produce:", "rf": "Preguntas ⑪⑫ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Si falla el freno", "m": "<b>Disregulación:</b> sin Treg (<mark>FOXP3</mark>, IPEX), sin apoptosis (FAS, ALPS) o sin perforina (FHL) el sistema se vuelve contra sí; en los autoinflamatorios la fiebre llega sola.", "pr": "autoinmunidad neonatal, ganglios gigantes, linfohistiocitosis o fiebre periódica.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥⑩", "color": "p4"}, {"t": "6. Fenocopias", "m": "<b>Por qué importan:</b> el mismo cuadro sin herencia: <mark>mutación somática</mark> (HPN, ALPS-SFAS) o autoanticuerpos anti-IFN-γ o anti-GM-CSF en un adulto.", "pr": "un adulto sano puede «debutar» con una IDP.", "pr_tit": "Produce:", "rf": "Pregunta ⑬", "color": "p1"}], "extra": [{"html": "💉 <b>Tratamiento según el brazo:</b> anticuerpos → <mark>gammaglobulina intravenosa</mark>; fagocitos y complemento → profilaxis y vacunas; formas graves (EGC, LAD, IPEX) → trasplante de células madre.", "k": ""}, {"html": "🔥 <b>Autoinflamatorios:</b> FMF (MEFV) 24–48 h con amiloidosis; hiper-IgD (MVK) 4–5 días; criopirinopatías (CIAS1/NLRP3) de menor a mayor: FCAS &lt; Muckle-Wells (sordera) &lt; NOMID (meningitis aséptica, artropatía).", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Del germen al brazo que falla", "pasos": ["neumococo y Haemophilus en pulmón y tripa → <b>anticuerpos</b>", "infección sin pus y leucocitosis → <b>LAD</b>", "abscesos por catalasa + y granulomas → <b>EGC</b>", "BCG o Salmonella diseminadas → <b>eje IL-12/IFN-γ</b>", "meningococo una y otra vez → <b>C5–C8</b>"]}], "html": "", "fuente": "Fuente: tu teoría — clase 30b (deficiencias de anticuerpos, disregulación inmune, fagocitos, inmunidad innata, autoinflamatorios, complemento y fenocopias)."}, "preguntas": [{"n": 1, "id": "IN13-014", "c": "i", "tema": "Deficiencias de anticuerpos", "pregunta": "Las deficiencias predominantemente de anticuerpos se caracterizan por:", "opciones": ["a. Ser menos del 10 % de las IDP", "b. Infecciones por virus y hongos oportunistas desde el nacimiento", "c. Abscesos por bacterias catalasa positivas", "d. Infecciones respiratorias y digestivas recurrentes por bacterias extracelulares encapsuladas", "e. Encefalitis herpética aislada"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Son más del 50 % de las IDP; dan infecciones por S. pneumoniae, H. influenzae y S. aureus, con bronquiectasias y malabsorción.", "sin_banco": true, "ok": "", "x": "El anticuerpo <mark>opsoniza</mark> a las bacterias con cápsula para que el fagocito las coma. Sin él, el neumococo y el Haemophilus causan otitis, sinusitis y neumonías que terminan en bronquiectasias. <span class=\"cx\">En cambio</span>, los virus y oportunistas son de la falla T, <span class=\"cx\">así que</span> <span class=\"res\">anticuerpo = bacteria encapsulada</span>.", "truco": "Sin anticuerpos: «pulmón y tripa» con encapsuladas.", "veces": 0}, {"n": 2, "id": "IN13-015", "c": "i", "tema": "Agamaglobulinemia ligada al X", "pregunta": "En la agamaglobulinemia ligada al X (de Bruton), es correcto:", "opciones": ["a. El gen mutado es BTK y los linfocitos B en sangre son menos del 2 %", "b. Hay IgM normal o alta", "c. Debuta en el periodo neonatal inmediato", "d. Los linfocitos T están ausentes", "e. Solo falta la IgA"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La quinasa de Bruton (BTK) falta en la señal del pre-BCR; los linfocitos B no maduran (&lt;2 %) y faltan todas las inmunoglobulinas.", "sin_banco": true, "ok": "", "x": "Mira la izquierda de la imagen (punto Ⓐ): el camino se corta antes del B maduro. Eso es la <mark>BTK</mark> que falta: <span class=\"res\">la a</span>, con B menores del 2 %.", "truco": "", "veces": 0}, {"n": 3, "id": "IN13-016", "c": "i", "tema": "IDCV", "pregunta": "¿Cuáles son los criterios mínimos para diagnosticar inmunodeficiencia común variable (IDCV)?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Concentraciones bajas de al menos 2 de 3 inmunoglobulinas (IgG e IgA, y/o IgM) más producción deficiente de anticuerpos específicos a antígenos T-dependientes y/o T-independientes.", "sin_banco": true, "ok": "", "x": "La IDCV es <mark>heterogénea</mark>, <span class=\"cx\">así que</span> se define por el resultado: pocas Ig y mala respuesta a vacunas. Tiene prevalencia de 1 en 10.000 y presentación bimodal. <span class=\"cx\">Además</span>, en el 10 % hay granulomas no caseificantes y <span class=\"res\">las neoplasias se multiplican por 25</span>.", "truco": "IDCV: «2 de 3 bajas y la vacuna no prende».", "veces": 0}, {"n": 4, "id": "IN13-017", "c": "i", "tema": "Deficiencia selectiva de IgA", "pregunta": "La inmunodeficiencia primaria humoral más común (1 en 700) se define por:", "opciones": ["a. IgG transitoriamente baja que se recupera a los 4 años", "b. Ausencia de linfocitos B", "c. IgM elevada con el resto bajo", "d. IgE mayor de 2.000 UI/mL", "e. IgA sérica menor de 5 mg/dL con las demás inmunoglobulinas normales"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es la deficiencia selectiva de IgA: IgA menor de 5 mg/dL, las otras Ig normales.", "sin_banco": true, "ok": "", "x": "La <mark>IgA</mark> protege las mucosas, pero las otras Ig compensan, <span class=\"cx\">así que</span> muchos pacientes tienen pocos síntomas. <span class=\"cx\">Por eso</span> es la más común (1 en 700) pero se diagnostica por casualidad. <span class=\"cx\">En cambio</span>, la IgG baja que se recupera sola es <span class=\"res\">la hipogammaglobulinemia transitoria de la infancia</span>.", "truco": "IgA &lt; 5: «A de Abundante»: la más común.", "veces": 0}, {"n": 5, "id": "IN13-018", "c": "i", "tema": "Disregulación inmune", "pregunta": "¿Qué gen está mutado en el síndrome IPEX y cuál es su consecuencia?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "FOXP3: no hay linfocitos T reguladores; se pierde la autotolerancia con endocrinopatía autoinmune (diabetes tipo 1), enteropatía grave y dermatitis desde el periodo neonatal.", "sin_banco": true, "ok": "", "x": "El <mark>FOXP3</mark> es el factor de transcripción que define al linfocito T regulador. Sin Treg nadie frena a los linfocitos autorreactivos, <span class=\"cx\">así que</span> atacan el páncreas, el intestino y la piel del recién nacido. <span class=\"cx\">En cambio</span>, en el APECED falla el <span class=\"res\">AIRE</span> y hay candidiasis con endocrinopatías.", "truco": "IPEX = «Inmune Policía EXtraviada» (sin Treg).", "veces": 0}, {"n": 6, "id": "IN13-019", "c": "i", "tema": "Disregulación inmune", "pregunta": "Los linfocitos T TCRαβ+ CD4−CD8− (doble negativos) en sangre periférica son característicos de:", "opciones": ["a. Síndrome IPEX", "b. Síndrome linfoproliferativo autoinmune (ALPS) por defecto de FAS", "c. Síndrome de Chediak-Higashi", "d. XLP1 por SH2D1A", "e. Síndrome de DiGeorge"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. El ALPS: la mutación de FAS (CD95, TNFRSF6) impide la apoptosis de los linfocitos efectores y da linfadenopatía crónica con doble negativos.", "sin_banco": true, "ok": "", "x": "Al terminar una respuesta, los linfocitos sobrantes se eliminan por <mark>apoptosis vía FAS</mark>. Si FAS falla, se acumulan y crecen ganglios y bazo, con autoinmunidad. <span class=\"cx\">Por eso</span> aparecen los <span class=\"res\">linfocitos T doble negativos</span>, su marca de laboratorio.", "truco": "ALPS: «FAS no apaga» → ganglios gigantes.", "veces": 0}, {"n": 7, "id": "IN13-020", "c": "d", "tema": "Deficiencias de fagocitos", "pregunta": "Lactante con caída del cordón umbilical a las 5 semanas, onfalitis sin pus y leucocitosis neutrofílica persistente aun sin infección. ¿Diagnóstico y gen más probable?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Deficiencia de adhesión leucocitaria tipo 1 (LAD-1) por mutación en ITGB2 (CD18): los neutrófilos no salen del vaso.", "sin_banco": true, "ok": "", "x": "Es el vaso del centro: los neutrófilos ruedan pero <mark>no cruzan la pared</mark>, <span class=\"cx\">así que</span> afuera hay bacterias sin pus. <span class=\"cx\">Por eso</span> sobra neutrófilo en sangre: <span class=\"res\">LAD-1 por CD18</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN13-021", "c": "d", "tema": "Deficiencias de fagocitos", "pregunta": "La enfermedad granulomatosa crónica (EGC) se debe con más frecuencia (80 %) a mutación en:", "opciones": ["a. ELANE", "b. LYST", "c. ITGB2", "d. CYBB (gp91phox) de la NADPH-oxidasa", "e. IL12RB1"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. CYBB, ligada al X: sin gp91phox no hay explosión respiratoria; abscesos por bacterias catalasa positivas, hongos y micobacterias, con granulomas.", "sin_banco": true, "ok": "", "x": "El neutrófilo de la imagen tiene microbios vivos en su vacuola oscura: comió pero <mark>no hizo el estallido</mark> (punto Ⓑ). <span class=\"cx\">Por eso</span> se arma el granuloma al lado: <span class=\"res\">la d, CYBB</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN13-022", "c": "d", "tema": "Deficiencias de fagocitos", "pregunta": "¿Qué eje de señalización falla en la susceptibilidad mendeliana a micobacterias (MSMD) y qué infecciones produce?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El eje IL-12/IL-23/IFN-γ (IL12B, IL12RB1, IFNGR1, IFNGR2, STAT1, IRF8): infecciones diseminadas por micobacterias atípicas, BCG y Salmonella, con granulomas ausentes o mal formados.", "sin_banco": true, "ok": "", "x": "El macrófago infectado manda <mark>IL-12</mark> al linfocito, y este le devuelve IFN-γ para que active su capacidad de matar. Si se corta ese circuito, el macrófago no elimina a las micobacterias intracelulares. <span class=\"cx\">Por eso</span> una simple <span class=\"res\">vacuna BCG puede diseminarse</span>.", "truco": "MSMD: «12 pide, gamma responde»; si se corta, gana la micobacteria.", "veces": 0}, {"n": 10, "id": "IN13-023", "c": "d", "tema": "Síndromes autoinflamatorios", "pregunta": "Síndrome autoinflamatorio con fiebre y serositis de 24 a 48 horas, mutación en MEFV y riesgo de amiloidosis renal:", "opciones": ["a. Fiebre mediterránea familiar", "b. Síndrome de hiper-IgD", "c. Síndrome de urticaria por frío (FCAS)", "d. Muckle-Wells", "e. NOMID/CINCA"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La fiebre mediterránea familiar (gen MEFV): episodios de 24-48 h con riesgo de amiloidosis renal.", "sin_banco": true, "ok": "", "x": "Los autoinflamatorios dan <mark>fiebre periódica y serositis</mark> sin infección ni autoanticuerpos. La FMF tiene crisis cortas, de 1 a 2 días, y la inflamación repetida deposita amiloide en el riñón. <span class=\"cx\">En cambio</span>, las criopirinopatías (CIAS1) van de la urticaria por frío al NOMID, <span class=\"res\">con gravedad creciente</span>.", "truco": "FMF: «Fiebre Mediterránea Fina»: corta, 1-2 días, riñón amiloide.", "veces": 0}, {"n": 11, "id": "IN13-024", "c": "d", "tema": "Deficiencias del complemento", "pregunta": "Paciente con meningococcemias recurrentes. La deficiencia del complemento más probable es de:", "opciones": ["a. C1q", "b. C2", "c. C4", "d. Inhibidor de C1", "e. C5 a C8 (complejo de ataque a la membrana)"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Las deficiencias de C5 a C8 impiden formar el poro y predisponen a Neisseria recurrente; las de C1, C2 y C4 se asocian a LES.", "sin_banco": true, "ok": "", "x": "A la derecha, los meningococos siguen enteros: hay complemento suelto pero <mark>no se forma el poro</mark> (punto Ⓒ). <span class=\"cx\">Por eso</span> <span class=\"res\">la e: C5 a C8</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN13-025", "c": "d", "tema": "Deficiencias del complemento", "pregunta": "¿Qué causa el angioedema hereditario y cuál es su manifestación más grave?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La deficiencia del inhibidor de C1 (C1INH): el sistema de contacto se activa sin freno y produce bradiquinina, con angioedema no pruriginoso; lo más grave es la obstrucción laríngea, que puede ser fatal.", "sin_banco": true, "ok": "", "x": "El C1INH frena al complemento y también al <mark>sistema de contacto</mark> (kininas). Sin él se libera bradiquinina, que abre los vasos y hincha la piel y las mucosas. Como no hay histamina, el edema no pica y no responde a antihistamínicos (literatura), <span class=\"cx\">así que</span> <span class=\"res\">la laringe puede cerrarse</span>.", "truco": "Bradiquinina: hincha sin picar.", "veces": 0}, {"n": 13, "id": "IN13-026", "c": "g", "tema": "Fenocopias de IDP", "pregunta": "¿Qué es una fenocopia de IDP y cuáles son sus dos mecanismos?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Una inmunodeficiencia que imita a una IDP sin mutación de línea germinal: por mutaciones somáticas (HPN en CD55/CD59, ALPS-SFAS, RALD) o por autoanticuerpos neutralizantes (anti-IFN-γ, anti-GM-CSF, anti-IL-6).", "sin_banco": true, "ok": "", "x": "La clínica es la de una IDP, pero el defecto <mark>no se hereda</mark>: aparece en una célula del adulto o lo crea un autoanticuerpo. <span class=\"cx\">Por ejemplo</span>, un adulto sano con micobacterias diseminadas puede tener anti-IFN-γ. <span class=\"cx\">Así que</span> <span class=\"res\">un adulto sin antecedentes también puede tener una «IDP»</span>.", "truco": "Fenocopia = «copia del fenotipo» sin el gen heredado.", "veces": 0}], "tabla": {"cab": ["", "Qué falla", "Germen típico", "Pista"], "filas": [["Bruton", "BTK: B no madura", "Encapsuladas", "B &lt; 2 %, 4-6 meses"], ["IDCV", "B no responde", "Encapsuladas", "2 de 3 Ig bajas"], ["LAD-1", "CD18: no sale", "Bacterias, sin pus", "Leucocitosis, cordón tardío"], ["EGC", "NADPH-oxidasa", "Catalasa +, hongos", "Granulomas, 80 % XL"], ["MSMD", "IL-12/IFN-γ", "Micobacterias, BCG", "Granuloma mal formado"], ["C5–C8", "Sin poro", "Neisseria", "Meningococcemia recurrente"], ["🔑 Para diferenciar", "El brazo que falla", "decide el germen", "y el dato que lo delata"]]}, "fuente": "Fuente: tu teoría — clase 30b (Inmunodeficiencias primarias: anticuerpos, disregulación, fagocitos, innata, autoinflamatorios, complemento y fenocopias), Rojas 17.ª ed., cap. 30."}, {"n": 24, "slug": "VIH_ciclo_e_inmunopatogenesis", "titulo": "VIH: ciclo, inmunopatogénesis y clínica", "subtitulo": "del virión al CD4, del GALT a la translocación microbiana y del recuento CD4 al SIDA", "grupo": "g14", "lema": "La idea: el <mark>HIV</mark> es un <b>retrovirus</b> que entra al linfocito T CD4+ con la gp120, copia su ARN a ADN con la <b>transcriptasa inversa</b> y se esconde en el genoma como <mark>provirus</mark>. Su golpe más precoz es en el <b>intestino</b>: el GALT concentra la mayoría de los CD4 y, al morir sus Th17, las bacterias atraviesan la pared y encienden una <u>hiperactivación inmune crónica</u>. Esa hiperactivación y la pérdida de unos 50 CD4 por año llevan al <mark>SIDA</mark> en 8-10 años; cada paso del ciclo es blanco de un fármaco. En la imagen: el virión en corte, el linfocito CD4 con el ciclo del virus y la mucosa intestinal con bacterias que la cruzan.", "img": "img/24.webp", "mini": "img/mini/24.webp", "ratio": 1.5, "etiquetas": [{"n": "②", "t": "gp120", "s": "espiga que se une<br>a CD4 y correceptor", "c": "i", "x": 0.5, "y": 6, "ax": 15, "ay": 27, "al": "l"}, {"n": "④", "t": "CD4 + CCR5", "s": "cepas R5 al inicio;<br>X4 (CXCR4) al final", "c": "i", "x": 30, "y": 6, "ax": 38, "ay": 30}, {"n": "②", "t": "Fusión (gp41)", "s": "la envoltura se funde<br>y entra la cápside", "c": "i", "x": 47, "y": 6, "ax": 45.5, "ay": 31}, {"n": "⑯", "t": "Gemación", "s": "la proteasa madura<br>el virión: blanco de PI", "c": "d", "x": 66, "y": 6, "ax": 66.5, "ay": 22}, {"n": "⑤", "t": "Epitelio con huecos", "s": "GALT sin Th17:<br>barrera rota", "c": "d", "x": 99.5, "y": 6, "ax": 91, "ay": 40, "d": "B", "al": "r"}, {"n": "⑮", "t": "Cápside p24", "s": "dos copias<br>de ARN", "c": "g", "x": 0.5, "y": 91, "ax": 19.5, "ay": 45, "d": "A", "al": "l"}, {"n": "⑩⑪⑫", "t": "Linfocito CD4", "s": "−50 por año;<br>< 200 = SIDA", "c": "d", "x": 24, "y": 91, "ax": 36, "ay": 70, "d": "C"}, {"n": "⑦", "t": "ARN → ADN", "s": "transcriptasa inversa<br>sin corrector: muta", "c": "i", "x": 41.5, "y": 91, "ax": 40.5, "ay": 49, "d": "D"}, {"n": "③⑰", "t": "Provirus latente", "s": "reservorio; Nef esconde<br>el CMH-I al CD8", "c": "i", "x": 60, "y": 91, "ax": 53, "ay": 61.5}, {"n": "⑤⑥", "t": "Bacterias que cruzan", "s": "translocación:<br>hiperactivación", "c": "d", "x": 99.5, "y": 91, "ax": 90, "ay": 62, "al": "r"}], "diapos": [{"img": "img/24.webp", "ratio": 1.5, "titulo": "Virión, ciclo y GALT", "texto": "La <mark>gp120</mark> se une a CD4 y al correceptor ②④; la transcriptasa inversa copia el ARN y el provirus se integra; en el <mark>GALT</mark> caen los Th17 ⑤.", "etiquetas": [{"n": "②", "t": "gp120", "s": "espiga que se une<br>a CD4 y correceptor", "c": "i", "x": 0.5, "y": 6, "ax": 15, "ay": 27, "al": "l"}, {"n": "④", "t": "CD4 + CCR5", "s": "cepas R5 al inicio;<br>X4 (CXCR4) al final", "c": "i", "x": 30, "y": 6, "ax": 38, "ay": 30}, {"n": "②", "t": "Fusión (gp41)", "s": "la envoltura se funde<br>y entra la cápside", "c": "i", "x": 47, "y": 6, "ax": 45.5, "ay": 31}, {"n": "⑯", "t": "Gemación", "s": "la proteasa madura<br>el virión: blanco de PI", "c": "d", "x": 66, "y": 6, "ax": 66.5, "ay": 22}, {"n": "⑤", "t": "Epitelio con huecos", "s": "GALT sin Th17:<br>barrera rota", "c": "d", "x": 99.5, "y": 6, "ax": 91, "ay": 40, "d": "B", "al": "r"}, {"n": "⑮", "t": "Cápside p24", "s": "dos copias<br>de ARN", "c": "g", "x": 0.5, "y": 91, "ax": 19.5, "ay": 45, "d": "A", "al": "l"}, {"n": "⑩⑪⑫", "t": "Linfocito CD4", "s": "−50 por año;<br>< 200 = SIDA", "c": "d", "x": 24, "y": 91, "ax": 36, "ay": 70, "d": "C"}, {"n": "⑦", "t": "ARN → ADN", "s": "transcriptasa inversa<br>sin corrector: muta", "c": "i", "x": 41.5, "y": 91, "ax": 40.5, "ay": 49, "d": "D"}, {"n": "③⑰", "t": "Provirus latente", "s": "reservorio; Nef esconde<br>el CMH-I al CD8", "c": "i", "x": 60, "y": 91, "ax": 53, "ay": 61.5}, {"n": "⑤⑥", "t": "Bacterias que cruzan", "s": "translocación:<br>hiperactivación", "c": "d", "x": 99.5, "y": 91, "ax": 90, "ay": 62, "al": "r"}]}, {"img": "img/24_2.webp", "ratio": 1.5, "titulo": "Escape y reservorio", "texto": "La transcriptasa <mark>no corrige errores</mark> <span class=\"lt2\">D</span> ⑦; <b>Nef</b> baja el CMH-I y el CD8 no ve la célula ③; el <mark>reservorio</mark> latente impide curar ⑰.", "etiquetas": [{"n": "⑦", "t": "Transcriptasa inversa", "s": "copia el ARN a ADN<br>sin corregir errores", "c": "i", "x": 0.5, "y": 6, "ax": 10, "ay": 45, "al": "l"}, {"n": "⑦", "t": "Variantes nuevas", "s": "cada virión trae<br>espigas distintas", "c": "d", "x": 31, "y": 6, "ax": 28, "ay": 28}, {"n": "③", "t": "CMH-I hacia adentro", "s": "Nef lo retira<br>de la superficie", "c": "i", "x": 49, "y": 6, "ax": 46, "ay": 36}, {"n": "③", "t": "CD8 que no ataca", "s": "no ve el péptido viral:<br>célula invisible", "c": "d", "x": 68, "y": 6, "ax": 64, "ay": 38}, {"n": "⑰", "t": "Fármacos alrededor", "s": "el HAART no toca<br>al virus dormido", "c": "g", "x": 99.5, "y": 6, "ax": 81.5, "ay": 28, "al": "r"}, {"n": "⑦", "t": "Errores en el ADN", "s": "una mutación<br>o más por copia", "c": "d", "x": 0.5, "y": 91, "ax": 27, "ay": 61, "d": "D", "al": "l"}, {"n": "⑦", "t": "Anticuerpo que no agarra", "s": "el virus ya cambió<br>su envoltura", "c": "g", "x": 30, "y": 91, "ax": 33, "ay": 44}, {"n": "③", "t": "CD4 infectado", "s": "casi sin moléculas<br>presentadoras", "c": "i", "x": 52, "y": 91, "ax": 50, "ay": 62}, {"n": "⑰", "t": "Provirus latente", "s": "ADN viral en el cromosoma<br>del T de memoria: reservorio", "c": "d", "x": 99.5, "y": 91, "ax": 85, "ay": 50, "al": "r"}]}, {"img": "img/24_3.webp", "ratio": 1.5, "titulo": "Madre-hijo y sida avanzado", "texto": "La IgG materna cruza la placenta, <span class=\"cx\">por eso</span> el ELISA del lactante no sirve ⑭; con CD4 <span class=\"lt2\">C</span> bajo 200 aparece <b>P. jirovecii</b> ⑫ y bajo 50 el <mark>CMV</mark> ⑬.", "etiquetas": [{"n": "⑭", "t": "Sangre materna", "s": "virus e IgG<br>de la madre", "c": "g", "x": 0.5, "y": 6, "ax": 5, "ay": 32, "al": "l"}, {"n": "⑭", "t": "IgG cruza la placenta", "s": "el anticuerpo materno<br>llega al bebé", "c": "i", "x": 27, "y": 6, "ax": 19, "ay": 46}, {"n": "⑫", "t": "Vidrio esmerilado", "s": "bilateral: tos seca,<br>disnea, hipoxemia", "c": "d", "x": 46, "y": 6, "ax": 37, "ay": 50}, {"n": "⑫", "t": "Quistes de P. jirovecii", "s": "exudado espumoso<br>en el alvéolo", "c": "d", "x": 65, "y": 6, "ax": 62, "ay": 37, "d": "C"}, {"n": "⑬", "t": "Retinitis por CMV", "s": "necrosis blanca<br>junto a los vasos", "c": "d", "x": 99.5, "y": 6, "ax": 88, "ay": 33, "al": "r"}, {"n": "⑭", "t": "Capilar fetal", "s": "ELISA + por la IgG materna:<br>en menores de 18 meses, PCR", "c": "i", "x": 16, "y": 91, "ax": 26, "ay": 40}, {"n": "⑫", "t": "Neumocistosis", "s": "CD4 < 200: la definitoria<br>más frecuente (38 %)", "c": "d", "x": 41, "y": 91, "ax": 55, "ay": 62}, {"n": "⑬", "t": "Papila óptica", "s": "fondo de ojo:<br>visión borrosa", "c": "g", "x": 64, "y": 91, "ax": 77.5, "ay": 45}, {"n": "⑬", "t": "Hemorragias retinianas", "s": "el CMV aparece<br>con CD4 < 50", "c": "d", "x": 99.5, "y": 91, "ax": 89, "ay": 57, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = lo que falla</b> (la célula, el gen o la molécula), <b class=\"d\">rojo = lo que produce</b> (la infección, el síntoma o el dato de laboratorio), gris = estructuras de referencia.", "<b>Izquierda:</b> el virión mide <span class=\"lt2\">A</span> y tiene envoltura con espigas (<mark>gp120</mark> se une, gp41 se funde), cápside cónica (p24) y dos copias de ARN.", "<b>Centro:</b> el ciclo va en sentido horario: unión a CD4 + correceptor (CCR5 o CXCR4), fusión, <mark>transcripción inversa</mark> (sin corrector: muta en cada ciclo) <span class=\"lt2\">D</span>, integración y gemación. Cada etapa es blanco de un grupo de antirretrovirales.", "<b>Derecha:</b> el <mark>GALT</mark> pierde sus Th17 <span class=\"lt2\">B</span>; la barrera se abre y entran bacterias: translocación microbiana."], "recordar": "gp120 <b>se une</b>, gp41 <b>se funde</b>, Nef <b>esconde</b> el CMH-I. R5 al inicio, X4 al final. CD4 &lt; 200 = SIDA y <b>P. jirovecii</b>. Bebé &lt; 18 meses: busca el virus, no el anticuerpo. HAART = <b>tres fármacos de dos grupos</b>."}, "numeros": [{"l": "A", "html": "<b>Virión</b>: <b class=\"n\">100–150 nm</b>; <b class=\"n\">9 genes</b> → <b class=\"n\">15 proteínas</b>; ARN de unos <b class=\"n\">10 kb</b>, dos copias.", "rango": null}, {"l": "B", "html": "<b>GALT</b>: <b class=\"a\">más del 60 %</b> de los linfocitos del cuerpo; viremia primaria a los <b class=\"n\">7–10 días</b>; anticuerpos y CD8 a las <b class=\"n\">1–2 semanas</b>.", "rango": null}, {"l": "C", "html": "<b>Linfocito CD4</b>: pérdida de <b class=\"b\">≈50 por año</b>; SIDA con <b class=\"b\">&lt; 200/μL</b>; P. jirovecii en el <b class=\"a\">38 %</b> de los casos de SIDA; progresión típica en <b class=\"n\">8–10 años</b>.", "rango": {"min": 0, "max": 1000, "unidad": "LT CD4+/µL", "zonas": [[0, 200, "a"], [200, 500, "m"], [500, 1000, "n"]], "marcas": [50, 100, 200, 500], "valor": 120}}, {"l": "D", "html": "<b>Transcriptasa inversa</b>: <b class=\"a\">≥ 1 mutación</b> por cada molécula de ADN; con HAART, carga viral indetectable a las <b class=\"n\">12–24 semanas</b> (límite <b class=\"n\">40 copias/mL</b>).", "rango": {"min": 0, "max": 400, "unidad": "copias/mL (carga viral)", "zonas": [[0, 40, "n"], [40, 200, "m"], [200, 400, "a"]], "marcas": [40, 200]}}], "escalas": [], "cadena": {"titulo": "De la mucosa al SIDA", "subtitulo": "exposición → entrada al CD4 → GALT y set point → escape crónico → SIDA → HAART", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Exposición", "m": "<b>Qué pasa:</b> el virus entra por mucosa genital (más del 85 % de los casos nuevos), sangre o vía materna; la <mark>transfusión</mark> contaminada infecta en el 90 %.", "pr": "macrófagos, dendríticas (DC-SIGN, «caballos de Troya») y CD4 de la mucosa se infectan.", "pr_tit": "Produce:", "rf": "Preguntas ①⑧", "color": "p1"}, {"t": "2. Entrada y provirus", "m": "<b>Por qué:</b> la <mark>gp120</mark> se une a CD4 y a CCR5 (cepas R5); la gp41 funde; la transcriptasa inversa copia el ARN y la integrasa lo inserta como provirus.", "pr": "célula infectada para siempre; cada copia trae mutaciones.", "pr_tit": "Produce:", "rf": "Preguntas ②④⑦ · punto <span class=\"lt2\">D</span>", "color": "p2"}, {"t": "3. GALT y set point", "m": "<b>Qué produce:</b> la mayor replicación ocurre en el <mark>GALT</mark>; mueren los Th17 y las bacterias cruzan la pared. A las 1–2 semanas llegan CD8 y anticuerpos.", "pr": "síndrome retroviral agudo (fiebre 96 %) y una carga viral basal: el set point.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥⑨ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Escape crónico", "m": "<b>Por qué no se cura:</b> el virus muta sin corrector, <mark>Nef</mark> esconde el CMH-I, la hiperactivación agota a los linfocitos y aparecen cepas X4 con sincitios.", "pr": "pérdida de unos 50 CD4 por año durante una latencia clínica, no asintomática.", "pr_tit": "Produce:", "rf": "Preguntas ③⑦⑩ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. SIDA", "m": "<b>Desenlace:</b> con <mark>CD4 &lt; 200</mark> o enfermedad definitoria: P. jirovecii (38 %), <span class=\"cx\">luego</span> toxoplasma y criptococo (&lt;100), CMV, MAC y linfoma del SNC (&lt;50).", "pr": "infecciones oportunistas, tumores y desgaste.", "pr_tit": "Produce:", "rf": "Preguntas ⑪⑫⑬ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "6. Diagnóstico y HAART", "m": "<b>Qué hacer:</b> ELISA de 4.ª generación + Western blot; en menores de 18 meses, <mark>PCR</mark>. HAART con tres fármacos de dos grupos suprime el virus pero no borra el reservorio.", "pr": "enfermedad crónica controlable; transmisión cerca de cero.", "pr_tit": "Produce:", "rf": "Preguntas ⑭⑮⑯⑰", "color": "p1"}], "extra": [{"html": "💊 <b>Un fármaco por etapa del ciclo:</b> entrada (<mark>maraviroc</mark>, anti-CCR5) · fusión (enfuvirtida) · transcripción inversa (NRTI: AZT, TDF, FTC; NNRTI: EFV) · integración (raltegravir, dolutegravir) · maduración (inhibidores de proteasa: lopinavir, darunavir).", "k": ""}, {"html": "🧪 <b>Pruebas:</b> p24 por ELISA = detección precoz; ADN proviral por PCR = niños menores de 18 meses; carga viral (ARN) = seguimiento, no diagnóstico de rutina en adultos.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Escalera de CD4 y sus infecciones", "pasos": ["> 500: síndrome agudo, vaginitis candidiásica, adenopatías", "200–499: neumococo, tuberculosis pulmonar, zóster, Kaposi", "&lt; 200: <b>P. jirovecii</b>, histoplasmosis, TB miliar, desgaste", "&lt; 100: toxoplasmosis, criptococosis, herpes diseminado", "&lt; 50: <b>CMV</b> diseminado, <b>MAC</b>, linfoma primario del SNC"]}], "html": "", "fuente": "Fuente: tu teoría — clase 31a (origen, estructura, ciclo, tropismo, transmisión, infección aguda y crónica) y clase 31b (evolución clínica, clasificación CDC, diagnóstico, HAART y perspectivas de cura)."}, "preguntas": [{"n": 1, "id": "IN14-001", "c": "i", "tema": "Origen del HIV", "pregunta": "El HIV-1, responsable de la pandemia mundial, se originó por zoonosis a partir de:", "opciones": ["a. SIVsm del sooty mangabey", "b. HTLV-1 humano", "c. SIVcpz del chimpancé Pan troglodytes troglodytes", "d. Un lentivirus felino", "e. SIV del macaco rhesus"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Del SIVcpz del chimpancé; el HIV-2 viene del SIVsm del sooty mangabey y se concentra en el oeste de África.", "sin_banco": true, "ok": "", "x": "Ambos HIV son lentivirus de la familia retroviridae que saltaron de primates al humano por <mark>zoonosis</mark>. El HIV-1 viene del chimpancé y domina el mundo (grupo M, subtipo C el más prevalente). <span class=\"cx\">En cambio</span>, el HIV-2 viene del mangabey y es <span class=\"res\">casi exclusivo del oeste de África</span>.", "truco": "HIV-1 = «1 chimpancé»; HIV-2 = «2.º mono, mangabey».", "veces": 0}, {"n": 2, "id": "IN14-002", "c": "i", "tema": "Estructura y genoma", "pregunta": "La glicoproteína del HIV que se une a la molécula CD4 de la célula blanco es:", "opciones": ["a. gp41", "b. p24", "c. p17", "d. gp120", "e. Nef"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La gp120, producto del gen env junto con la gp41; la gp120 se une a CD4 y al correceptor, y la gp41 media la fusión.", "sin_banco": true, "ok": "", "x": "Son las espigas de la envoltura del virión (izquierda). La <mark>gp120</mark> es la que se une a CD4 y al correceptor; la gp41 hace la fusión. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN14-003", "c": "i", "tema": "Estructura y genoma", "pregunta": "La proteína Nef del HIV favorece la evasión inmune porque:", "opciones": ["a. Regula negativamente CD4, CD25 y las moléculas del CMH clase I de la célula infectada", "b. Degrada APOBEC3G", "c. Transporta los ARNm virales fuera del núcleo", "d. Inserta el provirus en el genoma", "e. Corta las poliproteínas Gag y Gag-Pol"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Nef baja el CMH-I (y CD4, CD25), así que el linfocito T CD8+ citotóxico no reconoce a la célula infectada.", "sin_banco": true, "ok": "", "x": "El CD8 solo mata a la célula que le muestra péptidos virales en el <mark>CMH clase I</mark>. Nef retira esas moléculas de la superficie, <span class=\"cx\">así que</span> la célula infectada se vuelve «invisible». <span class=\"cx\">En cambio</span>, Vif degrada APOBEC3G, Rev saca ARNm del núcleo y <span class=\"res\">la integrasa inserta el provirus</span>.", "truco": "Nef = «Ne-gativo»: esconde el CMH-I.", "veces": 0}, {"n": 4, "id": "IN14-004", "c": "i", "tema": "Tropismo", "pregunta": "¿En qué se diferencian las cepas R5 y X4 del HIV?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Las R5 usan CD4 + CCR5, predominan en la transmisión y la mayor parte de la infección; las X4 usan CD4 + CXCR4, aparecen en fases avanzadas y se asocian a caída marcada de CD4+ y progresión a SIDA (forman sincitios).", "sin_banco": true, "ok": "", "x": "Tras unirse a CD4, la gp120 necesita un <mark>correceptor</mark> para fusionarse. Las cepas R5 entran a los CD4 de memoria efectora CCR5+ del GALT, <span class=\"cx\">por eso</span> dominan al inicio. <span class=\"cx\">En cambio</span>, las X4 aparecen tarde, forman sincitios que atrapan CD4 sanos y <span class=\"res\">aceleran el deterioro</span>.", "truco": "R5 = «Recién» infectado; X4 = «eXtremo», final.", "veces": 0}, {"n": 5, "id": "IN14-005", "c": "i", "tema": "Infección aguda", "pregunta": "El sitio de mayor replicación del HIV durante toda la infección, cuya destrucción de células Th17 causa translocación microbiana, es:", "opciones": ["a. El timo", "b. La médula ósea", "c. El bazo", "d. El sistema nervioso central", "e. El tejido linfoide asociado al intestino (GALT)"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. El GALT, que concentra más del 60 % de los linfocitos, en su mayoría CD4+ de memoria efectora CCR5+.", "sin_banco": true, "ok": "", "x": "A la derecha de la imagen el epitelio intestinal tiene huecos y las bacterias pasan al tejido (punto Ⓑ): es el <mark>GALT</mark> sin Th17. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN14-006", "c": "i", "tema": "Infección aguda", "pregunta": "¿Qué es el «set point» de la carga viral y por qué importa?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es el nivel basal en que se estabiliza la carga viral tras el control parcial por anticuerpos y linfocitos CD8+; es factor pronóstico: cuanto más bajo, más lenta la progresión al SIDA.", "sin_banco": true, "ok": "", "x": "La viremia primaria aparece a los <mark>7-10 días</mark>; <span class=\"cx\">luego</span>, a las 1-2 semanas, llegan los CD8+ y los anticuerpos, y la carga viral baja hasta un piso. Ese piso refleja qué tan bien controla el hospedero al virus. <span class=\"cx\">Por eso</span> <span class=\"res\">un set point bajo predice progresión lenta</span> (el típico tarda 8-10 años).", "truco": "Set point = «termostato»: más bajo, más tiempo sano.", "veces": 0}, {"n": 7, "id": "IN14-007", "c": "i", "tema": "Mecanismos de escape", "pregunta": "El HIV escapa rápidamente de la respuesta inmune por mutaciones porque su transcriptasa inversa:", "opciones": ["a. Tiene doble actividad de integrasa", "b. Carece de actividad exonucleasa correctora y genera al menos una mutación por molécula de ADN", "c. Solo copia el gen env", "d. Es inhibida por APOBEC3G", "e. Funciona dentro del núcleo"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. No corrige errores (sin exonucleasa): hay al menos una mutación por ciclo, y las variantes que evaden la inmunidad se seleccionan en pocas semanas.", "sin_banco": true, "ok": "", "x": "Es el paso del centro donde el ARN se copia a ADN (punto Ⓓ). La transcriptasa inversa <mark>no tiene corrector</mark>, <span class=\"cx\">así que</span> <span class=\"res\">la b</span>: una mutación por copia.", "truco": "", "veces": 0}, {"n": 8, "id": "IN14-008", "c": "d", "tema": "Mecanismos de transmisión", "pregunta": "¿Cuál de estas exposiciones tiene el mayor riesgo de transmisión del HIV?", "opciones": ["a. Accidente laboral percutáneo", "b. Uso de agujas compartidas", "c. Exposición de mucosa intacta", "d. Transfusión de sangre contaminada", "e. Relación sexual receptiva única sin protección"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La transfusión de sangre contaminada: 90 % (9.000 por 10.000 exposiciones); el accidente percutáneo es 0,3 %.", "sin_banco": true, "ok": "", "x": "La transfusión mete un <mark>gran inóculo</mark> directo en la sangre, <span class=\"cx\">por eso</span> el riesgo es casi seguro (90 %). Le siguen la transmisión madre-hijo (10-35 %) y, mucho más abajo, las agujas (0,67 %) y el pinchazo laboral (0,3 %). Aun así, <span class=\"res\">las relaciones sexuales causan más del 85 % de las infecciones nuevas</span> <span class=\"cx\">porque</span> son la exposición más frecuente.", "truco": "Sangre 90, pinchazo 0,3: «nueve-cero vs cero-tres».", "veces": 0}, {"n": 9, "id": "IN14-009", "c": "d", "tema": "Síndrome retroviral agudo", "pregunta": "El signo más frecuente del síndrome retroviral agudo, que aparece 1 a 4 semanas tras la infección, es:", "opciones": ["a. Fiebre persistente (96 %)", "b. Candidosis orofaríngea", "c. Hepatoesplenomegalia", "d. Diarrea", "e. Meningitis aséptica"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La fiebre (96 %), seguida de adenopatías (74 %), faringitis y brote cutáneo (70 % cada uno).", "sin_banco": true, "ok": "", "x": "El síndrome retroviral agudo parece una <mark>mononucleosis o gripe severa</mark> y dura 1-3 semanas. La fiebre es casi constante, <span class=\"cx\">en cambio</span> la candidosis y los síntomas neurológicos solo llegan al 12 %. <span class=\"cx\">Además</span>, hasta <span class=\"res\">el 50 % de los infectados no presenta síntomas</span> en esta etapa.", "truco": "Agudo VIH = «mono-gripe»: Fiebre, Ganglios, Garganta, Granitos.", "veces": 0}, {"n": 10, "id": "IN14-010", "c": "d", "tema": "Latencia clínica", "pregunta": "¿Cuántos linfocitos T CD4+ por año se pierden en la fase crónica y por qué no se la llama «asintomática»?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Unos 50 CD4+ por año tras el set point; no es asintomática porque son frecuentes la linfadenopatía generalizada persistente, candidosis oral, herpes zóster, trombocitopenia y anemias hemolíticas.", "sin_banco": true, "ok": "", "x": "Tras el set point, el recuento CD4 cae <mark>unos 50 por año</mark>, <span class=\"cx\">así que</span> alguien con 1.000 tardaría años en llegar a 200. Durante ese tiempo no hay enfermedades definitorias de SIDA, pero sí manifestaciones menores. <span class=\"cx\">Por eso</span> se habla de <span class=\"res\">latencia clínica</span>, no de fase asintomática.", "truco": "Latencia: «50 por año, en silencio pero no mudo».", "veces": 0}, {"n": 11, "id": "IN14-011", "c": "d", "tema": "Clasificación CDC", "pregunta": "Según los CDC, un paciente infectado por HIV se considera en fase de SIDA cuando:", "opciones": ["a. Tiene carga viral mayor de 100.000 copias/mL", "b. Presenta síndrome retroviral agudo", "c. Tiene CD4+ menor de 500/μL", "d. Tiene ELISA de cuarta generación positivo", "e. Tiene CD4+ menor de 200/μL o una enfermedad definitoria (categorías A3, B3, C1, C2, C3)"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Categorías A3, B3, C1, C2 y C3: CD4+ menor de 200/μL o enfermedad definitoria; siempre se clasifica en el peor estadio alcanzado.", "sin_banco": true, "ok": "", "x": "La clasificación cruza la <mark>categoría clínica</mark> (A, B, C) con el recuento CD4 (1, 2, 3). Todo «3» (&lt;200) y toda «C» (enfermedad definitoria) es SIDA. <span class=\"cx\">Además</span> el paciente <span class=\"res\">nunca baja de categoría</span>, aunque mejore con tratamiento.", "truco": "Todo 3 y toda C = SIDA.", "veces": 0}, {"n": 12, "id": "IN14-012", "c": "d", "tema": "Clasificación CDC", "pregunta": "Paciente con HIV sin tratamiento, CD4+ de 120/μL, con tos seca, disnea progresiva e hipoxemia. ¿Cuál es la infección definitoria de SIDA más probable (y la más frecuente)?", "opciones": ["a. Neumonía neumocócica", "b. Tuberculosis miliar", "c. Neumonía por Pneumocystis jirovecii", "d. Criptococosis", "e. Citomegalovirus diseminado"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Neumonía por P. jirovecii: aparece con CD4+ menor de 200/μL y es la definitoria más frecuente (38 % de los casos de SIDA).", "sin_banco": true, "ok": "", "x": "Con <mark>CD4 menor de 200</mark> se abre la puerta a P. jirovecii, que da neumonía intersticial con hipoxemia. Es la enfermedad definitoria más frecuente (38 %). <span class=\"cx\">En cambio</span>, la criptococosis espera a menos de 100 y el CMV diseminado a <span class=\"res\">menos de 50</span>.", "truco": "200 = «Pneumo-dos-cientos».", "veces": 0}, {"n": 13, "id": "IN14-013", "c": "d", "tema": "Clasificación CDC", "pregunta": "¿Cuál de estas complicaciones del HIV aparece típicamente con un recuento de CD4+ menor de 50/μL?", "opciones": ["a. Vaginitis candidiásica", "b. Neumonía neumocócica", "c. Neumonía por P. jirovecii", "d. Toxoplasmosis", "e. Enfermedad diseminada por citomegalovirus"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. CMV diseminado (junto con M. avium complex diseminado y linfoma primario del SNC) es de menos de 50; la toxoplasmosis es de menos de 100.", "sin_banco": true, "ok": "", "x": "Es la escalera de CD4 de la página 2: con menos de 50 aparecen el <mark>CMV diseminado</mark>, el MAC y el linfoma del SNC. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 14, "id": "IN14-014", "c": "g", "tema": "Diagnóstico", "pregunta": "Lactante de 3 meses, hijo de madre con HIV, tiene ELISA anti-HIV positivo. ¿Confirma la infección? ¿Qué prueba corresponde?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "No: en menores de 18 meses las pruebas serológicas están contraindicadas porque la IgG materna anti-HIV atraviesa la placenta y persiste hasta los 18 meses; se usan pruebas virológicas (ARN viral o ADN proviral por PCR), confirmadas con una segunda determinación.", "sin_banco": true, "ok": "", "x": "La <mark>IgG materna</mark> cruza la placenta, <span class=\"cx\">así que</span> el ELISA del bebé puede detectar los anticuerpos de la madre y no los propios. <span class=\"cx\">Por eso</span> se buscan el virus o su ADN integrado, a las 48 horas, a 1-2 meses y a 3 y 6 meses. <span class=\"res\">Una prueba positiva se confirma con una segunda</span>.", "truco": "Bebé &lt; 18 meses: «busca al virus, no al anticuerpo».", "veces": 0}, {"n": 15, "id": "IN14-015", "c": "g", "tema": "Diagnóstico", "pregunta": "Para considerar positivo un Western blot para HIV, los CDC exigen anticuerpos contra:", "opciones": ["a. p24 y al menos una proteína de envoltura (gp41, gp120 o gp160)", "b. Solo p17", "c. Solo la transcriptasa inversa", "d. Nef y Tat", "e. Cualquier banda aislada"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Contra p24 y al menos una proteína de envoltura (gp41, gp120 o gp160); ELISA positivo con Western blot negativo es falso positivo.", "sin_banco": true, "ok": "", "x": "El ELISA es el <mark>tamizaje</mark> (sensible, de cuarta generación detecta p24 y anticuerpos con más del 99 %); el Western blot confirma. Exige una banda de la cápside y otra de la envoltura para no confundir reacciones cruzadas. Si sale indeterminado con sospecha clínica, <span class=\"res\">se repite en 6-12 semanas</span>.", "truco": "Western: «cápside + envoltura» = 24 + gp.", "veces": 0}, {"n": 16, "id": "IN14-016", "c": "g", "tema": "HAART", "pregunta": "Sobre el tratamiento antirretroviral de alta actividad (HAART), es correcto:", "opciones": ["a. La monoterapia con AZT es suficiente si la carga viral es baja", "b. Se combinan tres fármacos del mismo grupo", "c. Combina al menos tres antirretrovirales de dos o tres grupos distintos; un esquema de primera línea es EFV + TDF + FTC", "d. Su objetivo es erradicar el reservorio en 12 semanas", "e. Solo se indica con CD4+ menor de 50/μL"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Al menos tres fármacos de dos o tres grupos (p. ej., EFV + TDF + FTC); monoterapia y biterapia generan resistencia rápida.", "sin_banco": true, "ok": "", "x": "Como el virus muta en cada ciclo, un solo fármaco selecciona mutantes resistentes enseguida. Con <mark>tres fármacos de grupos distintos</mark> el virus tendría que mutar en varios blancos a la vez. Así la carga viral se hace indetectable en 12-24 semanas y <span class=\"res\">la transmisión baja casi al 100 %</span>, aunque no se erradica el reservorio.", "truco": "HAART = «3 de 2»: tres fármacos, dos grupos o más.", "veces": 0}, {"n": 17, "id": "IN14-017", "c": "g", "tema": "Perspectivas de cura", "pregunta": "¿Cuál es el principal obstáculo para curar el HIV y por qué es relevante el «paciente de Berlín»?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El reservorio: linfocitos T CD4+ de memoria central con el virus latente, fuera del alcance de fármacos y defensas. El paciente de Berlín recibió células madre de un donante homocigoto delta32 en CCR5 y mantuvo supresión viral años sin HAART (cura funcional).", "sin_banco": true, "ok": "", "x": "El provirus <mark>latente</mark> no replica, <span class=\"cx\">así que</span> ni el fármaco ni el CD8 lo ven; al suspender el HAART, el virus vuelve. En Berlín, las células nuevas no tenían CCR5 y las cepas R5 no pudieron entrar. <span class=\"cx\">Por eso</span> se ensaya el <span class=\"res\">«shock and kill»</span>: despertar el reservorio y destruirlo.", "truco": "Berlín: «sin puerta CCR5, no entra».", "veces": 0}], "tabla": {"cab": ["", "Qué detecta", "Cuándo se usa", "Ojo"], "filas": [["ELISA 4.ª gen.", "Anticuerpos + p24", "Tamizaje", "S y E > 99 %"], ["Western blot", "p24 + una de envoltura", "Confirmación", "Indeterminado: repetir"], ["Antígeno p24", "Proteína de cápside", "Antes de la seroconversión", "S ≈ 89 %"], ["PCR ADN proviral", "Virus integrado", "Menores de 18 meses", "IgG materna confunde"], ["Carga viral", "ARN en plasma", "Seguimiento", "Límite 40 copias/mL"], ["🔑 Para diferenciar", "Anticuerpo = adulto", "Virus = bebé", "ARN = control del HAART"]]}, "fuente": "Fuente: tu teoría — clases 31a (virología e inmunopatogénesis del HIV) y 31b (curso clínico, diagnóstico y tratamiento), Rojas 17.ª ed., cap. 31."}, {"n": 25, "slug": "Inmunodeficiencias_secundarias", "titulo": "Inmunodeficiencias secundarias", "subtitulo": "un sistema sano que se debilita por hambre, órganos enfermos, edad, fármacos, infecciones o trauma", "grupo": "g14", "lema": "La idea: en las <mark>inmunodeficiencias secundarias</mark> el sistema nació sano y <b>algo de afuera</b> lo debilita. Son las más frecuentes y la causa número uno en el mundo es la <mark>malnutrición</mark>; en los países industrializados pesan más tumores y fármacos. Cada causa golpea un brazo: el hambre encoge el <b>timo</b>, el riñón nefrótico <b>pierde anticuerpos</b>, sin bazo entran las <b>bacterias con cápsula</b> y el tumor <b>mata</b> linfocitos. Importa porque <u>muchas revierten al corregir la causa</u>. En la imagen: timo normal y atrófico, glomérulo que pierde anticuerpos, bazo ausente con encapsulados y un tumor que mata a un linfocito T junto a inmunosupresores.", "img": "img/25.webp", "mini": "img/mini/25.webp", "ratio": 1.5, "etiquetas": [{"n": "", "t": "Timo normal", "s": "referencia", "c": "g", "x": 0.5, "y": 6, "ax": 7, "ay": 30, "al": "l"}, {"n": "②③", "t": "Timo atrófico", "s": "hambre y zinc:<br>se van los T", "c": "i", "x": 21, "y": 6, "ax": 18, "ay": 34, "d": "A"}, {"n": "⑤", "t": "Glomérulo", "s": "síndrome nefrótico:<br>filtro abierto", "c": "i", "x": 39, "y": 6, "ax": 35, "ay": 33}, {"n": "⑦", "t": "Bazo ausente", "s": "sin anticuerpos<br>antipolisacárido", "c": "i", "x": 58, "y": 6, "ax": 68, "ay": 31}, {"n": "", "t": "Célula tumoral", "s": "TGF-β y Fas-L<br>apagan la defensa", "c": "i", "x": 77, "y": 6, "ax": 79.5, "ay": 30}, {"n": "⑨", "t": "Linfocito T", "s": "apoptosis y<br>anergia", "c": "d", "x": 99.5, "y": 6, "ax": 91.5, "ay": 44, "al": "r"}, {"n": "①②", "t": "Comida escasa", "s": "causa n.º 1<br>en el mundo", "c": "g", "x": 0.5, "y": 91, "ax": 15.5, "ay": 66, "al": "l"}, {"n": "⑤", "t": "IgG en la orina", "s": "pasa primero la IgG,<br>luego la IgM", "c": "d", "x": 27, "y": 91, "ax": 37.5, "ay": 66}, {"n": "⑦", "t": "Encapsulados", "s": "cápsula: sepsis<br>fulminante sin bazo", "c": "d", "x": 50, "y": 91, "ax": 56, "ay": 70}, {"n": "⑧", "t": "Inmunosupresores", "s": "corticoides, ciclosporina,<br>rituximab (anti-CD20)", "c": "i", "x": 99.5, "y": 91, "ax": 84, "ay": 68, "al": "r"}], "diapos": [{"img": "img/25.webp", "ratio": 1.5, "titulo": "Cinco golpes al sistema sano", "texto": "Hambre, riñón, bazo ausente, tumor y fármacos: cada causa golpea un brazo distinto, <span class=\"cx\">por eso</span> <mark>la malnutrición</mark> es la n.º 1 ①.", "etiquetas": [{"n": "", "t": "Timo normal", "s": "referencia", "c": "g", "x": 0.5, "y": 6, "ax": 7, "ay": 30, "al": "l"}, {"n": "②③", "t": "Timo atrófico", "s": "hambre y zinc:<br>se van los T", "c": "i", "x": 21, "y": 6, "ax": 18, "ay": 34, "d": "A"}, {"n": "⑤", "t": "Glomérulo", "s": "síndrome nefrótico:<br>filtro abierto", "c": "i", "x": 39, "y": 6, "ax": 35, "ay": 33}, {"n": "⑦", "t": "Bazo ausente", "s": "sin anticuerpos<br>antipolisacárido", "c": "i", "x": 58, "y": 6, "ax": 68, "ay": 31}, {"n": "", "t": "Célula tumoral", "s": "TGF-β y Fas-L<br>apagan la defensa", "c": "i", "x": 77, "y": 6, "ax": 79.5, "ay": 30}, {"n": "⑨", "t": "Linfocito T", "s": "apoptosis y<br>anergia", "c": "d", "x": 99.5, "y": 6, "ax": 91.5, "ay": 44, "al": "r"}, {"n": "①②", "t": "Comida escasa", "s": "causa n.º 1<br>en el mundo", "c": "g", "x": 0.5, "y": 91, "ax": 15.5, "ay": 66, "al": "l"}, {"n": "⑤", "t": "IgG en la orina", "s": "pasa primero la IgG,<br>luego la IgM", "c": "d", "x": 27, "y": 91, "ax": 37.5, "ay": 66}, {"n": "⑦", "t": "Encapsulados", "s": "cápsula: sepsis<br>fulminante sin bazo", "c": "d", "x": 50, "y": 91, "ax": 56, "ay": 70}, {"n": "⑧", "t": "Inmunosupresores", "s": "corticoides, ciclosporina,<br>rituximab (anti-CD20)", "c": "i", "x": 99.5, "y": 91, "ax": 84, "ay": 68, "al": "r"}]}, {"img": "img/25_2.webp", "ratio": 1.5, "titulo": "La IgG materna llega al final", "texto": "La IgG cruza la placenta <mark>en el último trimestre</mark>; <span class=\"cx\">por eso</span> el prematuro nace sin ella, <span class=\"cx\">en cambio</span> el de término tiene IgG pero NK y T al 50 % ⑥.", "etiquetas": [{"n": "⑥", "t": "Trofoblasto", "s": "vesículas llevan<br>la IgG al feto", "c": "i", "x": 13, "y": 6, "ax": 18, "ay": 50}, {"n": "⑥", "t": "Capilar fetal", "s": "la IgG materna<br>llega al bebé", "c": "i", "x": 33, "y": 6, "ax": 28.5, "ay": 50}, {"n": "⑥", "t": "Último trimestre", "s": "aquí cruza<br>casi toda la IgG", "c": "i", "x": 55, "y": 6, "ax": 59, "ay": 32}, {"n": "⑥", "t": "A término", "s": "IgG<br>adecuada", "c": "i", "x": 75, "y": 6, "ax": 76, "ay": 39}, {"n": "⑥", "t": "Prematuro", "s": "casi<br>sin IgG", "c": "d", "x": 99.5, "y": 6, "ax": 88, "ay": 41, "al": "r"}, {"n": "⑥", "t": "Sangre materna", "s": "llena de IgG<br>de la madre", "c": "g", "x": 0.5, "y": 91, "ax": 5, "ay": 64, "al": "l"}, {"n": "⑥", "t": "1.er y 2.º trimestre", "s": "pasa muy poca IgG", "c": "g", "x": 36, "y": 91, "ax": 42, "ay": 61}, {"n": "⑥", "t": "Célula NK", "s": "en el neonato:<br>al 50 % del adulto", "c": "i", "x": 64, "y": 91, "ax": 71.5, "ay": 46, "d": "A"}, {"n": "⑥", "t": "Innata más débil", "s": "TNF-α del prematuro<br>75 % menor", "c": "d", "x": 99.5, "y": 91, "ax": 87, "ay": 56, "al": "r"}]}, {"img": "img/25_3.webp", "ratio": 1.5, "titulo": "Vitamina D: catelicidina y Treg", "texto": "La vitamina D enciende la <mark>catelicidina</mark> del macrófago <span class=\"lt2\">A</span> y modula dendríticas y Treg; <span class=\"cx\">por eso</span> su déficit deja pasar a las <b>micobacterias</b> ④.", "etiquetas": [{"n": "④", "t": "Sol en la piel", "s": "la luz UVB forma<br>la vitamina D", "c": "g", "x": 15, "y": 6, "ax": 13, "ay": 27}, {"n": "④", "t": "Receptor de vitamina D", "s": "en el núcleo<br>enciende genes", "c": "i", "x": 38, "y": 6, "ax": 42.3, "ay": 40, "d": "A"}, {"n": "④", "t": "Dendrítica tolerante", "s": "la vitamina D<br>la modula", "c": "i", "x": 64, "y": 6, "ax": 75, "ay": 30}, {"n": "④", "t": "Linfocito Treg", "s": "frena la<br>inflamación", "c": "g", "x": 99.5, "y": 6, "ax": 93.7, "ay": 33, "al": "r"}, {"n": "④", "t": "Vitamina D a la sangre", "s": "viaja hasta<br>el macrófago", "c": "g", "x": 10, "y": 91, "ax": 11.7, "ay": 67}, {"n": "④", "t": "Catelicidina", "s": "péptido que perfora<br>a la micobacteria", "c": "i", "x": 56, "y": 91, "ax": 53, "ay": 54}, {"n": "④", "t": "Micobacteria destruida", "s": "dentro del<br>fagosoma", "c": "i", "x": 34, "y": 91, "ax": 49.5, "ay": 62}, {"n": "④", "t": "Sin vitamina D", "s": "las micobacterias<br>se multiplican", "c": "d", "x": 99.5, "y": 91, "ax": 84.6, "ay": 68, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = lo que falla</b> (la célula, el gen o la molécula), <b class=\"d\">rojo = lo que produce</b> (la infección, el síntoma o el dato de laboratorio), gris = estructuras de referencia.", "<b>Izquierda:</b> la desnutrición y la falta de zinc <span class=\"lt2\">A</span> encogen el <mark>timo</mark> (también por glucocorticoides endógenos): cae la inmunidad celular, pero todo revierte al nutrir.", "<b>Centro izquierda:</b> en el <mark>síndrome nefrótico</mark> el glomérulo deja pasar <span class=\"cx\">primero</span> la IgG y <span class=\"cx\">luego</span> la IgM. <b>Centro derecha:</b> sin bazo faltan los anticuerpos contra polisacáridos, <span class=\"cx\">así que</span> ganan los <mark>encapsulados</mark>.", "<b>Derecha:</b> el tumor fabrica TGF-β y expresa Fas-L, que induce apoptosis del linfocito; los inmunosupresores frenan al T a propósito."], "recordar": "Hambre = <b>timo chico</b> (celular). Riñón = <b>pierde IgG</b>. Sin bazo = <b>encapsulados</b> → vacunar antes. Prematuro = sin IgG materna. Rituximab = <b>sin B</b>. Trauma = cortisol + catecolaminas → <b>parálisis inmune</b>."}, "numeros": [{"l": "A", "html": "<b>Zinc</b>: cofactor de <b class=\"a\">más de 1.300 enzimas</b>. Vitamina D: regula <b class=\"n\">más de 200 genes</b>. <b>Neonato</b>: NK al <b class=\"b\">50 %</b> del adulto; TNF-α del prematuro <b class=\"b\">75 % menor</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la causa externa a la infección", "subtitulo": "causa → brazo inmune golpeado → mecanismo → infección típica → corregir la causa", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Malnutrición", "m": "<b>Qué pasa:</b> sin proteínas ni <mark>zinc</mark> el timo involuciona; el eje hipotálamo-hipófisis-adrenal sube los glucocorticoides; baja la IgA secretora.", "pr": "anergia, linfopenia T, diarreas e infecciones respiratorias; revierte al nutrir.", "pr_tit": "Produce:", "rf": "Preguntas ①②③④ · punto <span class=\"lt2\">A</span>", "color": "p1"}, {"t": "2. Órganos enfermos", "m": "<b>Por qué:</b> el <mark>síndrome nefrótico</mark> pierde IgG por la orina; la uremia daña T y neutrófilos y la hemodiálisis activa el complemento; la enteropatía pierde Ig por el intestino.", "pr": "hipogammaglobulinemia e infecciones pulmonares, cutáneas y urinarias.", "pr_tit": "Produce:", "rf": "Pregunta ⑤", "color": "p2"}, {"t": "3. Edad", "m": "<b>Qué produce:</b> el <mark>prematuro</mark> no recibe la IgG del último trimestre; el neonato tiene NK al 50 %; el anciano pierde T vírgenes y responde mal a vacunas.", "pr": "sepsis neonatal, herpes, infecciones y tumores en el anciano.", "pr_tit": "Produce:", "rf": "Pregunta ⑥", "color": "p3"}, {"t": "4. Fármacos y tumores", "m": "<b>Qué pasa:</b> glucocorticoides, ciclosporina y tacrolimus frenan al T; <mark>rituximab</mark> elimina al B; el tumor usa TGF-β y Fas-L.", "pr": "CMV e intracelulares; hipogammaglobulinemia prolongada.", "pr_tit": "Produce:", "rf": "Pregunta ⑧", "color": "p4"}, {"t": "5. Bazo, trauma e infecciones", "m": "<b>Por qué:</b> sin <mark>bazo</mark> no hay anticuerpos antipolisacárido; el trauma libera cortisol y catecolaminas; el HIV destruye CD4 y los superantígenos agotan a los T.", "pr": "sepsis por encapsulados, parálisis inmunológica, SIDA.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑨", "color": "p4"}, {"t": "6. Qué hacer", "m": "<b>Tratamiento:</b> corregir la <mark>causa original</mark>; si no se puede (asplenia, síndromes), vacunas, citocinas recombinantes y profilaxis antibiótica.", "pr": "muchas IDS se revierten por completo.", "pr_tit": "Produce:", "rf": "Preguntas ①⑦", "color": "p1"}], "extra": [{"html": "🥕 <b>Vitaminas:</b> A = mucosas y sarampión grave · C = explosión respiratoria y óxido nítrico · <mark>D = catelicidina, Treg, micobacterias</mark> · E = antioxidante, baja la IgE en atópicos.", "k": ""}, {"html": "🧬 <b>Otras causas:</b> diabetes (quimiotaxis y fagocitosis lentas: TB, Candida, celulitis), síndrome de Down (inversión CD4:CD8, NK disfuncionales), Hodgkin (anergia cutánea).", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Del trauma a la parálisis inmune", "pasos": ["lesión y dolor: cortisol y catecolaminas", "barreras rotas: entran gérmenes", "tormenta de IL-6 y TNF-α", "distrés respiratorio y falla multiorgánica", "<b>parálisis inmunológica</b>: muerte por activación y anergia"]}], "html": "", "fuente": "Fuente: tu teoría — clase 32 (clasificación, malnutrición, vitaminas y oligoelementos, órganos, cáncer, edad, inmunosupresores, infecciones, trauma, diabetes, asplenia y síndrome de Down)."}, "preguntas": [{"n": 1, "id": "IN14-018", "c": "i", "tema": "Generalidades", "pregunta": "La causa más frecuente de inmunodeficiencia secundaria a nivel mundial es:", "opciones": ["a. La infección por HIV", "b. La malnutrición proteico-calórica", "c. Los glucocorticoides", "d. La diabetes mellitus", "e. El cáncer"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La malnutrición; en países industrializados predominan las metabólicas, los tumores y los fármacos inmunosupresores.", "sin_banco": true, "ok": "", "x": "Las IDS son las inmunodeficiencias <mark>más prevalentes</mark> y su causa depende del país. En los países en desarrollo domina la malnutrición con carencias de vitaminas y oligoelementos. <span class=\"cx\">En cambio</span>, en los industrializados pesan más <span class=\"res\">los tumores y los inmunosupresores</span>; el HIV es el caso mejor estudiado, no el más frecuente.", "truco": "Mundo: el hambre primero.", "veces": 0}, {"n": 2, "id": "IN14-019", "c": "i", "tema": "Malnutrición", "pregunta": "En la desnutrición grave, ¿qué compartimiento inmune se afecta más y es reversible?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La inmunidad celular: involución del timo, linfopenia T, anergia cutánea; los anticuerpos séricos se conservan relativamente, pero baja la IgA secretora. Todo revierte por completo al corregir la desnutrición.", "sin_banco": true, "ok": "", "x": "Compara los dos timos de la izquierda: el del desnutrido está <mark>encogido</mark> y pierde linfocitos. <span class=\"cx\">Por eso</span> falla sobre todo la <span class=\"res\">inmunidad celular</span>, y revierte al nutrir.", "truco": "", "veces": 0}, {"n": 3, "id": "IN14-020", "c": "i", "tema": "Oligoelementos", "pregunta": "La acrodermatitis enteropática, deficiencia exclusiva de zinc con atrofia tímica, linfopenia y pérdida de la actividad NK, se debe a mutación en:", "opciones": ["a. FOXP3", "b. ATM", "c. CYBB", "d. STAT3", "e. SLC39A4, transportador de zinc"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. SLC39A4 (autosómica recesiva): dermatitis, diarrea, alopecia e infecciones graves desde la infancia.", "sin_banco": true, "ok": "", "x": "El zinc es cofactor de más de <mark>1.300 enzimas</mark> y lo necesitan las células que proliferan rápido, como los linfocitos. Si falla su transportador intestinal, no entra zinc. <span class=\"cx\">Por eso</span> se combinan la tríada de <span class=\"res\">dermatitis, diarrea y alopecia</span> con una inmunodeficiencia celular profunda.", "truco": "Zinc: «Diarrea, Dermatitis, (sin) pelo».", "veces": 0}, {"n": 4, "id": "IN14-021", "c": "i", "tema": "Vitaminas", "pregunta": "¿Qué vitamina regula el péptido antimicrobiano catelicidina, modula las células dendríticas y los Treg, y cuya deficiencia predispone a micobacteriosis?", "opciones": ["a. Vitamina A", "b. Vitamina C", "c. Vitamina D", "d. Vitamina E", "e. Riboflavina"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. La vitamina D: afecta más de 200 genes; su deficiencia da susceptibilidad a micobacterias y autoinmunidad.", "sin_banco": true, "ok": "", "x": "La <mark>vitamina D</mark> actúa como una hormona inmunológica: induce catelicidina en el macrófago y modula los Treg y la IL-10. <span class=\"cx\">Por eso</span> su falta favorece la tuberculosis y la autoinmunidad. <span class=\"cx\">En cambio</span>, la vitamina A protege las mucosas y su falta <span class=\"res\">agrava el sarampión y el rotavirus</span>.", "truco": "D de «Defensa contra la TB».", "veces": 0}, {"n": 5, "id": "IN14-022", "c": "d", "tema": "Disfunción de órganos", "pregunta": "¿Por qué el síndrome nefrótico produce inmunodeficiencia humoral y qué inmunoglobulina se pierde primero?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Por el aumento de la permeabilidad glomerular se pierden proteínas en la orina: primero la IgG (más pequeña) y después la IgM; hay hipogammaglobulinemia con infecciones pulmonares, cutáneas, urinarias y septicemia.", "sin_banco": true, "ok": "", "x": "En el glomérulo de la imagen los anticuerpos en forma de Y cruzan hacia la orina: pasa <span class=\"cx\">primero</span> la <mark>IgG</mark> (pequeña) y después la IgM.", "truco": "", "veces": 0}, {"n": 6, "id": "IN14-023", "c": "i", "tema": "Edad", "pregunta": "Respecto a la inmunodeficiencia secundaria del prematuro frente al neonato a término, es correcto:", "opciones": ["a. El prematuro tiene IgG muy baja porque no recibió la IgG materna del último trimestre", "b. El neonato a término carece de IgG materna", "c. La actividad NK del neonato es el doble de la del adulto", "d. El prematuro produce más TNF-α que el adulto", "e. No hay diferencias humorales"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. El paso de IgG materna ocurre en el último trimestre; el prematuro no lo completa. El neonato a término tiene IgG adecuada pero NK y LT al 50 %.", "sin_banco": true, "ok": "", "x": "La <mark>IgG materna</mark> cruza la placenta sobre todo en el último trimestre, <span class=\"cx\">así que</span> el prematuro nace casi sin ella. <span class=\"cx\">Además</span> sus monocitos hacen un 75 % menos de TNF-α. <span class=\"cx\">En cambio</span>, el neonato a término tiene IgG suficiente y su falla es celular: <span class=\"res\">NK al 50 % del adulto</span>, con riesgo por herpes simplex.", "truco": "Prematuro = «se fue antes del regalo» de IgG.", "veces": 0}, {"n": 7, "id": "IN14-024", "c": "d", "tema": "Otras: asplenia", "pregunta": "Joven esplenectomizado tras un accidente consulta por fiebre alta y shock en pocas horas. ¿Qué gérmenes se sospechan y qué debió recibir antes de una esplenectomía electiva?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Gérmenes encapsulados (S. pneumoniae, H. influenzae tipo b, N. meningitidis); antes de una esplenectomía electiva se vacuna contra neumococo, Haemophilus influenzae tipo b y meningococo.", "sin_banco": true, "ok": "", "x": "La silueta vacía del bazo y las bacterias con halo brillante (cápsula) en la sangre: sin bazo ganan los <mark>encapsulados</mark>, <span class=\"cx\">por eso</span> se vacuna <span class=\"res\">antes de la esplenectomía</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN14-025", "c": "i", "tema": "Inmunosupresores", "pregunta": "El rituximab produce inmunodeficiencia secundaria porque:", "opciones": ["a. Inhibe la calcineurina", "b. Bloquea el TNF-α", "c. Es anti-CD20 y elimina los linfocitos B, con hipogammaglobulinemia que puede durar meses", "d. Bloquea la IL-6", "e. Inhibe la síntesis de purinas"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es un monoclonal anti-CD20: elimina linfocitos B y deja una hipogammaglobulinemia profunda que persiste meses.", "sin_banco": true, "ok": "", "x": "El <mark>CD20</mark> está en la superficie del linfocito B, <span class=\"cx\">así que</span> el rituximab lo marca para destruirlo. Se usa en linfomas B y artritis reumatoide. <span class=\"cx\">En cambio</span>, la ciclosporina y el tacrolimus inhiben la calcineurina del linfocito T y predisponen a <span class=\"res\">intracelulares como el citomegalovirus</span>.", "truco": "Ritu-«B»: borra los B.", "veces": 0}, {"n": 9, "id": "IN14-026", "c": "d", "tema": "Trauma y dolor", "pregunta": "¿Por qué el trauma severo puede llevar a una «parálisis inmunológica»?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El estrés agudo libera catecolaminas y cortisol (inmunosupresores), se rompen las barreras, y la activación innata masiva (IL-6, TNF-α) induce muerte celular por activación y anergia: la parálisis inmunológica.", "sin_banco": true, "ok": "", "x": "<span class=\"cx\">Primero</span> hay una tormenta: la lesión activa la inmunidad innata y libera <mark>IL-6 y TNF-α</mark>, que pueden causar distrés respiratorio y falla multiorgánica. <span class=\"cx\">Luego</span>, la activación sin control agota y mata a los linfocitos, sumada al cortisol. <span class=\"cx\">Así que</span> tras el exceso viene la anergia: <span class=\"res\">el paciente queda indefenso ante infecciones</span>.", "truco": "Trauma: «primero incendio, luego cenizas».", "veces": 0}], "tabla": {"cab": ["", "Brazo afectado", "Mecanismo", "Germen o riesgo"], "filas": [["Malnutrición", "Celular, IgA secretora", "Timo atrófico, cortisol", "Entéricas, respiratorias"], ["Nefrótico", "Humoral", "Pierde IgG y luego IgM", "Pulmón, piel, orina"], ["Prematuro", "Humoral", "Sin IgG del 3.er trimestre", "Sepsis neonatal"], ["Asplenia", "Humoral", "Sin anti-polisacárido", "Encapsulados"], ["Inmunosupresores", "Celular (o B)", "Calcineurina, anti-CD20", "CMV, intracelulares"], ["Trauma", "Global", "Cortisol, activación", "Parálisis inmune"], ["🔑 Para diferenciar", "Celular vs humoral", "La causa define el brazo", "y el brazo, el germen"]]}, "fuente": "Fuente: tu teoría — clase 32 (Inmunodeficiencias secundarias), Rojas 17.ª ed., cap. 32."}, {"n": 26, "slug": "Mecanismos_basicos_de_la_alergia", "titulo": "Mecanismos básicos de la alergia", "subtitulo": "del alérgeno inocuo a la IgE, el mastocito y el eosinófilo", "grupo": "g15", "lema": "La idea: la alergia es una respuesta inmune nociva <mark>mediada por IgE</mark> que solo aparece en quien trae la predisposición genética llamada <b>atopia</b>. Primero hay una <u>sensibilización silenciosa</u>: la célula dendrítica presenta el alérgeno a un Th2, este hace que el linfocito B fabrique IgE y la IgE se pega al FcεRI del mastocito. En la reexposición el alérgeno une dos IgE vecinas y el mastocito se vacía en segundos (<b>fase aguda</b>); horas después llegan eosinófilos y linfocitos (<b>fase tardía</b>) y, si la exposición sigue, queda <b>fibrosis</b>. En la imagen verás de izquierda a derecha las tres escenas: sensibilización, mastocito que se degranula y pared bronquial invadida por eosinófilos.", "img": "img/26.webp", "mini": "img/mini/26.webp", "ratio": 1.5, "etiquetas": [{"n": "③④", "t": "Ácaro y polen", "s": "proteínas inocuas:<br>ácaros 60-70 %", "c": "i", "x": 0.5, "y": 6, "ax": 20, "ay": 22, "d": "D", "al": "l"}, {"n": "⑥⑦", "t": "Mastocito con IgE", "s": "IgE sobre FcεRI:<br>célula «armada»", "c": "i", "x": 30, "y": 6, "ax": 39, "ay": 31, "d": "A"}, {"n": "⑧", "t": "Alérgeno puente", "s": "une dos IgE:<br>reexposición", "c": "d", "x": 50, "y": 6, "ax": 48, "ay": 23}, {"n": "⑧", "t": "Gránulos liberados", "s": "histamina, heparina,<br>triptasa en 30 s", "c": "d", "x": 72, "y": 6, "ax": 62, "ay": 40, "d": "B"}, {"n": "", "t": "Epitelio bronquial", "s": "donde se instala<br>la fase tardía", "c": "g", "x": 99.5, "y": 6, "ax": 90, "ay": 26, "al": "r"}, {"n": "①⑤", "t": "Célula dendrítica", "s": "presenta<br>al Th2", "c": "i", "x": 0.5, "y": 91, "ax": 7, "ay": 52, "al": "l"}, {"n": "⑥", "t": "Th2 y linfocito B", "s": "IL-4: el B cambia<br>a IgE", "c": "i", "x": 27, "y": 91, "ax": 22, "ay": 66}, {"n": "⑪", "t": "Capilar permeable", "s": "histamina: edema,<br>habón, rinorrea", "c": "d", "x": 46, "y": 91, "ax": 52, "ay": 72}, {"n": "⑨", "t": "Eosinófilo", "s": "eotaxina-CCR3:<br>sale del vaso", "c": "d", "x": 66, "y": 91, "ax": 76, "ay": 65, "d": "C"}, {"n": "⑩⑫", "t": "Fibrosis", "s": "TGF-β: colágeno,<br>remodelación", "c": "d", "x": 99.5, "y": 91, "ax": 92, "ay": 50, "al": "r"}], "diapos": [{"img": "img/26.webp", "ratio": 1.5, "titulo": "Sensibilización, degranulación y fase tardía", "texto": "<span class=\"cx\">Primero</span> el Th2 hace que el B fabrique IgE; <span class=\"cx\">luego</span>, en la reexposición, el mastocito <mark>se vacía en 30 s</mark> ⑧ <span class=\"lt2\">B</span>.", "etiquetas": [{"n": "③④", "t": "Ácaro y polen", "s": "proteínas inocuas:<br>ácaros 60-70 %", "c": "i", "x": 0.5, "y": 6, "ax": 20, "ay": 22, "d": "D", "al": "l"}, {"n": "⑥⑦", "t": "Mastocito con IgE", "s": "IgE sobre FcεRI:<br>célula «armada»", "c": "i", "x": 30, "y": 6, "ax": 39, "ay": 31, "d": "A"}, {"n": "⑧", "t": "Alérgeno puente", "s": "une dos IgE:<br>reexposición", "c": "d", "x": 50, "y": 6, "ax": 48, "ay": 23}, {"n": "⑧", "t": "Gránulos liberados", "s": "histamina, heparina,<br>triptasa en 30 s", "c": "d", "x": 72, "y": 6, "ax": 62, "ay": 40, "d": "B"}, {"n": "", "t": "Epitelio bronquial", "s": "donde se instala<br>la fase tardía", "c": "g", "x": 99.5, "y": 6, "ax": 90, "ay": 26, "al": "r"}, {"n": "①⑤", "t": "Célula dendrítica", "s": "presenta<br>al Th2", "c": "i", "x": 0.5, "y": 91, "ax": 7, "ay": 52, "al": "l"}, {"n": "⑥", "t": "Th2 y linfocito B", "s": "IL-4: el B cambia<br>a IgE", "c": "i", "x": 27, "y": 91, "ax": 22, "ay": 66}, {"n": "⑪", "t": "Capilar permeable", "s": "histamina: edema,<br>habón, rinorrea", "c": "d", "x": 46, "y": 91, "ax": 52, "ay": 72}, {"n": "⑨", "t": "Eosinófilo", "s": "eotaxina-CCR3:<br>sale del vaso", "c": "d", "x": 66, "y": 91, "ax": 76, "ay": 65, "d": "C"}, {"n": "⑩⑫", "t": "Fibrosis", "s": "TGF-β: colágeno,<br>remodelación", "c": "d", "x": 99.5, "y": 91, "ax": 92, "ay": 50, "al": "r"}]}, {"img": "img/26_2.webp", "ratio": 1.5, "titulo": "La IgE arma al mastocito", "texto": "La IgE se pega por su Fc al <mark>FcεRI</mark> ⑦ <span class=\"lt2\">A</span>; <span class=\"cx\">cuando</span> el alérgeno une dos IgE vecinas, entra calcio y el mastocito se degranula en 30 segundos ⑧ <span class=\"lt2\">B</span>.", "etiquetas": [{"n": "⑥", "t": "IgE", "s": "pegada por su Fc,<br>dura hasta 3 meses", "c": "i", "x": 0.5, "y": 6, "ax": 16, "ay": 28, "d": "A", "al": "l"}, {"n": "⑧", "t": "Alérgeno", "s": "une dos IgE<br>vecinas", "c": "g", "x": 40, "y": 6, "ax": 47, "ay": 26}, {"n": "⑧", "t": "Mastocito", "s": "unos 1000<br>gránulos", "c": "d", "x": 60, "y": 6, "ax": 72, "ay": 25}, {"n": "⑧", "t": "Gránulos liberados", "s": "se vacía en<br>30 segundos", "c": "d", "x": 99.5, "y": 6, "ax": 85, "ay": 48, "d": "B", "al": "r"}, {"n": "⑦", "t": "FcεRI", "s": "receptor de alta<br>afinidad por el Fc", "c": "i", "x": 0.5, "y": 91, "ax": 15.6, "ay": 43, "al": "l"}, {"n": "⑧", "t": "Señal", "s": "quinasas activadas<br>al entrecruzarse", "c": "i", "x": 30, "y": 91, "ax": 45, "ay": 56}, {"n": "⑧", "t": "Calcio", "s": "entra y dispara<br>la degranulación", "c": "i", "x": 47, "y": 91, "ax": 50, "ay": 63}, {"n": "⑪", "t": "Capilar con fuga", "s": "la histamina abre<br>el endotelio", "c": "d", "x": 99.5, "y": 91, "ax": 87, "ay": 78, "al": "r"}]}, {"img": "img/26_3.webp", "ratio": 1.5, "titulo": "Las cuatro fases de la alergia", "texto": "Sensibilización → fase aguda (menos de 60 min) → <mark>fase tardía a las 3-4 h</mark>, <span class=\"cx\">cuando</span> la <b>eotaxina</b> trae eosinófilos ⑨ <span class=\"lt2\">C</span> → fase crónica con fibrosis por TGF-β ⑩.", "etiquetas": [{"n": "⑩", "t": "1. Sensibilización", "s": "la dendrítica lleva<br>el alérgeno", "c": "i", "x": 0.5, "y": 6, "ax": 7, "ay": 47, "al": "l"}, {"n": "⑩", "t": "2. Fase aguda", "s": "en minutos el<br>mastocito se vacía", "c": "d", "x": 33, "y": 6, "ax": 32.5, "ay": 50, "d": "B"}, {"n": "⑨⑩", "t": "3. Fase tardía", "s": "a las 3-4 h llegan<br>los eosinófilos", "c": "d", "x": 61, "y": 6, "ax": 66, "ay": 46, "d": "C"}, {"n": "⑩", "t": "4. Fase crónica", "s": "fibrosis por TGF-β:<br>pared gruesa", "c": "d", "x": 99.5, "y": 6, "ax": 83, "ay": 51, "al": "r"}, {"n": "①", "t": "Linfocito B", "s": "con ayuda del Th2<br>fabrica IgE", "c": "i", "x": 13, "y": 91, "ax": 16.3, "ay": 55}, {"n": "⑧", "t": "Mediadores", "s": "histamina: edema<br>y broncoespasmo", "c": "d", "x": 35, "y": 91, "ax": 36.5, "ay": 50}, {"n": "⑨", "t": "Salen del capilar", "s": "la eotaxina los<br>atrae por CCR3", "c": "i", "x": 57, "y": 91, "ax": 61, "ay": 58.6}, {"n": "⑩", "t": "Músculo grueso", "s": "luz estrecha<br>para siempre", "c": "d", "x": 99.5, "y": 91, "ax": 87, "ay": 60, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = cómo se arma la alergia</b> (alérgeno, presentación, IgE), <b class=\"d\">rojo = qué daña</b> (degranulación, eosinófilos, fibrosis), gris = estructuras de referencia.", "<b>Izquierda:</b> el ácaro y el polen son <mark>proteínas</mark> inocuas para la mayoría. La célula dendrítica las presenta a un Th2 y, <span class=\"cx\">por eso</span>, el linfocito B cambia a IgE. Nada se nota todavía.", "<b>Centro:</b> el mastocito ya está «armado» con IgE sobre su FcεRI <span class=\"lt2\">A</span>. <span class=\"cx\">Cuando</span> un alérgeno une dos IgE vecinas, sale el contenido de sus gránulos <span class=\"lt2\">B</span> y el capilar se vuelve permeable.", "<b>Derecha:</b> la eotaxina llama a los eosinófilos por su CCR3 <span class=\"lt2\">C</span>; en el tejido viven semanas, liberan proteína básica mayor y, con el TGF-β, dejan colágeno y remodelación."], "recordar": "Atopia + alérgeno → Th2 → <b>IgE</b> → FcεRI del mastocito → reexposición: <mark>degranulación en 30 s</mark> → eosinófilos a las 3-4 h → fibrosis si persiste."}, "numeros": [{"l": "A", "html": "<b>IgE</b>: media en sangre <b class=\"b\">3 µg/L</b>; libre vive <b class=\"n\">2-3 días</b>, unida al receptor hasta <b class=\"a\">3 meses</b>.", "rango": null}, {"l": "B", "html": "<b>Mastocito</b>: unos <b class=\"n\">1000 gránulos</b>, se vacía en <b class=\"a\">30 segundos</b>; triptasa, quinasa y carboxilpeptidasa son el <b class=\"n\">25 %</b> del gránulo.", "rango": null}, {"l": "C", "html": "<b>Eosinófilo</b>: en sangre vive <b class=\"n\">8-18 h</b>, en el tejido <b class=\"a\">semanas</b>; normal <b class=\"n\">200-500/µL</b>.", "rango": {"min": 0, "max": 1000, "unidad": "/µL", "zonas": [[0, 200, "b"], [200, 500, "n"], [500, 1000, "a"]], "marcas": [200, 500]}}, {"l": "D", "html": "<b>Riesgo hereditario</b>: un padre <b class=\"a\">30 %</b>, ambos <b class=\"a\">50 %</b>, gemelo idéntico <b class=\"a\">70 %</b>. Ácaros: <b class=\"a\">60-70 %</b> de las sensibilizaciones.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del alérgeno a la fibrosis", "subtitulo": "estímulo → células → mecanismo → resultado → qué pasa si persiste", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> un atópico inhala o come un <mark>alérgeno</mark> (ácaro, polen, caspa, alimento). La higiene excesiva ya había programado su respuesta hacia Th2.", "pr": "el alérgeno llega a la mucosa sin hacer daño propio.", "pr_tit": "Produce:", "rf": "Preguntas ①②③④⑤ · punto <span class=\"lt2\">D</span>", "color": "p1"}, {"t": "2. Sensibilización", "m": "<b>Por qué:</b> la célula dendrítica lo presenta al <mark>Th2</mark>; la IL-4 hace que el linfocito B produzca <b>IgE</b>, que se fija al FcεRI de mastocitos y basófilos.", "pr": "mastocito «armado»; clínicamente silencioso.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑦ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Fase aguda", "m": "<b>Qué produce:</b> en la reexposición el alérgeno une dos IgE; el mastocito libera <mark>histamina</mark>, heparina, triptasa y <span class=\"cx\">luego</span> leucotrienos y PGF2.", "pr": "broncoconstricción, edema, rinorrea o habón en menos de 60 min.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑩⑪ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Fase tardía", "m": "<b>Por qué:</b> eicosanoides y <mark>eotaxina</mark> atraen eosinófilos (CCR3), linfocitos y macrófagos, que suman IL-4, IL-5, IL-9 e IL-13.", "pr": "la inflamación vuelve a las 3-4 h.", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑩ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Si persiste", "m": "<b>Fase crónica:</b> el <mark>TGF-β</mark> baja la inflamación pero deposita colágeno y atrae fibroblastos; los eosinófilos liberan MBP y metaloproteinasas.", "pr": "fibrosis y remodelación (asma). Se previene con lactancia, control ambiental e inmunoterapia.", "pr_tit": "Produce:", "rf": "Preguntas ⑩⑫", "color": "p4"}], "extra": [{"html": "🧪 <b>Diagnóstico:</b> la prueba cutánea da eritema y habón en 10-20 min, pero solo prueba <mark>sensibilización</mark>; la IgE específica se mide en suero y la IgE total vale poco. Los eosinófilos suben en moco nasal y esputo.", "k": ""}, {"html": "💊 <b>Cinco pilares:</b> prevenir la sensibilización (lactancia: IgA + TGF-β), controlar el ambiente, antiinflamatorios, <b>inmunoterapia</b> con dosis crecientes y anticuerpos monoclonales contra la IgE.", "k": "k"}], "escaleras": [{"c": "d", "t": "⏱️ Las cuatro fases en el tiempo", "pasos": ["sensibilización: silenciosa", "aguda: menos de 60 min", "tardía: 3-4 h", "crónica: semanas a años", "<b>fibrosis</b> y remodelación"]}], "html": "", "fuente": "Fuente: tu teoría — clase 33 (definición, genética, alérgenos, hipótesis de la higiene, actores celulares, cuatro fases, diagnóstico y tratamiento)."}, "preguntas": [{"n": 1, "id": "IN15-001", "c": "i", "tema": "Definición y atopia", "pregunta": "La alergia se define como una respuesta inmune nociva, de tipo inflamatorio, mediada principalmente por:", "opciones": ["a. IgG que activa el complemento", "b. Linfocitos T CD8 citotóxicos", "c. IgE en individuos con predisposición genética (atopia)", "d. Inmunocomplejos depositados en los vasos", "e. IgA secretora de las mucosas"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. IgE, en individuos con predisposición genética (atopia) que se sensibilizan a alérgenos inocuos para la mayoría.", "sin_banco": true, "ok": "", "x": "La alergia es <mark>mediada por IgE</mark> y aparece solo en quien tiene la predisposición genética llamada <b>atopia</b>. <span class=\"cx\">Por eso</span> el mismo polen no hace nada a la mayoría, <span class=\"cx\">en cambio</span> sensibiliza al atópico. <span class=\"res\">Atopia = predisposición; alergia = la respuesta IgE nociva.</span>", "truco": "Atopia es el terreno; la IgE es la semilla.", "veces": 0}, {"n": 2, "id": "IN15-002", "c": "i", "tema": "Definición y atopia", "pregunta": "¿Cuál es el riesgo de alergia en un hijo cuando ambos padres son alérgicos?", "opciones": ["a. 10 %", "b. 30 %", "c. 70 %", "d. 50 %", "e. 90 %"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. 50 %; si solo un padre es alérgico, 30 %, y en gemelos idénticos, 70 %.", "sin_banco": true, "ok": "", "x": "Es el punto Ⓓ de «Números clave»: el riesgo crece con la carga genética, <mark>30 % con un padre, 50 % con dos</mark> y 70 % en gemelos idénticos. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN15-003", "c": "i", "tema": "Alérgenos", "pregunta": "¿Qué fuente explica el 60-70 % de las sensibilizaciones alérgicas y es la principal causa de asma alérgica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Los ácaros del polvo doméstico (Dermatophagoides pteronyssinus, D. farinae, Blomia tropicalis), que proliferan a 25-30 °C y humedad mayor de 60 %.", "sin_banco": true, "ok": "", "x": "El ácaro de la izquierda de la imagen explica el <mark>60-70 %</mark> de las sensibilizaciones; vive en colchones y almohadas a 25-30 °C y humedad mayor de 60 %, <span class=\"cx\">así que</span> <span class=\"res\">es el rey del asma alérgica</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN15-004", "c": "i", "tema": "Alérgenos", "pregunta": "¿Cómo se nombran internacionalmente los alérgenos purificados? Da un ejemplo.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Con las tres primeras letras del género y la primera de la especie del organismo de origen, más un número: Der p 1 = Dermatophagoides pteronyssinus.", "sin_banco": true, "ok": "", "x": "Los alérgenos son <mark>proteínas</mark>, muchas con actividad enzimática. Al purificarlos se nombran con <b>3 letras del género + 1 de la especie</b>; <span class=\"cx\">así que</span> «Der p» es Dermatophagoides pteronyssinus y «Ara h» es Arachis hypogaea (maní). <span class=\"res\">Género (3) + especie (1) + número.</span>", "truco": "Der-p: tres del género, una de la especie.", "veces": 0}, {"n": 5, "id": "IN15-005", "c": "i", "tema": "Hipótesis de la higiene", "pregunta": "Según la hipótesis de la higiene, el contacto temprano con bacterias y parásitos intracelulares protege de la alergia porque:", "opciones": ["a. Programa la respuesta inmune hacia el perfil Th1, que dificulta la producción de IgE", "b. Aumenta la producción de IgE protectora", "c. Destruye los mastocitos de la mucosa", "d. Induce el perfil Th2 de manera precoz", "e. Bloquea el receptor FcεRI de los basófilos"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Programa la respuesta hacia Th1, que dificulta la producción de IgE.", "sin_banco": true, "ok": "", "x": "Las infecciones tempranas empujan al sistema inmune hacia <mark>Th1</mark>. <span class=\"cx\">En cambio</span>, la higiene excesiva de los países desarrollados quita ese estímulo y la respuesta se programa precozmente hacia <b>Th2</b>, que es la que produce IgE. <span class=\"res\">Menos microbios = más Th2 = más alergia.</span>", "truco": "Mucha higiene, mucho Th2.", "veces": 0}, {"n": 6, "id": "IN15-006", "c": "i", "tema": "IgE", "pregunta": "Sobre la IgE, señale lo FALSO:", "opciones": ["a. Su concentración media en sangre es de unos 3 µg/L", "b. Libre en circulación vive dos a tres días", "c. Se produce desde la semana 11 de gestación", "d. Unida a su receptor puede durar hasta tres meses", "e. Es la inmunoglobulina más abundante del suero"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es FALSO: la IgE es la menos abundante (µg/L frente a los mg/L de IgG, IgA e IgM).", "sin_banco": true, "ok": "", "x": "Las Y azules del mastocito (punto Ⓐ) son IgE: hay <mark>muy poca en sangre (3 µg/L)</mark>, pero pegada al FcεRI dura meses. <span class=\"cx\">Por eso</span> <span class=\"res\">la e es la falsa</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN15-007", "c": "i", "tema": "Mastocitos y basófilos", "pregunta": "¿Qué receptor reconoce con mayor afinidad la porción Fc de la IgE y en qué células abunda?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El FcεRI, receptor de alta afinidad; se expresa en grandes cantidades en mastocitos y basófilos.", "sin_banco": true, "ok": "", "x": "El <mark>FcεRI</mark> es el receptor de alta afinidad; al unirse al complejo alérgeno-IgE <b>activa</b> la célula. El FcεRII y el FcεRIII tienen menor afinidad y regulan. <span class=\"cx\">Por eso</span> <span class=\"res\">mastocitos y basófilos</span> mandan en la respuesta inmediata.", "truco": "Fc-épsilon-RI: el «uno» es el de alta afinidad.", "veces": 0}, {"n": 8, "id": "IN15-008", "c": "d", "tema": "Mastocitos y basófilos", "pregunta": "Respecto al mastocito en la reacción alérgica, es correcto:", "opciones": ["a. Tiene unos 100 gránulos y se degranula en 10 minutos", "b. Cada mastocito tiene unos 1000 gránulos y se degranula en unos 30 segundos", "c. Sus gránulos contienen IgE preformada", "d. La triptasa, quinasa y carboxilpeptidasa son el 75 % del contenido granular", "e. Solo libera mediadores neoformados"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Cada mastocito tiene unos 1000 gránulos y se degranula en unos 30 segundos.", "sin_banco": true, "ok": "", "x": "Es el mastocito del centro (punto Ⓑ): <mark>1000 gránulos en 30 segundos</mark>, con histamina, heparina y tres enzimas que son el 25 % del gránulo. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN15-009", "c": "d", "tema": "Eosinófilos", "pregunta": "¿Qué quimioquina recluta a los eosinófilos al tejido en la alergia y por qué receptor actúa?", "opciones": ["a. IL-8 por CXCR1", "b. RANTES por CCR5", "c. Eotaxina por CCR3", "d. C5a por C5aR", "e. IL-2 por CD25"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. La eotaxina, producida por mastocitos y basófilos, actúa por el receptor CCR3.", "sin_banco": true, "ok": "", "x": "A la derecha de la imagen los eosinófilos salen del vaso (punto Ⓒ) <span class=\"cx\">porque</span> el mastocito produjo <mark>eotaxina</mark> y ellos tienen <b>CCR3</b>. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN15-010", "c": "d", "tema": "Fases del proceso inflamatorio", "pregunta": "Ordene las cuatro fases del proceso inflamatorio alérgico e indique cuándo aparece la fase tardía.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Sensibilización → fase aguda (menos de 60 min) → fase tardía (3-4 h después) → fase crónica (exposición prolongada, TGF-β, fibrosis).", "sin_banco": true, "ok": "", "x": "La imagen recorre las fases de izquierda a derecha: <mark>sensibilización → aguda → tardía (3-4 h) → crónica</mark>. La escalera de la página 2 las ordena en el tiempo.", "truco": "", "veces": 0}, {"n": 11, "id": "IN15-011", "c": "i", "tema": "Diagnóstico de alergia", "pregunta": "Un niño tiene una prueba cutánea positiva a gato, pero convive con su gato sin ningún síntoma. ¿Cómo se interpreta?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Está sensibilizado (tiene IgE específica en los mastocitos de la piel), pero no es alérgico: la alergia exige relación clínica entre exposición y síntomas.", "sin_banco": true, "ok": "", "x": "La prueba cutánea da habón y eritema en 10-20 min <span class=\"cx\">porque</span> el alérgeno se une a la IgE de los mastocitos de la piel. Eso prueba <mark>sensibilización, no alergia</mark>; <span class=\"cx\">en cambio</span>, la alergia necesita síntomas ligados a la exposición. <span class=\"res\">Prueba positiva sin síntomas = solo sensibilizado.</span>", "truco": "Positivo en la piel no es enfermo en la vida.", "veces": 0}, {"n": 12, "id": "IN15-012", "c": "i", "tema": "Bases del tratamiento", "pregunta": "¿Por qué la lactancia materna previene la sensibilización alérgica? Mencione los dos componentes de la leche implicados.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La IgA de la leche bloquea los alérgenos en el intestino y el TGF-β evita el inicio de una respuesta inflamatoria ante proteínas extrañas.", "sin_banco": true, "ok": "", "x": "La lactancia evita el contacto precoz con proteínas extrañas. <span class=\"cx\">Además</span>, su <mark>IgA</mark> bloquea alérgenos en la luz intestinal y su <b>TGF-β</b> frena la inflamación. Los otros pilares son control ambiental, antiinflamatorios, inmunoterapia y monoclonales. <span class=\"res\">IgA + TGF-β de la leche.</span>", "truco": "La leche trae escudo (IgA) y calmante (TGF-β).", "veces": 0}], "tabla": {"cab": ["", "Sensibilización", "Fase aguda", "Fase tardía", "Fase crónica"], "filas": [["Cuándo", "1.er contacto", "menos de 60 min", "3-4 h", "exposición prolongada"], ["Actores", "dendrítica, Th2, LB", "mastocito, basófilo", "eosinófilo, linfocito", "eosinófilo, fibroblasto"], ["Mediadores", "IL-4 → IgE", "histamina, triptasa", "leucotrienos, eotaxina", "TGF-β, MBP"], ["Clínica", "ninguna", "habón, broncoespasmo", "inflamación vuelve", "fibrosis"], ["🔑 Para diferenciar", "silenciosa", "minutos", "horas", "cicatriz"]]}, "fuente": "Fuente: tu teoría — clase 33 (Mecanismos básicos de las alergias), Rojas 17.ª ed., cap. 33."}, {"n": 27, "slug": "Anafilaxia", "titulo": "Anafilaxia", "subtitulo": "degranulación masiva: piel, vía aérea y circulación a la vez; adrenalina IM al muslo", "grupo": "g15", "lema": "La idea: la anafilaxia es una reacción de hipersensibilidad <mark>generalizada, sistémica y seria</mark> que atenta contra la vida. Mastocitos y basófilos de todo el cuerpo se vacían a la vez: la <b>histamina</b> y el <b>PAF</b> abren los vasos y deprimen el corazón, mientras el bronquio se cierra. Por eso la muerte llega <u>en la primera hora</u> y el único tratamiento de primera línea es la <b>adrenalina intramuscular</b> en el muslo; antihistamínicos y corticoides llegan tarde. En la imagen verás de izquierda a derecha: el mastocito y el basófilo que se degranulan hacia la sangre, el cuerpo con todos los órganos tomados y el autoinyector en la cara anterolateral del muslo.", "img": "img/27.webp", "mini": "img/mini/27.webp", "ratio": 1.5, "etiquetas": [{"n": "④", "t": "Mastocito", "s": "IgE entrecruzada:<br>entra calcio", "c": "i", "x": 0.5, "y": 6, "ax": 10, "ay": 30, "al": "l"}, {"n": "⑦", "t": "Basófilo", "s": "también se vacía;<br>contraste: sin IgE", "c": "i", "x": 33, "y": 6, "ax": 30, "ay": 31}, {"n": "⑧", "t": "Labios y habones", "s": "piel 80-90 %:<br>el primer aviso", "c": "d", "x": 66, "y": 6, "ax": 65, "ay": 37, "d": "A"}, {"n": "⑩", "t": "Autoinyector", "s": "300 µg adulto,<br>150 µg niño", "c": "g", "x": 99.5, "y": 6, "ax": 82, "ay": 25, "al": "r"}, {"n": "⑤⑨", "t": "Mediadores", "s": "histamina, triptasa;<br>luego PAF", "c": "d", "x": 0.5, "y": 91, "ax": 22, "ay": 60, "d": "C", "al": "l"}, {"n": "②⑥", "t": "Vasos dilatados", "s": "fuga de plasma:<br>hipotensión", "c": "d", "x": 28, "y": 91, "ax": 37, "ay": 68, "d": "D"}, {"n": "", "t": "Bronquios cerrados", "s": "broncoespasmo,<br>estridor (70 %)", "c": "d", "x": 46, "y": 91, "ax": 47, "ay": 40}, {"n": "⑥⑪", "t": "Corazón", "s": "PAF: menos flujo<br>y contractilidad", "c": "d", "x": 66, "y": 91, "ax": 55, "ay": 52}, {"n": "⑩⑫", "t": "Vasto lateral", "s": "IM 0,01 mg/kg:<br>absorbe rápido", "c": "g", "x": 99.5, "y": 91, "ax": 85, "ay": 72, "d": "B", "al": "r"}], "diapos": [{"img": "img/27.webp", "ratio": 1.5, "titulo": "Todo el cuerpo a la vez", "texto": "Mastocito y basófilo se vacían hacia la sangre: piel, vía aérea y vasos caen juntos; <span class=\"cx\">por eso</span> la <mark>adrenalina IM al muslo</mark> va <span class=\"cx\">primero</span> ⑩.", "etiquetas": [{"n": "④", "t": "Mastocito", "s": "IgE entrecruzada:<br>entra calcio", "c": "i", "x": 0.5, "y": 6, "ax": 10, "ay": 30, "al": "l"}, {"n": "⑦", "t": "Basófilo", "s": "también se vacía;<br>contraste: sin IgE", "c": "i", "x": 33, "y": 6, "ax": 30, "ay": 31}, {"n": "⑧", "t": "Labios y habones", "s": "piel 80-90 %:<br>el primer aviso", "c": "d", "x": 66, "y": 6, "ax": 65, "ay": 37, "d": "A"}, {"n": "⑩", "t": "Autoinyector", "s": "300 µg adulto,<br>150 µg niño", "c": "g", "x": 99.5, "y": 6, "ax": 82, "ay": 25, "al": "r"}, {"n": "⑤⑨", "t": "Mediadores", "s": "histamina, triptasa;<br>luego PAF", "c": "d", "x": 0.5, "y": 91, "ax": 22, "ay": 60, "d": "C", "al": "l"}, {"n": "②⑥", "t": "Vasos dilatados", "s": "fuga de plasma:<br>hipotensión", "c": "d", "x": 28, "y": 91, "ax": 37, "ay": 68, "d": "D"}, {"n": "", "t": "Bronquios cerrados", "s": "broncoespasmo,<br>estridor (70 %)", "c": "d", "x": 46, "y": 91, "ax": 47, "ay": 40}, {"n": "⑥⑪", "t": "Corazón", "s": "PAF: menos flujo<br>y contractilidad", "c": "d", "x": 66, "y": 91, "ax": 55, "ay": 52}, {"n": "⑩⑫", "t": "Vasto lateral", "s": "IM 0,01 mg/kg:<br>absorbe rápido", "c": "g", "x": 99.5, "y": 91, "ax": 85, "ay": 72, "d": "B", "al": "r"}]}, {"img": "img/27_2.webp", "ratio": 1.5, "titulo": "Mediadores: listos o recién hechos", "texto": "Las IgE entrecruzadas activan Lyn, Syk y Fyn y <mark>entra calcio</mark> ④; la histamina sale de inmediato, <span class=\"cx\">en cambio</span> el <b>PAF</b> se fabrica de novo ⑤⑥; el contraste lo activa sin IgE ⑦.", "etiquetas": [{"n": "④", "t": "Alérgeno puente", "s": "une dos IgE<br>vecinas", "c": "i", "x": 0.5, "y": 6, "ax": 13.3, "ay": 24, "al": "l"}, {"n": "④", "t": "Canal de calcio", "s": "entra Ca2+:<br>orden de vaciar", "c": "i", "x": 25, "y": 6, "ax": 23, "ay": 44}, {"n": "⑤", "t": "Gránulos preformados", "s": "histamina y triptasa<br>salen en segundos", "c": "d", "x": 43, "y": 6, "ax": 35, "ay": 36}, {"n": "⑦", "t": "Contraste yodado", "s": "activa al mastocito<br>sin IgE", "c": "g", "x": 70, "y": 6, "ax": 86, "ay": 23}, {"n": "④", "t": "Lyn, Syk y Fyn", "s": "cinasas en cadena<br>tras el entrecruzamiento", "c": "i", "x": 11, "y": 91, "ax": 14, "ay": 55}, {"n": "⑤", "t": "Gránulos llenos", "s": "mediador preformado:<br>listo para salir", "c": "g", "x": 34, "y": 91, "ax": 45.6, "ay": 67}, {"n": "⑥", "t": "Mediadores lipídicos", "s": "el PAF se fabrica de novo:<br>vasodilata y hace fugar plasma", "c": "d", "x": 59, "y": 91, "ax": 64, "ay": 52}, {"n": "⑦", "t": "Sin IgE en la superficie", "s": "anafilaxia<br>no mediada por IgE", "c": "d", "x": 99.5, "y": 91, "ax": 79, "ay": 62, "al": "r"}]}, {"img": "img/27_3.webp", "ratio": 1.5, "titulo": "Desencadenantes y rescate", "texto": "En América Latina los <mark>medicamentos</mark> encabezan las causas ③; el rescate es adrenalina IM <span class=\"lt2\">B</span> ⑩ y, si toma betabloqueador, <b>glucagón</b> ⑪.", "etiquetas": [{"n": "③", "t": "Medicamentos", "s": "1.ª causa en<br>América Latina (2011)", "c": "d", "x": 13, "y": 6, "ax": 12, "ay": 26}, {"n": "③", "t": "Alimentos", "s": "maní y<br>mariscos", "c": "d", "x": 40, "y": 6, "ax": 42, "ay": 26}, {"n": "③", "t": "Insectos", "s": "abeja y avispa:<br>himenópteros", "c": "d", "x": 68, "y": 6, "ax": 70, "ay": 28}, {"n": "⑩", "t": "Autoinyector al muslo", "s": "adrenalina IM:<br>primera línea", "c": "i", "x": 14, "y": 91, "ax": 17.6, "ay": 70, "d": "B"}, {"n": "⑩", "t": "Ampolla 1:1000", "s": "0,01 mg/kg IM;<br>repetir cada 5-15 min", "c": "i", "x": 37, "y": 91, "ax": 41.7, "ay": 70}, {"n": "", "t": "Suero IV", "s": "volumen para<br>el choque", "c": "g", "x": 59, "y": 91, "ax": 61, "ay": 62, "d": "D"}, {"n": "⑪", "t": "Glucagón", "s": "si toma betabloqueador<br>y sigue hipotenso", "c": "i", "x": 99.5, "y": 91, "ax": 85, "ay": 72, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = mecanismo y diagnóstico</b>, <b class=\"d\">rojo = daño en órganos</b>, gris = tratamiento y referencias.", "<b>Izquierda:</b> en la reexposición el alérgeno une dos IgE sobre el FcεRI; Lyn, Syk y Fyn se activan y el <mark>influjo de calcio</mark> vacía los gránulos. Contrastes, dextranos y AINE lo hacen <b>sin IgE</b>.", "<b>Centro:</b> la piel avisa <span class=\"cx\">primero</span> <span class=\"lt2\">A</span>; <span class=\"cx\">luego</span> vía aérea, intestino y corazón. El PAF baja el flujo coronario y, por óxido nítrico, dilata los vasos: <b>choque</b>.", "<b>Derecha:</b> adrenalina 1:1000 al músculo vasto lateral <span class=\"lt2\">B</span>, que absorbe más rápido que el deltoides o el subcutáneo. La triptasa confirma el cuadro <span class=\"lt2\">C</span>."], "recordar": "Piel + (vía aérea o hipotensión) tras un alérgeno = anafilaxia → <mark>adrenalina IM 0,01 mg/kg al muslo</mark> ya; el resto es soporte."}, "numeros": [{"l": "A", "html": "<b>Órganos</b>: piel <b class=\"a\">80-90 %</b>, respiratorio <b class=\"a\">70 %</b>, digestivo y cardiovascular <b class=\"n\">45 %</b>, SNC <b class=\"b\">15 %</b>.", "rango": null}, {"l": "B", "html": "<b>Adrenalina</b>: <b class=\"n\">0,01 mg/kg</b> IM (1:1000), máximo <b class=\"a\">0,5 mg</b> adulto y <b class=\"a\">0,3 mg</b> niño, cada <b class=\"n\">5-15 min</b>. Autoinyector <b class=\"n\">300 µg</b> adulto, <b class=\"n\">150 µg</b> niño.", "rango": null}, {"l": "C", "html": "<b>Triptasa</b>: tomar entre <b class=\"n\">15 min y 3 h</b>; estudio alergológico a las <b class=\"n\">3-4 semanas</b>; observación mínima <b class=\"a\">4 h</b>.", "rango": {"min": 0, "max": 6, "unidad": "h", "zonas": [[0, 0.25, "m", "pronto"], [0.25, 3, "n", "ventana"], [3, 6, "a", "tarde"]], "marcas": [0.25, 3]}}, {"l": "D", "html": "<b>Choque</b>: sistólica <b class=\"b\">menos de 90 mmHg</b> o caída de más de <b class=\"a\">30 %</b>; mortalidad <b class=\"a\">0,65-2 %</b>, casi siempre en la <b class=\"a\">primera hora</b>.", "rango": {"min": 50, "max": 140, "unidad": "mmHg", "zonas": [[50, 90, "a", "choque"], [90, 140, "n"]], "marcas": [90]}}], "escalas": [], "cadena": {"titulo": "Del alérgeno al choque", "subtitulo": "estímulo → mastocito → mediadores → órganos → qué pasa si falla la adrenalina", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> un sensibilizado vuelve a recibir el alérgeno: <mark>medicamento</mark>, alimento (maní) o veneno de himenóptero. Contrastes y AINE pueden actuar sin IgE.", "pr": "llega a la sangre en minutos.", "pr_tit": "Produce:", "rf": "Preguntas ①③⑦", "color": "p1"}, {"t": "2. Mastocito", "m": "<b>Por qué:</b> el alérgeno <mark>entrecruza dos IgE</mark> en el FcεRI; Lyn, Syk y Fyn activan la señal y entra calcio.", "pr": "degranulación de mastocitos y basófilos de todo el cuerpo.", "pr_tit": "Produce:", "rf": "Pregunta ④", "color": "p2"}, {"t": "3. Mediadores", "m": "<b>Qué produce:</b> en segundos los <mark>preformados</mark> (histamina, triptasa, heparina, carboxipeptidasa A3); en minutos los <b>neoformados</b> (PAF, PGD2, leucotrieno C4).", "pr": "vasodilatación, fuga capilar, broncoespasmo y depresión miocárdica.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥ · punto <span class=\"lt2\">C</span>", "color": "p3"}, {"t": "4. Órganos", "m": "<b>Qué pasa:</b> piel y mucosas (urticaria, angioedema), vía aérea (estridor, sibilancias), intestino, <mark>hipotensión</mark> y arritmias (renina-angiotensina local).", "pr": "criterios WAO: diagnóstico clínico.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">D</span>", "color": "p4"}, {"t": "5. Si falla", "m": "<b>Sin adrenalina a tiempo:</b> colapso cardiovascular y respiratorio <mark>en la primera hora</mark>. Con betabloqueadores la adrenalina no actúa: <b>glucagón</b>.", "pr": "muerte; al alta, autoinyector y plan escrito.", "pr_tit": "Produce:", "rf": "Preguntas ②⑩⑪⑫ · punto <span class=\"lt2\">B</span>", "color": "p4"}], "extra": [{"html": "🌎 <b>Causas en Latinoamérica (2011):</b> <mark>medicamentos 31,2 %</mark>, alimentos 23,3 %, himenópteros 14,8 %. En el mundo los alimentos son el 33-56 % de los casos.", "k": ""}, {"html": "🩺 <b>Soporte a la vez:</b> retirar el desencadenante, <mark>decúbito supino con piernas elevadas</mark>, oxígeno 6-8 L/min, vía gruesa y solución salina 5-10 ml/kg en 5-10 min; observar mínimo 4 h.", "k": ""}, {"html": "⚠️ <b>Error más frecuente:</b> dar antihistamínico (1-3 h) o corticoide (4 h) antes de la adrenalina. No corrigen la hipotensión ni la obstrucción de la vía aérea.", "k": "k"}], "escaleras": [{"c": "d", "t": "💉 Escalera de la adrenalina", "pasos": ["IM 1:1000 al muslo, 0,01 mg/kg", "repetir cada 5-15 min", "IV 1:10 000 si paro o choque refractario", "intratraqueal si no hay vena", "<b>glucagón</b> si toma betabloqueadores"]}], "html": "", "fuente": "Fuente: tu teoría — clase 34 (definición, epidemiología, desencadenantes, inmunopatología, clínica, criterios WAO, triptasa y tratamiento)."}, "preguntas": [{"n": 1, "id": "IN15-013", "c": "i", "tema": "Definición", "pregunta": "Según la WAO, la anafilaxia es:", "opciones": ["a. Una reacción local limitada a la piel", "b. Una reacción de hipersensibilidad generalizada, sistémica y seria que atenta contra la vida", "c. Una reacción tardía mediada por linfocitos T", "d. Una intolerancia no inmunológica a fármacos", "e. Una urticaria crónica de más de seis semanas"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Una reacción de hipersensibilidad generalizada, sistémica y seria que atenta contra la vida.", "sin_banco": true, "ok": "", "x": "<b>Ana-phylaxis</b> significa «contra la protección»: Richet y Portier (1902) vieron que una <mark>segunda exposición</mark> podía matar al animal que la toleró la primera vez. <span class=\"cx\">Por eso</span> la anafilaxia es la emergencia alérgica más grave. <span class=\"res\">Generalizada, sistémica, seria y letal.</span>", "truco": "Ana-filaxia: la protección que mata.", "veces": 0}, {"n": 2, "id": "IN15-014", "c": "d", "tema": "Epidemiología", "pregunta": "¿En qué momento ocurre generalmente la muerte por anafilaxia y cuál es el principal factor de riesgo de muerte?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "En la primera hora del cuadro; el principal factor de riesgo es el retardo en administrar adrenalina.", "sin_banco": true, "ok": "", "x": "Es el punto Ⓓ: los vasos dilatados del torso y la fuga de plasma llevan al <mark>choque en la primera hora</mark>; sin adrenalina a tiempo, el organismo no alcanza a compensar.", "truco": "", "veces": 0}, {"n": 3, "id": "IN15-015", "c": "i", "tema": "Desencadenantes", "pregunta": "En América Latina (datos de 2011), la primera causa de anafilaxia fue:", "opciones": ["a. Alimentos", "b. Picadura de himenópteros", "c. Látex", "d. Ejercicio", "e. Medicamentos"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Medicamentos (31,2 %), seguidos de alimentos (23,3 %) e himenópteros (14,8 %).", "sin_banco": true, "ok": "", "x": "Mira el recuadro 🌎 de la página 2: en Latinoamérica los <mark>medicamentos</mark> (31,2 %) superan a los alimentos y a las picaduras. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN15-016", "c": "i", "tema": "Inmunopatología", "pregunta": "En la anafilaxia mediada por IgE, el paso que inicia la degranulación del mastocito es:", "opciones": ["a. La unión del alérgeno a una sola IgE libre en plasma", "b. La activación del complemento por la vía alterna", "c. El entrecruzamiento de dos IgE adyacentes unidas al FcεRI, con activación de Lyn, Syk y Fyn e influjo de calcio", "d. La fagocitosis del alérgeno por el neutrófilo", "e. La salida de calcio de la célula"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. El entrecruzamiento de dos IgE vecinas sobre el FcεRI activa las tirosinkinasas Lyn, Syk y Fyn, y el influjo de calcio desencadena la degranulación.", "sin_banco": true, "ok": "", "x": "En el mastocito de la izquierda el alérgeno hace <mark>puente entre dos IgE</mark>; las tirosinkinasas y el calcio que entra vacían los gránulos que se ven hacia el vaso. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN15-017", "c": "d", "tema": "Mediadores", "pregunta": "Señale cuál NO es un mediador preformado del mastocito:", "opciones": ["a. Histamina", "b. Triptasa", "c. Heparina", "d. Factor activador de plaquetas (PAF)", "e. Carboxipeptidasa A3"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El PAF es neoformado (síntesis de novo, minutos a horas).", "sin_banco": true, "ok": "", "x": "Los gránulos que salen en la imagen son los <mark>preformados</mark>; el PAF no está guardado, se fabrica después. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN15-018", "c": "d", "tema": "Mediadores", "pregunta": "¿Qué efectos produce el PAF en la anafilaxia y cómo explica la hipotensión severa?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Disminuye el flujo coronario y la contractilidad cardíaca, recluta eosinófilos y neutrófilos, agrega plaquetas y causa vasodilatación periférica con hipotensión severa, posiblemente por inducción de óxido nítrico.", "sin_banco": true, "ok": "", "x": "El <mark>PAF</mark> golpea dos veces: deprime el corazón (menos flujo coronario y contractilidad) y dilata los vasos periféricos, probablemente por <b>óxido nítrico</b>. <span class=\"cx\">Por eso</span> cae la presión aunque el corazón intente compensar. <span class=\"res\">Corazón débil + vasos abiertos = choque.</span>", "truco": "PAF: Paraliza el corazón, Abre los vasos, Funde plaquetas.", "veces": 0}, {"n": 7, "id": "IN15-019", "c": "i", "tema": "Mecanismos no mediados por IgE", "pregunta": "Paciente sin antecedentes alérgicos presenta anafilaxia a los pocos minutos de recibir medio de contraste yodado por primera vez. ¿Qué mecanismo explica el cuadro?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Anafilaxia independiente de IgE: el medio de contraste activa directamente al mastocito, sin sensibilización previa ni IgE.", "sin_banco": true, "ok": "", "x": "La anafilaxia por IgE exige una <mark>sensibilización previa</mark>; en este paciente es la primera exposición. <span class=\"cx\">En cambio</span>, medios de contraste, dextranos, AINE y factores físicos degranulan al mastocito <b>directamente</b>. <span class=\"res\">Primera vez + contraste = vía no IgE.</span>", "truco": "Sin IgE no hace falta «primera vez».", "veces": 0}, {"n": 8, "id": "IN15-020", "c": "d", "tema": "Presentación clínica", "pregunta": "En la anafilaxia, el sistema afectado con mayor frecuencia es:", "opciones": ["a. Piel y mucosas (80-90 %)", "b. Tracto respiratorio (70 %)", "c. Tracto gastrointestinal (45 %)", "d. Cardiovascular (45 %)", "e. Sistema nervioso central (15 %)"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Piel y mucosas, en el 80-90 % de los casos (eritema, prurito, urticaria, angioedema).", "sin_banco": true, "ok": "", "x": "En el torso de la imagen la <mark>piel</mark> (habones y labios hinchados) es lo más frecuente, 80-90 % (punto Ⓐ). <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN15-021", "c": "i", "tema": "Diagnóstico", "pregunta": "¿Cuál es el marcador de laboratorio más útil en la anafilaxia y en qué ventana se toma la muestra?", "opciones": ["a. Histamina sérica, a las 24 horas", "b. IgE total, al alta", "c. Eosinófilos en sangre, a la semana", "d. Triptasa sérica, entre los 15 minutos y las 3 horas del inicio", "e. Complemento C3, a las 4 semanas"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La triptasa sérica, tomada entre los 15 minutos y las 3 horas del inicio.", "sin_banco": true, "ok": "", "x": "Punto Ⓒ: la <mark>triptasa</mark> sigue alta hasta 3 h, <span class=\"cx\">en cambio</span> la histamina dura minutos. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN15-022", "c": "g", "tema": "Tratamiento: adrenalina", "pregunta": "En un adulto con anafilaxia, la adrenalina de primera línea se administra:", "opciones": ["a. 1 mg IV directo de la dilución 1:1000", "b. 0,01 mg/kg IM en la cara anterolateral del muslo, de la dilución 1:1000, máximo 0,5 mg, repetible cada 5-15 min", "c. 0,5 mg subcutánea en el deltoides, una sola vez", "d. 0,1 mg/kg inhalada", "e. Solo después del antihistamínico y del corticoide"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. 0,01 mg/kg IM en el muslo anterolateral (dilución 1:1000), máximo 0,5 mg en adultos y 0,3 mg en niños, repetible cada 5-15 min.", "sin_banco": true, "ok": "", "x": "Es el autoinyector de la derecha (punto Ⓑ): <mark>0,01 mg/kg IM</mark> en la cara anterolateral del muslo, máximo 0,5 mg en adultos. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN15-023", "c": "g", "tema": "Tratamiento: segunda línea", "pregunta": "Paciente con anafilaxia que toma betabloqueadores sigue hipotenso y bradicárdico pese a varias dosis de adrenalina. ¿Qué fármaco está indicado?", "opciones": ["a. Clorfenamina", "b. Hidrocortisona", "c. Salbutamol", "d. Atropina en nebulización", "e. Glucagón"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Glucagón, 20-30 µg/kg (máx. 1 mg) y luego infusión de 5-15 µg/min.", "sin_banco": true, "ok": "", "x": "El betabloqueador impide que la adrenalina actúe. El <mark>glucagón</mark> tiene efecto cronotrópico e inotrópico <b>independiente de catecolaminas</b>, <span class=\"cx\">por eso</span> rescata a este paciente. <span class=\"res\">Betabloqueado y refractario = glucagón.</span>", "truco": "Betabloqueador bloquea; glucagón lo esquiva.", "veces": 0}, {"n": 12, "id": "IN15-024", "c": "g", "tema": "Tratamiento: segunda línea", "pregunta": "¿Por qué los antihistamínicos y los corticoides no son primera línea en anafilaxia? ¿Qué se indica al alta?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "No corrigen la hipotensión ni la obstrucción de la vía aérea y actúan tarde (1-3 h y 4 h). Al alta: adrenalina en autoinyector (150 µg niños, 300 µg adultos), plan escrito y alergólogo a las 3-4 semanas, tras observar mínimo 4 h.", "sin_banco": true, "ok": "", "x": "Dar antihistamínico o corticoide <mark>antes de la adrenalina</mark> es el error más frecuente y aumenta la mortalidad, <span class=\"cx\">porque</span> solo alivian piel y prurito. <span class=\"cx\">Por eso</span> el paciente se observa <b>4 h</b> y se va con <span class=\"res\">autoinyector y plan de emergencia</span>.", "truco": "Antihistamínico calma la piel, no salva la vida.", "veces": 0}], "tabla": {"cab": ["", "Adrenalina", "Antihistamínico", "Corticoide", "Glucagón"], "filas": [["Línea", "primera", "segunda", "segunda", "rescate"], ["Inicio", "minutos", "1-3 h", "4 h", "minutos"], ["Qué corrige", "choque y vía aérea", "prurito, urticaria", "¿bifásica?", "corazón betabloqueado"], ["Dosis", "0,01 mg/kg IM", "—", "—", "20-30 µg/kg"], ["🔑 Lo que no debes olvidar", "nunca retrasarla", "no salva la vida", "no es urgente", "si toma betabloqueador"]]}, "fuente": "Fuente: tu teoría — clase 34 (Anafilaxia), Rojas 17.ª ed., cap. 34."}, {"n": 28, "slug": "Asma_rinitis_y_urticaria", "titulo": "Asma, rinitis y urticaria", "subtitulo": "el mismo mastocito en el bronquio y en la piel", "grupo": "g16", "lema": "La idea: el asma y la rinitis son <mark>una sola vía aérea inflamada</mark> por la IgE, y la urticaria es el mismo mastocito trabajando en la piel. En el bronquio, la histamina y los leucotrienos cierran la luz en minutos; a las 3-4 h los <b>Th2</b> traen eosinófilos y, si nadie lo frena, la pared se <b>remodela</b>. En la piel, la histamina sobre los receptores H1 hace la <u>triple respuesta</u>: eritema, habón y reflejo axonal; si el edema es profundo, es <b>angioedema</b>. En la imagen verás de izquierda a derecha: un bronquio normal frente a uno asmático, la mucosa bronquial ampliada y un corte de piel con habón y angioedema.", "img": "img/28.webp", "mini": "img/mini/28.webp", "ratio": 1.5, "etiquetas": [{"n": "①", "t": "Normal", "s": "luz amplia,<br>músculo fino", "c": "g", "x": 0.5, "y": 6, "ax": 10, "ay": 40, "al": "l"}, {"n": "②⑦", "t": "Asmático", "s": "luz estrecha,<br>tapón de moco", "c": "i", "x": 27, "y": 6, "ax": 30, "ay": 49}, {"n": "③⑤", "t": "Mastocito bronquial", "s": "histamina, triptasa,<br>leucotrienos", "c": "i", "x": 46, "y": 6, "ax": 52, "ay": 42, "d": "A"}, {"n": "", "t": "Epitelio ciliado", "s": "MBP y proteína<br>catiónica lo dañan", "c": "i", "x": 63, "y": 6, "ax": 60, "ay": 25}, {"n": "⑧⑨", "t": "Habón", "s": "dermis superficial:<br>dura 1-24 h", "c": "d", "x": 99.5, "y": 6, "ax": 80, "ay": 21, "al": "r"}, {"n": "⑥", "t": "Músculo grueso", "s": "remodelación<br>si no se controla", "c": "i", "x": 0.5, "y": 91, "ax": 33, "ay": 72, "al": "l"}, {"n": "⑤", "t": "Nervio vago", "s": "acetilcolina:<br>contrae el músculo", "c": "i", "x": 37, "y": 91, "ax": 52, "ay": 66}, {"n": "④", "t": "Eosinófilo", "s": "llega a las 3-4 h<br>traído por los Th2", "c": "i", "x": 55, "y": 91, "ax": 63, "ay": 57, "d": "D"}, {"n": "⑩⑪⑫", "t": "Mastocito cutáneo", "s": "H1: capilar, nervio;<br>C5a, IgG", "c": "d", "x": 72, "y": 91, "ax": 84, "ay": 40, "d": "C"}, {"n": "⑬⑭", "t": "Angioedema", "s": "dermis profunda:<br>hasta 72 h", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 66, "d": "B", "al": "r"}], "diapos": [{"img": "img/28.webp", "ratio": 1.5, "titulo": "Bronquio asmático y piel con habón", "texto": "El mismo mastocito cierra el bronquio en minutos y, en la piel, hace el <mark>habón</mark> ⑧ y el angioedema ⑬.", "etiquetas": [{"n": "①", "t": "Normal", "s": "luz amplia,<br>músculo fino", "c": "g", "x": 0.5, "y": 6, "ax": 10, "ay": 40, "al": "l"}, {"n": "②⑦", "t": "Asmático", "s": "luz estrecha,<br>tapón de moco", "c": "i", "x": 27, "y": 6, "ax": 30, "ay": 49}, {"n": "③⑤", "t": "Mastocito bronquial", "s": "histamina, triptasa,<br>leucotrienos", "c": "i", "x": 46, "y": 6, "ax": 52, "ay": 42, "d": "A"}, {"n": "", "t": "Epitelio ciliado", "s": "MBP y proteína<br>catiónica lo dañan", "c": "i", "x": 63, "y": 6, "ax": 60, "ay": 25}, {"n": "⑧⑨", "t": "Habón", "s": "dermis superficial:<br>dura 1-24 h", "c": "d", "x": 99.5, "y": 6, "ax": 80, "ay": 21, "al": "r"}, {"n": "⑥", "t": "Músculo grueso", "s": "remodelación<br>si no se controla", "c": "i", "x": 0.5, "y": 91, "ax": 33, "ay": 72, "al": "l"}, {"n": "⑤", "t": "Nervio vago", "s": "acetilcolina:<br>contrae el músculo", "c": "i", "x": 37, "y": 91, "ax": 52, "ay": 66}, {"n": "④", "t": "Eosinófilo", "s": "llega a las 3-4 h<br>traído por los Th2", "c": "i", "x": 55, "y": 91, "ax": 63, "ay": 57, "d": "D"}, {"n": "⑩⑪⑫", "t": "Mastocito cutáneo", "s": "H1: capilar, nervio;<br>C5a, IgG", "c": "d", "x": 72, "y": 91, "ax": 84, "ay": 40, "d": "C"}, {"n": "⑬⑭", "t": "Angioedema", "s": "dermis profunda:<br>hasta 72 h", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 66, "d": "B", "al": "r"}]}, {"img": "img/28_2.webp", "ratio": 1.5, "titulo": "Asma en el tiempo", "texto": "Minutos: mastocito <span class=\"lt2\">A</span> y vago cierran el bronquio ③⑤; a las <mark>3-4 h</mark> los Th2 traen eosinófilos <span class=\"lt2\">D</span>; <span class=\"cx\">luego</span>, si persiste, <span class=\"res\">remodelación</span> ④, que el corticoide inhalado frena ⑥.", "etiquetas": [{"n": "⑤", "t": "Fibras del vago", "s": "acetilcolina:<br>contrae el músculo", "c": "i", "x": 0.5, "y": 6, "ax": 4, "ay": 37, "al": "l"}, {"n": "③", "t": "Mastocito bronquial", "s": "minutos: histamina,<br>triptasa, leucotrienos", "c": "i", "x": 30, "y": 6, "ax": 10, "ay": 29, "d": "A"}, {"n": "④", "t": "Eosinófilos", "s": "llegan a las 3-4 h<br>traídos por los Th2", "c": "d", "x": 52, "y": 6, "ax": 43, "ay": 37, "d": "D"}, {"n": "④", "t": "Músculo engrosado", "s": "remodelación:<br>la luz no se reabre", "c": "i", "x": 99.5, "y": 6, "ax": 81, "ay": 25, "al": "r"}, {"n": "③⑤", "t": "Fase inmediata", "s": "luz cerrada<br>en minutos", "c": "i", "x": 0.5, "y": 91, "ax": 16, "ay": 48, "al": "l"}, {"n": "④", "t": "Tapón de moco", "s": "fase tardía:<br>moco y células", "c": "d", "x": 30, "y": 91, "ax": 48, "ay": 52}, {"n": "④", "t": "Epitelio herido", "s": "MBP y proteína<br>catiónica: sin cilios", "c": "d", "x": 54, "y": 91, "ax": 57, "ay": 41}, {"n": "④⑥", "t": "Caliciformes y fibrosis", "s": "remodelación: el corticoide<br>inhalado la frena", "c": "g", "x": 99.5, "y": 91, "ax": 85, "ay": 45, "al": "r"}]}, {"img": "img/28_3.webp", "ratio": 1.5, "titulo": "Cómo nace un habón", "texto": "La histamina sobre H1 hace la <mark>triple respuesta</mark> ⑩; el mastocito también se enciende por anti-FcεRI ⑫ <span class=\"lt2\">C</span> o por C3a y C5a ⑪; <span class=\"cx\">en cambio</span>, el angioedema por IECA es <b>bradicinina</b> ⑬.", "etiquetas": [{"n": "⑧", "t": "Habón con eritema", "s": "edema superficial:<br>dura 1-24 h", "c": "d", "x": 0.5, "y": 6, "ax": 15, "ay": 24, "al": "l"}, {"n": "⑩", "t": "Nervio sensitivo", "s": "reflejo axonal:<br>agranda el eritema", "c": "d", "x": 28, "y": 6, "ax": 29, "ay": 39}, {"n": "⑫", "t": "IgG anti-FcεRI", "s": "autoanticuerpo: urticaria<br>crónica autoinmune", "c": "d", "x": 50, "y": 6, "ax": 40, "ay": 31, "d": "C"}, {"n": "", "t": "IgE + alérgeno", "s": "la vía clásica:<br>dos IgE unidas", "c": "g", "x": 72, "y": 6, "ax": 51, "ay": 22}, {"n": "⑩", "t": "Capilar que filtra", "s": "H1: vasodilatación<br>y permeabilidad", "c": "d", "x": 0.5, "y": 91, "ax": 21, "ay": 55, "al": "l"}, {"n": "⑪", "t": "C3a y C5a", "s": "anafilotoxinas:<br>sin anticuerpos", "c": "i", "x": 30, "y": 91, "ax": 60, "ay": 40}, {"n": "⑧⑬", "t": "Angioedema", "s": "dermis inferior y<br>subcutáneo: hasta 72 h", "c": "d", "x": 54, "y": 91, "ax": 80, "ay": 62, "d": "B"}, {"n": "⑬", "t": "Bradicinina", "s": "IECA: edema sin habón,<br>suspender ya", "c": "d", "x": 99.5, "y": 91, "ax": 89, "ay": 58, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = vía aérea</b> (asma y rinitis), <b class=\"d\">rojo = piel</b> (urticaria y angioedema), gris = estructuras de referencia.", "<b>Izquierda:</b> el bronquio asmático tiene la luz estrecha, músculo grueso y moco. La triptasa vive 90-150 min <span class=\"lt2\">A</span> y prende el C3, <span class=\"cx\">por eso</span> la inflamación no se apaga sola.", "<b>Centro:</b> el vago suelta acetilcolina sobre el músculo; los eosinófilos dañan cilios con proteína catiónica y MBP. Los <mark>corticoides inhalados</mark> frenan esa red; el salbutamol solo rescata.", "<b>Derecha:</b> el habón es superficial y dura 1-24 h; el angioedema es profundo y dura hasta 72 h <span class=\"lt2\">B</span>. Más de seis semanas = urticaria crónica <span class=\"lt2\">C</span>."], "recordar": "Bronquio: mastocito en minutos → Th2 y eosinófilo a las 3-4 h → remodelación. Piel: histamina H1 → <mark>eritema, habón y reflejo axonal</mark>."}, "numeros": [{"l": "A", "html": "<b>Triptasa</b>: vida media <b class=\"a\">90-150 min</b>, mucho mayor que la histamina. Asma: <b class=\"n\">10 %</b> de la población; rinitis alérgica <b class=\"a\">30-60 %</b>.", "rango": null}, {"l": "B", "html": "<b>Habón</b>: dura <b class=\"n\">1-24 h</b>; <b>angioedema</b>: hasta <b class=\"a\">72 h</b>, en 40-50 % de las urticarias crónicas.", "rango": {"min": 0, "max": 72, "unidad": "h", "zonas": [[0, 24, "n", "habón"], [24, 72, "a", "angioedema"]], "marcas": [24]}}, {"l": "C", "html": "<b>Crónica</b>: más de <b class=\"a\">6 semanas</b>. Autoanticuerpos IgG anti-FcεRI <b class=\"a\">30 %</b>, anti-IgE <b class=\"n\">10 %</b>.", "rango": {"min": 0, "max": 12, "unidad": "semanas", "zonas": [[0, 6, "m", "aguda"], [6, 12, "a", "crónica"]], "marcas": [6]}}, {"l": "D", "html": "<b>Fase tardía</b>: a las <b class=\"a\">3-4 h</b>; los Th2 secretan IL-3, IL-4, IL-5 e IL-13. Salbutamol: inicio en <b class=\"n\">menos de 5 min</b>, dura <b class=\"n\">4-5 h</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del mastocito al bronquio y a la piel", "subtitulo": "estímulo → mastocito → mediadores → órgano → qué pasa si persiste", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> alérgeno inhalado sobre IgE (asma, rinitis), o en la piel IgE, <mark>anafilotoxinas C3a-C5a</mark>, autoanticuerpos, trombina o estímulos físicos.", "pr": "el mastocito se activa por varias puertas.", "pr_tit": "Produce:", "rf": "Preguntas ②⑪⑫⑬", "color": "p1"}, {"t": "2. Fase inmediata", "m": "<b>Por qué:</b> el mastocito libera <mark>histamina, triptasa</mark>, PGD2 y leucotrienos C4-D4-E4; el vago suma acetilcolina.", "pr": "broncoespasmo, edema y moco en minutos.", "pr_tit": "Produce:", "rf": "Preguntas ③⑤ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Fase tardía", "m": "<b>Qué produce:</b> a las 3-4 h los <mark>Th2</mark> (IL-4, IL-5, IL-13) mantienen la IgE y traen eosinófilos, que liberan proteína catiónica y MBP.", "pr": "daño de cilios, hipersecreción de mucina.", "pr_tit": "Produce:", "rf": "Pregunta ④ · punto <span class=\"lt2\">D</span>", "color": "p3"}, {"t": "4. En la piel", "m": "<b>Qué pasa:</b> la histamina actúa sobre H1 del endotelio y de los nervios: <mark>triple respuesta</mark>. Edema superficial = habón; profundo = angioedema.", "pr": "habón de 1-24 h o angioedema de hasta 72 h.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨⑩ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Si persiste", "m": "<b>Asma:</b> remodelación (fibrosis, pólipos, cornetes). <b>Urticaria crónica:</b> autoinmune, tiroides. Se trata con <mark>corticoide inhalado</mark>, inmunoterapia, antihistamínico escalonado u omalizumab.", "pr": "obstrucción crónica o habones por años.", "pr_tit": "Produce:", "rf": "Preguntas ①⑥⑦⑭ · punto <span class=\"lt2\">C</span>", "color": "p4"}], "extra": [{"html": "🫁 <b>Fármacos del asma:</b> corticoide inhalado = base; salbutamol = rescate (menos de 5 min, 4-5 h); LABA + corticoide en moderada-severa; montelukast adyuvante; antihistamínico solo en rinitis; omalizumab en asma alérgica severa.", "k": ""}, {"html": "⚠️ <b>Urgencias:</b> la anafilaxia trae urticaria en 80-90 % de los casos. Ante habones agudos, busca disnea, hipotensión, diarrea o vómito. Y el angioedema por <b>IECA</b> es por bradicinina: suspender ya.", "k": "k"}], "escaleras": [{"c": "i", "t": "🫁 Control del asma (GINA)", "pasos": ["controlada: menos de 2 episodios/semana", "sin síntomas nocturnos", "parcial: 1-2 criterios", "no controlada: 3 o más", "o exacerbación en el último mes"]}, {"c": "d", "t": "🩹 Escalera de la urticaria crónica", "pasos": ["antihistamínico 2.ª generación", "hasta 4 veces la dosis a las 2 semanas", "<b>omalizumab</b> o ciclosporina", "corticoide solo en cursos cortos"]}], "html": "", "fuente": "Fuente: tu teoría — clase 35 (definición, GINA, genética, fases inmediata y tardía, mediadores, tratamiento) y clase 36 (habón, angioedema, vías del mastocito, autoinmunidad, IECA, escalera terapéutica)."}, "preguntas": [{"n": 1, "id": "IN16-001", "c": "i", "tema": "Definición y clasificación", "pregunta": "Según GINA, ¿qué criterios cumple un asma «controlada»?", "opciones": ["a. Síntomas diurnos más de 2 veces por semana y función pulmonar menor de 80 %", "b. Síntomas nocturnos ocasionales con limitación leve de actividades", "c. Síntomas diurnos menos de 2 episodios leves por semana, sin síntomas nocturnos, sin limitación de actividades y función pulmonar normal", "d. Una exacerbación moderada en el último mes", "e. Tres o más criterios de asma parcialmente controlada"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Menos de 2 episodios diurnos leves por semana, sin síntomas nocturnos, sin limitación y con función pulmonar normal.", "sin_banco": true, "ok": "", "x": "GINA clasifica el asma por <mark>nivel de control</mark>, no por gravedad. Basta un criterio (síntomas nocturnos, limitación o función menor de 80 %) para que sea <b>parcialmente controlada</b>, y tres o una exacerbación en el último mes la hacen <span class=\"res\">no controlada</span>.", "truco": "Controlada = de noche duerme, de día juega, el pulmón sopla normal.", "veces": 0}, {"n": 2, "id": "IN16-002", "c": "i", "tema": "Epidemiología y genética", "pregunta": "¿Por qué el gen ORMDL3 (locus 17q21) ilustra la complejidad genética del asma?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Sus alelos se asocian a hiperreactividad bronquial y más IgE en la infancia, pero actúan como protectores en la edad adulta.", "sin_banco": true, "ok": "", "x": "El asma es <mark>multifactorial</mark>: muchos genes (DENND1B, IL4, ADAM33, filagrina) y muchos estímulos. El ORMDL3 muestra que un mismo alelo puede ser <b>riesgo en el niño y protección en el adulto</b>. <span class=\"cx\">Además</span>, el humo del cigarrillo promueve activamente Th2. <span class=\"res\">Mismo gen, efecto según la edad.</span>", "truco": "ORMDL3: malo de niño, bueno de grande.", "veces": 0}, {"n": 3, "id": "IN16-003", "c": "i", "tema": "Inmunopatología", "pregunta": "En la fase inmediata del asma alérgica, sobre la triptasa es correcto:", "opciones": ["a. Tiene una vida media menor que la histamina", "b. Activa la vía del complemento y su vida media es de 90 a 150 minutos", "c. Es producida por los eosinófilos en la fase tardía", "d. Es broncodilatadora", "e. Solo se libera en la fase crónica"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Activa el complemento (C3) y vive 90-150 minutos, mucho más que la histamina.", "sin_banco": true, "ok": "", "x": "Punto Ⓐ: la <mark>triptasa</mark> sale junto con la histamina del mastocito bronquial, pero vive 90-150 min y activa el C3. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN16-004", "c": "i", "tema": "Inmunopatología", "pregunta": "¿Cuándo aparece la fase tardía del asma, qué células la protagonizan y a qué lleva si se perpetúa?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "A las 3-4 horas; la dominan los linfocitos Th2 (IL-3, IL-4, IL-5, IL-13) con eosinófilos; si persiste lleva a remodelación: fibrosis, pólipos nasales y crecimiento de cornetes.", "sin_banco": true, "ok": "", "x": "Los eosinófilos del centro de la imagen (punto Ⓓ) llegan a las <mark>3-4 h</mark> traídos por los Th2; en el bronquio asmático se ven junto al músculo grueso y el moco. Si sigue, <span class=\"res\">remodelación</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN16-005", "c": "i", "tema": "Células y mediadores", "pregunta": "Sobre los mediadores en el asma, señale lo FALSO:", "opciones": ["a. La PGD2 produce broncoconstricción e hipersecreción de moco", "b. Los leucotrienos C4, D4 y E4 causan broncoconstricción", "c. El leucotrieno B4 es quimiotáctico de neutrófilos", "d. El vago libera acetilcolina que contrae el músculo liso", "e. La PGE2 es un potente broncoconstrictor"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es FALSO: la PGE2 es broncodilatadora, al contrario que la PGD2.", "sin_banco": true, "ok": "", "x": "La <mark>PGD2</mark> cierra el bronquio, <span class=\"cx\">en cambio</span> la <b>PGE2</b> lo abre. Los leucotrienos C4-D4-E4 contraen en la fase tardía y el B4 atrae neutrófilos; el vago suma acetilcolina y las fibras no adrenérgicas, sustancia P. <span class=\"res\">D de «Daño», E de «Expande».</span>", "truco": "PGD2 Daña, PGE2 Expande.", "veces": 0}, {"n": 6, "id": "IN16-006", "c": "i", "tema": "Tratamiento", "pregunta": "¿Cuál es el fármaco de primera línea en el asma de cualquier severidad?", "opciones": ["a. Corticosteroides inhalados", "b. Antihistamínicos H1", "c. Montelukast", "d. Teofilina", "e. Salbutamol en monoterapia continua"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Los corticosteroides inhalados, que inhiben la transcripción de IL-1 a IL-6, IL-13, GM-CSF, TNF-α y moléculas de adherencia.", "sin_banco": true, "ok": "", "x": "El asma es inflamación crónica, <span class=\"cx\">por eso</span> la base es el <mark>corticoide</mark>: frena a nivel genómico las citoquinas. El salbutamol es <b>rescate</b> (empieza en menos de 5 min y dura 4-5 h) y los antihistamínicos sirven en la rinitis, <span class=\"res\">no en el asma</span>.", "truco": "En asma: el corticoide controla, el salbutamol rescata.", "veces": 0}, {"n": 7, "id": "IN16-007", "c": "i", "tema": "Inmunomodulación", "pregunta": "¿En qué se diferencia la inmunoterapia de los fármacos en el asma y la rinitis alérgica, y para qué sirve el omalizumab?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La inmunoterapia induce tolerancia al alérgeno y modifica la historia natural (efecto que persiste al suspenderla); los fármacos solo controlan síntomas. El omalizumab es anti-IgE: bloquea la IgE libre e impide su unión al FcεRI, en asma alérgica severa resistente a corticoides inhalados.", "sin_banco": true, "ok": "", "x": "La <mark>inmunoterapia</mark> (subcutánea o sublingual) es la única que cambia el curso: reduce síntomas y previene nuevas sensibilizaciones; conviene empezarla temprano, antes de la remodelación. El <b>omalizumab</b> atrapa la IgE libre antes de que arme al mastocito. <span class=\"res\">Tolerancia vs control.</span>", "truco": "Fármaco apaga el fuego; inmunoterapia quita la leña.", "veces": 0}, {"n": 8, "id": "IN16-008", "c": "d", "tema": "Generalidades", "pregunta": "Respecto al habón y al angioedema, es correcto:", "opciones": ["a. El habón afecta el tejido subcutáneo y dura hasta 72 horas", "b. El angioedema es siempre más pruriginoso que doloroso", "c. El habón se resuelve en 1-24 horas; el angioedema afecta dermis inferior y subcutáneo y tarda hasta 72 horas", "d. El angioedema nunca afecta mucosas", "e. Ambos dejan cicatriz"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. El habón es efímero (1-24 h); el angioedema afecta dermis inferior y tejido subcutáneo, compromete mucosas y tarda hasta 72 h.", "sin_banco": true, "ok": "", "x": "A la derecha de la imagen el <mark>habón</mark> está arriba, en la dermis superficial, y el <b>angioedema</b> abajo, en dermis inferior y subcutáneo (punto Ⓑ). <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN16-009", "c": "d", "tema": "Generalidades", "pregunta": "¿Qué umbral de tiempo separa la urticaria aguda de la crónica?", "opciones": ["a. 72 horas", "b. 2 semanas", "c. 1 mes", "d. 6 semanas", "e. 6 meses"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Seis semanas de habones diarios o casi diarios.", "sin_banco": true, "ok": "", "x": "Si los habones aparecen casi a diario por <mark>más de seis semanas</mark> la urticaria es crónica. La aguda suele ser <b>infecciosa</b> (37 % en adultos, 57 % en niños); la crónica espontánea es a menudo <span class=\"res\">autoinmune</span>.", "truco": "Más de seis semanas: de visita pasa a inquilino.", "veces": 0}, {"n": 10, "id": "IN16-010", "c": "d", "tema": "Inmunopatología", "pregunta": "¿Qué es la triple respuesta de la histamina en la piel y qué receptores la median?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Vasodilatación (eritema), aumento de la permeabilidad capilar (edema = habón) y reflejo axonal que amplía el eritema; la median receptores H1 de células endoteliales y de nervios sensitivos.", "sin_banco": true, "ok": "", "x": "En la piel de la imagen el mastocito suelta histamina junto al <mark>capilar dilatado</mark> (eritema y edema) y al <b>nervio sensitivo</b> (reflejo axonal y prurito).", "truco": "", "veces": 0}, {"n": 11, "id": "IN16-011", "c": "d", "tema": "Inmunopatología", "pregunta": "Las anafilotoxinas pueden causar urticaria porque:", "opciones": ["a. Neutralizan la histamina", "b. Bloquean el FcεRI", "c. Requieren IgE para actuar", "d. C3a, C4a y C5a activan directamente mastocitos y basófilos, sin anticuerpos", "e. Inhiben la quimiotaxis de eosinófilos"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. C3a, C4a y C5a se unen directamente a mastocitos y basófilos y liberan histamina sin anticuerpos.", "sin_banco": true, "ok": "", "x": "La segunda vía inmune de la urticaria es el <mark>complemento</mark>: las anafilotoxinas degranulan al mastocito <b>sin IgE</b>. <span class=\"cx\">Además</span>, el C5a atrae neutrófilos, eosinófilos y mononucleares, y el C3a atrae <span class=\"res\">selectivamente eosinófilos</span>.", "truco": "Anafilotoxina: degranula sin pedir permiso a la IgE.", "veces": 0}, {"n": 12, "id": "IN16-012", "c": "d", "tema": "Autoinmunidad y coagulación", "pregunta": "Mujer de 45 años con habones casi diarios desde hace 5 meses, sin desencadenante; tiene tiroiditis autoinmune y la prueba de suero autólogo es positiva. ¿Cuál es el mecanismo más probable?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Urticaria crónica espontánea autoinmune: autoanticuerpos IgG contra el FcεRI (30 %) o contra la IgE (10 %) que activan directamente mastocitos y basófilos.", "sin_banco": true, "ok": "", "x": "El 30-40 % de la urticaria crónica espontánea es <mark>autoinmune</mark>; predomina en mujeres de 35-60 años y se asocia a enfermedad tiroidea. La prueba de suero autólogo detecta esos autoanticuerpos funcionales. <span class=\"cx\">Además</span>, el factor tisular del <b>eosinófilo</b> genera trombina que también degranula. <span class=\"res\">IgG anti-FcεRI 30 %, anti-IgE 10 %.</span>", "truco": "Treinta contra el receptor, diez contra la IgE.", "veces": 0}, {"n": 13, "id": "IN16-013", "c": "d", "tema": "Etiología", "pregunta": "Paciente hipertenso que inicia enalapril presenta edema de labios y lengua sin habones. ¿Cuál es el mecanismo y la conducta?", "opciones": ["a. IgE contra el fármaco; dar antihistamínico y continuar", "b. Incremento local de bradicinina; suspender el IECA de inmediato", "c. Anafilotoxinas; añadir corticoide", "d. Autoanticuerpos anti-FcεRI; dar omalizumab", "e. Dermografismo; observar"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Los IECA aumentan la bradicinina local; hay que suspender el fármaco de inmediato por riesgo de edema de vía aérea.", "sin_banco": true, "ok": "", "x": "Los <mark>IECA</mark> no son alérgicos: impiden degradar la <b>bradicinina</b>, que causa angioedema sin habones. <span class=\"cx\">Por eso</span> los antihistamínicos no sirven y el edema de vía aérea puede matar. <span class=\"res\">IECA + angioedema = suspender ya.</span>", "truco": "IECA: la bradicinina se acumula, la lengua se hincha.", "veces": 0}, {"n": 14, "id": "IN16-014", "c": "d", "tema": "Tratamiento", "pregunta": "En la urticaria crónica espontánea que no mejora tras 2 semanas con antihistamínico de segunda generación a dosis convencional, el siguiente paso es:", "opciones": ["a. Antihistamínico de primera generación", "b. Corticoide oral por tiempo prolongado", "c. Omalizumab de entrada", "d. Suspender todo tratamiento", "e. Aumentar el antihistamínico de segunda generación hasta cuatro veces la dosis"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Aumentar el antihistamínico de segunda generación hasta cuatro veces la dosis recomendada.", "sin_banco": true, "ok": "", "x": "Es la escalera roja de la página 2: tras 2 semanas sin respuesta se sube el <mark>antihistamínico de 2.ª generación hasta 4 veces</mark>; recién después, omalizumab o ciclosporina. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "Asma", "Rinitis", "Urticaria", "Angioedema"], "filas": [["Dónde", "bronquio", "mucosa nasal", "dermis superficial", "dermis inferior"], ["Mediador", "histamina, leucotrienos", "histamina", "histamina H1", "histamina o bradicinina"], ["Duración", "crisis y fase tardía", "intermitente o persistente", "1-24 h", "hasta 72 h"], ["Base del tratamiento", "corticoide inhalado", "antihistamínico", "antihistamínico 2.ª gen.", "suspender IECA si aplica"], ["🔑 Para diferenciar", "sibilancias", "rinorrea", "pica y se va", "duele y dura"]]}, "fuente": "Fuente: tu teoría — clase 35 (Asma y rinitis alérgica) y clase 36 (Urticaria), Rojas 17.ª ed."}, {"n": 29, "slug": "Dermatitis_atopica_y_alergia_alimentaria", "titulo": "Dermatitis atópica y alergia alimentaria", "subtitulo": "barreras rotas y tolerancia perdida: piel e intestino", "grupo": "g16", "lema": "La idea: en la dermatitis atópica la piel pierde su cemento —la <mark>filagrina</mark>— y se seca; por las grietas entran alérgenos y <b>S. aureus</b>, el queratinocito herido produce <b>TSLP</b> y la célula dendrítica enseña al linfocito a ser Th2. Las citoquinas Th2 bajan aún más la filagrina: <u>círculo vicioso</u> que el rascado cierra. En el intestino pasa algo parecido: lo normal es la <b>tolerancia oral</b> (Treg, IL-10, TGF-β); si se rompe, aparece IgE contra el alimento. Ambas abren la <b>marcha atópica</b>. En la imagen verás de izquierda a derecha: la epidermis sana frente a la atópica, la dermis con la célula dendrítica y el Th2, y una vellosidad intestinal con un Treg y un mastocito.", "img": "img/29.webp", "mini": "img/mini/29.webp", "ratio": 1.5, "etiquetas": [{"n": "②", "t": "Piel sana", "s": "capa granulosa:<br>filagrina", "c": "i", "x": 0.5, "y": 6, "ax": 8, "ay": 40, "al": "l"}, {"n": "⑤", "t": "S. aureus", "s": "entra por grietas;<br>empuja a Th1", "c": "d", "x": 20, "y": 6, "ax": 21, "ay": 25}, {"n": "①②", "t": "Agua que se pierde", "s": "xerosis:<br>barrera rota", "c": "d", "x": 39, "y": 6, "ax": 28, "ay": 19, "d": "A"}, {"n": "④⑦", "t": "Rascado", "s": "daña al queratinocito:<br>sale TSLP", "c": "d", "x": 69, "y": 6, "ax": 57, "ay": 18, "d": "D"}, {"n": "⑧⑨", "t": "Maní y huevo", "s": "proteína intacta:<br>mucosa inmadura", "c": "d", "x": 99.5, "y": 6, "ax": 81, "ay": 22, "d": "C", "al": "r"}, {"n": "③⑥", "t": "Piel atópica", "s": "IgE alta, Th2:<br>marcha atópica", "c": "d", "x": 0.5, "y": 91, "ax": 27, "ay": 45, "d": "B", "al": "l"}, {"n": "⑤", "t": "Eosinófilos", "s": "IL-5; la IL-17<br>los aumenta", "c": "d", "x": 26, "y": 91, "ax": 40, "ay": 72}, {"n": "④", "t": "Célula dendrítica", "s": "la TSLP la orienta<br>hacia Th2", "c": "i", "x": 45, "y": 91, "ax": 45, "ay": 55}, {"n": "⑩⑪", "t": "Treg", "s": "tolerancia oral:<br>IL-10, TGF-β", "c": "i", "x": 67, "y": 91, "ax": 78, "ay": 68}, {"n": "⑫⑬⑭", "t": "Mastocito con IgE", "s": "tolerancia perdida:<br>SAO, anafilaxia", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 64, "al": "r"}], "diapos": [{"img": "img/29.webp", "ratio": 1.5, "titulo": "Barrera rota en piel e intestino", "texto": "Sin <mark>filagrina</mark> la piel se seca y deja entrar alérgenos ②; en el intestino, si se pierde la tolerancia oral aparece IgE contra el alimento ⑩.", "etiquetas": [{"n": "②", "t": "Piel sana", "s": "capa granulosa:<br>filagrina", "c": "i", "x": 0.5, "y": 6, "ax": 8, "ay": 40, "al": "l"}, {"n": "⑤", "t": "S. aureus", "s": "entra por grietas;<br>empuja a Th1", "c": "d", "x": 20, "y": 6, "ax": 21, "ay": 25}, {"n": "①②", "t": "Agua que se pierde", "s": "xerosis:<br>barrera rota", "c": "d", "x": 39, "y": 6, "ax": 28, "ay": 19, "d": "A"}, {"n": "④⑦", "t": "Rascado", "s": "daña al queratinocito:<br>sale TSLP", "c": "d", "x": 69, "y": 6, "ax": 57, "ay": 18, "d": "D"}, {"n": "⑧⑨", "t": "Maní y huevo", "s": "proteína intacta:<br>mucosa inmadura", "c": "d", "x": 99.5, "y": 6, "ax": 81, "ay": 22, "d": "C", "al": "r"}, {"n": "③⑥", "t": "Piel atópica", "s": "IgE alta, Th2:<br>marcha atópica", "c": "d", "x": 0.5, "y": 91, "ax": 27, "ay": 45, "d": "B", "al": "l"}, {"n": "⑤", "t": "Eosinófilos", "s": "IL-5; la IL-17<br>los aumenta", "c": "d", "x": 26, "y": 91, "ax": 40, "ay": 72}, {"n": "④", "t": "Célula dendrítica", "s": "la TSLP la orienta<br>hacia Th2", "c": "i", "x": 45, "y": 91, "ax": 45, "ay": 55}, {"n": "⑩⑪", "t": "Treg", "s": "tolerancia oral:<br>IL-10, TGF-β", "c": "i", "x": 67, "y": 91, "ax": 78, "ay": 68}, {"n": "⑫⑬⑭", "t": "Mastocito con IgE", "s": "tolerancia perdida:<br>SAO, anafilaxia", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 64, "al": "r"}]}, {"img": "img/29_2.webp", "ratio": 1.5, "titulo": "Filagrina: el cemento de la piel", "texto": "La filagrina retiene agua y <mark>pH ácido</mark> ②; sin ella entran alérgenos y <b>S. aureus</b> ⑤, y el queratinocito herido libera TSLP ④.", "etiquetas": [{"n": "②", "t": "Filagrina", "s": "gránulos de la<br>capa granulosa", "c": "i", "x": 0.5, "y": 6, "ax": 21.5, "ay": 43, "al": "l"}, {"n": "②", "t": "Agua retenida", "s": "humectantes naturales<br>y pH ácido", "c": "i", "x": 25, "y": 6, "ax": 24.7, "ay": 37.6}, {"n": "", "t": "Ácaro y polen", "s": "alérgenos que entran<br>por las grietas", "c": "d", "x": 48, "y": 6, "ax": 65, "ay": 22}, {"n": "⑤", "t": "S. aureus", "s": "coloniza y amplifica<br>la inflamación", "c": "d", "x": 68, "y": 6, "ax": 84, "ay": 28}, {"n": "①②", "t": "Agua que se escapa", "s": "sin filagrina:<br>xerosis", "c": "d", "x": 99.5, "y": 6, "ax": 92.5, "ay": 22, "d": "A", "al": "r"}, {"n": "", "t": "Dendrítica en reposo", "s": "piel sana:<br>sin señal de alarma", "c": "g", "x": 0.5, "y": 91, "ax": 17.6, "ay": 70, "al": "l"}, {"n": "④", "t": "TSLP", "s": "la suelta el<br>queratinocito herido", "c": "d", "x": 40, "y": 91, "ax": 68, "ay": 55}, {"n": "④", "t": "Dendrítica activada", "s": "lleva el alérgeno<br>y orienta a Th2", "c": "i", "x": 59, "y": 91, "ax": 74, "ay": 63.5}, {"n": "③⑤", "t": "Linfocito Th2", "s": "IL-4, IL-13:<br>bajan la filagrina", "c": "i", "x": 78, "y": 91, "ax": 82, "ay": 67}, {"n": "⑤", "t": "Eosinófilos", "s": "IL-5:<br>inflamación", "c": "d", "x": 99.5, "y": 91, "ax": 91.5, "ay": 64, "al": "r"}]}, {"img": "img/29_3.webp", "ratio": 1.5, "titulo": "Tolerancia oral frente a alergia", "texto": "Lo normal es <mark>tolerar</mark> con Treg e IgA ⑩; <span class=\"cx\">cuando</span> se pierde, el mastocito con IgE reacciona al alimento ⑨ <span class=\"lt2\">C</span>, y el polen cruza con la fruta: SAO ⑫.", "etiquetas": [{"n": "⑩", "t": "IgA secretora", "s": "neutraliza<br>en la luz", "c": "i", "x": 0.5, "y": 6, "ax": 10.4, "ay": 29, "al": "l"}, {"n": "⑩", "t": "Dendrítica tolerogénica", "s": "presenta el antígeno<br>sin alarma", "c": "i", "x": 28, "y": 6, "ax": 13, "ay": 46}, {"n": "⑨", "t": "Maní, huevo, leche", "s": "entre los 8 alimentos<br>más alergénicos", "c": "d", "x": 50, "y": 6, "ax": 40, "ay": 24, "d": "C"}, {"n": "⑫", "t": "Polen de abedul", "s": "proteína parecida<br>a la de la fruta", "c": "d", "x": 70, "y": 6, "ax": 78, "ay": 41}, {"n": "⑫", "t": "Reactividad cruzada", "s": "misma forma: la IgE<br>no las distingue", "c": "d", "x": 99.5, "y": 6, "ax": 94, "ay": 28, "al": "r"}, {"n": "⑩", "t": "Treg", "s": "IL-10, TGF-β:<br>tolerancia oral", "c": "i", "x": 0.5, "y": 91, "ax": 21.5, "ay": 62.5, "al": "l"}, {"n": "⑨", "t": "Mastocito con IgE", "s": "tolerancia perdida:<br>degranulación", "c": "d", "x": 36, "y": 91, "ax": 49.5, "ay": 62.5}, {"n": "", "t": "Histamina", "s": "minutos después<br>de comer", "c": "d", "x": 58, "y": 91, "ax": 58.6, "ay": 68}, {"n": "⑫", "t": "Síndrome de alergia oral", "s": "labio y paladar<br>edematosos al morder", "c": "d", "x": 99.5, "y": 91, "ax": 85, "ay": 62, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = barrera y tolerancia</b> (lo que protege), <b class=\"d\">rojo = lo que daña</b> (alérgeno, bacteria, Th2, mastocito), gris = estructuras de referencia.", "<b>Izquierda:</b> la filagrina sale de los gránulos de queratohialina de la capa granulosa; da factores humectantes y pH ácido. Sin ella se pierde agua: <mark>xerosis</mark> <span class=\"lt2\">A</span>.", "<b>Centro:</b> TSLP por daño mecánico o PAR-2 → célula dendrítica → Th2 al inicio; <span class=\"cx\">luego</span> Th1 y, en lo crónico, Th2/T22. El prurito está en <b>todas</b> las fases.", "<b>Derecha:</b> el intestino del niño es inmaduro y deja pasar proteínas intactas <span class=\"lt2\">C</span>. El Treg (dosis baja) o la anergia (dosis alta) mantienen la tolerancia; si fallan, IgE y mastocito."], "recordar": "Piel: <mark>filagrina rota → TSLP → Th2 → menos filagrina</mark> (círculo). Intestino: tolerancia oral → si se rompe, Th2 e IgE. Ambas: marcha atópica."}, "numeros": [{"l": "A", "html": "<b>Dermatitis atópica</b>: al menos <b class=\"a\">15 %</b> de los niños, <b class=\"n\">2-10 %</b> de los adultos; <b class=\"a\">70 %</b> con familia atópica.", "rango": null}, {"l": "B", "html": "<b>Pronóstico</b>: <b class=\"a\">50-80 %</b> hará asma o rinitis; <b class=\"n\">75-84 %</b> cura tras la adolescencia; solo <b class=\"b\">2-5 %</b> sigue de adulto.", "rango": null}, {"l": "C", "html": "<b>Alergia alimentaria</b>: niños <b class=\"a\">8 %</b>, adultos <b class=\"n\">2 %</b>; unos <b class=\"n\">170</b> alimentos; causa <b class=\"a\">15-57 %</b> de las anafilaxias.", "rango": null}, {"l": "D", "html": "<b>Prurito</b>: en <b class=\"a\">todos</b> los pacientes (alloknesis); la IL-31 media el prurito inmunológico. Hanifin y Rajka: <b class=\"n\">3 de 4</b> mayores + al menos <b class=\"n\">3</b> menores; IgE alta en <b class=\"a\">80 %</b>, pero no es específica.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la barrera rota a la marcha atópica", "subtitulo": "estímulo → barrera → células → mecanismo → qué pasa si sigue", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> niño con familia atópica y <mark>mutación de filagrina</mark>, o con mucosa intestinal inmadura, recibe alérgenos (ácaro, huevo, leche, maní).", "pr": "la proteína pasa la barrera.", "pr_tit": "Produce:", "rf": "Preguntas ①⑧⑨ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">C</span>", "color": "p1"}, {"t": "2. Barrera rota", "m": "<b>Por qué:</b> sin filagrina, menos ceramidas y más proteasas, la piel pierde agua (<mark>xerosis</mark>) y deja entrar alérgenos, bacterias y virus.", "pr": "queratinocito dañado y prurito.", "pr_tit": "Produce:", "rf": "Pregunta ②", "color": "p2"}, {"t": "3. TSLP y Th2", "m": "<b>Qué produce:</b> el queratinocito suelta <mark>TSLP</mark>; la célula dendrítica polariza a Th2 (IL-4, IL-5, IL-13), que baja la filagrina; S. aureus empuja a Th1 y <span class=\"cx\">luego</span> domina Th2/T22.", "pr": "círculo vicioso barrera-inflamación.", "pr_tit": "Produce:", "rf": "Preguntas ③④⑤", "color": "p3"}, {"t": "4. Tolerancia perdida", "m": "<b>En el intestino:</b> normalmente <mark>Treg, IL-10 y TGF-β</mark> mantienen la tolerancia oral. Si fallan, desviación Th2, IgE y mastocito armado.", "pr": "urticaria, síndrome de alergia oral, anafilaxia.", "pr_tit": "Produce:", "rf": "Preguntas ⑩⑪⑫", "color": "p4"}, {"t": "5. Si sigue", "m": "<b>Marcha atópica:</b> dermatitis en el lactante → alergia alimentaria → <mark>asma y rinitis</mark>. Se trata con barrera (humectantes), corticoide tópico o tacrolimus y evitación del alimento.", "pr": "50-80 % hará asma o rinitis.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑦⑬⑭ · puntos <span class=\"lt2\">B</span><span class=\"lt2\">D</span>", "color": "p4"}], "extra": [{"html": "🧴 <b>Tratamiento de la DA:</b> baño tibio de 10 min + <mark>humectante inmediato</mark>; corticoide de baja potencia en cara y pliegues, alta potencia solo 1-2 semanas; tacrolimus o pimecrolimus sin atrofia; hipoclorito diluido si S. aureus recurrente; antibiótico 7 días solo si hay infección.", "k": ""}, {"html": "🥜 <b>Alergia alimentaria:</b> sensibilización no es alergia; el estándar de oro es la <mark>OFC doble ciega con placebo</mark>. En el maní, Ara h2 predice reactividad y solo Ara h8 da buen pronóstico. Nunca probar el alimento por cuenta propia.", "k": "k"}], "escaleras": [{"c": "d", "t": "🚶 Marcha atópica", "pasos": ["dermatitis atópica (lactante)", "alergia alimentaria", "rinitis alérgica", "<b>asma</b>"]}, {"c": "i", "t": "🍽️ Mecanismos de la alergia alimentaria", "pasos": ["IgE: urticaria, anafilaxia, SAO", "mixto: esofagitis eosinofílica, DA", "no IgE: enterocolitis, proctocolitis, celíaca", "celular: dermatitis de contacto"]}], "html": "", "fuente": "Fuente: tu teoría — clase 37 (filagrina, TSLP, Th1/Th2/T22, clínica, Hanifin y Rajka, tratamiento) y clase 38 (definición, tolerancia oral, mecanismos, OFC, componentes, tratamiento)."}, "preguntas": [{"n": 1, "id": "IN16-015", "c": "i", "tema": "Epidemiología y factores de riesgo", "pregunta": "¿Cuáles son los dos factores de riesgo con mayor respaldo en la dermatitis atópica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La historia personal o familiar de atopia y la mutación con pérdida de función del gen de la filagrina (FLG, cromosoma 1q21).", "sin_banco": true, "ok": "", "x": "El <mark>70 %</mark> de los pacientes tiene familiares atópicos, y la mutación de <b>filagrina</b> da inicio más temprano y formas más graves y persistentes. La DA afecta al menos al 15 % de los niños; endotoxinas, guarderías y perros protegen, <span class=\"cx\">en cambio</span> los antibióticos tempranos aumentan el riesgo. <span class=\"res\">Atopia familiar + filagrina.</span>", "truco": "Familia atópica y filagrina rota.", "veces": 0}, {"n": 2, "id": "IN16-016", "c": "i", "tema": "Función de barrera", "pregunta": "Sobre la filagrina, señale lo correcto:", "opciones": ["a. Es producida por los linfocitos Th2", "b. La IL-4 y la IL-13 aumentan su expresión", "c. Su pérdida reduce la pérdida de agua transepidérmica", "d. Se agrega a la queratina formando una matriz densa y sus monómeros generan factores humectantes que mantienen la hidratación y el pH ácido", "e. Se localiza en la capa basal de la epidermis"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Se agrega al citoesqueleto de queratina y sus monómeros dan factores humectantes naturales que mantienen hidratación y pH ácido.", "sin_banco": true, "ok": "", "x": "A la izquierda de la imagen: la mitad sana tiene la <mark>capa granulosa llena de gránulos</mark> de queratohialina, de donde sale la filagrina; la atópica casi no tiene y pierde agua (punto Ⓐ). <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN16-017", "c": "d", "tema": "Inmunopatología", "pregunta": "¿Qué diferencia la dermatitis atópica extrínseca de la intrínseca?", "opciones": ["a. La extrínseca tiene IgE normal y perfil Th1", "b. La intrínseca tiene mutación de filagrina", "c. La extrínseca tiene IgE elevada, IgE específica, filagrina mutada y perfil Th2; la intrínseca, IgE normal, sin filagrina mutada y alto IFN-γ", "d. No hay diferencias inmunológicas", "e. La intrínseca siempre se asocia a alergia alimentaria"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Extrínseca: IgE alta y específica, filagrina mutada, Th2. Intrínseca: IgE normal, sin mutación, IFN-γ alto (Th1).", "sin_banco": true, "ok": "", "x": "En la <mark>extrínseca</mark> hay IgE contra alérgenos ambientales y alimentarios, barrera rota y <b>Th2</b> (IL-4, IL-5, IL-13). En la intrínseca no hay IgE específica y predomina el <b>IFN-γ</b>. <span class=\"res\">Extrínseca = alérgeno de afuera.</span>", "truco": "EXtrínseca = EXterior: alérgeno, IgE y filagrina rota.", "veces": 0}, {"n": 4, "id": "IN16-018", "c": "d", "tema": "Inmunopatología", "pregunta": "¿Qué es la TSLP y cuál es su papel en la dermatitis atópica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La linfopoyetina estromal del timo: se expresa en la epidermis lesionada, inducida por daño mecánico y activación de PAR-2; polariza a las células dendríticas hacia Th2 e induce infiltración eosinofílica.", "sin_banco": true, "ok": "", "x": "Es la escena del centro: el queratinocito herido por el rascado suelta <mark>TSLP</mark>, y la célula dendrítica que ves con el alérgeno enseña al linfocito a ser <span class=\"res\">Th2</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN16-019", "c": "d", "tema": "Subpoblaciones de linfocitos T", "pregunta": "Explica la respuesta bifásica de linfocitos T en la dermatitis atópica y el papel de S. aureus.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "En las fases iniciales predomina Th2 (IL-4, IL-5, IL-13, IgE); en las tardías cambia a Th1 (IFN-γ), que inhibe los péptidos antimicrobianos y favorece sobreinfección. S. aureus amplifica la inflamación y podría causar ese cambio; en la enfermedad crónica domina Th2/T22.", "sin_banco": true, "ok": "", "x": "Las bacterias en racimo que entran por las grietas son <b>S. aureus</b>: amplifican la inflamación y empujarían el cambio de <mark>Th2 a Th1</mark>; <span class=\"cx\">luego</span>, en lo crónico, domina <span class=\"res\">Th2/T22</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN16-020", "c": "d", "tema": "Manifestaciones clínicas", "pregunta": "Lactante de 6 meses con placas eritematosas, vesiculosas y exudativas en mejillas y superficies extensoras, con prurito intenso; su madre tiene asma. Respecto a su pronóstico, es correcto:", "opciones": ["a. El 50-80 % de los pacientes con DA desarrollará asma o rinitis alérgica (marcha atópica)", "b. La mayoría mantiene la enfermedad en la vida adulta", "c. Las lesiones crónicas se localizarán en axilas e ingles", "d. La IgE total normal confirma el diagnóstico", "e. El prurito solo aparece en la fase crónica"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. El 50-80 % desarrolla asma o rinitis alérgica (marcha atópica); 75-84 % se cura después de la adolescencia.", "sin_banco": true, "ok": "", "x": "Punto Ⓑ y escalera de la página 2: la <mark>marcha atópica</mark> lleva al 50-80 % a asma o rinitis. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN16-021", "c": "i", "tema": "Diagnóstico y tratamiento", "pregunta": "Según Hanifin y Rajka, ¿cuántos criterios se necesitan para diagnosticar dermatitis atópica?", "opciones": ["a. 1 mayor y 2 menores", "b. 3 de 4 mayores y al menos 3 menores", "c. 4 mayores obligatorios", "d. 2 mayores y 5 menores", "e. Solo la IgE total elevada"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Tres de los cuatro criterios mayores (prurito, morfología y distribución típica, cronicidad o recurrencia, atopia personal o familiar) y al menos tres menores.", "sin_banco": true, "ok": "", "x": "Los <mark>4 mayores</mark> son prurito, morfología típica según la edad, curso crónico-recurrente y atopia. Se piden <b>3 de 4 + 3 menores</b> (xerosis, Dennie-Morgan, queratosis pilaris…). La IgE total sube en 80 % pero <span class=\"res\">no es específica</span> y no se usa de rutina.", "truco": "Regla del 3 + 3.", "veces": 0}, {"n": 8, "id": "IN16-022", "c": "i", "tema": "Definición", "pregunta": "¿En qué se diferencia la alergia alimentaria de la intolerancia alimentaria? Dé un ejemplo de intolerancia.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La alergia es una respuesta inmune específica y reproducible ante un alimento (IgE, celular o mixta); la intolerancia es una reacción por mecanismos no inmunológicos, por ejemplo la intolerancia a la lactosa (metabólica), la escombroidosis (tóxica) o la cafeína (farmacológica).", "sin_banco": true, "ok": "", "x": "El NIAID exige dos cosas: <mark>base inmune</mark> y <b>reproducibilidad</b> con el mismo alimento. La intolerancia no es inmunológica, <span class=\"cx\">así que</span> no necesita estudio inmune ni inmunoterapia, solo evitación o enzimas. <span class=\"res\">Alergia = sistema inmune; intolerancia = no.</span>", "truco": "Alergia: el inmune se equivoca. Intolerancia: el intestino no puede.", "veces": 0}, {"n": 9, "id": "IN16-023", "c": "d", "tema": "Epidemiología", "pregunta": "¿Cuáles son los ocho alimentos que más alergia causan en niños?", "opciones": ["a. Arroz, papa, maíz, pollo, manzana, zanahoria, avena y quinua", "b. Chocolate, fresa, tomate, café, cerdo, naranja, ají y miel", "c. Maní, frutos secos, leche de vaca, mariscos, pescados, huevo, trigo y soya", "d. Solo leche y huevo", "e. Maní, sésamo, kiwi, mango, uva, pera, lenteja y arveja"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Maní, frutos secos, leche de vaca, mariscos, pescados, huevo, trigo y soya.", "sin_banco": true, "ok": "", "x": "La alergia alimentaria afecta más a <mark>niños (8 %)</mark> que a adultos (2 %) <span class=\"cx\">porque</span> su mucosa intestinal es inmadura y deja pasar proteínas intactas. Se han descrito unos 170 alimentos, pero <b>ocho</b> concentran casi todo. <span class=\"res\">Maní, nueces, leche, mar, pescado, huevo, trigo, soya.</span>", "truco": "MaNi-NuLe-MaPe-HuTriSo.", "veces": 0}, {"n": 10, "id": "IN16-024", "c": "i", "tema": "Tolerancia oral", "pregunta": "Sobre la tolerancia oral a los alimentos, señale lo FALSO:", "opciones": ["a. A bajas dosis de antígeno predomina la supresión por células T reguladoras", "b. A altas dosis predominan la anergia y la deleción clonal", "c. Las APC no profesionales del intestino tienden a inducir tolerancia", "d. La IL-10 y el TGF-β ayudan a mantenerla", "e. La administración prolongada del antígeno por vía oral impide la tolerancia"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es FALSO: la administración oral prolongada favorece la tolerancia.", "sin_banco": true, "ok": "", "x": "En la vellosidad de la imagen el <mark>Treg</mark> tranquilo representa la tolerancia: comer el antígeno de forma continua la <b>favorece</b>. <span class=\"cx\">Por eso</span> <span class=\"res\">la e es la falsa</span>.", "truco": "", "veces": 0}, {"n": 11, "id": "IN16-025", "c": "d", "tema": "Mecanismos inmunológicos", "pregunta": "¿Cuál de estas entidades es una alergia alimentaria NO mediada por IgE?", "opciones": ["a. Síndrome de alergia oral", "b. Síndrome de enterocolitis inducido por proteínas alimentarias", "c. Anafilaxia inducida por ejercicio", "d. Urticaria-angioedema", "e. Anafilaxia retardada por carne de mamíferos"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. El síndrome de enterocolitis inducido por proteínas es no dependiente de IgE (inicio retardado), igual que la proctocolitis alérgica y la celíaca.", "sin_banco": true, "ok": "", "x": "Las IgE dependientes son <mark>inmediatas</mark>: urticaria, anafilaxia, síndrome de alergia oral. Las <b>no IgE</b> son de inicio retardado: enterocolitis, proctocolitis, Heiner y celíaca. Las <b>mixtas</b> son esofagitis eosinofílica y dermatitis atópica. <span class=\"res\">Enterocolitis = no IgE.</span>", "truco": "IgE es inmediata; la enterocolitis llega tarde.", "veces": 0}, {"n": 12, "id": "IN16-026", "c": "d", "tema": "Mecanismos inmunológicos", "pregunta": "Joven con rinitis alérgica estacional por pólenes nota prurito, hormigueo y edema de labios y paladar segundos después de morder una manzana cruda. ¿Qué cuadro es y cuál es su mecanismo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome de alergia oral: hipersensibilidad IgE localizada en la mucosa oral por reactividad cruzada entre proteínas de frutas o vegetales frescos y aeroalérgenos a los que ya está sensibilizado.", "sin_banco": true, "ok": "", "x": "El paciente ya tiene IgE contra el <mark>polen</mark>; la fruta fresca trae proteínas <b>estructuralmente parecidas</b>, <span class=\"cx\">así que</span> la IgE las reconoce en la boca. Es IgE dependiente e inmediato, pero queda <span class=\"res\">localizado en labios, lengua y paladar</span>.", "truco": "Polen en la nariz, fruta en la boca: reactividad cruzada.", "veces": 0}, {"n": 13, "id": "IN16-027", "c": "i", "tema": "Diagnóstico", "pregunta": "¿Cuál es el estándar de oro para diagnosticar alergia alimentaria y qué indica un prick test positivo?", "opciones": ["a. IgE total sérica; indica alergia confirmada", "b. Prueba de exposición oral controlada doble ciega con placebo; un prick positivo indica solo sensibilización", "c. Prueba de parche; indica intolerancia", "d. Recuento de eosinófilos; indica anafilaxia", "e. Endoscopia; indica celíaca"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La prueba de exposición oral controlada (OFC) doble ciega con placebo; un SPT o IgE específica positivos indican sensibilización, no necesariamente alergia.", "sin_banco": true, "ok": "", "x": "La <mark>OFC doble ciega</mark> es el estándar de oro, pero es lenta y cara; en la práctica se hace <b>abierta</b> y siempre donde se pueda tratar una anafilaxia. Un prick positivo solo dice que hay IgE; en el maní, el diagnóstico por componentes ayuda: <span class=\"res\">Ara h2 predice reactividad; solo Ara h8, buen pronóstico.</span>", "truco": "El oro es comer el alimento, a ciegas y con placebo.", "veces": 0}, {"n": 14, "id": "IN16-028", "c": "i", "tema": "Tratamiento", "pregunta": "¿Cuáles son los dos pilares del tratamiento convencional de la alergia alimentaria y cómo actúa el omalizumab en ella?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Evitación estricta del alimento y preparación para tratar prontamente una reacción (plan de emergencia y educación). El omalizumab (anti-IgE) reduce la IgE libre y los receptores de alta afinidad en mastocitos y basófilos.", "sin_banco": true, "ok": "", "x": "El paciente <mark>evita el alimento</mark> y lleva un <b>plan de emergencia</b>; nunca debe probarlo por su cuenta. La escuela debe saberlo y prevenir el acoso. En múltiples alergias se usan probióticos (<b>L. rhamnosus GG</b>) y <span class=\"res\">omalizumab</span>.", "truco": "Evitar y estar preparado.", "veces": 0}], "tabla": {"cab": ["", "DA extrínseca", "DA intrínseca", "Alergia alimentaria", "Intolerancia"], "filas": [["Base", "IgE, Th2", "Th1, IFN-γ", "inmune, reproducible", "no inmune"], ["IgE específica", "sí", "no", "sí (en la IgE)", "no"], ["Filagrina", "mutada", "normal", "—", "—"], ["Estudio", "clínico", "clínico", "SPT, IgE, OFC", "no inmunológico"], ["🔑 Para diferenciar", "alérgeno de afuera", "sin IgE", "el inmune se equivoca", "lactosa, cafeína"]]}, "fuente": "Fuente: tu teoría — clase 37 (Dermatitis atópica) y clase 38 (Alergia alimentaria), Rojas 17.ª ed."}, {"n": 30, "slug": "Autoinmunidad", "titulo": "Autoinmunidad y mecanismos de daño", "subtitulo": "cómo se rompe la tolerancia y cómo dañan los autoanticuerpos, los complejos inmunes y los linfocitos T", "grupo": "g17", "lema": "La idea: la <mark>autoinmunidad</mark> es la ruptura de la tolerancia: el sistema inmune ataca lo propio y produce inflamación crónica. Afecta a <b>1 de cada 20 personas</b> y sobre todo a mujeres jóvenes. Nace de la suma de <u>genes (HLA, AIRE, FoxP3), ambiente (infecciones con mimetismo molecular, fármacos, sol) y hormonas (estrógenos)</u>. Una vez rota la tolerancia, el daño ocurre por tres vías de Gell y Coombs: <b>tipo II</b> (el autoanticuerpo se pega a la célula), <b>tipo III</b> (los complejos inmunes se depositan en los vasos) y <b>tipo IV</b> (el linfocito T mata o activa macrófagos). En la imagen verás de izquierda a derecha esas tres vías: el eritrocito y los receptores atacados por anticuerpos, el capilar con complejos inmunes y neutrófilos, y el islote pancreático destruido por un linfocito T CD8.", "img": "img/30.webp", "mini": "img/mini/30.webp", "ratio": 1.5, "etiquetas": [{"n": "⑤", "t": "Autoanticuerpos", "s": "sobre la célula:<br>tipo II", "c": "i", "x": 0.5, "y": 6, "ax": 11, "ay": 22, "al": "l"}, {"n": "⑤⑧", "t": "Poro", "s": "lisis;<br>sin C1q: lupus", "c": "i", "x": 25, "y": 6, "ax": 19.5, "ay": 31, "d": "A"}, {"n": "⑦", "t": "Complejos inmunes", "s": "en el endotelio:<br>tipo III", "c": "d", "x": 42, "y": 6, "ax": 39, "ay": 37, "d": "B"}, {"n": "⑦", "t": "C3a y C5a", "s": "atraen<br>neutrófilos", "c": "d", "x": 58.5, "y": 6, "ax": 48, "ay": 36}, {"n": "⑩", "t": "Macrófago activado", "s": "TNF, IFN-γ, IL-1:<br>tipo IV", "c": "g", "x": 76, "y": 6, "ax": 76, "ay": 26}, {"n": "⑩", "t": "Th1", "s": "activa al<br>macrófago", "c": "g", "x": 99.5, "y": 6, "ax": 92.5, "ay": 26, "al": "r"}, {"n": "⑥", "t": "Receptor de TSH", "s": "lo enciende:<br>Graves", "c": "i", "x": 0.5, "y": 91, "ax": 6.2, "ay": 60, "d": "C", "al": "l"}, {"n": "⑤", "t": "Receptor de ACh", "s": "lo tapa:<br>miastenia", "c": "i", "x": 28, "y": 91, "ax": 21, "ay": 66}, {"n": "⑦", "t": "Pared vascular", "s": "dañada por<br>enzimas", "c": "d", "x": 45, "y": 91, "ax": 53, "ay": 70}, {"n": "⑦", "t": "Neutrófilo", "s": "libera enzimas<br>lisosomales", "c": "d", "x": 61.5, "y": 91, "ax": 56.5, "ay": 58}, {"n": "⑩", "t": "Célula beta", "s": "apoptosis:<br>diabetes tipo 1", "c": "g", "x": 78, "y": 91, "ax": 80.5, "ay": 66}, {"n": "⑩", "t": "LT CD8", "s": "lisa la célula<br>propia", "c": "g", "x": 99.5, "y": 91, "ax": 90, "ay": 58, "al": "r"}], "diapos": [{"img": "img/30.webp", "ratio": 1.5, "titulo": "Tipos II, III y IV de daño", "texto": "El <mark>autoanticuerpo</mark> daña la célula (tipo II) ⑤, los complejos se depositan en el vaso (tipo III) ⑦ y el linfocito T mata (tipo IV) ⑩.", "etiquetas": [{"n": "⑤", "t": "Autoanticuerpos", "s": "sobre la célula:<br>tipo II", "c": "i", "x": 0.5, "y": 6, "ax": 11, "ay": 22, "al": "l"}, {"n": "⑤⑧", "t": "Poro", "s": "lisis;<br>sin C1q: lupus", "c": "i", "x": 25, "y": 6, "ax": 19.5, "ay": 31, "d": "A"}, {"n": "⑦", "t": "Complejos inmunes", "s": "en el endotelio:<br>tipo III", "c": "d", "x": 42, "y": 6, "ax": 39, "ay": 37, "d": "B"}, {"n": "⑦", "t": "C3a y C5a", "s": "atraen<br>neutrófilos", "c": "d", "x": 58.5, "y": 6, "ax": 48, "ay": 36}, {"n": "⑩", "t": "Macrófago activado", "s": "TNF, IFN-γ, IL-1:<br>tipo IV", "c": "g", "x": 76, "y": 6, "ax": 76, "ay": 26}, {"n": "⑩", "t": "Th1", "s": "activa al<br>macrófago", "c": "g", "x": 99.5, "y": 6, "ax": 92.5, "ay": 26, "al": "r"}, {"n": "⑥", "t": "Receptor de TSH", "s": "lo enciende:<br>Graves", "c": "i", "x": 0.5, "y": 91, "ax": 6.2, "ay": 60, "d": "C", "al": "l"}, {"n": "⑤", "t": "Receptor de ACh", "s": "lo tapa:<br>miastenia", "c": "i", "x": 28, "y": 91, "ax": 21, "ay": 66}, {"n": "⑦", "t": "Pared vascular", "s": "dañada por<br>enzimas", "c": "d", "x": 45, "y": 91, "ax": 53, "ay": 70}, {"n": "⑦", "t": "Neutrófilo", "s": "libera enzimas<br>lisosomales", "c": "d", "x": 61.5, "y": 91, "ax": 56.5, "ay": 58}, {"n": "⑩", "t": "Célula beta", "s": "apoptosis:<br>diabetes tipo 1", "c": "g", "x": 78, "y": 91, "ax": 80.5, "ay": 66}, {"n": "⑩", "t": "LT CD8", "s": "lisa la célula<br>propia", "c": "g", "x": 99.5, "y": 91, "ax": 90, "ay": 58, "al": "r"}]}, {"img": "img/30_2.webp", "ratio": 1.5, "titulo": "Cómo se rompe la tolerancia", "texto": "Sin <mark>FoxP3</mark> no hay Treg: IPEX ③; por mimetismo, <b>Campylobacter</b> lleva a Guillain-Barré ④; la procainamida altera la metilación ⑨.", "etiquetas": [{"n": "③", "t": "Timo con Treg", "s": "FoxP3: los Treg<br>verdes salen", "c": "i", "x": 0.5, "y": 6, "ax": 13, "ay": 47, "al": "l"}, {"n": "③", "t": "Sin FoxP3", "s": "sin Treg: LT<br>libres = IPEX", "c": "d", "x": 26, "y": 6, "ax": 34, "ay": 46}, {"n": "④", "t": "Campylobacter", "s": "azúcares como<br>gangliósidos", "c": "g", "x": 45, "y": 6, "ax": 51, "ay": 37}, {"n": "④", "t": "Anticuerpo", "s": "hecho contra<br>la bacteria", "c": "i", "x": 63, "y": 6, "ax": 60, "ay": 40}, {"n": "⑨", "t": "Fármaco", "s": "procainamida,<br>hidralazina", "c": "g", "x": 99.5, "y": 6, "ax": 91, "ay": 29, "al": "r"}, {"n": "③", "t": "Treg frena al LT", "s": "contacto<br>regulador", "c": "i", "x": 0.5, "y": 91, "ax": 21.5, "ay": 67, "al": "l"}, {"n": "④", "t": "Mielina dañada", "s": "reacción cruzada:<br>Guillain-Barré", "c": "d", "x": 45, "y": 91, "ax": 65, "ay": 51}, {"n": "⑨", "t": "ADN metilado", "s": "la metilación<br>apaga genes", "c": "g", "x": 73, "y": 91, "ax": 82, "ay": 46}, {"n": "⑨", "t": "Metilos que se caen", "s": "ADN hipometilado:<br>lupus por fármacos", "c": "d", "x": 99.5, "y": 91, "ax": 94, "ay": 58, "al": "r"}]}, {"img": "img/30_3.webp", "ratio": 1.5, "titulo": "Órgano-específica frente a sistémica", "texto": "En las <mark>órgano-específicas</mark> mandan los linfocitos T (tiroides, islote, nervio); <span class=\"cx\">en cambio</span>, en las sistémicas mandan el linfocito B y los complejos inmunes que se depositan en riñón, articulación y piel ⑩ <span class=\"lt2\">B</span>.", "etiquetas": [{"n": "⑩", "t": "Tiroides", "s": "infiltrado de<br>linfocitos T", "c": "i", "x": 45, "y": 6, "ax": 24, "ay": 22}, {"n": "⑩", "t": "Insulitis", "s": "LT rodean y<br>destruyen el islote", "c": "d", "x": 47, "y": 38, "ax": 32, "ay": 48, "al": "r"}, {"n": "⑩", "t": "Plasmocito", "s": "fábrica de<br>autoanticuerpos", "c": "i", "x": 62, "y": 6, "ax": 57, "ay": 20}, {"n": "⑩", "t": "Glomérulo", "s": "depósito:<br>glomerulonefritis", "c": "d", "x": 99.5, "y": 6, "ax": 88, "ay": 25, "al": "r"}, {"n": "⑩", "t": "Desmielinización", "s": "LT y macrófagos<br>pelan la mielina", "c": "d", "x": 0.5, "y": 93, "ax": 19.5, "ay": 78, "al": "l"}, {"n": "⑦", "t": "Inmunocomplejos", "s": "antígeno + anticuerpo<br>en la sangre", "c": "d", "x": 52, "y": 91, "ax": 69, "ay": 52, "d": "B"}, {"n": "⑩", "t": "Articulación", "s": "complejos en<br>la sinovial: artritis", "c": "d", "x": 72, "y": 91, "ax": 85, "ay": 48}, {"n": "⑩", "t": "Piel", "s": "depósitos en la unión<br>dermoepidérmica", "c": "d", "x": 99.5, "y": 91, "ax": 85, "ay": 79, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = autoanticuerpos sobre la célula</b> (tipo II), <b class=\"d\">rojo = complejos inmunes e inflamación</b> (tipo III), gris = linfocitos T y macrófagos (tipo IV).", "<b>Izquierda (tipo II):</b> el mismo autoanticuerpo puede <mark>romper</mark> la célula con el complemento, <mark>tapar</mark> un receptor (miastenia) o <mark>encenderlo</mark> (Graves). <span class=\"cx\">Por eso</span> el tipo II da cuadros opuestos: debilidad o hiperfunción.", "<b>Centro (tipo III):</b> los complejos antígeno-anticuerpo que el sistema reticuloendotelial no alcanza a limpiar se depositan donde la sangre se filtra: glomérulo, plexo coroide, sinovial y serosas <span class=\"lt2\">B</span>.", "<b>Derecha (tipo IV):</b> el LT CD8 mata la célula beta (diabetes tipo 1) y el Th1 activa al macrófago, que libera TNF, IFN-γ e IL-1 (daño sinovial de la artritis reumatoide)."], "recordar": "Genes + ambiente + hormonas rompen la tolerancia. Luego el daño es <b>tipo II</b> (anticuerpo sobre la célula), <b>tipo III</b> (complejos en el vaso) o <b>tipo IV</b> (linfocito T). Órgano-específica = linfocito T; sistémica = linfocito B."}, "numeros": [{"l": "A", "html": "<b>Déficit de complemento</b>: sin C1q, el <b class=\"a\">90 %</b> desarrolla lupus; sin C4, el <b class=\"a\">75 %</b>.", "rango": null}, {"l": "B", "html": "<b>Complejos inmunes</b>: se depositan cuando superan la capacidad de limpieza; atraen neutrófilos con C3a y C5a.", "rango": null}, {"l": "C", "html": "<b>Epidemiología</b>: las EAI afectan al <b class=\"a\">5 %</b> de la población; el <b class=\"a\">80 %</b> son mujeres. Concordancia en gemelos monocigotos: <b class=\"n\">20–60 %</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la tolerancia al daño", "subtitulo": "factores → clones autorreactivos → mecanismo de daño → enfermedad", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Predisposición", "m": "<b>Qué pasa:</b> genes <mark>HLA</mark> (B27, DRB1*0401, DR3) y no-HLA (PTPN22, CTLA-4); raros genes únicos: AIRE, <mark>FoxP3</mark>, Fas, C4, NOD2. La epigenética une genes y ambiente.", "pr": "el terreno es fértil, pero la concordancia en gemelos es solo de 20–60 %.", "pr_tit": "Produce:", "rf": "Preguntas ①②③ · <span class=\"lt2\">C</span>", "color": "p1"}, {"t": "2. Disparador", "m": "<b>Por qué:</b> una infección con <mark>mimetismo molecular</mark> (estreptococo, Campylobacter, Klebsiella), un fármaco que desmetila el ADN (hidralazina, procainamida), un antígeno oculto que se expone, los estrógenos.", "pr": "los pocos clones autorreactivos que sobrevivieron se despiertan.", "pr_tit": "Produce:", "rf": "Preguntas ④⑨", "color": "p2"}, {"t": "3. Se pierde el freno", "m": "<b>Qué falla:</b> los <mark>LsTreg CD4+ CD25+ FoxP3+</mark> no frenan; falta C1q o C4 y no se limpian complejos ni cuerpos apoptóticos; el déficit de IgA deja pasar antígenos.", "pr": "LsT CD4 → Th1 proinflamatorios; LsB → autoanticuerpos.", "pr_tit": "Produce:", "rf": "Preguntas ③⑧ · punto <span class=\"lt2\">A</span>", "color": "p3"}, {"t": "4. Daño tipo II y III", "m": "<b>Qué produce:</b> el autoanticuerpo lisa, marca para ADCC, bloquea o estimula el receptor; los <mark>complejos inmunes</mark> se depositan en el endotelio y activan el complemento, y los neutrófilos liberan enzimas lisosomales.", "pr": "anemia hemolítica, miastenia, Graves, nefritis, artritis, serositis.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥⑦ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Daño tipo IV y clasificación", "m": "<b>Qué produce:</b> el <mark>LT CD8</mark> lisa la célula propia; el Th1 activa macrófagos (TNF, IFN-γ, IL-1). Si el blanco es un órgano, la EAI es <b>órgano-específica</b> (T); si son complejos que viajan, <b>sistémica</b> (B).", "pr": "diabetes tipo 1, Hashimoto, esclerosis múltiple; o lupus y artritis reumatoide.", "pr_tit": "Produce:", "rf": "Pregunta ⑩", "color": "p4"}], "extra": [{"html": "🧬 <b>Genes únicos (mendelianos):</b> AIRE → poliendocrinopatía; FoxP3 → IPEX; Fas/FasL → síndrome linfoproliferativo autoinmune; C4 → lupus; NOD2 → Crohn.", "k": ""}, {"html": "🦠 <b>Mimetismo molecular:</b> estreptococo grupo A ≈ miosina (fiebre reumática); Campylobacter ≈ gangliósidos (Guillain-Barré); Klebsiella ≈ colágeno (espondilitis); <b>T. cruzi</b> ≈ miosina (Chagas). Los helmintos, <span class=\"cx\">en cambio</span>, parecen <b>proteger</b>.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De un clon a varias enfermedades", "pasos": ["un clon autorreactivo escapa", "una EAI órgano-específica", "otra EAI en el mismo paciente", "<b>síndrome autoinmune múltiple</b> (3 o más EAI)", "varias EAI en la familia: autoinmunidad familiar"]}], "html": "", "fuente": "Fuente: tu teoría — clase 39 (etiología genética, ambiental, inmunológica y hormonal; mecanismos de daño tipo II, III y IV; clasificación clínica)."}, "preguntas": [{"n": 1, "id": "IN17-001", "c": "g", "tema": "El sistema inmune contra lo propio", "pregunta": "Respecto a la epidemiología de las enfermedades autoinmunes (EAI), es correcto:", "opciones": ["a. Afectan a cerca del 5 % de la población y el 80 % de los casos son mujeres en edad reproductiva.", "b. Afectan a cerca del 0,5 % de la población, sin predominio de sexo.", "c. Afectan al 20 % de la población y predominan en varones mayores.", "d. Son monogénicas en la mayoría de los casos y se curan con inmunosupresión.", "e. Predominan en la infancia y desaparecen después de la pubertad."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Cerca del 5 % de las personas; el 80 % son mujeres en edad reproductiva.", "sin_banco": true, "ok": "", "x": "La autoinmunidad es la ruptura de la tolerancia: el sistema inmune ataca antígenos propios. Afecta a <mark>1 de cada 20 personas</mark> y, <span class=\"cx\">porque</span> los estrógenos modulan la respuesta inmune, predomina en mujeres jóvenes. <span class=\"cx\">Además</span>, casi todas son <span class=\"res\">crónicas e incurables y poligénicas</span>.", "truco": "«Una de cada veinte, y cuatro de cada cinco son mujeres».", "veces": 0}, {"n": 2, "id": "IN17-002", "c": "g", "tema": "Factores genéticos", "pregunta": "La concordancia de las EAI en gemelos monocigotos es de 20 a 60 %. Esto indica que:", "opciones": ["a. Las EAI se heredan con patrón mendeliano dominante.", "b. Los gemelos monocigotos no comparten los genes HLA.", "c. El HLA no participa en la susceptibilidad.", "d. Además de los genes, son imprescindibles factores ambientales, epigenéticos y hormonales.", "e. La enfermedad depende solo del ambiente."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los genes predisponen, pero sin ambiente, epigenética y hormonas no basta.", "sin_banco": true, "ok": "", "x": "Si dependiera solo de los genes, dos gemelos idénticos enfermarían <mark>siempre juntos (100 %)</mark>. Como la concordancia no pasa del 60 %, el ambiente y la epigenética (metilación del ADN, histonas) completan el cuadro. <span class=\"cx\">Por eso</span> se dice que las EAI son <span class=\"res\">poligénicas y multifactoriales</span>.", "truco": "Gemelos idénticos, destinos distintos: el ambiente pone el resto.", "veces": 0}, {"n": 3, "id": "IN17-003", "c": "g", "tema": "Factores genéticos: genes únicos", "pregunta": "La mutación del gen FoxP3, que deja sin linfocitos T reguladores, produce:", "opciones": ["a. Poliendocrinopatía autoinmune.", "b. Síndrome linfoproliferativo autoinmune.", "c. Síndrome IPEX ligado al X.", "d. Enfermedad de Crohn.", "e. Lupus eritematoso sistémico."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Síndrome IPEX ligado al X (deficiencia de LsTreg).", "sin_banco": true, "ok": "", "x": "El FoxP3 es el «interruptor» de los <mark>LsTreg CD4+ CD25+</mark>; sin ellos no hay freno para los clones autorreactivos. <span class=\"cx\">En cambio</span>, el AIRE falla en la tolerancia central (poliendocrinopatía) y el Fas/FasL no elimina los LsB autorreactivos. <span class=\"cx\">Así que</span> <span class=\"res\">FoxP3 → IPEX</span>.", "truco": "FoxP3 = Freno; sin freno, IPEX.", "veces": 0}, {"n": 4, "id": "IN17-004", "c": "g", "tema": "Factores ambientales: mimetismo molecular", "pregunta": "Por mimetismo molecular entre sus lipo-oligosacáridos y los gangliósidos del nervio, la infección por Campylobacter jejuni puede desencadenar:", "opciones": ["a. Fiebre reumática.", "b. Síndrome de Guillain-Barré.", "c. Espondilitis anquilosante.", "d. Cardiopatía chagásica.", "e. Enfermedad celíaca."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Síndrome de Guillain-Barré.", "sin_banco": true, "ok": "", "x": "En el <mark>mimetismo molecular</mark> el microbio tiene un epítopo parecido a una molécula propia, <span class=\"cx\">por eso</span> los anticuerpos contra el germen atacan también al tejido. El estreptococo imita la miosina (fiebre reumática), la Klebsiella al colágeno (espondilitis) y el <b>T. cruzi</b> la miosina (Chagas). <span class=\"cx\">En cambio</span>, el Campylobacter imita <span class=\"res\">los gangliósidos del nervio</span>.", "truco": "Campylobacter → «campo» de gangliósidos → nervio → Guillain-Barré.", "veces": 0}, {"n": 5, "id": "IN17-005", "c": "i", "tema": "Mecanismos de daño: tipo II", "pregunta": "¿Cuáles son los cuatro mecanismos por los que los autoanticuerpos (tipo II) dañan los tejidos?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Lisis por activación del complemento, citotoxicidad dependiente de anticuerpos (ADCC), bloqueo de receptores (miastenia gravis) y estimulación agonista de receptores (enfermedad de Graves).", "sin_banco": true, "ok": "", "x": "Son las tres escenas de la izquierda: el eritrocito con el <mark>poro del complemento</mark> (lisis), el receptor tapado y el receptor encendido; la cuarta vía es la ADCC por la Fc. <span class=\"cx\">Por eso</span>: <span class=\"res\">lisa, marca, tapa y prende</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN17-006", "c": "i", "tema": "Mecanismos de daño: tipo II (correlación clínica)", "pregunta": "Mujer de 30 años con taquicardia, pérdida de peso y bocio difuso. Tiene anticuerpos IgG contra el receptor de TSH. ¿Qué mecanismo de daño explica el cuadro?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Tipo II por estimulación agonista del receptor: el anticuerpo imita a la TSH y causa hipertiroidismo (enfermedad de Graves).", "sin_banco": true, "ok": "", "x": "En la imagen, el anticuerpo sobre la célula tiroidea <mark>enciende</mark> el receptor de TSH en lugar de taparlo, <span class=\"cx\">así que</span> la tiroides trabaja de más: <span class=\"res\">tipo II estimulador (Graves)</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN17-007", "c": "d", "tema": "Mecanismos de daño: tipo III", "pregunta": "Los complejos inmunes que superan la capacidad del sistema reticuloendotelial se depositan en el endotelio de los siguientes sitios, EXCEPTO:", "opciones": ["a. Glomérulos renales.", "b. Cristalino.", "c. Plexos coroides.", "d. Articulaciones.", "e. Serosas."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Cristalino: no tiene vasos; es un sitio de antígenos ocultos, no de depósito de complejos.", "sin_banco": true, "ok": "", "x": "Es el capilar del centro (punto Ⓑ): los complejos se depositan donde la sangre se filtra y los neutrófilos liberan enzimas. El cristalino no tiene vasos: es un antígeno oculto. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN17-008", "c": "d", "tema": "Factores inmunológicos: complemento", "pregunta": "¿Por qué la deficiencia de C1q predispone al lupus eritematoso sistémico?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque el C1q limpia complejos inmunes y células apoptóticas; sin él se acumulan y sirven de fuente de autoantígenos. El 90 % de quienes no tienen C1q desarrolla lupus (75 % con déficit de C4).", "sin_banco": true, "ok": "", "x": "El C1q no solo inicia la vía clásica: también <mark>retira la basura</mark> (complejos inmunes y cuerpos apoptóticos). Si falta, esos restos con ADN quedan expuestos y el sistema inmune los ataca. <span class=\"cx\">Por eso</span> <span class=\"res\">el déficit de C1q da lupus en el 90 %</span>.", "truco": "Sin el «barrendero» C1q, la basura nuclear se vuelve autoantígeno.", "veces": 0}, {"n": 9, "id": "IN17-009", "c": "g", "tema": "Factores ambientales: fármacos", "pregunta": "La procainamida y la hidralazina pueden inducir lupus porque:", "opciones": ["a. Activan el gen PADI4 y citrulinizan proteínas.", "b. Destruyen los linfocitos T reguladores por apoptosis.", "c. Imitan a la miosina cardíaca.", "d. Bloquean la producción de IgA secretora.", "e. Alteran los patrones de metilación del ADN (mecanismo epigenético)."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Alteran la metilación del ADN.", "sin_banco": true, "ok": "", "x": "Estos fármacos <mark>quitan metilos al ADN</mark>; así se encienden genes que debían estar apagados en los linfocitos y aparece un cuadro lúpico. <span class=\"cx\">En cambio</span>, la metil-dopa da anemia hemolítica, la amiodarona tiroiditis y el cigarrillo (PADI4) se asocia a <span class=\"res\">artritis reumatoide</span>.", "truco": "Hidralazina y procainamida «desmetilan» y despiertan al lupus.", "veces": 0}, {"n": 10, "id": "IN17-010", "c": "g", "tema": "Clasificación clínica de las EAI", "pregunta": "¿Qué diferencia a las EAI órgano-específicas de las sistémicas en cuanto a la inmunidad que predomina?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "En las órgano-específicas (Hashimoto, diabetes tipo 1, esclerosis múltiple) predominan los linfocitos T; en las sistémicas (lupus, artritis reumatoide), los linfocitos B y los autoanticuerpos.", "sin_banco": true, "ok": "", "x": "Compara la derecha de la imagen (un LT CD8 contra un islote: un solo órgano) con el centro (complejos que viajan por la sangre: muchos órganos). <span class=\"cx\">Por eso</span> <span class=\"res\">órgano-específica = T y sistémica = B</span>.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "Tipo II", "Tipo III", "Tipo IV"], "filas": [["Quién daña", "Autoanticuerpo IgG/IgM sobre la célula", "Complejos antígeno-anticuerpo", "LT CD8 y Th1 con macrófagos"], ["Cómo daña", "Complemento, ADCC, bloqueo o estímulo del receptor", "Depósito en endotelio, C3a/C5a, enzimas de neutrófilos", "Lisis directa o TNF, IFN-γ e IL-1"], ["Ejemplos", "Anemia hemolítica, miastenia, Graves", "Lupus, Arthus, enfermedad del suero", "Diabetes tipo 1, AR (sinovial)"], ["🔑 Para diferenciar", "El anticuerpo está en la célula", "El anticuerpo viaja y se deposita", "Sin anticuerpo: lo hace el linfocito T"]]}, "fuente": "Fuente: tu teoría — clase 39 (Autoinmunidad), Rojas 17.ª ed., cap. 39."}, {"n": 31, "slug": "Artritis_autoinmunes", "titulo": "Artritis reumatoide y otras artritis", "subtitulo": "el pannus que come cartílago y hueso, frente a la entesis, los cristales y los complejos a distancia", "grupo": "g17", "lema": "La idea: en la <mark>artritis reumatoide</mark> la membrana sinovial se vuelve un tejido invasor, el <b>pannus</b>, que come el cartílago y el hueso. Todo empieza años antes, en una <b>fase prearticular</b>: el cigarrillo citruliniza proteínas y aparecen el factor reumatoide y los <mark>anti-CCP</mark>. En la sinovial mandan el <u>TNF de los macrófagos M1</u>, los Th17 (IL-17 → RANKL → osteoclastos) y los fibroblastos con sus metaloproteinasas. Otras artritis dañan por caminos distintos: la <b>espondilitis</b> inflama la entesis (HLA-B27, IL-17/IL-23), la <b>gota</b> enciende el inflamasoma NLRP3 con cristales de urato, la <b>reactiva</b> y la <b>lúpica</b> dependen de complejos inmunes y la de la <b>fiebre reumática</b> del mimetismo molecular. En la imagen verás la articulación metacarpofalángica con pannus, una ampliación del frente de erosión y, a la derecha, un neutrófilo que fagocita cristales de urato en el dedo gordo.", "img": "img/31.webp", "mini": "img/mini/31.webp", "ratio": 1.5, "etiquetas": [{"n": "④", "t": "Sinovitis y neovasos", "s": "macrófagos, Th1,<br>neutrófilos", "c": "i", "x": 0.5, "y": 6, "ax": 25, "ay": 29, "al": "l"}, {"n": "④", "t": "Macrófago M1", "s": "TNF, IL-1, IL-6", "c": "i", "x": 27.5, "y": 6, "ax": 42, "ay": 30}, {"n": "⑤", "t": "Th17", "s": "IL-17:<br>RANKL", "c": "i", "x": 44, "y": 6, "ax": 56, "ay": 27}, {"n": "①③", "t": "Plasmocito", "s": "anti-CCP y<br>factor reumatoide", "c": "i", "x": 60, "y": 6, "ax": 66, "ay": 42, "d": "A"}, {"n": "⑫⑬", "t": "Neutrófilo", "s": "come urato<br>y revienta", "c": "d", "x": 85.5, "y": 6, "ax": 87, "ay": 17, "al": "r"}, {"n": "", "t": "Cartílago", "s": "sin lubricina:<br>MMP-14 lo rompe", "c": "g", "x": 0.5, "y": 91, "ax": 11, "ay": 40, "al": "l"}, {"n": "⑧", "t": "Pannus", "s": "sinovial invasora", "c": "d", "x": 22.5, "y": 91, "ax": 21, "ay": 48}, {"n": "", "t": "Fibroblasto sinovial", "s": "metaloproteinasas", "c": "i", "x": 39, "y": 91, "ax": 51, "ay": 45}, {"n": "⑤", "t": "Osteoclasto", "s": "reabsorbe hueso:<br>erosión", "c": "d", "x": 55, "y": 91, "ax": 55, "ay": 58, "d": "B"}, {"n": "⑫", "t": "Cristales de urato", "s": "gota: inflamación<br>estéril", "c": "d", "x": 73, "y": 91, "ax": 84, "ay": 55}, {"n": "⑬", "t": "Dedo gordo", "s": "ataque agudo,<br>muy doloroso", "c": "g", "x": 99.5, "y": 91, "ax": 96, "ay": 66, "al": "r"}], "diapos": [{"img": "img/31.webp", "ratio": 1.5, "titulo": "Pannus, osteoclasto y cristal de urato", "texto": "En la AR la sinovial se vuelve <mark>pannus</mark> y el osteoclasto erosiona el hueso ④⑤; en la gota el neutrófilo <b>come urato y revienta</b> ⑫⑬.", "etiquetas": [{"n": "④", "t": "Sinovitis y neovasos", "s": "macrófagos, Th1,<br>neutrófilos", "c": "i", "x": 0.5, "y": 6, "ax": 25, "ay": 29, "al": "l"}, {"n": "④", "t": "Macrófago M1", "s": "TNF, IL-1, IL-6", "c": "i", "x": 27.5, "y": 6, "ax": 42, "ay": 30}, {"n": "⑤", "t": "Th17", "s": "IL-17:<br>RANKL", "c": "i", "x": 44, "y": 6, "ax": 56, "ay": 27}, {"n": "①③", "t": "Plasmocito", "s": "anti-CCP y<br>factor reumatoide", "c": "i", "x": 60, "y": 6, "ax": 66, "ay": 42, "d": "A"}, {"n": "⑫⑬", "t": "Neutrófilo", "s": "come urato<br>y revienta", "c": "d", "x": 85.5, "y": 6, "ax": 87, "ay": 17, "al": "r"}, {"n": "", "t": "Cartílago", "s": "sin lubricina:<br>MMP-14 lo rompe", "c": "g", "x": 0.5, "y": 91, "ax": 11, "ay": 40, "al": "l"}, {"n": "⑧", "t": "Pannus", "s": "sinovial invasora", "c": "d", "x": 22.5, "y": 91, "ax": 21, "ay": 48}, {"n": "", "t": "Fibroblasto sinovial", "s": "metaloproteinasas", "c": "i", "x": 39, "y": 91, "ax": 51, "ay": 45}, {"n": "⑤", "t": "Osteoclasto", "s": "reabsorbe hueso:<br>erosión", "c": "d", "x": 55, "y": 91, "ax": 55, "ay": 58, "d": "B"}, {"n": "⑫", "t": "Cristales de urato", "s": "gota: inflamación<br>estéril", "c": "d", "x": 73, "y": 91, "ax": 84, "ay": 55}, {"n": "⑬", "t": "Dedo gordo", "s": "ataque agudo,<br>muy doloroso", "c": "g", "x": 99.5, "y": 91, "ax": 96, "ay": 66, "al": "r"}]}, {"img": "img/31_2.webp", "ratio": 1.5, "titulo": "Del cigarrillo al anti-CCP", "texto": "El <mark>cigarrillo</mark> citrulina proteínas (PADI4) ②; la célula B fabrica anti-CCP años antes del dolor ① <span class=\"lt2\">A</span>, y el <b>factor reumatoide</b> es una IgM contra el Fc de la IgG ③.", "etiquetas": [{"n": "②", "t": "Humo", "s": "del<br>cigarrillo", "c": "g", "x": 0.5, "y": 6, "ax": 5, "ay": 21.5, "al": "l"}, {"n": "②", "t": "PADI4", "s": "citrulina las<br>proteínas", "c": "i", "x": 22, "y": 6, "ax": 12.4, "ay": 48}, {"n": "②", "t": "Dendrítica", "s": "presenta el péptido<br>citrulinado", "c": "i", "x": 39, "y": 6, "ax": 35, "ay": 31}, {"n": "②", "t": "LT CD4", "s": "lo reconoce<br>en HLA-DR", "c": "i", "x": 57, "y": 6, "ax": 57, "ay": 29}, {"n": "③", "t": "Factor reumatoide", "s": "IgM contra el Fc<br>de la IgG", "c": "d", "x": 99.5, "y": 6, "ax": 81.4, "ay": 43, "al": "r"}, {"n": "", "t": "Linfocito B", "s": "se activa", "c": "i", "x": 0.5, "y": 91, "ax": 34, "ay": 62.5, "al": "l"}, {"n": "①", "t": "Plasmocito", "s": "anti-CCP años<br>antes del dolor", "c": "i", "x": 40, "y": 91, "ax": 47, "ay": 62.5, "d": "A"}, {"n": "①", "t": "Anti-CCP", "s": "especificidad<br>95 %", "c": "i", "x": 61, "y": 91, "ax": 62.5, "ay": 62.5}, {"n": "③", "t": "IgG", "s": "su Fc es el<br>blanco del FR", "c": "g", "x": 99.5, "y": 91, "ax": 92.5, "ay": 50, "al": "r"}]}, {"img": "img/31_3.webp", "ratio": 1.5, "titulo": "Espondilitis: entesis y uveítis", "texto": "La espondilitis inflama la <mark>entesis</mark> con IL-17 e IL-23 ⑫, con patrón axial centrífugo ⑨; HLA-B27 en más del 90 % ⑪, que se asocia a uveítis anterior ⑯.", "etiquetas": [{"n": "⑫", "t": "Entesitis", "s": "ligamento<br>inflamado", "c": "d", "x": 0.5, "y": 6, "ax": 13.3, "ay": 29, "al": "l"}, {"n": "⑨", "t": "Columna lumbar", "s": "patrón axial<br>centrífugo", "c": "g", "x": 27, "y": 6, "ax": 19.5, "ay": 39}, {"n": "⑫", "t": "Tendón", "s": "fibras que se<br>anclan al hueso", "c": "g", "x": 45, "y": 6, "ax": 40, "ay": 23.4}, {"n": "⑫", "t": "IL-17 e IL-23", "s": "eje Th17<br>en la entesis", "c": "d", "x": 62, "y": 6, "ax": 45, "ay": 44}, {"n": "⑯", "t": "Uveítis anterior", "s": "ojo rojo<br>doloroso", "c": "d", "x": 99.5, "y": 6, "ax": 79.5, "ay": 31, "al": "r"}, {"n": "⑪", "t": "Sacroilíaca", "s": "HLA-B27 en<br>más del 90 %", "c": "d", "x": 0.5, "y": 91, "ax": 14, "ay": 62.5, "al": "l"}, {"n": "⑫", "t": "Neutrófilos", "s": "infiltran<br>la entesis", "c": "i", "x": 30, "y": 91, "ax": 40, "ay": 55}, {"n": "⑫", "t": "Hueso nuevo", "s": "osificación<br>de la entesis", "c": "g", "x": 50, "y": 91, "ax": 49.5, "ay": 50}, {"n": "⑯", "t": "Cámara anterior", "s": "células<br>inflamatorias", "c": "d", "x": 76, "y": 91, "ax": 75, "ay": 56.6}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = células que inflaman</b> (macrófago, linfocitos, plasmocito), <b class=\"d\">rojo = lo que destruye</b> (pannus, osteoclasto, cristales, neutrófilo), gris = estructuras de referencia.", "<b>Izquierda:</b> la sinovial engrosada, con vasos nuevos (<mark>neoangiogénesis</mark>), avanza como una lengua sobre el cartílago. Sin <b>lubricina</b> el fibroblasto se adhiere y la MMP-14 rompe el colágeno tipo II.", "<b>Centro:</b> el macrófago M1 libera TNF; el Th17 libera IL-17, que induce <mark>RANKL</mark> y convierte osteoblastos en osteoclastos <span class=\"lt2\">B</span>; el plasmocito fabrica factor reumatoide y anti-CCP <span class=\"lt2\">A</span>.", "<b>Derecha:</b> en la gota no hay autoanticuerpos: el cristal de urato activa el <mark>NLRP3</mark> y sale IL-1β; el neutrófilo que lo fagocita muere y vacía sus lisosomas."], "recordar": "AR = <b>sinovial</b> (pannus, TNF, anti-CCP); espondilitis = <b>entesis</b> (HLA-B27, IL-17/23); gota = <b>cristal</b> (NLRP3, IL-1β); reactiva y lúpica = <b>complejos inmunes</b>; fiebre reumática = <b>mimetismo</b>."}, "numeros": [{"l": "A", "html": "<b>Autoanticuerpos</b>: anti-CCP con especificidad <b class=\"a\">95 %</b> y sensibilidad <b class=\"n\">84 %</b>; factor reumatoide con sensibilidad <b class=\"b\">66 %</b> y especificidad <b class=\"n\">87 %</b>.", "rango": null}, {"l": "B", "html": "<b>Pronóstico</b>: la AR reduce la expectativa de vida <b class=\"a\">3 a 10 años</b>; relación mujer:hombre <b class=\"a\">5:1</b>; nódulos en el <b class=\"n\">20 %</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del cigarrillo al hueso roto", "subtitulo": "estímulo → autoanticuerpos → sinovitis → pannus y osteoclastos → deformidad", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> el <mark>cigarrillo</mark> activa PADI4 (enzima PAD) y la arginina de proteínas de la mucosa y la sinovial se vuelve citrulina; pesa más en portadores de HLA-DRB1 *0401 y *0404.", "pr": "proteínas citrulinadas que el sistema inmune ve como extrañas.", "pr_tit": "Produce:", "rf": "Pregunta ②", "color": "p1"}, {"t": "2. Fase prearticular", "m": "<b>Por qué:</b> los linfocitos B producen <mark>anti-CCP</mark> y factor reumatoide (IgM anti-Fc de IgG) años antes del dolor.", "pr": "autoanticuerpos en sangre sin artritis todavía.", "pr_tit": "Produce:", "rf": "Preguntas ①③ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Sinovitis", "m": "<b>Qué produce:</b> macrófagos M1 liberan <mark>TNF</mark>, IL-1 e IL-6; llegan neutrófilos, NK y Th1; los Treg están, pero no funcionan; la sinovial se engrosa con vasos nuevos.", "pr": "artritis simétrica de manos con rigidez matutina de más de una hora.", "pr_tit": "Produce:", "rf": "Preguntas ④⑧", "color": "p3"}, {"t": "4. Pannus y erosión", "m": "<b>Qué pasa:</b> el fibroblasto invade el cartílago sin lubricina (MMP-14); la IL-17 de los Th17 induce <mark>RANKL</mark> y aparecen osteoclastos que reabsorben el hueso.", "pr": "erosiones y deformidades (dedos en botonera).", "pr_tit": "Produce:", "rf": "Pregunta ⑤ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Más allá de la articulación", "m": "<b>Si progresa:</b> nódulos, síntomas secos, vasculitis; <mark>síndrome de Felty</mark> (esplenomegalia + neutropenia); más infarto, ACV y linfoma. El tratamiento (metotrexate, anti-TNF) predispone a infecciones y TB.", "pr": "la vida se acorta de 3 a 10 años.", "pr_tit": "Produce:", "rf": "Preguntas ⑥⑦", "color": "p4"}], "extra": [{"html": "💊 <b>Biológicos:</b> anti-TNF (infliximab, adalimumab, golimumab, certolizumab, etanercept); <b>abatacept</b> (CTLA-4, frena al LT); <b>rituximab</b> (anti-CD20, quita LB); <b>tocilizumab</b> (anti-receptor de IL-6); <b>tofacitinib</b> (inhibidor oral de JAK).", "k": ""}, {"html": "🦴 <b>Otras artritis:</b> reactiva = complejos de un gramnegativo a distancia, articulación <b>estéril</b> (+ uretritis + conjuntivitis = Reiter); espondilitis = entesitis centrífuga, HLA-B27 (más del 90 % de los pacientes; solo enferma el 5 % de los portadores), IL-17/IL-23, uveítis; gota = urato → NLRP3 → IL-1β, C5a por vía alterna; colchicina frena los lisosomas del neutrófilo; fiebre reumática = hialuronidasa estreptocócica ≈ sinovial; lupus = complejos, <b>sin erosiones</b>; colitis ulcerativa = artritis aguda monoarticular en el 20 %.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Cómo empeora la AR", "pasos": ["anti-CCP sin síntomas", "sinovitis simétrica de manos", "pannus y erosiones", "deformidad en botonera", "Felty, vasculitis, infarto o linfoma"]}], "html": "", "fuente": "Fuente: tu teoría — clase 40 (etiología, inmunidad innata y adquirida, daño articular, clínica, diagnóstico y tratamiento) y clase 41 (artritis reactiva, espondilitis, gota, fiebre reumática, lupus articular)."}, "preguntas": [{"n": 1, "id": "IN17-011", "c": "i", "tema": "Inmunodiagnóstico", "pregunta": "En la artritis reumatoide, el autoanticuerpo que aparece en la fase prearticular y tiene especificidad del 95 % es:", "opciones": ["a. Factor reumatoide IgM.", "b. Anticuerpo antinuclear.", "c. Anticuerpo anti-glucosa-6-fosfato isomerasa.", "d. Anti-ADN de doble cadena.", "e. Anti-péptido cíclico citrulinado (anti-CCP)."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Anti-CCP (ACPA): especificidad 95 %, sensibilidad 84 %.", "sin_banco": true, "ok": "", "x": "El plasmocito de la ampliación (punto Ⓐ) fabrica los anti-CCP años antes del dolor: especificidad del <mark>95 %</mark>, mayor que la del factor reumatoide. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN17-012", "c": "i", "tema": "Factores ambientales", "pregunta": "El cigarrillo es el principal factor ambiental de la artritis reumatoide porque:", "opciones": ["a. Destruye la lubricina del cartílago.", "b. Bloquea el receptor de IL-6.", "c. Inhibe a los linfocitos Th17.", "d. Activa PADI4 (enzima PAD), que citruliniza proteínas de la mucosa y la sinovial.", "e. Disminuye la producción de TNF en los macrófagos."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Activa PADI4 y citruliniza proteínas, sobre todo en portadores de HLA-DRB1 *0401 y *0404.", "sin_banco": true, "ok": "", "x": "La enzima PAD cambia la arginina por <mark>citrulina</mark>; esas proteínas «nuevas» se vuelven antigénicas y el organismo fabrica ACPA. El riesgo es mayor si la persona porta el <mark>epítopo compartido</mark> HLA-DRB1 *0401 o *0404, <span class=\"cx\">porque</span> presenta mejor esos péptidos. <span class=\"cx\">Así que</span> <span class=\"res\">cigarrillo + HLA-DRB1 = ACPA</span>.", "truco": "Fumar «citruliniza»: humo → PAD → citrulina → anti-CCP.", "veces": 0}, {"n": 3, "id": "IN17-013", "c": "i", "tema": "Inmunopatología: linfocitos B y autoanticuerpos", "pregunta": "¿Qué es el factor reumatoide y cuál es su rendimiento diagnóstico?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Un autoanticuerpo IgM dirigido contra la fracción Fc de las IgG; sensibilidad 66 % y especificidad 87 %.", "sin_banco": true, "ok": "", "x": "El factor reumatoide es un <mark>anticuerpo contra otro anticuerpo</mark>: una IgM que reconoce la cola (Fc) de la IgG y forma complejos en la sinovial. Es útil, pero sale positivo en solo dos de cada tres pacientes, <span class=\"cx\">en cambio</span> el anti-CCP es <span class=\"res\">más específico (95 %)</span>.", "truco": "FR = IgM que muerde la cola (Fc) de la IgG.", "veces": 0}, {"n": 4, "id": "IN17-014", "c": "i", "tema": "Inmunopatología: inmunidad innata", "pregunta": "La citoquina responsable de los principales daños articulares en la artritis reumatoide, producida sobre todo por macrófagos M1, es:", "opciones": ["a. TNF.", "b. IL-10.", "c. IL-4.", "d. TGF-β.", "e. IFN-α."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. TNF, que además estimula IL-6, IL-8 y GM-CSF.", "sin_banco": true, "ok": "", "x": "Es el macrófago grande de la ampliación: el <mark>M1</mark> libera TNF, que activa fibroblastos y condrocitos. <span class=\"cx\">Por eso</span> los biológicos más usados son <span class=\"res\">anti-TNF</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN17-015", "c": "d", "tema": "Daño articular: hueso", "pregunta": "¿Cómo se produce la erosión del hueso subcondral en la artritis reumatoide?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Las citoquinas sinoviales (IL-17, IL-1, IL-6, IL-21) inducen RANKL, que transforma osteoblastos en osteoclastos; estos invaden el periostio y reabsorben el hueso.", "sin_banco": true, "ok": "", "x": "Mira el osteoclasto multinucleado en su laguna (punto Ⓑ): la IL-17 y otras citoquinas inducen <mark>RANKL</mark>, que convierte osteoblastos en osteoclastos. Así <span class=\"res\">se erosiona el hueso</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN17-016", "c": "d", "tema": "Tratamiento", "pregunta": "Sobre los fármacos de la artritis reumatoide, es FALSO:", "opciones": ["a. El tofacitinib es un inhibidor oral de la Janus kinasa (JAK).", "b. El abatacept es una molécula de fusión CTLA-4 que inhibe la activación de linfocitos T.", "c. El rituximab es anti-CD20 y depleta los linfocitos B.", "d. El metotrexate se usa en promedio a 20 mg semanales.", "e. El infliximab bloquea el receptor de la IL-6."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es falso: el infliximab bloquea el TNF; el que bloquea el receptor de IL-6 es el tocilizumab.", "sin_banco": true, "ok": "", "x": "Cada biológico apaga un eslabón: <mark>anti-TNF</mark> (infliximab, adalimumab, golimumab, certolizumab, etanercept), <mark>anti-CD20</mark> (rituximab), <mark>CTLA-4</mark> (abatacept) y <mark>anti-IL-6R</mark> (tocilizumab, que puede usarse solo). <span class=\"cx\">Por eso</span> <span class=\"res\">la e es la falsa</span>.", "truco": "Toci = «Tocar la IL-6»; inflixi = «inflamación por TNF».", "veces": 0}, {"n": 7, "id": "IN17-017", "c": "d", "tema": "Manifestaciones clínicas (correlación clínica)", "pregunta": "Mujer con artritis reumatoide erosiva de larga data, nódulos reumatoides y factor reumatoide muy alto. Presenta esplenomegalia y neutropenia por anticuerpos contra neutrófilos. ¿Cuál es el diagnóstico?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome de Felty: esplenomegalia + neutropenia autoinmune en una AR erosiva, con factor reumatoide alto y nodulosis.", "sin_banco": true, "ok": "", "x": "Es una complicación grave y rara de la AR. Los <mark>anticuerpos contra los neutrófilos</mark> los destruyen y el bazo crece; <span class=\"cx\">por eso</span> el paciente se infecta con facilidad. Se ve en la enfermedad <span class=\"res\">más agresiva: erosiva, con FR alto y nódulos</span>.", "truco": "Felty: «Falta» de neutrófilos + bazo «Feo» (grande).", "veces": 0}, {"n": 8, "id": "IN17-018", "c": "g", "tema": "Comorbilidad e inmunosupresión", "pregunta": "Antes de iniciar un bloqueador del TNF en un paciente con artritis reumatoide es obligatorio descartar:", "opciones": ["a. Déficit de IgA.", "b. Hipotiroidismo autoinmune.", "c. Tuberculosis latente.", "d. Portación de HLA-B27.", "e. Gota asociada."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Tuberculosis latente, porque el anti-TNF puede reactivarla (sobre todo extrapulmonar).", "sin_banco": true, "ok": "", "x": "El TNF mantiene <mark>cerrado el granuloma</mark> que encierra al bacilo de Koch. Si se bloquea, el granuloma se desarma y la tuberculosis latente se reactiva, muchas veces fuera del pulmón. <span class=\"cx\">Por eso</span> <span class=\"res\">se busca TB latente antes del biológico</span>.", "truco": "Sin TNF, el granuloma se abre y sale el Koch.", "veces": 0}, {"n": 9, "id": "IN17-019", "c": "g", "tema": "Manifestaciones clínicas: articular", "pregunta": "Son características del compromiso articular de la artritis reumatoide, EXCEPTO:", "opciones": ["a. Compromiso simétrico e inflamatorio.", "b. Rigidez matutina que dura más de una hora.", "c. Afección de metacarpofalángicas (2.ª y 3.ª) e interfalángicas proximales.", "d. Inicio en las articulaciones sacroilíacas con avance centrífugo hacia la periferia.", "e. Compromiso de muñecas, metatarsofalángicas y rodillas."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Ese patrón centrífugo axial es de la espondilitis anquilosante, no de la AR.", "sin_banco": true, "ok": "", "x": "La AR empieza en <mark>articulaciones pequeñas periféricas</mark> de manos y pies, de forma simétrica, con rigidez de más de una hora. <span class=\"cx\">En cambio</span>, la espondilitis anquilosante empieza en la <mark>columna y las sacroilíacas</mark> y avanza hacia afuera. <span class=\"cx\">Por eso</span> <span class=\"res\">la d no corresponde</span>.", "truco": "AR: de las manos hacia adentro; espondilitis: de la columna hacia afuera.", "veces": 0}, {"n": 10, "id": "IN17-020", "c": "g", "tema": "Artritis reactivas", "pregunta": "Sobre las artritis reactivas, es FALSO:", "opciones": ["a. Se desencadenan por infecciones gastrointestinales o urogenitales por gramnegativos.", "b. Son producidas por complejos inmunes formados a distancia.", "c. El germen se aísla en el cultivo del líquido sinovial y se trata con antibiótico intraarticular.", "d. Pueden acompañarse de uretritis y conjuntivitis (síndrome de Reiter).", "e. Los agentes incluyen clamidias, yersinias, salmonelas, shigelas y campilobacter."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es falso: la articulación es estéril; el tratamiento de la fase articular es antiinflamatorio.", "sin_banco": true, "ok": "", "x": "La infección ocurre <mark>lejos de la articulación</mark> (intestino o uretra); lo que llega a la rodilla son los complejos inmunes, no el germen. <span class=\"cx\">Por eso</span> el cultivo sale negativo y el tratamiento articular es <span class=\"res\">antiinflamatorio, no antibiótico</span>.", "truco": "Reiter: «no puedo orinar, no puedo ver, no puedo trepar».", "veces": 0}, {"n": 11, "id": "IN17-021", "c": "g", "tema": "Espondilitis anquilosante", "pregunta": "En la espondilitis anquilosante, ¿qué porcentaje de pacientes es HLA-B27 positivo y qué porcentaje de portadores del HLA-B27 enferma?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Más del 90 % de los pacientes es HLA-B27 positivo, pero solo el 5 % de los portadores desarrolla la enfermedad.", "sin_banco": true, "ok": "", "x": "El HLA-B27 es un marcador muy <mark>sensible</mark> (casi todos los enfermos lo tienen), pero la mayoría de quienes lo portan nunca enferman. <span class=\"cx\">Así que</span> hacen falta otros factores, como la <mark>reacción cruzada con Klebsiella pneumoniae</mark>. <span class=\"cx\">Por eso</span> <span class=\"res\">un B27 positivo solo no hace el diagnóstico</span>.", "truco": "B27: «9 de 10 enfermos lo tienen; 1 de 20 portadores enferma».", "veces": 0}, {"n": 12, "id": "IN17-022", "c": "d", "tema": "Espondilitis anquilosante", "pregunta": "El sitio anatómico de la inflamación en la espondilitis anquilosante y las citoquinas elevadas en suero son:", "opciones": ["a. La membrana sinovial; IL-4 e IL-13.", "b. La entesis (unión de tendones y ligamentos al hueso); IL-17 e IL-23.", "c. El cartílago articular; IFN-α.", "d. El disco intervertebral; IL-10 y TGF-β.", "e. La médula ósea; IL-5."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La entesis, con IL-17 e IL-23 (espectro Th17).", "sin_banco": true, "ok": "", "x": "Es la escena de la derecha: el <mark>cristal de urato</mark> activa el inflamasoma NLRP3 y sale IL-1β; no hay autoanticuerpos ni complejos. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 13, "id": "IN17-023", "c": "d", "tema": "Gota", "pregunta": "El mecanismo inmunológico central de la crisis de gota es:", "opciones": ["a. Depósito de complejos inmunes por un germen a distancia.", "b. Mimetismo molecular con la hialuronidasa del estreptococo.", "c. Autoanticuerpos IgM contra el Fc de la IgG.", "d. Activación del inflamasoma NLRP3 por cristales de urato monosódico, con liberación de IL-1β.", "e. Hipersensibilidad tipo I mediada por IgE."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los cristales de urato activan el inflamasoma NLRP3 y se libera IL-1β.", "sin_banco": true, "ok": "", "x": "El neutrófilo de la ampliación (círculo de arriba a la derecha) <mark>se come el cristal y revienta</mark>, vaciando lisosomas. La colchicina frena esa liberación, <span class=\"cx\">así que</span> <span class=\"res\">corta el daño, no baja el urato</span>.", "truco": "", "veces": 0}, {"n": 14, "id": "IN17-024", "c": "g", "tema": "Gota: tratamiento", "pregunta": "¿Por qué la colchicina mejora el ataque agudo de gota?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque inhibe la liberación de lisosomas de los neutrófilos que fagocitaron cristales de urato, y así evita el daño de los tejidos vecinos.", "sin_banco": true, "ok": "", "x": "El neutrófilo <mark>se come los cristales</mark> y muere, vaciando lisosomas y enzimas que dañan los tejidos y causan el dolor intenso del dedo gordo. La colchicina frena esa liberación, <span class=\"cx\">así que</span> <span class=\"res\">corta el daño del neutrófilo</span>, no baja el ácido úrico.", "truco": "Colchicina «cierra la bolsa» de lisosomas del neutrófilo.", "veces": 0}, {"n": 15, "id": "IN17-025", "c": "g", "tema": "Fiebre reumática y lupus articular", "pregunta": "¿Cuál es el mecanismo de la artritis en la fiebre reumática?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Antigenicidad cruzada (mimetismo molecular) entre la hialuronidasa de la cápsula del estreptococo β-hemolítico del grupo A y el tejido sinovial.", "sin_banco": true, "ok": "", "x": "Tras una faringitis, los anticuerpos contra el <mark>estreptococo del grupo A</mark> reconocen también la sinovial <span class=\"cx\">porque</span> se parece a la hialuronidasa de la cápsula. <span class=\"cx\">Por eso</span> aparece sinovitis sin germen en la articulación. Es el mismo principio que en el corazón: <span class=\"res\">mimetismo molecular</span>.", "truco": "Estrepto «se disfraza» de sinovial.", "veces": 0}, {"n": 16, "id": "IN17-026", "c": "g", "tema": "Espondilitis anquilosante (correlación clínica)", "pregunta": "Varón de 25 años con dolor lumbar de predominio nocturno y rigidez que mejora con el ejercicio; ahora presenta ojo rojo doloroso por uveítis. ¿Qué diagnóstico y qué marcador genético esperas?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Espondilitis anquilosante con uveítis; todos los pacientes con espondilitis y uveítis son HLA-B27 positivos.", "sin_banco": true, "ok": "", "x": "Un varón joven con <mark>dolor axial inflamatorio</mark> orienta a espondilitis anquilosante, que afecta más a hombres. La uveítis es su asociación clínica frecuente: quien tiene ambas es HLA-B27 positivo en el <mark>100 %</mark>, <span class=\"cx\">en cambio</span> solo la mitad de las uveítis aisladas lo son. <span class=\"cx\">Por eso</span> <span class=\"res\">se pide HLA-B27</span> (el dolor nocturno que mejora con ejercicio es dato de literatura).", "truco": "Columna + ojo rojo = B27 seguro.", "veces": 0}], "tabla": {"cab": ["", "Artritis reumatoide", "Espondilitis", "Gota", "Reactiva"], "filas": [["Dónde", "Sinovial (pannus)", "Entesis axial", "Espacio articular", "Sinovial estéril"], ["Mecanismo", "TNF, Th17, anti-CCP", "IL-17/IL-23", "Urato → NLRP3 → IL-1β", "Complejos a distancia"], ["Marcador", "Anti-CCP, FR", "HLA-B27 (>90 %)", "Cristales", "Gramnegativo previo"], ["Patrón", "Simétrico, manos", "Centrífugo, varones", "Agudo, dedo gordo", "Semanas a meses"], ["🔑 Para diferenciar", "Erosiona hueso", "Columna + uveítis", "Sin autoanticuerpos", "Sin germen en la articulación"]]}, "fuente": "Fuente: tu teoría — clase 40 (Artritis reumatoide) y clase 41 (Otras artritis autoinmunes), Rojas 17.ª ed."}, {"n": 32, "slug": "Lupus_eritematoso_sistemico", "titulo": "Lupus eritematoso sistémico", "subtitulo": "sol, ADN expuesto, interferón y complejos inmunes que caen en el riñón", "grupo": "g18", "lema": "La idea: el <mark>lupus</mark> es el prototipo de enfermedad autoinmune sistémica, y todo gira alrededor del <b>ADN propio que queda a la vista</b>. El sol (UVB) mata queratinocitos, los cuerpos apoptóticos no se limpian (falta C1q) y el neutrófilo muere lanzando una red de ADN (<mark>NETOSIS</mark>). Ese ADN enciende a la célula dendrítica plasmocitoide, que produce exceso de <u>interferón alfa</u>, y a los linfocitos B, que fabrican anti-ADN de doble cadena, anti-Sm y más de 100 autoanticuerpos. Los complejos inmunes caen en la piel, las articulaciones, las serosas y sobre todo en el <b>riñón</b>. En la imagen verás de izquierda a derecha: la piel dañada por el sol, la red de ADN del neutrófilo con la célula dendrítica y el plasmocito, y el glomérulo con depósitos de complejos inmunes.", "img": "img/32.webp", "mini": "img/mini/32.webp", "ratio": 1.5, "etiquetas": [{"n": "④", "t": "Luz UVB", "s": "vuelve inmunogénico<br>el ADN", "c": "i", "x": 0.5, "y": 6, "ax": 9, "ay": 20, "al": "l"}, {"n": "③", "t": "NETOSIS", "s": "el neutrófilo lanza<br>una red de ADN", "c": "i", "x": 30, "y": 6, "ax": 34, "ay": 33}, {"n": "③", "t": "Red de ADN", "s": "ADN + LL37:<br>lo ve el TLR-9", "c": "i", "x": 47, "y": 6, "ax": 46, "ay": 38}, {"n": "③", "t": "Dendrítica", "s": "plasmocitoide:<br>exceso de IFN-α", "c": "i", "x": 66, "y": 6, "ax": 60, "ay": 28}, {"n": "⑨", "t": "Depósitos", "s": "complejos inmunes<br>consumen C3 y C4", "c": "d", "x": 99.5, "y": 6, "ax": 76, "ay": 30, "al": "r"}, {"n": "④", "t": "Queratinocitos", "s": "apoptosis:<br>ADN expuesto", "c": "g", "x": 0.5, "y": 91, "ax": 15, "ay": 43, "al": "l"}, {"n": "", "t": "Linfocito B", "s": "autorreactivo", "c": "d", "x": 21, "y": 91, "ax": 35, "ay": 64}, {"n": "①②", "t": "Plasmocito", "s": "anti-ADNdc,<br>anti-Sm", "c": "d", "x": 37, "y": 91, "ax": 45, "ay": 66}, {"n": "①②", "t": "Complejos", "s": "ADN + anticuerpo<br>viajan en sangre", "c": "d", "x": 57, "y": 91, "ax": 60, "ay": 66, "d": "A"}, {"n": "⑨", "t": "Glomérulo", "s": "nefritis lúpica", "c": "d", "x": 77, "y": 91, "ax": 83, "ay": 50, "d": "B"}, {"n": "", "t": "Mesangio", "s": "también recibe<br>complejos", "c": "d", "x": 99.5, "y": 91, "ax": 89, "ay": 57, "al": "r"}], "diapos": [{"img": "img/32.webp", "ratio": 1.5, "titulo": "NETOSIS, piel al sol y riñón", "texto": "La luz UVB y la <mark>NETOSIS</mark> exponen ADN propio ③④; los complejos de anti-ADN se depositan en el glomérulo ⑨.", "etiquetas": [{"n": "④", "t": "Luz UVB", "s": "vuelve inmunogénico<br>el ADN", "c": "i", "x": 0.5, "y": 6, "ax": 9, "ay": 20, "al": "l"}, {"n": "③", "t": "NETOSIS", "s": "el neutrófilo lanza<br>una red de ADN", "c": "i", "x": 30, "y": 6, "ax": 34, "ay": 33}, {"n": "③", "t": "Red de ADN", "s": "ADN + LL37:<br>lo ve el TLR-9", "c": "i", "x": 47, "y": 6, "ax": 46, "ay": 38}, {"n": "③", "t": "Dendrítica", "s": "plasmocitoide:<br>exceso de IFN-α", "c": "i", "x": 66, "y": 6, "ax": 60, "ay": 28}, {"n": "⑨", "t": "Depósitos", "s": "complejos inmunes<br>consumen C3 y C4", "c": "d", "x": 99.5, "y": 6, "ax": 76, "ay": 30, "al": "r"}, {"n": "④", "t": "Queratinocitos", "s": "apoptosis:<br>ADN expuesto", "c": "g", "x": 0.5, "y": 91, "ax": 15, "ay": 43, "al": "l"}, {"n": "", "t": "Linfocito B", "s": "autorreactivo", "c": "d", "x": 21, "y": 91, "ax": 35, "ay": 64}, {"n": "①②", "t": "Plasmocito", "s": "anti-ADNdc,<br>anti-Sm", "c": "d", "x": 37, "y": 91, "ax": 45, "ay": 66}, {"n": "①②", "t": "Complejos", "s": "ADN + anticuerpo<br>viajan en sangre", "c": "d", "x": 57, "y": 91, "ax": 60, "ay": 66, "d": "A"}, {"n": "⑨", "t": "Glomérulo", "s": "nefritis lúpica", "c": "d", "x": 77, "y": 91, "ax": 83, "ay": 50, "d": "B"}, {"n": "", "t": "Mesangio", "s": "también recibe<br>complejos", "c": "d", "x": 99.5, "y": 91, "ax": 89, "ay": 57, "al": "r"}]}, {"img": "img/32_2.webp", "ratio": 1.5, "titulo": "Lupus neonatal y Libman-Sacks", "texto": "Los anti-Ro y anti-La maternos cruzan la placenta en las semanas 18-24 <span class=\"lt2\">C</span> y bloquean la conducción fetal ⑥; en el adulto, verrugas estériles en ambas caras de la mitral = <mark>Libman-Sacks</mark> ⑧.", "etiquetas": [{"n": "⑥", "t": "Placenta", "s": "la IgG materna<br>la cruza", "c": "i", "x": 0.5, "y": 6, "ax": 11.7, "ay": 32, "d": "C", "al": "l"}, {"n": "⑥", "t": "Anti-Ro y anti-La", "s": "maternos<br>(IgG)", "c": "i", "x": 24, "y": 6, "ax": 19.5, "ay": 41}, {"n": "⑥", "t": "Nodo AV fetal", "s": "bloqueo cardíaco<br>congénito", "c": "d", "x": 42, "y": 6, "ax": 39.7, "ay": 48}, {"n": "⑧", "t": "Válvula aórtica", "s": "también con<br>verrugas", "c": "g", "x": 62, "y": 6, "ax": 65, "ay": 28}, {"n": "⑧", "t": "Vegetación", "s": "fibrina y<br>complejos inmunes", "c": "d", "x": 99.5, "y": 6, "ax": 90.5, "ay": 29, "al": "r"}, {"n": "⑥", "t": "Vellosidad", "s": "trofoblasto", "c": "i", "x": 0.5, "y": 91, "ax": 24.7, "ay": 60.5, "al": "l"}, {"n": "⑥", "t": "Haz de His", "s": "conducción<br>fetal dañada", "c": "d", "x": 35, "y": 91, "ax": 42, "ay": 62.5}, {"n": "⑧", "t": "Libman-Sacks", "s": "verrugas estériles<br>en ambas caras", "c": "d", "x": 62, "y": 91, "ax": 72, "ay": 46}, {"n": "⑧", "t": "Válvula mitral", "s": "cuerdas<br>tendinosas", "c": "g", "x": 85, "y": 91, "ax": 78, "ay": 58.6}]}, {"img": "img/32_3.webp", "ratio": 1.5, "titulo": "Anti-ADN en el cerebro y belimumab", "texto": "El anti-ADNdc reacciona cruzado con el <mark>receptor NMDA</mark> del hipocampo ②; <span class=\"cx\">en cambio</span>, el <b>belimumab</b> atrapa BLyS y el linfocito B autorreactivo muere ⑩.", "etiquetas": [{"n": "②", "t": "Hipocampo", "s": "memoria<br>y ánimo", "c": "g", "x": 0.5, "y": 6, "ax": 9.8, "ay": 49, "al": "l"}, {"n": "②", "t": "Terminal presináptica", "s": "libera<br>glutamato", "c": "g", "x": 30, "y": 6, "ax": 37.8, "ay": 29}, {"n": "⑩", "t": "Belimumab", "s": "anticuerpo<br>monoclonal", "c": "i", "x": 55, "y": 6, "ax": 56.6, "ay": 29}, {"n": "⑩", "t": "BLyS", "s": "atrapado: no<br>llega al LB", "c": "i", "x": 99.5, "y": 6, "ax": 83.3, "ay": 39, "al": "r"}, {"n": "②", "t": "Receptor NMDA", "s": "reconocido por<br>el anti-ADNdc", "c": "d", "x": 14, "y": 91, "ax": 33, "ay": 49}, {"n": "②", "t": "Anti-ADNdc", "s": "reacción<br>cruzada", "c": "d", "x": 36, "y": 91, "ax": 39, "ay": 43}, {"n": "⑩", "t": "Linfocito B", "s": "autorreactivo", "c": "i", "x": 62, "y": 91, "ax": 65, "ay": 55}, {"n": "⑩", "t": "LB apoptótico", "s": "sin BLyS<br>muere", "c": "d", "x": 99.5, "y": 91, "ax": 88.5, "ay": 58.6, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = innata que enciende</b> (sol, NETOSIS, célula dendrítica plasmocitoide, IFN-α), <b class=\"d\">rojo = adquirida que daña</b> (linfocito B, autoanticuerpos, complejos en el glomérulo), gris = referencias.", "<b>Izquierda:</b> la <mark>UVB</mark> vuelve inmunogénico el ADN; los fragmentos se unen al péptido LL37 y el TLR-9 los reconoce. <span class=\"cx\">Por eso</span> el eritema aparece en zonas expuestas al sol.", "<b>Centro:</b> el IFN-α hace morir al neutrófilo por <mark>NETOSIS</mark>; su ADN vuelve a estimular a la dendrítica (más IFN-α) y al linfocito B (anti-ADN): un círculo vicioso.", "<b>Derecha:</b> los complejos inmunes se depositan en el mesangio y en las superficies subendotelial y subepitelial; consumen complemento, <span class=\"cx\">así que</span> <mark>C3 y C4 bajos</mark> indican actividad <span class=\"lt2\">B</span>."], "recordar": "Sol + basura nuclear sin limpiar → NETOSIS → IFN-α → anti-ADNdc → complejos en el riñón. Anti-Sm = el más específico; anti-ADNdc = el más patogénico; ANA = sensible, poco específico."}, "numeros": [{"l": "A", "html": "<b>Autoanticuerpos</b>: anti-ADNdc <b class=\"a\">70–80 %</b>; anti-Sm <b class=\"n\">30 %</b> (el más específico); anti-Ro <b class=\"n\">40 %</b>; antinucleosoma <b class=\"a\">100 %</b> en el lupus por fármacos.", "rango": null}, {"l": "B", "html": "<b>Nefritis lúpica</b>: <b class=\"a\">50 %</b> de los latinoamericanos frente a <b class=\"n\">30 %</b> de los europeos; compromiso renal global <b class=\"n\">35–60 %</b>.", "rango": null}, {"l": "C", "html": "<b>Lupus neonatal</b>: paso transplacentario de anti-Ro y anti-La en las semanas <b class=\"a\">18–24</b>; el <b class=\"a\">60 %</b> requiere marcapasos.", "rango": {"min": 0, "max": 40, "unidad": "semanas de gestación", "zonas": [[18, 24, "a"]], "marcas": [18, 24]}}], "escalas": [], "cadena": {"titulo": "Del sol al riñón", "subtitulo": "disparador → basura nuclear → interferón → autoanticuerpos → complejos inmunes", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Terreno y disparador", "m": "<b>Qué pasa:</b> genes (<mark>HLA-DR3</mark>, déficit de C1q, C2 o C4), estrógenos altos con andrógenos bajos (Klinefelter), fármacos que desmetilan el ADN y la <mark>luz UVB</mark>, que mata queratinocitos. Afecta a 20–150 por 100 000, con más de 10 mujeres por cada hombre.", "pr": "aparecen cuerpos apoptóticos con ADN expuesto.", "pr_tit": "Produce:", "rf": "Preguntas ④⑤⑦", "color": "p1"}, {"t": "2. Basura sin limpiar", "m": "<b>Por qué:</b> la fagocitosis de cuerpos apoptóticos está disminuida y el complemento es deficiente, <span class=\"cx\">así que</span> el ADN persiste y se une a <mark>LL37</mark>.", "pr": "el TLR-7 y el TLR-9 reconocen ácidos nucleicos propios.", "pr_tit": "Produce:", "rf": "Pregunta ③", "color": "p2"}, {"t": "3. Interferón y NETOSIS", "m": "<b>Qué produce:</b> la célula dendrítica plasmocitoide fabrica exceso de <mark>IFN-α</mark> (firma de interferón); el IFN-α hace morir al neutrófilo por NETOSIS y su ADN reactiva a la dendrítica.", "pr": "un círculo vicioso innato que alimenta a los linfocitos B.", "pr_tit": "Produce:", "rf": "Pregunta ③", "color": "p3"}, {"t": "4. Autoanticuerpos", "m": "<b>Qué pasa:</b> baja la IL-2 (más infecciones) y suben IL-6, IL-17, IL-21 e IL-23; el linfocito B produce <mark>anti-ADNdc</mark>, anti-Sm, anti-Ro, antifosfolipídicos y antileucocitarios.", "pr": "daño de piel, riñón, cerebro (NMDAR), sangre y coagulación.", "pr_tit": "Produce:", "rf": "Preguntas ①② · punto <span class=\"lt2\">A</span>", "color": "p4"}, {"t": "5. Complejos y órganos", "m": "<b>Si progresa:</b> complejos inmunes en el glomérulo (<mark>nefritis lúpica</mark>), sinovial sin erosión, serosas (pleuritis 40 %), válvulas (Libman-Sacks), SNC; el complemento baja con la actividad.", "pr": "insuficiencia renal, psicosis, convulsiones, citopenias.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨ · punto <span class=\"lt2\">B</span>", "color": "p4"}], "extra": [{"html": "👶 <b>Formas especiales:</b> lupus neonatal (anti-Ro/anti-La, bloqueo cardíaco congénito; cruzan la placenta en las semanas 18–24 y el 60 % necesita marcapasos) ⑥; lupus por fármacos (procainamida, hidralazina, isoniazida, fenitoína, cloroquina, penicilamina, anti-TNF), que se resuelve al suspenderlos; el embarazo y el puerperio lo exacerban.", "k": ""}, {"html": "💊 <b>Tratamiento:</b> AINE, esteroides, antimaláricos y citotóxicos; en casos seleccionados micofenolato, rituximab, plasmaféresis, gammaglobulina y <mark>belimumab</mark> (anti-BLyS). Evitar el sol, el tabaco y el sobrepeso.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Cómo se agrava el lupus", "pasos": ["piel y articulaciones (83 %)", "citopenias (75 %)", "serositis y Libman-Sacks", "nefritis lúpica con complemento bajo", "compromiso neuropsiquiátrico"]}], "html": "", "fuente": "Fuente: tu teoría — clase 42 (epidemiología, etiología, inmunidad innata y NETOSIS, linfocitos T y B, autoanticuerpos, manifestaciones, formas especiales, diagnóstico y tratamiento)."}, "preguntas": [{"n": 1, "id": "IN18-001", "c": "d", "tema": "Trastornos de linfocitos B: autoanticuerpos", "pregunta": "El autoanticuerpo más específico del lupus eritematoso sistémico, aunque presente solo en el 30 % de los pacientes, es:", "opciones": ["a. Anti-Sm.", "b. Anticuerpo antinuclear (ANA).", "c. Anti-Ro (SSA).", "d. ANCA.", "e. Antinucleosoma."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Anti-Sm.", "sin_banco": true, "ok": "", "x": "Los ANA salen en casi todos, <span class=\"cx\">por eso</span> son <mark>sensibles pero poco específicos</mark>. El <mark>anti-Sm</mark> es raro (30 %) pero casi exclusivo del LES y daña el riñón. El anti-ADN de doble cadena (70-80 %) es también muy específico y es <span class=\"res\">el más patogénico</span>.", "truco": "Sm = «Super marca» de lupus.", "veces": 0}, {"n": 2, "id": "IN18-002", "c": "d", "tema": "Trastornos de linfocitos B: autoanticuerpos", "pregunta": "Los anticuerpos anti-ADN de doble cadena producen manifestaciones neuropsiquiátricas en el LES porque reaccionan en forma cruzada con:", "opciones": ["a. El receptor de acetilcolina de la placa motora.", "b. La mielina de los nervios periféricos.", "c. El receptor muscarínico M3.", "d. El receptor de glutamato NMDAR del hipocampo y las amígdalas.", "e. La β2-glucoproteína I de la neurona."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El receptor NMDAR del cerebro (hipocampo y amígdalas).", "sin_banco": true, "ok": "", "x": "El anti-ADNdc está en el <mark>70-80 %</mark> de los pacientes y daña piel y riñón. <span class=\"cx\">Además</span>, se parece al <mark>receptor NMDA</mark> del cerebro, <span class=\"cx\">así que</span> al unirse altera la función del hipocampo: de ahí los trastornos cognitivos, la psicosis o las convulsiones. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "ADN y NMDA: «casi las mismas letras», por eso se confunden.", "veces": 0}, {"n": 3, "id": "IN18-003", "c": "i", "tema": "Inmunopatología de la inmunidad innata", "pregunta": "¿Qué es la NETOSIS y qué papel tiene en el lupus?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es la muerte del neutrófilo formando redes extracelulares de ADN, inducida por el IFN-α (con LL-37 y HNP). Esos fragmentos de ADN activan las células dendríticas plasmocitoides (TLR-9), que hacen más IFN-α, y a los linfocitos B, que fabrican anti-ADN y anti-LL37.", "sin_banco": true, "ok": "", "x": "Es la red del centro de la imagen: el neutrófilo <mark>lanza su ADN</mark>, la célula dendrítica de al lado lo reconoce por TLR-9 y produce más IFN-α, y el plasmocito fabrica anti-ADN. Así se cierra <span class=\"res\">el círculo vicioso del lupus</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN18-004", "c": "i", "tema": "Etiología: factores ambientales", "pregunta": "El factor ambiental más relevante en el lupus, que vuelve inmunogénico el ADN e induce apoptosis de queratinocitos, es:", "opciones": ["a. El tabaco.", "b. La sílica.", "c. La luz ultravioleta B.", "d. El gluten.", "e. La deficiencia de vitamina D."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. La luz ultravioleta B (exposición solar).", "sin_banco": true, "ok": "", "x": "Mira la izquierda: los rayos UVB matan queratinocitos y liberan <mark>fragmentos de ADN</mark>. <span class=\"cx\">Por eso</span> el sol es el factor ambiental más relevante y <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN18-005", "c": "g", "tema": "Etiología: genética", "pregunta": "La asociación HLA más consistente con el lupus eritematoso sistémico es:", "opciones": ["a. HLA-B27.", "b. HLA-DR3 (DRB1*03:01).", "c. HLA-DRB1*0401.", "d. HLA-DQ8.", "e. HLA-B51."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. HLA-DR3 (DRB1*03:01).", "sin_banco": true, "ok": "", "x": "El LES es poligénico (más de 100 asociaciones), pero el alelo que más se repite es el <mark>HLA-DR3</mark>; DR2 y DR3 favorecen <span class=\"cx\">además</span> los anti-ADN. <span class=\"cx\">En cambio</span>, el B27 es de la espondilitis y el DRB1*0401 de la <span class=\"res\">artritis reumatoide</span>.", "truco": "LES = 3 letras → DR3.", "veces": 0}, {"n": 6, "id": "IN18-006", "c": "d", "tema": "Formas especiales (correlación clínica)", "pregunta": "Recién nacido con bradicardia por bloqueo cardíaco completo. La madre, asintomática, tiene anticuerpos anti-Ro y anti-La. ¿Qué diagnóstico y qué mecanismo explican el cuadro?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Lupus neonatal: los anti-Ro y anti-La maternos (IgG) atraviesan la placenta entre las semanas 18 y 24 y dañan el sistema de conducción cardíaca fetal; el 60 % requiere marcapasos.", "sin_banco": true, "ok": "", "x": "Los anticuerpos son <mark>IgG</mark>, <span class=\"cx\">así que</span> cruzan la placenta; el anti-Ro se fija al tejido de conducción del corazón fetal y lo daña de forma permanente. <span class=\"cx\">Por eso</span> el bloqueo puede verse aunque la madre no tenga síntomas, y <span class=\"res\">6 de cada 10 niños necesitan marcapasos</span>.", "truco": "Ro y La «cruzan el río» placentario y cortan el cable del corazón.", "veces": 0}, {"n": 7, "id": "IN18-007", "c": "g", "tema": "Formas especiales: lupus inducido por fármacos", "pregunta": "Pueden inducir un cuadro lúpico los siguientes fármacos, EXCEPTO:", "opciones": ["a. Procainamida.", "b. Hidralazina.", "c. Isoniazida.", "d. Fenitoína.", "e. Pilocarpina."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Pilocarpina (se usa en el Sjögren para la xerostomía).", "sin_banco": true, "ok": "", "x": "El lupus por fármacos lo dan <mark>procainamida, hidralazina, cloroquina, isoniazida, fenitoína, penicilamina y anti-TNF</mark>; los anticuerpos antinucleosoma están en el 100 %, y el cuadro se resuelve al suspender el fármaco. <span class=\"cx\">En cambio</span>, la pilocarpina es un <span class=\"res\">agonista muscarínico</span> para la boca seca.", "truco": "«Pro-Hidra-Iso-Feni-Peni» dan lupus.", "veces": 0}, {"n": 8, "id": "IN18-008", "c": "d", "tema": "Manifestaciones clínicas", "pregunta": "La lesión cardíaca más característica del lupus eritematoso sistémico es:", "opciones": ["a. Miocardiopatía hipertrófica.", "b. Pericarditis constrictiva calcificada.", "c. Estenosis mitral reumática.", "d. Endocarditis infecciosa por estafilococo.", "e. Endocarditis verrugosa atípica de Libman-Sacks, sobre todo en válvulas mitral y aórtica."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Endocarditis de Libman-Sacks (mitral y aórtica).", "sin_banco": true, "ok": "", "x": "Un tercio de los pacientes tiene compromiso cardíaco (pericarditis, miocarditis, arritmias), pero la lesión <mark>propia del lupus</mark> son verrugas estériles en las válvulas. <span class=\"cx\">Por eso</span> <span class=\"res\">Libman-Sacks</span> es la respuesta; la pleuritis (40 %) es la manifestación pulmonar más frecuente.", "truco": "Libman-Sacks: verrugas «Lupus en la Mitral».", "veces": 0}, {"n": 9, "id": "IN18-009", "c": "d", "tema": "Diagnóstico: actividad frente a infección", "pregunta": "En un paciente con LES y fiebre, ¿cómo orientan la VSG y la PCR entre un brote lúpico y una infección?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La VSG sube en ambos; la PCR responde poco en el brote lúpico, así que una PCR (y procalcitonina) elevada orienta a infección.", "sin_banco": true, "ok": "", "x": "En el glomérulo de la derecha (punto Ⓑ) los complejos <mark>consumen complemento</mark>: C3 y C4 bajan con la actividad, <span class=\"cx\">en cambio</span> la PCR casi no sube. Si la PCR sube, <span class=\"res\">piensa en infección</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN18-010", "c": "d", "tema": "Tratamiento", "pregunta": "¿Qué es el belimumab y por qué sirve en el lupus?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Un anticuerpo monoclonal contra BLyS (estimulador de linfocitos B); al bloquearlo disminuye la supervivencia de los linfocitos B autorreactivos y la producción de autoanticuerpos.", "sin_banco": true, "ok": "", "x": "El BLyS (también llamado BAFF) es el <mark>alimento de supervivencia</mark> del linfocito B. Sin él, los clones autorreactivos mueren antes de convertirse en plasmocitos. <span class=\"cx\">Por eso</span> se suma a los cuatro pilares clásicos: <span class=\"res\">AINE, esteroides, antimaláricos y citotóxicos</span>.", "truco": "Beli-mumab «Bloquea la Vida» del linfocito B.", "veces": 0}], "tabla": {"cab": ["Autoanticuerpo", "Frecuencia", "Qué hace o para qué sirve"], "filas": [["Anti-ADNdc", "70–80 %", "El más patogénico: piel, riñón y SNC (NMDAR)"], ["Anti-Sm", "30 %", "El más específico; daño renal"], ["Anti-Ro (SSA)", "40 %", "Cruza la placenta: bloqueo cardíaco fetal"], ["Antinucleosoma", "60–90 %", "100 % en el lupus por fármacos"], ["Antifosfolipídicos", "Variable", "Frenan la proteína C: trombosis"], ["🔑 Para diferenciar", "ANA = sensible", "Anti-Sm y anti-ADNdc = específicos"]]}, "fuente": "Fuente: tu teoría — clase 42 (Lupus eritematoso sistémico), Rojas 17.ª ed., cap. 42."}, {"n": 33, "slug": "Sjogren_esclerodermia_SAF", "titulo": "Sjögren, esclerodermia y síndrome antifosfolipídico", "subtitulo": "una glándula que se seca, una piel que se endurece y una sangre que coagula de más", "grupo": "g18", "lema": "La idea: tres enfermedades autoinmunes sistémicas con un blanco distinto cada una. En el <mark>síndrome de Sjögren</mark> los linfocitos rodean los conductos de las glándulas exocrinas (<b>epitelitis autoinmune</b>): boca y ojos secos, anti-Ro y anti-La, y un 10 % de linfomas B. En la <mark>esclerodermia</mark> se suman tres pilares —<u>vasculopatía por endotelina-1, fibrosis por exceso de colágeno y autoanticuerpos</u>— y la piel y los órganos se endurecen. En el <mark>síndrome antifosfolipídico</mark> los anticuerpos contra la β2-glucoproteína I y la cardiolipina quitan los frenos de la coagulación: trombosis y pérdidas fetales. En la imagen verás de izquierda a derecha: la glándula salival con su collar de linfocitos, la piel engrosada con una arteriola estrecha y la vena con un trombo y plaquetas cubiertas de anticuerpos.", "img": "img/33.webp", "mini": "img/mini/33.webp", "ratio": 1.5, "etiquetas": [{"n": "①⑦", "t": "Conducto", "s": "Sjögren:<br>epitelitis", "c": "i", "x": 0.5, "y": 6, "ax": 19, "ay": 28, "al": "l"}, {"n": "①⑤", "t": "Collar de LT CD4", "s": "IFN-γ: el epitelio<br>expresa HLA-II", "c": "i", "x": 27, "y": 6, "ax": 27, "ay": 44}, {"n": "⑩", "t": "Calcinosis", "s": "la C de<br>CREST", "c": "g", "x": 45, "y": 6, "ax": 62, "ay": 32}, {"n": "⑬", "t": "Anticuerpo en endotelio", "s": "contra β2GPI", "c": "d", "x": 66, "y": 6, "ax": 77, "ay": 40}, {"n": "⑬", "t": "Plaqueta activada", "s": "se agrega;<br>proteína C apagada", "c": "d", "x": 99.5, "y": 6, "ax": 89.5, "ay": 38, "d": "C", "al": "r"}, {"n": "③", "t": "Anti-M3", "s": "tapa el receptor", "c": "i", "x": 0.5, "y": 91, "ax": 11, "ay": 60, "d": "A", "al": "l"}, {"n": "②④", "t": "Acino destruido", "s": "anti-Ro, anti-La;<br>riesgo de linfoma", "c": "i", "x": 23.5, "y": 91, "ax": 24, "ay": 68}, {"n": "⑨", "t": "Colágeno denso", "s": "fibrosis:<br>piel rígida", "c": "g", "x": 40.5, "y": 91, "ax": 48, "ay": 50}, {"n": "⑪", "t": "Arteriola", "s": "endotelina-1:<br>vasculopatía", "c": "g", "x": 58.5, "y": 91, "ax": 64, "ay": 55, "d": "B"}, {"n": "⑭⑮", "t": "Trombo", "s": "trombosis y<br>pérdidas fetales", "c": "d", "x": 76, "y": 91, "ax": 83, "ay": 56}, {"n": "⑫", "t": "Vena ocluida", "s": "in vivo<br>protrombótico", "c": "d", "x": 99.5, "y": 91, "ax": 95, "ay": 64, "al": "r"}], "diapos": [{"img": "img/33.webp", "ratio": 1.5, "titulo": "Glándula, piel y vena", "texto": "Sjögren: collar de LT CD4 y anti-M3 que apagan la saliva ①③; esclerodermia: <mark>colágeno denso</mark> ⑨; SAF: anticuerpos que <span class=\"res\">trombosan</span> ⑬⑭.", "etiquetas": [{"n": "①⑦", "t": "Conducto", "s": "Sjögren:<br>epitelitis", "c": "i", "x": 0.5, "y": 6, "ax": 19, "ay": 28, "al": "l"}, {"n": "①⑤", "t": "Collar de LT CD4", "s": "IFN-γ: el epitelio<br>expresa HLA-II", "c": "i", "x": 27, "y": 6, "ax": 27, "ay": 44}, {"n": "⑩", "t": "Calcinosis", "s": "la C de<br>CREST", "c": "g", "x": 45, "y": 6, "ax": 62, "ay": 32}, {"n": "⑬", "t": "Anticuerpo en endotelio", "s": "contra β2GPI", "c": "d", "x": 66, "y": 6, "ax": 77, "ay": 40}, {"n": "⑬", "t": "Plaqueta activada", "s": "se agrega;<br>proteína C apagada", "c": "d", "x": 99.5, "y": 6, "ax": 89.5, "ay": 38, "d": "C", "al": "r"}, {"n": "③", "t": "Anti-M3", "s": "tapa el receptor", "c": "i", "x": 0.5, "y": 91, "ax": 11, "ay": 60, "d": "A", "al": "l"}, {"n": "②④", "t": "Acino destruido", "s": "anti-Ro, anti-La;<br>riesgo de linfoma", "c": "i", "x": 23.5, "y": 91, "ax": 24, "ay": 68}, {"n": "⑨", "t": "Colágeno denso", "s": "fibrosis:<br>piel rígida", "c": "g", "x": 40.5, "y": 91, "ax": 48, "ay": 50}, {"n": "⑪", "t": "Arteriola", "s": "endotelina-1:<br>vasculopatía", "c": "g", "x": 58.5, "y": 91, "ax": 64, "ay": 55, "d": "B"}, {"n": "⑭⑮", "t": "Trombo", "s": "trombosis y<br>pérdidas fetales", "c": "d", "x": 76, "y": 91, "ax": 83, "ay": 56}, {"n": "⑫", "t": "Vena ocluida", "s": "in vivo<br>protrombótico", "c": "d", "x": 99.5, "y": 91, "ax": 95, "ay": 64, "al": "r"}]}, {"img": "img/33_2.webp", "ratio": 1.5, "titulo": "CREST y vaso de la esclerodermia", "texto": "*C*alcinosis, *R*aynaud, *E*sófago, *S*clerodactilia, *T*elangiectasias = forma limitada (anti-centrómero) ⑨⑩; la <mark>endotelina-1</mark> cierra la arteriola <span class=\"lt2\">B</span> y el fibroblasto deposita colágeno ⑧⑪.", "etiquetas": [{"n": "⑩", "t": "Raynaud", "s": "blanco, azul<br>y rojo", "c": "i", "x": 0.5, "y": 6, "ax": 11.4, "ay": 22.5, "al": "l"}, {"n": "⑩", "t": "Calcinosis", "s": "nódulos<br>de calcio", "c": "g", "x": 23, "y": 6, "ax": 23.8, "ay": 25}, {"n": "⑧⑩", "t": "Esófago", "s": "colágeno en<br>lugar de músculo", "c": "g", "x": 42, "y": 6, "ax": 40.4, "ay": 32}, {"n": "⑪", "t": "Endotelina-1", "s": "cierra la<br>arteriola", "c": "d", "x": 99.5, "y": 6, "ax": 88.5, "ay": 27, "al": "r"}, {"n": "⑩", "t": "Telangiectasias", "s": "vasos dilatados<br>en la piel", "c": "d", "x": 0.5, "y": 91, "ax": 10.4, "ay": 47, "al": "l"}, {"n": "⑨⑩", "t": "Esclerodactilia", "s": "dedos afilados:<br>anti-centrómero", "c": "g", "x": 25, "y": 91, "ax": 21.5, "ay": 36}, {"n": "⑧", "t": "Linfocitos", "s": "inflamación<br>perivascular", "c": "i", "x": 57, "y": 91, "ax": 71, "ay": 63.5}, {"n": "⑪", "t": "Luz estrecha", "s": "íntima engrosada:<br>vasculopatía", "c": "d", "x": 75, "y": 91, "ax": 83.3, "ay": 48, "d": "B"}, {"n": "⑧", "t": "Fibroblasto", "s": "deposita<br>colágeno", "c": "g", "x": 99.5, "y": 91, "ax": 93.8, "ay": 67, "al": "r"}]}, {"img": "img/33_3.webp", "ratio": 1.5, "titulo": "SAF: placenta, trombo y plaquetas", "texto": "Los antifosfolípidos actúan sobre el <mark>trofoblasto</mark> y causan abortos ⑭ <span class=\"lt2\">C</span>; son <b>protrombóticos</b> in vivo <span class=\"cx\">porque</span> frenan la proteína C ⑫⑬; el bazo destruye plaquetas cubiertas de anti-GPIIb/IIIa ⑮.", "etiquetas": [{"n": "⑭", "t": "Trofoblasto", "s": "anticuerpos con<br>β2GPI: abortos", "c": "d", "x": 0.5, "y": 6, "ax": 14, "ay": 21, "d": "C", "al": "l"}, {"n": "⑬", "t": "Anticuerpo", "s": "sobre el<br>endotelio", "c": "d", "x": 43, "y": 6, "ax": 53.4, "ay": 29}, {"n": "⑬", "t": "Plaquetas activadas", "s": "se agregan<br>en el trombo", "c": "d", "x": 64, "y": 6, "ax": 56, "ay": 41}, {"n": "⑮", "t": "Macrófago del bazo", "s": "come plaquetas<br>con anticuerpo", "c": "g", "x": 99.5, "y": 6, "ax": 84.6, "ay": 32, "al": "r"}, {"n": "⑭", "t": "Arteria espiral", "s": "trombo en<br>la placenta", "c": "d", "x": 0.5, "y": 91, "ax": 15.6, "ay": 66.4, "al": "l"}, {"n": "⑫", "t": "Trombo venoso", "s": "in vivo:<br>protrombótico", "c": "d", "x": 35, "y": 91, "ax": 47, "ay": 58.6}, {"n": "⑬", "t": "Proteína C", "s": "apagada por<br>los anticuerpos", "c": "g", "x": 58, "y": 91, "ax": 62.5, "ay": 65.4}, {"n": "⑮", "t": "Anti-GPIIb/IIIa", "s": "plaqueta marcada:<br>trombocitopenia", "c": "d", "x": 99.5, "y": 91, "ax": 81.4, "ay": 67.4, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = Sjögren</b> (glándula, linfocitos, anticuerpos anti-M3), <b class=\"d\">rojo = síndrome antifosfolipídico</b> (trombo, plaquetas, endotelio), gris = esclerodermia (colágeno, arteriola, calcio).", "<b>Izquierda:</b> el infiltrado es sobre todo de <mark>LT CD4</mark>; el IFN-γ hace que el propio epitelio exprese HLA de clase II, y los anticuerpos anti-M3 tapan la señal que pide saliva <span class=\"lt2\">A</span>.", "<b>Centro:</b> la <mark>endotelina-1</mark> cierra la arteriola y hace proliferar su pared; el colágeno se acumula y la piel queda rígida, lisa y sin pliegues <span class=\"lt2\">B</span>.", "<b>Derecha:</b> in vitro los anticuerpos antifosfolipídicos alargan la coagulación, pero in vivo activan plaquetas y endotelio y <mark>apagan la proteína C</mark>: trombosis <span class=\"lt2\">C</span>."], "recordar": "Sjögren = <b>conducto</b> (CD4, anti-Ro/La, anti-M3, linfoma B). Esclerodermia = <b>vaso + colágeno + anticuerpo</b> (ET-1; anti-centrómero limitada, anti-Scl-70 difusa). SAF = <b>trombo + aborto</b> (β2GPI, anticardiolipina, «anticoagulante» lúpico)."}, "numeros": [{"l": "A", "html": "<b>Sjögren</b>: prevalencia <b class=\"n\">1–3 %</b>; mujeres de 40 a 50 años; <b class=\"a\">60 %</b> de quienes consultan por ojo seco lo tiene sin diagnóstico; linfoma B en el <b class=\"a\">10 %</b>; manifestaciones sistémicas en el <b class=\"n\">50 %</b>.", "rango": null}, {"l": "B", "html": "<b>Esclerodermia</b>: incidencia <b class=\"n\">1–10</b> por millón al año; la ET-1 contrae <b class=\"a\">10 veces</b> más que la angiotensina; autoanticuerpos en el <b class=\"a\">80 %</b>; Raynaud en más de la mitad.", "rango": null}, {"l": "C", "html": "<b>SAF</b>: causa el <b class=\"a\">7–25 %</b> de las pérdidas fetales recurrentes (anticardiolipina en el <b class=\"n\">50 %</b>, anticoagulante lúpico en el <b class=\"n\">14 %</b>); trombocitopenia por anti-GPIIb/IIIa en el <b class=\"n\">25 %</b>; en el neonato los anticuerpos se van a los <b class=\"n\">4 meses</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "Tres blancos, tres daños", "subtitulo": "disparador → célula o molécula blanco → mecanismo → resultado y complicación", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Disparadores", "m": "<b>Qué pasa:</b> Sjögren: HLA-DRB1*0301, DQA1*0501, DQB1*0201 y virus sialotrópicos (Epstein-Barr, hepatitis C). Esclerodermia: citomegalovirus, cloruro de polivinilo, solventes. SAF: infecciones con <mark>mimetismo molecular</mark> con la cardiolipina y la β2GPI.", "pr": "se rompe la tolerancia frente a un blanco distinto en cada enfermedad.", "pr_tit": "Produce:", "rf": "Pregunta ⑧", "color": "p1"}, {"t": "2. Sjögren: el conducto", "m": "<b>Por qué:</b> LT CD4 periductales liberan IL-2 e IFN-γ; el epitelio expresa <mark>HLA clase II</mark>; VCAM-1, ICAM-1 y ELAM-1 atraen más linfocitos; el BAFF alto mantiene vivos a los linfocitos B (anti-Ro, anti-La, anti-M3).", "pr": "xerostomía, xeroftalmia, Raynaud, vasculitis; linfoma B de la zona marginal.", "pr_tit": "Produce:", "rf": "Preguntas ①②③④⑤⑥⑦ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Esclerodermia: vaso y colágeno", "m": "<b>Qué produce:</b> la <mark>endotelina-1</mark> cierra la arteriola y prolifera su pared; los fibroblastos acumulan colágeno; hay menos Treg y más Th17; la CXCL4 de la célula dendrítica plasmocitoide marca la gravedad.", "pr": "piel dura, CREST (limitada, anti-centrómero) o pulmón y riñón (difusa, anti-Scl-70).", "pr_tit": "Produce:", "rf": "Preguntas ⑨⑩⑪⑫ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. SAF: la coagulación", "m": "<b>Qué pasa:</b> los anticuerpos se unen a la <mark>β2GPI</mark> en endotelio y plaquetas: agregación plaquetaria, menos proteína C, menos AT-III y anexina V, menos fibrinolisis.", "pr": "trombosis arteriales y venosas (cerebro más que corazón), trombocitopenia.", "pr_tit": "Produce:", "rf": "Preguntas ⑬⑭⑮ · punto <span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Si se complica", "m": "<b>Desenlaces:</b> linfoma en el Sjögren; hipertensión pulmonar, fibrosis pulmonar y crisis renal en la esclerodermia; abortos, preeclampsia, restricción del crecimiento y <mark>bloqueo cardíaco neonatal</mark> en el SAF.", "pr": "seguimiento activo y tratamiento dirigido a cada blanco.", "pr_tit": "Produce:", "rf": "", "color": "p4"}], "extra": [{"html": "💊 <b>Tratamiento:</b> Sjögren — lágrimas artificiales, pilocarpina o <mark>cevimelina</mark> (más afín a M3), rituximab en la forma sistémica. Esclerodermia — penicilamina y colchicina (efecto transitorio), antagonistas de endotelina en la hipertensión pulmonar, ciclofosfamida en el pulmón intersticial, trasplante de médula ósea en casos graves.", "k": ""}, {"html": "⚠️ <b>Paradoja del SAF:</b> el «anticoagulante lúpico» alarga la coagulación en el tubo, pero en el cuerpo produce trombosis; <span class=\"cx\">además</span> aparece sin lupus. <span class=\"cx\">Por eso</span> el nombre engaña dos veces.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Cómo progresa el Sjögren", "pasos": ["ojo y boca secos", "fatiga, febrícula, Raynaud (50 %)", "vasculitis y órganos internos", "adenopatías, esplenomegalia, crioglobulinemia", "<b>linfoma B de la zona marginal</b> (10 %)"]}], "html": "", "fuente": "Fuente: tu teoría — clase 43 (epidemiología, etiología, inmunopatogenia, clínica, linfoma y tratamiento) y clase 44 (esclerodermia: tres pilares, CREST, tratamiento; SAF: anticuerpos, paradoja, trombosis, embarazo, SAF neonatal)."}, "preguntas": [{"n": 1, "id": "IN18-011", "c": "i", "tema": "Inmunopatogenia: infiltrado periductal", "pregunta": "En la biopsia de glándula salival del síndrome de Sjögren, el infiltrado periductal está formado predominantemente por:", "opciones": ["a. Neutrófilos.", "b. Eosinófilos.", "c. Linfocitos T CD4.", "d. Mastocitos.", "e. Células plasmáticas IgE."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Linfocitos T CD4 (seguidos de T CD8, linfocitos B y macrófagos).", "sin_banco": true, "ok": "", "x": "Es el collar de linfocitos que rodea el conducto de la izquierda: predominan los <mark>LT CD4</mark>, que activan a los linfocitos B. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN18-012", "c": "i", "tema": "Inmunopatogenia: autoanticuerpos", "pregunta": "Los autoanticuerpos más característicos del síndrome de Sjögren son:", "opciones": ["a. Anti-CCP y factor reumatoide.", "b. Anti-centrómero y anti-Scl-70.", "c. Anticardiolipina y anti-β2-glucoproteína I.", "d. Anti-Ro (SSA) y anti-La (SSB).", "e. Anti-ADNdc y anti-Sm."], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Anti-Ro (SSA) y anti-La (SSB), contra ribonucleoproteínas.", "sin_banco": true, "ok": "", "x": "La destrucción epitelial libera <mark>ribonucleoproteínas Ro y La</mark> y el organismo fabrica anticuerpos contra ellas; también aparece anti-α-fodrina. Son los mismos anticuerpos que, en una madre, causan el <span class=\"res\">lupus neonatal</span> con bloqueo cardíaco.", "truco": "SS-A y SS-B: «Sjögren Sindrome A y B».", "veces": 0}, {"n": 3, "id": "IN18-013", "c": "i", "tema": "Inmunopatogenia: secreción", "pregunta": "¿Por qué disminuye el flujo salival en el síndrome de Sjögren, además de la destrucción glandular?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Por anticuerpos contra los receptores muscarínicos M3, que bloquean la señal colinérgica que estimula la secreción.", "sin_banco": true, "ok": "", "x": "En la imagen, un anticuerpo tapa el receptor de la célula acinar: es el <mark>anti-M3</mark>. Aunque quede glándula, no recibe la orden de la acetilcolina, <span class=\"cx\">así que</span> <span class=\"res\">no hay saliva</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN18-014", "c": "i", "tema": "Riesgo de linfoma", "pregunta": "La complicación más temida del síndrome de Sjögren, presente en cerca del 10 % de los pacientes, es:", "opciones": ["a. Linfoma de células B de la zona marginal.", "b. Carcinoma escamoso de lengua.", "c. Leucemia mieloide crónica.", "d. Linfoma de Hodgkin.", "e. Adenocarcinoma de parótida."], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Linfoma de células B de la zona marginal.", "sin_banco": true, "ok": "", "x": "Los linfocitos B viven <mark>estimulados sin descanso</mark> por el BAFF elevado y los autoantígenos; un clon puede escapar al control y volverse maligno. <span class=\"cx\">Por eso</span> hay que sospecharlo ante <span class=\"res\">adenopatías, esplenomegalia o crioglobulinemia</span>.", "truco": "Sjögren 10 % → linfoma B «Marginal».", "veces": 0}, {"n": 5, "id": "IN18-015", "c": "i", "tema": "Inmunopatogenia: el epitelio", "pregunta": "¿Qué hace el IFN-γ sobre las células epiteliales de los conductos en el síndrome de Sjögren?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Induce en ellas moléculas HLA clase II, de modo que el propio epitelio presenta antígenos, amplifica la respuesta local y libera autoantígenos.", "sin_banco": true, "ok": "", "x": "Normalmente el epitelio no presenta antígenos a los CD4. Con el IFN-γ del infiltrado empieza a expresar <mark>HLA de clase II</mark> y se convierte en <mark>presentador</mark>; así el ataque se perpetúa en la misma glándula. <span class=\"cx\">Además</span>, el IFN-γ, la IL-1 y el TNF suben <span class=\"res\">VCAM-1, ICAM-1 y ELAM-1</span>, que atraen más linfocitos.", "truco": "El epitelio «se pone el uniforme» HLA-II y se delata.", "veces": 0}, {"n": 6, "id": "IN18-016", "c": "i", "tema": "Tratamiento", "pregunta": "Sobre el tratamiento del síndrome de Sjögren, es FALSO:", "opciones": ["a. La xeroftalmia se trata con lágrimas artificiales.", "b. La pilocarpina es un agonista muscarínico.", "c. La cevimelina tiene menor afinidad por el receptor M3 y más efectos adversos que la pilocarpina.", "d. El rituximab depleta linfocitos B en la enfermedad sistémica.", "e. El manejo es principalmente paliativo."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es falso: la cevimelina tiene MAYOR afinidad por M3, efecto más duradero y menos efectos adversos.", "sin_banco": true, "ok": "", "x": "Ambas estimulan la secreción, pero la <mark>cevimelina</mark> se pega mejor al receptor M3, dura más y molesta menos. El resto del manejo es de soporte (lágrimas, cremas, lubricantes) y en la forma sistémica se usa <span class=\"res\">rituximab (anti-CD20)</span>.", "truco": "Cevimelina: «Ce-Very-Mejor» para el M3.", "veces": 0}, {"n": 7, "id": "IN18-017", "c": "i", "tema": "Epidemiología (correlación clínica)", "pregunta": "Mujer de 45 años consulta al oftalmólogo por sensación de arena en los ojos y fotofobia; además tiene boca seca y dificultad para masticar. ¿Qué enfermedad sospechas y qué examen es la referencia diagnóstica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome de Sjögren; la referencia es la biopsia de glándula salival (infiltrado linfocítico periductal), con anti-Ro y anti-La.", "sin_banco": true, "ok": "", "x": "Mujer de la <mark>cuarta o quinta década</mark> con xeroftalmia y xerostomía es el perfil típico. El Sjögren se diagnostica tarde: cerca del <mark>60 %</mark> de quienes consultan por ojo seco lo tiene sin saberlo. <span class=\"cx\">Por eso</span>, ante ojo y boca secos, <span class=\"res\">se pide biopsia salival y anti-Ro/anti-La</span>.", "truco": "Ojo seco + boca seca en mujer de 40-50 = Sjögren hasta demostrar lo contrario.", "veces": 0}, {"n": 8, "id": "IN18-018", "c": "g", "tema": "Esclerodermia: inmunopatología", "pregunta": "Son pilares fisiopatológicos de la esclerosis sistémica, EXCEPTO:", "opciones": ["a. Vasculopatía por desequilibrio de vasodilatadores y vasoconstrictores.", "b. Depósito de cristales que activan el inflamasoma NLRP3.", "c. Fibrosis por acumulación de colágeno.", "d. Autoinmunidad con autoanticuerpos en el 80 % de los pacientes.", "e. Disminución de Treg y aumento de Th17."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Los cristales e inflamasoma NLRP3 son de la gota, no de la esclerodermia.", "sin_banco": true, "ok": "", "x": "La esclerodermia descansa en <mark>tres pilares</mark>: el vaso se cierra (endotelina-1), el colágeno se acumula (fibrosis) y aparecen autoanticuerpos (80 %, con menos Treg y más Th17). <span class=\"cx\">Por eso</span> <span class=\"res\">la b es la excepción</span>.", "truco": "Esclerodermia = «Vaso, Fibra y Anticuerpo».", "veces": 0}, {"n": 9, "id": "IN18-019", "c": "g", "tema": "Esclerodermia: autoanticuerpos", "pregunta": "Relacione correctamente el autoanticuerpo con la variante de esclerosis sistémica:", "opciones": ["a. Anti-Scl-70 con la variante limitada (CREST).", "b. Anti-centrómero con la variante difusa.", "c. Anti-centrómero con la variante limitada (CREST) y anti-Scl-70 con la difusa.", "d. Anti-Sm con la variante difusa.", "e. Anti-Ro con la variante limitada."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Anti-centrómero → limitada (CREST); anti-Scl-70 → difusa.", "sin_banco": true, "ok": "", "x": "La variante <mark>limitada</mark> (CREST) lleva anti-centrómero y puede complicarse con hipertensión pulmonar. La <mark>difusa</mark> lleva anti-Scl-70 y su peor manifestación es la enfermedad pulmonar intersticial, junto con la <span class=\"res\">crisis renal hipertensiva</span>.", "truco": "«Centro-Limitado»; «Scl-70 se Difunde».", "veces": 0}, {"n": 10, "id": "IN18-020", "c": "g", "tema": "Esclerodermia: cuadro clínico", "pregunta": "¿Qué significa el acrónimo CREST y a qué variante de esclerosis sistémica corresponde?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Calcinosis, fenómeno de Raynaud, compromiso del Esófago, Esclerodactilia y Telangiectasias; corresponde a la variante limitada y puede complicarse con hipertensión pulmonar.", "sin_banco": true, "ok": "", "x": "Cada letra es una manifestación de la <mark>variante limitada</mark>. El Raynaud aparece en más de la mitad de los casos y puede <mark>preceder por años</mark> a la piel dura. <span class=\"cx\">Por eso</span>, ante un Raynaud con anti-centrómero, <span class=\"res\">hay que vigilar la presión pulmonar</span>.", "truco": "CREST como la cresta del gallo: Calcio, Raynaud, Esófago, eSclerodactilia, Telangiectasias.", "veces": 0}, {"n": 11, "id": "IN18-021", "c": "g", "tema": "Esclerodermia: vasculopatía y tratamiento", "pregunta": "Respecto a la endotelina-1 en la esclerosis sistémica, es correcto:", "opciones": ["a. Es un vasodilatador potente que protege el endotelio.", "b. Solo está elevada en la variante limitada.", "c. Su efecto vasoconstrictor es 10 veces mayor que el de la angiotensina y sus antagonistas se usan en la hipertensión pulmonar.", "d. Es secretada por las células dendríticas plasmocitoides y mide 70 aminoácidos.", "e. Se bloquea con penicilamina."], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Vasoconstrictor 10 veces más potente que la angiotensina; sus antagonistas tratan la hipertensión pulmonar.", "sin_banco": true, "ok": "", "x": "Mira la arteriola del centro (punto Ⓑ): la <mark>ET-1</mark> la cierra y engrosa su pared, con una fuerza diez veces mayor que la angiotensina. <span class=\"cx\">Por eso</span> <span class=\"res\">sus antagonistas</span> se usan en la hipertensión pulmonar.", "truco": "", "veces": 0}, {"n": 12, "id": "IN18-022", "c": "d", "tema": "SAF: anticuerpos y mecanismo", "pregunta": "¿Por qué se considera inadecuado el término «anticoagulante lúpico»?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque in vivo no es anticoagulante sino protrombótico, y porque aparece también en pacientes con anticuerpos antifosfolipídicos sin lupus.", "sin_banco": true, "ok": "", "x": "En el tubo de ensayo los anticuerpos antifosfolipídicos <mark>alargan el tiempo de coagulación</mark> <span class=\"cx\">porque</span> reaccionan con factores de la cascada (sobre todo la trombina). <span class=\"cx\">En cambio</span>, dentro del cuerpo activan plaquetas y endotelio y producen <mark>trombosis</mark>. <span class=\"cx\">Así que</span> el nombre engaña dos veces: <span class=\"res\">ni anticoagula ni es solo lúpico</span>.", "truco": "«Anticoagulante» en el tubo, «coágulo» en la vena.", "veces": 0}, {"n": 13, "id": "IN18-023", "c": "d", "tema": "SAF: mecanismo in vivo", "pregunta": "Los anticuerpos antifosfolipídicos crean un estado protrombótico in vivo por los siguientes mecanismos, EXCEPTO:", "opciones": ["a. Activación y agregación plaquetaria.", "b. Disminución de la antitrombina III.", "c. Menor unión de la anexina V.", "d. Reducción de la fibrinolisis.", "e. Aumento de la activación de la proteína C."], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es al revés: disminuyen la activación de la proteína C (anticoagulante natural).", "sin_banco": true, "ok": "", "x": "Los anticuerpos de la derecha sobre plaquetas y endotelio <mark>apagan la proteína C</mark>, la AT-III, la anexina V y la fibrinolisis. Si aumentaran la proteína C habría menos trombo; <span class=\"cx\">por eso</span> <span class=\"res\">la e es la excepción</span>.", "truco": "", "veces": 0}, {"n": 14, "id": "IN18-024", "c": "d", "tema": "SAF y embarazo (correlación clínica)", "pregunta": "Mujer de 32 años con tres abortos espontáneos y una trombosis venosa profunda previa. ¿Qué diagnóstico sospechas, qué anticuerpos buscas y sobre qué tejido actúan?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome antifosfolipídico: anticardiolipina (50 % de estos casos), anticoagulante lúpico (14 %) y anti-β2-glucoproteína I; actúan sobre el trofoblasto.", "sin_banco": true, "ok": "", "x": "Trombosis + pérdidas fetales recurrentes es la <mark>pareja típica del SAF</mark>, que explica entre el 7 y el 25 % de los abortos recurrentes. Los anticuerpos dañan el <mark>trofoblasto</mark>, <span class=\"cx\">por eso</span> también causan preeclampsia, restricción del crecimiento e incluso <span class=\"res\">infertilidad por pérdidas preclínicas</span>.", "truco": "SAF: «Sangre que coagula y Abortos Frecuentes».", "veces": 0}, {"n": 15, "id": "IN18-025", "c": "d", "tema": "SAF: manifestaciones hematológicas", "pregunta": "Después de la trombosis, la manifestación hematológica más importante del SAF es:", "opciones": ["a. Policitemia.", "b. Trombocitopenia, en el 25 % por anticuerpos contra GPIIb/IIIa y Ib/IX.", "c. Neutrofilia.", "d. Eosinofilia.", "e. Aplasia medular."], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Trombocitopenia (25 % por anticuerpos anti-GPIIb/IIIa e Ib/IX), por lo general no grave.", "sin_banco": true, "ok": "", "x": "Las plaquetas se <mark>consumen y se destruyen</mark>: en un cuarto de los casos por anticuerpos contra sus glucoproteínas de superficie. Por lo general no es grave. <span class=\"cx\">Además</span> puede haber <span class=\"res\">anemia hemolítica</span>.", "truco": "SAF baja plaquetas: los anticuerpos «muerden» la GPIIb/IIIa.", "veces": 0}], "tabla": {"cab": ["", "Sjögren", "Esclerodermia", "SAF"], "filas": [["Blanco", "Conductos exocrinos", "Vaso y colágeno", "β2GPI y cardiolipina"], ["Anticuerpos", "Anti-Ro, anti-La, anti-M3", "Anti-centrómero, anti-Scl-70", "Anticardiolipina, anticoagulante lúpico"], ["Clínica", "Boca y ojo secos", "Piel dura, Raynaud, CREST", "Trombosis y abortos"], ["Complicación", "Linfoma B (10 %)", "Pulmón, hipertensión pulmonar, riñón", "Bloqueo cardíaco neonatal"], ["🔑 Para diferenciar", "Sequedad", "Rigidez", "Coágulo"]]}, "fuente": "Fuente: tu teoría — clase 43 (Síndrome de Sjögren) y clase 44 (Esclerodermia y síndrome antifosfolipídico), Rojas 17.ª ed."}, {"n": 34, "slug": "Autoinmunidad_nervios_glandulas", "titulo": "Autoinmunidad de nervios y glándulas", "subtitulo": "esclerosis múltiple, Guillain-Barré, Graves, Hashimoto y diabetes tipo 1", "grupo": "g19", "lema": "La idea: en estas enfermedades el sistema inmune ataca <b>un solo órgano</b>, pero con dos armas distintas. Unas veces dispara el <mark>linfocito T</mark> (esclerosis múltiple, diabetes tipo 1, Hashimoto); otras, el <mark>anticuerpo</mark> (Guillain-Barré, Graves). Y el anticuerpo no siempre destruye: en Graves <u>enciende</u> el receptor de la TSH. Casi siempre hay un gen de riesgo (HLA-DRB1, DQ-β 57, CTLA4, PTPN22) más un gatillo externo (infección, poca vitamina D, <b>Campylobacter</b>, rubéola). En la imagen verás de izquierda a derecha: el linfocito cruzando la barrera hematoencefálica y la mielina pelada, el nódulo de Ranvier cubierto de anticuerpos, dos folículos tiroideos (uno encendido y otro destruido) y un islote pancreático invadido por linfocitos T.", "img": "img/34.webp", "mini": "img/mini/34.webp", "ratio": 1.5, "etiquetas": [{"n": "①③⑥", "t": "Linfocito T", "s": "cruza la barrera:<br>ICAM-1, VCAM-1", "c": "i", "x": 0.5, "y": 6, "ax": 14.3, "ay": 33, "al": "l"}, {"n": "②④⑦", "t": "Nódulo de Ranvier", "s": "IgG anti-gangliósido:<br>Guillain-Barré", "c": "d", "x": 32, "y": 6, "ax": 32.5, "ay": 47, "d": "B"}, {"n": "⑧", "t": "IgG en el receptor TSH", "s": "llave que enciende:<br>Graves, más T3 y T4", "c": "d", "x": 57, "y": 6, "ax": 60.5, "ay": 17, "d": "C"}, {"n": "⑩⑪", "t": "Linfocitos T CD8", "s": "atacan la célula β<br>(diabetes tipo 1)", "c": "i", "x": 99.5, "y": 6, "ax": 92.5, "ay": 34, "al": "r"}, {"n": "①⑥", "t": "Placa de EM", "s": "macrófago: NO,<br>radicales, glutamato", "c": "i", "x": 0.5, "y": 91, "ax": 20, "ay": 57, "d": "A", "al": "l"}, {"n": "②", "t": "Axón periférico", "s": "parálisis flácida;<br>LCR sin células", "c": "g", "x": 31, "y": 91, "ax": 37, "ay": 70}, {"n": "⑨", "t": "Infiltrado linfocitario", "s": "Hashimoto: anti-TPO<br>+ LT CD8", "c": "i", "x": 51, "y": 91, "ax": 54, "ay": 60}, {"n": "⑨", "t": "Centro germinal", "s": "células plasmáticas<br>fabrican anticuerpos", "c": "d", "x": 71, "y": 91, "ax": 66, "ay": 68}, {"n": "⑬", "t": "Islote destruido", "s": "al diagnóstico queda<br>menos del 10 %", "c": "g", "x": 99.5, "y": 91, "ax": 86.5, "ay": 45, "d": "D", "al": "r"}], "diapos": [{"img": "img/34.webp", "ratio": 1.5, "titulo": "Mielina, nervio, tiroides e islote", "texto": "La EM pela la mielina central y el Guillain-Barré ataca el <mark>nódulo de Ranvier</mark> ②④; Graves <b>enciende</b> el receptor de TSH ⑧ y los LT CD8 destruyen el islote ⑪⑬.", "etiquetas": [{"n": "①③⑥", "t": "Linfocito T", "s": "cruza la barrera:<br>ICAM-1, VCAM-1", "c": "i", "x": 0.5, "y": 6, "ax": 14.3, "ay": 33, "al": "l"}, {"n": "②④⑦", "t": "Nódulo de Ranvier", "s": "IgG anti-gangliósido:<br>Guillain-Barré", "c": "d", "x": 32, "y": 6, "ax": 32.5, "ay": 47, "d": "B"}, {"n": "⑧", "t": "IgG en el receptor TSH", "s": "llave que enciende:<br>Graves, más T3 y T4", "c": "d", "x": 57, "y": 6, "ax": 60.5, "ay": 17, "d": "C"}, {"n": "⑩⑪", "t": "Linfocitos T CD8", "s": "atacan la célula β<br>(diabetes tipo 1)", "c": "i", "x": 99.5, "y": 6, "ax": 92.5, "ay": 34, "al": "r"}, {"n": "①⑥", "t": "Placa de EM", "s": "macrófago: NO,<br>radicales, glutamato", "c": "i", "x": 0.5, "y": 91, "ax": 20, "ay": 57, "d": "A", "al": "l"}, {"n": "②", "t": "Axón periférico", "s": "parálisis flácida;<br>LCR sin células", "c": "g", "x": 31, "y": 91, "ax": 37, "ay": 70}, {"n": "⑨", "t": "Infiltrado linfocitario", "s": "Hashimoto: anti-TPO<br>+ LT CD8", "c": "i", "x": 51, "y": 91, "ax": 54, "ay": 60}, {"n": "⑨", "t": "Centro germinal", "s": "células plasmáticas<br>fabrican anticuerpos", "c": "d", "x": 71, "y": 91, "ax": 66, "ay": 68}, {"n": "⑬", "t": "Islote destruido", "s": "al diagnóstico queda<br>menos del 10 %", "c": "g", "x": 99.5, "y": 91, "ax": 86.5, "ay": 45, "d": "D", "al": "r"}]}, {"img": "img/34_2.webp", "ratio": 1.5, "titulo": "EM en tres etapas", "texto": "1) El LT se activa con mielina en la periferia ①⑥; 2) cruza la barrera con <mark>VLA-4</mark> (el <b>natalizumab</b> la bloquea) ③ <span class=\"lt2\">A</span>; 3) desata la cascada que pela la mielina ⑥.", "etiquetas": [{"n": "⑥", "t": "Dendrítica", "s": "presenta<br>mielina", "c": "i", "x": 0.5, "y": 8, "ax": 11, "ay": 40, "al": "l"}, {"n": "③", "t": "Natalizumab", "s": "anticuerpo que<br>tapa la VLA-4", "c": "i", "x": 37, "y": 8, "ax": 41, "ay": 30, "d": "A"}, {"n": "⑥", "t": "LT activado", "s": "libera citoquinas<br>en el SNC", "c": "d", "x": 62, "y": 8, "ax": 74, "ay": 28}, {"n": "⑥", "t": "Oligodendrocito", "s": "célula que fabrica<br>la mielina", "c": "g", "x": 99.5, "y": 8, "ax": 90, "ay": 22, "al": "r"}, {"n": "①", "t": "HLA-DRB1*15:01", "s": "presenta al<br>TCR: riesgo", "c": "i", "x": 0.5, "y": 91, "ax": 16, "ay": 43, "al": "l"}, {"n": "⑥", "t": "Clon de LT", "s": "se multiplica<br>en el ganglio", "c": "i", "x": 19, "y": 8, "ax": 25, "ay": 55}, {"n": "③", "t": "VLA-4", "s": "se pega al<br>endotelio (paso 2)", "c": "i", "x": 40, "y": 91, "ax": 40, "ay": 50}, {"n": "③", "t": "Cruza la barrera", "s": "hemato-<br>encefálica", "c": "d", "x": 57, "y": 91, "ax": 58, "ay": 57}, {"n": "⑥", "t": "Macrófago", "s": "come la mielina<br>(paso 3)", "c": "d", "x": 72, "y": 91, "ax": 71, "ay": 45}, {"n": "⑥", "t": "Axón desnudo", "s": "mielina<br>pelada", "c": "d", "x": 99.5, "y": 91, "ax": 86, "ay": 60, "al": "r"}]}, {"img": "img/34_3.webp", "ratio": 1.5, "titulo": "Timo, Treg y reactividad cruzada", "texto": "Sin <mark>AIRE</mark> el timo no borra los LT autorreactivos; sin <b>FOXP3</b> faltan los Treg (IPEX) ⑭; los anticuerpos anti-suprarrenal reconocen también la célula esteroidogénica del ovario ⑫.", "etiquetas": [{"n": "⑭", "t": "Célula epitelial con AIRE", "s": "muestra antígenos<br>de todo el cuerpo", "c": "i", "x": 0.5, "y": 8, "ax": 15, "ay": 40, "al": "l"}, {"n": "⑭", "t": "Treg (FOXP3)", "s": "frena a los LT<br>autorreactivos", "c": "i", "x": 52, "y": 8, "ax": 53, "ay": 37}, {"n": "⑫", "t": "Corteza suprarrenal", "s": "blanco del<br>anti-suprarrenal", "c": "d", "x": 75, "y": 8, "ax": 80, "ay": 30}, {"n": "⑫", "t": "Anticuerpo", "s": "contra la célula<br>que fabrica esteroides", "c": "d", "x": 99.5, "y": 8, "ax": 91, "ay": 26, "al": "r"}, {"n": "⑭", "t": "LT autorreactivo", "s": "muere en el timo:<br>selección negativa", "c": "d", "x": 0.5, "y": 91, "ax": 29, "ay": 63, "al": "l"}, {"n": "⑭", "t": "LT efectores", "s": "sin FOXP3 quedan<br>libres: IPEX", "c": "d", "x": 40, "y": 91, "ax": 40, "ay": 60}, {"n": "⑫", "t": "Folículo ovárico", "s": "teca y granulosa<br>también: hipogonadismo", "c": "d", "x": 99.5, "y": 91, "ax": 84, "ay": 57, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = ataque celular</b> (linfocitos T, macrófagos), <b class=\"d\">rojo = ataque por anticuerpos</b> (o complejos inmunes), gris = el tejido o la célula blanco.", "<b>Sistema nervioso central:</b> el linfocito T se activa en el ganglio, cruza la barrera ya abierta por una infección (ICAM-1, VCAM-1) y ataca la <mark>proteína básica de la mielina</mark>; <span class=\"cx\">luego</span> el macrófago pela la vaina <span class=\"lt2\">A</span>.", "<b>Nervio periférico:</b> en Guillain-Barré la IgG se pega a los <mark>gangliósidos</mark> del nódulo de Ranvier; <span class=\"cx\">por eso</span> el daño es periférico y el LCR tiene proteínas altas sin células <span class=\"lt2\">B</span>.", "<b>Glándulas:</b> en Graves el anticuerpo es una llave que no se suelta del receptor de la TSH; <span class=\"cx\">en cambio</span>, en Hashimoto el anti-TPO y los LT destruyen el folículo <span class=\"lt2\">C</span>. En el islote, los LT CD8 matan a la célula β en silencio <span class=\"lt2\">D</span>."], "recordar": "EM = LT contra mielina del SNC (DRB1*15:01, poca vitamina D). Guillain-Barré = IgG contra gangliósidos del nervio periférico (<b>Campylobacter</b>). Graves <b>estimula</b>, Hashimoto <b>destruye</b>. Diabetes tipo 1 = LT CD8 contra la célula β."}, "numeros": [{"l": "A", "html": "<b>Esclerosis múltiple</b>: <b class=\"a\">1 de cada 1000</b> adultos jóvenes; anti-KIR4.1 en el <b class=\"a\">47 %</b>. El natalizumab baja las recaídas un <b class=\"n\">68 %</b> pero da leucoencefalopatía en <b class=\"a\">1/1000</b>.", "rango": null}, {"l": "B", "html": "<b>Guillain-Barré</b>: <b>Campylobacter jejuni</b> previo en el <b class=\"a\">30 %</b>; LCR con proteínas <b class=\"a\">altas</b> y células <b class=\"n\">normales</b>.", "rango": null}, {"l": "C", "html": "<b>Tiroides</b>: la autoinmunidad tiroidea afecta al <b class=\"a\">5 %</b> de la población. Graves <b class=\"a\">50/100 000/año</b> (mujeres más del <b class=\"a\">80 %</b>); Hashimoto <b class=\"a\">500/100 000/año</b>.", "rango": null}, {"l": "D", "html": "<b>Diabetes tipo 1</b>: al diagnóstico funciona <b class=\"b\">menos del 10 %</b> de los islotes. Rubéola congénita: el <b class=\"a\">30 %</b> hace diabetes.", "rango": {"min": 0, "max": 100, "unidad": "% de islotes que aún funcionan", "zonas": [[0, 10, "a"], [10, 100, "n"]], "marcas": [10], "valor": 8}}], "escalas": [], "cadena": {"titulo": "Del gen al órgano destruido", "subtitulo": "estímulo → ruptura de tolerancia → llegada al órgano → arma → resultado → si no se frena", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Terreno y gatillo", "m": "<b>Qué pasa:</b> un gen de riesgo (<mark>HLA-DRB1*15:01</mark> en EM, <mark>DQ-β 57</mark> sin ácido aspártico en diabetes tipo 1, CTLA4 y PTPN22 en tiroides) se junta con un gatillo: poca vitamina D, <b>Campylobacter</b>, rubéola, yodo o estrés.", "pr": "el sistema inmune queda listo para equivocarse.", "pr_tit": "Produce:", "rf": "Preguntas ①⑩", "color": "p1"}, {"t": "2. Se rompe la tolerancia", "m": "<b>Por qué:</b> el <mark>mimetismo molecular</mark> (microbio parecido a lo propio) o una falla del timo (<b>AIRE</b>) o de los Treg (<b>FOXP3</b>) deja vivos linfocitos autorreactivos.", "pr": "linfocitos y anticuerpos contra mielina, gangliósidos o glándula.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑦⑭", "color": "p2"}, {"t": "3. Llegan al órgano", "m": "<b>Qué pasa:</b> en la EM una infección sube ICAM-1 y VCAM-1 y la osteopontina se une a VLA-4: el LT cruza la barrera. En glándulas, el IFN-γ hace que el tirocito y la célula β expresen <mark>HLA clase II</mark>.", "pr": "el blanco queda a la vista del linfocito.", "pr_tit": "Produce:", "rf": "Preguntas ③⑥ · punto <span class=\"lt2\">A</span>", "color": "p3"}, {"t": "4. El arma", "m": "<b>Celular:</b> LT, Th17 y CD8 más macrófagos (óxido nítrico, glutamato) en EM; LT CD8 en el islote. <b>Humoral:</b> IgG anti-gangliósido en el nódulo, IgG <mark>estimulante</mark> del receptor TSH, anti-TPO destructor.", "pr": "desmielinización, folículo encendido o destruido, célula β muerta.", "pr_tit": "Produce:", "rf": "Preguntas ④⑧⑨⑪ · puntos <span class=\"lt2\">B</span><span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Resultado", "m": "<b>Qué produce:</b> placas de EM, parálisis flácida arrefléxica (SGB), <mark>hipertiroidismo</mark> (Graves) o <mark>hipotiroidismo</mark> (Hashimoto), y diabetes <span class=\"cx\">cuando</span> queda menos del 10 % de islotes.", "pr": "la clínica aparece tarde, cuando el daño ya es grande.", "pr_tit": "Produce:", "rf": "Preguntas ②⑫⑬ · punto <span class=\"lt2\">D</span>", "color": "p5"}, {"t": "6. Cómo se frena", "m": "<b>Tratamiento:</b> natalizumab (anti-VLA-4), fingolimod, rituximab y alemtuzumab en EM; gammaglobulina IV y plasmaféresis en SGB; ciclosporina A en personas de alto riesgo de diabetes tipo 1.", "pr": "menos recaídas, recuperación o retraso de la enfermedad.", "pr_tit": "Produce:", "rf": "Preguntas ③⑦", "color": "p4"}], "extra": [{"html": "🧠 <b>Otras del sistema nervioso:</b> encefalomielitis por la vacuna antirrábica de Pasteur (médula de conejo), panencefalitis esclerosante subaguda (sarampión, menores de 15 años), corea de Sydenham (estreptococo) y lupus con anti-ribosoma P. Preguntas ⑤⑥.", "k": ""}, {"html": "🧬 <b>Poliglandular tipo 1</b> = mutación de <mark>AIRE</mark>, autosómica recesiva. <b>IPEX</b> = mutación de <mark>FOXP3</mark>, ligada al X: diarrea, dermatitis, diabetes y tiroiditis en niños. <b>Addison:</b> el anticuerpo contra la suprarrenal ataca también al ovario. Preguntas ⑫⑭.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 La célula β se acaba en silencio", "pasos": ["gen DQ-β 57 + gatillo (rubéola, leche de vaca precoz)", "bajan los Treg, suben los Th1", "IFN-γ: el islote muestra HLA clase II", "LT CD8 matan células β; aparecen GADA e IA-2", "<b>diagnóstico</b>: queda menos del 10 % de islotes"]}], "html": "", "fuente": "Fuente: tu teoría — clase 45 (SNC inmunoprivilegiado, esclerosis múltiple, Guillain-Barré, encefalitis) y clase 46 (Graves, Hashimoto, Addison, diabetes tipo 1, síndromes poliglandulares)."}, "preguntas": [{"n": 1, "id": "IN19-001", "c": "i", "tema": "Esclerosis múltiple", "pregunta": "¿Qué alelo HLA se asocia con más fuerza a la esclerosis múltiple?", "opciones": ["a. HLA-B27", "b. HLA-DQ2", "c. HLA-DRB1*15:01", "d. HLA-DR4", "e. HLA-B5"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. HLA-DRB1*15:01, junto con polimorfismos del IL7R.", "sin_banco": true, "ok": "", "x": "Paso 1 de la cadena: el <mark>HLA-DRB1*15:01</mark> es el gen; la falta de vitamina D (poco sol) es el gatillo, <span class=\"cx\">porque</span> la vitamina D regula justo ese alelo. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN19-002", "c": "d", "tema": "Síndrome de Guillain-Barré", "pregunta": "En el síndrome de Guillain-Barré, el líquido cefalorraquídeo muestra típicamente:", "opciones": ["a. Pleocitosis linfocitaria con proteínas normales", "b. Glucosa baja con neutrófilos", "c. Bandas oligoclonales con pleocitosis", "d. Proteínas elevadas sin pleocitosis", "e. LCR completamente normal"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Proteínas elevadas con recuento celular normal: disociación albuminocitológica.", "sin_banco": true, "ok": "", "x": "El daño está en la raíz y el nervio periférico, no en las meninges; <span class=\"cx\">por eso</span> suben las <mark>proteínas</mark> pero no llegan células. Se llama <span class=\"res\">disociación albuminocitológica</span> y es la clave de laboratorio del SGB.", "truco": "Guillain-Barré: «mucha proteína, ninguna célula».", "veces": 0}, {"n": 3, "id": "IN19-003", "c": "i", "tema": "Tratamiento de la EM", "pregunta": "El natalizumab, usado en la esclerosis múltiple, actúa bloqueando:", "opciones": ["a. CD20 de los linfocitos B", "b. CD52 de linfocitos T y B", "c. La integrina VLA-4", "d. El TNF-α", "e. La subunidad p40 de IL-12/IL-23"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. La integrina VLA-4: impide que los linfocitos crucen la barrera hematoencefálica.", "sin_banco": true, "ok": "", "x": "Es el paso 3 de la cadena: sin <mark>VLA-4</mark> el linfocito de la imagen no puede cruzar la pared del capilar cerebral. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>; el precio es el virus JC.", "truco": "", "veces": 0}, {"n": 4, "id": "IN19-004", "c": "d", "tema": "Síndrome de Guillain-Barré", "pregunta": "En el síndrome de Guillain-Barré, los anticuerpos IgG se dirigen contra:", "opciones": ["a. Gangliósidos de los nervios periféricos, en los nódulos de Ranvier", "b. La proteína básica de la mielina del SNC", "c. El receptor de acetilcolina", "d. El canal de potasio KIR4.1", "e. La ribonucleoproteína Ro"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Gangliósidos de los nervios periféricos; se unen a fibras motoras en los nódulos de Ranvier.", "sin_banco": true, "ok": "", "x": "Míralo en el punto Ⓑ: los anticuerpos están justo en el <mark>nódulo de Ranvier</mark> del nervio periférico, no en la mielina del cerebro. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 5, "id": "IN19-005", "c": "d", "tema": "Otras afecciones neuroinmunológicas", "pregunta": "¿Por qué la vacuna antirrábica original de Pasteur producía parálisis ascendente?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque se preparaba en médula de conejo: los anticuerpos contra antígenos de esa médula reaccionaban en forma cruzada con la del paciente (encefalomielitis diseminada aguda).", "sin_banco": true, "ok": "", "x": "El problema no era el virus mal inactivado, sino el <mark>tejido nervioso del animal</mark> donde se cultivaba. Así, la vacuna enseñaba al sistema inmune a atacar mielina parecida a la humana. <span class=\"cx\">Por eso</span> se cambió a embrión de pato y <span class=\"cx\">luego</span> a <span class=\"res\">células humanas</span>.", "truco": "Pasteur: «el conejo venía en la vacuna».", "veces": 0}, {"n": 6, "id": "IN19-006", "c": "i", "tema": "Esclerosis múltiple", "pregunta": "Explique las tres etapas del proceso neuroinflamatorio en la esclerosis múltiple.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "1) El LT reconoce el antígeno de la mielina en la periferia y se activa; 2) cruza la barrera hematoencefálica permeabilizada; 3) inicia la cascada inflamatoria, recluta leucocitos y daña el parénquima.", "sin_banco": true, "ok": "", "x": "Las infecciones suben ICAM-1, VCAM-1 y selectina E en el endotelio, <span class=\"cx\">así que</span> la barrera se abre. Dentro, el LT ataca la <mark>proteína básica de la mielina</mark>; <span class=\"cx\">luego</span> el complemento, los macrófagos (óxido nítrico, glutamato) y los Th17/CD8 amplían el daño. En el <span class=\"res\">47 %</span> hay <span class=\"cx\">además</span> IgG anti-KIR4.1.", "truco": "Periferia → puerta → incendio.", "veces": 0}, {"n": 7, "id": "IN19-007", "c": "d", "tema": "Síndrome de Guillain-Barré", "pregunta": "Varón de 30 años con diarrea hace dos semanas presenta debilidad que asciende desde las piernas y arreflexia. ¿Cuál es el mecanismo más probable?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome de Guillain-Barré por mimetismo molecular: los anticuerpos contra Campylobacter jejuni reconocen gangliósidos de los nervios periféricos.", "sin_banco": true, "ok": "", "x": "El <b>Campylobacter jejuni</b> precede al <mark>30 %</mark> de los casos; sus antígenos se parecen a los gangliósidos, <span class=\"cx\">por eso</span> la IgG antibacteriana ataca el nódulo de Ranvier. Se trata con <span class=\"res\">gammaglobulina IV, plasmaféresis</span> y esteroides.", "truco": "Diarrea + parálisis que sube = Campylobacter → Guillain-Barré.", "veces": 0}, {"n": 8, "id": "IN19-008", "c": "d", "tema": "Enfermedad de Graves", "pregunta": "El hipertiroidismo de la enfermedad de Graves se debe a:", "opciones": ["a. Anticuerpos anti-TPO que destruyen los tirocitos", "b. Linfocitos T CD8 contra la tiroglobulina", "c. Exceso de TSH hipofisaria", "d. IgG que estimulan en forma permanente el receptor de la TSH", "e. Anticuerpos que bloquean el receptor de la TSH"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. IgG contra el receptor de la TSH que lo activan de forma permanente y suben T3 y T4.", "sin_banco": true, "ok": "", "x": "En el folículo de arriba la llave (IgG) queda puesta en el receptor de la TSH y lo mantiene <mark>encendido</mark>; <span class=\"cx\">por eso</span> las células son altas y comen coloide. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN19-009", "c": "d", "tema": "Tiroiditis de Hashimoto", "pregunta": "En la tiroiditis de Hashimoto, el autoanticuerpo de mayor relevancia clínica es:", "opciones": ["a. Anti-tiroglobulina", "b. Anti-receptor de TSH estimulante", "c. GADA", "d. Antimitocondrial", "e. Anti-peroxidasa tiroidea (anti-TPO)"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Anti-TPO: se asocia directamente con la disfunción, la inflamación y el daño glandular.", "sin_banco": true, "ok": "", "x": "Es el folículo de abajo (punto Ⓒ): infiltrado de linfocitos y células plasmáticas con centro germinal; el <mark>anti-TPO</mark> acompaña al daño. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN19-010", "c": "i", "tema": "Diabetes tipo 1", "pregunta": "En la diabetes tipo 1, la susceptibilidad genética más importante es la sustitución del ácido aspártico en:", "opciones": ["a. La posición 52 de la cadena DQ-α", "b. La posición 57 de la cadena DQ-β", "c. El gen AIRE", "d. La posición 57 de HLA-B27", "e. El gen FOXP3"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La posición 57 de la cadena DQ-β (cambia por valina, serina o alanina).", "sin_banco": true, "ok": "", "x": "El <mark>ácido aspártico en DQ-β 57</mark> protege; <span class=\"cx\">cuando</span> se reemplaza, el HLA presenta mejor los péptidos del islote. <span class=\"cx\">En cambio</span>, la arginina en DQ-α 52 es un factor de riesgo <span class=\"res\">adicional e independiente</span>.", "truco": "DT1: «57 sin Asp, diabetes por llegar».", "veces": 0}, {"n": 11, "id": "IN19-011", "c": "d", "tema": "Diabetes tipo 1", "pregunta": "Son autoantígenos o autoanticuerpos propios de la diabetes tipo 1, EXCEPTO:", "opciones": ["a. Glutamato-descarboxilasa (GADA)", "b. Tirosina-fosfatasa IA-2", "c. Cromogranina A", "d. Anti-peroxidasa tiroidea", "e. Insulina"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El anti-TPO es de la tiroiditis de Hashimoto, no de la diabetes tipo 1.", "sin_banco": true, "ok": "", "x": "En la DT1 la <mark>cromogranina A y el APP</mark> activan a los LT CD8 y CD4, y la insulina alterada estimula a los LB. <span class=\"cx\">Además</span> hay anticuerpos GADA, IA-2, carboxipeptidasa H e ICA69. Pero el daño lo hacen sobre todo los <span class=\"res\">LT citotóxicos</span>.", "truco": "Islote: «GADA, IA-2, insulina y cromogranina».", "veces": 0}, {"n": 12, "id": "IN19-012", "c": "d", "tema": "Enfermedad de Addison", "pregunta": "¿Por qué la enfermedad de Addison autoinmune se asocia con hipogonadismo femenino?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Por reactividad cruzada: los anticuerpos contra la corteza suprarrenal reconocen también a las células que fabrican esteroides en el ovario.", "sin_banco": true, "ok": "", "x": "Suprarrenal y ovario comparten la maquinaria de <mark>síntesis de esteroides</mark>; <span class=\"cx\">así que</span> el mismo anticuerpo ataca a los dos. Resultado: infiltración linfocitaria, <span class=\"res\">atrofia ovárica y amenorrea</span>. Hoy casi todo Addison es autoinmune; antes la causa era la tuberculosis.", "truco": "Addison: «el anticuerpo confunde suprarrenal con ovario».", "veces": 0}, {"n": 13, "id": "IN19-013", "c": "i", "tema": "Diabetes tipo 1", "pregunta": "¿Qué fracción de islotes sigue funcionando cuando se diagnostica clínicamente la diabetes tipo 1 y qué implica?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Menos del 10 % de los islotes productores de insulina; el ataque autoinmune lleva un largo período preclínico.", "sin_banco": true, "ok": "", "x": "Es el islote de la derecha (punto Ⓓ): los LT CD8 matan durante años y, <span class=\"cx\">cuando</span> aparece la sed, queda <span class=\"res\">menos del 10 %</span> de células β.", "truco": "", "veces": 0}, {"n": 14, "id": "IN19-014", "c": "i", "tema": "Síndromes poliglandulares", "pregunta": "Compare el síndrome poliglandular autoinmune tipo 1 con el síndrome IPEX (gen y herencia).", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Poliglandular tipo 1: mutación de AIRE, autosómica recesiva (falla la selección en el timo). IPEX: mutación de FOXP3, ligada al X (faltan los LT reguladores).", "sin_banco": true, "ok": "", "x": "<mark>AIRE</mark> hace que el timo muestre antígenos de todo el cuerpo y elimine los LT autorreactivos; <span class=\"cx\">en cambio</span>, <mark>FOXP3</mark> fabrica los Treg que frenan en la periferia. <span class=\"cx\">Por eso</span> IPEX da en niños <span class=\"res\">diarrea, dermatitis, diabetes, tiroiditis y anemia hemolítica</span>.", "truco": "AIRE = aire del timo; FOXP3 = policía periférica (X).", "veces": 0}], "tabla": {"cab": ["", "Blanco", "Arma", "Resultado"], "filas": [["Esclerosis múltiple", "Proteína básica de la mielina (SNC)", "LT, Th17, CD8 y macrófagos", "Placas de desmielinización"], ["Guillain-Barré", "Gangliósidos del nódulo de Ranvier", "IgG + complemento", "Parálisis flácida ascendente"], ["Graves", "Receptor de la TSH", "IgG que estimula", "Hipertiroidismo"], ["Hashimoto", "Peroxidasa tiroidea", "Anti-TPO + LT CD8", "Hipotiroidismo"], ["Diabetes tipo 1", "Célula β (cromogranina A, APP)", "LT CD8 (+ GADA, IA-2)", "Falta de insulina"], ["🔑 Para diferenciar", "SNC o periférico", "Graves estimula, Hashimoto destruye", "EM y diabetes: el que mata es el LT"]]}, "fuente": "Fuente: tu teoría — clase 45 (Enfermedades autoinmunes del sistema nervioso) y clase 46 (Afecciones autoinmunes endocrinas), Rojas 17.ª ed."}, {"n": 35, "slug": "Autoinmunidad_piel_pulmon", "titulo": "Autoinmunidad de piel y pulmón", "subtitulo": "pénfigos, psoriasis, Goodpasture, sarcoidosis y EPOC", "grupo": "g19", "lema": "La idea: piel y pulmón son fronteras con el exterior, así que sus autoinmunes se ordenan por el <b>arma</b>. Cuando el <mark>anticuerpo</mark> ataca una proteína de unión aparece la ampolla (pénfigo) o la hemorragia (Goodpasture); cuando se forman <mark>complejos inmunes</mark> aparecen el eritema multiforme o la neumonitis del granjero; y cuando manda el <mark>linfocito T</mark> aparecen la psoriasis, la necrólisis epidérmica tóxica, el granuloma de la sarcoidosis y la EPOC. Importa porque la <b>profundidad</b> de la ampolla y el <b>patrón</b> del depósito (lineal o granular) delatan el mecanismo. En la imagen verás de izquierda a derecha: una piel con ampolla superficial y otra profunda, una placa de psoriasis, un alvéolo y un glomérulo tapizados por anticuerpo, y un granuloma sin necrosis.", "img": "img/35.webp", "mini": "img/mini/35.webp", "ratio": 1.5, "etiquetas": [{"n": "①⑦", "t": "Ampolla superficial", "s": "desmogleína I:<br>pénfigo foliáceo", "c": "d", "x": 0.5, "y": 6, "ax": 7.8, "ay": 32, "al": "l"}, {"n": "③", "t": "Escamas", "s": "hiperqueratosis<br>de la psoriasis", "c": "g", "x": 34, "y": 6, "ax": 43.6, "ay": 23}, {"n": "⑧⑨", "t": "IgG lineal en el alvéolo", "s": "Goodpasture:<br>hemoptisis", "c": "d", "x": 60, "y": 6, "ax": 73, "ay": 37, "d": "B"}, {"n": "⑪", "t": "Granuloma sin necrosis", "s": "sarcoidosis:<br>no se caseifica", "c": "i", "x": 99.5, "y": 6, "ax": 85, "ay": 43, "d": "C", "al": "r"}, {"n": "②", "t": "Ampolla profunda", "s": "desmogleína II:<br>pénfigo vulgar, firme", "c": "d", "x": 0.5, "y": 91, "ax": 22, "ay": 50, "al": "l"}, {"n": "③", "t": "Crestas y capilares", "s": "LT CD4 e IL-23:<br>hiperplasia", "c": "i", "x": 33, "y": 91, "ax": 45, "ay": 47, "d": "A"}, {"n": "⑭", "t": "Glomérulo", "s": "misma línea:<br>glomerulonefritis", "c": "d", "x": 56, "y": 91, "ax": 65, "ay": 59}, {"n": "⑪", "t": "Anillo de linfocitos", "s": "Th1: 10 a 1<br>sobre los Treg", "c": "i", "x": 78, "y": 91, "ax": 79.4, "ay": 56}, {"n": "", "t": "Célula gigante", "s": "macrófagos<br>fusionados", "c": "g", "x": 99.5, "y": 91, "ax": 92, "ay": 48, "al": "r"}], "diapos": [{"img": "img/35.webp", "ratio": 1.5, "titulo": "Ampollas, psoriasis, alvéolo y granuloma", "texto": "Pénfigo foliáceo = ampolla <mark>superficial</mark>, vulgar = profunda ①②; Goodpasture pega IgG <b>lineal</b> ⑧⑨; sarcoidosis = granuloma <span class=\"res\">sin necrosis</span> ⑪.", "etiquetas": [{"n": "①⑦", "t": "Ampolla superficial", "s": "desmogleína I:<br>pénfigo foliáceo", "c": "d", "x": 0.5, "y": 6, "ax": 7.8, "ay": 32, "al": "l"}, {"n": "③", "t": "Escamas", "s": "hiperqueratosis<br>de la psoriasis", "c": "g", "x": 34, "y": 6, "ax": 43.6, "ay": 23}, {"n": "⑧⑨", "t": "IgG lineal en el alvéolo", "s": "Goodpasture:<br>hemoptisis", "c": "d", "x": 60, "y": 6, "ax": 73, "ay": 37, "d": "B"}, {"n": "⑪", "t": "Granuloma sin necrosis", "s": "sarcoidosis:<br>no se caseifica", "c": "i", "x": 99.5, "y": 6, "ax": 85, "ay": 43, "d": "C", "al": "r"}, {"n": "②", "t": "Ampolla profunda", "s": "desmogleína II:<br>pénfigo vulgar, firme", "c": "d", "x": 0.5, "y": 91, "ax": 22, "ay": 50, "al": "l"}, {"n": "③", "t": "Crestas y capilares", "s": "LT CD4 e IL-23:<br>hiperplasia", "c": "i", "x": 33, "y": 91, "ax": 45, "ay": 47, "d": "A"}, {"n": "⑭", "t": "Glomérulo", "s": "misma línea:<br>glomerulonefritis", "c": "d", "x": 56, "y": 91, "ax": 65, "ay": 59}, {"n": "⑪", "t": "Anillo de linfocitos", "s": "Th1: 10 a 1<br>sobre los Treg", "c": "i", "x": 78, "y": 91, "ax": 79.4, "ay": 56}, {"n": "", "t": "Célula gigante", "s": "macrófagos<br>fusionados", "c": "g", "x": 99.5, "y": 91, "ax": 92, "ay": 48, "al": "r"}]}, {"img": "img/35_2.webp", "ratio": 1.5, "titulo": "EPOC: neutrófilos sin freno", "texto": "En el fumador la LTA4H no apaga el quimioatrayente y los <mark>neutrófilos</mark> se acumulan ⑫; sin antitripsina alfa la elastasa rompe los alvéolos <span class=\"lt2\">B</span>, y los corticoides alargan la vida del neutrófilo ⑬.", "etiquetas": [{"n": "⑬", "t": "Antitripsina alfa", "s": "frena a la<br>elastasa", "c": "i", "x": 30, "y": 8, "ax": 36, "ay": 43}, {"n": "⑫", "t": "Neutrófilos", "s": "LTA4H no apaga<br>la señal: se acumulan", "c": "d", "x": 50, "y": 8, "ax": 63, "ay": 30}, {"n": "⑫", "t": "Humo del cigarrillo", "s": "partículas que<br>inflaman", "c": "g", "x": 75, "y": 8, "ax": 75, "ay": 17}, {"n": "⑬", "t": "Elastasa", "s": "tijeras sin freno<br>rompen la pared", "c": "d", "x": 99.5, "y": 8, "ax": 81, "ay": 46, "al": "r"}, {"n": "⑬", "t": "Alvéolo sano", "s": "pared fina de<br>neumocitos tipo I", "c": "g", "x": 0.5, "y": 91, "ax": 29, "ay": 55, "d": "B", "al": "l"}, {"n": "⑬", "t": "Neutrófilo en el alvéolo", "s": "los corticoides<br>alargan su vida", "c": "d", "x": 62, "y": 91, "ax": 63, "ay": 53}, {"n": "⑬", "t": "Alvéolos rotos", "s": "enfisema: espacios<br>grandes", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 62, "al": "r"}]}, {"img": "img/35_3.webp", "ratio": 1.5, "titulo": "Vitiligo, necrólisis y dermatitis herpetiforme", "texto": "Vitiligo = pérdida de <mark>melanocitos</mark> (0,5 %, PTPN22) ⑥; necrólisis epidérmica tóxica = LT CD8 activados por fármacos ④; dermatitis herpetiforme = celíaca con <b>prurito intenso</b> ⑤.", "etiquetas": [{"n": "⑥", "t": "Parche blanco", "s": "sin melanocitos:<br>0,5 % de la población", "c": "d", "x": 15, "y": 6, "ax": 15, "ay": 36}, {"n": "④", "t": "Epidermis desprendida", "s": "necrólisis: la piel<br>se despega", "c": "d", "x": 45, "y": 6, "ax": 40, "ay": 22}, {"n": "⑤", "t": "Ampollas subepidérmicas", "s": "prurito<br>intenso", "c": "d", "x": 72, "y": 6, "ax": 84, "ay": 34}, {"n": "⑤", "t": "Trigo (gluten)", "s": "enfermedad<br>celíaca asociada", "c": "g", "x": 99.5, "y": 6, "ax": 96, "ay": 40, "al": "r"}, {"n": "⑥", "t": "Melanocito", "s": "sobrevive en<br>el borde", "c": "g", "x": 0.5, "y": 91, "ax": 6, "ay": 44, "al": "l"}, {"n": "⑥", "t": "LT CD8", "s": "matan al melanocito<br>(PTPN22)", "c": "d", "x": 22, "y": 91, "ax": 21.5, "ay": 46}, {"n": "④", "t": "LT CD8", "s": "atacan la unión<br>dermoepidérmica", "c": "d", "x": 37, "y": 91, "ax": 40, "ay": 46}, {"n": "④", "t": "Fármaco", "s": "dispara a los<br>LT CD8", "c": "g", "x": 54, "y": 91, "ax": 56, "ay": 68}, {"n": "⑤", "t": "Neutrófilos en las papilas", "s": "con IgA<br>granular", "c": "d", "x": 75, "y": 91, "ax": 75, "ay": 50}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = ataque celular</b> (linfocitos T, macrófagos), <b class=\"d\">rojo = ataque por anticuerpos</b> (o complejos inmunes), gris = el tejido o la célula blanco.", "<b>Ampollas:</b> el pénfigo <mark>foliáceo</mark> rompe la desmogleína I arriba, <span class=\"cx\">así que</span> la ampolla es superficial y flácida; el <mark>vulgar</mark> rompe la desmogleína II abajo, en la unión dermoepidérmica, y la ampolla es firme.", "<b>Psoriasis:</b> los LT CD4 liberan IL-2 e IFN-γ y la IL-23 mantiene la hiperplasia; <span class=\"cx\">por eso</span> la epidermis se engruesa y se descama <span class=\"lt2\">A</span>.", "<b>Pulmón:</b> en Goodpasture el anticuerpo contra el colágeno IV α3 tapiza el alvéolo y el glomérulo como una línea <span class=\"lt2\">B</span>; en la sarcoidosis el granuloma Th1 no se caseifica <span class=\"lt2\">C</span>."], "recordar": "Foliáceo = Uno (desmogleína I), arriba y flácido; vulgar = Dos (desmogleína II), abajo y firme. Goodpasture = IgG <b>lineal</b>; complejos = <b>granular</b>. Sarcoidosis = granuloma sin queso. EPOC: el esteroide alarga la vida del neutrófilo."}, "numeros": [{"l": "A", "html": "<b>Psoriasis</b>: <b class=\"a\">2 %</b> de la población; concordancia en gemelos idénticos <b class=\"a\">70 %</b> (dicigóticos 20 %); artritis psoriásica en <b class=\"a\">5–20 %</b>.", "rango": null}, {"l": "B", "html": "<b>Alvéolo</b>: los neumocitos tipo I cubren el <b class=\"n\">95 %</b> de la superficie; si mueren, los reemplazan los tipo II y llega la fibrosis.", "rango": null}, {"l": "C", "html": "<b>Sarcoidosis</b>: pulmón en el <b class=\"a\">90 %</b>, uveítis en el <b class=\"a\">25 %</b>. Relación Th1/Treg en pulmón <b class=\"a\">10 a 1</b> (normal <b class=\"n\">0,2 a 1</b>).", "rango": {"min": 0, "max": 12, "unidad": "relación Th1/Treg en pulmón (a 1)", "zonas": [[0, 1, "n"], [1, 12, "a"]], "marcas": [0.2, 10], "valor": 10}}], "escalas": [], "cadena": {"titulo": "Tres armas contra la frontera", "subtitulo": "estímulo → arma (anticuerpo, complejo o célula) → lesión → enfermedad → qué la frena", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> algo vuelve antigénico al tejido: un factor del ambiente (fogo selvagem), <mark>gases de hidrocarburos</mark> (Goodpasture), esporas inhaladas (granjero, palomas), humo del cigarro (EPOC) o un fármaco (sulfas, Stevens-Johnson).", "pr": "anticuerpos, complejos o LT contra la piel o el pulmón.", "pr_tit": "Produce:", "rf": "Preguntas ⑦⑭", "color": "p1"}, {"t": "2. Anticuerpo contra una estructura", "m": "<b>Por qué:</b> la IgG contra la <mark>desmogleína</mark> separa los queratinocitos (ampolla); la IgG contra el <mark>colágeno IV α3</mark> se pega al alvéolo y, por similitud, al glomérulo.", "pr": "ampolla o hemoptisis con glomerulonefritis; depósito <b>lineal</b>.", "pr_tit": "Produce:", "rf": "Preguntas ①②⑧⑨ · punto <span class=\"lt2\">B</span>", "color": "p2"}, {"t": "3. Complejos inmunes", "m": "<b>Qué pasa:</b> el complejo precipita en capilares de la piel (eritema multiforme, Stevens-Johnson) o en el alvéolo (fibrosis pulmonar idiopática, neumonitis alérgica extrínseca con IgG e IgA, IgE normal).", "pr": "complemento, neutrófilos, fibrina; reacción de Arthus a las 4–8 h.", "pr_tit": "Produce:", "rf": "Pregunta ⑩", "color": "p3"}, {"t": "4. Linfocito T", "m": "<b>Por qué:</b> LT CD4 con IL-2, IFN-γ e <mark>IL-23</mark> (psoriasis); LT CD8 desatados por fármacos (necrólisis epidérmica tóxica); Th1 en el granuloma (sarcoidosis); LT CD8 que inducen apoptosis del epitelio (EPOC).", "pr": "placa descamativa, piel despegada, granuloma o destrucción alveolar.", "pr_tit": "Produce:", "rf": "Preguntas ③④⑪ · puntos <span class=\"lt2\">A</span><span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Si no se frena (EPOC)", "m": "<b>Qué pasa:</b> el humo activa <mark>TLR2 y TLR4</mark>; llegan neutrófilos con elastasa. En el fumador la LTA4H no degrada el quimioatrayente y, sin antitripsina alfa, la elastasa no tiene freno.", "pr": "inflamación neutrofílica crónica, enfisema y fibrosis (TGFβ).", "pr_tit": "Produce:", "rf": "Preguntas ⑫⑬", "color": "p4"}, {"t": "6. Tratamiento", "m": "<b>Qué se usa:</b> esteroides y <mark>rituximab</mark> (pénfigo), ustekinumab anti-p40 (psoriasis), plasmaféresis + inmunosupresión (Goodpasture), corticoides y metotrexato (sarcoidosis). En la EPOC el esteroide sirve poco.", "pr": "control de la lesión según el arma que la produce.", "pr_tit": "Produce:", "rf": "Preguntas ③⑭", "color": "p1"}], "extra": [{"html": "🧴 <b>Otras de la piel:</b> dermatitis herpetiforme (prurito intenso, la mitad con enteropatía por gluten), dermatitis de contacto (IL-23 del queratinocito → Th17 + IL-22, baja la claudina-1), mastocitosis (factor de crecimiento del mastocito) y vitiligo (pérdida de melanocitos; PTPN22 → más autoinmunes). Preguntas ⑤⑥.", "k": ""}, {"html": "☠️ <b>Piel grave:</b> necrólisis epidérmica tóxica hasta el <mark>30 %</mark> de la piel con mortalidad del <mark>25 %</mark> (LT CD8 por fármacos); Stevens-Johnson compromete mucosas en el 10 % (complejos inmunes, sulfas). Pregunta ④.", "k": ""}, {"html": "🔍 <b>Lineal o granular:</b> el anticuerpo que se pega a la membrana basal la dibuja como una <mark>línea continua</mark> (Goodpasture). Los complejos que caen desde la sangre quedan en <mark>grumos</mark> (granular).", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Del cigarro al enfisema", "pasos": ["humo: más de 2000 xenobióticos y radicales libres", "TLR2 y TLR4: neutrófilos y macrófagos con proteasas", "la LTA4H no apaga el quimioatrayente", "LT CD8 inducen apoptosis del epitelio", "<b>EPOC irreversible</b>: enfisema y fibrosis"]}], "html": "", "fuente": "Fuente: tu teoría — clase 47 (pénfigos, dermatitis herpetiforme, psoriasis, afecciones sistémicas, dermatitis de contacto, vitiligo) y clase 48 (fibrosis pulmonar, Goodpasture, complejos inmunes, neumonitis alérgica extrínseca, sarcoidosis, EPOC)."}, "preguntas": [{"n": 1, "id": "IN19-015", "c": "d", "tema": "Pénfigos", "pregunta": "En el pénfigo foliáceo, los anticuerpos IgG se dirigen contra:", "opciones": ["a. Desmogleína I", "b. Desmogleína II", "c. Desmoplaquina I", "d. Colágeno IV α3", "e. Filagrina"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Desmogleína I, en los espacios intercelulares de la epidermis superficial.", "sin_banco": true, "ok": "", "x": "Es la ampolla pequeña de la izquierda, alta en la epidermis: la <mark>desmogleína I</mark> une las capas de arriba. <span class=\"cx\">Por eso</span> el techo es fino y <span class=\"res\">flácido</span>: <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN19-016", "c": "d", "tema": "Pénfigos", "pregunta": "Respecto al pénfigo vulgar, es correcto:", "opciones": ["a. Forma ampollas superficiales y flácidas", "b. Ataca la desmogleína I", "c. Tiene una forma endémica llamada fogo selvagem", "d. Es mediado por IgE", "e. Forma ampollas profundas y firmes, con anticuerpos contra desmogleína II y complejos inmunes"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Ampolla profunda y firme: anticuerpos contra desmogleína II y complejos inmunes, con daño en hemidesmosomas.", "sin_banco": true, "ok": "", "x": "Es la ampolla grande de la derecha: el plano está en la <mark>unión dermoepidérmica</mark> y el techo es toda la epidermis. <span class=\"cx\">Por eso</span> es firme: <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN19-017", "c": "i", "tema": "Psoriasis", "pregunta": "El ustekinumab, usado en la psoriasis, actúa sobre:", "opciones": ["a. El TNF-α", "b. La molécula LFA-1α", "c. El CD20", "d. La subunidad p40 compartida por IL-12 e IL-23", "e. La IgG4"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La subunidad p40, común a IL-12 e IL-23.", "sin_banco": true, "ok": "", "x": "Míralo en la placa de psoriasis (punto Ⓐ): la <mark>IL-23</mark> mantiene la hiperplasia. El ustekinumab bloquea la p40, compartida por IL-12 e IL-23: <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN19-018", "c": "i", "tema": "Afecciones sistémicas con manifestaciones cutáneas", "pregunta": "La necrólisis epidérmica tóxica se debe principalmente a:", "opciones": ["a. Hiperactividad de linfocitos T CD8 inducida por medicamentos", "b. Anticuerpos contra desmogleína II", "c. Precipitación de complejos inmunes en capilares", "d. Degranulación de mastocitos por IgE", "e. Proliferación de LT CD4 CLA+"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Linfocitos T CD8 hiperactivos inducidos por fármacos.", "sin_banco": true, "ok": "", "x": "Los <mark>LT CD8</mark> matan queratinocitos en masa; <span class=\"cx\">por eso</span> puede despegarse hasta el <span class=\"res\">30 % de la piel</span>, con mortalidad del <span class=\"res\">25 %</span>. <span class=\"cx\">En cambio</span>, el eritema multiforme y el Stevens-Johnson se deben a complejos inmunes en los capilares.", "truco": "NET = «CD8 desatado por un fármaco».", "veces": 0}, {"n": 5, "id": "IN19-019", "c": "d", "tema": "Dermatitis herpetiforme", "pregunta": "¿Con qué enfermedad digestiva se asocia la dermatitis herpetiforme y cuál es su síntoma dominante?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Con la enteropatía por gluten (enfermedad celíaca); la mitad tiene alteración intestinal. El síntoma dominante es un prurito intenso.", "sin_banco": true, "ok": "", "x": "El <mark>prurito</mark> lleva al rascado, <span class=\"cx\">así que</span> muchas vesículas se destruyen antes de examinarlas. La mitad de los pacientes tiene alteración intestinal y el 25 % anticuerpos antirreticulares IgG e IgA; <span class=\"cx\">por eso</span> mejora con <span class=\"res\">dieta sin gluten</span>.", "truco": "Herpetiforme = «pica y es celíaca».", "veces": 0}, {"n": 6, "id": "IN19-020", "c": "g", "tema": "Vitiligo", "pregunta": "¿Qué es el vitiligo, a qué porcentaje de la población afecta y qué implica la alteración del gen PTPN22?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Pérdida autoinmune de melanocitos con parches despigmentados; afecta al 0,5 % de la población. Con PTPN22 alterado sube el riesgo de tiroiditis, diabetes, psoriasis y artritis reumatoide.", "sin_banco": true, "ok": "", "x": "Es la despigmentación <mark>más frecuente</mark>. Se asocian HLA-DQA1, HLA-DRB21, NLRP1 y TYR; y <span class=\"cx\">cuando</span> falla <mark>PTPN22</mark> el paciente tiende a la <span class=\"res\">poliautoinmunidad</span>.", "truco": "Vitiligo: «medio por ciento sin melanocitos».", "veces": 0}, {"n": 7, "id": "IN19-021", "c": "d", "tema": "Pénfigos", "pregunta": "Agricultor de la selva peruana con ampollas superficiales flácidas que se rompen dejando erosiones, sin lesiones en mucosas. ¿Diagnóstico, blanco del anticuerpo y principal riesgo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Pénfigo foliáceo endémico (fogo selvagem): IgG contra desmogleína I. Puede matar por desequilibrio electrolítico o infección sobreagregada.", "sin_banco": true, "ok": "", "x": "La forma <mark>endémica</mark> aparece en Brasil, Colombia, Bolivia, Perú, Venezuela y Túnez, con un desencadenante externo aún no identificado. Las erosiones pierden líquido y se infectan; <span class=\"cx\">por eso</span> es de las pocas dermatosis que <span class=\"res\">pueden matar</span>. Se trata con esteroides y rituximab.", "truco": "Fogo selvagem = «fuego salvaje» en la piel de arriba.", "veces": 0}, {"n": 8, "id": "IN19-022", "c": "d", "tema": "Síndrome de Goodpasture", "pregunta": "En el síndrome de Goodpasture, los autoanticuerpos se dirigen contra:", "opciones": ["a. Proteinasa 3", "b. La cadena α3 del colágeno IV de las membranas basales", "c. Mieloperoxidasa", "d. Desmogleína II", "e. Colágeno I del intersticio"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La cadena α3 del colágeno IV, presente en la membrana basal del alvéolo y del glomérulo.", "sin_banco": true, "ok": "", "x": "En la imagen el alvéolo y el glomérulo tienen la misma línea naranja: es la IgG contra el <mark>colágeno IV α3</mark>, que ambos comparten. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN19-023", "c": "d", "tema": "Síndrome de Goodpasture", "pregunta": "En la inmunofluorescencia del síndrome de Goodpasture, el depósito de IgG y C3 es:", "opciones": ["a. Granular, en grumos", "b. Mesangial de IgA", "c. Ausente (pauci-inmune)", "d. Subepitelial en jorobas", "e. Lineal y uniforme sobre la membrana basal"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Lineal y uniforme, porque el anticuerpo se pega directo al antígeno estructural de la membrana.", "sin_banco": true, "ok": "", "x": "La línea naranja continua sobre la membrana basal (punto Ⓑ) es el patrón <mark>lineal</mark>: el anticuerpo tapiza la pared en vez de caer en grumos. <span class=\"res\">La e</span>.", "truco": "", "veces": 0}, {"n": 10, "id": "IN19-024", "c": "d", "tema": "Neumonitis alérgica extrínseca", "pregunta": "Sobre la neumonitis alérgica extrínseca, es FALSO:", "opciones": ["a. Cursa con IgE elevada, como una alergia tipo I", "b. Hay anticuerpos IgG e IgA", "c. Combina reacciones tipo III y tipo IV", "d. La intradermorreacción da un fenómeno de Arthus a las 4-8 horas", "e. Los actinomicetos termofílicos causan el pulmón del granjero"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Es falso: la IgE es normal, y eso la separa de la alergia tipo I.", "sin_banco": true, "ok": "", "x": "El antígeno inhalado forma <mark>complejos inmunes</mark> con IgG e IgA (tipo III) y <span class=\"cx\">además</span> actúan LT CD8 (tipo IV). <span class=\"cx\">Por eso</span> el extracto intradérmico da un <span class=\"res\">Arthus</span> intermedio de 4 a 8 horas y no una roncha inmediata.", "truco": "Granjero, palomas, bagazo: «IgG sí, IgE no».", "veces": 0}, {"n": 11, "id": "IN19-025", "c": "i", "tema": "Sarcoidosis", "pregunta": "Es característico de la sarcoidosis:", "opciones": ["a. Granulomas caseificantes", "b. Granulomas no caseificantes con LT CD4 y respuesta Th1", "c. Predominio de respuesta Th2 con IgE alta", "d. Aumento de células NK en sangre periférica", "e. Afecta sobre todo el riñón"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Granulomas no caseificantes dominados por LT CD4 con respuesta Th1.", "sin_banco": true, "ok": "", "x": "El granuloma de la derecha (punto Ⓒ) tiene un centro sano, <mark>sin caseum</mark>, rodeado de linfocitos: es una respuesta Th1 de LT CD4. <span class=\"res\">La b</span>.", "truco": "", "veces": 0}, {"n": 12, "id": "IN19-026", "c": "i", "tema": "EPOC", "pregunta": "¿Qué papel cumple la enzima LTA4H en la EPOC y qué falla en el fumador?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Normalmente degrada el péptido quimioatrayente de los neutrófilos y apaga la inflamación; en el fumador no lo degrada y la inflamación neutrofílica se vuelve crónica.", "sin_banco": true, "ok": "", "x": "El humo daña el epitelio y sus restos activan <mark>TLR2 y TLR4</mark>; llegan neutrófilos y macrófagos con proteasas. Si la <mark>LTA4H</mark> no corta la señal, los neutrófilos siguen llegando y el daño se hace <span class=\"res\">irreversible</span>.", "truco": "LTA4H = el «interruptor de apagado» que el cigarro rompe.", "veces": 0}, {"n": 13, "id": "IN19-027", "c": "i", "tema": "EPOC", "pregunta": "¿Por qué los corticosteroides controlan mal la EPOC y qué deficiencia congénita aumenta su riesgo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque prolongan la vida de los neutrófilos y perpetúan la inflamación. La deficiencia de antitripsina alfa (1 en 3000-5000 anglosajones) deja sin freno a la elastasa.", "sin_banco": true, "ok": "", "x": "En otras inflamaciones el esteroide apaga; en la EPOC, <span class=\"cx\">en cambio</span>, <mark>alarga la vida del neutrófilo</mark>. Sin antitripsina la elastasa del neutrófilo digiere la fibra elástica, <span class=\"cx\">así que</span> aparece <span class=\"res\">enfisema</span>. Los fármacos prometedores inhiben la elastasa o degradan el quimioatrayente.", "truco": "EPOC: «el esteroide le da más vida al neutrófilo».", "veces": 0}, {"n": 14, "id": "IN19-028", "c": "d", "tema": "Síndrome de Goodpasture", "pregunta": "Varón de 28 años que limpia tanques de combustible presenta hemoptisis y, días después, hematuria con creatinina en ascenso. La biopsia renal muestra IgG lineal. ¿Diagnóstico y tratamiento?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome de Goodpasture (enfermedad anti-membrana basal): plasmaféresis para retirar los anticuerpos más inmunosupresión para frenar su producción.", "sin_banco": true, "ok": "", "x": "Los <mark>gases de hidrocarburos</mark> vuelven antigénica la membrana basal alveolar; los anticuerpos atacan <span class=\"cx\">luego</span> al glomérulo por similitud. La plasmaféresis saca lo que ya circula y el inmunosupresor <span class=\"res\">corta la fábrica</span>.", "truco": "Hemoptisis + hematuria + IgG lineal = Goodpasture.", "veces": 0}], "tabla": {"cab": ["", "Blanco", "Arma", "Pista"], "filas": [["Pénfigo foliáceo", "Desmogleína I", "IgG", "Ampolla superficial, flácida"], ["Pénfigo vulgar", "Desmogleína II", "IgG + complejos", "Ampolla profunda, firme"], ["Psoriasis", "Queratinocito", "LT CD4, IL-23", "Placas en codos y rodillas"], ["Goodpasture", "Colágeno IV α3", "IgG + complemento", "IgG lineal; pulmón + riñón"], ["Neumonitis extrínseca", "Antígeno inhalado", "IgG, IgA, LT CD8", "IgE normal; Arthus 4–8 h"], ["Sarcoidosis", "Antígeno no identificado", "LT CD4 Th1", "Granuloma sin caseum"], ["🔑 Para diferenciar", "Profundidad de la ampolla", "Lineal = anticuerpo; granular = complejo", "Sarcoidosis: anergia a tuberculina"]]}, "fuente": "Fuente: tu teoría — clase 47 (Enfermedades autoinmunes de la piel) y clase 48 (Enfermedades autoinmunes del árbol respiratorio), Rojas 17.ª ed."}, {"n": 36, "slug": "Autoinmunidad_digestivo_higado", "titulo": "Autoinmunidad del digestivo y del hígado", "subtitulo": "celíaca, Crohn, colitis ulcerativa, anemia perniciosa, hepatitis y cirrosis biliar primaria", "grupo": "g20", "lema": "La idea: el intestino y el hígado conviven con billones de bacterias y antígenos de la comida, así que viven de la <mark>tolerancia</mark>. Cuando esa tolerancia se rompe aparecen la <b>celíaca</b> (el gluten activa a los LT), <b>Crohn</b> y la <b>colitis ulcerativa</b> (respuesta exagerada a la flora propia) y la <b>anemia perniciosa</b> (anticuerpos contra el factor intrínseco). En el hígado, el principio es otro: <u>el daño no lo hace el virus, sino la respuesta inmune</u> contra el hepatocito; y en la <b>cirrosis biliar primaria</b> los LT destruyen los conductos biliares. En la imagen verás de izquierda a derecha: vellosidades normales frente a atróficas, una célula parietal atacada por anticuerpos y un lobulillo hepático con un hepatocito infectado rodeado de LT y un conducto biliar destruido.", "img": "img/36.webp", "mini": "img/mini/36.webp", "ratio": 1.5, "etiquetas": [{"n": "", "t": "Vellosidades normales", "s": "altas y finas:<br>para comparar", "c": "g", "x": 0.5, "y": 6, "ax": 8.5, "ay": 22, "al": "l"}, {"n": "③", "t": "Gliadina", "s": "entra si falla<br>la zonulina", "c": "g", "x": 28, "y": 6, "ax": 22.8, "ay": 36}, {"n": "①⑦", "t": "Célula parietal", "s": "atacada por<br>anticuerpos", "c": "d", "x": 52, "y": 6, "ax": 52, "ay": 36}, {"n": "⑫", "t": "Hepatocito infectado", "s": "lo matan los LT,<br>no el virus", "c": "i", "x": 99.5, "y": 6, "ax": 80, "ay": 34, "d": "B", "al": "r"}, {"n": "③⑥", "t": "Vellosidad atrófica", "s": "criptas largas<br>y linfocitos", "c": "i", "x": 0.5, "y": 91, "ax": 28, "ay": 48, "d": "A", "al": "l"}, {"n": "③", "t": "Presentadora + LT", "s": "HLA-DQ2/DQ8<br>muestra la gliadina", "c": "i", "x": 32, "y": 91, "ax": 28.6, "ay": 63.5}, {"n": "①", "t": "Factor intrínseco", "s": "bloqueado: la B12<br>no se absorbe", "c": "d", "x": 53, "y": 91, "ax": 49, "ay": 58}, {"n": "⑭", "t": "Anillo de LT", "s": "citotóxicos<br>hasta 10 veces más", "c": "i", "x": 74, "y": 91, "ax": 74, "ay": 67}, {"n": "⑩⑭", "t": "Conducto biliar", "s": "destruido: cirrosis<br>biliar primaria", "c": "g", "x": 99.5, "y": 91, "ax": 85, "ay": 62, "d": "C", "al": "r"}], "diapos": [{"img": "img/36.webp", "ratio": 1.5, "titulo": "Vellosidad, estómago e hígado", "texto": "La gliadina deaminada <mark>atrofia la vellosidad</mark> ③⑥; los anticuerpos contra la célula parietal y el factor intrínseco dan anemia perniciosa ①⑦; los LT destruyen el conducto biliar ⑭.", "etiquetas": [{"n": "", "t": "Vellosidades normales", "s": "altas y finas:<br>para comparar", "c": "g", "x": 0.5, "y": 6, "ax": 8.5, "ay": 22, "al": "l"}, {"n": "③", "t": "Gliadina", "s": "entra si falla<br>la zonulina", "c": "g", "x": 28, "y": 6, "ax": 22.8, "ay": 36}, {"n": "①⑦", "t": "Célula parietal", "s": "atacada por<br>anticuerpos", "c": "d", "x": 52, "y": 6, "ax": 52, "ay": 36}, {"n": "⑫", "t": "Hepatocito infectado", "s": "lo matan los LT,<br>no el virus", "c": "i", "x": 99.5, "y": 6, "ax": 80, "ay": 34, "d": "B", "al": "r"}, {"n": "③⑥", "t": "Vellosidad atrófica", "s": "criptas largas<br>y linfocitos", "c": "i", "x": 0.5, "y": 91, "ax": 28, "ay": 48, "d": "A", "al": "l"}, {"n": "③", "t": "Presentadora + LT", "s": "HLA-DQ2/DQ8<br>muestra la gliadina", "c": "i", "x": 32, "y": 91, "ax": 28.6, "ay": 63.5}, {"n": "①", "t": "Factor intrínseco", "s": "bloqueado: la B12<br>no se absorbe", "c": "d", "x": 53, "y": 91, "ax": 49, "ay": 58}, {"n": "⑭", "t": "Anillo de LT", "s": "citotóxicos<br>hasta 10 veces más", "c": "i", "x": 74, "y": 91, "ax": 74, "ay": 67}, {"n": "⑩⑭", "t": "Conducto biliar", "s": "destruido: cirrosis<br>biliar primaria", "c": "g", "x": 99.5, "y": 91, "ax": 85, "ay": 62, "d": "C", "al": "r"}]}, {"img": "img/36_2.webp", "ratio": 1.5, "titulo": "Crohn, colitis y células de Paneth", "texto": "Crohn = <mark>íleon</mark>, transmural, salteado y con fístulas; la colitis ulcerativa = colon continuo y superficial ④; la célula de <mark>Paneth</mark> libera criptidinas reguladas por <b>NOD2</b> ②⑤ <span class=\"lt2\">A</span>.", "etiquetas": [{"n": "④", "t": "Íleon con Crohn", "s": "pared gruesa,<br>lesiones salteadas", "c": "i", "x": 0.5, "y": 6, "ax": 7, "ay": 30, "al": "l"}, {"n": "④", "t": "Empedrado", "s": "úlceras y fisuras<br>que atraviesan", "c": "i", "x": 25, "y": 6, "ax": 25, "ay": 47}, {"n": "④", "t": "Pseudopólipos", "s": "colitis: solo<br>la mucosa", "c": "d", "x": 46, "y": 6, "ax": 45.5, "ay": 34}, {"n": "⑤", "t": "Criptidinas", "s": "gotas que matan<br>bacterias", "c": "i", "x": 68, "y": 6, "ax": 80, "ay": 41}, {"n": "⑤", "t": "Bacterias de la flora", "s": "en la luz<br>de la cripta", "c": "g", "x": 99.5, "y": 6, "ax": 84, "ay": 27, "al": "r"}, {"n": "④", "t": "Fístula", "s": "sale del intestino:<br>daño transmural", "c": "i", "x": 0.5, "y": 91, "ax": 15, "ay": 54, "al": "l"}, {"n": "④", "t": "Colon continuo", "s": "superficial,<br>desde el recto", "c": "d", "x": 40, "y": 91, "ax": 50, "ay": 70}, {"n": "②⑤", "t": "Célula de Paneth", "s": "base de la cripta;<br>NOD2 la regula", "c": "i", "x": 68, "y": 91, "ax": 76, "ay": 55, "d": "A"}, {"n": "⑤", "t": "Gránulos", "s": "defensinas<br>guardadas", "c": "g", "x": 99.5, "y": 91, "ax": 88, "ay": 52, "al": "r"}]}, {"img": "img/36_3.webp", "ratio": 1.5, "titulo": "Hepatitis B: tres desenlaces", "texto": "Las NK son el <mark>50 %</mark> de los leucocitos del hígado ⑧ <span class=\"lt2\">B</span>; la respuesta decide: curación, portador o necrosis masiva ⑫; los complejos virus-anticuerpo dan vasculitis y glomerulitis ⑬, y el <b>HBe</b> predice cronicidad ⑨.", "etiquetas": [{"n": "⑧", "t": "Células NK", "s": "50 % de los<br>leucocitos", "c": "i", "x": 0.5, "y": 6, "ax": 6, "ay": 28, "d": "B", "al": "l"}, {"n": "⑨", "t": "Partícula de Dane", "s": "su HBe predice<br>cronicidad", "c": "g", "x": 25, "y": 6, "ax": 26.7, "ay": 38.5}, {"n": "⑫", "t": "Curación", "s": "respuesta adecuada:<br>virus eliminado", "c": "i", "x": 47, "y": 6, "ax": 47, "ay": 23}, {"n": "⑬", "t": "Complejos inmunes", "s": "anti-VHB + antígeno<br>en la pared", "c": "d", "x": 69, "y": 6, "ax": 77, "ay": 29}, {"n": "⑬", "t": "Glomérulo", "s": "glomerulitis<br>por depósito", "c": "d", "x": 99.5, "y": 6, "ax": 90, "ay": 38, "al": "r"}, {"n": "", "t": "Célula de Kupffer", "s": "macrófago del<br>sinusoide", "c": "i", "x": 0.5, "y": 91, "ax": 28.6, "ay": 46, "al": "l"}, {"n": "⑫", "t": "Portador", "s": "respuesta débil:<br>el virus persiste", "c": "g", "x": 30, "y": 91, "ax": 43, "ay": 47}, {"n": "⑫", "t": "Necrosis masiva", "s": "muchos LT<br>citotóxicos", "c": "i", "x": 51, "y": 91, "ax": 47, "ay": 74}, {"n": "⑬", "t": "Neutrófilos", "s": "vasculitis, como<br>enfermedad del suero", "c": "d", "x": 76, "y": 91, "ax": 70, "ay": 42}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = ataque celular</b> (linfocitos T, macrófagos), <b class=\"d\">rojo = ataque por anticuerpos</b> (o complejos inmunes), gris = el tejido o la célula blanco.", "<b>Intestino:</b> la zonulina abre las uniones, entra la gliadina, la <mark>transglutaminasa</mark> la deamina y el HLA-DQ2/DQ8 la presenta al LT; <span class=\"cx\">por eso</span> las vellosidades se aplanan y las criptas crecen <span class=\"lt2\">A</span>.", "<b>Estómago:</b> los anticuerpos atacan a la célula parietal y al <mark>factor intrínseco</mark>; así la vitamina B12 no se absorbe y aparecen los megaloblastos.", "<b>Hígado:</b> el LT citotóxico mata al hepatocito infectado (el virus casi no lo daña) <span class=\"lt2\">B</span>; abajo, los LT destruyen el conducto biliar en la cirrosis biliar primaria <span class=\"lt2\">C</span>."], "recordar": "Celíaca = gluten + transglutaminasa + DQ2/DQ8 → atrofia de vellosidades (IgA anti-transglutaminasa; biopsia). Crohn = íleon + NOD2; colitis = colon + IL-17. Perniciosa = sin factor intrínseco no hay B12. Hepatitis: adecuada cura, débil deja portador, excesiva mata."}, "numeros": [{"l": "A", "html": "<b>Intestino</b>: <b class=\"a\">10¹⁰</b> linfocitos por metro lineal; NOD2 mutado sube <b class=\"a\">40 veces</b> el riesgo de Crohn. Celíaca: <b class=\"a\">1 %</b> de la población, el <b class=\"a\">50 %</b> asintomático.", "rango": null}, {"l": "B", "html": "<b>Hígado</b>: las NK son el <b class=\"a\">50 %</b> de sus leucocitos. VHB: <b class=\"a\">50 %</b> de los hepatocarcinomas; VHC: <b class=\"a\">170 millones</b> de infectados, <b class=\"a\">28 %</b> de las cirrosis.", "rango": null}, {"l": "C", "html": "<b>Cirrosis biliar primaria</b>: antimitocondriales en <b class=\"a\">más del 90 %</b>; LT citotóxicos <b class=\"a\">hasta 10 veces</b> más; gemelos monocigóticos <b class=\"a\">60 %</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "Del gluten a la vellosidad plana", "subtitulo": "estímulo → puerta abierta → antígeno modificado → linfocito → lesión → qué hacer", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> una persona con <mark>HLA-DQ2 o DQ8</mark> come gluten (trigo, avena, cebada). Su gliadina resiste la digestión.", "pr": "llega gliadina intacta al epitelio.", "pr_tit": "Produce:", "rf": "Pregunta ③", "color": "p1"}, {"t": "2. Se abre la puerta", "m": "<b>Por qué:</b> falla la <mark>zonulina</mark>, que regula las uniones estrechas; la mucosa se vuelve permeable y la gliadina entra a la lámina propia.", "pr": "el antígeno queda frente a las células presentadoras.", "pr_tit": "Produce:", "rf": "Pregunta ③", "color": "p2"}, {"t": "3. Antígeno modificado", "m": "<b>Qué produce:</b> la <mark>transglutaminasa tisular</mark> deamina los residuos de glutamina; el péptido encaja mejor en DQ2/DQ8 y se presenta al LT.", "pr": "LT CD4 y CD8 activados; LB que fabrican IgA anti-transglutaminasa.", "pr_tit": "Produce:", "rf": "Preguntas ③⑥", "color": "p3"}, {"t": "4. Lesión", "m": "<b>Qué pasa:</b> los linfocitos infiltran el epitelio: <mark>atrofia de vellosidades</mark> e hipertrofia de criptas.", "pr": "malabsorción y diarrea; a veces dermatitis herpetiforme.", "pr_tit": "Produce:", "rf": "Pregunta ⑥ · punto <span class=\"lt2\">A</span>", "color": "p4"}, {"t": "5. Diagnóstico y manejo", "m": "<b>Qué se hace:</b> serología (IgA antiendosomal) y, sobre todo, <mark>biopsia de mucosa</mark>. Tratamiento: dieta sin gluten.", "pr": "recupera las vellosidades si se retira el gluten.", "pr_tit": "Produce:", "rf": "Pregunta ⑥", "color": "p4"}], "extra": [{"html": "🦠 <b>Crohn frente a colitis ulcerativa:</b> Crohn = íleon y ciego, fístulas, <mark>NOD2</mark> (criptidinas de Paneth), IL-12 e IL-23, concordancia gemelar 50–75 %, infliximab. Colitis ulcerativa = colon difuso, <mark>IL-17</mark> y Th2, reacción cruzada con <b>Yersinia</b> o <b>E. coli</b> O14; artritis, uveítis, eritema nodoso. Preguntas ②④⑤.", "k": ""}, {"html": "💉 <b>Halotano:</b> la primera anestesia vuelve antigénico al hepatocito (hapteno); la <mark>segunda</mark> activa una respuesta celular y da hepatitis postoperatoria. Pregunta ⑪.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Hepatitis: la respuesta decide", "pasos": ["respuesta <b>adecuada</b>: elimina el virus y cura", "respuesta <b>débil</b>: portador sano (VHB)", "respuesta celular <b>intensa y difusa</b>: necrosis masiva", "complejos inmunes fuera del hígado: vasculitis, artritis, riñón (PAN)", "<b>VHB y VHC crónicos</b>: cirrosis y hepatocarcinoma"]}], "html": "", "fuente": "Fuente: tu teoría — clase 49 (GALT, flora, anemia perniciosa, Crohn, colitis ulcerativa, enfermedad celíaca) y clase 50 (hígado inmune, hepatitis A, B, C, E y G, cirrosis biliar primaria, halotano)."}, "preguntas": [{"n": 1, "id": "IN20-001", "c": "d", "tema": "Enfermedades del estómago", "pregunta": "La anemia perniciosa se produce por:", "opciones": ["a. Linfocitos T CD8 contra los enterocitos del íleon", "b. Anticuerpos contra el factor intrínseco y las células parietales", "c. Anticuerpos antitransglutaminasa", "d. Mutaciones de NOD2", "e. Anticuerpos antimitocondriales"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Anticuerpos contra el factor intrínseco y contra las células parietales del estómago.", "sin_banco": true, "ok": "", "x": "En el centro de la imagen los anticuerpos se pegan a la célula parietal y al <mark>factor intrínseco</mark>, <span class=\"cx\">así que</span> las bolitas de B12 quedan sueltas. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN20-002", "c": "i", "tema": "Enfermedad de Crohn", "pregunta": "La mutación que aumenta unas 40 veces la susceptibilidad a la enfermedad de Crohn está en el gen:", "opciones": ["a. IL10", "b. HLA-DQ2", "c. NOD2", "d. FOXP3", "e. CTLA4"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. NOD2, receptor intracelular que regula la producción de criptidinas.", "sin_banco": true, "ok": "", "x": "<mark>NOD2</mark> controla las criptidinas (defensinas de Paneth); sin ellas la defensa innata frente a las bacterias comensales falla, <span class=\"cx\">así que</span> la inflamación se cronifica. <span class=\"cx\">Por eso</span> Crohn es una <span class=\"res\">respuesta exagerada a la flora propia</span> (perfil IL-12/IL-23, Th1).", "truco": "NOD2 × 40 = Crohn.", "veces": 0}, {"n": 3, "id": "IN20-003", "c": "i", "tema": "Enfermedad celíaca", "pregunta": "En la enfermedad celíaca, la enzima que deamina la gliadina y aumenta su afinidad por HLA-DQ2/DQ8 es:", "opciones": ["a. Zonulina", "b. Glucosiltransferasa", "c. Pepsina", "d. Lisozima", "e. Transglutaminasa tisular"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La transglutaminasa tisular.", "sin_banco": true, "ok": "", "x": "Es el paso 3 de la cadena: la <mark>transglutaminasa</mark> afila la gliadina para que encaje en DQ2/DQ8. La zonulina solo abre la puerta (paso 2). <span class=\"res\">La e</span>.", "truco": "", "veces": 0}, {"n": 4, "id": "IN20-004", "c": "i", "tema": "Enfermedades inflamatorias del intestino", "pregunta": "Respecto a la enfermedad de Crohn y la colitis ulcerativa, es FALSO:", "opciones": ["a. Ambas son poligénicas y aumentan el riesgo de cáncer de colon", "b. Crohn tiene concordancia gemelar de 50-75 %", "c. La colitis ulcerativa se localiza en íleon y ciego y forma fístulas", "d. En la colitis ulcerativa aumenta mucho la IL-17", "e. Crohn se trata con infliximab (anti-TNF)"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Es falso: íleon, ciego y fístulas son de Crohn; la colitis ulcerativa es difusa y del colon.", "sin_banco": true, "ok": "", "x": "<mark>Crohn</mark> = íleon y ciego, fístulas, IL-12/IL-23, NOD2. <mark>Colitis ulcerativa</mark> = colon difuso, IL-17 y Th2, posible reacción cruzada con <b>Yersinia</b> o <b>E. coli</b> O14. <span class=\"cx\">Por eso</span> la CU tiene <span class=\"res\">más peso ambiental</span> y menos concordancia gemelar.", "truco": "Crohn «come» íleon; la colitis se queda en el colon.", "veces": 0}, {"n": 5, "id": "IN20-005", "c": "g", "tema": "El tracto digestivo como órgano inmune", "pregunta": "¿Qué son las células de Paneth y qué secretan?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Células de la base de las criptas de Lieberkühn que guardan gránulos de defensinas (criptidinas) y los liberan ante patógenos.", "sin_banco": true, "ok": "", "x": "Son parte de la <mark>inmunidad innata</mark> intestinal, junto al mucus, el peristaltismo y la lisozima. Su producción la regula NOD2; <span class=\"cx\">por eso</span>, si NOD2 falla, <span class=\"res\">faltan criptidinas</span> y se favorece Crohn.", "truco": "Paneth = «panadería de defensinas» al fondo de la cripta.", "veces": 0}, {"n": 6, "id": "IN20-006", "c": "d", "tema": "Enfermedad celíaca", "pregunta": "¿Cuál es el marcador serológico característico de la enfermedad celíaca y cuál la prueba diagnóstica más importante?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Anticuerpos IgA antiendosomales (anti-transglutaminasa); la prueba más importante es la biopsia de mucosa intestinal.", "sin_banco": true, "ok": "", "x": "La imagen muestra lo que ve la biopsia (punto Ⓐ): vellosidades planas y criptas largas. La serología orienta, pero la <mark>biopsia</mark> confirma.", "truco": "", "veces": 0}, {"n": 7, "id": "IN20-007", "c": "d", "tema": "Enfermedades del estómago", "pregunta": "Mujer de 45 años con tiroiditis de Hashimoto presenta palidez, glositis y parestesias; el frotis muestra macrocitos. ¿Qué enfermedad sospecha y qué anticuerpos buscaría?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Anemia perniciosa: anticuerpos contra el factor intrínseco y contra las células parietales gástricas (déficit de vitamina B12).", "sin_banco": true, "ok": "", "x": "La anemia perniciosa se agrupa con <mark>Hashimoto, Addison y vitiligo</mark>: es poliautoinmunidad. Sin factor intrínseco no se absorbe B12, <span class=\"cx\">por eso</span> hay <span class=\"res\">megaloblastos</span> y parestesias por daño neurológico (literatura).", "truco": "Tiroides autoinmune + macrocitosis = piensa en perniciosa.", "veces": 0}, {"n": 8, "id": "IN20-008", "c": "i", "tema": "El hígado como órgano inmune", "pregunta": "Del total de leucocitos del hígado, las células NK representan aproximadamente:", "opciones": ["a. 5 %", "b. 10 %", "c. 25 %", "d. 50 %", "e. 80 %"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El 50 %; además, un 8 % son células de Ito.", "sin_banco": true, "ok": "", "x": "El hígado es <mark>rico en NK</mark> y tiene Kupffer, que limpian lo que llega por la porta, y células de Ito, que hacen fibrosis. Esa tolerancia especial explica que el <span class=\"res\">trasplante hepático se tolere mejor que el renal</span>.", "truco": "Hígado: «la mitad, NK».", "veces": 0}, {"n": 9, "id": "IN20-009", "c": "d", "tema": "Hepatitis B", "pregunta": "¿Qué antígeno del virus de la hepatitis B, al cuantificarse en suero, predice la evolución a hepatitis crónica?", "opciones": ["a. HBe", "b. HBs", "c. HBc", "d. HL-AG", "e. Anti-HBs"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. El HBe (partículas Dane).", "sin_banco": true, "ok": "", "x": "El <mark>HBe</mark> refleja replicación activa; <span class=\"cx\">por eso</span> su cuantificación anticipa la cronicidad. El HBc da IgM en la fase aguda y <span class=\"cx\">luego</span> IgG; el HBs aparece desde el final de la incubación y el <span class=\"res\">anti-HBs</span> marca la convalecencia.", "truco": "HBe = «E de evolución crónica».", "veces": 0}, {"n": 10, "id": "IN20-010", "c": "d", "tema": "Cirrosis biliar primaria", "pregunta": "El marcador serológico de la cirrosis biliar primaria, presente en más del 90 %, es:", "opciones": ["a. Anti-músculo liso", "b. Anti-transglutaminasa", "c. Anticuerpos antimitocondriales contra la subunidad E2 de la deshidrogenasa pirúvica", "d. ANCA anti-mieloperoxidasa", "e. Anti-Ro"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Anticuerpos antimitocondriales contra la subunidad E2 del complejo de la deshidrogenasa pirúvica.", "sin_banco": true, "ok": "", "x": "Los <mark>antimitocondriales</mark> pueden aparecer <span class=\"res\">años antes</span> de los síntomas; <span class=\"cx\">por eso</span> sirven para un diagnóstico temprano. Pero quienes destruyen los conductos biliares son los LT citotóxicos, que suben hasta diez veces.", "truco": "CBP: «la mitocondria delata al conducto».", "veces": 0}, {"n": 11, "id": "IN20-011", "c": "i", "tema": "Daño hepático por halotano", "pregunta": "Paciente que recibe halotano por segunda vez y desarrolla hepatitis postoperatoria. El mecanismo es:", "opciones": ["a. Toxicidad directa dependiente de la dosis", "b. Anticuerpos antimitocondriales", "c. El halotano vuelve antigénico al hepatocito y la reexposición activa la inmunidad celular", "d. Reactivación del virus de la hepatitis B", "e. Hipersensibilidad tipo I mediada por IgE"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. El halotano altera al hepatocito (hapteno); la segunda exposición activa una respuesta celular que lo daña.", "sin_banco": true, "ok": "", "x": "La primera dosis <mark>sensibiliza</mark>: el fármaco modifica proteínas del hepatocito. <span class=\"cx\">Por eso</span> el daño aparece en la <span class=\"res\">segunda administración</span>, como respuesta de inmunidad celular contra un hapteno.", "truco": "Halotano: «la segunda anestesia es la que duele».", "veces": 0}, {"n": 12, "id": "IN20-012", "c": "i", "tema": "Hepatitis virales", "pregunta": "Explique el principio de la respuesta inmune que decide la evolución de una hepatitis viral.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Respuesta adecuada = curación; respuesta débil = portador sano; respuesta celular hiperagresiva = necrosis masiva de hepatocitos, potencialmente mortal.", "sin_banco": true, "ok": "", "x": "Míralo arriba a la derecha (punto Ⓑ): el virus está dentro del hepatocito, pero quienes lo matan son los <mark>LT citotóxicos</mark>. <span class=\"cx\">Por eso</span> la fuerza de la respuesta decide el cuadro.", "truco": "", "veces": 0}, {"n": 13, "id": "IN20-013", "c": "d", "tema": "Hepatitis B", "pregunta": "¿Por qué las manifestaciones extrahepáticas de la hepatitis B recuerdan a la enfermedad del suero?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque se forman complejos inmunes (anticuerpos anti-VHB + antígenos virales) que precipitan en piel, articulaciones y riñón: vasculitis, eritema, artritis y daño renal.", "sin_banco": true, "ok": "", "x": "Es una hipersensibilidad <mark>tipo III</mark> como la enfermedad del suero. <span class=\"cx\">Por eso</span> el VHB se asocia a <span class=\"res\">poliarteritis nodosa</span>: el 50 % de los pacientes con PAN tiene historia de hepatitis B.", "truco": "VHB fuera del hígado = complejos inmunes de paseo.", "veces": 0}, {"n": 14, "id": "IN20-014", "c": "i", "tema": "Cirrosis biliar primaria", "pregunta": "Mujer de 58 años con fatiga intensa, prurito y fosfatasa alcalina elevada; anticuerpos antimitocondriales positivos. ¿Qué células destruyen los conductos biliares y cuál es el tratamiento de elección?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Cirrosis biliar primaria: los LT citotóxicos (hasta 10 veces aumentados) destruyen los conductos biliares intrahepáticos. Tratamiento: ácido ursodeoxicólico; colestiramina para el prurito.", "sin_banco": true, "ok": "", "x": "Es el conducto de abajo a la derecha (punto Ⓒ): un anillo de <mark>LT citotóxicos</mark> lo destruye. <span class=\"cx\">Por eso</span> hay colestasis, prurito y fatiga; se trata con <span class=\"res\">ácido ursodeoxicólico</span>.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "Dónde", "Mecanismo", "Marcador"], "filas": [["Celíaca", "Intestino delgado", "Gliadina deaminada + DQ2/DQ8 → LT", "IgA anti-transglutaminasa; biopsia"], ["Crohn", "Íleon y ciego", "Respuesta a la flora; NOD2, IL-12/23", "Fístulas"], ["Colitis ulcerativa", "Colon difuso", "Reacción cruzada; IL-17, Th2", "Artritis, uveítis"], ["Anemia perniciosa", "Estómago", "Ac anti-factor intrínseco y anti-parietal", "Megaloblastos, B12 baja"], ["Cirrosis biliar primaria", "Conductos biliares", "LT citotóxicos ×10", "Antimitocondriales (E2)"], ["🔑 Lo que no debes olvidar", "Crohn íleon, colitis colon", "En la hepatitis daña la respuesta, no el virus", "AMA aparecen años antes"]]}, "fuente": "Fuente: tu teoría — clase 49 (Enfermedades autoinmunes del tracto digestivo) y clase 50 (Enfermedades autoinmunes del hígado), Rojas 17.ª ed."}, {"n": 37, "slug": "Autoinmunidad_corazon_rinon", "titulo": "Autoinmunidad del corazón, los vasos y el riñón", "subtitulo": "fiebre reumática, vasculitis, glomerulonefritis y síndrome nefrótico", "grupo": "g20", "lema": "La idea: el corazón se daña sobre todo por <mark>mimetismo molecular</mark> (los anticuerpos contra la proteína M del estreptococo atacan válvulas y miocardio) o por anticuerpos maternos (anti-Ro, bloqueo congénito). Los vasos se inflaman por <mark>complejos inmunes</mark>, ANCA o granulomas, y se clasifican por su calibre. El riñón filtra y acumula complejos inmunes; por eso casi todas sus enfermedades son autoinmunes. Importa porque el <u>patrón en la inmunofluorescencia</u> —lineal, granular o mesangial— dice el mecanismo. En la imagen: corazón con estreptococo, arteria inflamada y glomérulo con dos ampliaciones (lineal arriba, granular abajo).", "img": "img/37.webp", "mini": "img/mini/37.webp", "ratio": 1.5, "etiquetas": [{"n": "①⑭", "t": "Estreptococo", "s": "proteína M:<br>mimetismo", "c": "g", "x": 0.5, "y": 6, "ax": 19.5, "ay": 22, "al": "l"}, {"n": "①", "t": "IgG en la válvula", "s": "reacción cruzada:<br>fiebre reumática", "c": "d", "x": 31, "y": 6, "ax": 21.5, "ay": 32}, {"n": "", "t": "Aneurisma", "s": "panarteritis<br>nodosa", "c": "g", "x": 53, "y": 6, "ax": 59, "ay": 29, "d": "A"}, {"n": "⑫", "t": "Depósito lineal", "s": "anti-MBG:<br>contra la pared", "c": "d", "x": 82, "y": 6, "ax": 89, "ay": 17, "al": "r"}, {"n": "①", "t": "Cuerpo de Aschoff", "s": "granuloma<br>del miocardio", "c": "i", "x": 0.5, "y": 91, "ax": 17, "ay": 60.5, "al": "l"}, {"n": "⑦", "t": "Complejos inmunes", "s": "en el endotelio:<br>vasculitis", "c": "d", "x": 28, "y": 91, "ax": 51.4, "ay": 45.5}, {"n": "", "t": "Pared con neutrófilos", "s": "necrosis<br>fibrinoide", "c": "i", "x": 50, "y": 91, "ax": 56, "ay": 65}, {"n": "⑧", "t": "Mesangio", "s": "IgA1 sin galactosa:<br>nefropatía por IgA", "c": "d", "x": 71, "y": 91, "ax": 82, "ay": 47, "d": "C"}, {"n": "⑫⑭", "t": "Depósito granular", "s": "complejos + C3b:<br>posestreptocócica", "c": "d", "x": 99.5, "y": 91, "ax": 90.5, "ay": 77, "d": "B", "al": "r"}], "diapos": [{"img": "img/37.webp", "ratio": 1.5, "titulo": "Corazón, arteria y glomérulo", "texto": "Mimetismo con la <mark>proteína M</mark> en el corazón ①; complejos inmunes en la arteria ⑦; en el glomérulo, depósito <b>lineal</b>, <b>granular</b> o <b>mesangial</b> ⑧⑫⑭.", "etiquetas": [{"n": "①⑭", "t": "Estreptococo", "s": "proteína M:<br>mimetismo", "c": "g", "x": 0.5, "y": 6, "ax": 19.5, "ay": 22, "al": "l"}, {"n": "①", "t": "IgG en la válvula", "s": "reacción cruzada:<br>fiebre reumática", "c": "d", "x": 31, "y": 6, "ax": 21.5, "ay": 32}, {"n": "", "t": "Aneurisma", "s": "panarteritis<br>nodosa", "c": "g", "x": 53, "y": 6, "ax": 59, "ay": 29, "d": "A"}, {"n": "⑫", "t": "Depósito lineal", "s": "anti-MBG:<br>contra la pared", "c": "d", "x": 82, "y": 6, "ax": 89, "ay": 17, "al": "r"}, {"n": "①", "t": "Cuerpo de Aschoff", "s": "granuloma<br>del miocardio", "c": "i", "x": 0.5, "y": 91, "ax": 17, "ay": 60.5, "al": "l"}, {"n": "⑦", "t": "Complejos inmunes", "s": "en el endotelio:<br>vasculitis", "c": "d", "x": 28, "y": 91, "ax": 51.4, "ay": 45.5}, {"n": "", "t": "Pared con neutrófilos", "s": "necrosis<br>fibrinoide", "c": "i", "x": 50, "y": 91, "ax": 56, "ay": 65}, {"n": "⑧", "t": "Mesangio", "s": "IgA1 sin galactosa:<br>nefropatía por IgA", "c": "d", "x": 71, "y": 91, "ax": 82, "ay": 47, "d": "C"}, {"n": "⑫⑭", "t": "Depósito granular", "s": "complejos + C3b:<br>posestreptocócica", "c": "d", "x": 99.5, "y": 91, "ax": 90.5, "ay": 77, "d": "B", "al": "r"}]}, {"img": "img/37_2.webp", "ratio": 1.5, "titulo": "Vasculitis según el calibre", "texto": "De grande a pequeño: <mark>Takayasu</mark> y células gigantes ⑥, <mark>Kawasaki</mark> ④, ANCA de los neutrófilos ③ y la púrpura por IgA de Henoch-Schönlein ⑦.", "etiquetas": [{"n": "⑥", "t": "Aorta estrechada", "s": "Takayasu: mujer joven<br>sin pulsos", "c": "i", "x": 0.5, "y": 6, "ax": 17.5, "ay": 45, "al": "l"}, {"n": "⑥", "t": "Células gigantes", "s": "arteria temporal:<br>más de 50 años", "c": "i", "x": 36, "y": 6, "ax": 49.5, "ay": 41, "d": "E"}, {"n": "④", "t": "Aneurisma coronario", "s": "Kawasaki: niño,<br>gammaglobulina IV", "c": "d", "x": 62, "y": 6, "ax": 68, "ay": 44}, {"n": "⑦", "t": "Complejos de IgA", "s": "Henoch-Schönlein:<br>vaso pequeño", "c": "d", "x": 99.5, "y": 6, "ax": 79, "ay": 44, "al": "r"}, {"n": "⑥", "t": "Granuloma en la pared", "s": "grandes vasos:<br>aorta y ramas", "c": "i", "x": 0.5, "y": 91, "ax": 9.5, "ay": 57, "al": "l"}, {"n": "⑥", "t": "Lámina elástica rota", "s": "rodeada de<br>células gigantes", "c": "i", "x": 32, "y": 91, "ax": 40.5, "ay": 52}, {"n": "③", "t": "Neutrófilo activado", "s": "ANCA: PR3 o MPO<br>de sus gránulos", "c": "d", "x": 62, "y": 91, "ax": 85.5, "ay": 52}, {"n": "⑦", "t": "Púrpura palpable", "s": "eritrocitos fuera,<br>plaquetas normales", "c": "d", "x": 99.5, "y": 91, "ax": 89, "ay": 63, "al": "r"}]}, {"img": "img/37_3.webp", "ratio": 1.5, "titulo": "La barrera del glomérulo", "texto": "<span class=\"cx\">Cuando</span> el podocito se daña, la albúmina se escapa: <span class=\"res\">síndrome nefrótico</span> ⑨⑬. La IgG4 contra el receptor de fosfolipasa A2 ⑩ y la vía alterna sin freno (SHU atípico) ⑪ son otras formas de romperla.", "etiquetas": [{"n": "⑬", "t": "Albúmina retenida", "s": "barrera sana:<br>no pasa a la orina", "c": "g", "x": 0.5, "y": 6, "ax": 22, "ay": 25, "al": "l"}, {"n": "⑪", "t": "Microtrombo", "s": "SHU atípico: vía alterna<br>sin factor H ni CD46", "c": "d", "x": 45, "y": 6, "ax": 66, "ay": 30}, {"n": "⑪", "t": "Poro de complemento", "s": "daña el<br>endotelio", "c": "d", "x": 70, "y": 6, "ax": 69.5, "ay": 38}, {"n": "⑪", "t": "Eritrocito roto", "s": "hemólisis<br>en el capilar", "c": "d", "x": 99.5, "y": 6, "ax": 81, "ay": 30, "al": "r"}, {"n": "⑨", "t": "Pedicelos interdigitados", "s": "podocito sano:<br>filtro fino", "c": "g", "x": 0.5, "y": 91, "ax": 24, "ay": 60, "al": "l"}, {"n": "", "t": "Membrana basal", "s": "entre endotelio<br>y podocito", "c": "g", "x": 31, "y": 91, "ax": 31, "ay": 46}, {"n": "⑨⑬", "t": "Pedicelos fusionados", "s": "podocito dañado:<br>síndrome nefrótico", "c": "g", "x": 51, "y": 91, "ax": 62, "ay": 58}, {"n": "⑩", "t": "IgG4 en su receptor", "s": "receptor de PLA2<br>del podocito: membranosa", "c": "d", "x": 71, "y": 91, "ax": 77, "ay": 51}, {"n": "⑬", "t": "Albúmina en la orina", "s": "proteinuria<br>en rango nefrótico", "c": "d", "x": 99.5, "y": 91, "ax": 80, "ay": 67, "d": "D", "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = ataque celular</b> (linfocitos T, macrófagos), <b class=\"d\">rojo = ataque por anticuerpos</b> (o complejos inmunes), gris = el tejido o la célula blanco.", "<b>Corazón:</b> la IgG contra la <mark>proteína M</mark> reconoce endocardio, miocardio, sinovial y glomérulo; el cuerpo de Aschoff prueba que el ataque sigue activo.", "<b>Arteria:</b> en la panarteritis nodosa los neutrófilos y la necrosis fibrinoide debilitan la pared y aparecen <mark>aneurismas</mark> <span class=\"lt2\">A</span>.", "<b>Glomérulo:</b> arriba, el anticuerpo contra la membrana basal la dibuja como una <mark>línea</mark> (anti-MBG); abajo, los complejos caen en <mark>grumos</mark> con C3 (posestreptocócica) <span class=\"lt2\">B</span>. En el mesangio se acumula la IgA1 <span class=\"lt2\">C</span>."], "recordar": "Proteína M → mimetismo → fiebre reumática (Aschoff). Anti-Ro materno → bloqueo congénito que se va a los 6 meses. ANCA (PR3/MPO) = Wegener, Churg-Strauss, poliangeítis microscópica. Lineal = anti-MBG; granular = complejos; mesangial = IgA."}, "numeros": [{"l": "A", "html": "<b>Panarteritis nodosa</b>: aneurismas de <b class=\"a\">hasta 1 cm</b>; riñón afectado en el <b class=\"a\">70 %</b>; historia de hepatitis B en el <b class=\"a\">50 %</b>.", "rango": null}, {"l": "B", "html": "<b>Glomerulonefritis posestreptocócica</b>: aparece <b class=\"a\">10 a 15 días</b> después de la faringitis; C3 sérico <b class=\"b\">bajo</b>.", "rango": {"min": 0, "max": 21, "unidad": "días", "zonas": [[0, 10, "m", "latencia"], [10, 15, "a", "glomerulonefritis"]], "marcas": [10, 15], "valor": 12}}, {"l": "C", "html": "<b>Nefropatía por IgA</b> a los <b class=\"a\">15 años</b>: <b class=\"a\">20 %</b> pierde función renal, <b class=\"a\">8 %</b> llega a insuficiencia, <b class=\"n\">12 %</b> remite.", "rango": null}, {"l": "D", "html": "<b>Síndrome nefrótico</b>: proteinuria <b class=\"a\">mayor de 3,5 g/24 h/1,73 m²</b>; focal y segmentaria <b class=\"a\">35 %</b>, membranosa <b class=\"a\">33 %</b>, cambios mínimos <b class=\"a\">15 %</b>.", "rango": {"min": 0, "max": 6, "unidad": "g/24 h/1,73 m²", "zonas": [[0, 3.5, "m", "no nefrótica"], [3.5, 6, "a", "nefrótica"]], "marcas": [3.5]}}, {"l": "E", "html": "<b>Arteritis de grandes vasos</b>: Takayasu en <b class=\"b\">mujeres jóvenes</b>; células gigantes en <b class=\"a\">mayores de 50 años</b>.", "rango": {"min": 10, "max": 90, "unidad": "años", "zonas": [[10, 50, "b", "Takayasu"], [50, 90, "a", "células gigantes"]], "marcas": [50]}}], "escalas": [], "cadena": {"titulo": "De la faringitis al riñón y al corazón", "subtitulo": "estímulo → anticuerpo → dónde se deposita → complemento → lesión → si no se frena", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> una faringitis por <mark><b>Streptococcus pyogenes</b></mark> (grupo A). El germen trae proteína M, endostreptosina, proteína ligadora de plasminógeno y proteinasa catiónica.", "pr": "anticuerpos IgG y antiestreptolisinas altas.", "pr_tit": "Produce:", "rf": "Preguntas ①⑭", "color": "p1"}, {"t": "2. Mimetismo (corazón)", "m": "<b>Por qué:</b> la IgG contra la <mark>proteína M</mark> se parece a lo propio: ácido hialurónico sinovial, endocardio, miocardio y epicardio.", "pr": "fiebre reumática: artritis, carditis con cuerpos de Aschoff.", "pr_tit": "Produce:", "rf": "Pregunta ①", "color": "p2"}, {"t": "3. Complejos (riñón)", "m": "<b>Qué pasa:</b> los antígenos del estreptococo y sus anticuerpos forman complejos que caen en el <mark>subepitelio y el mesangio</mark>, 10 a 15 días después.", "pr": "depósito <b>granular</b> con IgG y C3b.", "pr_tit": "Produce:", "rf": "Preguntas ⑫⑭ · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Complemento", "m": "<b>Por qué:</b> los complejos circulantes encienden la <mark>vía clásica</mark>; los formados in situ, la alterna. <span class=\"cx\">Por eso</span> baja el C3 en sangre.", "pr": "neutrófilos, inflamación glomerular, hematuria y edema.", "pr_tit": "Produce:", "rf": "Pregunta ⑫", "color": "p4"}, {"t": "5. Si falla el freno", "m": "<b>Qué produce:</b> sin <mark>factor H o CD46</mark> la vía alterna se descontrola (SHU atípico); la IgA1 sin galactosa se queda en el mesangio; el anti-MBG da depósito lineal; la IgG4 contra el receptor de fosfolipasa A2 daña el podocito.", "pr": "insuficiencia renal, hematuria crónica o síndrome nefrótico.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨⑩⑪ · puntos <span class=\"lt2\">C</span>", "color": "p4"}], "extra": [{"html": "🫀 <b>Otras del corazón:</b> bloqueo congénito por IgG materna <mark>anti-Ro</mark> (Purkinje; se va a los 6 meses), miocarditis viral (Coxsackie B), síndrome de Dressler (menos del 1 %), isquemia extra por exceso de leucocitos a los 30–60 min del infarto, aterosclerosis (CD36 del macrófago capta LDL). Preguntas ②⑤.", "k": ""}, {"html": "🩸 <b>Vasculitis por calibre:</b> grandes = Takayasu (mujer joven sin pulsos) y células gigantes (temporal, más de 50 años). Medianos = panarteritis nodosa y <mark>Kawasaki</mark> (cardiopatía adquirida del niño, gammaglobulina IV). ANCA = Wegener, Churg-Strauss. Pequeños = <mark>Henoch-Schönlein</mark> (IgA) y crioglobulinas. Behçet = HLA-B5. Preguntas ③④⑥⑦.", "k": "k"}, {"html": "💧 <b>Síndrome nefrótico:</b> proteinuria <mark>mayor de 3,5 g/24 h/1,73 m²</mark>, edema, hipoalbuminemia e hipercolesterolemia. Causas: focal y segmentaria 35 %, membranosa 33 %, cambios mínimos 15 % (niños); todas con daño del podocito. Preguntas ⑨⑬.", "k": ""}], "escaleras": [{"c": "d", "t": "🔥 Tres formas de dañar el glomérulo", "pasos": ["complejos circulantes que precipitan: vía clásica", "complejos formados in situ: vía alterna", "LT y macrófagos sin anticuerpos (nefritis intersticial por fármacos)", "inflamación del glomérulo o de los túbulos", "<b>fibrosis</b> e insuficiencia renal"]}], "html": "", "fuente": "Fuente: tu teoría — clase 51 (fiebre reumática, bloqueo congénito, otras cardiopatías, aterosclerosis, vasculitis) y clase 52 (mecanismos, glomerulonefritis endocapilar, nefropatía por IgA, anti-MBG, membranosa, síndrome nefrótico, nefritis intersticial, SHU)."}, "preguntas": [{"n": 1, "id": "IN20-015", "c": "d", "tema": "Fiebre reumática", "pregunta": "El hallazgo histológico característico de la miocarditis reumática es:", "opciones": ["a. Granulomas caseificantes", "b. Depósito lineal de IgG", "c. Aneurismas de hasta un centímetro", "d. Cuerpos de Aschoff", "e. Células de Reed-Sternberg"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los cuerpos de Aschoff, granulomas del miocardio.", "sin_banco": true, "ok": "", "x": "A la izquierda, los anticuerpos hechos contra el estreptococo se pegan al corazón (<mark>mimetismo</mark>); el nódulo en el miocardio es el cuerpo de Aschoff. <span class=\"res\">La d</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN20-016", "c": "d", "tema": "Bloqueo cardíaco congénito", "pregunta": "El bloqueo cardíaco congénito se debe a:", "opciones": ["a. IgM materna anti-ADN", "b. IgG materna anti-Ro que atraviesa la placenta y daña las fibras de Purkinje", "c. Linfocitos T maternos que cruzan la placenta", "d. Infección fetal por Coxsackie B", "e. Anticuerpos anti-proteína M"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. IgG materna anti-Ro que cruza la placenta y actúa sobre las fibras de Purkinje del feto.", "sin_banco": true, "ok": "", "x": "Solo la <mark>IgG</mark> cruza la placenta; <span class=\"cx\">por eso</span> es un daño pasivo que <span class=\"res\">desaparece a los seis meses</span>, <span class=\"cx\">cuando</span> se cataboliza la IgG materna. Ocurre en hijos de madres con Sjögren o lupus (lupus neonatal).", "truco": "Ro + Purkinje = bloqueo del bebé.", "veces": 0}, {"n": 3, "id": "IN20-017", "c": "d", "tema": "Vasculitis", "pregunta": "Los ANCA de la granulomatosis con poliangeítis (Wegener) se dirigen contra:", "opciones": ["a. Colágeno IV", "b. Ro", "c. ADN de doble cadena", "d. Desmogleína", "e. Proteinasa 3 o mieloperoxidasa de los gránulos del neutrófilo"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Proteinasa 3 o mieloperoxidasa, antígenos de los gránulos de los PMN.", "sin_banco": true, "ok": "", "x": "Los <mark>ANCA</mark> definen la vasculitis de vasos medianos y pequeños: granulomatosis con poliangeítis, granulomatosis eosinofílica con poliangeítis (asma y eosinofilia) y poliangeítis microscópica. Wegener destruye <span class=\"res\">nariz, senos y oído medio</span>; se trata con esteroides y ciclofosfamida o metotrexate, y rituximab si resiste.", "truco": "ANCA = «anticuerpos que muerden el neutrófilo» (PR3/MPO).", "veces": 0}, {"n": 4, "id": "IN20-018", "c": "i", "tema": "Vasculitis", "pregunta": "La principal causa de cardiopatía adquirida en niños, que se trata con gammaglobulina intravenosa, es:", "opciones": ["a. Enfermedad de Kawasaki", "b. Arteritis de Takayasu", "c. Púrpura de Henoch-Schönlein", "d. Arteritis de células gigantes", "e. Síndrome de Behçet"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. La enfermedad de Kawasaki.", "sin_banco": true, "ok": "", "x": "<mark>Kawasaki</mark> puede dar miocarditis, valvulitis y aneurismas que causan <span class=\"res\">muerte súbita</span>; es más frecuente en japoneses. Henoch-Schönlein es la vasculitis sistémica más común en la infancia, pero no la principal causa de cardiopatía.", "truco": "Kawasaki: «corazón de niño, gammaglobulina».", "veces": 0}, {"n": 5, "id": "IN20-019", "c": "i", "tema": "Aterosclerosis", "pregunta": "¿Qué papel cumple CD36 en la aterosclerosis?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Es el receptor del macrófago para LDL y restos celulares: capta lípidos, genera radicales de oxígeno y el macrófago cargado se queda en la pared formando el ateroma.", "sin_banco": true, "ok": "", "x": "La aterosclerosis es <mark>inflamación crónica</mark> por disfunción endotelial (sube ICAM-1, VCAM y selectina E). El macrófago lleno de lípidos pierde motilidad, <span class=\"cx\">así que</span> se acumula; su centro necrótico puede romper el endotelio y dar <span class=\"res\">trombosis</span>.", "truco": "CD36 = «aspiradora de LDL» del macrófago.", "veces": 0}, {"n": 6, "id": "IN20-020", "c": "i", "tema": "Vasculitis", "pregunta": "Diferencie la arteritis de Takayasu de la arteritis de células gigantes.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Takayasu: aorta y ramas, mujeres jóvenes, granulomas que obstruyen y quitan pulsos. Células gigantes: arterias extracraneales (temporal), mayores de 50 años, riesgo de amaurosis.", "sin_banco": true, "ok": "", "x": "Ambas son de <mark>vasos grandes</mark> con granulomas. Takayasu es la «enfermedad sin pulsos»; <span class=\"cx\">en cambio</span>, la de células gigantes amenaza la arteria central de la retina y puede acompañarse de <span class=\"res\">polimialgia reumática</span>.", "truco": "Takayasu joven sin pulso; temporal vieja que pierde la vista.", "veces": 0}, {"n": 7, "id": "IN20-021", "c": "d", "tema": "Vasculitis", "pregunta": "Niño de 6 años con púrpura palpable en las piernas, plaquetas normales, dolor abdominal y artralgias. ¿Diagnóstico y tipo de depósito?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Púrpura de Henoch-Schönlein: complejos inmunes con predominio de IgA en vasos pequeños.", "sin_banco": true, "ok": "", "x": "La arteria del centro muestra la vasculitis por <mark>complejos inmunes</mark>; en la Henoch-Schönlein esos complejos son de IgA y el vaso es pequeño, <span class=\"cx\">por eso</span> la púrpura es <span class=\"res\">no trombocitopénica</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN20-022", "c": "d", "tema": "Nefropatía por IgA", "pregunta": "La enfermedad glomerular crónica más prevalente en el mundo, con depósitos mesangiales de IgA1 deficiente en galactosa, es:", "opciones": ["a. Glomerulonefritis membranosa", "b. Enfermedad de cambios mínimos", "c. Glomerulonefritis posestreptocócica", "d. Nefropatía por IgA", "e. Enfermedad anti-MBG"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. La nefropatía por IgA.", "sin_banco": true, "ok": "", "x": "Son los grumos del mesangio en el glomérulo (punto Ⓒ): <mark>IgA1 sin galactosa</mark>. <span class=\"res\">La d</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN20-023", "c": "g", "tema": "Síndrome nefrótico", "pregunta": "La causa más frecuente de síndrome nefrótico, según la clase, es:", "opciones": ["a. Nefropatía membranosa", "b. Glomerulonefritis focal y segmentaria", "c. Enfermedad de cambios mínimos", "d. Nefropatía por IgA", "e. Nefritis aguda intersticial"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La glomerulonefritis focal y segmentaria (35 %).", "sin_banco": true, "ok": "", "x": "Orden: <mark>focal y segmentaria 35 %</mark>, membranosa 33 % y cambios mínimos 15 % (sobre todo niños). Las tres comparten una <span class=\"res\">podocitopatía</span>.", "truco": "Nefrótico: «35-33-15, focal-membranosa-mínimos».", "veces": 0}, {"n": 10, "id": "IN20-024", "c": "d", "tema": "Nefropatía membranosa idiopática", "pregunta": "La nefropatía membranosa idiopática se debe a anticuerpos contra:", "opciones": ["a. El receptor de la fosfolipasa A2 de los podocitos", "b. El colágeno IV α3", "c. El ADN de doble cadena", "d. El factor H", "e. La proteína M del estreptococo"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. El receptor de la fosfolipasa A2 de los podocitos; son sobre todo IgG4.", "sin_banco": true, "ok": "", "x": "No hay complejos circulantes: la <mark>IgG4</mark> se forma in situ sobre el podocito. La IgG4 activa poco el complemento, pero aun así <span class=\"res\">daña el glomérulo y da síndrome nefrótico</span>; es la causa principal en adultos blancos.", "truco": "Membranosa idiopática: «fosfolipasa y IgG4».", "veces": 0}, {"n": 11, "id": "IN20-025", "c": "d", "tema": "Síndrome hemolítico urémico", "pregunta": "El síndrome hemolítico urémico atípico se debe a mutaciones en:", "opciones": ["a. NOD2 y ATG16L1", "b. AIRE y FOXP3", "c. Factor H (CFH) y CD46 (MCP), reguladores de la vía alterna", "d. HLA-DR4", "e. El receptor de la fosfolipasa A2"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. El factor H y CD46, que regulan la vía alterna del complemento.", "sin_banco": true, "ok": "", "x": "Sin esos frenos, la <mark>vía alterna</mark> se activa sin control sobre el endotelio glomerular. Resultado: <span class=\"res\">insuficiencia renal, anemia hemolítica microangiopática y trombocitopenia</span>.", "truco": "SHU atípico: «sin factor H, el complemento no frena».", "veces": 0}, {"n": 12, "id": "IN20-026", "c": "d", "tema": "Mecanismos de daño renal", "pregunta": "¿Cuáles son los tres mecanismos de daño glomerular autoinmune y qué vía del complemento usa cada uno?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "1) Complejos circulantes que precipitan: vía clásica. 2) Complejos formados in situ sobre antígenos sembrados: vía alterna. 3) Infiltración por LT y macrófagos citotóxicos: sin complemento.", "sin_banco": true, "ok": "", "x": "Compara las dos ampliaciones: la de arriba es una línea (anticuerpo contra la pared, in situ) y la de abajo son grumos (complejos que caen desde la sangre, <mark>vía clásica</mark>).", "truco": "", "veces": 0}, {"n": 13, "id": "IN20-027", "c": "g", "tema": "Síndrome nefrótico", "pregunta": "¿Cómo se define el síndrome nefrótico?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Proteinuria mayor de 3,5 g/24 h/1,73 m², edema, hipercolesterolemia e hipoalbuminemia.", "sin_banco": true, "ok": "", "x": "Se pierde tanta albúmina por la orina que baja en sangre; <span class=\"cx\">por eso</span> aparece <mark>edema</mark> y el hígado compensa fabricando lípidos. El elemento común de sus causas es el <span class=\"res\">daño del podocito</span>.", "truco": "Nefrótico: «más de 3,5 g de proteína: edema, poca albúmina y colesterol alto».", "veces": 0}, {"n": 14, "id": "IN20-028", "c": "d", "tema": "Glomerulonefritis endocapilar", "pregunta": "Niño de 8 años presenta hematuria, edema e hipertensión 12 días después de una faringitis; C3 bajo y antiestreptolisinas altas. ¿Diagnóstico y mecanismo?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Glomerulonefritis endocapilar posestreptocócica: complejos inmunes con IgG y C3b depositados en subepitelio y mesangio, con consumo del complemento.", "sin_banco": true, "ok": "", "x": "Es la ampliación de abajo (punto Ⓑ): <mark>grumos</mark> de IgG con C3b en el subepitelio. <span class=\"cx\">Por eso</span> el C3 sérico baja y aparecen hematuria y edema <span class=\"res\">10 a 15 días</span> después.", "truco": "", "veces": 0}], "tabla": {"cab": ["", "Antígeno", "Patrón", "Pista"], "filas": [["Anti-MBG (Goodpasture)", "Colágeno IV", "IgG lineal", "Hemoptisis + glomerulonefritis"], ["Posestreptocócica", "Antígenos del estreptococo", "Granular, IgG + C3b", "10–15 días tras faringitis; C3 bajo"], ["Nefropatía por IgA", "IgA1 sin galactosa", "Mesangial difuso", "Hematuria microscópica; HLA-DR4"], ["Membranosa idiopática", "Receptor de fosfolipasa A2", "IgG4 in situ", "Nefrótico en adultos"], ["SHU atípico", "Sin anticuerpo", "Vía alterna sin freno", "Factor H, CD46"], ["🔑 Para diferenciar", "¿Hay anticuerpo contra la pared?", "Lineal / granular / mesangial", "El C3 bajo delata complejos"]]}, "fuente": "Fuente: tu teoría — clase 51 (Enfermedades autoinmunes cardiovasculares) y clase 52 (Enfermedades autoinmunes del riñón), Rojas 17.ª ed."}, {"n": 38, "slug": "Autoinmunidad_musculo_y_sangre", "titulo": "Autoinmunidad del músculo y de la sangre", "subtitulo": "miastenia gravis, polimiositis y citopenias autoinmunes", "grupo": "g21", "lema": "La idea: el músculo y las células de la sangre se dañan por los <b>dos brazos</b> de la inmunidad adaptativa. Por el brazo <mark>humoral</mark>, un anticuerpo se sienta en el receptor de acetilcolina (miastenia), en los capilares del músculo con el complemento (dermatomiositis) o sobre el eritrocito y la plaqueta, que el bazo retira (anemias hemolíticas y púrpura). Por el brazo <mark>celular</mark>, linfocitos T CD8 destruyen la fibra muscular (polimiositis pura y por cuerpos de inclusión) o la médula (anemia aplástica). Importa porque el mecanismo decide el tratamiento: <b>plasmaféresis, timectomía y rituximab</b> sacan o frenan anticuerpos; los inmunosupresores frenan a los T. En la imagen verás de izquierda a derecha: la placa neuromuscular con anticuerpos, la fibra muscular invadida por linfocitos y el macrófago del bazo comiéndose un eritrocito recubierto.", "img": "img/38.webp", "mini": "img/mini/38.webp", "ratio": 1.5, "etiquetas": [{"n": "", "t": "Terminal nerviosa", "s": "libera acetilcolina<br>en la hendidura", "c": "g", "x": 0.5, "y": 6, "ax": 13, "ay": 30, "d": "A", "al": "l"}, {"n": "②", "t": "Poro de complemento", "s": "lisa la membrana y<br>atrofia los pliegues", "c": "d", "x": 27, "y": 6, "ax": 24, "ay": 53.5}, {"n": "⑦", "t": "Linfocito T CD8", "s": "ataca la fibra:<br>polimiositis", "c": "d", "x": 45, "y": 6, "ax": 47, "ay": 43.5}, {"n": "⑥", "t": "Capilar dañado", "s": "C5-C9 en su pared:<br>dermatomiositis", "c": "d", "x": 64, "y": 6, "ax": 61, "ay": 35.5}, {"n": "⑧", "t": "Macrófago del bazo", "s": "receptores Fc y C3b:<br>retira lo recubierto", "c": "g", "x": 99.5, "y": 6, "ax": 90, "ay": 30, "al": "r"}, {"n": "①③④", "t": "Anti-AChR (IgG)", "s": "sobre el receptor<br>nicotínico", "c": "i", "x": 0.5, "y": 91, "ax": 12, "ay": 52, "al": "l"}, {"n": "⑤", "t": "Necrosis de la fibra", "s": "segmentaria;<br>anti-Jo-1", "c": "g", "x": 36, "y": 91, "ax": 52, "ay": 57, "d": "B"}, {"n": "⑨⑩⑪", "t": "Eritrocito con IgG", "s": "Coombs directa +:<br>bazo o complemento", "c": "i", "x": 65, "y": 91, "ax": 78, "ay": 68, "d": "C"}, {"n": "⑫⑬", "t": "Plaquetas con IgG", "s": "anti-HPA:<br>PTI y neonatal", "c": "i", "x": 99.5, "y": 91, "ax": 95.5, "ay": 71, "d": "D", "al": "r"}], "diapos": [{"img": "img/38.webp", "ratio": 1.5, "titulo": "Placa, músculo y sangre", "texto": "Anticuerpos contra el receptor de acetilcolina ①②, complemento en los capilares del músculo ⑥ y eritrocitos y plaquetas cubiertos de anticuerpos ⑨⑫.", "etiquetas": [{"n": "", "t": "Terminal nerviosa", "s": "libera acetilcolina<br>en la hendidura", "c": "g", "x": 0.5, "y": 6, "ax": 13, "ay": 30, "d": "A", "al": "l"}, {"n": "②", "t": "Poro de complemento", "s": "lisa la membrana y<br>atrofia los pliegues", "c": "d", "x": 27, "y": 6, "ax": 24, "ay": 53.5}, {"n": "⑦", "t": "Linfocito T CD8", "s": "ataca la fibra:<br>polimiositis", "c": "d", "x": 45, "y": 6, "ax": 47, "ay": 43.5}, {"n": "⑥", "t": "Capilar dañado", "s": "C5-C9 en su pared:<br>dermatomiositis", "c": "d", "x": 64, "y": 6, "ax": 61, "ay": 35.5}, {"n": "⑧", "t": "Macrófago del bazo", "s": "receptores Fc y C3b:<br>retira lo recubierto", "c": "g", "x": 99.5, "y": 6, "ax": 90, "ay": 30, "al": "r"}, {"n": "①③④", "t": "Anti-AChR (IgG)", "s": "sobre el receptor<br>nicotínico", "c": "i", "x": 0.5, "y": 91, "ax": 12, "ay": 52, "al": "l"}, {"n": "⑤", "t": "Necrosis de la fibra", "s": "segmentaria;<br>anti-Jo-1", "c": "g", "x": 36, "y": 91, "ax": 52, "ay": 57, "d": "B"}, {"n": "⑨⑩⑪", "t": "Eritrocito con IgG", "s": "Coombs directa +:<br>bazo o complemento", "c": "i", "x": 65, "y": 91, "ax": 78, "ay": 68, "d": "C"}, {"n": "⑫⑬", "t": "Plaquetas con IgG", "s": "anti-HPA:<br>PTI y neonatal", "c": "i", "x": 99.5, "y": 91, "ax": 95.5, "ay": 71, "d": "D", "al": "r"}]}, {"img": "img/38_2.webp", "ratio": 1.5, "titulo": "Miastenia: el receptor bloqueado", "texto": "Los anticuerpos <mark>bloquean, entrecruzan e internalizan</mark> el receptor y el complemento aplana los pliegues ①②; la colinesterasa sigue intacta, <span class=\"cx\">por eso</span> inhibirla es el tratamiento. El timo anómalo ④.", "etiquetas": [{"n": "②", "t": "Colinesterasa", "s": "intacta: inhibirla<br>es el tratamiento", "c": "g", "x": 0.5, "y": 6, "ax": 3.5, "ay": 43.5, "al": "l"}, {"n": "", "t": "Vesícula de acetilcolina", "s": "placa normal:<br>muchas por impulso", "c": "g", "x": 24, "y": 6, "ax": 17.5, "ay": 31, "d": "A"}, {"n": "①②", "t": "Anticuerpos anti-AChR", "s": "bloquean y entrecruzan<br>los receptores", "c": "i", "x": 50, "y": 6, "ax": 51.5, "ay": 45}, {"n": "④", "t": "Centros germinales", "s": "timo anómalo:<br>hiperplasia", "c": "g", "x": 99.5, "y": 6, "ax": 87, "ay": 39, "al": "r"}, {"n": "①", "t": "Receptores en crestas", "s": "nicotínicos: la cadena<br>alfa es el blanco", "c": "g", "x": 0.5, "y": 91, "ax": 4.5, "ay": 49, "al": "l"}, {"n": "②", "t": "Receptor internalizado", "s": "el anticuerpo<br>lo arrastra adentro", "c": "i", "x": 34, "y": 91, "ax": 49, "ay": 58}, {"n": "②", "t": "Poro de complemento", "s": "rompe y aplana<br>los pliegues", "c": "d", "x": 57, "y": 91, "ax": 63, "ay": 52}, {"n": "④", "t": "Timoma", "s": "timectomía solo<br>si hay anti-AChR", "c": "g", "x": 99.5, "y": 91, "ax": 89, "ay": 72, "al": "r"}]}, {"img": "img/38_3.webp", "ratio": 1.5, "titulo": "La paradoja antifosfolipídica", "texto": "En el tubo la sangre <mark>tarda en coagular</mark>; en el cuerpo, <span class=\"cx\">en cambio</span>, hace <span class=\"res\">trombosis</span> venosas y arteriales y pérdidas gestacionales ⑭.", "etiquetas": [{"n": "⑭", "t": "Plasma que no coagula", "s": "in vitro: «anticoagulante<br>lúpico» prolongado", "c": "g", "x": 0.5, "y": 6, "ax": 10, "ay": 33, "al": "l"}, {"n": "⑭", "t": "Trombo venoso", "s": "in vivo: trombosis<br>venosa y arterial", "c": "g", "x": 45, "y": 6, "ax": 47, "ay": 42}, {"n": "⑭", "t": "Infarto placentario", "s": "pérdidas<br>gestacionales", "c": "g", "x": 99.5, "y": 6, "ax": 70, "ay": 46, "al": "r"}, {"n": "⑭", "t": "Antifosfolípido", "s": "se une a los<br>fosfolípidos", "c": "i", "x": 0.5, "y": 91, "ax": 8.5, "ay": 64, "al": "l"}, {"n": "⑭", "t": "Endotelio marcado", "s": "anticuerpos<br>sobre la pared", "c": "i", "x": 31, "y": 91, "ax": 28, "ay": 62}, {"n": "⑭", "t": "Plaquetas agrupadas", "s": "se consumen:<br>trombocitopenia", "c": "g", "x": 51, "y": 91, "ax": 36, "ay": 60}, {"n": "⑭", "t": "Vaso placentario ocluido", "s": "trombos en<br>la placenta", "c": "g", "x": 99.5, "y": 91, "ax": 88.5, "ay": 71, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = daño por anticuerpos</b> (humoral), <b class=\"d\">rojo = daño por células o complemento</b>, gris = estructuras de referencia.", "<b>Izquierda:</b> la terminal libera acetilcolina, pero los <mark>anti-AChR</mark> bloquean el receptor, activan el complemento y aplanan los pliegues; <span class=\"cx\">por eso</span> cada impulso abre menos canales y la debilidad <b>fluctúa</b> con el esfuerzo.", "<b>Centro:</b> en la polimiositis pura los <mark>LT CD8</mark> atacan la fibra; en la dermatomiositis, <span class=\"cx\">en cambio</span>, el complemento C5-C9 daña <span class=\"cx\">primero</span> el <b>capilar</b> y la fibra se queda sin sangre.", "<b>Derecha:</b> el bazo es un filtro fino: sus macrófagos tienen receptores para el <mark>Fc de la IgG y para el C3b</mark>, <span class=\"cx\">así que</span> retiran eritrocitos y plaquetas recubiertos; la Coombs directa detecta ese anticuerpo pegado."], "recordar": "Músculo: <b>anticuerpo en la placa</b> (miastenia) · <b>complemento en el capilar</b> (dermatomiositis) · <b>CD8 en la fibra</b> (polimiositis). Sangre: <b>IgG caliente → bazo</b>, <b>IgM fría → complemento</b>, <b>aloinmune neonatal → mamá contra papá</b>."}, "numeros": [{"l": "A", "html": "<b>Placa normal</b>: cada impulso abre <b class=\"n\">200</b> vesículas con <b class=\"n\">10 000</b> moléculas de acetilcolina, <b class=\"n\">20 veces por segundo</b>. Miastenia: <b class=\"n\">1 de cada 20 000</b> personas; timo anómalo en <b class=\"a\">2/3</b>, timoma en <b class=\"a\">15 %</b>.", "rango": null}, {"l": "B", "html": "<b>Polimiositis</b>: se asocia a cáncer en el <b class=\"a\">20 %</b> de los pacientes, así que siempre se busca una neoplasia.", "rango": null}, {"l": "C", "html": "<b>Eritrocito</b>: vive <b class=\"n\">120 días</b>; luego la CD233 se fragmenta y el bazo lo retira. Tiene <b class=\"n\">22 sistemas</b> con más de <b class=\"n\">600 antígenos</b>; el <b class=\"n\">85 %</b> expresa algún antígeno Rh.", "rango": {"min": 0, "max": 140, "unidad": "días", "zonas": [[0, 120, "n", "circula"], [120, 140, "a", "CD233 rota: bazo"]], "marcas": [120]}}, {"l": "D", "html": "<b>Coagulación</b>: hasta el <b class=\"a\">5 %</b> de las hemofilias se debe a anticuerpos anti-factor VIII; la púrpura postransfusional aparece a la <b class=\"a\">semana</b> (anti-HPA-1).", "rango": null}], "escalas": [], "cadena": {"titulo": "Del autoantígeno a la debilidad y la citopenia", "subtitulo": "estímulo → células y anticuerpos → mecanismo → resultado → qué pasa si no se controla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> un virus o las <mark>células mioides del timo</mark> (que expresan AChR) rompen la tolerancia; en la polimiositis un picornavirus se une a la <b>histidil-tRNA sintetasa</b>; en la sangre, un fármaco-hapteno, un embarazo o una transfusión exponen antígenos.", "pr": "aparecen linfocitos autorreactivos o aloanticuerpos.", "pr_tit": "Produce:", "rf": "Preguntas ④⑤⑪", "color": "p1"}, {"t": "2. Células y anticuerpos", "m": "<b>Por qué:</b> plasmocitos hacen <mark>IgG anti-AChR</mark>, anti-Jo-1, IgG calientes, IgM frías o anti-HPA; a la vez, LT CD8 activados por células dendríticas reconocen la fibra muscular o la médula como extrañas.", "pr": "anticuerpos sobre la célula blanco o linfocitos citotóxicos en el tejido.", "pr_tit": "Produce:", "rf": "Preguntas ①⑦⑨ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Mecanismo", "m": "<b>Qué produce:</b> en la placa, bloqueo + complemento + atrofia de pliegues; en la dermatomiositis, el C5-C9 daña el <b>capilar</b>; en la sangre, los macrófagos del bazo (receptores Fc y C3b) retiran células recubiertas y la IgM fría activa el complemento.", "pr": "menos transmisión, isquemia muscular o destrucción de células sanguíneas.", "pr_tit": "Produce:", "rf": "Preguntas ②⑥⑨⑩", "color": "p3"}, {"t": "4. Resultado", "m": "<b>Qué se ve:</b> <mark>debilidad fluctuante</mark> (miastenia); debilidad <b>proximal y simétrica</b> con heliotropo y Gottron (dermatomiositis); anemia con reticulocitos e <b>hiperbilirrubinemia indirecta</b>; púrpura en la PTI; trombosis paradójica en el SAF.", "pr": "el cuadro clínico que orienta el diagnóstico (anti-AChR, anti-Jo-1, Coombs).", "pr_tit": "Produce:", "rf": "Preguntas ③⑥⑭ · puntos <span class=\"lt2\">B</span><span class=\"lt2\">C</span>", "color": "p4"}, {"t": "5. Tratamiento y si falla", "m": "<b>Qué se hace:</b> neostigmina, <mark>plasmaféresis</mark> en la crisis, timectomía precoz (no en seronegativos), esteroides, esplenectomía, <b>rituximab</b> y anti-Rh tras el primer parto. Si no se controla: crisis miasténica, cáncer oculto, hemorragia o trombosis.", "pr": "se frena el anticuerpo o la célula que daña.", "pr_tit": "Produce:", "rf": "Preguntas ④⑪⑬", "color": "p4"}], "extra": [{"html": "🩸 <b>Hemólisis según el anticuerpo:</b> <mark>calientes (IgG)</mark> → bazo, esteroides y esplenectomía; <mark>frías (IgM)</mark> contra ABOH o P → complemento, evitar el frío; <b>fármacos</b> (levodopa, penicilina) → retirar el fármaco; <b>Donath-Landsteiner (IgG)</b> → hemoglobinuria al frío. La paroxística <b>nocturna</b> no es autoinmune.", "k": ""}, {"html": "👶 <b>Citopenias neonatales aloinmunes:</b> IgG de la madre contra un antígeno del padre cruza la placenta (eritroblastos, granulocitos, plaquetas HPA-1a); curan solas <span class=\"cx\">cuando</span> el niño cataboliza esos anticuerpos. El <b>fenómeno Bombay</b> (sin antígeno H) obliga a buscar sangre Bombay.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 Cómo empeora la placa miasténica", "pasos": ["anti-AChR sobre el receptor", "bloqueo de la acetilcolina", "complemento: lisis de la membrana", "pliegues atróficos: menos área", "<b>crisis miasténica</b>: plasmaféresis urgente"]}], "html": "", "fuente": "Fuente: tu teoría — clase 53 (miastenia gravis; polimiositis, dermatomiositis y miositis por cuerpos de inclusión) y clase 54 (mielopatías, anemias hemolíticas, Rh, granulopenias, trombocitopenias, coagulopatías y SAF)."}, "preguntas": [{"n": 1, "id": "IN21-001", "c": "i", "tema": "Miastenia gravis", "pregunta": "En la miastenia gravis, los autoanticuerpos IgG se dirigen principalmente contra:", "opciones": ["a. El receptor de rianodina del retículo sarcoplásmico", "b. Los canales de calcio de la terminal presináptica", "c. Las vesículas de acetilcolina de la terminal nerviosa", "d. El receptor nicotínico de acetilcolina de la membrana postsináptica (cadena alfa)", "e. La acetilcolinesterasa de la hendidura sináptica"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. El receptor nicotínico de acetilcolina de la membrana postsináptica (cadena alfa): la cadena alfa 2 es la más inmunogénica.", "sin_banco": true, "ok": "", "x": "Es el anticuerpo azul de la izquierda de la imagen: se sienta sobre el <mark>receptor nicotínico</mark> de los pliegues postsinápticos, cuya cadena alfa 2 es la más inmunogénica. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN21-002", "c": "i", "tema": "Miastenia gravis", "pregunta": "Los anticuerpos anti-AChR alteran la transmisión neuromuscular por todos estos mecanismos, EXCEPTO:", "opciones": ["a. Inhibición de la acetilcolinesterasa de la hendidura", "b. Activación del complemento con lisis de la membrana postsináptica", "c. Bloqueo directo del receptor, que impide la unión de la acetilcolina", "d. Atrofia de las vellosidades postsinápticas", "e. Reducción del área de contacto disponible para la acetilcolina"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Inhibición de la acetilcolinesterasa de la hendidura: inhibir la colinesterasa es justamente el tratamiento (neostigmina, piridostigmina).", "sin_banco": true, "ok": "", "x": "En la placa de la imagen ves los tres golpes: anticuerpo sobre el receptor, poro de complemento y pliegues aplanados. Inhibir la colinesterasa, <span class=\"cx\">en cambio</span>, es el <b>tratamiento</b>. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN21-003", "c": "i", "tema": "Miastenia gravis", "pregunta": "¿Qué anticuerpo de la miastenia gravis se correlaciona con la gravedad clínica y qué es su antígeno?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El anti-receptor de rianodina: su título se correlaciona directamente con la gravedad. La rianodina forma parte de un canal de calcio del retículo sarcoplásmico.", "sin_banco": true, "ok": "", "x": "El anti-AChR es el hallazgo <mark>más específico</mark> para diagnosticar, <span class=\"cx\">en cambio</span> el anti-rianodina sirve para <b>pronosticar</b>, <span class=\"cx\">porque</span> su título sube con la gravedad. <span class=\"cx\">Por eso</span> se piden ambos: <span class=\"res\">AChR para diagnosticar, rianodina para medir gravedad</span>.", "truco": "Rianodina = «Riesgo»: cuanto más alto, más grave.", "veces": 0}, {"n": 4, "id": "IN21-004", "c": "i", "tema": "Miastenia gravis", "pregunta": "Sobre el timo y la miastenia gravis, es FALSO que:", "opciones": ["a. Dos terceras partes de los pacientes tienen alguna anomalía tímica", "b. Alrededor del 15 % tiene un timoma macroscópico", "c. Las células mioides del timo pueden expresar receptores de acetilcolina", "d. La timectomía precoz modifica favorablemente el curso clínico", "e. La timectomía está indicada también en pacientes negativos para anticuerpos anti-AChR"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La timectomía está indicada también en pacientes negativos para anticuerpos anti-AChR: no está indicada en los seronegativos.", "sin_banco": true, "ok": "", "x": "Las <mark>células mioides</mark> del timo expresan AChR y así inducirían los anticuerpos; <span class=\"cx\">por eso</span> la timectomía precoz ayuda, con timoma o sin él. <span class=\"cx\">En cambio</span>, el beneficio se demostró en los <b>seropositivos</b>, <span class=\"cx\">así que</span> <span class=\"res\">en el seronegativo anti-AChR la timectomía no está indicada</span>.", "truco": "Timo: 2/3 anómalo, 15 % timoma; sin anticuerpo, no se opera.", "veces": 0}, {"n": 5, "id": "IN21-005", "c": "d", "tema": "Polimiositis", "pregunta": "Los anticuerpos anti-Jo-1, los más frecuentes en las polimiositis, se dirigen contra:", "opciones": ["a. La topoisomerasa I", "b. La histidil-tRNA sintetasa", "c. El receptor de acetilcolina", "d. El ADN de doble cadena", "e. La proteína del centrómero"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. La histidil-tRNA sintetasa: se asocian al síndrome antisintetasa.", "sin_banco": true, "ok": "", "x": "Un picornavirus o retrovirus se uniría a la <mark>histidil-tRNA sintetasa</mark> y la volvería antigénica; contra ella se forman los anti-Jo-1. <span class=\"cx\">Por eso</span> pueden acompañarse del <b>síndrome antisintetasa</b>: <span class=\"res\">miositis, artritis, Raynaud y enfermedad pulmonar intersticial</span>.", "truco": "Jo-1 = «JOven HIStidina»: la sintetasa de histidina.", "veces": 0}, {"n": 6, "id": "IN21-006", "c": "d", "tema": "Polimiositis", "pregunta": "Mujer de 52 años con debilidad proximal y simétrica de cintura escapular y pélvica, párpados color lila con edema y placas eritematosas en el dorso de los nudillos. ¿Diagnóstico, mecanismo efector y qué hay que buscar?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Dermatomiositis (heliotropo + pápulas de Gottron). Mecanismo humoral: el complemento C5-C9 daña los capilares del músculo (microangiopatía e isquemia). Hay que buscar una neoplasia: se asocia a cáncer en el 20 %.", "sin_banco": true, "ok": "", "x": "Mira el capilar del centro: en la <mark>dermatomiositis</mark> el complemento C5-C9 lo perfora y la fibra queda isquémica; <span class=\"cx\">por eso</span> hay piel (heliotropo, Gottron). Y como el 20 % tiene cáncer (punto Ⓑ), <span class=\"res\">siempre se busca una neoplasia</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN21-007", "c": "d", "tema": "Polimiositis", "pregunta": "¿Qué hallazgo distingue a la miositis por cuerpos de inclusión de la polimiositis pura?", "opciones": ["a. Microangiopatía por el complejo de ataque C5-C9", "b. Pápulas de Gottron en los nudillos", "c. Inclusiones tubulares en el citoplasma de las células musculares", "d. Anticuerpos anti-receptor de acetilcolina", "e. Granulomas con células gigantes"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Inclusiones tubulares en el citoplasma de las células musculares: ambas comparten el infiltrado de LT CD8.", "sin_banco": true, "ok": "", "x": "Los linfocitos que invaden la fibra del centro son <mark>LT CD8</mark>, comunes a la polimiositis pura y a la de cuerpos de inclusión; solo esta última tiene <b>inclusiones tubulares</b> dentro de la fibra. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 8, "id": "IN21-008", "c": "i", "tema": "Destrucción normal del eritrocito", "pregunta": "Tras 120 días de circulación, ¿qué molécula de la membrana del eritrocito se fragmenta y expone epítopos que inducen su destrucción fisiológica?", "opciones": ["a. CD55", "b. CD59", "c. CD233", "d. CD20", "e. CD34"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. CD233: contra sus fragmentos se forman IgG que facilitan la retención en el bazo.", "sin_banco": true, "ok": "", "x": "El eritrocito que come el macrófago (punto Ⓒ) puede ser uno viejo: a los 120 días la <mark>CD233</mark> se rompe y una IgG lo marca. Es autoinmunidad normal. <span class=\"cx\">Por eso</span> <span class=\"res\">la c</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN21-009", "c": "i", "tema": "Anemias hemolíticas", "pregunta": "La anemia hemolítica por anticuerpos al frío se debe a:", "opciones": ["a. IgG contra antígenos de membrana alterados, con destrucción en el bazo", "b. IgM contra antígenos ABOH o P que activan el complemento en frío", "c. Un defecto intrínseco del eritrocito sin anticuerpos", "d. Anticuerpos IgE contra el grupo Rh", "e. Un complejo fármaco-proteína de membrana que induce IgG"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. IgM contra antígenos ABOH o P que activan el complemento en frío: por eso se trata evitando el frío.", "sin_banco": true, "ok": "", "x": "Los anticuerpos <mark>al frío son IgM</mark> contra ABOH o P y activan el complemento <span class=\"cx\">cuando</span> baja la temperatura. <span class=\"cx\">En cambio</span>, los <b>calientes</b> son IgG y el bazo destruye a los eritrocitos recubiertos. <span class=\"cx\">Por eso</span> el manejo cambia: <span class=\"res\">al frío, evitar el frío; calientes, esteroides o esplenectomía</span>.", "truco": "IgM = «Muy frío»; IgG = «Grados altos».", "veces": 0}, {"n": 10, "id": "IN21-010", "c": "i", "tema": "Anemias hemolíticas", "pregunta": "¿En qué se diferencia la hemoglobinuria paroxística al frío de la hemoglobinuria paroxística nocturna?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La al frío es autoinmune: IgG de Donath-Landsteiner que activan el complemento al enfriarse. La nocturna no es autoinmune: es un defecto intrínseco del eritrocito que lo hace hipersensible al complemento, sin anticuerpos ni frío.", "sin_banco": true, "ok": "", "x": "Las dos terminan con complemento sobre el eritrocito, pero el origen es distinto. En la <mark>al frío</mark> hay anticuerpos (Donath-Landsteiner, IgG); en la <mark>nocturna</mark> falta la protección de la membrana, <span class=\"cx\">así que</span> el complemento la lisa solo. <span class=\"cx\">Por eso</span> <span class=\"res\">solo la al frío figura entre las autoinmunes</span>.", "truco": "Frío = Donath-Landsteiner (anticuerpo); Nocturna = No autoinmune.", "veces": 0}, {"n": 11, "id": "IN21-011", "c": "i", "tema": "Incompatibilidad Rh", "pregunta": "¿En qué principio se basa la profilaxis de la eritroblastosis fetal con anticuerpos anti-Rh?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Si a un individuo Rh negativo se le dan a la vez eritrocitos Rh positivos y anticuerpos anti-Rh, no produce anticuerpos propios. Por eso se aplica anti-Rh a la madre Rh negativa justo después del primer parto: evita su sensibilización y protege los embarazos siguientes.", "sin_banco": true, "ok": "", "x": "<span class=\"cx\">Al final</span> del embarazo pasan eritrocitos fetales Rh+ a la madre y la <mark>sensibilizan</mark>; en el segundo embarazo sus IgG anti-Rh cruzan la placenta. El anti-Rh pasivo elimina esos eritrocitos <b>antes</b> de que la madre responda, <span class=\"cx\">así que</span> <span class=\"res\">no se forma memoria y no hay eritroblastosis después</span>.", "truco": "Anti-Rh «borra la evidencia» antes de que la madre la vea.", "veces": 0}, {"n": 12, "id": "IN21-012", "c": "i", "tema": "Trombocitopenias", "pregunta": "La trombocitopenia neonatal aloinmune se produce por anticuerpos maternos contra:", "opciones": ["a. El antígeno plaquetario HPA-1a de origen paterno", "b. Los antígenos HLA clase II del feto", "c. El antígeno Rh del eritrocito fetal", "d. El antígeno HPA-3 de las propias plaquetas de la madre", "e. El antígeno H del grupo ABOH"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. El antígeno plaquetario HPA-1a de origen paterno: a las pocas horas del parto aparecen púrpura y hemorragias.", "sin_banco": true, "ok": "", "x": "Las plaquetas recubiertas de la derecha muestran la idea: en el neonato, la IgG es de la madre contra el <mark>HPA-1a del padre</mark> y cruza la placenta. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 13, "id": "IN21-013", "c": "i", "tema": "Trombocitopenias", "pregunta": "El rituximab es útil en la púrpura trombocitopénica inmune crónica porque:", "opciones": ["a. Inhibe la producción de IL-2 por los linfocitos T", "b. Neutraliza el TNF circulante", "c. Bloquea los receptores Fc de los macrófagos esplénicos", "d. Es un anticuerpo anti-CD3 que elimina linfocitos T", "e. Es un anticuerpo anti-CD20 que depleta los linfocitos B que producen los anticuerpos antiplaquetarios"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Es un anticuerpo anti-CD20 que depleta los linfocitos B que producen los anticuerpos antiplaquetarios", "sin_banco": true, "ok": "", "x": "En la PTI las plaquetas se destruyen por <mark>IgG, IgM y a veces IgA</mark> contra HPA-3 o HPA-1. El rituximab se une al <b>CD20</b> del linfocito B, <span class=\"cx\">así que</span> baja la producción de esos anticuerpos. <span class=\"cx\">Por eso</span> se suma a esteroides, esplenectomía y gammaglobulina: <span class=\"res\">ataca la fábrica de anticuerpos</span>.", "truco": "Rituximab = «Retira los B» (CD20).", "veces": 0}, {"n": 14, "id": "IN21-014", "c": "d", "tema": "Síndrome antifosfolipídico", "pregunta": "Mujer de 30 años con dos trombosis venosas y dos pérdidas gestacionales; su prueba de coagulación in vitro sale prolongada («anticoagulante lúpico» positivo). ¿Qué tiene y cómo se explica la paradoja?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Síndrome antifosfolipídico. Los anticuerpos antifosfolípidos prolongan la coagulación in vitro, pero in vivo producen trombosis venosa y arterial recurrente, pérdidas gestacionales y trombocitopenia.", "sin_banco": true, "ok": "", "x": "El nombre <mark>anticoagulante lúpico</mark> viene del laboratorio: el anticuerpo interfiere con los fosfolípidos de la prueba y alarga el tiempo. En el cuerpo, <span class=\"cx\">en cambio</span>, produce <b>trombosis</b>. <span class=\"cx\">Así que</span> un resultado positivo <span class=\"res\">significa más riesgo de trombosis, no protección</span>; <span class=\"cx\">además</span>, puede darse sin lupus.", "truco": "«Anticoagulante» en el tubo, «procoagulante» en la vena.", "veces": 0}], "tabla": {"cab": ["", "Miastenia gravis", "Dermatomiositis", "Polimiositis pura", "Hemólisis caliente"], "filas": [["Brazo inmune", "Humoral (IgG)", "Humoral + complemento", "Celular (LT CD8)", "Humoral (IgG)"], ["Blanco", "Receptor de ACh", "Capilar del músculo", "Fibra muscular", "Eritrocito"], ["Marcador", "Anti-AChR (anti-rianodina = gravedad)", "Anti-Jo-1, heliotropo, Gottron", "Anti-Jo-1, infiltrado CD8", "Coombs directa +"], ["Tratamiento", "Neostigmina, plasmaféresis, timectomía", "Inmunosupresión; buscar cáncer", "Inmunosupresión; buscar cáncer", "Esteroides, esplenectomía"], ["🔑 Para diferenciar", "Debilidad que fluctúa", "Piel + vaso", "Solo músculo", "El bazo retira IgG"]]}, "fuente": "Fuente: tu teoría — clase 53 (Enfermedades autoinmunes de los músculos) y clase 54 (Enfermedades autoinmunes hematológicas), Rojas 17.ª ed."}, {"n": 39, "slug": "Autoinmunidad_ojo_y_poliautoinmunidad", "titulo": "El ojo autoinmune y la poliautoinmunidad", "subtitulo": "un órgano inmunoespecializado que se rompe, y enfermedades que se juntan", "grupo": "g21", "lema": "La idea: el ojo no es un órgano «sin defensas» sino <mark>inmunoespecializado</mark>: una barrera hematoocular lo aísla, sus células pigmentadas inducen linfocitos T reguladores y las lágrimas traen lisozima e IgA secretora. Cuando ese control falla aparecen la <b>uveítis</b>, la <b>escleritis</b>, la <b>degeneración macular</b> (por un factor H débil) y, tras un trauma, la <mark>oftalmía simpática</mark>, en la que el ojo sano paga por el herido. La segunda mitad enseña que las enfermedades autoinmunes rara vez van solas: un mismo genotipo se expresa en dos (<b>poliautoinmunidad</b>), tres o más (<b>SAM</b>) o en distintos familiares. Importa porque ante una EAI hay que buscar las otras. En la imagen verás de izquierda a derecha: el ojo herido y el ojo sano inflamado, la superficie y la barrera del ojo normal, y un genotipo que se ramifica a varias glándulas.", "img": "img/39.webp", "mini": "img/mini/39.webp", "ratio": 1.5, "etiquetas": [{"n": "⑥", "t": "Herida penetrante", "s": "el aire modifica<br>antígenos internos", "c": "d", "x": 0.5, "y": 6, "ax": 7, "ay": 38, "al": "l"}, {"n": "③⑥", "t": "Úvea inflamada", "s": "ojo sano: reacción<br>citotóxica", "c": "d", "x": 30, "y": 6, "ax": 37, "ay": 40}, {"n": "②⑦", "t": "Película lagrimal", "s": "lisozima e<br>IgA secretora", "c": "i", "x": 52, "y": 6, "ax": 55, "ay": 33.5}, {"n": "⑫", "t": "Tiroides", "s": "Hashimoto:<br>SPA II y III", "c": "g", "x": 74, "y": 6, "ax": 77, "ay": 31}, {"n": "⑨⑫", "t": "Suprarrenal", "s": "Addison:<br>SPA I y II", "c": "g", "x": 99.5, "y": 6, "ax": 92, "ay": 28, "al": "r"}, {"n": "⑥", "t": "Linfocitos T", "s": "viajan al otro ojo<br>semanas o meses", "c": "d", "x": 0.5, "y": 91, "ax": 22, "ay": 53, "d": "A", "al": "l"}, {"n": "①", "t": "Células pigmentadas", "s": "inducen Treg:<br>frenan la inflamación", "c": "i", "x": 31, "y": 91, "ax": 52, "ay": 46}, {"n": "②", "t": "Barrera hematoocular", "s": "uniones estrechas<br>del endotelio", "c": "i", "x": 52, "y": 91, "ax": 58, "ay": 54}, {"n": "⑫", "t": "Islotes del páncreas", "s": "diabetes autoinmune<br>(Carpenter)", "c": "g", "x": 72, "y": 91, "ax": 79, "ay": 62}, {"n": "⑧⑩⑪⑭", "t": "Un genotipo", "s": "varias EAIs: poli,<br>SAM, EAIF, AF", "c": "d", "x": 99.5, "y": 91, "ax": 84, "ay": 48, "d": "B", "al": "r"}], "diapos": [{"img": "img/39.webp", "ratio": 1.5, "titulo": "Ojo y poliautoinmunidad", "texto": "El ojo herido sensibiliza al sano (oftalmía simpática) ⑥; las glándulas y articulaciones afectadas juntas son la poliautoinmunidad ⑧⑨⑫.", "etiquetas": [{"n": "⑥", "t": "Herida penetrante", "s": "el aire modifica<br>antígenos internos", "c": "d", "x": 0.5, "y": 6, "ax": 7, "ay": 38, "al": "l"}, {"n": "③⑥", "t": "Úvea inflamada", "s": "ojo sano: reacción<br>citotóxica", "c": "d", "x": 30, "y": 6, "ax": 37, "ay": 40}, {"n": "②⑦", "t": "Película lagrimal", "s": "lisozima e<br>IgA secretora", "c": "i", "x": 52, "y": 6, "ax": 55, "ay": 33.5}, {"n": "⑫", "t": "Tiroides", "s": "Hashimoto:<br>SPA II y III", "c": "g", "x": 74, "y": 6, "ax": 77, "ay": 31}, {"n": "⑨⑫", "t": "Suprarrenal", "s": "Addison:<br>SPA I y II", "c": "g", "x": 99.5, "y": 6, "ax": 92, "ay": 28, "al": "r"}, {"n": "⑥", "t": "Linfocitos T", "s": "viajan al otro ojo<br>semanas o meses", "c": "d", "x": 0.5, "y": 91, "ax": 22, "ay": 53, "d": "A", "al": "l"}, {"n": "①", "t": "Células pigmentadas", "s": "inducen Treg:<br>frenan la inflamación", "c": "i", "x": 31, "y": 91, "ax": 52, "ay": 46}, {"n": "②", "t": "Barrera hematoocular", "s": "uniones estrechas<br>del endotelio", "c": "i", "x": 52, "y": 91, "ax": 58, "ay": 54}, {"n": "⑫", "t": "Islotes del páncreas", "s": "diabetes autoinmune<br>(Carpenter)", "c": "g", "x": 72, "y": 91, "ax": 79, "ay": 62}, {"n": "⑧⑩⑪⑭", "t": "Un genotipo", "s": "varias EAIs: poli,<br>SAM, EAIF, AF", "c": "d", "x": 99.5, "y": 91, "ax": 84, "ay": 48, "d": "B", "al": "r"}]}, {"img": "img/39_2.webp", "ratio": 1.5, "titulo": "Esclera, mácula y barrera", "texto": "Escleritis: vasculitis y <span class=\"cx\">luego</span> <mark>granulomas</mark> ④; degeneración macular: el <b>factor H</b> falla ⑤; la barrera hematoocular y los T reguladores protegen el interior ①②.", "etiquetas": [{"n": "④", "t": "Vasculitis inicial", "s": "primero el vaso,<br>luego el granuloma", "c": "d", "x": 0.5, "y": 6, "ax": 11, "ay": 35, "al": "l"}, {"n": "⑤", "t": "Fotorreceptores", "s": "la mácula:<br>visión central", "c": "g", "x": 42, "y": 6, "ax": 50, "ay": 35}, {"n": "②", "t": "Uniones estrechas", "s": "barrera hematoocular,<br>como la hematoencefálica", "c": "i", "x": 70, "y": 6, "ax": 79, "ay": 40}, {"n": "①", "t": "Célula pigmentada", "s": "induce T reguladores,<br>no proinflamatorios", "c": "i", "x": 99.5, "y": 6, "ax": 90, "ay": 43, "al": "r"}, {"n": "④", "t": "Granuloma necrotizante", "s": "escleritis: T, macrófagos<br>y plasmocitos", "c": "d", "x": 0.5, "y": 91, "ax": 19, "ay": 43, "al": "l"}, {"n": "⑤", "t": "Drusas", "s": "depósitos bajo<br>el epitelio pigmentario", "c": "d", "x": 37, "y": 91, "ax": 47, "ay": 57}, {"n": "⑤", "t": "Complemento sin freno", "s": "factor H débil:<br>degeneración macular", "c": "d", "x": 63, "y": 91, "ax": 54, "ay": 55, "d": "B"}, {"n": "①", "t": "T reguladores", "s": "y T CD8<br>supresores", "c": "i", "x": 99.5, "y": 91, "ax": 95, "ay": 46, "al": "r"}]}, {"img": "img/39_3.webp", "ratio": 1.5, "titulo": "La enfermedad empieza en silencio", "texto": "Los autoanticuerpos aparecen <mark>años antes</mark> de los síntomas (tautología autoinmune) ⑩, <span class=\"cx\">por eso</span> se puede <span class=\"res\">predecir y prevenir</span>.", "etiquetas": [{"n": "⑩", "t": "Tiroides aún normal", "s": "sin síntomas, pero<br>ya hay marcadores", "c": "g", "x": 0.5, "y": 6, "ax": 14, "ay": 40, "al": "l"}, {"n": "⑩", "t": "Pocos autoanticuerpos", "s": "período silente:<br>años antes", "c": "d", "x": 32, "y": 6, "ax": 29.6, "ay": 44}, {"n": "⑩", "t": "Autoanticuerpos en aumento", "s": "se pueden medir:<br>predecir y prevenir", "c": "d", "x": 64, "y": 6, "ax": 64, "ay": 37}, {"n": "⑩⑫", "t": "Glándula destruida", "s": "tiroiditis de Hashimoto,<br>parte del Schmidt", "c": "d", "x": 99.5, "y": 6, "ax": 80, "ay": 40, "al": "r"}, {"n": "⑩", "t": "Infiltrado inicial", "s": "grupos de linfocitos,<br>aún sin síntomas", "c": "d", "x": 36, "y": 91, "ax": 53, "ay": 42}, {"n": "⑩", "t": "Linfocitos que entran", "s": "desde la sangre<br>a la glándula", "c": "d", "x": 62, "y": 91, "ax": 61, "ay": 51}, {"n": "⑭", "t": "Fibrosis", "s": "el cuadro cambia<br>con el tiempo", "c": "d", "x": 99.5, "y": 91, "ax": 84, "ay": 49, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = defensa y regulación</b> (lo que mantiene la tolerancia), <b class=\"d\">rojo = ruptura y daño</b>, gris = estructuras de referencia.", "<b>Izquierda:</b> la herida deja entrar aire y <mark>modifica antígenos secuestrados</mark>; se forman linfocitos T que, semanas o meses después, llegan por la sangre al ojo contralateral y lo atacan. <span class=\"cx\">Por eso</span> ese intervalo es una ventana para enuclear.", "<b>Centro:</b> la lágrima (lisozima + IgA secretora) y las <b>uniones estrechas</b> del endotelio forman las dos barreras; las células pigmentadas, <span class=\"cx\">en cambio</span>, frenan activamente a los T proinflamatorios.", "<b>Derecha:</b> un solo <mark>genotipo</mark> (HLA y no HLA) se ramifica en tiroides, suprarrenal, páncreas y articulación: así se ve el <b>caleidoscopio</b> de la autoinmunidad."], "recordar": "Ojo: <b>barrera + pigmento + lágrima</b>; si falla → uveítis, escleritis, mácula (factor H) y oftalmía simpática. Poliautoinmunidad: <b>2 EAIs</b> = poli · <b>3 o más</b> = SAM · <b>misma EAI en la familia</b> = EAIF · <b>distintas</b> = AF."}, "numeros": [{"l": "A", "html": "<b>Oftalmía simpática</b>: el ojo sano se afecta <b class=\"a\">semanas o meses</b> después del trauma; en ese intervalo la enucleación oportuna lo protege.", "rango": null}, {"l": "B", "html": "<b>SAM</b>: <b class=\"a\">3 o más</b> EAIs en un paciente (descrito en <b class=\"n\">1988</b>); SPA: <b class=\"n\">4 tipos</b>; Carpenter sumó la diabetes al Schmidt en <b class=\"n\">1964</b>. La degeneración macular (factor H) afecta a más de <b class=\"a\">30 millones</b> de personas.", "rango": {"min": 1, "max": 5, "unidad": "EAIs", "zonas": [[1, 2, "b", "una sola"], [2, 3, "m", "poliautoinmunidad"], [3, 5, "a", "SAM"]], "marcas": [2, 3]}}], "escalas": [], "cadena": {"titulo": "Del ojo tolerante a las enfermedades que se juntan", "subtitulo": "estímulo → células y moléculas → mecanismo → resultado → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> una <mark>herida penetrante</mark> o una infección expone las proteínas internas del ojo al aire; o un <b>polimorfismo del factor H</b> deja el complemento sin freno; o un genotipo de riesgo (sexo femenino, HLA, familia) se suma a hormonas e infecciones.", "pr": "se pierde el aislamiento o la regulación.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥⑩", "color": "p1"}, {"t": "2. Células y moléculas", "m": "<b>Por qué:</b> aparecen <mark>linfocitos T autorreactivos</mark>, complejos inmunes en la úvea, anticuerpos contra la membrana basal (pénfigo) o una vasculitis con granulomas en la esclera; sin lágrimas (Sjögren) falta la lisozima y la IgA.", "pr": "inflamación de úvea, esclera, conjuntiva, córnea o mácula.", "pr_tit": "Produce:", "rf": "Preguntas ①②③④⑦", "color": "p2"}, {"t": "3. Mecanismo", "m": "<b>Qué produce:</b> en la oftalmía simpática los T viajan al <mark>ojo contralateral</mark>, que comparte las mismas proteínas, y hacen una reacción citotóxica; en la mácula, el complemento activado causa daño crónico de bajo grado.", "pr": "atrofia del ojo sano o pérdida de la visión central.", "pr_tit": "Produce:", "rf": "Preguntas ⑤⑥ · punto <span class=\"lt2\">A</span>", "color": "p3"}, {"t": "4. Más allá del ojo", "m": "<b>Qué pasa:</b> el mismo genotipo se expresa en otras enfermedades: <mark>dos EAIs</mark> (poliautoinmunidad), <b>tres o más</b> (SAM, SPA tipos I-IV), la misma en la familia (EAIF) o distintas (AF). Todo empieza <b>años antes</b> de los síntomas (tautología).", "pr": "un paciente o una familia con varias EAIs.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨⑪⑫ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Qué se hace", "m": "<b>Si falla la vigilancia:</b> se pierde un ojo o se diagnostica tarde la segunda EAI. <span class=\"cx\">Por eso</span> se enuclea a tiempo, se busca una vasculitis o artritis tras una escleritis y se <b>buscan activamente otras EAIs</b> en el paciente y su familia.", "pr": "prevención secundaria y terciaria.", "pr_tit": "Produce:", "rf": "Preguntas ⑩⑬⑭", "color": "p4"}], "extra": [{"html": "👁️ <b>Dónde se enciende el ojo:</b> conjuntiva → <b>pénfigo benigno</b> (anticuerpos contra la membrana basal, bulas subepiteliales); úvea → <b>uveítis</b> (complejos inmunes, T o anticuerpos; espondiloartropatías y ARJ); esclera → <b>escleritis</b> (vasculitis + granulomas, puede ser necrotizante); córnea → <b>úlcera</b> por Sjögren; mácula → factor H.", "k": ""}, {"html": "🧩 <b>SPA:</b> tipo I = Candida + hipoparatiroidismo + suprarrenal (<b>AIRE</b>, recesivo); tipo II (Schmidt) = Addison + Hashimoto + diabetes; tipo III = tiroides + otra EAI; tipo IV = otras órgano-específicas. II, III y IV son un mismo espectro.", "k": "k"}], "escaleras": [{"c": "d", "t": "🔥 De la herida al ojo sano", "pasos": ["herida penetrante en un ojo", "aire: antígenos internos modificados", "linfocitos T activados contra ellos", "semanas o meses: viajan al otro ojo", "<b>reacción citotóxica</b>: atrofia del ojo sano"]}], "html": "", "fuente": "Fuente: tu teoría — clase 55 (ojo inmunoespecializado, pénfigo benigno, uveítis, escleritis, Sjögren, degeneración macular, oftalmía simpática) y clase 56 (mosaico, caleidoscopio y tautología; SAM y SPA; EAIF y AF)."}, "preguntas": [{"n": 1, "id": "IN21-015", "c": "i", "tema": "Defensa inmune del ojo", "pregunta": "El ojo se considera un órgano «inmunoespecializado» principalmente porque:", "opciones": ["a. Carece por completo de células inmunes", "b. Sus lágrimas son ricas en IgE", "c. Su barrera hematoocular deja pasar libremente células y anticuerpos", "d. Sus células pigmentadas inducen linfocitos T reguladores y T CD8 supresores en vez de T proinflamatorios", "e. No expresa ningún antígeno propio"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Sus células pigmentadas inducen linfocitos T reguladores y T CD8 supresores en vez de T proinflamatorios", "sin_banco": true, "ok": "", "x": "Mira las células pigmentadas del recuadro central: inducen <mark>Treg y T CD8 supresores</mark>. El ojo regula, no solo se esconde. <span class=\"cx\">Por eso</span> <span class=\"res\">la d</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN21-016", "c": "i", "tema": "Defensa inmune del ojo", "pregunta": "¿Qué componentes de las lágrimas protegen la superficie del ojo y qué otra barrera protege su interior?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Lisozima (bactericida) e IgA secretora. El interior lo protege la barrera hematoocular: uniones estrechas entre células endoteliales, análoga a la hematoencefálica.", "sin_banco": true, "ok": "", "x": "Afuera actúan la <mark>lisozima</mark> y la <b>IgA secretora</b>, que interceptan lo que trae el aire o el contacto. Adentro, las uniones estrechas del endotelio impiden el paso de células, líquidos y microbios, igual que la barrera hematoencefálica. <span class=\"cx\">Por eso</span> <span class=\"res\">el ojo tiene una defensa de superficie y otra de aislamiento</span>.", "truco": "Lágrima = «Lisa» (lisozima) + «IgA».", "veces": 0}, {"n": 3, "id": "IN21-017", "c": "d", "tema": "Uveítis", "pregunta": "Las enfermedades inflamatorias sistémicas que con mayor frecuencia se acompañan de uveítis son:", "opciones": ["a. Las espondiloartropatías y la artritis reumatoide juvenil", "b. El lupus y la esclerodermia", "c. La diabetes tipo 1 y la tiroiditis de Hashimoto", "d. La miastenia gravis y la polimiositis", "e. El síndrome de Sjögren y la púrpura trombocitopénica inmune"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Las espondiloartropatías y la artritis reumatoide juvenil", "sin_banco": true, "ok": "", "x": "La uveítis es la inflamación de la <mark>úvea</mark> (iris, cuerpo ciliar y coroides) y su mecanismo varía: complejos inmunes, linfocitos T o anticuerpos. Puede ser idiopática o parte de una enfermedad sistémica; <span class=\"cx\">por eso</span> conviene recordar que <span class=\"res\">las espondiloartropatías y la artritis reumatoide juvenil son las que más la acompañan</span>.", "truco": "Úvea + columna (espondilo) + niño con artritis.", "veces": 0}, {"n": 4, "id": "IN21-018", "c": "d", "tema": "Escleritis", "pregunta": "¿Qué mecanismo describe mejor la escleritis autoinmune?", "opciones": ["a. Autoanticuerpos contra la membrana basal con bulas subepiteliales", "b. Vasculitis inicial seguida de infiltrado de linfocitos T, macrófagos y plasmocitos con granulomas", "c. Polimorfismos del factor H del complemento", "d. Linfocitos activados tras un trauma del ojo contralateral", "e. Falta de lágrimas con úlceras de córnea"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Vasculitis inicial seguida de infiltrado de linfocitos T, macrófagos y plasmocitos con granulomas: puede volverse necrotizante.", "sin_banco": true, "ok": "", "x": "La escleritis es <mark>crónica, destructiva y muy sintomática</mark>: empieza como vasculitis de la esclera y sigue con inmunidad celular y <b>granulomas</b>, a veces con fibrina. <span class=\"cx\">Además</span> puede ser la primera señal de una vasculitis sistémica o de artritis reumatoide, <span class=\"cx\">por eso</span> <span class=\"res\">obliga a buscar una enfermedad sistémica</span>.", "truco": "Escleritis = Vasos + Granulomas.", "veces": 0}, {"n": 5, "id": "IN21-019", "c": "d", "tema": "Degeneración macular", "pregunta": "El hallazgo que vincula la degeneración macular con el sistema inmune es:", "opciones": ["a. La deficiencia hereditaria de C1q", "b. Los anticuerpos contra el receptor de acetilcolina", "c. Polimorfismos del factor H del complemento que lo hacen menos eficaz", "d. La deficiencia selectiva de IgA", "e. La presencia de HLA-B27"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Polimorfismos del factor H del complemento que lo hacen menos eficaz: afecta a más de 30 millones de personas.", "sin_banco": true, "ok": "", "x": "El <mark>factor H</mark> frena la activación espontánea del complemento; sus variantes débiles permiten una activación local exagerada y un <b>daño crónico de bajo grado</b> en la mácula. <span class=\"cx\">Por eso</span> la enfermedad, antes vista como solo degenerativa, se reconoce inmunológica: <span class=\"res\">falta de freno, no exceso de acelerador</span>.", "truco": "Mácula = «falta el freno H».", "veces": 0}, {"n": 6, "id": "IN21-020", "c": "d", "tema": "Oftalmía simpática", "pregunta": "Hombre de 40 años con herida penetrante en el ojo derecho hace dos meses; ahora tiene visión borrosa e inflamación uveal en el ojo izquierdo, que estaba sano. ¿Diagnóstico, mecanismo y cómo se habría prevenido?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Oftalmía simpática: el aire modificó antigénicamente las proteínas internas del ojo herido, se generaron linfocitos T contra ellas y semanas o meses después atacan el ojo contralateral. Se previene con la enucleación oportuna del ojo traumatizado sin pronóstico visual.", "sin_banco": true, "ok": "", "x": "Es la escena de la izquierda: herida en un ojo, linfocitos que viajan por el vaso y <mark>úvea inflamada en el ojo sano</mark> (punto Ⓐ). <span class=\"cx\">Por eso</span> <span class=\"res\">enuclear a tiempo salva el ojo contralateral</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN21-021", "c": "i", "tema": "Sjögren ocular", "pregunta": "¿Cómo produce daño corneal el síndrome de Sjögren?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Destruye las glándulas lacrimales: sin lágrimas falta la lubricación, la lisozima y la IgA secretora, y la córnea expuesta a microbios y a la fricción del párpado desarrolla úlceras.", "sin_banco": true, "ok": "", "x": "El Sjögren ataca las <mark>glándulas exocrinas</mark> (lacrimales y salivales). Sin película lagrimal, la córnea pierde su lubricación y su defensa química, <span class=\"cx\">así que</span> el párpado la roza y los microbios la colonizan. <span class=\"cx\">Por eso</span> <span class=\"res\">aparecen úlceras corneales con riesgo de infección y cicatriz</span>.", "truco": "Ojo seco → córnea sin escudo → úlcera.", "veces": 0}, {"n": 8, "id": "IN21-022", "c": "d", "tema": "Síndromes autoinmunes múltiples", "pregunta": "Un síndrome autoinmune múltiple (SAM) se define como:", "opciones": ["a. La presencia de dos enfermedades autoinmunes en un mismo paciente", "b. La misma enfermedad autoinmune en varios miembros de una familia", "c. Diversas enfermedades autoinmunes en distintos miembros de una familia", "d. Signos de varias enfermedades autoinmunes sin cumplir criterios de ninguna", "e. La presencia de tres o más enfermedades autoinmunes en un mismo paciente"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La presencia de tres o más enfermedades autoinmunes en un mismo paciente: expresión fenotípica múltiple de un solo genotipo.", "sin_banco": true, "ok": "", "x": "El genotipo de la derecha se ramifica en varias glándulas: si son <mark>tres o más EAIs</mark> en el paciente, es un SAM (punto Ⓑ). <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN21-023", "c": "d", "tema": "Síndrome poliglandular autoinmune", "pregunta": "El síndrome poliglandular autoinmune tipo I se caracteriza por:", "opciones": ["a. Candidiasis oral, hipoparatiroidismo y daño suprarrenal, por mutaciones del gen AIRE (autosómica recesiva)", "b. Addison, tiroiditis de Hashimoto y diabetes autoinmune, poligénico", "c. Enfermedad tiroidea autoinmune más otra EAI, sin Addison", "d. Dos o más EAIs órgano-específicas no incluidas en los otros tipos", "e. Miastenia gravis, timoma y lupus"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Candidiasis oral, hipoparatiroidismo y daño suprarrenal, por mutaciones del gen AIRE (autosómica recesiva)", "sin_banco": true, "ok": "", "x": "El tipo I es el único <mark>monogénico</mark>: sin <b>AIRE</b> el timo no muestra los antígenos propios y escapan linfocitos autorreactivos. <span class=\"cx\">Por eso</span> es distinto de los tipos II, III y IV, que son poligénicos y forman un mismo espectro. <span class=\"res\">Tríada: Candida, paratiroides y suprarrenal</span>.", "truco": "Tipo I = «CHA» de AIRE: Candida, Hipoparatiroidismo, Addison.", "veces": 0}, {"n": 10, "id": "IN21-024", "c": "i", "tema": "Tautología autoinmune", "pregunta": "¿Qué es la tautología autoinmune y qué consecuencia práctica tiene?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Las EAIs comienzan varios años antes de los síntomas, en un período silente con marcadores detectables (sexo femenino, antecedente familiar, alelos HLA, anticuerpos). Por eso se pueden predecir y permite la prevención secundaria y terciaria.", "sin_banco": true, "ok": "", "x": "Una EAI no empieza con el primer síntoma: hay <mark>años de autoinmunidad silente</mark>. <span class=\"cx\">Así que</span> los factores de riesgo (<b>sexo femenino, familia, HLA</b>) y los anticuerpos predictivos permiten anticiparse. <span class=\"cx\">Por eso</span> <span class=\"res\">se abre una ventana real de prevención</span>.", "truco": "Tautología: «la enfermedad ya estaba antes de estar».", "veces": 0}, {"n": 11, "id": "IN21-025", "c": "d", "tema": "Autoinmunidad familiar", "pregunta": "En una familia nuclear, el padre tiene artritis reumatoide, la hermana lupus y la madre tiroiditis autoinmune. Esto corresponde a:", "opciones": ["a. Poliautoinmunidad", "b. Síndrome autoinmune múltiple", "c. Enfermedad autoinmune familiar", "d. Autoinmunidad familiar", "e. Síndrome de superposición"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Autoinmunidad familiar: diversas EAIs en distintos miembros.", "sin_banco": true, "ok": "", "x": "<span class=\"cx\">Cuando</span> <mark>la misma EAI</mark> se repite en la familia es una <b>EAIF</b> (p. ej. varios hermanos con diabetes). Aquí son enfermedades distintas en personas distintas, <span class=\"cx\">así que</span> es <span class=\"res\">autoinmunidad familiar</span>: el rasgo que se hereda es la autoinmunidad, útil para buscar genes mayores.", "truco": "EAIF = la misma enfermedad; AF = la misma familia, distintas enfermedades.", "veces": 0}, {"n": 12, "id": "IN21-026", "c": "d", "tema": "Síndrome poliglandular autoinmune", "pregunta": "El síndrome de Schmidt (síndrome poliglandular autoinmune tipo II) incluye al menos dos de:", "opciones": ["a. Candidiasis oral, hipoparatiroidismo y Addison", "b. Enfermedad de Addison, tiroiditis de Hashimoto y diabetes autoinmune", "c. Miastenia gravis, polimiositis y lupus", "d. Vitíligo, anemia perniciosa y alopecia", "e. Uveítis, escleritis y Sjögren"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Enfermedad de Addison, tiroiditis de Hashimoto y diabetes autoinmune: Carpenter agregó la diabetes en 1964.", "sin_banco": true, "ok": "", "x": "Schmidt describió <mark>Addison + tiroiditis</mark>, y en 1964 Carpenter sumó la <b>diabetes autoinmune</b>. Es poligénico, asociado a HLA clase II, y para los autores forma un solo espectro con los tipos III y IV. <span class=\"cx\">Por eso</span> <span class=\"res\">el tipo II es suprarrenal + tiroides + páncreas</span>.", "truco": "Schmidt = «Supra, Tiroides, Diabetes».", "veces": 0}, {"n": 13, "id": "IN21-027", "c": "i", "tema": "Poliautoinmunidad", "pregunta": "¿Cómo se diferencian la poliautoinmunidad y los síndromes de superposición?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "En la poliautoinmunidad el paciente cumple criterios de dos o más EAIs definidas. En la superposición (p. ej. enfermedad mixta del tejido conectivo) tiene signos de varias, pero no cumple criterios de ninguna; con el tiempo muchos desarrollan una EAI definida.", "sin_banco": true, "ok": "", "x": "La clave son los <mark>criterios diagnósticos</mark>: en la poliautoinmunidad se cumplen para cada enfermedad; en la superposición, <span class=\"cx\">en cambio</span>, no se cumplen para ninguna. Muchos evolucionan hacia una EAI definida, y los que no, se mantienen <b>frustos</b> por factores protectores. <span class=\"cx\">Por eso</span> <span class=\"res\">la superposición es una etapa, no una suma</span>.", "truco": "Poli = enfermedades completas; superposición = piezas sueltas.", "veces": 0}, {"n": 14, "id": "IN21-028", "c": "i", "tema": "Mosaico y caleidoscopio", "pregunta": "¿Qué diferencia el «mosaico» del «caleidoscopio» de la autoinmunidad?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "El mosaico describe el origen multifactorial (genes, hormonas, infecciones, ambiente) y la diversidad de las EAIs. El caleidoscopio describe cómo varía el cuadro de una EAI en el tiempo y la coexistencia de varias EAIs en un paciente o en una familia.", "sin_banco": true, "ok": "", "x": "El <mark>mosaico</mark> mira las <b>piezas</b> que causan la enfermedad: genética, sexo, hormonas, infecciones. El <mark>caleidoscopio</mark>, <span class=\"cx\">en cambio</span>, mira cómo <b>gira</b> el cuadro: cambia con el tiempo y se combina en el paciente o en la familia. <span class=\"cx\">Por eso</span> <span class=\"res\">el caleidoscopio es la base clínica de la poliautoinmunidad</span>.", "truco": "Mosaico = piezas (causas); caleidoscopio = giros (combinaciones).", "veces": 0}], "tabla": {"cab": ["", "Poliautoinmunidad", "SAM", "EAIF", "AF"], "filas": [["Qué es", "2 o más EAIs en un paciente", "3 o más EAIs en un paciente", "Misma EAI en varios familiares", "Distintas EAIs en familiares"], ["Ejemplo", "Hashimoto + diabetes", "SPA tipo II completo", "Hermanos con diabetes", "AR, lupus y tiroiditis"], ["Por qué importa", "Buscar la otra EAI", "Un genotipo, varios fenotipos", "Genes de riesgo", "Genes mayores de autoinmunidad"], ["🔑 Para diferenciar", "Un paciente, 2", "Un paciente, 3+", "Familia, la misma", "Familia, distintas"]]}, "fuente": "Fuente: tu teoría — clase 55 (Enfermedades autoinmunes oftalmológicas) y clase 56 (Poliautoinmunidad), Rojas 17.ª ed."}, {"n": 40, "slug": "Inmunomodulacion_y_trasplantes", "titulo": "Inmunomodulación y rechazo de trasplantes", "subtitulo": "dónde frena cada fármaco y por qué el riñón trasplantado se pierde", "grupo": "g22", "lema": "La idea: cuando la respuesta inmune falta se <b>suple o refuerza</b> (inmunoglobulina, citoquinas, trasplante de timo o médula, terapia génica); cuando sobra o se equivoca —alergia, autoinmunidad, rechazo— se <mark>frena</mark>. Cada inmunosupresor corta un punto de la activación del linfocito T: la <b>coestimulación</b> (abatacept), la <b>IL-2</b> (ciclosporina, tacrolimús), la <b>división</b> (azatioprina, ciclofosfamida, rapamicina) o la célula entera (anticuerpos monoclonales). El trasplante reúne todo: hay que impedir el <mark>rechazo</mark> sin causar infección ni cáncer. En la imagen verás de izquierda a derecha: la célula dendrítica activando al linfocito T que libera citoquinas y se divide, un anticuerpo monoclonal quimérico y un riñón trasplantado con los tres tipos de rechazo.", "img": "img/40.webp", "mini": "img/mini/40.webp", "ratio": 1.5, "etiquetas": [{"n": "", "t": "Célula dendrítica", "s": "presenta el HLA<br>del donante", "c": "g", "x": 0.5, "y": 6, "ax": 9, "ay": 40, "al": "l"}, {"n": "⑤", "t": "Coestimulación", "s": "B7-CD28: la bloquea<br>el abatacept", "c": "i", "x": 25, "y": 6, "ax": 18, "ay": 40}, {"n": "⑥", "t": "Región variable", "s": "de ratón: parte<br>que une el antígeno", "c": "i", "x": 45, "y": 6, "ax": 44, "ay": 28}, {"n": "⑩", "t": "Anastomosis vascular", "s": "alotrasplante:<br>depende del HLA", "c": "g", "x": 65, "y": 6, "ax": 74, "ay": 38}, {"n": "②", "t": "Vaso trombosado", "s": "hiperagudo: anticuerpos<br>preformados", "c": "d", "x": 99.5, "y": 6, "ax": 89, "ay": 26, "al": "r"}, {"n": "①", "t": "IL-2 e IFNγ", "s": "las corta<br>la ciclosporina", "c": "i", "x": 0.5, "y": 91, "ax": 32, "ay": 52, "d": "A", "al": "l"}, {"n": "④⑦", "t": "Clon T que se divide", "s": "lo frenan citotóxicos,<br>esteroides y OKT3", "c": "i", "x": 25, "y": 91, "ax": 36, "ay": 64}, {"n": "⑥", "t": "Región constante", "s": "humana: el quimérico<br>se tolera mejor", "c": "i", "x": 48, "y": 91, "ax": 54, "ay": 62}, {"n": "⑦", "t": "Linfocitos en túbulos", "s": "agudo: celular,<br>revierte con OKT3", "c": "d", "x": 71, "y": 91, "ax": 87, "ay": 42}, {"n": "③", "t": "Fibrosis y atrofia", "s": "crónico: Th1, Th17<br>y linfocitos B", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 64, "d": "B", "al": "r"}], "diapos": [{"img": "img/40.webp", "ratio": 1.5, "titulo": "Fármacos, anticuerpos e injerto", "texto": "La ciclosporina frena la IL-2 ①, el abatacept bloquea B7-CD28 ⑤, los monoclonales humanizados ⑥⑦ y los tres tiempos del rechazo ②③.", "etiquetas": [{"n": "", "t": "Célula dendrítica", "s": "presenta el HLA<br>del donante", "c": "g", "x": 0.5, "y": 6, "ax": 9, "ay": 40, "al": "l"}, {"n": "⑤", "t": "Coestimulación", "s": "B7-CD28: la bloquea<br>el abatacept", "c": "i", "x": 25, "y": 6, "ax": 18, "ay": 40}, {"n": "⑥", "t": "Región variable", "s": "de ratón: parte<br>que une el antígeno", "c": "i", "x": 45, "y": 6, "ax": 44, "ay": 28}, {"n": "⑩", "t": "Anastomosis vascular", "s": "alotrasplante:<br>depende del HLA", "c": "g", "x": 65, "y": 6, "ax": 74, "ay": 38}, {"n": "②", "t": "Vaso trombosado", "s": "hiperagudo: anticuerpos<br>preformados", "c": "d", "x": 99.5, "y": 6, "ax": 89, "ay": 26, "al": "r"}, {"n": "①", "t": "IL-2 e IFNγ", "s": "las corta<br>la ciclosporina", "c": "i", "x": 0.5, "y": 91, "ax": 32, "ay": 52, "d": "A", "al": "l"}, {"n": "④⑦", "t": "Clon T que se divide", "s": "lo frenan citotóxicos,<br>esteroides y OKT3", "c": "i", "x": 25, "y": 91, "ax": 36, "ay": 64}, {"n": "⑥", "t": "Región constante", "s": "humana: el quimérico<br>se tolera mejor", "c": "i", "x": 48, "y": 91, "ax": 54, "ay": 62}, {"n": "⑦", "t": "Linfocitos en túbulos", "s": "agudo: celular,<br>revierte con OKT3", "c": "d", "x": 71, "y": 91, "ax": 87, "ay": 42}, {"n": "③", "t": "Fibrosis y atrofia", "s": "crónico: Th1, Th17<br>y linfocitos B", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 64, "d": "B", "al": "r"}]}, {"img": "img/40_2.webp", "ratio": 1.5, "titulo": "Injerto contra hospedero", "texto": "Los linfocitos <mark>del donante</mark> atacan la piel, el intestino y el hígado del receptor ⑧; aparece <span class=\"cx\">cuando</span> la inmunosupresión es <span class=\"res\">intensa</span>.", "etiquetas": [{"n": "⑧", "t": "Médula del donante", "s": "trasplante<br>alogénico", "c": "g", "x": 0.5, "y": 6, "ax": 9, "ay": 41, "al": "l"}, {"n": "⑧", "t": "Piel", "s": "exantema: linfocitos<br>en la capa basal", "c": "d", "x": 40, "y": 6, "ax": 42, "ay": 37}, {"n": "⑧", "t": "Intestino", "s": "diarrea: criptas<br>destruidas", "c": "d", "x": 64, "y": 6, "ax": 64, "ay": 37}, {"n": "⑧", "t": "Hígado", "s": "hepatoesplenomegalia", "c": "d", "x": 99.5, "y": 6, "ax": 85, "ay": 35, "al": "r"}, {"n": "⑧", "t": "Linfocitos T del donante", "s": "ven el HLA del<br>receptor como extraño", "c": "d", "x": 32, "y": 91, "ax": 36.5, "ay": 61}, {"n": "⑧", "t": "Conducto biliar", "s": "rodeado<br>de linfocitos", "c": "d", "x": 99.5, "y": 91, "ax": 88, "ay": 44, "al": "r"}]}, {"img": "img/40_3.webp", "ratio": 1.5, "titulo": "Plasmaféresis, bazo y terapia génica", "texto": "La plasmaféresis <mark>retira anticuerpos</mark> ⑫; sin bazo, los gérmenes <span class=\"res\">encapsulados</span> ⑨; el vector puede activar un oncogén vecino ⑪.", "etiquetas": [{"n": "⑫", "t": "Plasma con anticuerpos", "s": "se separa<br>de las células", "c": "d", "x": 0.5, "y": 6, "ax": 15.6, "ay": 38, "al": "l"}, {"n": "⑫", "t": "Plasma retirado", "s": "Goodpasture, miastenia,<br>Guillain-Barré", "c": "i", "x": 32, "y": 6, "ax": 29.6, "ay": 41}, {"n": "⑨", "t": "Bazo", "s": "filtra las bacterias<br>encapsuladas", "c": "g", "x": 54, "y": 6, "ax": 51.4, "ay": 31}, {"n": "⑪", "t": "Vector viral", "s": "lleva el gen ADA:<br>no requiere donante", "c": "i", "x": 76, "y": 6, "ax": 77, "ay": 25}, {"n": "⑫", "t": "Células devueltas", "s": "la sangre vuelve<br>al paciente", "c": "g", "x": 0.5, "y": 91, "ax": 15.6, "ay": 60.5, "al": "l"}, {"n": "⑨", "t": "Bacterias encapsuladas", "s": "neumococo, meningococo:<br>vacunar antes", "c": "d", "x": 50, "y": 91, "ax": 58.6, "ay": 68}, {"n": "⑪", "t": "Oncogén vecino activado", "s": "leucemia en 3<br>de 5 niños", "c": "d", "x": 99.5, "y": 91, "ax": 90.5, "ay": 55, "al": "r"}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = dónde actúa el fármaco</b>, <b class=\"d\">rojo = rechazo y daño</b>, gris = estructuras de referencia.", "<b>Izquierda:</b> el linfocito T necesita antígeno + <mark>B7-CD28</mark> y <span class=\"cx\">luego</span> IL-2 para dividirse. <span class=\"cx\">Por eso</span> el abatacept lo deja anérgico, la ciclosporina corta la IL-2 y los citotóxicos matan al que se divide.", "<b>Centro:</b> el monoclonal <mark>quimérico</mark> es humano en la parte constante y de ratón en la variable; el humanizado solo conserva de ratón las CDR, <span class=\"cx\">así que</span> provoca menos anticuerpos en contra.", "<b>Derecha:</b> el riñón muestra los tres rechazos: <mark>trombosis</mark> por anticuerpos preformados (hiperagudo), linfocitos en los túbulos (agudo) y vaso fibrosado con túbulos atróficos (crónico)."], "recordar": "Rechazo: <b>hiper</b> = minutos, anticuerpos, irreversible · <b>agudo</b> = semanas, celular, revierte con OKT3 · <b>crónico</b> = años, Th1/Th17 + B, 3-5 %/año. Exceso de inmunosupresión → <b>infección (CMV, EBV, polioma) y cáncer linfoide</b>."}, "numeros": [{"l": "A", "html": "<b>Ciclosporina</b>: supervivencia del trasplante cardíaco <b class=\"n\">85 %</b> al año y <b class=\"n\">75 %</b> a cinco años.", "rango": null}, {"l": "B", "html": "<b>Rechazo crónico</b>: se pierde el <b class=\"a\">3–5 %</b> de los órganos por año; es el mayor problema actual.", "rango": {"min": 0, "max": 8, "unidad": "% de órganos por año", "zonas": [[3, 5, "a", "rechazo crónico"]], "marcas": [3, 5]}}], "escalas": [], "cadena": {"titulo": "Del aloantígeno al rechazo, y dónde se frena", "subtitulo": "estímulo → células y moléculas → mecanismo → resultado → qué pasa si falla la inmunosupresión", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> el órgano trae <mark>HLA ajeno</mark>; cuanto más distinto del receptor, más rechazo. Si el receptor ya tiene anticuerpos (transfusiones, embarazos), el ataque empieza en minutos. Gemelo idéntico o el propio tejido: casi 100 % de éxito.", "pr": "el receptor reconoce el injerto como extraño.", "pr_tit": "Produce:", "rf": "Preguntas ②⑩", "color": "p1"}, {"t": "2. Células y moléculas", "m": "<b>Por qué:</b> la célula presentadora da antígeno + <mark>B7-CD28</mark>; el T produce <b>IL-2 e IFNγ</b> y se divide; los linfocitos B hacen anticuerpos y presentan antígeno.", "pr": "expansión de clones T y B contra el injerto.", "pr_tit": "Produce:", "rf": "Preguntas ①⑤ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Mecanismo y freno", "m": "<b>Dónde se corta:</b> abatacept (coestimulación), ciclosporina y tacrolimús (IL-2), rapamicina (TOR), azatioprina y ciclofosfamida (ADN), <mark>OKT3 (CD3)</mark>, daclizumab (CD25); glucocorticoides sobre casi todas las células, salvo los <b>linfocitos B</b>.", "pr": "menos linfocitos activados contra el órgano.", "pr_tit": "Produce:", "rf": "Preguntas ①④⑤⑥⑦", "color": "p3"}, {"t": "4. Resultado", "m": "<b>Qué se ve:</b> hiperagudo = <mark>trombosis</mark> en minutos e irreversible; agudo = infiltrado celular en semanas, reversible; crónico = fibrosis de la íntima y atrofia tubular en años.", "pr": "pérdida del órgano si no se controla.", "pr_tit": "Produce:", "rf": "Preguntas ②③ · punto <span class=\"lt2\">B</span>", "color": "p4"}, {"t": "5. Si falla el equilibrio", "m": "<b>Poca inmunosupresión:</b> rechazo. <b>Mucha:</b> infecciones (CMV, Epstein-Barr, polioma), <mark>cáncer linfoide</mark> y, si los linfocitos del injerto predominan, <b>reacción injerto contra hospedero</b>. La esplenectomía, <span class=\"cx\">además</span>, abre la puerta al neumococo.", "pr": "dosis altas al inicio, que se bajan según la evolución.", "pr_tit": "Produce:", "rf": "Preguntas ⑧⑨", "color": "p4"}], "extra": [{"html": "💉 <b>Suplir y reconstruir:</b> inmunoglobulina humana (satura el FcRN, sube Treg) en inmunodeficiencia humoral, PTI y neuropatías; retinoides; adyuvantes (aluminio, BCG, levamisol); citoquinas (IFNα en hepatitis, IFNβ en esclerosis múltiple, G-CSF y GM-CSF en agranulocitosis); timo fetal, médula ósea y <b>terapia génica</b> sin donante. En SCID-ADA, 3 de 5 niños tratados con vector viral hicieron leucemia; con células madre, éxito en 8 de 10 (2009). El timo fetal de 10–13 semanas reconstituye los LT en el DiGeorge.", "k": ""}, {"html": "🩸 <b>Aféresis:</b> la <mark>plasmaféresis</mark> retira anticuerpos en Goodpasture, miastenia y Guillain-Barré; la leucoféresis aporta granulocitos en agranulocitosis. Córnea (poco vascularizada) y cartílago (sialomucina) se rechazan poco.", "k": "k"}], "escaleras": [{"c": "d", "t": "⏱️ Los tres rechazos en el tiempo", "pasos": ["<b>minutos</b>: anticuerpos preformados, trombosis (hiperagudo)", "<b>semanas a meses</b>: linfocitos T en el injerto (agudo, OKT3)", "<b>años</b>: Th1, Th17 y B; fibrosis (crónico)", "pérdida del <b>3–5 %</b> de órganos por año"]}], "html": "", "fuente": "Fuente: tu teoría — clase 57 (suplencia y refuerzo, citoquinas, reconstrucción y terapia génica, inmunosupresores, anticuerpos monoclonales, aféresis, tipos de trasplante, rechazo, reacción injerto contra hospedero y complicaciones)."}, "preguntas": [{"n": 1, "id": "IN22-001", "c": "i", "tema": "Inhibidores de citoquinas", "pregunta": "La ciclosporina A revolucionó el trasplante de riñón, hígado y corazón porque:", "opciones": ["a. Inhibe selectivamente la producción de IL-2 e IFNγ por los linfocitos T", "b. Bloquea la síntesis de ADN en la fase G2", "c. Es un análogo de la purina que genera cadenas de ADN anómalas", "d. Inhibe la molécula TOR e impide la entrada a G1", "e. Bloquea la coestimulación B7-CD28"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Inhibe selectivamente la producción de IL-2 e IFNγ por los linfocitos T", "sin_banco": true, "ok": "", "x": "En la izquierda de la imagen el T libera citoquinas y se divide: la ciclosporina corta justo esa <mark>IL-2 (e IFNγ)</mark>, <span class=\"cx\">así que</span> el T no prolifera (punto Ⓐ). <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN22-002", "c": "d", "tema": "Rechazo de trasplantes", "pregunta": "El rechazo hiperagudo se caracteriza por:", "opciones": ["a. Aparecer en semanas o meses, ser celular y revertir con OKT-3", "b. Avanzar en años con fibrosis de la íntima y atrofia tubular", "c. Aparecer en minutos por anticuerpos preformados, con trombosis vascular, y ser irreversible", "d. Deberse a linfocitos del injerto que atacan al receptor", "e. Ocurrir solo en los isotrasplantes"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Aparecer en minutos por anticuerpos preformados, con trombosis vascular, y ser irreversible", "sin_banco": true, "ok": "", "x": "Es el polo superior del riñón: un vaso tapado por un coágulo con anticuerpos en la pared. Son <mark>anticuerpos preformados</mark> que actúan en minutos, <span class=\"cx\">por eso</span> <span class=\"res\">es irreversible: la c</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN22-003", "c": "d", "tema": "Rechazo de trasplantes", "pregunta": "¿Por qué se pierden trasplantes renales año tras año aun sin rechazo agudo? Indica mecanismo y cifra.", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Por rechazo crónico: humoral y celular (Th1, Th17 y linfocitos B que hacen anticuerpos, presentan antígeno y liberan citoquinas). Produce fibrosis de la íntima, atrofia tubular y fibrosis intersticial; se pierde el 3-5 % de los órganos por año.", "sin_banco": true, "ok": "", "x": "Es el polo inferior: pared vascular engrosada y túbulos atróficos. Lo causan Th1, Th17 y linfocitos B, y se pierde el <mark>3–5 % por año</mark> (punto Ⓑ).", "truco": "", "veces": 0}, {"n": 4, "id": "IN22-004", "c": "i", "tema": "Antiinflamatorios", "pregunta": "¿Qué células son muy resistentes a los glucocorticoides?", "opciones": ["a. Los macrófagos", "b. Los linfocitos T", "c. Los eosinófilos", "d. Los linfocitos B", "e. Las células endoteliales"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Los linfocitos B: solo dosis altas y prolongadas frenan en parte las inmunoglobulinas.", "sin_banco": true, "ok": "", "x": "Los glucocorticoides entran a casi todas las células y frenan genes de citoquinas: en el <mark>macrófago</mark> bajan IL-1, IL-6 y TNF; en el <b>linfocito T</b>, IL-2 e IFNγ. <span class=\"cx\">En cambio</span>, el linfocito B apenas se afecta, <span class=\"cx\">por eso</span> <span class=\"res\">la síntesis de anticuerpos solo cae con dosis altas y prolongadas</span>.", "truco": "Esteroides: «a los B les rebota».", "veces": 0}, {"n": 5, "id": "IN22-005", "c": "i", "tema": "Control de linfocitos", "pregunta": "El abatacept (CTLA-4-Ig) actúa:", "opciones": ["a. Destruyendo linfocitos B CD20+", "b. Bloqueando la vía coestimuladora B7-CD28, lo que produce anergia", "c. Neutralizando el TNF", "d. Eliminando linfocitos T CD3+", "e. Neutralizando la IgE circulante"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Bloqueando la vía coestimuladora B7-CD28, lo que produce anergia: se usa en enfermedades autoinmunes.", "sin_banco": true, "ok": "", "x": "En el contacto entre la célula dendrítica y el T (izquierda) está el par <mark>B7-CD28</mark>; el abatacept lo ocupa, <span class=\"cx\">así que</span> el T queda anérgico. <span class=\"cx\">Por eso</span> <span class=\"res\">la b</span>.", "truco": "", "veces": 0}, {"n": 6, "id": "IN22-006", "c": "i", "tema": "Anticuerpos monoclonales", "pregunta": "En un anticuerpo monoclonal humanizado:", "opciones": ["a. Toda la molécula es de ratón", "b. Las cadenas pesadas son humanas y las livianas de ratón", "c. Toda la molécula proviene de caballo", "d. Solo la región Fc es de ratón", "e. Solo las regiones determinantes de complementariedad (CDR) son de ratón"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. Solo las regiones determinantes de complementariedad (CDR) son de ratón: por eso es aún menos antigénico que el quimérico.", "sin_banco": true, "ok": "", "x": "El anticuerpo del centro es <mark>quimérico</mark>: dos colores, humano y de ratón. El humanizado deja de ratón solo las CDR. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 7, "id": "IN22-007", "c": "i", "tema": "Anticuerpos monoclonales", "pregunta": "Sobre los anticuerpos monoclonales y sus blancos, es FALSO:", "opciones": ["a. Infliximab: anti-TNF, en artritis reumatoide y Crohn", "b. Rituximab: anti-CD20, en linfomas no Hodgkin", "c. OKT3: anti-CD20, para el rechazo agudo renal", "d. Daclizumab: anti-CD25 (receptor de IL-2), profilaxis del rechazo renal", "e. Omalizumab: anti-IgE, en asma persistente"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. OKT3: anti-CD20, para el rechazo agudo renal: el OKT3 es anti-CD3.", "sin_banco": true, "ok": "", "x": "El <mark>OKT3 es anti-CD3</mark>: elimina linfocitos T, <span class=\"cx\">por eso</span> revierte el rechazo agudo celular. El anti-CD20 es el rituximab, que actúa sobre los linfocitos B. <span class=\"cx\">Así que</span> <span class=\"res\">la opción c mezcla el blanco de uno con el uso del otro</span>.", "truco": "OKT-3 = CD-3.", "veces": 0}, {"n": 8, "id": "IN22-008", "c": "d", "tema": "Reacción injerto contra hospedero", "pregunta": "Receptor de un trasplante alogénico de médula ósea, con inmunosupresión intensa, presenta exantema, diarrea, hepatoesplenomegalia y anemia hemolítica. ¿Qué ocurre y por qué?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Reacción injerto contra hospedero: los linfocitos del injerto reconocen como extraños los antígenos del receptor y lo atacan. Predomina cuando la inmunosupresión es severa o el receptor es inmunodeficiente; puede llevar a la muerte.", "sin_banco": true, "ok": "", "x": "Aquí el ataque va <mark>al revés</mark>: no es el receptor contra el órgano, sino los <b>linfocitos del injerto</b> contra el receptor. Como el receptor no puede defenderse, esos linfocitos predominan y dañan piel, intestino, hígado y sangre. <span class=\"cx\">Por eso</span> <span class=\"res\">se ve más en médula ósea e inmunosupresión intensa</span>.", "truco": "Injerto contra hospedero = «el invitado ataca al dueño de casa».", "veces": 0}, {"n": 9, "id": "IN22-009", "c": "d", "tema": "Aféresis y esplenectomía", "pregunta": "¿Qué riesgo infeccioso introduce la esplenectomía y qué se recomienda?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Susceptibilidad a infecciones graves por neumococo y meningococo (bacterias encapsuladas). Se recomienda vacunar contra el neumococo a quien será esplenectomizado.", "sin_banco": true, "ok": "", "x": "El bazo filtra la sangre y <mark>elimina bacterias encapsuladas</mark> opsonizadas. Sin él, el neumococo y el meningococo circulan libremente; <span class=\"cx\">por eso</span> la esplenectomía, útil en anemias hemolíticas y trombocitopenias, tiene un costo. <span class=\"cx\">Así que</span> <span class=\"res\">antes de operar se vacuna contra el neumococo</span> (clase 58).", "truco": "Sin bazo: «Neumo y Meningo entran sin pasaporte».", "veces": 0}, {"n": 10, "id": "IN22-010", "c": "g", "tema": "Trasplantes", "pregunta": "El trasplante entre gemelos monocigóticos se denomina:", "opciones": ["a. Autotrasplante", "b. Isotrasplante", "c. Alotrasplante", "d. Xenotrasplante", "e. Trasplante haploidéntico"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Isotrasplante: su éxito es prácticamente del 100 %.", "sin_banco": true, "ok": "", "x": "Los gemelos monocigóticos tienen el <mark>mismo HLA</mark>, <span class=\"cx\">así que</span> no hay nada extraño que rechazar: el éxito es casi del 100 %, como en el <b>autotrasplante</b>. <span class=\"cx\">En cambio</span>, el alotrasplante depende de la compatibilidad HLA y el xenotrasplante cruza especies. <span class=\"cx\">Por eso</span> <span class=\"res\">iso = idéntico</span>.", "truco": "Iso = igual; alo = otro; xeno = extranjero.", "veces": 0}, {"n": 11, "id": "IN22-011", "c": "g", "tema": "Reconstrucción inmunológica", "pregunta": "¿Qué ventaja tiene la terapia génica sobre el trasplante de médula en las inmunodeficiencias, y qué riesgo mostró?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "No necesita buscar un donante compatible, así que en teoría está disponible para todos. Riesgo: de cinco niños con SCID tratados con el gen ADA por vector viral, tres desarrollaron leucemia por activación de un oncógeno vecino.", "sin_banco": true, "ok": "", "x": "La terapia génica <mark>reemplaza el gen defectuoso</mark> en las propias células del paciente, <span class=\"cx\">por eso</span> no requiere donante. <span class=\"cx\">En cambio</span>, el vector viral puede insertarse junto a un <b>oncógeno</b> y activarlo. Con células madre en lugar de vector retroviral se logró <span class=\"res\">éxito en 8 de 10 niños con SCID (2009)</span>.", "truco": "Gen nuevo, sin donante… pero cuidado con el vecino (oncógeno).", "veces": 0}, {"n": 12, "id": "IN22-012", "c": "i", "tema": "Aféresis y esplenectomía", "pregunta": "La plasmaféresis está indicada para retirar anticuerpos patológicos en:", "opciones": ["a. Síndrome de DiGeorge y SCID", "b. Agranulocitosis por quimioterapia", "c. Rechazo agudo celular de trasplante renal", "d. Síndrome de Goodpasture, miastenia gravis y síndrome de Guillain-Barré", "e. Degeneración macular y uveítis"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Síndrome de Goodpasture, miastenia gravis y síndrome de Guillain-Barré", "sin_banco": true, "ok": "", "x": "La plasmaféresis <mark>saca el plasma con sus anticuerpos</mark>, <span class=\"cx\">así que</span> sirve donde el daño lo hace un anticuerpo circulante: antimembrana basal (<b>Goodpasture</b>), anti-AChR (<b>miastenia</b>) y antimielina (<b>Guillain-Barré</b>). <span class=\"cx\">En cambio</span>, la agranulocitosis se trata con leucoféresis o factores estimulantes de colonias. <span class=\"cx\">Por eso</span> <span class=\"res\">el blanco es el anticuerpo, no la célula</span>.", "truco": "Plasmaféresis = «lavar» los anticuerpos.", "veces": 0}], "tabla": {"cab": ["", "Hiperagudo", "Agudo", "Crónico"], "filas": [["Cuándo", "Minutos", "Semanas a meses", "Años"], ["Mecanismo", "Anticuerpos preformados: trombosis", "Celular (y humoral)", "Th1, Th17 y linfocitos B"], ["Qué se ve", "Vaso trombosado", "Linfocitos en el injerto", "Fibrosis de la íntima, atrofia tubular"], ["¿Revierte?", "No", "Sí, con OKT3 (anti-CD3)", "No; 3-5 % de pérdida por año"], ["🔑 Para diferenciar", "Anticuerpo ya listo", "Linfocito T nuevo", "Cicatriz lenta"]]}, "fuente": "Fuente: tu teoría — clase 57 (Inmunomodulación y trasplantes), Rojas 17.ª ed."}, {"n": 41, "slug": "Inmunizacion_y_vacunas", "titulo": "Inmunización: cómo una vacuna entrena al linfocito", "subtitulo": "clases de vacunas, memoria, complicaciones e inmunización pasiva", "grupo": "g22", "lema": "La idea: una vacuna muestra al sistema inmune un antígeno <b>sin la enfermedad</b>, para que los linfocitos se <mark>entrenen</mark> y dejen memoria. El tipo de antígeno decide la respuesta: el germen <b>vivo atenuado</b> protege más tiempo pero es peligroso en inmunodeficiencias celulares; el <b>muerto</b> es seguro pero pide refuerzos; el <b>toxoide</b> neutraliza la toxina; el <b>conjugado</b> une un azúcar a una proteína para que ayude el linfocito T CD4 y haya IgG desde los 2 meses. Cuando no hay tiempo de esperar, se dan anticuerpos ya hechos (<mark>inmunización pasiva</mark>). Importa porque las vacunas salvan 3 millones de vidas al año. En la imagen verás de izquierda a derecha: cuatro tipos de antígeno vacunal, el centro germinal donde el T ayuda al B a hacer anticuerpos, y las células de memoria neutralizando al virus real.", "img": "img/41.webp", "mini": "img/mini/41.webp", "ratio": 1.5, "etiquetas": [{"n": "②④⑤", "t": "Virus vivo atenuado", "s": "protege más; no en<br>inmunodef. celular", "c": "i", "x": 0.5, "y": 6, "ax": 11, "ay": 25, "d": "C", "al": "l"}, {"n": "⑥", "t": "Célula dendrítica", "s": "presenta el antígeno<br>(TLR)", "c": "g", "x": 31, "y": 6, "ax": 35, "ay": 38}, {"n": "①", "t": "Linfocito T CD4", "s": "ayuda al B si hay<br>proteína", "c": "d", "x": 48, "y": 6, "ax": 44, "ay": 41}, {"n": "①", "t": "Linfocito B", "s": "prolifera y cambia<br>a IgG", "c": "d", "x": 65, "y": 6, "ax": 53, "ay": 40}, {"n": "⑥", "t": "Células de memoria", "s": "esperan años<br>o toda la vida", "c": "d", "x": 99.5, "y": 6, "ax": 84, "ay": 30, "d": "D", "al": "r"}, {"n": "②", "t": "Virus muerto", "s": "seguro; pide refuerzo", "c": "i", "x": 18.5, "y": 44, "ax": 15, "ay": 43, "al": "l"}, {"n": "③⑦", "t": "Toxoide", "s": "toxina desactivada", "c": "i", "x": 18.5, "y": 62, "ax": 15.5, "ay": 61, "d": "B", "al": "l"}, {"n": "①", "t": "Polisacárido + proteína", "s": "conjugada: IgG<br>desde los 2 meses", "c": "i", "x": 0.5, "y": 91, "ax": 13, "ay": 76, "al": "l"}, {"n": "", "t": "Plasmocito", "s": "fabrica IgG de<br>alta afinidad", "c": "d", "x": 34, "y": 91, "ax": 46, "ay": 70}, {"n": "⑦⑨⑫", "t": "Anticuerpos IgG", "s": "pasiva: se dan<br>ya hechos", "c": "d", "x": 58, "y": 91, "ax": 64, "ay": 72}, {"n": "⑪", "t": "Virus neutralizado", "s": "la memoria impide<br>la enfermedad", "c": "d", "x": 99.5, "y": 91, "ax": 85, "ay": 66, "d": "A", "al": "r"}], "diapos": [{"img": "img/41.webp", "ratio": 1.5, "titulo": "Cómo entrena una vacuna", "texto": "Tipos de antígeno ②③, la presentación al linfocito T y la memoria ①⑥: el anticuerpo neutraliza al virus.", "etiquetas": [{"n": "②④⑤", "t": "Virus vivo atenuado", "s": "protege más; no en<br>inmunodef. celular", "c": "i", "x": 0.5, "y": 6, "ax": 11, "ay": 25, "d": "C", "al": "l"}, {"n": "⑥", "t": "Célula dendrítica", "s": "presenta el antígeno<br>(TLR)", "c": "g", "x": 31, "y": 6, "ax": 35, "ay": 38}, {"n": "①", "t": "Linfocito T CD4", "s": "ayuda al B si hay<br>proteína", "c": "d", "x": 48, "y": 6, "ax": 44, "ay": 41}, {"n": "①", "t": "Linfocito B", "s": "prolifera y cambia<br>a IgG", "c": "d", "x": 65, "y": 6, "ax": 53, "ay": 40}, {"n": "⑥", "t": "Células de memoria", "s": "esperan años<br>o toda la vida", "c": "d", "x": 99.5, "y": 6, "ax": 84, "ay": 30, "d": "D", "al": "r"}, {"n": "②", "t": "Virus muerto", "s": "seguro; pide refuerzo", "c": "i", "x": 18.5, "y": 44, "ax": 15, "ay": 43, "al": "l"}, {"n": "③⑦", "t": "Toxoide", "s": "toxina desactivada", "c": "i", "x": 18.5, "y": 62, "ax": 15.5, "ay": 61, "d": "B", "al": "l"}, {"n": "①", "t": "Polisacárido + proteína", "s": "conjugada: IgG<br>desde los 2 meses", "c": "i", "x": 0.5, "y": 91, "ax": 13, "ay": 76, "al": "l"}, {"n": "", "t": "Plasmocito", "s": "fabrica IgG de<br>alta afinidad", "c": "d", "x": 34, "y": 91, "ax": 46, "ay": 70}, {"n": "⑦⑨⑫", "t": "Anticuerpos IgG", "s": "pasiva: se dan<br>ya hechos", "c": "d", "x": 58, "y": 91, "ax": 64, "ay": 72}, {"n": "⑪", "t": "Virus neutralizado", "s": "la memoria impide<br>la enfermedad", "c": "d", "x": 99.5, "y": 91, "ax": 85, "ay": 66, "d": "A", "al": "r"}]}, {"img": "img/41_2.webp", "ratio": 1.5, "titulo": "Polisacárido solo frente a conjugado", "texto": "Sin proteína el linfocito B no recibe ayuda: poca IgM y sin memoria. Con la <mark>proteína transportadora</mark> entra el <span class=\"res\">T CD4</span>: IgG de alta afinidad y memoria desde los 2 meses ①.", "etiquetas": [{"n": "①", "t": "Polisacárido solo", "s": "entrecruza el BCR<br>sin ayuda T", "c": "d", "x": 0.5, "y": 6, "ax": 24.7, "ay": 22, "al": "l"}, {"n": "①", "t": "Proteína transportadora", "s": "unida al azúcar:<br>vacuna conjugada", "c": "i", "x": 38, "y": 6, "ax": 57, "ay": 19.5}, {"n": "①", "t": "Péptido en HLA II", "s": "el B lo presenta<br>al T", "c": "i", "x": 72, "y": 6, "ax": 76, "ay": 36}, {"n": "①", "t": "Linfocito T CD4", "s": "da la ayuda<br>al linfocito B", "c": "i", "x": 99.5, "y": 20, "ax": 87, "ay": 32, "al": "r"}, {"n": "①", "t": "IgM de baja afinidad", "s": "sin memoria: falla<br>antes de los 2 años", "c": "d", "x": 0.5, "y": 91, "ax": 21.5, "ay": 67, "al": "l"}, {"n": "①", "t": "Plasmocito", "s": "fábrica<br>de IgG", "c": "i", "x": 40, "y": 91, "ax": 58, "ay": 66}, {"n": "①", "t": "IgG de alta afinidad", "s": "cambio de clase<br>gracias al T", "c": "i", "x": 66, "y": 91, "ax": 75, "ay": 76}, {"n": "①", "t": "Célula de memoria", "s": "protege desde<br>los 2 meses", "c": "i", "x": 99.5, "y": 91, "ax": 89, "ay": 62, "al": "r"}]}, {"img": "img/41_3.webp", "ratio": 1.5, "titulo": "Inmunidad pasiva y vacunología reversa", "texto": "En la herida tetánica se dan <mark>anticuerpos ya hechos</mark> ⑦⑫; la IgG materna cruza la placenta ⑨; el genoma del meningococo da las proteínas candidatas ⑩.", "etiquetas": [{"n": "⑫", "t": "Clostridium tetani", "s": "herida profunda<br>con tierra", "c": "d", "x": 0.5, "y": 6, "ax": 19.5, "ay": 38, "al": "l"}, {"n": "⑫", "t": "Antitoxina ya hecha", "s": "inmunidad pasiva:<br>protege de inmediato", "c": "i", "x": 30, "y": 6, "ax": 31, "ay": 41}, {"n": "⑨", "t": "IgG materna", "s": "cruza la placenta:<br>protege al recién nacido", "c": "i", "x": 54, "y": 6, "ax": 51.4, "ay": 23.4}, {"n": "⑩", "t": "Meningococo", "s": "se lee su<br>genoma completo", "c": "g", "x": 78, "y": 6, "ax": 77.5, "ay": 20.5}, {"n": "⑦", "t": "Toxina neutralizada", "s": "si el suero es animal, la<br>2.ª vez: anafilaxia", "c": "d", "x": 0.5, "y": 91, "ax": 32, "ay": 52, "al": "l"}, {"n": "⑨", "t": "Vellosidad placentaria", "s": "sangre fetal<br>adentro", "c": "g", "x": 45, "y": 91, "ax": 52, "ay": 51}, {"n": "⑩", "t": "Genoma", "s": "de él salen<br>las proteínas", "c": "i", "x": 99.5, "y": 6, "ax": 90, "ay": 45, "al": "r"}, {"n": "⑩", "t": "Proteínas candidatas", "s": "570 halladas,<br>350 evaluadas", "c": "i", "x": 76, "y": 91, "ax": 71.3, "ay": 51}]}], "css": "", "lado": {"titulo": "Cómo leer la lámina", "parrafos": ["Colores: <b class=\"i\">azul = lo que pone la vacuna</b> (antígenos), <b class=\"d\">rojo = la respuesta del cuerpo</b> (linfocitos, anticuerpos, memoria), gris = referencia.", "<b>Izquierda:</b> vivo atenuado (Sabin, fiebre amarilla, sarampión), muerto (Salk, gripe), <mark>toxoide</mark> (difteria, tétanos) y <mark>conjugado</mark> (Haemophilus, neumococo, meningococo).", "<b>Centro:</b> la célula dendrítica presenta el antígeno; el <b>T CD4</b> ayuda al linfocito B, que se vuelve plasmocito y fabrica IgG de alta afinidad. <span class=\"cx\">Por eso</span> el polisacárido solo, sin proteína, no sirve antes de los 2 años.", "<b>Derecha:</b> las <mark>células de memoria</mark> esperan años; <span class=\"cx\">cuando</span> llega el virus real lo cubren de anticuerpos rápido y con eficacia, <span class=\"cx\">así que</span> no hay enfermedad."], "recordar": "<b>Vivo</b> = más protección, no en inmunodeficiencia celular ni embarazo · <b>muerto</b> = seguro, con refuerzo · <b>toxoide</b> = TD cada 10 años · <b>conjugado</b> = T CD4 + IgG desde 2 meses · <b>pasiva</b> = anticuerpos prestados, ya."}, "numeros": [{"l": "A", "html": "<b>Eficacia</b>: polio <b class=\"n\">100 %</b>, sarampión <b class=\"n\">99 %</b>, fiebre amarilla <b class=\"n\">99 %</b>, parotiditis y rubéola <b class=\"n\">97 %</b>, hepatitis B <b class=\"n\">85 %</b>.", "rango": null}, {"l": "B", "html": "<b>Refuerzo</b>: tétanos y difteria cada <b class=\"a\">10 años</b>; fiebre amarilla: <b class=\"n\">una dosis</b> de por vida (OMS, 2014).", "rango": {"min": 0, "max": 15, "unidad": "años", "zonas": [[0, 10, "n", "protegido"], [10, 15, "a", "refuerzo"]], "marcas": [10]}}, {"l": "C", "html": "<b>Complicaciones</b>: anafilaxia <b class=\"b\">1 por 10 millones</b>; daño cerebral por DTP <b class=\"b\">1 por 3,2 millones</b> de dosis; polio paralítica por OPV <b class=\"b\">1 por millón</b>.", "rango": null}, {"l": "D", "html": "<b>Impacto</b>: vacunas contra <b class=\"n\">23 de 70</b> microorganismos; salvan <b class=\"n\">3 millones</b> de vidas al año; esperanza de vida de <b class=\"b\">35</b> a <b class=\"n\">80 años</b>.", "rango": null}], "escalas": [], "cadena": {"titulo": "De la vacuna a la memoria", "subtitulo": "estímulo → células y moléculas → mecanismo → resultado → qué pasa si falla", "lema": "Cada paso dice <b>qué pasa</b>, <b>por qué pasa</b> y, en blanco, <b>qué produce</b>.", "pasos": [{"t": "1. Estímulo", "m": "<b>Qué pasa:</b> se aplica un <mark>antígeno sin enfermedad</mark>: germen vivo atenuado, muerto, toxoide, subunidad conjugada, proteína recombinante (hepatitis B) o un vector viral; los adyuvantes de aluminio prolongan su liberación.", "pr": "el antígeno llega al ganglio.", "pr_tit": "Produce:", "rf": "Preguntas ①②③⑩", "color": "p1"}, {"t": "2. Células y moléculas", "m": "<b>Por qué:</b> la <mark>célula dendrítica</mark> (activada por TLR, como con la fiebre amarilla) presenta el antígeno al <b>T CD4</b>; si es un polisacárido puro, el B responde solo y sin memoria.", "pr": "el T CD4 ayuda al linfocito B.", "pr_tit": "Produce:", "rf": "Preguntas ①⑥ · punto <span class=\"lt2\">A</span>", "color": "p2"}, {"t": "3. Mecanismo", "m": "<b>Qué produce:</b> el B prolifera, cambia a <mark>IgG de alta afinidad</mark> y deja <b>células de memoria</b>; el germen vivo, <span class=\"cx\">además</span>, activa la inmunidad celular.", "pr": "anticuerpos protectores y memoria por años o de por vida.", "pr_tit": "Produce:", "rf": "Preguntas ①② · punto <span class=\"lt2\">B</span>", "color": "p3"}, {"t": "4. Resultado", "m": "<b>Qué se ve:</b> al llegar el patógeno real, la memoria responde rápido y lo neutraliza. Así se erradicó la <b>viruela</b> (OMS, 1978) y la polio cayó un 95 %; las vacunas de VPH y hepatitis B previenen cáncer.", "pr": "protección individual y de la comunidad.", "pr_tit": "Produce:", "rf": "Preguntas ⑪ · punto <span class=\"lt2\">D</span>", "color": "p4"}, {"t": "5. Si falla o no hay tiempo", "m": "<b>Riesgos:</b> el vivo atenuado puede revertir (OPV) y es peligroso en <mark>inmunodeficiencia celular</mark> y embarazo; las reacciones son raras. <b>Sin tiempo:</b> inmunoglobulina hiperinmune; el suero animal repetido da anafilaxia o enfermedad del suero.", "pr": "elegir bien la vacuna o dar anticuerpos prestados.", "pr_tit": "Produce:", "rf": "Preguntas ④⑤⑦⑧⑨⑫ · punto <span class=\"lt2\">C</span>", "color": "p4"}], "extra": [{"html": "👶 <b>Esquema del niño:</b> al nacer BCG + hepatitis B; 2 meses DTP + OPV + neumococo + Haemophilus; 4 meses DTP-2 + OPV-2; 6 meses DTP-3; 15 meses MMR + DTP-4; 4-6 años DTP-5 + OPV-4; 11 años MMR-2; 14-16 años Td, <span class=\"cx\">luego</span> cada 10 años.", "k": ""}, {"html": "🧳 <b>Adulto y viajero:</b> hepatitis B en personal de salud; influenza y neumococo en mayores de 65 años (neumococo también antes de una esplenectomía); <mark>rubéola contraindicada</mark> en el embarazo y 3 meses antes; tétanos e influenza en la embarazada protegen al recién nacido.", "k": "k"}], "escaleras": [{"c": "i", "t": "🛡️ Del más fuerte al más seguro", "pasos": ["<b>vivo atenuado</b>: protege más, puede revertir", "<b>muerto</b>: seguro, pide refuerzos", "<b>toxoide</b>: solo la toxina, refuerzo cada 10 años", "<b>conjugado</b>: azúcar + proteína, desde 2 meses", "<b>pasiva</b>: anticuerpos ya hechos, protege hoy y se acaba"]}], "html": "", "fuente": "Fuente: tu teoría — clase 58 (generalidades, clases de vacunas, complicaciones, vacunas específicas y contra el cáncer, inmunoglobulinas hiperinmunes y esquemas del niño, el adulto y el viajero)."}, "preguntas": [{"n": 1, "id": "IN22-013", "c": "i", "tema": "Clases de vacunas", "pregunta": "Las vacunas conjugadas (polisacárido unido a proteína) son eficaces desde los 2 meses porque:", "opciones": ["a. El polisacárido solo activa linfocitos B sin ayuda T", "b. Contienen la bacteria viva atenuada", "c. Son toxoides desactivados químicamente", "d. Inducen sobre todo anticuerpos IgE", "e. La proteína activa linfocitos T CD4, que inducen IgG de alta afinidad y memoria"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. La proteína activa linfocitos T CD4, que inducen IgG de alta afinidad y memoria", "sin_banco": true, "ok": "", "x": "Mira el cuarto antígeno de la izquierda (azúcar + proteína) y el centro de la imagen: la proteína hace que el <mark>T CD4 ayude al linfocito B</mark>, <span class=\"cx\">así que</span> hay IgG de alta afinidad y memoria. <span class=\"cx\">Por eso</span> <span class=\"res\">la e</span>.", "truco": "", "veces": 0}, {"n": 2, "id": "IN22-014", "c": "i", "tema": "Clases de vacunas", "pregunta": "¿Cuál de estas es una vacuna de microorganismo vivo atenuado?", "opciones": ["a. Polio oral (Sabin)", "b. Polio inyectable (Salk)", "c. Toxoide tetánico", "d. Hepatitis B recombinante", "e. Neumococo conjugada"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Polio oral (Sabin): también fiebre amarilla, sarampión y rubéola.", "sin_banco": true, "ok": "", "x": "El primer antígeno de la columna es el virus entero pero debilitado: así es la <mark>Sabin (oral)</mark>. La Salk, <span class=\"cx\">en cambio</span>, es el virus roto, muerto. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 3, "id": "IN22-015", "c": "i", "tema": "Clases de vacunas", "pregunta": "Las vacunas preparadas con toxoides son las de:", "opciones": ["a. Hepatitis B y enfermedad de Lyme", "b. Sarampión y rubéola", "c. Difteria y tétanos", "d. Haemophilus y neumococo", "e. Influenza y polio Salk"], "letra": "c", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "c. Difteria y tétanos: requieren refuerzo cada 10 años.", "sin_banco": true, "ok": "", "x": "Un <mark>toxoide</mark> es la toxina desactivada químicamente: pierde la toxicidad y conserva la antigenicidad. Como en difteria y tétanos el daño lo hace la toxina, basta con neutralizarla. <span class=\"cx\">Por eso</span> <span class=\"res\">se refuerzan cada 10 años</span> (Td).", "truco": "Toxoide = «Tétanos y Difteria» (TD).", "veces": 0}, {"n": 4, "id": "IN22-016", "c": "d", "tema": "Complicaciones de las vacunas", "pregunta": "¿Por qué la vacuna oral antipolio (OPV) puede causar poliomielitis paralítica y qué se hará tras la erradicación?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Porque es de virus vivo atenuado, que puede recuperar virulencia (un caso por cada millón de dosis), sobre todo en inmunodeficientes. Tras la erradicación se usará solo la vacuna de virus muerto (IPV) hasta que se extingan las cepas atenuadas.", "sin_banco": true, "ok": "", "x": "La OPV tiene ventajas: es oral, protege más tiempo y se <mark>propaga de persona a persona</mark>. Pero ese mismo virus vivo puede revertir, <span class=\"cx\">así que</span> da <span class=\"res\">un caso de polio paralítica por millón de dosis</span>. <span class=\"cx\">Por eso</span>, <span class=\"cx\">al final</span>, se pasará a la IPV.", "truco": "Viva = protege más, pero puede «despertar».", "veces": 0}, {"n": 5, "id": "IN22-017", "c": "d", "tema": "Complicaciones de las vacunas", "pregunta": "La vacunación activa con microorganismos vivos representa un riesgo serio en:", "opciones": ["a. Los mayores de 65 años sanos", "b. Las inmunodeficiencias celulares", "c. Los trabajadores de la salud", "d. Los lactantes de 2 meses sanos", "e. Los viajeros a zonas tropicales"], "letra": "b", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "b. Las inmunodeficiencias celulares", "sin_banco": true, "ok": "", "x": "La <mark>inmunidad celular</mark> es la que controla la replicación del germen atenuado. Si falta, el microorganismo se multiplica y puede recuperar virulencia. <span class=\"cx\">Por eso</span> <span class=\"res\">la vacuna viva se contraindica en inmunodeficiencias celulares</span>, y ahí se prefieren las de germen muerto.", "truco": "Sin linfocitos T, la vacuna viva «se escapa».", "veces": 0}, {"n": 6, "id": "IN22-018", "c": "i", "tema": "Vacunas específicas", "pregunta": "Según la OMS desde 2014, la vacuna contra la fiebre amarilla:", "opciones": ["a. Requiere refuerzo cada 10 años", "b. Requiere refuerzo cada 5 años", "c. Debe aplicarse cada año", "d. Confiere protección de por vida con una sola dosis", "e. Requiere tres dosis para proteger"], "letra": "d", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "d. Confiere protección de por vida con una sola dosis: protege en un 99 %.", "sin_banco": true, "ok": "", "x": "Es de <mark>virus atenuado</mark> (Theiler, 1937) y activa a las células dendríticas por varios TLR, <span class=\"cx\">así que</span> genera una memoria muy duradera. <span class=\"cx\">Por eso</span> desde 2014 la OMS dejó de pedir el refuerzo cada 10 años: <span class=\"res\">una dosis, protección de por vida y del 99 %</span>.", "truco": "Amarilla = una vez y para siempre.", "veces": 0}, {"n": 7, "id": "IN22-019", "c": "d", "tema": "Inmunización pasiva", "pregunta": "¿Qué riesgo tiene aplicar por segunda vez un suero hiperinmune de origen animal (antitetánico, antigangrenoso)?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Choque anafiláctico o enfermedad del suero, porque la primera aplicación sensibiliza al individuo contra las proteínas animales del suero.", "sin_banco": true, "ok": "", "x": "El suero de caballo es <mark>proteína extraña</mark>: la primera dosis protege, pero <span class=\"cx\">además</span> <b>sensibiliza</b>. <span class=\"cx\">Así que</span> en la segunda dosis ya hay anticuerpos contra esas proteínas y aparecen anafilaxia (IgE) o enfermedad del suero (complejos inmunes). <span class=\"cx\">Por eso</span> <span class=\"res\">el suero animal se usa una sola vez</span>.", "truco": "Suero animal: la primera cura, la segunda castiga.", "veces": 0}, {"n": 8, "id": "IN22-020", "c": "d", "tema": "Complicaciones de las vacunas", "pregunta": "La incidencia de reacciones anafilácticas por vacunas es aproximadamente de:", "opciones": ["a. Un caso por cada 10 millones de vacunados", "b. Un caso por cada mil vacunados", "c. Un caso por cada 100 000 vacunados", "d. Un caso por cada 3,2 millones de dosis", "e. Un caso por cada millón de dosis"], "letra": "a", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "a. Un caso por cada 10 millones de vacunados", "sin_banco": true, "ok": "", "x": "Es el punto Ⓒ: la anafilaxia es de <mark>1 por 10 millones</mark>; el daño por DTP, 1 por 3,2 millones, y la polio por OPV, 1 por millón. <span class=\"cx\">Por eso</span> <span class=\"res\">la a</span>.", "truco": "", "veces": 0}, {"n": 9, "id": "IN22-021", "c": "d", "tema": "Esquemas de vacunación", "pregunta": "Mujer de 26 años con 20 semanas de embarazo, no inmunizada. ¿Qué vacuna está contraindicada y cuáles protegen además al recién nacido?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Está contraindicada la rubéola (vacuna viva) durante el embarazo y los 3 meses previos a la concepción. Las vacunas contra tétanos e influenza en el embarazo protegen al recién nacido por los anticuerpos maternos (inmunidad pasiva) antes de sus primeras vacunas.", "sin_banco": true, "ok": "", "x": "La <mark>rubéola</mark> es de virus vivo, <span class=\"cx\">por eso</span> no se aplica en el embarazo ni 3 meses antes, aunque es obligatoria para toda mujer en edad reproductiva no inmunizada. <span class=\"cx\">En cambio</span>, el toxoide tetánico y la influenza <b>inactivada</b> son seguros, y la IgG materna cruza la placenta, <span class=\"cx\">así que</span> <span class=\"res\">el recién nacido nace protegido</span>.", "truco": "Embarazo: «Rubéola NO; Tétanos e Influenza SÍ».", "veces": 0}, {"n": 10, "id": "IN22-022", "c": "i", "tema": "Clases de vacunas", "pregunta": "La vacunología reversa, a partir del genoma completo, se ha aplicado con éxito sobre todo en:", "opciones": ["a. La viruela", "b. La rabia", "c. El tétanos", "d. El sarampión", "e. El meningococo"], "letra": "e", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "e. El meningococo: se identificaron hasta 570 proteínas y se evaluaron 350.", "sin_banco": true, "ok": "", "x": "Secuenciar el <mark>genoma bacteriano completo</mark> permite elegir candidatos sin cultivar el germen. En el <b>meningococo</b> así se identificaron hasta 570 proteínas y se evaluaron 350 en ratones. <span class=\"cx\">Por eso</span> <span class=\"res\">vacunología reversa = del genoma a la vacuna</span>.", "truco": "Reversa = empezar por el genoma (meningococo, 570).", "veces": 0}, {"n": 11, "id": "IN22-023", "c": "i", "tema": "Vacunas contra el cáncer", "pregunta": "¿Qué vacunas actuales previenen un cáncer y cuál previenen?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "La del papilomavirus previene el cáncer de cérvix y la de hepatitis B previene el cáncer de hígado (hepatocarcinoma). Inauguran la era de la vacunación contra el cáncer.", "sin_banco": true, "ok": "", "x": "Ambos cánceres los inicia un <mark>virus crónico</mark>; <span class=\"cx\">por eso</span>, si la vacuna evita la infección, evita también el tumor. <span class=\"cx\">Así que</span> <span class=\"res\">VPH → cérvix y hepatitis B → hígado</span>, y ya se investigan vacunas para estómago, colon y próstata.", "truco": "Vacuno el virus, prevengo el tumor.", "veces": 0}, {"n": 12, "id": "IN22-024", "c": "d", "tema": "Inmunización pasiva", "pregunta": "Niño de 5 años no vacunado sufre una herida profunda contaminada con tierra. Además de limpiar la herida, ¿qué tipo de inmunización necesita de inmediato y por qué?", "opciones": [], "letra": "", "ex": [], "nex": "", "porq": null, "clave": "", "aviso": "", "r": "Inmunización pasiva con inmunoglobulina hiperinmune antitetánica, porque no tiene anticuerpos propios y la vacuna activa tardaría en protegerlo; además, se inicia su esquema de vacunación (literatura).", "sin_banco": true, "ok": "", "x": "La vacuna <mark>tarda semanas</mark> en generar anticuerpos, <span class=\"cx\">en cambio</span> el suero hiperinmune los da <b>ya hechos</b>. <span class=\"cx\">Por eso</span> está indicada en heridas contaminadas en no vacunados o con esquema incompleto, igual que tras contacto con sarampión o tosferina. <span class=\"cx\">Así que</span> <span class=\"res\">pasiva para hoy, activa para mañana</span>.", "truco": "Pasiva = anticuerpos prestados; activa = anticuerpos propios.", "veces": 0}], "tabla": {"cab": ["", "Vivo atenuado", "Muerto", "Toxoide", "Conjugada"], "filas": [["Ejemplos", "Sabin, fiebre amarilla, sarampión, rubéola", "Salk, gripe", "Difteria, tétanos", "Haemophilus, neumococo, meningococo"], ["Ventaja", "Protección más larga; OPV se contagia", "Segura", "Neutraliza la toxina", "IgG y memoria desde 2 meses"], ["Límite", "No en inmunodeficiencia celular ni embarazo", "Pide refuerzo", "Refuerzo cada 10 años", "Sin la proteína no sirve antes de 2 años"], ["🔑 Para diferenciar", "Se replica", "No se replica", "Solo la toxina", "Azúcar + proteína"]]}, "fuente": "Fuente: tu teoría — clase 58 (Inmunización), Rojas 17.ª ed."}], "resueltos": [], "conceptos": {}, "siglas": {}};
